class PropertyPronunciationNormalizer:
    """In-memory property-name replacer for TTS text.

    The matcher is case-insensitive, prefers the longest exact property-name
    match, and requires word boundaries so short keys do not corrupt longer
    words. The dictionary is loaded once at process startup; normalize() does
    no file I/O and makes no network calls.
    """

    _END = "__value__"
    _BOUNDARY_EXTRA = frozenset({"'", "-", "_"})

    def __init__(self, dictionary_path: str):
        self._dictionary_path = dictionary_path
        self._trie: dict[str, dict] = {}
        self._entries = 0
        self._load()

    @property
    def entries(self) -> int:
        return self._entries

    def _load(self) -> None:
        path = Path(self._dictionary_path)
        if not path.exists():
            logger.warning(
                f"[TTSPronunciation] Dictionary not found: {path}. "
                "Property pronunciation normalization disabled."
            )
            return

        try:
            raw = json.loads(path.read_text(encoding="utf-8"))
        except Exception as exc:
            logger.warning(
                f"[TTSPronunciation] Failed to load dictionary {path}: {exc}. "
                "Property pronunciation normalization disabled."
            )
            return

        if not isinstance(raw, dict):
            logger.warning(
                f"[TTSPronunciation] Dictionary {path} is not a JSON object. "
                "Property pronunciation normalization disabled."
            )
            return

        for original, phonetic in raw.items():
            key = str(original or "").strip()
            value = str(phonetic or "").strip()
            if not key or not value:
                continue
            node = self._trie
            for ch in key.casefold():
                node = node.setdefault(ch, {})
            node[self._END] = value
            self._entries += 1

        logger.info(
            f"[TTSPronunciation] Loaded {self._entries} property pronunciations "
            f"from {path}"
        )

    def _is_name_char(self, ch: str | None) -> bool:
        return bool(ch) and (ch.isalnum() or ch in self._BOUNDARY_EXTRA)

    def _has_valid_boundaries(self, text: str, start: int, end: int) -> bool:
        before = text[start - 1] if start > 0 else None
        after = text[end] if end < len(text) else None
        return not self._is_name_char(before) and not self._is_name_char(after)

    def normalize(self, text: str) -> str:
        if not text or not self._trie:
            return text

        folded = text.casefold()
        replacements: list[tuple[int, int, str]] = []
        i = 0
        n = len(text)

        while i < n:
            node = self._trie
            j = i
            best: tuple[int, str] | None = None

            while j < n:
                node = node.get(folded[j])
                if node is None:
                    break
                j += 1
                value = node.get(self._END)
                if value and self._has_valid_boundaries(text, i, j):
                    best = (j, value)

            if best:
                end, value = best
                replacements.append((i, end, value))
                i = end
            else:
                i += 1

        if not replacements:
            return text

        out: list[str] = []
        last = 0
        for start, end, value in replacements:
            out.append(text[last:start])
            out.append(value)
            last = end
        out.append(text[last:])
        return "".join(out)


_PROPERTY_PRONUNCIATION_NORMALIZER = PropertyPronunciationNormalizer(
    PROPERTY_PHONETIC_DICTIONARY_PATH
)


def normalize_text_for_tts(text: str) -> str:
    """Replace known property names with phonetic forms before TTS."""
    return _PROPERTY_PRONUNCIATION_NORMALIZER.normalize(text)

