def build_cartesia_generation_config(speed: float | None = None) -> GenerationConfig:
    return GenerationConfig(speed=speed, emotion=CARTESIA_FIXED_EMOTION)


def _make_opening_audio_cache_key(voice_id: str, greeting: str, tts_lang: Any, voice_speed: float) -> tuple[str, str, str, str, str]:
    return (
        str(voice_id or "").strip(),
        re.sub(r"\s+", " ", str(greeting or "").strip()),
        str(tts_lang.value if hasattr(tts_lang, "value") else tts_lang or "").strip(),
        f"{float(voice_speed):.3f}",
        CARTESIA_FIXED_EMOTION,
    )


def _resolve_tts_language(stt_language: Any) -> Any:
    return TTS_LANG_MAP.get(str(stt_language or "").strip(), Language.EN)


async def _build_opening_audio_chunks(voice_id: str, greeting: str, tts_lang: Any, voice_speed: float) -> list[bytes]:
    async with httpx.AsyncClient() as _client:
        _cartesia_resp = await _client.post(
            "https://api.cartesia.ai/tts/bytes",
            headers={
                "X-API-Key": os.getenv("CARTESIA_API_KEY"),
                "Cartesia-Version": "2024-06-10",
                "Content-Type": "application/json",
            },
            json={
                "model_id": "sonic-3",
                "transcript": greeting,
                "voice": {"mode": "id", "id": voice_id},
                "generation_config": {
                    "speed": voice_speed,
                    "emotion": CARTESIA_FIXED_EMOTION,
                },
                "output_format": {
                    "container": "raw",
                    "encoding": "pcm_s16le",
                    "sample_rate": 8000,
                },
                "language": tts_lang.value if hasattr(tts_lang, "value") else str(tts_lang),
            },
            timeout=10.0,
        )
    if _cartesia_resp.status_code != 200:
        raise RuntimeError(f"opening_cache_http_{_cartesia_resp.status_code}")
    _raw_pcm = _cartesia_resp.content
    _chunk_size = VODAFONE_OUTBOUND_CHUNK_MS * 8000 * 2 // 1000
    return [
        _raw_pcm[i:i + _chunk_size]
        for i in range(0, len(_raw_pcm), _chunk_size)
        if len(_raw_pcm[i:i + _chunk_size]) == _chunk_size
    ]


async def _get_or_build_opening_audio_chunks(
    voice_id: str,
    greeting: str,
    tts_lang: Any,
    voice_speed: float,
) -> list[bytes]:
    _cache_key = _make_opening_audio_cache_key(voice_id, greeting, tts_lang, voice_speed)
    _cached = _OPENING_AUDIO_CACHE.get(_cache_key)
    if _cached:
        logger.info(f"[Outbound Pipeline] Opening cache HIT: {len(_cached)} chunks")
        return list(_cached)

    _pending = _OPENING_AUDIO_CACHE_TASKS.get(_cache_key)
    if _pending:
        _chunks = await asyncio.shield(_pending)
        return list(_chunks)

    async def _builder() -> list[bytes]:
        _chunks = await _build_opening_audio_chunks(voice_id, greeting, tts_lang, voice_speed)
        _OPENING_AUDIO_CACHE[_cache_key] = list(_chunks)
        return _chunks

    _task = asyncio.create_task(_builder())
    _OPENING_AUDIO_CACHE_TASKS[_cache_key] = _task
    try:
        _chunks = await asyncio.shield(_task)
        return list(_chunks)
    finally:
        if _OPENING_AUDIO_CACHE_TASKS.get(_cache_key) is _task and _task.done():
            _OPENING_AUDIO_CACHE_TASKS.pop(_cache_key, None)


def _parse_property_date(value: Any) -> "_dt.date | None":
    text = str(value or "").strip()
    if not text:
        return None
    for fmt in ("%Y-%m-%d", "%d-%m-%Y", "%d/%m/%Y", "%Y/%m/%d", "%B %d, %Y", "%b %d, %Y"):
        try:
            return _dt.datetime.strptime(text, fmt).date()
        except Exception:
            continue
    return None


def _normalize_construction_state(value: Any) -> str:
    return re.sub(r"\s+", " ", str(value or "").strip().lower())


def _format_property_possession_message(data: dict, property_name: str | None = None) -> str | None:
    possession = str(data.get("possession") or "").strip()
    construction = _normalize_construction_state(
        data.get("construction")
        or data.get("construction_state")
        or data.get("State_Of_Construction")
    )
    possession_date = _parse_property_date(possession)
    today = _dt.date.today()
    ready_now = (
        "ready to move" in construction
        or "ready-to-move" in construction
        or (possession_date is not None and possession_date <= today)
    )

    if ready_now:
        if property_name:
            return f"Possession for {property_name} is available now; it is ready to move in."
        return "Possession is available now; it is ready to move in."

    if possession:
        if property_name:
            return f"The possession timeline for {property_name} is expected by {possession}."
        return f"Possession is expected by {possession}."

    return None


