def _build_vodafone_media_frame(
    payload_b64: str,
    room_id: str | None = None,
    *,
    include_room_id: bool | None = None,
) -> dict:
    """Build Vodafone media frames in the provider-compatible shape by default."""
    frame = {"event": "media", "media": {"payload": payload_b64}}
    _include_room_id = VODAFONE_MEDIA_INCLUDE_ROOM_ID if include_room_id is None else include_room_id
    if _include_room_id and room_id:
        frame["room_id"] = room_id
    return frame


def _pcm16_peak_abs(pcm: bytes) -> int:
    """Cheap PCM16 peak meter for Vodafone inbound-media diagnostics."""
    if not pcm:
        return 0
    limit = len(pcm) - (len(pcm) % 2)
    peak = 0
    for idx in range(0, limit, 2):
        sample = int.from_bytes(pcm[idx:idx + 2], "little", signed=True)
        if sample < 0:
            sample = -sample
        if sample > peak:
            peak = sample
    return peak


def _pcm16_rms_dbfs(pcm: bytes) -> float:
    """Return RMS level in dBFS for 16-bit little-endian PCM."""
    if not pcm:
        return -120.0
    limit = len(pcm) - (len(pcm) % 2)
    if limit <= 0:
        return -120.0
    total = 0.0
    count = 0
    for idx in range(0, limit, 2):
        sample = int.from_bytes(pcm[idx:idx + 2], "little", signed=True)
        total += float(sample * sample)
        count += 1
    if count <= 0 or total <= 0:
        return -120.0
    rms = math.sqrt(total / count)
    return 20.0 * math.log10(max(rms, 1.0) / 32768.0)


@dataclass
class VodafoneTtsAudioConditioner:
    """Small Vodafone-only PCM16 conditioner for live telephony TTS output."""

    enabled: bool = VODAFONE_TTS_CONDITIONING_ENABLED
    gain: float = VODAFONE_TTS_GAIN
    limit_peak: int = VODAFONE_TTS_LIMIT_PEAK
    highpass_hz: float = VODAFONE_TTS_HIGHPASS_HZ
    sample_rate: int = 8000
    log_chunks: int = VODAFONE_TTS_AUDIO_LOG_CHUNKS
    _hp_prev_x: float = 0.0
    _hp_prev_y: float = 0.0
    _chunks_seen: int = 0

    def reset(self) -> None:
        self._hp_prev_x = 0.0
        self._hp_prev_y = 0.0

    def process(self, pcm: bytes, *, source: str = "tts") -> bytes:
        if not pcm or not self.enabled:
            return pcm
        limit = len(pcm) - (len(pcm) % 2)
        if limit <= 0:
            return pcm

        before_peak = _pcm16_peak_abs(pcm[:limit])
        before_rms = _pcm16_rms_dbfs(pcm[:limit])
        out = bytearray()
        limited = 0
        hp_alpha = 0.0
        use_hp = self.highpass_hz > 0 and self.sample_rate > 0
        if use_hp:
            rc = 1.0 / (2.0 * math.pi * self.highpass_hz)
            dt = 1.0 / float(self.sample_rate)
            hp_alpha = rc / (rc + dt)

        peak_limit = max(1, min(32767, int(self.limit_peak or 32767)))
        gain = max(0.0, float(self.gain or 1.0))
        for idx in range(0, limit, 2):
            raw = int.from_bytes(pcm[idx:idx + 2], "little", signed=True)
            sample = float(raw)
            if use_hp:
                sample = hp_alpha * (self._hp_prev_y + sample - self._hp_prev_x)
                self._hp_prev_x = float(raw)
                self._hp_prev_y = sample
            sample *= gain
            if sample > peak_limit:
                sample = float(peak_limit)
                limited += 1
            elif sample < -peak_limit:
                sample = float(-peak_limit)
                limited += 1
            out.extend(int(round(sample)).to_bytes(2, "little", signed=True))
        if len(pcm) > limit:
            out.extend(pcm[limit:])

        processed = bytes(out)
        self._chunks_seen += 1
        if self._chunks_seen <= max(0, self.log_chunks):
            logger.info(
                f"[VodafoneAudio] conditioning source={source} chunk={self._chunks_seen} "
                f"gain={gain:.2f} highpass_hz={self.highpass_hz:.0f} limit_peak={peak_limit} "
                f"peak_in={before_peak} peak_out={_pcm16_peak_abs(processed[:limit])} "
                f"rms_in_dbfs={before_rms:.1f} rms_out_dbfs={_pcm16_rms_dbfs(processed[:limit]):.1f} "
                f"limited_samples={limited}"
            )
        return processed


def _condition_vodafone_tts_pcm(
    pcm: bytes,
    *,
    source: str = "tts",
    conditioner: VodafoneTtsAudioConditioner | None = None,
) -> bytes:
    active_conditioner = conditioner or VodafoneTtsAudioConditioner()
    return active_conditioner.process(pcm, source=source)


async def _send_vodafone_pcm_realtime(
    websocket,
    room_id: str,
    pcm_chunks: list[bytes],
    *,
    stop_event: asyncio.Event | None = None,
) -> int:
    """Send PCM chunks to Vodafone at real-time telephony pace."""
    _sent = 0
    _next_send_at = time.monotonic()
    _conditioner = VodafoneTtsAudioConditioner()
    for _chunk in pcm_chunks:
        if stop_event and stop_event.is_set():
            break
        _sleep_for = _next_send_at - time.monotonic()
        if _sleep_for > 0:
            await asyncio.sleep(_sleep_for)
        _chunk = _condition_vodafone_tts_pcm(
            _chunk,
            source="prestart_greeting",
            conditioner=_conditioner,
        )
        await websocket.send_text(json.dumps(
            _build_vodafone_media_frame(
                base64.b64encode(_chunk).decode("utf-8"),
                room_id,
            )
        ))
        _sent += 1
        _next_send_at += len(_chunk) / float(8000 * 2)
    return _sent
VODAFONE_MAX_OUTBOUND_QUEUE_CHUNKS = int(os.getenv("VODAFONE_MAX_OUTBOUND_QUEUE_CHUNKS", "1").strip() or "1")
VODAFONE_MAX_PROVIDER_LEAD_MS = int(os.getenv("VODAFONE_MAX_PROVIDER_LEAD_MS", "200").strip() or "200")
OUTBOUND_INTERRUPT_MIN_INTERIM_WORDS = int(os.getenv("OUTBOUND_INTERRUPT_MIN_INTERIM_WORDS", "1").strip() or "1")

SPEAKING_PHASE_NO_BARGE = "ASSISTANT_SPEAKING_NO_BARGE"
SPEAKING_PHASE_BARGEABLE = "ASSISTANT_SPEAKING_BARGEABLE"


@dataclass
class InterruptDecision:
    kind: str
    should_commit: bool = False
    should_pause: bool = False
    should_resume: bool = False
    reason: str = ""


@dataclass
class AssistantPlayoutCursor:
    utterance_id: str = ""
    generation_id: int = 0
    tts_context_id: str = ""
    assistant_item_id: str = ""
    audio_started_at: float | None = None
    played_audio_ms: float = 0.0
    played_audio_bytes: int = 0
    current_sentence_index: int = -1
    current_sentence_offset_chars: int = 0
    telephony_queue_drained_at: float | None = None
    sentence_texts: list[str] | None = None
    sentence_audio_bytes: list[int] | None = None

    def __post_init__(self):
        self.sentence_texts = list(self.sentence_texts or [])
        self.sentence_audio_bytes = list(self.sentence_audio_bytes or [])

    def register_sentence(self, index: int, text: str):
        while len(self.sentence_texts) <= index:
            self.sentence_texts.append("")
        while len(self.sentence_audio_bytes) <= index:
            self.sentence_audio_bytes.append(0)
        self.sentence_texts[index] = text or ""

    def note_sentence_audio(self, index: int, audio_bytes: int):
        while len(self.sentence_audio_bytes) <= index:
            self.sentence_audio_bytes.append(0)
        self.sentence_audio_bytes[index] = max(0, int(audio_bytes))

    def note_played_audio_bytes(self, audio_bytes: int, sample_rate: int = 24000):
        if audio_bytes <= 0:
            return
        self.played_audio_bytes += int(audio_bytes)
        denom = max(1, int(sample_rate) * 2)
        self.played_audio_ms = (self.played_audio_bytes / denom) * 1000.0

    def build_unheard_suffix(self) -> str:
        if not self.sentence_texts:
            return ""
        index = self.current_sentence_index
        if index < 0 or index >= len(self.sentence_texts):
            return " ".join(s.strip() for s in self.sentence_texts if s and s.strip()).strip()

        sentence = self.sentence_texts[index] or ""
        sentence_bytes = self.sentence_audio_bytes[index] if index < len(self.sentence_audio_bytes) else 0
        offset = 0
        if sentence and sentence_bytes > 0:
            played_before_current = sum(self.sentence_audio_bytes[:index])
            played_inside_current = max(0, min(sentence_bytes, self.played_audio_bytes - played_before_current))
            ratio = min(1.0, max(0.0, played_inside_current / sentence_bytes))
            offset = min(len(sentence), int(len(sentence) * ratio))
        self.current_sentence_offset_chars = offset
        suffix_parts: list[str] = []
        current_suffix = sentence[offset:].strip()
        if current_suffix:
            suffix_parts.append(current_suffix)
        suffix_parts.extend(s.strip() for s in self.sentence_texts[index + 1:] if s and s.strip())
        return " ".join(suffix_parts).strip()


@dataclass
class InterruptEvalRecord:
    timestamp: float
    candidate_detected: bool = False
    candidate_class: str = ""
    committed: bool = False
    commit_latency_ms: int | None = None
    false_interrupt_suspected: bool = False
    resume_success: bool = False
    truncation_applied: bool = False
    synthetic_prompt_triggered: bool = False
    reason: str = ""
    text: str = ""


@dataclass
class TurnOrchestrationLedger:
    generation_id: int
    utterance_id: str
    tts_context_id: str = ""
    assistant_item_id: str = ""
    audio_started_at: float | None = None
    played_audio_ms: float = 0.0
    current_sentence_index: int = -1
    resume_seed: str = ""
    interrupt_candidate_count: int = 0
    interrupt_committed: bool = False
    synthetic_output: bool = False
    truncation_applied: bool = False
    candidate_first_seen_at: float | None = None
    candidate_classes: list[str] | None = None
    playout_cursor: AssistantPlayoutCursor | None = None
    eval_records: list[InterruptEvalRecord] | None = None

    def __post_init__(self):
        self.candidate_classes = list(self.candidate_classes or [])
        self.playout_cursor = self.playout_cursor or AssistantPlayoutCursor(
            utterance_id=self.utterance_id,
            generation_id=self.generation_id,
        )
        self.eval_records = list(self.eval_records or [])


class TurnTakingAdapter:
    def on_speech_start(self, text: str, meta: dict | None = None):
        pass

    def on_partial_update(self, text: str, meta: dict | None = None):
        pass

    def on_eager_eot(self, meta: dict | None = None):
        pass

    def on_turn_resumed(self, text: str, meta: dict | None = None):
        pass

    def on_end_of_turn(self, text: str, meta: dict | None = None):
        pass

    def on_stream_close(self):
        pass


class DeepgramFluxShadowAdapter(TurnTakingAdapter):
    """Shadow-only adapter for model-level turn-taking comparisons."""

    def __init__(self, sink):
        self._sink = sink

    def _record(self, event: str, text: str = "", meta: dict | None = None):
        if not FLUX_SHADOW_ENABLED:
            return
        payload = {"event": event, "text": text}
        if meta:
            payload.update(meta)
        self._sink(payload)

    def on_speech_start(self, text: str, meta: dict | None = None):
        self._record("StartOfTurn", text, meta)

    def on_partial_update(self, text: str, meta: dict | None = None):
        self._record("PartialUpdate", text, meta)

    def on_eager_eot(self, meta: dict | None = None):
        if EAGER_EOT_SHADOW_ENABLED:
            self._record("EagerEndOfTurn", "", meta)

    def on_turn_resumed(self, text: str, meta: dict | None = None):
        self._record("TurnResumed", text, meta)

    def on_end_of_turn(self, text: str, meta: dict | None = None):
        self._record("EndOfTurn", text, meta)

    def on_stream_close(self):
        self._record("StreamClosed")


def _map_azure_locale(stt_language: str) -> str:
    return AZURE_LANG_MAP.get(str(stt_language or "").strip(), "en-IN")


def _normalize_azure_auto_detect_languages(raw_value) -> list[str]:
    if isinstance(raw_value, (list, tuple, set)):
        raw_items = [str(item).strip() for item in raw_value]
    else:
        raw_items = [part.strip() for part in re.split(r"[,|]", str(raw_value or ""))]
    normalized: list[str] = []
    for item in raw_items:
        if not item:
            continue
        locale = _map_azure_locale(item)
        if locale == "unknown":
            continue
        if locale not in normalized:
            normalized.append(locale)
    return normalized or list(AZURE_DEFAULT_AUTO_DETECT_LANGUAGES)


def build_azure_stt_profile(config: dict, stt_language: str, sample_rate: int) -> dict[str, Any]:
    provider_profile_enabled = bool(config.get("azureProviderProfileEnabled", True))
    default_locale = _map_azure_locale(stt_language)
    language_strategy = "auto" if stt_language == "multi" and provider_profile_enabled else "explicit"
    auto_detect_candidates = _normalize_azure_auto_detect_languages(
        config.get("azureAutoDetectLanguages") or AZURE_DEFAULT_AUTO_DETECT_LANGUAGES
    ) if language_strategy == "auto" else []
    return {
        "sttProvider": "azure",
        "model": str(config.get("azureModel") or "azure-speech").strip(),
        "locale": default_locale if language_strategy == "explicit" else "unknown",
        "language_strategy": language_strategy,
        "auto_detect_candidates": auto_detect_candidates,
        "phrase_bias_enabled": bool(config.get("azurePhraseBiasEnabled", True)),
        "endpoint_id": str(config.get("azureEndpointId") or "").strip(),
        "provider_profile_enabled": provider_profile_enabled,
        "supports_interim_semantics": True,
        "supports_native_vad_signals": False,
        "native_turn_events_are_destructive": False,
        "supports_auto_detect": True,
        "supports_phrase_biasing": True,
        "supports_custom_endpoint": True,
        "segmentation_silence_ms": (
            int(config.get("azureSegmentationSilenceMs"))
            if str(config.get("azureSegmentationSilenceMs") or "").strip().isdigit()
            else 500
        ),
        "initial_silence_ms": (
            int(config.get("azureInitialSilenceMs"))
            if str(config.get("azureInitialSilenceMs") or "").strip().isdigit()
            else None
        ),
        "profanity_option": str(config.get("azureProfanityOption") or "").strip() or None,
        "sample_rate": int(sample_rate),
    }


def _map_sarvam_language_code(stt_language: str) -> str:
    return SARVAM_LANG_MAP.get(str(stt_language or "").strip(), "unknown")


def _map_sarvam_pipecat_language(stt_language: str):
    return SARVAM_PIPECAT_LANG_MAP.get(_map_sarvam_language_code(stt_language))


def _normalize_sarvam_input_audio_codec(raw_codec: str | None) -> tuple[str, bool]:
    codec = str(raw_codec or "").strip().lower()
    if codec in {"", "wav", "audio/wav"}:
        return "wav", False
    if codec in {"pcm_s16le", "audio/pcm_s16le", "linear16", "audio/linear16", "raw"}:
        return "wav", True
    return "wav", True


def build_sarvam_stt_profile(config: dict, stt_language: str, sample_rate: int) -> dict[str, Any]:
    provider_profile_enabled = bool(config.get("sarvamProviderProfileEnabled", True))
    language_code = _map_sarvam_language_code(stt_language)
    language_strategy = "auto" if language_code == "unknown" else "explicit"
    default_mode = "codemix" if stt_language == "multi" else "transcribe"
    input_audio_codec, codec_compat_fallback = _normalize_sarvam_input_audio_codec(
        config.get("sarvamInputAudioCodec") or "wav"
    )
    profile = {
        "sttProvider": "sarvam",
        "model": str(config.get("sarvamModel") or ("saaras:v3" if provider_profile_enabled else "saarika:v2.5")).strip(),
        "mode": str(config.get("sarvamMode") or default_mode).strip(),
        "input_audio_codec": input_audio_codec,
        "language_code": language_code,
        "language_strategy": str(config.get("sarvamLanguageStrategy") or language_strategy).strip(),
        "native_vad_shadow_enabled": bool(config.get("sarvamNativeVadShadowEnabled", False)),
        "high_vad_sensitivity": bool(config.get("sarvamHighVadSensitivity", False)),
        "codec_compat_fallback": codec_compat_fallback,
        "provider_profile_enabled": provider_profile_enabled,
        "supports_interim_semantics": False,
        "supports_native_vad_signals": "optional",
        "native_turn_events_are_destructive": True,
        "sample_rate": int(sample_rate),
    }
    if profile["language_strategy"] == "auto":
        profile["language_code"] = "unknown"
    if profile["model"] != "saaras:v3":
        profile["mode"] = "transcribe"
    return profile


class ConversationStateManager:
    """Centralized state manager for conversation flow and interruption handling."""
    
    def __init__(self):
        self.state = AgentState.IDLE
        self.last_topic = None
        self.latest_assistant_text = None
        self.last_tool_result = None
        self.turn_id = 0
        self._interrupted_text = None  # Store what was being said when interrupted
        self._pending_resume = False
        self._current_assistant_is_synthetic = False
        self._current_assistant_text = None
        self._synthetic_messages: list[str] = []
        self._assistant_output_generation = 0
        self._idle_followup_suppressed_until = 0.0
        self._idle_followup_suppression_reason = ""
        self._idle_followup_last_log_key = ""
        self._idle_followup_last_log_at = 0.0
        self._current_turn_ledger: TurnOrchestrationLedger | None = None
        self._completed_turn_ledgers: list[TurnOrchestrationLedger] = []
        self._speaker_separation_signals: list[dict[str, Any]] = []
        self._shadow_turn_taking_comparison: list[dict[str, Any]] = []
        self._stt_observability: dict[str, Any] = {}
    
    def set_state(self, new_state: AgentState):
        """Transition to a new state with logging."""
        old_state = self.state
        self.state = new_state
        if old_state != new_state:
            logger.info(f"[STATE] {old_state.value} â†’ {new_state.value}")
    
    def is_active(self) -> bool:
        """Check if conversation is in an active state (not idle)."""
        return self.state in {
            AgentState.LISTENING,
            AgentState.THINKING,
            AgentState.SPEAKING,
            AgentState.INTERRUPTED,
            AgentState.RESUMING
        }
    
    def is_speaking(self) -> bool:
        """Check if agent is currently speaking."""
        return self.state == AgentState.SPEAKING
    
    def can_interrupt(self) -> bool:
        """Check if current state allows interruption."""
        return self.state in {AgentState.SPEAKING, AgentState.THINKING}
    
    def record_interruption(self, text_being_spoken: str = None):
        """Record that an interruption occurred."""
        if text_being_spoken:
            self._interrupted_text = text_being_spoken
        self._pending_resume = True
        self.set_state(AgentState.INTERRUPTED)

    def set_latest_assistant_text(self, text: str | None):
        self.latest_assistant_text = (text or "").strip() or None

    def begin_assistant_output(self, *, synthetic: bool = False, text: str | None = None):
        self._current_assistant_is_synthetic = bool(synthetic)
        self._current_assistant_text = (text or "").strip() or None
        self.suppress_idle_followup(8.0, "assistant_output_started")

    def begin_output_generation(self) -> int:
        self._assistant_output_generation += 1
        return self._assistant_output_generation

    def current_output_generation(self) -> int:
        return self._assistant_output_generation

    def finish_assistant_output(self, generation_id: int | None = None):
        if generation_id is not None and generation_id != self._assistant_output_generation:
            return
        self._current_assistant_is_synthetic = False
        self._current_assistant_text = None
        self.suppress_idle_followup(8.0, "assistant_output_finished")
        self.finish_assistant_turn_ledger(generation_id)

    def current_assistant_is_synthetic(self) -> bool:
        return self._current_assistant_is_synthetic

    def current_assistant_text(self) -> str | None:
        return self._current_assistant_text

    def suppress_idle_followup(self, seconds: float, reason: str = ""):
        until = time.time() + max(0.0, float(seconds or 0.0))
        if until > self._idle_followup_suppressed_until:
            self._idle_followup_suppressed_until = until
            self._idle_followup_suppression_reason = reason or "assistant_output"

    def idle_followup_block_reason(self) -> str | None:
        if self._idle_followup_suppressed_until <= 0:
            return None
        remaining = self._idle_followup_suppressed_until - time.time()
        if remaining > 0:
            return f"{self._idle_followup_suppression_reason or 'cooldown'}:{remaining:.1f}s"
        self._idle_followup_suppressed_until = 0.0
        self._idle_followup_suppression_reason = ""
        return None

    def should_log_idle_followup_block(self, reason: str, interval_s: float = 2.0) -> bool:
        key = (reason or "").split(":", 1)[0]
        now = time.time()
        if key != self._idle_followup_last_log_key or (now - self._idle_followup_last_log_at) >= interval_s:
            self._idle_followup_last_log_key = key
            self._idle_followup_last_log_at = now
            return True
        return False

    def remember_synthetic_message(self, text: str | None):
        cleaned = (text or "").strip()
        if cleaned:
            self._synthetic_messages.append(cleaned)
            self._synthetic_messages = self._synthetic_messages[-32:]

    def begin_turn_ledger(self, generation_id: int, *, synthetic: bool = False, utterance_id: str | None = None):
        utterance_id = utterance_id or f"utt-{generation_id}-{uuid.uuid4().hex[:8]}"
        self._current_turn_ledger = TurnOrchestrationLedger(
            generation_id=generation_id,
            utterance_id=utterance_id,
            synthetic_output=bool(synthetic),
        )
        return self._current_turn_ledger

    def current_turn_ledger(self) -> TurnOrchestrationLedger | None:
        return self._current_turn_ledger

    def note_tts_context_id(self, context_id: str | None):
        ledger = self._current_turn_ledger
        if not ledger or not context_id:
            return
        ledger.tts_context_id = context_id
        ledger.playout_cursor.tts_context_id = context_id

    def note_sentence_registered(self, index: int, sentence: str):
        ledger = self._current_turn_ledger
        if not ledger:
            return
        ledger.playout_cursor.register_sentence(index, sentence)

    def note_sentence_started(self, index: int, sentence: str):
        ledger = self._current_turn_ledger
        if not ledger:
            return
        ledger.current_sentence_index = index
        ledger.playout_cursor.current_sentence_index = index
        ledger.playout_cursor.register_sentence(index, sentence)

    def note_sentence_audio(self, index: int, sentence: str, audio_bytes: int):
        ledger = self._current_turn_ledger
        if not ledger:
            return
        ledger.playout_cursor.register_sentence(index, sentence)
        ledger.playout_cursor.note_sentence_audio(index, audio_bytes)

    def note_audio_started(self):
        ledger = self._current_turn_ledger
        if not ledger:
            return
        now = time.time()
        ledger.audio_started_at = now
        ledger.playout_cursor.audio_started_at = now

    def note_audio_progress(self, audio_bytes: int, sample_rate: int = 24000):
        ledger = self._current_turn_ledger
        if not ledger:
            return
        ledger.playout_cursor.note_played_audio_bytes(audio_bytes, sample_rate=sample_rate)
        ledger.played_audio_ms = ledger.playout_cursor.played_audio_ms

    def note_interrupt_candidate(self, kind: str, text: str = "", reason: str = ""):
        ledger = self._current_turn_ledger
        if not ledger:
            return
        now = time.time()
        ledger.interrupt_candidate_count += 1
        ledger.candidate_classes.append(kind)
        if ledger.candidate_first_seen_at is None:
            ledger.candidate_first_seen_at = now
        if CONTINUOUS_INTERRUPT_EVAL_ENABLED:
            ledger.eval_records.append(
                InterruptEvalRecord(
                    timestamp=now,
                    candidate_detected=True,
                    candidate_class=kind,
                    reason=reason,
                    text=text,
                )
            )

    def note_interrupt_commit(self, kind: str, text: str = "", reason: str = ""):
        ledger = self._current_turn_ledger
        if not ledger:
            return
        ledger.interrupt_committed = True
        commit_latency_ms = None
        if ledger.candidate_first_seen_at:
            commit_latency_ms = int((time.time() - ledger.candidate_first_seen_at) * 1000)
        if CONTINUOUS_INTERRUPT_EVAL_ENABLED:
            ledger.eval_records.append(
                InterruptEvalRecord(
                    timestamp=time.time(),
                    candidate_detected=True,
                    candidate_class=kind,
                    committed=True,
                    commit_latency_ms=commit_latency_ms,
                    reason=reason,
                    text=text,
                )
            )

    def note_resume_seed(self, text: str | None):
        ledger = self._current_turn_ledger
        cleaned = (text or "").strip()
        if not ledger or not cleaned:
            return
        ledger.resume_seed = cleaned

    def note_truncation_applied(self, resume_seed: str | None):
        ledger = self._current_turn_ledger
        if not ledger:
            return
        ledger.truncation_applied = bool((resume_seed or "").strip())
        ledger.resume_seed = (resume_seed or "").strip()
        if CONTINUOUS_INTERRUPT_EVAL_ENABLED and ledger.truncation_applied:
            ledger.eval_records.append(
                InterruptEvalRecord(
                    timestamp=time.time(),
                    truncation_applied=True,
                    reason="playback_truncation",
                    text=ledger.resume_seed,
                )
            )

    def note_resume_result(self, success: bool, reason: str = ""):
        ledger = self._current_turn_ledger
        if not ledger or not CONTINUOUS_INTERRUPT_EVAL_ENABLED:
            return
        ledger.eval_records.append(
            InterruptEvalRecord(
                timestamp=time.time(),
                resume_success=bool(success),
                reason=reason,
            )
        )

    def note_synthetic_prompt_triggered(self, text: str | None):
        ledger = self._current_turn_ledger
        if not ledger or not CONTINUOUS_INTERRUPT_EVAL_ENABLED:
            return
        ledger.eval_records.append(
            InterruptEvalRecord(
                timestamp=time.time(),
                synthetic_prompt_triggered=True,
                text=(text or "").strip(),
            )
        )

    def record_speaker_separation_signal(self, signal: dict[str, Any]):
        if not signal:
            return
        signal = dict(signal)
        signal["ts"] = signal.get("ts") or time.time()
        self._speaker_separation_signals.append(signal)
        self._speaker_separation_signals = self._speaker_separation_signals[-256:]

    def record_shadow_turn_taking_event(self, event: dict[str, Any]):
        if not event:
            return
        event = dict(event)
        event["ts"] = event.get("ts") or time.time()
        self._shadow_turn_taking_comparison.append(event)
        self._shadow_turn_taking_comparison = self._shadow_turn_taking_comparison[-256:]

    def set_stt_observability(self, payload: dict[str, Any]):
        self._stt_observability = dict(payload or {})

    def update_stt_observability(self, payload: dict[str, Any]):
        if not payload:
            return
        self._stt_observability.update(payload)

    def increment_stt_observability(self, key: str, amount: int = 1):
        if not key:
            return
        current = int(self._stt_observability.get(key, 0) or 0)
        self._stt_observability[key] = current + int(amount)

    def append_stt_observability_timing(self, key: str, value_ms: int):
        if not key:
            return
        timings = list(self._stt_observability.get(key) or [])
        timings.append(int(value_ms))
        self._stt_observability[key] = timings[-128:]

    def finish_assistant_turn_ledger(self, generation_id: int | None = None):
        ledger = self._current_turn_ledger
        if not ledger:
            return
        if generation_id is not None and generation_id != ledger.generation_id:
            return
        self._completed_turn_ledgers.append(ledger)
        self._completed_turn_ledgers = self._completed_turn_ledgers[-128:]
        self._current_turn_ledger = None

    def build_interrupt_metrics_payload(self) -> dict[str, Any]:
        ledgers = self._completed_turn_ledgers[:]
        if self._current_turn_ledger:
            ledgers.append(self._current_turn_ledger)
        eval_records = [rec for ledger in ledgers for rec in (ledger.eval_records or [])]
        commit_latencies = [rec.commit_latency_ms for rec in eval_records if rec.commit_latency_ms is not None]
        candidate_classes: dict[str, int] = {}
        for ledger in ledgers:
            for klass in ledger.candidate_classes or []:
                candidate_classes[klass] = candidate_classes.get(klass, 0) + 1
        payload = {
            "turnCount": len(ledgers),
            "candidateCount": sum(l.interrupt_candidate_count for l in ledgers),
            "candidateClasses": candidate_classes,
            "committedInterrupts": sum(1 for l in ledgers if l.interrupt_committed),
            "resumeSeeds": sum(1 for l in ledgers if l.resume_seed),
            "truncationApplied": sum(1 for l in ledgers if l.truncation_applied),
            "syntheticPromptCount": sum(1 for rec in eval_records if rec.synthetic_prompt_triggered),
            "falseInterruptSuspected": sum(1 for rec in eval_records if rec.false_interrupt_suspected),
            "commitLatencyMs": {
                "p50": int(statistics.median(commit_latencies)) if commit_latencies else 0,
                "p95": int(sorted(commit_latencies)[min(len(commit_latencies) - 1, int(len(commit_latencies) * 0.95))]) if commit_latencies else 0,
            },
            "speakerSeparationSignals": self._speaker_separation_signals[-64:],
            "shadowTurnTakingComparison": self._shadow_turn_taking_comparison[-64:],
        }
        if self._stt_observability:
            payload["stt"] = dict(self._stt_observability)
            if isinstance(self._stt_observability.get("speechStartToFinalMs"), list):
                timings = [int(v) for v in self._stt_observability.get("speechStartToFinalMs", []) if v is not None]
                payload["stt"]["speechStartToFinalMs"] = {
                    "count": len(timings),
                    "p50": int(statistics.median(timings)) if timings else 0,
                    "p95": int(sorted(timings)[min(len(timings) - 1, int(len(timings) * 0.95))]) if timings else 0,
                }
        return payload

    def reset_call_metrics(self):
        self._completed_turn_ledgers = []
        self._current_turn_ledger = None
        self._speaker_separation_signals = []
        self._shadow_turn_taking_comparison = []
        self._stt_observability = {}

    def synthetic_messages(self) -> list[str]:
        return list(self._synthetic_messages)

    def clear_synthetic_messages(self):
        self._synthetic_messages = []

    def prime_resume_seed(self, text: str | None):
        seeded = (text or "").strip()
        if seeded:
            self._interrupted_text = seeded
            self._pending_resume = True
    
    def clear_resume(self):
        """Clear pending resume state."""
        self._pending_resume = False
        self._interrupted_text = None

    def get_interrupted_text(self) -> str | None:
        """Return the speech fragment that was interrupted most recently."""
        return self._interrupted_text

    def pending_resume(self) -> bool:
        return self._pending_resume

    def build_unheard_resume_seed(self, fallback: str = "") -> str:
        ledger = self._current_turn_ledger
        if PLAYBACK_TRUNCATION_V1_ENABLED and ledger and ledger.playout_cursor:
            suffix = ledger.playout_cursor.build_unheard_suffix()
            if suffix:
                self.note_truncation_applied(suffix)
                return suffix
        cleaned = (fallback or "").strip()
        self.note_truncation_applied(cleaned)
        return cleaned
    
    def increment_turn(self):
        """Increment conversation turn counter."""
        self.turn_id += 1
        logger.info(f"[TURN] id={self.turn_id}")


# Global state manager instance - one per process
global_state_manager = ConversationStateManager()


if SARVAM_AVAILABLE:
    class SprioSarvamSTTService(SarvamSTTService):
        """Sarvam wrapper that keeps native VAD shadow-only when enabled."""

        def __init__(self, *args, shadow_vad_sink=None, native_vad_shadow_enabled: bool = False, **kwargs):
            super().__init__(*args, **kwargs)
            self._shadow_vad_sink = shadow_vad_sink
            self._native_vad_shadow_enabled = bool(native_vad_shadow_enabled)

        async def _handle_message(self, message):
            try:
                if (
                    self._native_vad_shadow_enabled
                    and getattr(message, "type", None) == "events"
                    and self._shadow_vad_sink
                ):
                    signal = getattr(getattr(message, "data", None), "signal_type", "")
                    occured_at = getattr(getattr(message, "data", None), "occured_at", None)
                    self._shadow_vad_sink(
                        {
                            "provider": "sarvam",
                            "event": signal,
                            "occured_at": occured_at,
                            "shadow": True,
                        }
                    )
                    global_state_manager.increment_stt_observability("nativeVadShadowEventCount", 1)
                    if signal == "START_SPEECH":
                        await self._start_metrics()
                    elif signal == "END_SPEECH":
                        await self.stop_processing_metrics()
                    return
            except Exception as e:
                logger.debug(f"[SarvamShadowVAD] message handling fallback: {e}")
            await super()._handle_message(message)
else:
    SprioSarvamSTTService = None


if AZURE_AVAILABLE and azure_speechsdk:
    class SprioAzureSTTService(AzureSTTService):
        """Azure STT wrapper with auto-detect, phrase biasing, and tuning hooks."""

        def __init__(
            self,
            *args,
            auto_detect_languages: list[str] | None = None,
            phrase_bias_phrases: list[str] | None = None,
            segmentation_silence_ms: int | None = None,
            initial_silence_ms: int | None = None,
            profanity_option: str | None = None,
            **kwargs,
        ):
            self._auto_detect_languages = [str(item).strip() for item in (auto_detect_languages or []) if str(item).strip()]
            self._auto_detect_enabled = len(self._auto_detect_languages) > 1
            self._phrase_bias_phrases = [str(item).strip() for item in (phrase_bias_phrases or []) if str(item).strip()]
            self._segmentation_silence_ms = int(segmentation_silence_ms) if segmentation_silence_ms else None
            self._initial_silence_ms = int(initial_silence_ms) if initial_silence_ms else None
            self._profanity_option = str(profanity_option or "").strip() or None
            self._shutdown_requested = False
            self._restart_lock = asyncio.Lock()
            self._restart_future = None
            super().__init__(*args, **kwargs)
            def _set_setting(name: str, value):
                if self._settings is None:
                    return
                if isinstance(self._settings, dict):
                    self._settings[name] = value
                    return
                setattr(self._settings, name, value)
            if self._auto_detect_enabled:
                _set_setting("auto_detect_languages", list(self._auto_detect_languages))
                _set_setting("language", "unknown")
            _set_setting("phrase_bias_enabled", bool(self._phrase_bias_phrases))

        async def _start_recognizer(self):
            if self._profanity_option:
                profanity_value = getattr(getattr(azure_speechsdk, "ProfanityOption", None), str(self._profanity_option), None)
                if profanity_value is not None:
                    self._speech_config.set_profanity(profanity_value)
            property_id = getattr(azure_speechsdk, "PropertyId", None)
            if property_id is not None:
                if self._segmentation_silence_ms is not None:
                    prop = getattr(property_id, "Speech_SegmentationSilenceTimeoutMs", None)
                    if prop is not None:
                        self._speech_config.set_property(prop, str(self._segmentation_silence_ms))
                if self._initial_silence_ms is not None:
                    prop = getattr(property_id, "SpeechServiceConnection_InitialSilenceTimeoutMs", None)
                    if prop is not None:
                        self._speech_config.set_property(prop, str(self._initial_silence_ms))

            stream_format = AzureAudioStreamFormat(samples_per_second=self.sample_rate, channels=1)
            self._audio_stream = AzurePushAudioInputStream(stream_format)
            audio_config = AzureAudioConfig(stream=self._audio_stream)

            recognizer = None
            if self._auto_detect_enabled:
                auto_detect_cls = getattr(azure_speechsdk, "AutoDetectSourceLanguageConfig", None)
                source_recognizer_cls = getattr(azure_speechsdk, "SourceLanguageRecognizer", None)
                if auto_detect_cls and source_recognizer_cls:
                    auto_detect_cfg = auto_detect_cls(languages=self._auto_detect_languages)
                    try:
                        recognizer = source_recognizer_cls(
                            speech_config=self._speech_config,
                            audio_config=audio_config,
                            auto_detect_source_language_config=auto_detect_cfg,
                        )
                    except TypeError:
                        recognizer = None
            if recognizer is None:
                recognizer = azure_speechsdk.SpeechRecognizer(
                    speech_config=self._speech_config,
                    audio_config=audio_config,
                )

            self._speech_recognizer = recognizer
            phrase_list_cls = getattr(azure_speechsdk, "PhraseListGrammar", None)
            if phrase_list_cls and self._phrase_bias_phrases:
                try:
                    phrase_list = phrase_list_cls.from_recognizer(self._speech_recognizer)
                    for phrase in self._phrase_bias_phrases:
                        phrase_list.addPhrase(phrase)
                except Exception as exc:
                    logger.debug(f"[AzurePhraseBias] failed to attach phrase list: {exc}")

            self._speech_recognizer.recognizing.connect(self._on_handle_recognizing)
            self._speech_recognizer.recognized.connect(self._on_handle_recognized)
            self._speech_recognizer.canceled.connect(self._on_handle_canceled)
            _session_stopped = getattr(self._speech_recognizer, "session_stopped", None)
            if _session_stopped is not None:
                _session_stopped.connect(self._on_handle_session_stopped)
            self._speech_recognizer.start_continuous_recognition_async()
            logger.info(
                f"[Azure STT] continuous recognition started "
                f"(sample_rate={self.sample_rate}, auto_detect={self._auto_detect_enabled})"
            )

        async def _restart_recognizer(self, reason: str):
            async with self._restart_lock:
                if self._shutdown_requested:
                    return
                logger.warning(f"[Azure STT] restarting recognizer after {reason}")
                try:
                    if self._speech_recognizer:
                        self._speech_recognizer.stop_continuous_recognition_async()
                except Exception as exc:
                    logger.debug(f"[Azure STT] stop before restart failed: {exc}")
                try:
                    if self._audio_stream:
                        self._audio_stream.close()
                except Exception as exc:
                    logger.debug(f"[Azure STT] audio stream close before restart failed: {exc}")
                self._speech_recognizer = None
                self._audio_stream = None
                await asyncio.sleep(0.1)
                await self._start_recognizer()

        def _schedule_restart(self, reason: str):
            if self._shutdown_requested:
                return
            if self._restart_future and not self._restart_future.done():
                return
            try:
                self._restart_future = asyncio.run_coroutine_threadsafe(
                    self._restart_recognizer(reason),
                    self.get_event_loop(),
                )
            except Exception as exc:
                logger.warning(f"[Azure STT] failed to schedule recognizer restart ({reason}): {exc}")

        async def start(self, frame: StartFrame):
            self._shutdown_requested = False
            await super(AzureSTTService, self).start(frame)

            if self._audio_stream:
                return

            try:
                await self._start_recognizer()
            except Exception as e:
                await self.push_error(
                    error_msg=f"Uncaught exception during Azure STT initialization: {e}",
                    exception=e,
                )

        async def stop(self, frame):
            self._shutdown_requested = True
            await super().stop(frame)

        async def cancel(self, frame):
            self._shutdown_requested = True
            await super().cancel(frame)

        def _on_handle_canceled(self, event):
            super()._on_handle_canceled(event)
            if self._shutdown_requested:
                return
            details = getattr(event.result, "cancellation_details", None)
            reason = getattr(details, "reason", None)
            error_details = getattr(details, "error_details", None)
            logger.warning(
                f"[Azure STT] recognition canceled unexpectedly "
                f"(reason={reason}, details={error_details or '-'})"
            )
            self._schedule_restart("canceled")

        def _on_handle_session_stopped(self, event):
            if self._shutdown_requested:
                return
            logger.warning("[Azure STT] session stopped unexpectedly; restarting continuous recognition")
            self._schedule_restart("session_stopped")
else:
    SprioAzureSTTService = None


def is_soft_interrupt(text: str) -> bool:
    """Classify if user input is a soft interruption (hello/hi/etc).
    Only matches when the text is JUST a greeting - not a greeting followed by
    a substantive request like 'Yeah, I want details on Ruby Dakshin.'
    Substring matching uses word boundaries to prevent property names like
    'Dakshin' (contains 'hi') from triggering false positives."""
    t = text.lower().strip()
    # Remove punctuation for matching
    t = re.sub(r'[^\w\s]', '', t)
    soft_patterns = [
        "hello", "hello there", "hi", "hey",
        "are you there", "you there", "still there",
        "can you hear me", "are you listening"
    ]
    # Exact match (entire input is just the greeting)
    if t in soft_patterns:
        return True
    # Word count guard: substantive requests have many words; greetings are 1-3 words
    word_count = len(t.split())
    if word_count > 4:
        return False
    # Word-boundary match for short inputs only (e.g. 'hi there friend')
    for p in soft_patterns[:4]:
        if re.search(r'\b' + re.escape(p) + r'\b', t):
            return True
    return False


def is_resume_confirmation(text: str) -> bool:
    cleaned = re.sub(r"[^\w\s]", " ", (text or "").lower()).strip()
    cleaned = re.sub(r"\s+", " ", cleaned)
    if cleaned in {
        "yes continue",
        "yes continue please",
        "continue",
        "continue please",
        "go ahead",
        "go on",
        "carry on",
        "please continue",
        "yes go ahead",
        "yes go on",
        "yes proceed",
        "proceed",
    }:
        return True
    cleaned = re.sub(
        r"^(?:no|no no|nah|actually|sorry|yes|yeah|yep|ok|okay|sure|please|you|no you|"
        r"yeah you|yes you|ok you|okay you)\s+",
        "",
        cleaned,
    ).strip()
    cleaned = re.sub(r"\b(?:you\s+can|can\s+you|could\s+you|please)\b", " ", cleaned)
    cleaned = re.sub(r"\s+", " ", cleaned).strip()
    return bool(
        re.fullmatch(
            r"(?:"
            r"continue(?:\s+(?:please|with\s+(?:that|the\s+list|the\s+properties|the\s+options)|"
            r"from\s+(?:there|where\s+you\s+stopped|where\s+you\s+left\s+off)))?|"
            r"go\s+(?:ahead|on)|"
            r"carry\s+on|"
            r"proceed|"
            r"resume"
            r")",
            cleaned,
        )
    )


def interrupted_prompt_expects_slot_answer(prompt_text: str, last_topic: str | None = None) -> bool:
    prompt = " ".join(
        part for part in [(prompt_text or "").lower().strip(), (last_topic or "").lower().strip()] if part
    )
    if not prompt:
        return False
    slot_markers = (
        "which area",
        "what area",
        "location",
        "which location",
        "what location",
        "budget",
        "price range",
        "bhk",
        "bedroom",
        "property type",
        "kind of property",
        "looking for property",
        "which property",
        "what property",
        "name or the number",
        "tell me the area",
        "valid area",
        "specify a valid area",
        "specify the area",
        "catch the area",
        "repeat the area",
    )
    return any(marker in prompt for marker in slot_markers)


def interrupted_prompt_expects_confirmation(prompt_text: str, last_topic: str | None = None) -> bool:
    prompt = " ".join(
        part for part in [(prompt_text or "").lower().strip(), (last_topic or "").lower().strip()] if part
    )
    if not prompt:
        return False
    confirmation_markers = (
        "are you asking about",
        "is that correct",
        "is this correct",
        "did i get that right",
        "please say yes or no",
        "say yes or no",
        "would you like more details",
        "would you like me to arrange a callback",
        "would you like a callback",
        "would you like to schedule a site visit",
        "which property would you like to know more about",
    )
    return any(marker in prompt for marker in confirmation_markers)


_CONTEXTUAL_INTERRUPT_RE = re.compile(
    r"\b("
    r"tell me|show me|find|search|look for|suggest|schedule|book|callback|visit|"
    r"price|budget|area|location|bhk|bedroom|property|project|details|apartment|apartments|"
    r"villa|villas|plot|plots|land|independent house|house|home|builder floor|penthouse|senior living|row house|villament|"
    r"villaments|duplex apartment|utsav plots|"
    r"first|second|third|fourth|fifth|"
    r"what|which|where|when|how|why|"
    r"anything else|something else|something more|another one|other one|different one|"
    r"more options|more properties|next property|next three|other areas|other locations"
    r")\b",
    re.IGNORECASE,
)

_DETERMINISTIC_REPEAT_INTERRUPT_RE = re.compile(
    r"\b(repeat|say that again|come again|pardon|what did you say|didnt catch that|didn't catch that)\b",
    re.IGNORECASE,
)

_DETERMINISTIC_PAUSE_INTERRUPT_RE = re.compile(
    r"\b(wait|hold on|one second|just a second|give me a second|give me a moment|wait a minute|one moment)\b",
    re.IGNORECASE,
)

_DETERMINISTIC_PACING_INTERRUPT_RE = re.compile(
    r"\b(slower|slow down|too fast|speak slowly|more slowly|start over|from the beginning)\b",
    re.IGNORECASE,
)


def build_deterministic_interrupt_reply(text: str) -> tuple[str | None, bool]:
    cleaned = re.sub(r"[^\w\s]", " ", (text or "").lower()).strip()
    cleaned = re.sub(r"\s+", " ", cleaned)
    if not cleaned or _CONTEXTUAL_INTERRUPT_RE.search(cleaned):
        return None, False
    if _DETERMINISTIC_REPEAT_INTERRUPT_RE.search(cleaned):
        return "Sure. I'll repeat that briefly.", True
    if _DETERMINISTIC_PACING_INTERRUPT_RE.search(cleaned):
        return "Sure. I'll continue more clearly.", True
    if _DETERMINISTIC_PAUSE_INTERRUPT_RE.search(cleaned):
        return "Sure. Is there anything else I can help you with?", False
    return None, False


def _interrupt_has_hard_stop(text: str) -> bool:
    return bool(re.search(r"\b(stop|wait|hold on|one second|give me a minute|listen)\b", text, re.IGNORECASE))


def _looks_like_short_farewell_ack(text: str) -> bool:
    cleaned = re.sub(r"\s+", " ", (text or "").strip().lower())
    return bool(
        cleaned
        and re.fullmatch(
            r"(?:no[ ,]+)?(?:thank you|thanks|thank you bye|thanks bye|bye|goodbye|have a great day)[.!]?",
            cleaned,
        )
    )


def _classify_conversational_interrupt(text: str) -> str | None:
    lower = re.sub(r"\s+", " ", (text or "").strip().lower())
    if not lower:
        return None
    if re.fullmatch(
        r"(?:hello|hi|hey|hello there|hi there|good morning|good afternoon|good evening|are you there|are you still there|can you hear me)[.!?]?",
        lower,
    ):
        return "greeting"
    if re.search(
        r"\b(?:why\s+are\s+you\s+calling|why\s+did\s+you\s+call|what\s+are\s+you\s+calling\s+about|what\s+is\s+this\s+about)\b",
        lower,
        re.IGNORECASE,
    ):
        return "purpose"
    if re.search(
        r"\b(?:what\s+(?:kind\s+of\s+)?services?\s+do\s+you\s+have|what\s+do\s+you\s+do|what\s+can\s+you\s+help\s+with|how\s+can\s+you\s+help|"
        r"do\s+you\s+help\s+with|do\s+you\s+deal\s+with|is\s+this\s+about\s+property)\b",
        lower,
        re.IGNORECASE,
    ):
        return "capabilities"
    if re.search(
        r"\b(?:where\s+is\s+your\s+office|where\s+is\s+the\s+office|where\s+is\s+jll(?:\s+homes)?|"
        r"office\s+(?:address|location))\b",
        lower,
        re.IGNORECASE,
    ):
        return "office"
    if re.search(
        r"\b(?:where\s+are\s+you\s+calling\s+from|where\s+are\s+you\s+from|"
        r"which\s+company(?:\s+is\s+this)?|what\s+company(?:\s+is\s+this)?|"
        r"is\s+this\s+jll|are\s+you\s+from\s+jll)\b",
        lower,
        re.IGNORECASE,
    ):
        return "source"
    if re.search(
        r"\b(?:who\s+(?:are\s+you|is\s+this)|what\s+is\s+(?:this|your\s+name)|"
        r"what's\s+your\s+name|your\s+name|may\s+i\s+know\s+your\s+name)\b",
        lower,
        re.IGNORECASE,
    ):
        return "identity"
    return None


def _looks_like_meta_conversation_question(text: str) -> bool:
    return _classify_conversational_interrupt(text) is not None


def _meta_question_base_reply(text: str) -> tuple[str | None, str | None, str | None]:
    interrupt_kind = _classify_conversational_interrupt(text)
    if not interrupt_kind:
        return None, None, None
    if interrupt_kind == "greeting":
        return "Yes, I'm here.", "greeting", "greeting"
    if interrupt_kind == "identity":
        return "My name is Riya. I'm a real estate assistant from JLL Homes.", "identity", "identity"
    if interrupt_kind == "source":
        return "I'm from JLL Homes, and I can help with your property search.", "company_source", "source"
    if interrupt_kind == "office":
        return (
            "I'm a virtual assistant for JLL Homes. I can help you find properties by property type, budget, and area.",
            "office_source",
            "office",
        )
    if interrupt_kind == "purpose":
        return "I'm calling to help with your property search through JLL Homes.", "purpose", "purpose"
    if interrupt_kind == "capabilities":
        return (
            "I can help you find properties like apartments, villas, or plots, and share pricing, "
            "amenities, possession timelines, callback, or site visit details.",
            "capabilities",
            "capabilities",
        )
    return "This is JLL Homes, and I'm here to help with your property search.", "fallback", interrupt_kind


def classify_interrupt_decision(
    text: str,
    interrupted_prompt: str = "",
    last_topic: str | None = None,
    *,
    assistant_is_synthetic: bool = False,
    speaking_phase: str = SPEAKING_PHASE_BARGEABLE,
    is_final: bool = True,
    min_interim_words: int = INTERRUPTION_MIN_INTERIM_WORDS,
) -> InterruptDecision:
    raw = (text or "").strip()
    if not raw:
        return InterruptDecision(kind="noise", reason="empty_input")

    lowered = raw.lower().strip()
    cleaned = re.sub(r"[^\w\s]", " ", lowered)
    cleaned = re.sub(r"\s+", " ", cleaned).strip()
    word_count = len(cleaned.split())
    prompt_expects_confirmation = interrupted_prompt_expects_confirmation(interrupted_prompt, last_topic)
    prompt_expects_slot = interrupted_prompt_expects_slot_answer(interrupted_prompt, last_topic)
    is_backchannel = is_ignorable_speaking_ack(raw)
    is_hold = bool(_DETERMINISTIC_PAUSE_INTERRUPT_RE.search(cleaned)) or cleaned in {
        "im here", "i am here", "yes im here", "yes i am here",
    }
    prompt_lower = (interrupted_prompt or "").strip().lower()
    is_closing_prompt = any(
        marker in prompt_lower
        for marker in (
            "thank you for calling",
            "have a great day",
            "goodbye",
            "reach out to you shortly",
            "call back later",
        )
    ) or (last_topic or "").strip().lower() in {"farewell", "goodbye", "closing"}
    is_repeat_or_pacing = bool(
        _DETERMINISTIC_REPEAT_INTERRUPT_RE.search(cleaned)
        or _DETERMINISTIC_PACING_INTERRUPT_RE.search(cleaned)
    )
    is_contextual = bool(_CONTEXTUAL_INTERRUPT_RE.search(cleaned))
    allow_early_commit = speaking_phase != SPEAKING_PHASE_NO_BARGE or _interrupt_has_hard_stop(cleaned) or is_hold

    if assistant_is_synthetic and cleaned in {
        "yes i am here", "yes im here", "i am here", "im here", "here", "yes",
    }:
        return InterruptDecision(
            kind="synthetic_checkin_reply",
            should_commit=True,
            should_pause=True,
            reason="synthetic_checkin_reply",
        )

    if is_resume_confirmation(raw):
        return InterruptDecision(
            kind="hold",
            should_commit=True,
            should_pause=False,
            should_resume=True,
            reason="resume_confirmation",
        )

    if is_hold:
        return InterruptDecision(
            kind="hold",
            should_commit=allow_early_commit,
            should_pause=True,
            should_resume=False,
            reason="hold_intent",
        )

    if is_final and is_closing_prompt and _looks_like_short_farewell_ack(raw):
        return InterruptDecision(
            kind="true_interrupt",
            should_commit=allow_early_commit,
            reason="farewell_ack",
        )

    if prompt_expects_confirmation:
        if _NEGATIVE_ONLY_RE.match(raw) or re.search(
            r"\b(yes|yeah|yep|correct|right|exactly|that one|this one)\b",
            cleaned,
            re.IGNORECASE,
        ):
            return InterruptDecision(
                kind="true_interrupt",
                should_commit=allow_early_commit,
                reason="prompt_confirmation_reply",
            )

    if prompt_expects_slot and not is_non_search_slot_chatter(raw) and not is_backchannel:
        if is_final or word_count >= min_interim_words:
            return InterruptDecision(
                kind="true_interrupt",
                should_commit=allow_early_commit,
                reason="prompt_slot_reply",
            )

    if is_backchannel:
        return InterruptDecision(
            kind="backchannel",
            should_commit=False,
            reason="bare_ack",
        )

    if is_non_search_slot_chatter(raw):
        if any(
            p in cleaned
            for p in ("can you hear me", "are you listening", "can we continue", "are you there", "still there")
        ):
            return InterruptDecision(
                kind="synthetic_checkin_reply" if assistant_is_synthetic else "noise",
                should_commit=assistant_is_synthetic and allow_early_commit,
                should_pause=assistant_is_synthetic,
                reason="checkin_chatter",
            )
        return InterruptDecision(kind="noise", reason="non_search_slot_chatter")

    substantive_patterns = [
        r"\b(stop|listen)\b",
        r"\b(no|not that|instead|but i asked|i said|dont want|do not want|another|different|elsewhere)\b",
        r"\b(tell me|show me|find|search|look for|suggest|schedule|book|callback|visit)\b",
        r"\b(anything else|something else|something more|more options|more properties|next property|next three|another one|other one|different one)\b",
        r"\b(price|budget|area|location|bhk|bedroom|property|project|details|apartment|apartments|villa|villas|plot|plots|builder floor|penthouse|senior living|row house|villament|villaments|duplex apartment|utsav plots)\b",
        r"\b(first|second|third|fourth|fifth)\b",
        r"\b(what|which|where|when|how|why)\b",
        r"\d",
    ]
    if is_repeat_or_pacing:
        return InterruptDecision(
            kind="true_interrupt",
            should_commit=allow_early_commit,
            reason="repeat_or_pacing_request",
        )

    if is_contextual or any(re.search(pattern, cleaned, re.IGNORECASE) for pattern in substantive_patterns):
        if is_final or word_count >= min_interim_words:
            return InterruptDecision(
                kind="true_interrupt",
                should_commit=allow_early_commit,
                reason="contextual_redirect",
            )

    if word_count >= 4 and (is_final or allow_early_commit):
        return InterruptDecision(
            kind="true_interrupt",
            should_commit=allow_early_commit,
            reason="multi_word_redirect",
        )

    return InterruptDecision(kind="noise", reason="low_semantic_content")


def is_ignorable_speaking_ack(text: str) -> bool:
    return bool(_IGNORABLE_SPEAKING_ACK_RE.match((text or "").strip()))


def is_non_location_chatter(text: str) -> bool:
    """Return True for generic check-in/chit-chat phrases that should never fill location slots."""
    t = (text or "").lower().strip()
    t = re.sub(r"[^\w\s]", "", t)
    if not t:
        return False
    chatter_patterns = [
        "i am here", "im here", "i'm here",
        "yes i am here", "yes im here", "yes i'm here",
        "can you hear me", "are you listening",
        "hello", "hi", "hey", "hello there",
        "are you there", "you there", "still there",
        "can we continue", "can you hear me now",
    ]
    if t in chatter_patterns:
        return True
    if len(t.split()) > 6:
        return False
    return any(re.search(r"\b" + re.escape(p) + r"\b", t) for p in chatter_patterns)


def is_non_search_slot_chatter(text: str) -> bool:
    """Return True for generic conversation that should never populate search slots."""
    t = (text or "").lower().strip()
    t = re.sub(r"[^\w\s]", "", t)
    if not t:
        return False
    substantive_patterns = (
        r"\b(?:bhk|bedroom|bedrooms|budget|price|pricing|cost|property|properties|project|projects|"
        r"apartment|apartments|villa|villas|plot|plots|location|area|areas|construction|"
        r"under construction|ready to move|launched|resale|new project|show|find|search|"
        r"looking|want|need|only|just|more|another|different)\b",
        r"\d",
    )
    if any(re.search(pattern, t, re.IGNORECASE) for pattern in substantive_patterns):
        return False
    generic_patterns = [
        "i am here", "im here", "i'm here",
        "yes i am here", "yes im here", "yes i'm here",
        "can you hear me", "are you listening",
        "are you there", "you there", "still there",
        "hello", "hello there", "hi", "hey",
        "okay", "ok", "yes", "yeah", "yep", "sure",
        "one second", "hold on", "wait a minute",
        "can we continue", "tell me more", "go on",
    ]
    if t in generic_patterns:
        return True
    if len(t.split()) > 7:
        return False
    return any(re.search(r"\b" + re.escape(p) + r"\b", t) for p in generic_patterns)


def _strip_recent_synthetic_context_messages(ctx) -> int:
    if not ctx or not hasattr(ctx, "messages"):
        return 0
    synthetic_messages = {
        msg.strip() for msg in global_state_manager.synthetic_messages() if (msg or "").strip()
    }
    if not synthetic_messages:
        return 0
    kept = []
    removed = 0
    for message in getattr(ctx, "messages", []):
        content = (message.get("content") or "").strip() if isinstance(message, dict) else ""
        role = message.get("role") if isinstance(message, dict) else None
        if role == "assistant" and content in synthetic_messages:
            removed += 1
            continue
        kept.append(message)
    if removed:
        ctx.messages[:] = kept
    global_state_manager.clear_synthetic_messages()
    return removed


def _should_block_idle_followup() -> bool:
    if global_state_manager.pending_resume():
        logger.info("[IdleGuard] suppressed_are_you_there reason=pending_resume")
        return True
    if global_state_manager.get_interrupted_text():
        logger.info("[IdleGuard] suppressed_are_you_there reason=interrupted_text")
        return True
    if global_state_manager.current_assistant_is_synthetic():
        logger.info("[IdleGuard] suppressed_are_you_there reason=synthetic_assistant_output")
        return True
    idle_block_reason = global_state_manager.idle_followup_block_reason()
    if idle_block_reason:
        if global_state_manager.should_log_idle_followup_block(idle_block_reason):
            logger.info(f"[IdleGuard] suppressed_are_you_there reason={idle_block_reason}")
        return True
    return False


async def _queue_synthetic_assistant_text(task, text: str):
    cleaned = (text or "").strip()
    if not cleaned:
        return
    global_state_manager.begin_assistant_output(synthetic=True, text=cleaned)
    global_state_manager.remember_synthetic_message(cleaned)
    await task.queue_frames([
        LLMFullResponseStartFrame(),
        LLMTextFrame(cleaned),
        LLMFullResponseEndFrame(),
    ])


