def _looks_like_independent_house_request(text: str) -> bool:
    lower = re.sub(r"\s+", " ", (text or "").strip().lower())
    return bool(re.search(r"\b(?:independent|individual|standalone)\s+houses?\b", lower))


def _looks_like_land_property_type_request(text: str) -> bool:
    lower = re.sub(r"\s+", " ", (text or "").strip().lower())
    return bool(re.search(r"\blands?\b", lower))


def _looks_like_ambiguous_house_request(text: str) -> bool:
    lower = re.sub(r"\s+", " ", (text or "").strip().lower())
    if not lower:
        return False
    if _looks_like_independent_house_request(lower) or _looks_like_land_property_type_request(lower):
        return False
    if re.search(r"\b(?:row|raw)\s+houses?\b|\bpenthouses?\b", lower):
        return False
    if re.search(r"\b(?:apartment|apartments|flat|flats|villa|villas|plot|plots|land|lands)\b", lower):
        return False
    return bool(re.search(r"\b(?:house|houses|home|homes)\b", lower))


def _house_type_clarification_response(gathered: dict | None) -> tuple[str, bool]:
    gs = gathered or {}
    try:
        attempts = int(gs.get("_house_type_clarification_count") or 0)
    except Exception:
        attempts = 0
    if attempts >= 2:
        return "I'll take house as apartments for now.", True
    if attempts == 1:
        return "House can mean either apartment or villa here. Which one should I search?", False
    return "By house, do you mean an apartment or a villa?", False


def _looks_like_unsupported_property_type_request(text: str) -> bool:
    lower = re.sub(r"\s+", " ", (text or "").strip().lower())
    if not lower:
        return False
    if (
        _looks_like_independent_house_request(lower)
        or _looks_like_land_property_type_request(lower)
        or _looks_like_ambiguous_house_request(lower)
    ):
        return False
    unsupported_patterns = (
        r"\b(?:house|houses|home|homes)\b",
        r"\b(?:builder floor|building floor|penthouse|penthouses|senior living)\b",
        r"\b(?:row house|raw house|row houses|raw houses|villament|villaments)\b",
        r"\b(?:duplex apartment|duplex apartments|utsav plot|utsav plots)\b",
    )
    if not any(re.search(pattern, lower, re.IGNORECASE) for pattern in unsupported_patterns):
        return False
    if re.search(r"\b(?:apartment|apartments|flat|flats|villa|villas|plot|plots|land)\b", lower, re.IGNORECASE):
        return False
    return bool(
        re.search(
            r"\b(?:looking|searching|find|show|list|suggest|recommend|need|want|interested|property|properties)\b",
            lower,
            re.IGNORECASE,
        )
    )


