def _format_spoken_clock_time(hour: int, minute: int = 0, meridiem: str = "") -> str:
    """Return a TTS-safe spoken time without punctuation or AM/PM tokens."""
    mer = (meridiem or "").strip().lower()
    hour = int(hour)
    minute = int(minute or 0)
    if not (1 <= hour <= 12) or not (0 <= minute <= 59):
        return ""

    if minute == 0:
        if mer.startswith("a") and hour == 12:
            return "12 midnight"
        if mer.startswith("p") and hour == 12:
            return "12 noon"
        base = f"{hour} o'clock"
    else:
        minute_text = f"oh {minute}" if minute < 10 else str(minute)
        base = f"{hour} {minute_text}"

    if mer.startswith("a"):
        return f"{base} in the morning"
    if mer.startswith("p"):
        period = "in the afternoon" if hour == 12 or hour < 5 else "in the evening"
        return f"{base} {period}"
    return base


def _site_visit_closing_confirmation(
    property_name: str | None = None,
    visit_date: str | None = None,
    first_name: str | None = None,
) -> str:
    name = str(property_name or "").strip()
    if not name or name.lower() in {"property", "properties", "apartment", "apartments"}:
        name = "the property"

    date_phrase = ""
    raw_date = str(visit_date or "").strip()
    if raw_date:
        try:
            import datetime as _dt

            today = _dt.date.today()
            parsed = raw_date.replace("Z", "+00:00")
            dt = _dt.datetime.fromisoformat(parsed)
            if dt.year < today.year:
                dt = dt.replace(year=today.year)
            visit_day = dt.date()
            if visit_day == today:
                day_text = "today"
            elif visit_day == today + _dt.timedelta(days=1):
                day_text = "tomorrow"
            else:
                day_text = dt.strftime("%d %B %Y")
            time_text = _format_spoken_clock_time(
                int(dt.strftime("%I")),
                dt.minute,
                dt.strftime("%p"),
            )
            date_phrase = f" for {day_text} at {time_text}"
        except Exception:
            date_phrase = ""

    customer = str(first_name or "").strip()
    customer_suffix = (
        f", {customer}"
        if customer and customer.lower() not in {"customer", "user", "caller"}
        else ""
    )
    return (
        f"Your site visit to {name} is scheduled{date_phrase}{customer_suffix}. "
        "Thank you for calling JLL Homes, have a great day."
    )


def _property_type_singular_label(property_type: str | None) -> str:
    normalized = re.sub(r"\s+", " ", str(property_type or "").strip().lower())
    if not normalized:
        return "property"
    mapping = {
        "apartments": "apartment",
        "apartment": "apartment",
        "duplex apartment": "duplex apartment",
        "builder floor": "builder floor",
        "penthouses": "penthouse",
        "penthouse": "penthouse",
        "villas": "villa",
        "villa": "villa",
        "villaments": "villament",
        "villament": "villament",
        "plots": "plot",
        "plot": "plot",
        "utsav plots": "plot",
        "row house": "row house",
        "senior living": "senior living property",
    }
    if normalized in mapping:
        return mapping[normalized]
    if normalized.endswith("ies"):
        return normalized[:-3] + "y"
    if normalized.endswith("s") and len(normalized) > 3:
        return normalized[:-1]
    return normalized or "property"


def _property_type_plural_label(property_type: str | None) -> str:
    singular = _property_type_singular_label(property_type)
    irregular = {
        "property": "properties",
        "senior living property": "senior living properties",
    }
    if singular in irregular:
        return irregular[singular]
    if singular.endswith("s"):
        return singular
    return f"{singular}s"


GATHER_OFF_DOMAIN_RESPONSE = (
    "Sorry, I'm a real estate assistant from JLL Homes. I can help you find properties by "
    "property type, budget, and area. Please share the property details you're looking for."
)


def _looks_like_off_domain_gather_request(text: str) -> bool:
    lower = re.sub(r"\s+", " ", (text or "").strip().lower())
    if not lower:
        return False
    if _extract_property_type_from_text(lower) or _parse_inr_amounts(lower):
        return False
    if re.search(
        r"\b(property|properties|apartment|apartments|villa|villas|plot|plots|bhk|bedroom|"
        r"budget|price|area|location|site\s+visit|visit|callback|call\s+back|jll|home|homes|"
        r"real\s+estate)\b",
        lower,
    ):
        return False
    return bool(
        re.search(
            r"\b(order|book|buy|purchase|shoe|shoes|food|pizza|biryani|meal|meals|"
            r"lunch|dinner|breakfast|swiggy|zomato|cab|taxi|ticket|tickets|movie|"
            r"restaurant|hotel|medicine|doctor|hospital|bank|loan|insurance|repair|support|"
            r"complaint|refund|delivery|appointment|appoint|meeting|interview|passport|"
            r"visa|flight|train|bus)\b",
            lower,
        )
    )


def _should_defer_invalid_gather_turn_to_llm(text: str, expected_field: str | None = None) -> bool:
    """Let the LLM semantically repair substantive non-slot turns during gather."""
    lower = re.sub(r"\s+", " ", (text or "").strip().lower())
    if not lower or not expected_field:
        return False
    if _looks_like_off_domain_gather_request(lower):
        return False
    if is_non_search_slot_chatter(lower):
        return False
    if _extract_property_type_from_text(lower) or _parse_inr_amounts(lower):
        return False
    if _is_flexible_budget_text(lower) or _is_citywide_location_text(lower):
        return False

    words = re.findall(r"\w+", lower)
    if len(words) <= 2:
        return False
    if re.search(
        r"\b("
        r"what|why|how|can|could|would|please|tell|explain|help|want|need|book|"
        r"order|buy|purchase|make|schedule|arrange|do|does|is|are|renew|cancel|"
        r"pay|open|close|apply"
        r")\b",
        lower,
    ):
        return True
    return len(words) >= 5


def _llm_gather_repair_instruction(expected_field: str, user_text: str) -> str:
    retry_prompt = _reprompt_for_invalid_gather_field(expected_field, user_text=user_text)
    return (
        "GATHER REPAIR INSTRUCTION: The assistant is currently gathering "
        f"{expected_field}, but the latest user turn did not provide a valid value: "
        f"{user_text!r}. If the user is asking for something outside JLL Homes real "
        "estate property search, respond exactly: "
        f"{GATHER_OFF_DOMAIN_RESPONSE!r}. If the turn is just unclear or likely a "
        f"misheard answer for {expected_field}, respond exactly: {retry_prompt!r}. "
        "If the user is asking a valid property-search follow-up, answer briefly and "
        "then ask for the missing search detail. Do not call search tools from this "
        "turn unless the user supplied a valid search slot or a valid property workflow intent."
    )


def _property_type_supports_bedrooms(property_type: str | None) -> bool:
    normalized = str(property_type or "").strip().lower()
    if not normalized:
        return True
    return normalized not in {
        "plots",
        "utsav plots",
    }


def _extract_property_type_from_text(text: str) -> str:
    lower = (text or "").lower()
    if is_non_search_slot_chatter(lower):
        return ""
    if _looks_like_independent_house_request(lower):
        return "Villas"
    if _looks_like_land_property_type_request(lower):
        return "Plots"
    if _looks_like_ambiguous_house_request(lower):
        return ""
    if _looks_like_unsupported_property_type_request(lower):
        return ""
    # Handle common short STT variants around "apartments" when the user is
    # answering with a property type.
    if lower.strip().startswith("apart"):
        return "Apartments"
    for kw, val in _PROPERTY_TYPE_ALIASES:
        if re.search(r"\b" + re.escape(kw) + r"\b", lower, re.IGNORECASE):
            return val if val in _SUPPORTED_DETERMINISTIC_PROPERTY_TYPES else ""
    return ""


def is_greeting(text: str) -> bool:
    """Check if text is a greeting (respects state - only true in IDLE)."""
    if not text:
        return False
    t = text.lower().strip()
    t = re.sub(r'[^\w\s]', '', t)
    greetings = ["hello", "hi", "hey", "greetings", "good morning", 
                 "good afternoon", "good evening", "namaste", "vanakkam"]
    return any(g in t for g in greetings)


def extract_topic(response_text: str) -> str:
    """Extract the topic from assistant response for resume context.
    
    Fully dynamic - no hardcoded locations. Extracts from actual response text.
    """
    if not response_text:
        return None
    
    text = response_text.lower()
    
    # Look for property/project names (capitalized words that look like names)
    # Pattern: look for "about X" or "property X" or "project X"
    patterns = [
        r'about\s+([A-Z][a-zA-Z\s]+?)(?:\s+(?:in|at|with|for|and|or|\.))',
        r'(property|project|apartment|villa|plot)\s+(?:called|named)\s+([A-Z][a-zA-Z\s]+?)',
        r'([A-Z][a-zA-Z]+(?:\s+[A-Z][a-zA-Z]+)?)\s+(?:in|at|located)',
    ]
    
    for pattern in patterns:
        match = re.search(pattern, text, re.IGNORECASE)
        if match:
            topic = match.group(1).strip()
            if len(topic) > 2:
                return topic
    
    # Dynamic location extraction - find capitalized location names
    # Look for patterns like "in [Location]" or "at [Location]"
    location_patterns = [
        r'(?:in|at|located\s+in)\s+([A-Z][a-zA-Z\s]+?)(?:\s+(?:with|for|and|or|\.|$))',
        r'area\s+(?:called|named)\s+([A-Z][a-zA-Z\s]+?)',
    ]
    
    for pattern in location_patterns:
        match = re.search(pattern, text)
        if match:
            location = match.group(1).strip()
            if len(location) > 2:
                return f"properties in {location}"
    
    # Return None if no topic found - caller will handle fallback
    return None


def resume_response(state_manager: ConversationStateManager) -> str:
    """Generate a context-aware resume response after interruption.
    
    Fully dynamic - uses actual context data from state manager.
    No generic fallbacks - if no context, returns None for caller to handle.
    """
    # Try to extract specific context from tool results first
    if state_manager.last_tool_result:
        result = state_manager.last_tool_result
        if isinstance(result, dict):
            project = result.get("project_name") or result.get("name")
            location = result.get("location") or result.get("micro_market")
            city = result.get("city")
            property_type = result.get("property_type")
            
            if project:
                # Most specific: we have the actual project name
                response = f"Yes, I'm here. I was telling you about {project}. Would you like full details or schedule a visit?"
                lower = response.lower()
                if any(x in lower for x in ["thank you", "thanks for calling", "goodbye", "have a great day", "welcome", "hello"]):
                    return None
                return response
            elif location and city:
                # Specific location + city
                response = f"Yes, I'm here. I was showing you properties in {location}, {city}. What would you like to know?"
                lower = response.lower()
                if any(x in lower for x in ["thank you", "thanks for calling", "goodbye", "have a great day", "welcome", "hello"]):
                    return None
                return response
            elif location:
                # Specific location only
                response = f"Yes, I'm here. I was showing you properties in {location}. Would you like more details?"
                lower = response.lower()
                if any(x in lower for x in ["thank you", "thanks for calling", "goodbye", "have a great day", "welcome", "hello"]):
                    return None
                return response
            elif city:
                # City only
                response = f"Yes, I'm here. I was showing you properties in {city}. What would you like to know?"
                lower = response.lower()
                if any(x in lower for x in ["thank you", "thanks for calling", "goodbye", "have a great day", "welcome", "hello"]):
                    return None
                return response
    
    # Fall back to topic extracted from assistant response
    if state_manager.last_topic:
        topic = state_manager.last_topic
        response = f"Yes, I'm here. I was talking about {topic}. What would you like to know?"
        lower = response.lower()
        if any(x in lower for x in ["thank you", "thanks for calling", "goodbye", "have a great day", "welcome", "hello"]):
            return None
        return response
    
    # No context available - return None for caller to handle
    return None


def route_interrupt(state_manager: ConversationStateManager, user_text: str) -> tuple[str, bool]:
    """
    Route an interruption based on state and user input.
    
    Returns:
        tuple: (response_text, is_resume) - response to speak, and whether it's a resume
    """
    logger.info(f"[INTERRUPT] text='{user_text}' state={state_manager.state.value}")
    
    if state_manager.state != AgentState.INTERRUPTED:
        return None, False
    
    if is_soft_interrupt(user_text):
        response = resume_response(state_manager)
        if response:
            # EXPLICIT STATE TRANSITION LOG (REQUIRED FOR AUDIT)
            logger.info(f"[STATE] interrupted â†’ resuming | reason=soft_interrupt text='{user_text}'")

            state_manager.set_state(AgentState.RESUMING)

            logger.info(f"[RESUME] context_available=True response='{response[:60]}...'")
            return response, True
        else:
            # No context available - treat as new input
            logger.info(f"[RESUME] context_available=False - treating as new input")
            state_manager.set_state(AgentState.THINKING)
            return None, False
    else:
        # Substantive interruption - treat as new input but preserve context
        state_manager.set_state(AgentState.THINKING)
        logger.info(f"[INTERRUPT] Substantive - processing as new input")
        return None, False


