class FillerAudioManager:
    """Pre-synthesizes filler audio clips at startup for instant playback during tool calls."""

    FILLER_TEXTS = [
        "Sure, let me find that for you.",
        "Let me check that for you.",
        "Give me just a moment.",
        "Looking that up for you now.",
        "One moment while I search.",
        "Let me pull that up for you.",
        "Searching for the best options.",
        "Just a second while I check.",
    ]

    def __init__(self, tts_service, sample_rate=24000):
        self._clips: dict[str, bytes] = {}
        self._tts = tts_service
        self._sample_rate = sample_rate
        self._lock = asyncio.Lock()
        self._ready = False

    async def preload(self):
        """Call once at pipeline startup. Synthesizes all clips."""
        async with self._lock:
            for text in self.FILLER_TEXTS:
                try:
                    audio = await self._tts.synthesize_raw(text)
                    if audio:
                        self._clips[text] = audio
                        logger.info(f"[Filler] Preloaded: '{text}' ({len(audio)} bytes)")
                    else:
                        logger.warning(f"[Filler] Skipped (empty result): '{text}'")
                except Exception as e:
                    logger.warning(f"[Filler] Failed to preload '{text}': {e}")
            self._ready = True
            logger.info(f"[Filler] Ready - {len(self._clips)} clips loaded")

    def get_random_clip(self) -> bytes | None:
        if not self._ready or not self._clips:
            return None
        import random
        text = random.choice(list(self._clips.keys()))
        return self._clips[text]

    def get_clip(self, text: str) -> bytes | None:
        return self._clips.get(text)


async def _play_filler_audio(audio_bytes: bytes, transport, filler_playing_ref: list):
    """Push raw PCM audio directly to transport output."""
    try:
        filler_playing_ref[0] = True
        frame = AudioRawFrame(
            audio=audio_bytes,
            sample_rate=24000,
            num_channels=1,
        )
        await transport.send_audio(frame)
        filler_playing_ref[0] = False
    except Exception as e:
        logger.warning(f"[Filler] Failed to play clip: {e}")
        filler_playing_ref[0] = False


