def _redact_sensitive_value(value):
    if isinstance(value, str):
        redacted = re.sub(r'Bearer\s+[A-Za-z0-9._\-]+', 'Bearer [REDACTED]', value, flags=re.IGNORECASE)
        redacted = re.sub(r'\b(?:\+91|91)?[6-9]\d{9}\b', '[REDACTED_PHONE]', redacted)
        return redacted
    if isinstance(value, list):
        return [_redact_sensitive_value(item) for item in value]
    if isinstance(value, dict):
        return {
            key: ('[REDACTED]' if any(token in str(key).lower() for token in ('token', 'authorization', 'password', 'secret')) else _redact_sensitive_value(val))
            for key, val in value.items()
        }
    return value


def _summarize_transcript(transcript: list[dict]) -> dict:
    return {
        "turns": len(transcript or []),
        "roles": dict(Counter(item.get("role", "unknown") for item in (transcript or []) if isinstance(item, dict))),
    }


def _log_transcript_if_enabled(prefix: str, transcript: list[dict]) -> None:
    if not DEBUG_TRANSCRIPT_LOGS:
        logger.info(f"{prefix} transcript_summary={_summarize_transcript(transcript)}")
        return
    logger.debug(
        f"{prefix} transcript={json.dumps(_redact_sensitive_value(transcript), ensure_ascii=False)}"
    )


def _get_internal_service_headers() -> dict:
    headers = {}
    if INTERNAL_SERVICE_TOKEN:
        headers["Authorization"] = f"Bearer {INTERNAL_SERVICE_TOKEN}"
    return headers


async def _backend_request(
    method: str,
    path: str,
    *,
    json_body: dict | None = None,
    headers: dict | None = None,
    timeout: httpx.Timeout | float | None = None,
):
    merged_headers = {**_get_internal_service_headers(), **(headers or {})}
    async with httpx.AsyncClient(timeout=timeout or DEFAULT_HTTP_TIMEOUT, limits=DEFAULT_HTTP_LIMITS) as client:
        return await client.request(
            method,
            f"{BACKEND_URL}{path}",
            json=json_body,
            headers=merged_headers,
        )

