def _make_prefetch_key(
    city: str,
    property_type: str,
    location: str,
    min_price,
    max_price,
    bedrooms: str | None = None,
    project_category: str | None = None,
    construction_state: str | None = None,
) -> str:
    """Build normalized prefetch cache key for consistent lookup."""
    def _norm_text(value: str) -> str:
        return re.sub(r'[^a-z0-9]+', '', (value or "").strip().lower())
    return "|".join([
        _norm_text(city),
        _norm_text(property_type),
        _norm_text(location),
        str(int(min_price)) if min_price is not None else "",
        str(int(max_price)) if max_price is not None else "",
        _norm_text(bedrooms),
        _norm_text(project_category),
        _norm_text(construction_state),
    ])


