def classify_sentiment_topic(transcript: list[dict]) -> str:
    try:
        turns: list[str] = []
        for m in transcript[-12:]:
            role = m.get("role", "user")
            content = m.get("content", "")
            if not content:
                continue
            turns.append(f"{role}: {content}")
        convo = "\n".join(turns)[-4000:]

        system_prompt = (
            "You are a call outcome classifier for JLL real-estate voice calls.\n"
            "Given the conversation transcript, choose EXACTLY ONE of these labels:\n"
            "- Property Search\n"
            "- Property Details Inquiry\n"
            "- Budget Discussion\n"
            "- Locality Refinement\n"
            "- Site Visit Intent\n"
            "- Callback Intent\n"
            "- Failed Call\n\n"
            "Rules:\n"
            "- Output ONLY the label text, nothing else.\n"
            "- Use 'Property Search' when the user is mainly exploring properties, sharing broad requirements, or asking for options.\n"
            "- Use 'Property Details Inquiry' when the user focuses on a specific property and asks about its details, amenities, builder, pricing, or possession.\n"
            "- Use 'Budget Discussion' when the main exchange is around budget, affordability, price range, or pricing objections.\n"
            "- Use 'Locality Refinement' when the user changes, corrects, narrows, or compares area or locality preferences.\n"
            "- Use 'Site Visit Intent' when the user explicitly wants to book, schedule, or discuss a site visit.\n"
            "- Use 'Callback Intent' when the user explicitly asks for a callback, follow-up, or contact from the team.\n"
            "- Treat obviously dropped, one-sided, repeated hello/check-in, or unusable calls as 'Failed Call'.\n"
            "- If multiple labels appear, choose the dominant final business outcome of the call.\n"
            "- If uncertain between search-related labels, prefer 'Property Search'."
        )

        api_key = os.getenv("GROQ_API_KEY")
        if not api_key:
            logger.warning("Sentiment classification skipped: GROQ_API_KEY is not configured")
            return "Property Search"

        url = "https://api.groq.com/openai/v1/chat/completions"
        model = os.getenv("SENTIMENT_LLM_MODEL", "llama-3.3-70b-versatile")

        headers = {
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        }
        payload = {
            "model": model,
            "messages": [
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": convo or "No transcript available."},
            ],
            "temperature": 0.0,
            "max_tokens": 12,
        }

        with httpx.Client(timeout=8.0) as client:
            r = client.post(url, json=payload, headers=headers)
            r.raise_for_status()
            data = r.json()
            raw = (
                data.get("choices", [{}])[0]
                .get("message", {})
                .get("content", "")
                .strip()
            )
            normalized = raw.lower()
            mapping = {
                "property search": "Property Search",
                "property details inquiry": "Property Details Inquiry",
                "budget discussion": "Budget Discussion",
                "locality refinement": "Locality Refinement",
                "site visit intent": "Site Visit Intent",
                "callback intent": "Callback Intent",
                "failed call": "Failed Call",
            }
            for key, label in mapping.items():
                if key in normalized:
                    return label
            if "site visit" in normalized or "visit" in normalized:
                return "Site Visit Intent"
            if "callback" in normalized or "call back" in normalized or "follow up" in normalized:
                return "Callback Intent"
            if "locality" in normalized or "location" in normalized or "area" in normalized:
                return "Locality Refinement"
            if "budget" in normalized or "price" in normalized or "afford" in normalized:
                return "Budget Discussion"
            if "detail" in normalized or "amenit" in normalized or "builder" in normalized or "possession" in normalized:
                return "Property Details Inquiry"
            if "failed" in normalized or "dropped" in normalized or "one sided" in normalized or "unusable" in normalized:
                return "Failed Call"
    except Exception as e:
        logger.warning(f"Sentiment classification failed: {e}")
    return "Property Search"


