def _usage_rate(*env_names: str, default: float = 0.0) -> float:
    for name in env_names:
        value = os.getenv(name, "")
        if not value:
            continue
        try:
            return float(value)
        except (ValueError, TypeError):
            logger.warning(f"Invalid cost rate for {name}: {value}, using default {default}")
            return default
    return default


def _append_unique_model(target: dict[str, Any], model_name: str | None) -> None:
    if not model_name:
        return
    models = target.setdefault("models", [])
    if model_name not in models:
        models.append(model_name)


class STTAudioUsageTracker(FrameProcessor):
    """Tracks exact audio seconds sent to the STT service."""

    def __init__(self, usage_metrics_ref: list[dict[str, Any]], stt_provider: str, stt_region: str, stt_model: str):
        super().__init__()
        self._usage_metrics_ref = usage_metrics_ref
        self._stt_provider = stt_provider
        self._stt_region = stt_region
        self._stt_model = stt_model

    async def process_frame(self, frame, direction):
        if isinstance(frame, AudioRawFrame) and direction == FrameDirection.DOWNSTREAM:
            channels = max(int(getattr(frame, "num_channels", 1) or 1), 1)
            sample_rate = max(int(getattr(frame, "sample_rate", 0) or 0), 1)
            audio_bytes = len(getattr(frame, "audio", b"") or b"")
            duration_seconds = audio_bytes / (2 * channels * sample_rate)
            metrics = self._usage_metrics_ref[0].setdefault("stt", {})
            metrics["audio_seconds"] = round(float(metrics.get("audio_seconds", 0.0)) + duration_seconds, 6)
            metrics["provider"] = self._stt_provider
            metrics["region"] = self._stt_region
            metrics["model"] = self._stt_model

        await super().process_frame(frame, direction)
        await self.push_frame(frame, direction)


class CallAudioRecorder:
    """Collects user and assistant PCM frames and renders a mixed mono WAV."""

    def __init__(self, sample_rate: int = CALL_RECORDING_SAMPLE_RATE):
        self.sample_rate = max(int(sample_rate or 16000), 8000)
        self.started_at = time.monotonic()
        self._segments: list[tuple[int, bytes, int, int, str]] = []
        self._source_next_offset_samples: dict[str, int] = {}
        self._closed = False

    def add_frame(self, frame, source: str) -> None:
        if self._closed:
            return
        audio = getattr(frame, "audio", None) or getattr(frame, "data", None) or b""
        if not audio:
            return
        try:
            sample_rate = max(int(getattr(frame, "sample_rate", 0) or self.sample_rate), 1)
            channels = max(int(getattr(frame, "num_channels", 1) or 1), 1)
            self.add_pcm(audio, source, sample_rate=sample_rate, channels=channels)
        except Exception as exc:
            logger.debug(f"[CallRecording] frame capture skipped source={source}: {exc}")

    def add_pcm(self, audio: bytes, source: str, *, sample_rate: int, channels: int = 1) -> None:
        if self._closed or not audio:
            return
        try:
            sample_rate = max(int(sample_rate or self.sample_rate), 1)
            channels = max(int(channels or 1), 1)
            wall_offset_samples = max(0, int((time.monotonic() - self.started_at) * self.sample_rate))
            frame_samples = max(0, len(audio) // max(2 * channels, 1))
            duration_samples = int((frame_samples / float(sample_rate)) * self.sample_rate)
            source_key = (source or "").strip().lower() or "unknown"
            if source_key == "assistant":
                next_offset = self._source_next_offset_samples.get(source_key, 0)
                offset_samples = max(wall_offset_samples, next_offset)
                if offset_samples != wall_offset_samples:
                    logger.debug(
                        f"[CallRecording] adjusted assistant placement "
                        f"source={source_key} wall={wall_offset_samples} adjusted={offset_samples} "
                        f"duration={duration_samples} correction_ms={int(((offset_samples - wall_offset_samples) / self.sample_rate) * 1000)}"
                    )
                self._source_next_offset_samples[source_key] = offset_samples + duration_samples
            else:
                offset_samples = wall_offset_samples
            self._segments.append((offset_samples, bytes(audio), sample_rate, channels, source))
        except Exception as exc:
            logger.debug(f"[CallRecording] pcm capture skipped source={source}: {exc}")

    def _to_target_mono(self, pcm: bytes, sample_rate: int, channels: int) -> bytes:
        if channels > 1 and audioop:
            if channels == 2:
                pcm = audioop.tomono(pcm, 2, 0.5, 0.5)
            else:
                # audioop has no generic N-channel mixer; keep the first channel.
                pcm = audioop.tomono(pcm[: len(pcm) - (len(pcm) % (2 * channels))], 2, 1.0, 0.0)
        if sample_rate != self.sample_rate and audioop:
            pcm, _ = audioop.ratecv(pcm, 2, 1, sample_rate, self.sample_rate, None)
        elif sample_rate != self.sample_rate:
            return b""
        return pcm

    @staticmethod
    def _mix_into(target: bytearray, offset_bytes: int, pcm: bytes) -> None:
        end = offset_bytes + len(pcm)
        if end > len(target):
            target.extend(b"\x00" * (end - len(target)))
        if not audioop:
            target[offset_bytes:end] = pcm
            return
        existing = bytes(target[offset_bytes:end])
        mixed = audioop.add(existing, pcm, 2)
        target[offset_bytes:end] = mixed

    def render_wav(self) -> bytes | None:
        self._closed = True
        if not self._segments:
            return None
        mixed = bytearray()
        for offset_samples, pcm, sample_rate, channels, source in self._segments:
            try:
                converted = self._to_target_mono(pcm, sample_rate, channels)
                if not converted:
                    continue
                if audioop:
                    source_key = (source or "").strip().lower()
                    gain = 0.88 if source_key == "assistant" else 1.08
                    converted = audioop.mul(converted, 2, gain)
                self._mix_into(mixed, offset_samples * 2, converted)
            except Exception as exc:
                logger.debug(f"[CallRecording] segment skipped source={source}: {exc}")
        if not mixed:
            return None
        output = io.BytesIO()
        with wave.open(output, "wb") as wav:
            wav.setnchannels(1)
            wav.setsampwidth(2)
            wav.setframerate(self.sample_rate)
            wav.writeframes(bytes(mixed))
        return output.getvalue()


class UserAudioRecordingTap(FrameProcessor):
    def __init__(self, recorder: CallAudioRecorder | None):
        super().__init__()
        self._recorder = recorder

    async def process_frame(self, frame, direction):
        if self._recorder and isinstance(frame, AudioRawFrame) and direction == FrameDirection.DOWNSTREAM:
            self._recorder.add_frame(frame, "user")
        await super().process_frame(frame, direction)
        await self.push_frame(frame, direction)


class AssistantAudioRecordingTap(FrameProcessor):
    def __init__(self, recorder: CallAudioRecorder | None):
        super().__init__()
        self._recorder = recorder

    async def process_frame(self, frame, direction):
        if self._recorder and isinstance(frame, TTSAudioRawFrame) and direction == FrameDirection.DOWNSTREAM:
            self._recorder.add_frame(frame, "assistant")
        await super().process_frame(frame, direction)
        await self.push_frame(frame, direction)


class UsageMetricsCollector(FrameProcessor):
    """Captures exact LLM token usage and TTS character counts from Pipecat metrics."""

    def __init__(self, usage_metrics_ref: list[dict[str, Any]]):
        super().__init__()
        self._usage_metrics_ref = usage_metrics_ref

    async def process_frame(self, frame, direction):
        if isinstance(frame, MetricsFrame):
            for metrics_data in getattr(frame, "data", []) or []:
                if isinstance(metrics_data, LLMUsageMetricsData):
                    usage = metrics_data.value
                    llm_metrics = self._usage_metrics_ref[0].setdefault("llm", {})
                    llm_metrics["prompt_tokens"] = int(llm_metrics.get("prompt_tokens", 0)) + int(usage.prompt_tokens or 0)
                    llm_metrics["completion_tokens"] = int(llm_metrics.get("completion_tokens", 0)) + int(usage.completion_tokens or 0)
                    llm_metrics["total_tokens"] = int(llm_metrics.get("total_tokens", 0)) + int(usage.total_tokens or 0)
                    llm_metrics["cached_input_tokens"] = int(llm_metrics.get("cached_input_tokens", 0)) + int(usage.cache_read_input_tokens or 0)
                    llm_metrics["reasoning_tokens"] = int(llm_metrics.get("reasoning_tokens", 0)) + int(usage.reasoning_tokens or 0)
                    _append_unique_model(llm_metrics, getattr(metrics_data, "model", None))
                elif isinstance(metrics_data, TTSUsageMetricsData):
                    tts_metrics = self._usage_metrics_ref[0].setdefault("tts", {})
                    tts_metrics["characters"] = int(tts_metrics.get("characters", 0)) + int(metrics_data.value or 0)
                    _append_unique_model(tts_metrics, getattr(metrics_data, "model", None))

        await super().process_frame(frame, direction)
        await self.push_frame(frame, direction)


def compute_cost_breakdown(
    duration_seconds: float,
    transcript: list[dict[str, Any]] | None = None,
    config: dict[str, Any] | None = None,
    usage_metrics: dict[str, Any] | None = None,
) -> tuple[float, dict]:
    """Calculate a per-service INR breakdown for the completed call."""
    minutes = duration_seconds / 60.0
    transcript = transcript or []
    config = config or {}
    usage_metrics = usage_metrics or build_empty_usage_metrics()

    def transcript_usage_stats(items: list[dict[str, Any]]) -> dict[str, int]:
        user_chars = 0
        assistant_chars = 0
        assistant_turns = 0
        input_chars_seen = 0
        estimated_input_tokens = 0

        for item in items:
            if not isinstance(item, dict):
                continue
            role = str(item.get("role") or "").strip().lower()
            content = str(item.get("content") or "").strip()
            if role not in {"user", "assistant"} or not content:
                continue

            char_count = len(content)
            if role == "assistant":
                assistant_chars += char_count
                assistant_turns += 1
                estimated_input_tokens += math.ceil(input_chars_seen / 4) if input_chars_seen > 0 else 0
            else:
                user_chars += char_count

            input_chars_seen += char_count

        estimated_output_tokens = math.ceil(assistant_chars / 4) if assistant_chars > 0 else 0
        return {
            "user_chars": user_chars,
            "assistant_chars": assistant_chars,
            "assistant_turns": assistant_turns,
            "estimated_input_tokens": estimated_input_tokens,
            "estimated_output_tokens": estimated_output_tokens,
        }

    usage = transcript_usage_stats(transcript)
    llm_usage = usage_metrics.get("llm", {}) if isinstance(usage_metrics, dict) else {}
    tts_usage = usage_metrics.get("tts", {}) if isinstance(usage_metrics, dict) else {}
    stt_usage = usage_metrics.get("stt", {}) if isinstance(usage_metrics, dict) else {}
    llm_provider = str(config.get("llmProvider") or "groq").strip().lower()
    llm_model = str(config.get("llmModel") or "").strip().lower()
    stt_provider = str(config.get("sttProvider") or "deepgram").strip().lower()
    stt_model = str(config.get("sttModel") or stt_usage.get("model") or "").strip().lower()
    stt_region = str(stt_usage.get("region") or os.getenv("AZURE_SPEECH_REGION", "centralindia")).strip().lower()
    tts_provider = str(config.get("ttsProvider") or "cartesia").strip().lower()
    tts_model = str(config.get("ttsModel") or "").strip().lower()

    telephony_rate = _usage_rate("COST_TELEPHONY_PER_MIN", default=0.0)
    llm_fallback_rate = _usage_rate("COST_LLM_PER_MIN", default=0.0)
    stt_rate = _usage_rate("COST_STT_PER_MIN", default=0.0)
    tts_rate_per_1k_chars = _usage_rate("COST_TTS_PER_1K_CHARS", "COST_TTS_PER_1K_CHARS_INR", default=0.0)
    llm_input_rate = _usage_rate("COST_LLM_INPUT_PER_1M_TOKENS", "COST_LLM_INPUT_PER_1M_TOKENS_INR", default=0.0)
    llm_output_rate = _usage_rate("COST_LLM_OUTPUT_PER_1M_TOKENS", "COST_LLM_OUTPUT_PER_1M_TOKENS_INR", default=0.0)
    llm_cached_input_rate_per_1m = _usage_rate(
        "COST_LLM_CACHED_INPUT_PER_1M_TOKENS",
        "COST_LLM_CACHED_INPUT_PER_1M_TOKENS_INR",
        default=0.0,
    )
    llm_cached_input_rate_per_1k = _usage_rate(
        "AZURE_OPENAI_GPT4O_MINI_CACHED_INPUT_PER_1K_TOKENS_INR",
        default=round(0.000075 * USD_TO_INR_REFERENCE, 6),
    )
    llm_search_call_rate = _usage_rate("COST_LLM_SEARCH_CALL", "COST_LLM_SEARCH_CALL_INR", default=0.0)

    if llm_provider == "openai" and "gpt-4o-mini" in llm_model:
        llm_input_rate = _usage_rate(
            "AZURE_OPENAI_GPT4O_MINI_INPUT_PER_1K_TOKENS_INR",
            "OPENAI_GPT4O_MINI_INPUT_PER_1K_TOKENS_INR",
            default=round(0.00015 * USD_TO_INR_REFERENCE, 6),
        ) * 1000.0
        llm_output_rate = _usage_rate(
            "AZURE_OPENAI_GPT4O_MINI_OUTPUT_PER_1K_TOKENS_INR",
            "OPENAI_GPT4O_MINI_OUTPUT_PER_1K_TOKENS_INR",
            default=round(0.0006 * USD_TO_INR_REFERENCE, 6),
        ) * 1000.0
        if llm_cached_input_rate_per_1m <= 0:
            llm_cached_input_rate_per_1m = llm_cached_input_rate_per_1k * 1000.0

    if stt_provider == "azure":
        default_stt_per_hour = round(1.0 * USD_TO_INR_REFERENCE, 6)
        stt_per_hour = _usage_rate(
            f"AZURE_SPEECH_STT_PER_HOUR_INR_{stt_region.upper()}",
            "AZURE_SPEECH_STT_PER_HOUR_INR",
            default=default_stt_per_hour,
        )
        stt_rate = stt_per_hour / 60.0
    elif stt_provider == "deepgram":
        stt_rate = _usage_rate("DEEPGRAM_STT_PER_MIN_INR", "COST_STT_PER_MIN", default=stt_rate)

    if tts_provider == "cartesia":
        tts_rate_per_1k_chars = _usage_rate(
            "CARTESIA_SONIC_3_PER_1K_CHARS_INR",
            "COST_TTS_PER_1K_CHARS",
            "COST_TTS_PER_1K_CHARS_INR",
            default=round((49.0 / 1_250_000.0) * 1000.0 * USD_TO_INR_REFERENCE, 6),
        )

    stt_audio_seconds = float(stt_usage.get("audio_seconds", 0.0) or 0.0)
    stt_billable_minutes = (stt_audio_seconds / 60.0) if stt_audio_seconds > 0 else minutes
    tts_characters = int(tts_usage.get("characters", 0) or 0)
    if tts_characters <= 0:
        tts_characters = usage["assistant_chars"]

    stt_cost = stt_billable_minutes * stt_rate
    tts_cost = (tts_characters / 1000.0) * tts_rate_per_1k_chars
    telephony_cost = minutes * telephony_rate

    llm_cost = 0.0
    llm_pricing_mode = "legacy_per_min"
    estimated_search_calls = 0

    if (
        llm_provider == "openai"
        and (llm_input_rate > 0 or llm_output_rate > 0)
        and (int(llm_usage.get("prompt_tokens", 0) or 0) > 0 or int(llm_usage.get("completion_tokens", 0) or 0) > 0)
    ):
        llm_pricing_mode = "exact_token_based"
        prompt_tokens = int(llm_usage.get("prompt_tokens", 0) or 0)
        completion_tokens = int(llm_usage.get("completion_tokens", 0) or 0)
        cached_input_tokens = int(llm_usage.get("cached_input_tokens", 0) or 0)
        uncached_prompt_tokens = max(prompt_tokens - cached_input_tokens, 0)
        cached_rate = llm_cached_input_rate_per_1m if llm_cached_input_rate_per_1m > 0 else llm_input_rate
        llm_cost = (
            (uncached_prompt_tokens / 1_000_000.0) * llm_input_rate
            + (cached_input_tokens / 1_000_000.0) * cached_rate
            + (completion_tokens / 1_000_000.0) * llm_output_rate
        )
    elif llm_provider == "openai" and (llm_input_rate > 0 or llm_output_rate > 0):
        llm_pricing_mode = "estimated_token_based"
        if "search" in llm_model:
            estimated_search_calls = usage["assistant_turns"]
        llm_cost = (
            (usage["estimated_input_tokens"] / 1_000_000.0) * llm_input_rate
            + (usage["estimated_output_tokens"] / 1_000_000.0) * llm_output_rate
            + (estimated_search_calls * llm_search_call_rate)
        )
    else:
        llm_cost = minutes * llm_fallback_rate

    total = round(llm_cost + stt_cost + tts_cost + telephony_cost, 6)
    breakdown = {
        "currency": "INR",
        "llm": round(llm_cost, 6),
        "stt": round(stt_cost, 6),
        "tts": round(tts_cost, 6),
        "telephony": round(telephony_cost, 6),
        "total": total,
        "duration_minutes": round(minutes, 2),
        "usage": {
            **usage,
            "prompt_tokens": int(llm_usage.get("prompt_tokens", 0) or 0),
            "completion_tokens": int(llm_usage.get("completion_tokens", 0) or 0),
            "cached_input_tokens": int(llm_usage.get("cached_input_tokens", 0) or 0),
            "reasoning_tokens": int(llm_usage.get("reasoning_tokens", 0) or 0),
            "tts_characters": tts_characters,
            "stt_audio_seconds": round(stt_audio_seconds, 3),
            "estimated_search_calls": estimated_search_calls,
        },
        "rates": {
            "llm_input_per_1m_tokens": llm_input_rate,
            "llm_output_per_1m_tokens": llm_output_rate,
            "llm_cached_input_per_1m_tokens": llm_cached_input_rate_per_1m,
            "llm_search_call": llm_search_call_rate,
            "llm_fallback_per_min": llm_fallback_rate,
            "stt_per_min": stt_rate,
            "stt_per_hour": round(stt_rate * 60.0, 6),
            "tts_per_1k_chars": tts_rate_per_1k_chars,
            "telephony_per_min": telephony_rate,
        },
        "pricing_model": {
            "llm": llm_pricing_mode,
            "stt": "per_minute",
            "tts": "per_1k_chars",
            "telephony": "per_minute",
        },
        "providers": {
            "llm_provider": llm_provider,
            "llm_model": llm_model,
            "llm_usage_models": llm_usage.get("models", []),
            "stt_provider": stt_provider,
            "stt_model": stt_model,
            "stt_region": stt_region,
            "tts_provider": tts_provider,
            "tts_model": tts_model,
            "tts_usage_models": tts_usage.get("models", []),
        },
        "notes": [
            "All values are stored in INR.",
            "LLM token usage is exact when Pipecat usage metrics are available.",
            "Cartesia TTS characters are exact when Pipecat usage metrics are available.",
            "Azure Speech cost uses actual streamed audio seconds and the configured regional S1 rate.",
        ],
    }

    if total > 0:
        logger.info(
            f"Cost calculation: {minutes:.2f}min => INR {total} "
            f"(llm={breakdown['llm']}, stt={breakdown['stt']}, "
            f"tts={breakdown['tts']}, telephony={breakdown['telephony']})"
        )
    else:
        logger.warning(
            "Cost is INR 0 - check cost env vars: "
            f"COST_LLM_INPUT_PER_1M_TOKENS={llm_input_rate}, "
            f"COST_LLM_OUTPUT_PER_1M_TOKENS={llm_output_rate}, "
            f"COST_LLM_SEARCH_CALL={llm_search_call_rate}, "
            f"COST_STT_PER_MIN={stt_rate}, "
            f"COST_TTS_PER_1K_CHARS={tts_rate_per_1k_chars}, "
            f"COST_TELEPHONY_PER_MIN={telephony_rate}"
        )

    return total, breakdown


def build_farewell_message(system_prompt: str, assistant_name: str) -> str:
    base = f"Thank you for contacting {assistant_name}. Goodbye."
    api_key = os.getenv("GROQ_API_KEY")
    if not api_key:
        return base

    try:
        url = "https://api.groq.com/openai/v1/chat/completions"
        model = os.getenv("FAREWELL_LLM_MODEL", "llama-3.3-70b-versatile")
        headers = {
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        }
        prompt = (
            "You are customizing the closing line for a voice customer support agent.\n"
            "Given the agent's system prompt, write ONE friendly farewell sentence the agent can say to end the call.\n"
            "Requirements:\n"
            "- 1 sentence only, 8-20 words.\n"
            "- Warm, professional, and polite.\n"
            "- Mention the brand or context if obvious from the system prompt.\n"
            "- No markdown, no quotes, no extra commentary.\n"
        )
        payload = {
            "model": model,
            "messages": [
                {"role": "system", "content": prompt},
                {
                    "role": "user",
                    "content": f"System prompt:\n{system_prompt}\n\nAssistant display name: {assistant_name}",
                },
            ],
            "temperature": 0.4,
            "max_tokens": 32,
        }
        with httpx.Client(timeout=5.0) as client:
            r = client.post(url, json=payload, headers=headers)
            r.raise_for_status()
            data = r.json()
            text = (
                data.get("choices", [{}])[0]
                .get("message", {})
                .get("content", "")
                .strip()
            )
            if text and len(text.split()) <= 25 and "\n" not in text:
                return text
    except Exception as e:
        logger.warning(f"Failed to build dynamic farewell: {e}")

    return base


def fetch_assistant_config(assistant_id: str) -> dict | None:
    """Fetch assistant config from Sprio backend synchronously at startup."""
    if not assistant_id:
        return None
    try:
        with httpx.Client(timeout=5.0) as client:
            r = client.get(f"{BACKEND_URL}/api/agent-config/assistant/{assistant_id}")
            if r.status_code == 200:
                cfg = r.json()
                logger.info(f"âœ… Loaded assistant: {cfg.get('name')} (id={assistant_id})")
                return cfg
            else:
                logger.warning(f"Assistant {assistant_id} not found: {r.status_code}")
    except Exception as e:
        logger.warning(f"Could not fetch config from backend: {e}")
    return None


async def fetch_assistant_config_async(assistant_id: str) -> dict | None:
    """Fetch assistant config from Sprio backend asynchronously."""
    if not assistant_id:
        return None
    try:
        async with httpx.AsyncClient(timeout=5.0) as client:
            r = await client.get(f"{BACKEND_URL}/api/agent-config/assistant/{assistant_id}")
            if r.status_code == 200:
                cfg = r.json()
                logger.info(f"âœ… Loaded assistant: {cfg.get('name')} (id={assistant_id})")
                return cfg
            logger.warning(f"Assistant {assistant_id} not found: {r.status_code}")
    except Exception as e:
        logger.warning(f"Could not fetch config from backend: {e}")
    return None


async def get_rag_context(query: str, assistant_id: str, 
                           backend_url: str, api_key: str) -> str:
    """Fetch relevant knowledge base context for a query."""
    try:
        async with httpx.AsyncClient() as client:
            response = await client.post(
                f"{backend_url}/api/v1/knowledge/search",
                json={
                    "assistantId": assistant_id,
                    "query": query,
                    "limit": 5
                },
                headers={"Authorization": f"Bearer {api_key}"},
                timeout=3.0
            )
            if response.status_code == 200:
                data = response.json()
                return data.get("context", "")
    except Exception as e:
        logger.warning(f"RAG context fetch failed: {e}")
    return ""


async def initiate_call(
    assistant_id: str,
    assistant_name: str,
    caller: str = "browser-webrtc",
    phone_number: str = "web-test",
    call_direction: str = "inbound",
) -> str:
    """Initiate a call and let the backend own credit reservation."""
    try:
        payload = {
            "assistant_id": assistant_id,
            "assistant_name": assistant_name,
            "caller": caller,
            "phone_number": phone_number,
            "call_direction": call_direction,
        }
        
        logger.info(f"ðŸš€ Initiating call for assistant {assistant_id}")
        logger.info(f"ðŸ“¤ Request payload: {payload}")
        
        async with httpx.AsyncClient(timeout=10.0) as client:
            resp = await client.post(f"{BACKEND_URL}/api/calls/initiate", json=payload)
            
            logger.info(f"ðŸ“¥ Response status: {resp.status_code}")
            logger.info(f"ðŸ“¥ Response body: {resp.text}")
            
            if resp.status_code in (200, 201):
                call_data = resp.json()
                call_id = call_data.get("id")
                reserved_credits = "backend-managed"
                
                if call_id:
                    active_calls[call_id] = {
                        "start_time": time.time(),
                        "assistant_id": assistant_id,
                        "assistant_name": assistant_name,
                        "call_direction": call_direction,
                        "phone_number": phone_number,
                        "caller": caller,
                    }
                    
                    logger.info(f"âœ… Call initiated successfully: {call_id} (reserved {reserved_credits} credits)")
                    return call_id
                else:
                    logger.error("âŒ No call_id in response")
            else:
                logger.error(f"âŒ Call initiation failed: {resp.status_code} - {resp.text}")
                
    except Exception as e:
        logger.error(f"âŒ Call initiation failed: {e}")
        
    return None


async def resolve_vodafone_inbound_assistant(
    provider_dni: str | None,
    provider_cli: str | None,
    provider_call_id: str | None,
) -> dict | None:
    """Resolve a Vodafone inbound call to an assistant using backend routing."""
    if not provider_dni:
        return None

    payload = {
        "dni": provider_dni,
        "cli": provider_cli,
        "vodafone_call_id": provider_call_id,
    }

    try:
        async with httpx.AsyncClient(timeout=10.0) as client:
            resp = await client.post(f"{BACKEND_URL}/api/vodafone/inbound-resolve", json=payload)
            if resp.status_code == 200:
                return resp.json()
            logger.warning(
                f"[Vodafone Inbound] resolve failed: status={resp.status_code} body={resp.text[:500]}"
            )
    except Exception as e:
        logger.warning(f"[Vodafone Inbound] resolve exception: {e}")
    return None

async def complete_call(call_id: str, duration: float, transcript: list, config: dict = None, extra_metadata: dict = None):
    """Complete a call and finalize credit consumption."""
    try:
        if call_id not in active_calls:
            logger.error(
                f"âŒ [complete_call] call_id={call_id} NOT in active_calls. "
                f"Active calls: {list(active_calls.keys())}. "
                f"Call will NOT be logged to backend."
            )
            return False
            
        call_info = active_calls[call_id]
        if call_info.get("completion_started"):
            logger.info(f"[complete_call] completion already in progress for call_id={call_id}")
            return True
        call_info["completion_started"] = True
        sentiment = None
        cost, cost_breakdown = compute_cost_breakdown(
            duration,
            transcript=transcript,
            config=config,
            usage_metrics=call_info.get("usage_metrics"),
        )
        
        metadata_payload = {
            "costBreakdown": cost_breakdown,
        }
        if call_info.get("transfer"):
            metadata_payload["transfer"] = call_info["transfer"]
        if extra_metadata:
            metadata_payload.update(extra_metadata)

        payload = {
            "duration": int(duration),
            "status": call_info.get("final_status", "completed"),
            "cost": cost,
            "sentiment": sentiment,
            "transcript": transcript,
            "call_direction": call_info.get("call_direction", "outbound"),
            "metadata": metadata_payload,
        }
        if call_info.get("recording_url"):
            payload["recording_url"] = call_info["recording_url"]

        logger.info(
            f"ðŸ§¾ Full call transcript ({len(transcript)} turns): "
            f"{json.dumps(transcript, ensure_ascii=False)}"
        )
        
        logger.info(f"ðŸ Completing call {call_id} (duration: {duration}s)")
        logger.info(f"ðŸ“¤ Sending completion request to: {BACKEND_URL}/api/calls/{call_id}/complete")
        logger.info(f"ðŸ“¤ Request payload: {payload}")
        
        async with httpx.AsyncClient(timeout=10.0) as client:
            resp = await client.post(f"{BACKEND_URL}/api/calls/{call_id}/complete", json=payload)
            
            logger.info(f"ðŸ“¥ Response status: {resp.status_code}")
            if resp.status_code not in (200, 201):
                logger.error(f"âŒ Completion request failed with status {resp.status_code}")
                logger.error(f"ðŸ“¥ Response body: {resp.text}")
                return False
                
            result = resp.json()
            logger.info(f"ðŸ“¥ Response body: {result}")
            
            credits_consumed = result.get("creditResult", {}).get("creditsConsumed", 0)
            credits_returned = result.get("creditResult", {}).get("creditsReturned", 0)
            
            logger.info(f"âœ… Call completed successfully:")
            logger.info(f"   - Credits consumed: {credits_consumed}")
            logger.info(f"   - Credits returned: {credits_returned}")
            logger.info(f"   - Duration: {duration}s")
            logger.info(f"   - Cost: ${cost}")
            
            # Completion can race across the WS stop path and the pipeline finally path.
            # Make removal idempotent so a duplicate completion does not raise KeyError
            # after the backend has already accepted the completion payload.
            _removed_call = active_calls.pop(call_id, None)
            if _removed_call is None:
                logger.info(
                    f"[complete_call] active_calls already cleared for call_id={call_id}"
                )
            
            # Trigger AI analysis if config is available
            if config:
                await trigger_ai_analysis(call_id, config, client)
            
            return True
    except Exception as e:
        logger.error(f"âŒ Exception during call completion: {e}")
        try:
            if call_id in active_calls:
                active_calls[call_id]["completion_started"] = False
        except Exception:
            pass
        return False

async def cancel_call(call_id: str, reason: str = "User cancelled"):
    """Cancel a call and let the backend release any reserved credits."""
    try:
        if call_id not in active_calls:
            logger.warning(f"âš ï¸ Call {call_id} not found in active calls")
            return False
            
        logger.info(f"âŒ Cancelling call {call_id}: {reason}")
        
        async with httpx.AsyncClient(timeout=10.0) as client:
            resp = await client.post(f"{BACKEND_URL}/api/calls/{call_id}/cancel", json={
                "reason": reason
            })
            
            if resp.status_code in (200, 201):
                result = resp.json()
                credits_released = result.get("creditResult", {}).get("creditsReleased", 0)
                
                logger.info(f"âœ… Call cancelled successfully:")
                logger.info(f"   - Credits released: {credits_released}")
                logger.info(f"   - Reason: {reason}")
                
                # Cancellation can also be reached from more than one teardown path.
                active_calls.pop(call_id, None)
                
                return True
            else:
                logger.error(f"âŒ Call cancellation failed: {resp.status_code} - {resp.text}")
                return False
                
    except Exception as e:
        logger.error(f"âŒ Exception during call cancellation: {e}")
        return False

def _normalize_cli(cli: str | None) -> str | None:
    """Strip country code prefix so Vodafone gets a 10-digit CLI."""
    if not cli:
        return None
    digits = ''.join(c for c in cli if c.isdigit())
    if len(digits) == 12 and digits.startswith('91'):
        digits = digits[2:]
    return digits or None

async def transfer_outbound_call(call_id: str, destination_number: str, cli_override: str | None = None):
    """
    Transfer an active Vodafone call to a human agent using the exit event.

    Vodafone-confirmed flow:
    1. Store destination_number in pending_transfers[room_id] BEFORE sending exit.
    2. Send {"event": "exit", "room_id": "..."} over the active WebSocket.
    3. Vodafone terminates AI streaming, keeps A-party on the call.
    4. Vodafone calls our /api/vodafone/transfer-destination endpoint to fetch
       the B-party number, then dials them and connects to A-party.
    """
    call_info = active_calls.get(call_id)
    if not call_info:
        return {
            "ok": False,
            "error": "active_call_not_found",
            "message": f"No active call found for {call_id}",
        }

    room_id = call_info.get("room_id")
    ws = active_websockets.get(call_id)

    if not room_id:
        return {
            "ok": False,
            "error": "no_room_id",
            "message": "room_id not yet received from Vodafone - call may not be active yet",
        }

    if not ws:
        return {
            "ok": False,
            "error": "no_active_websocket",
            "message": "No active WebSocket for this call - call may have already ended",
        }

    # Extract the Vodafone numeric call_id from room_id.
    # room_id format: "HB_{vodafone_call_id}_{x}_{y}" e.g. "HB_621399055_945_3628380"
    # Vodafone sends this numeric call_id in the transfer-destination callback.
    vodafone_numeric_id = room_id.split('_')[1] if room_id and '_' in room_id else room_id
    cli = call_info.get("vodafone_cli") or os.getenv("VODAFONE_CLI", "")

    try:
        # Store BEFORE sending exit - Vodafone may call the callback immediately.
        # Keyed by the numeric Vodafone call_id since that's what Vodafone sends
        # in the transfer-destination request body as "call_id".
        pending_transfers[vodafone_numeric_id] = {
            "destination_number": str(destination_number),
            "cli": str(cli),
        }
        logger.info(
            f"[Transfer] Stored pending transfer: vodafone_call_id={vodafone_numeric_id} â†’ {destination_number}, cli={cli}"
        )

        exit_payload = {
            "event": "exit",
            "room_id": room_id,
        }
        await ws.send_text(json.dumps(exit_payload))
        logger.info(
            f"[Transfer] Sent exit event for call_id={call_id}, room_id={room_id}, payload={json.dumps(exit_payload)}"
        )
        try:
            ack = await asyncio.wait_for(ws.receive_text(), timeout=5.0)
            logger.info(f"[Transfer] Vodafone exit event ACK: {ack}")
        except asyncio.TimeoutError:
            logger.warning(f"[Transfer] No ACK from Vodafone within 5s (may be normal if they close immediately)")
        except Exception as ack_err:
            logger.warning(f"[Transfer] ACK receive error (non-fatal): {ack_err}")
    except Exception as e:
        pending_transfers.pop(vodafone_numeric_id, None)  # rollback
        logger.error(f"[Transfer] Failed to send exit event: {e}")
        return {
            "ok": False,
            "error": "exit_event_failed",
            "message": f"Failed to send exit event over WebSocket: {e}",
        }

    call_info["final_status"] = "transferred"
    call_info["transfer"] = {
        "destination_number": str(destination_number),
        "room_id": room_id,
        "vodafone_call_id": vodafone_numeric_id,
        "requested_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
    }

    return {
        "ok": True,
        "call_id": call_id,
        "room_id": room_id,
        "vodafone_call_id": vodafone_numeric_id,
        "destination_number": str(destination_number),
        "message": "Exit event sent - Vodafone will call /api/vodafone/transfer-destination to fetch B-party number",
    }


async def _persist_provider_context(
    call_id: str,
    vodafone_call_id: str | None = None,
    vodafone_cli: str | None = None,
    source: str = "voice-agent",
    metadata: dict | None = None,
    start_streaming: bool = False,
):
    """Persist Vodafone provider identifiers to the backend and local cache."""
    if not call_id:
        return False

    payload = {
        "vodafone_call_id": vodafone_call_id,
        "vodafone_cli": vodafone_cli,
        "start_streaming": bool(start_streaming),
        "metadata": {
            **(metadata or {}),
            "provider_call_id": vodafone_call_id,
            "provider_cli": vodafone_cli,
            "provider_context_source": source,
        },
    }

    try:
        async with httpx.AsyncClient(timeout=10.0) as client:
            resp = await client.patch(
                f"{BACKEND_URL}/api/calls/{call_id}/provider-context",
                json=payload,
            )
            if resp.status_code in (200, 201):
                local_call = active_calls.get(call_id)
                if local_call is not None:
                    if vodafone_call_id:
                        local_call["vodafone_call_id"] = vodafone_call_id
                    if vodafone_cli:
                        local_call["vodafone_cli"] = vodafone_cli
                logger.info(
                    f"[Provider Context] Synced call_id={call_id} "
                    f"vodafone_call_id={vodafone_call_id} vodafone_cli={vodafone_cli}"
                )
                return True

            logger.warning(
                f"[Provider Context] Sync failed for call_id={call_id}: "
                f"{resp.status_code} {resp.text}"
            )
    except Exception as e:
        logger.warning(f"[Provider Context] Sync exception for call_id={call_id}: {e}")

    return False

