async def fetch_assistant_config_async(assistant_id: str) -> dict | None:
    """Fetch assistant config from Sprio backend asynchronously."""
    if not assistant_id:
        return None
    try:
        response = await _backend_request(
            "GET",
            f"/api/agent-config/assistant/{assistant_id}",
            timeout=httpx.Timeout(5.0, connect=5.0),
        )
        if response.status_code == 200:
            cfg = response.json()
            logger.info(f"Loaded assistant: {cfg.get('name')} (id={assistant_id})")
            return cfg
        logger.warning(f"Assistant {assistant_id} not found: {response.status_code}")
    except Exception as e:
        logger.warning(f"Could not fetch config from backend: {e}")
    return None


async def _prewarm_opening_audio_for_assistant(
    assistant_id: str,
    call_id: str | None = None,
) -> list[bytes] | None:
    try:
        cfg = await fetch_assistant_config_async(assistant_id)
        if not cfg:
            return None
        cfg_first = cfg.get("firstMessage")
        if isinstance(cfg_first, str) and cfg_first.strip():
            greeting = re.sub(r"\s+", " ", cfg_first).strip()
        else:
            greeting = DEFAULT_GREETING
        voice_id = cfg.get("ttsVoiceId") or DEFAULT_VOICE_ID
        stt_language = cfg.get("sttLanguage") or DEFAULT_STT_LANGUAGE
        voice_speed = float(cfg.get("voiceSpeed", 0.7))
        tts_lang = _resolve_tts_language(stt_language)
        chunks = await _get_or_build_opening_audio_chunks(voice_id, greeting, tts_lang, voice_speed)
        if call_id:
            _payload = _outbound_call_store.get(call_id)
            if _payload is not None:
                _payload["prewarmed_opening_pcm"] = list(chunks)
        logger.info(
            f"[Outbound Pipeline] Opening prewarmed for assistant={assistant_id} "
            f"call_id={call_id or '-'} chunks={len(chunks)}"
        )
        return list(chunks)
    except Exception as exc:
        logger.warning(
            f"[Outbound Pipeline] Opening prewarm skipped for assistant={assistant_id} "
            f"call_id={call_id or '-'}: {exc}"
        )
    return None


async def get_rag_context(query: str, assistant_id: str, backend_url: str, api_key: str) -> str:
    """Fetch relevant knowledge base context for a query."""
    try:
        async with httpx.AsyncClient(timeout=httpx.Timeout(3.0, connect=3.0), limits=DEFAULT_HTTP_LIMITS) as client:
            response = await client.post(
                f"{backend_url}/api/v1/knowledge/search",
                json={"assistantId": assistant_id, "query": query, "limit": 5},
                headers={"Authorization": f"Bearer {api_key}"},
            )
        if response.status_code == 200:
            data = response.json()
            return data.get("context", "")
    except Exception as e:
        logger.warning(f"RAG context fetch failed: {e}")
    return ""


async def initiate_call(
    assistant_id: str,
    assistant_name: str,
    caller: str = "browser-webrtc",
    phone_number: str = "web-test",
    call_direction: str = "inbound",
) -> str:
    """Initiate a call and let the backend own credit reservation."""
    try:
        payload = {
            "assistant_id": assistant_id,
            "assistant_name": assistant_name,
            "caller": caller,
            "phone_number": phone_number,
            "call_direction": call_direction,
        }

        logger.info(f"Initiating call for assistant {assistant_id}")
        logger.info(f"[Call Initiate] payload={_redact_sensitive_value(payload)}")

        resp = await _backend_request("POST", "/api/calls/initiate", json_body=payload)
        logger.info(f"[Call Initiate] response_status={resp.status_code}")

        if resp.status_code in (200, 201):
            call_data = resp.json()
            call_id = call_data.get("id")
            if call_id:
                active_calls[call_id] = {
                    "start_time": time.time(),
                    "assistant_id": assistant_id,
                    "assistant_name": assistant_name,
                    "call_direction": call_direction,
                    "phone_number": phone_number,
                    "caller": caller,
                }
                logger.info(f"Call initiated successfully: {call_id}")
                return call_id
            logger.error("No call_id in initiate response")
        else:
            logger.error(f"Call initiation failed: {resp.status_code} - {resp.text[:500]}")
    except Exception as e:
        logger.error(f"Call initiation failed: {e}")
    return None


async def resolve_vodafone_inbound_assistant(
    provider_dni: str | None,
    provider_cli: str | None,
    provider_call_id: str | None,
) -> dict | None:
    """Resolve a Vodafone inbound call to an assistant using backend routing."""
    if not provider_dni:
        return None

    payload = {
        "dni": provider_dni,
        "cli": provider_cli,
        "vodafone_call_id": provider_call_id,
    }

    try:
        resp = await _backend_request("POST", "/api/vodafone/inbound-resolve", json_body=payload)
        if resp.status_code == 200:
            return resp.json()
        logger.warning(f"[Vodafone Inbound] resolve failed: status={resp.status_code} body={resp.text[:500]}")
    except Exception as e:
        logger.warning(f"[Vodafone Inbound] resolve exception: {e}")
    return None


async def complete_call(call_id: str, duration: float, transcript: list, config: dict = None, extra_metadata: dict = None):
    """Complete a call and finalize credit consumption."""
    try:
        if call_id not in active_calls:
            logger.error(
                f"[complete_call] call_id={call_id} NOT in active_calls. "
                f"Active calls: {list(active_calls.keys())}. "
                f"Call will NOT be logged to backend."
            )
            return False

        call_info = active_calls[call_id]
        if call_info.get("completion_started"):
            logger.info(f"[complete_call] completion already in progress for call_id={call_id}")
            return True

        call_info["completion_started"] = True
        sentiment = None
        cost, cost_breakdown = compute_cost_breakdown(
            duration,
            transcript=transcript,
            config=config,
            usage_metrics=call_info.get("usage_metrics"),
        )

        metadata_payload = {"costBreakdown": cost_breakdown}
        if call_info.get("transfer"):
            metadata_payload["transfer"] = call_info["transfer"]
        if extra_metadata:
            metadata_payload.update(extra_metadata)

        payload = {
            "duration": int(duration),
            "status": call_info.get("final_status", "completed"),
            "cost": cost,
            "sentiment": sentiment,
            "transcript": transcript,
            "call_direction": call_info.get("call_direction", "outbound"),
            "metadata": metadata_payload,
        }

        _log_transcript_if_enabled("[Call Complete]", transcript)
        logger.info(f"Completing call {call_id} (duration={duration}s)")
        logger.info(f"[Call Complete] payload={_redact_sensitive_value(payload)}")

        resp = await _backend_request("POST", f"/api/calls/{call_id}/complete", json_body=payload)
        logger.info(f"[Call Complete] response_status={resp.status_code}")
        if resp.status_code not in (200, 201):
            logger.error(f"Completion request failed with status {resp.status_code}: {resp.text[:500]}")
            return False

        result = resp.json()
        credit_result = result.get("creditResult", {})
        logger.info(
            f"Call completed successfully: credits_consumed={credit_result.get('creditsConsumed', 0)} "
            f"credits_returned={credit_result.get('creditsReturned', 0)} duration={duration}s cost=${cost}"
        )

        _removed_call = active_calls.pop(call_id, None)
        if _removed_call is None:
            logger.info(f"[complete_call] active_calls already cleared for call_id={call_id}")

        if config:
            async with httpx.AsyncClient(timeout=DEFAULT_HTTP_TIMEOUT, limits=DEFAULT_HTTP_LIMITS) as client:
                await trigger_ai_analysis(call_id, config, client)

        return True
    except Exception as e:
        logger.error(f"Exception during call completion: {e}")
        try:
            if call_id in active_calls:
                active_calls[call_id]["completion_started"] = False
        except Exception:
            pass
        return False


async def upload_call_recording(call_id: str, wav_bytes: bytes | None) -> str | None:
    if not call_id or not wav_bytes:
        return None
    try:
        payload = {
            "mime_type": "audio/wav",
            "audio_base64": base64.b64encode(wav_bytes).decode("ascii"),
        }
        resp = await _backend_request("POST", f"/api/calls/{call_id}/recording", json_body=payload)
        if resp.status_code not in (200, 201):
            logger.warning(f"[CallRecording] upload failed status={resp.status_code} body={resp.text[:300]}")
            return None
        data = resp.json()
        recording_url = data.get("recording_url") or data.get("recordingUrl")
        if recording_url:
            logger.info(f"[CallRecording] uploaded call_id={call_id} bytes={len(wav_bytes)}")
        return recording_url
    except Exception as exc:
        logger.warning(f"[CallRecording] upload exception call_id={call_id}: {exc}")
        return None


async def cancel_call(call_id: str, reason: str = "User cancelled"):
    """Cancel a call and let the backend release any reserved credits."""
    try:
        if call_id not in active_calls:
            logger.warning(f"Call {call_id} not found in active calls")
            return False

        logger.info(f"Cancelling call {call_id}: {reason}")
        resp = await _backend_request("POST", f"/api/calls/{call_id}/cancel", json_body={"reason": reason})

        if resp.status_code in (200, 201):
            result = resp.json()
            credits_released = result.get("creditResult", {}).get("creditsReleased", 0)
            logger.info(f"Call cancelled successfully: credits_released={credits_released} reason={reason}")
            active_calls.pop(call_id, None)
            return True

        logger.error(f"Call cancellation failed: {resp.status_code} - {resp.text[:500]}")
        return False
    except Exception as e:
        logger.error(f"Exception during call cancellation: {e}")
        return False


