async def enforce_max_duration(task, max_secs: int, stop_event: asyncio.Event = None):
    """Wait for max_secs (or stop_event) and then end the call by queuing an EndFrame."""
    if stop_event:
        try:
            await asyncio.wait_for(stop_event.wait(), timeout=max_secs)
            # stop_event fired naturally (ws_reader already queued EndFrame) - nothing to do
            return
        except asyncio.TimeoutError:
            pass  # fell through: max duration actually reached
    else:
        await asyncio.sleep(max_secs)
    logger.info(f"ðŸš« Max call duration ({max_secs}s) reached - ending call")
    await task.queue_frame(EndFrame())


