# â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

class RAGContextInjector(FrameProcessor):
    """Injects RAG context into system prompt before LLM processes user input."""
    def __init__(self, assistant_id: str, backend_url: str, context_ref: list):
        super().__init__()
        self.assistant_id = assistant_id
        self.backend_url = backend_url
        self._context_ref = context_ref  # mutable reference to LLMContext

    async def process_frame(self, frame, direction):
        if isinstance(frame, TranscriptionFrame) and frame.text:
            logger.info(f"[RAG] Fetching context for: {frame.text[:50]}")
            asyncio.create_task(self._fetch_and_inject(frame.text))
        await super().process_frame(frame, direction)
        await self.push_frame(frame, direction)

    async def _fetch_and_inject(self, query: str):
        try:
            import httpx as _hx
            async with _hx.AsyncClient(timeout=10.0) as client:  # 10 s - CPU embedding can take ~2-3 s
                resp = await client.post(
                    f"{self.backend_url}/api/knowledge/internal/search",
                    json={
                        "assistantId": self.assistant_id,
                        "query": query,
                        "limit": 3
                    }
                )
                if resp.status_code == 200:
                    rag_context = resp.json().get("context", "")
                    if rag_context and self._context_ref:
                        context = self._context_ref[0]
                        messages = context.messages
                        for msg in messages:
                            if msg.get("role") == "system":
                                import re
                                base = re.sub(
                                    r'\n\nKNOWLEDGE BASE CONTEXT.*$',
                                    '',
                                    msg["content"],
                                    flags=re.DOTALL
                                )
                                msg["content"] = (
                                    base +
                                    f"\n\nKNOWLEDGE BASE CONTEXT "
                                    f"(use this to answer accurately):\n{rag_context}"
                                )
                                logger.info(f"[RAG] Injected {len(rag_context)} chars for: {query[:40]}")
                                break
                else:
                    logger.warning(f"[RAG] Search returned {resp.status_code}: {resp.text[:100]}")
        except Exception as e:
            logger.warning(f"[RAG] Context fetch failed: {type(e).__name__}: {e}")



