def _pronunciation_name_key(text: str) -> str:
    return re.sub(r"[^a-z0-9]+", " ", (text or "").strip().lower()).strip()


def _contains_tamil(text: str | None) -> bool:
    return bool(text) and any("\u0b80" <= ch <= "\u0bff" for ch in text)


def _locality_name_to_tamil(text: str) -> str:
    """Return Tamil-script rendering for a known Chennai locality name."""
    if not text:
        return text

    parts = re.findall(r"[A-Za-z0-9&']+|[-–—/.,()]", text)
    if not parts:
        return text

    rendered: list[str] = []
    for part in parts:
        lower = part.strip("'").lower()
        if not lower:
            continue
        if part in {"-", "–", "—", "/"}:
            rendered.append(part)
            continue
        if part in {".", ",", "(", ")"}:
            rendered.append(part)
            continue
        if lower in {"and", "&"}:
            rendered.append("மற்றும்")
            continue
        rendered.append(_TAMIL_LOCALITY_WORDS.get(lower, part))

    text_out = " ".join(rendered)
    text_out = re.sub(r"\s+([.,)])", r"\1", text_out)
    text_out = re.sub(r"([(])\s+", r"\1", text_out)
    text_out = re.sub(r"\s*([-–—/])\s*", r" \1 ", text_out)
    return re.sub(r"\s+", " ", text_out).strip()


def _tts_replacement_for_locality(canonical_name: str, override: dict | None = None) -> str:
    override = override or {}
    explicit = override.get("tts_ipa") or override.get("tts_sounds_like")
    if _contains_tamil(explicit):
        return str(explicit)
    return _locality_name_to_tamil(canonical_name)


def _score_catalog_name(name: str) -> tuple[int, int, int]:
    words = (name or "").split()
    titled_words = sum(1 for word in words if word[:1].isupper())
    title_bonus = 1 if name == name.title() else 0
    digit_penalty = -sum(ch.isdigit() for ch in name)
    return (titled_words, title_bonus, digit_penalty)


def _extract_unique_chennai_catalog_names() -> tuple[list[str], set[str]]:
    try:
        catalog_path = Path(__file__).resolve().parent.parent / "backend" / "src" / "data" / "jll-catalog.json"
        with catalog_path.open("r", encoding="utf-8") as fh:
            data = json.load(fh)
        chennai = (((data or {}).get("by_city") or {}).get("Chennai") or {})
        micro_markets = [str(x).strip() for x in (chennai.get("micro_markets") or []) if str(x).strip()]
        locations = [str(x).strip() for x in (chennai.get("locations") or []) if str(x).strip()]
    except Exception as exc:
        logger.warning(f"[Pronunciation] Failed to load Chennai catalog: {exc}")
        return [], set()

    preferred_by_key: dict[str, str] = {}
    for raw_name in locations + micro_markets:
        key = _pronunciation_name_key(raw_name)
        if not key:
            continue
        current = preferred_by_key.get(key)
        if current is None or _score_catalog_name(raw_name) > _score_catalog_name(current):
            preferred_by_key[key] = raw_name

    micro_market_keys = {_pronunciation_name_key(name) for name in micro_markets if _pronunciation_name_key(name)}
    names = sorted(preferred_by_key.values(), key=lambda value: (_pronunciation_name_key(value), value))
    return names, micro_market_keys


def _should_include_default_keyword(name: str, *, is_micro_market: bool) -> bool:
    if not name or len(name) < 3:
        return False
    if any(ch.isdigit() for ch in name):
        return False
    if re.fullmatch(r"[A-Z]{2,4}", name):
        return True
    tokens = {token.lower() for token in re.findall(r"[A-Za-z]+", name)}
    if is_micro_market:
        return True
    if tokens & _CHENNAI_STT_GENERIC_SKIP_TOKENS:
        return False
    return len(tokens) <= 3


def _default_keywords_for_name(name: str, *, is_micro_market: bool) -> list[str]:
    if not _should_include_default_keyword(name, is_micro_market=is_micro_market):
        return []
    weight = 6 if is_micro_market else 4
    keywords = [f"{name}:{weight}"]
    if re.fullmatch(r"[A-Z]{2,4}", name):
        spaced = " ".join(name)
        keywords.append(f"{spaced}:{max(weight - 1, 3)}")
    return keywords


def _build_chennai_pronunciation_entries() -> dict[str, dict]:
    catalog_names, micro_market_keys = _extract_unique_chennai_catalog_names()
    entries: dict[str, dict] = {}

    for canonical_name in catalog_names:
        key = _pronunciation_name_key(canonical_name)
        override = _CHENNAI_PRONUNCIATION_OVERRIDES.get(canonical_name, {})
        aliases = []
        for alias in override.get("alias_spellings", []):
            alias = str(alias).strip()
            if alias:
                aliases.append(alias)
        entry = {
            "canonical_name": canonical_name,
            "tts_sounds_like": _tts_replacement_for_locality(canonical_name, override),
            "tts_ipa": None,
            "stt_keywords": list(override.get("stt_keywords", [])),
            "alias_spellings": aliases,
            "is_micro_market": key in micro_market_keys,
        }
        entry["stt_keywords"].extend(
            _default_keywords_for_name(canonical_name, is_micro_market=entry["is_micro_market"])
        )
        entries[key] = entry

    for canonical_name, override in _CHENNAI_PRONUNCIATION_OVERRIDES.items():
        key = _pronunciation_name_key(canonical_name)
        if not key or key in entries:
            continue
        entries[key] = {
            "canonical_name": canonical_name,
            "tts_sounds_like": _tts_replacement_for_locality(canonical_name, override),
            "tts_ipa": None,
            "stt_keywords": list(override.get("stt_keywords", [])),
            "alias_spellings": [
                str(alias).strip()
                for alias in override.get("alias_spellings", [])
                if str(alias).strip()
            ],
            "is_micro_market": key in micro_market_keys,
        }

    return entries


_CHENNAI_PRONUNCIATION_ENTRIES = _build_chennai_pronunciation_entries()


def _variant_to_name_pattern(variant: str) -> str:
    parts = [re.escape(part) for part in re.split(r"\s+", variant.strip()) if part]
    return r"\s+".join(parts) if parts else re.escape(variant)


def _build_chennai_tts_patterns() -> list[tuple[re.Pattern, str]]:
    patterns: list[tuple[re.Pattern, str]] = []
    for entry in _CHENNAI_PRONUNCIATION_ENTRIES.values():
        replacement = entry.get("tts_ipa") or entry.get("tts_sounds_like") or entry["canonical_name"]
        if replacement == entry["canonical_name"]:
            continue
        variants = {entry["canonical_name"], *entry.get("alias_spellings", [])}
        variants = {variant.strip() for variant in variants if variant and variant.strip()}
        if not variants:
            continue
        variant_patterns = sorted((_variant_to_name_pattern(variant) for variant in variants), key=len, reverse=True)
        pattern = re.compile(rf"(?<!\w)(?:{'|'.join(variant_patterns)})(?!\w)", re.IGNORECASE)
        patterns.append((pattern, replacement))
    patterns.sort(key=lambda item: len(item[0].pattern), reverse=True)
    return patterns


_CHENNAI_TTS_PATTERNS = _build_chennai_tts_patterns()


def _build_deepgram_keywords() -> list[str]:
    weighted_keywords: dict[str, tuple[str, int]] = {}
    for entry in _CHENNAI_PRONUNCIATION_ENTRIES.values():
        for raw_keyword in entry.get("stt_keywords", []):
            keyword = str(raw_keyword).strip()
            if not keyword:
                continue
            phrase, weight = keyword, 5
            if ":" in keyword:
                maybe_phrase, maybe_weight = keyword.rsplit(":", 1)
                if maybe_phrase.strip() and maybe_weight.strip().isdigit():
                    phrase = maybe_phrase.strip()
                    weight = int(maybe_weight.strip())
            dedupe_key = phrase.lower()
            current = weighted_keywords.get(dedupe_key)
            if current is None or weight > current[1]:
                weighted_keywords[dedupe_key] = (phrase, weight)
    ordered = sorted(
        weighted_keywords.values(),
        key=lambda item: (-item[1], len(item[0]), item[0].lower()),
    )
    return [f"{phrase}:{weight}" for phrase, weight in ordered[:_CHENNAI_STT_KEYWORD_LIMIT]]


_DEEPGRAM_CHENNAI_KEYWORDS = _build_deepgram_keywords()


def _build_azure_phrase_bias_phrases() -> list[str]:
    phrases: list[str] = []
    seen: set[str] = set()

    def _add_phrase(value: str):
        phrase = str(value or "").strip()
        if not phrase:
            return
        if ":" in phrase:
            maybe_phrase, maybe_weight = phrase.rsplit(":", 1)
            if maybe_phrase.strip() and maybe_weight.strip().isdigit():
                phrase = maybe_phrase.strip()
        key = phrase.lower()
        if key in seen:
            return
        seen.add(key)
        phrases.append(phrase)

    for phrase in (
        "budget range",
        "lakh",
        "lakhs",
        "50 lakh",
        "fifty lakh",
        "crore",
        "crores",
        "1 crore",
        "one crore",
        "2 crore",
        "two crore",
        "3 crore",
        "three crore",
    ):
        _add_phrase(phrase)

    for city_name in ("Chennai", "Bengaluru", "Hyderabad", "Mumbai"):
        _add_phrase(city_name)

    for phrase in (
        "apartment",
        "apartments",
        "villa",
        "villas",
        "plot",
        "plots",
        "builder floor",
        "penthouse",
        "senior living",
        "row house",
        "villament",
        "duplex apartment",
        "2 BHK",
        "3 BHK",
        "4 BHK",
        "budget",
        "budget range",
        "price",
        "property",
        "project",
        "site visit",
        "callback",
        "lakh",
        "lakhs",
        "50 lakh",
        "fifty lakh",
        "crore",
        "crores",
        "1 crore",
        "one crore",
        "2 crore",
        "two crore",
        "3 crore",
        "three crore",
    ):
        _add_phrase(phrase)

    for raw_keyword in _DEEPGRAM_CHENNAI_KEYWORDS:
        _add_phrase(raw_keyword)

    return phrases[:200]


_AZURE_PHRASE_BIAS_PHRASES = _build_azure_phrase_bias_phrases()


def apply_tamil_name_pronunciations(text: str) -> str:
    if not text:
        return text
    original = text
    for pattern, replacement in _CHENNAI_TTS_PATTERNS:
        text = pattern.sub(lambda _m, repl=replacement: repl, text)
    if text != original:
        logger.debug(f"[TTSLocalityNormalize] {original!r} -> {text!r}")
    return text


def normalize_localities(text: str) -> str:
    """Convert known locality names to Tamil script for TTS."""
    return apply_tamil_name_pronunciations(text)

def _normalize_chennai_locality(text: str) -> str:
    """Return corrected locality name if text matches a known mishear; else text unchanged.
    Only normalizes when the entire input matches a key (case-insensitive, trimmed of
    trailing punctuation). Won't touch multi-word sentences containing these tokens."""
    if not text:
        return text
    key = text.strip().lower().rstrip(".,!?;:")
    return _CHENNAI_LOCALITY_ALIASES.get(key, text)


_AFFIRM_ONLY_RE = re.compile(
    r"^\s*(yes|yes yes|yeah|yeah yes|yes yeah|yep|yup|correct|right|exactly|that's right|thats right|that is right|yes correct|yes right|sure|okay|ok|confirmed)\s*[.!?]?\s*$",
    re.IGNORECASE,
)
_NEGATIVE_ONLY_RE = re.compile(
    r"^\s*(no|nope|no thanks|not now|not needed|not required|not that|not exactly|wrong|incorrect)\s*[.!]?\s*$",
    re.IGNORECASE,
)
_NON_SUBSTANTIVE_ACK_RE = re.compile(
    r"^\s*(?:"
    r"m+\s*h+m+|mm+\s*hmm+|hmm+|hm+|mhm+|mm+|"
    r"uh[- ]?huh|uh[- ]?hm+|huh"
    r")\s*[.!?]?\s*$",
    re.IGNORECASE,
)
_IGNORABLE_SPEAKING_ACK_RE = re.compile(
    r"^\s*(?:"
    r"ok(?:ay)?|oh\s+ok(?:ay)?|ah\s+ok(?:ay)?|right|fine|sure|alright|all\s+right|"
    r"mm+\s*h+m+|mm+\s*hmm+|mhm+|uh[- ]?huh|uh[- ]?hm+|hmm+|hm+|huh|"
    r"yes|yeah|yep|got\s+it"
    r")\s*[.!?]?\s*$",
    re.IGNORECASE,
)

_NUMBER_WORDS = {
    "one": 1, "two": 2, "three": 3, "four": 4, "five": 5,
}

_ORDINAL_POSITION_MAP = {
    "first": 1, "1st": 1,
    "second": 2, "2nd": 2,
    "third": 3, "3rd": 3,
    "fourth": 4, "4th": 4,
    "fifth": 5, "5th": 5,
}

_FLEXIBLE_BUDGET_RE = re.compile(
    r"\b("
    r"any\s+budget|open\s+budget|flexible\s+budget|"
    r"open\s+to\s+any\s+budget|open\s+to\s+all\s+budgets|"
    r"i\s*(?:am|'m)\s+open\s+to\s+any\s+budget|"
    r"no\s+budget\s+preference|budget\s+is\s+flexible|"
    r"anything\s+works|any\s+price\s+range"
    r")\b",
    re.IGNORECASE,
)

_CITYWIDE_LOCATION_RE = re.compile(
    r"\b("
    r"anywhere(?:\s+in\s+chennai)?|any\s+(?:area|location|locality)|"
    r"no\s+(?:area|location|locality)\s+preference|"
    r"open\s+to\s+anywhere|anywhere\s+in\s+the\s+city|"
    r"all\s+over\s+chennai|across\s+chennai"
    r")\b",
    re.IGNORECASE,
)

_RESET_SEARCH_RE = re.compile(
    r"\b("
    r"start\s+over|start\s+again|start\s+from\s+the\s+beginning|"
    r"reset(?:\s+(?:the\s+)??search)?|reset\s+and\s+start\s+again|"
    r"forget\s+(?:everything|previous\s+details|all\s+details)|"
    r"begin\s+again|restart\s+(?:the\s+search|from\s+the\s+beginning)"
    r")\b",
    re.IGNORECASE,
)

_PAGINATION_RESULT_COUNT_RE = re.compile(
    r"\b(?:show|tell|give|list|share|get|need|want)?\s*(?:me\s+)?"
    r"(?:only\s+|just\s+|next\s+|another\s+)?"
    r"(\d+|one|two|three|four|five|six|seven|eight|nine|ten|twelve|fifteen|twenty)\s+"
    r"(?:more\s+)?(?:properties?|results?|listings?|options?|apartments?|villas?|plots?)\b",
    re.IGNORECASE,
)


def _is_flexible_budget_text(text: str) -> bool:
    return bool(_FLEXIBLE_BUDGET_RE.search((text or "").strip()))


def _is_citywide_location_text(text: str) -> bool:
    return bool(_CITYWIDE_LOCATION_RE.search((text or "").strip()))


def _extract_requested_result_count(text: str) -> int | None:
    if not text:
        return None
    match = _PAGINATION_RESULT_COUNT_RE.search(text)
    if not match:
        return None
    raw = (match.group(1) or "").strip().lower()
    raw = str(_NUMBER_WORDS.get(raw, raw))
    try:
        return max(1, int(raw))
    except (TypeError, ValueError):
        return None


_BUDGET_SCOPE_RE = re.compile(
    r"\b(my\s+budget|within\s+my\s+budget|in\s+my\s+budget|under|below|above|"
    r"less\s+than|more\s+than|budget|price\s+range)\b",
    re.IGNORECASE,
)

_TOTAL_INVENTORY_COUNT_RE = re.compile(
    r"\b("
    r"how\s+many|number\s+of|total(?:ly)?|overall|all"
    r")\b.{0,50}\b("
    r"properties?|apartments?|options?|results?|listings?|projects?"
    r")\b|\b("
    r"properties?|apartments?|options?|results?|listings?|projects?"
    r")\b.{0,50}\b("
    r"total(?:ly)?|overall|all|available\s+totally"
    r")\b",
    re.IGNORECASE,
)


def _looks_like_budget_scoped_count_request(text: str) -> bool:
    lower = (text or "").strip().lower()
    if not lower:
        return False
    return bool(_BUDGET_SCOPE_RE.search(lower) or _parse_inr_amounts(lower))


def _looks_like_total_inventory_count_request(text: str) -> bool:
    lower = (text or "").strip().lower()
    if not lower or _looks_like_budget_scoped_count_request(lower):
        return False
    if not _TOTAL_INVENTORY_COUNT_RE.search(lower):
        return False
    return bool(re.search(r"\b(how many|number of|count|total|totally|overall|all|available)\b", lower))


def _looks_like_shortlist_detail_more_request(text: str) -> bool:
    lower = (text or "").strip().lower()
    if not lower:
        return False
    return bool(re.search(
        r"\bmore\s+about\s+(?:the\s+)?"
        r"(?:first|second|third|fourth|fifth|last|1st|2nd|3rd|4th|5th|"
        r"one|two|three|four|five)"
        r"(?:\s+(?:property|project|option|plot|apartment|flat|villa))?\b",
        lower,
        re.IGNORECASE,
    ))


def _classify_priority_user_intent(text: str) -> str:
    lower = (text or "").strip().lower()
    if not lower:
        return "default"
    if _RESET_SEARCH_RE.search(lower):
        return "reset"
    if _looks_like_meta_conversation_question(lower):
        return "meta_question"
    if _looks_like_short_farewell_ack(lower):
        return "closing_ack"
    if _looks_like_shortlist_detail_more_request(lower):
        logger.info(f"[PaginationGuard] overridden reason=detail_request text={text!r}")
        return "default"
    if _extract_requested_result_count(lower) is not None:
        return "pagination"
    if re.search(r"\b(show|tell|list|give|share|find)\b.{0,20}\b(more|next|additional|extra|other|another)\b", lower, re.IGNORECASE):
        return "pagination"
    if re.search(
        r"\b("
        r"next\s+(?:properties?|apartments?|options?|results?)|"
        r"(?:more|other|remaining|necessary)\s+(?:properties?|apartments?|options?|results?)|"
        r"show\s+(?:me\s+)?(?:the\s+)?rest|"
        r"tell\s+(?:me\s+)?(?:the\s+)?rest"
        r")\b",
        lower,
        re.IGNORECASE,
    ):
        return "pagination"
    return "default"

_GATHER_DIRECT_FALLBACK_MARKERS = (
    "tell the user:",
    "sorry, ",
    "i couldn't find",
    "i didnt catch",
    "i didn't catch",
)

_GATHER_AMBIGUITY_RE = re.compile(
    r"\b("
    r"maybe|perhaps|actually|instead|either|or|between|around|approximately|"
    r"not sure|don't know|dont know|no preference|change|different|another|"
    r"except|but|however|rather than|other than"
    r")\b",
    re.IGNORECASE,
)


def _canonical_match_key(text: str) -> str:
    return re.sub(r'[^a-z0-9]+', ' ', (text or '').lower()).strip()


def _best_catalog_candidate(value: str, candidates: list[str], *, cutoff: float = 0.62) -> str | None:
    if not value or not candidates:
        return None
    decision = resolve_fuzzy_name(
        value,
        candidates,
        accept_threshold=max(0.82, cutoff),
        confirm_threshold=cutoff,
    )
    if decision.action in {"accept", "confirm"}:
        return decision.value
    return None


def _catalog_fuzzy_decision(
    value: str,
    candidates: list[str],
    *,
    aliases: dict[str, str] | None = None,
    accept_threshold: float = 0.88,
    confirm_threshold: float = 0.68,
) -> FuzzyNameDecision:
    return resolve_fuzzy_name(
        value,
        candidates,
        aliases=aliases,
        accept_threshold=accept_threshold,
        confirm_threshold=confirm_threshold,
    )


def _resolve_fuzzy_property_name_from_presented(text: str, presented: list[dict]) -> dict | None:
    """Resolve a property name against already spoken shortlist entries."""
    if not text or not presented:
        return None
    name_to_prop: dict[str, dict] = {}
    names: list[str] = []
    for prop in presented:
        name = str(prop.get("name") or prop.get("project_name") or "").strip()
        if not name or name.lower() in {"unknown", "n/a", "-"}:
            continue
        key = _canonical_match_key(name)
        if key not in name_to_prop:
            names.append(name)
            name_to_prop[key] = prop
    decision = resolve_fuzzy_name(text, names, accept_threshold=0.9, confirm_threshold=0.74)
    if decision.action != "accept":
        return None
    return name_to_prop.get(_canonical_match_key(decision.value))


def _is_plot_like_property(data: dict | None, property_ref: dict | None = None) -> bool:
    values: list[str] = []
    for source in (data or {}, property_ref or {}):
        for key in (
            "property_type",
            "searched_property_type",
            "type",
            "category",
            "project_category",
            "asset_type",
        ):
            value = source.get(key) if isinstance(source, dict) else None
            if value:
                values.append(str(value))
    joined = " ".join(values).lower()
    return bool(re.search(r"\bplots?\b", joined))


def _property_type_matches_request(item: dict, requested_type: str | None) -> bool:
    requested = _property_type_singular_label(requested_type)
    if not requested or requested == "property":
        return True
    values = [
        item.get("property_type"),
        item.get("searched_property_type"),
        item.get("type"),
        item.get("category"),
        item.get("project_category"),
    ]
    configs = item.get("configs") or item.get("configurations") or []
    for cfg in configs:
        if isinstance(cfg, dict):
            values.extend([cfg.get("property_type"), cfg.get("type"), cfg.get("category")])
    normalized = {_property_type_singular_label(str(v or "")) for v in values if str(v or "").strip()}
    if not normalized:
        return True
    synonyms = {
        "apartment": {"apartment", "flat"},
        "flat": {"apartment", "flat"},
        "villa": {"villa"},
        "plot": {"plot"},
    }
    explicit_types = set().union(*synonyms.values())
    typed_values = normalized & explicit_types
    if not typed_values:
        return True
    allowed = synonyms.get(requested, {requested})
    return bool(typed_values & allowed)


def _filter_results_for_requested_property_type(items: list[dict], requested_type: str | None) -> list[dict]:
    if not isinstance(items, list):
        return []
    return [item for item in items if isinstance(item, dict) and _property_type_matches_request(item, requested_type)]


def _shortlist_position_recap(text: str, presented: list[dict]) -> str | None:
    if not text or not presented:
        return None
    lower = text.lower()
    if not re.search(r"\b(?:what|which|tell|repeat|say)\b", lower):
        return None
    if not re.search(r"\b(?:first|second|third|fourth|fifth|1st|2nd|3rd|4th|5th)\b", lower):
        return None
    if not re.search(r"\b(?:property|project|name|option)\b", lower):
        return None
    position_words = {
        "first": 1, "1st": 1,
        "second": 2, "2nd": 2,
        "third": 3, "3rd": 3,
        "fourth": 4, "4th": 4,
        "fifth": 5, "5th": 5,
    }
    ordinal_label = {1: "first", 2: "second", 3: "third", 4: "fourth", 5: "fifth"}
    position = None
    for word, number in position_words.items():
        if re.search(rf"\b{word}\b", lower):
            position = number
            break
    if not position:
        return None
    for prop in presented:
        if int(prop.get("position") or 0) == position:
            name = str(prop.get("name") or "").strip()
            if name:
                return f"The {ordinal_label.get(position, str(position))} property name I mentioned was {name}."
    return None


_PROPERTY_COMPARISON_RE = re.compile(
    r"\b(compare|comparison|versus|vs\.?|difference\s+between|which\s+(?:one\s+)?(?:is\s+)?(?:cheaper|lower|better))\b",
    re.IGNORECASE,
)

_RERA_FACT_PATTERN = (
    r"\b(?:rera|re\s*ra|rehra|rerha|reira|reera|rehna)\b"
    r"(?:\s+(?:approved|approval|registered|registration|number|details?|proof|certified|clearance))?"
    r"|\b(?:rare|rayra|raira|chair)\b\s+(?:or\s+)?"
    r"(?:approved|approval|registered|registration|proof|certified|clearance)\b"
    r"|\b(?:approved|approval|registered|registration|proof|certified|clearance)\b.{0,24}"
    r"\b(?:rera|re\s*ra|rehra|rerha|reira|reera|rehna|rare|rayra|raira|chair)\b"
)

_POSSESSION_FACT_PATTERN = (
    r"\b(?:"
    r"possession(?:\s+date)?|posession(?:\s+date)?|possesson(?:\s+date)?|"
    r"procession\s+date|process\s+(?:and\s+)?date|processing\s+date|"
    r"ready\s+to\s+move|handover(?:\s+date)?|move[- ]?in|"
    r"under\s+construction|construction\s+state|state\s+of\s+construction|"
    r"completion\s+date"
    r")\b"
)


def _looks_like_property_comparison_request(text: str) -> bool:
    lower = (text or "").strip().lower()
    if not lower:
        return False
    if _PROPERTY_COMPARISON_RE.search(lower):
        return True
    ordinals = _extract_comparison_positions(lower)
    return len(ordinals) >= 2 and bool(re.search(r"\b(price|cost|location|possession|configuration|compare)\b", lower))


def _detect_property_comparison_fact(text: str) -> str:
    lower = (text or "").strip().lower()
    patterns = {
        "price": r"\b(price|cost|pricing|starts?\s+from|cheaper|lower)\b",
        "size": r"\b(size|area|sq\.?\s*ft|square\s*feet|carpet)\b",
        "configuration": r"\b(configuration|config|bhk|bedroom|bedrooms)\b",
        "possession": _POSSESSION_FACT_PATTERN,
        "amenities": r"\b(amenities|amenity|facilities|features)\b",
        "developer": r"\b(developer|builder|built by)\b",
        "rera": _RERA_FACT_PATTERN,
        "location": r"\b(location|where|area|micro market|micro-market)\b",
    }
    matches = [fact for fact, pattern in patterns.items() if re.search(pattern, lower, re.IGNORECASE)]
    if len(matches) == 1:
        return matches[0]
    for fact in ("possession", "configuration", "location", "size", "amenities", "developer", "rera"):
        if fact in matches:
            return fact
    if "price" in matches:
        return "price"
    return "price"


def _extract_comparison_positions(text: str) -> list[int]:
    lower = (text or "").strip().lower()
    if not lower:
        return []
    position_by_token = {
        **_ORDINAL_POSITION_MAP,
        "one": 1,
        "two": 2,
        "three": 3,
        "four": 4,
        "five": 5,
    }
    matches: list[tuple[int, int]] = []
    ordinal_pattern = "|".join(sorted((re.escape(k) for k in position_by_token), key=len, reverse=True))
    for match in re.finditer(rf"\b({ordinal_pattern})\b(?:\s+(?:property|project|option|one))?", lower, re.IGNORECASE):
        matches.append((match.start(), position_by_token[match.group(1).lower()]))
    for match in re.finditer(r"\b([1-5])(?:st|nd|rd|th)?\b(?:\s+(?:property|project|option|one))?", lower, re.IGNORECASE):
        token = match.group(1)
        if re.fullmatch(r"[1-5]", token):
            window = lower[max(0, match.start() - 12): match.end() + 18]
            if not re.search(r"(?:property|project|option|compare|versus|vs|and)", window):
                continue
        matches.append((match.start(), int(token)))
    matches.sort(key=lambda item: item[0])
    ordered: list[int] = []
    for _, position in matches:
        if position not in ordered:
            ordered.append(position)
    return ordered


def _property_ref_id(property_ref: dict | str | None) -> str:
    if isinstance(property_ref, str):
        return property_ref.strip()
    if not isinstance(property_ref, dict):
        return ""
    return str(
        property_ref.get("property_id")
        or property_ref.get("project_slug")
        or property_ref.get("slug")
        or ""
    ).strip()


def _looks_like_explicit_detail_repeat(text: str) -> bool:
    lower = (text or "").strip().lower()
    if not lower:
        return False
    return bool(
        re.search(
            r"\b("
            r"repeat|say\s+(?:that|it|this)\s+again|tell\s+(?:me\s+)?again|"
            r"tell\s+(?:me\s+)?about\s+(?:it|this|that|the property|the project)\s+again|"
            r"repeat\s+(?:the\s+)?details?|details?\s+again"
            r")\b",
            lower,
            re.IGNORECASE,
        )
    )


def _looks_like_vague_more_details(text: str) -> bool:
    lower = (text or "").strip().lower()
    if not lower:
        return False
    if re.search(
        r"\b(price|cost|amenit(?:y|ies)|possession|rera|developer|builder|location|"
        r"where|size|sq\.?\s*ft|square\s*feet|configuration|bhk|bedroom|floor|"
        r"callback|site\s+visit|schedule|visit)\b",
        lower,
        re.IGNORECASE,
    ):
        return False
    return bool(
        re.search(
            r"\b("
            r"go\s+ahead|continue|"
            r"(?:yes|yeah|yep|sure|okay|ok|go ahead|continue)[, ]*(?:please\s+)?"
            r"(?:tell|share|give)?\s*(?:me\s+)?more|"
            r"(?:tell|share|give)\s+(?:me\s+)?more(?:\s+details?)?|"
            r"more\s+details?|know\s+more|explain\s+more"
            r")\b",
            lower,
            re.IGNORECASE,
        )
    )


def _looks_like_unresolved_shortlist_property_detail_request(text: str) -> bool:
    lower = re.sub(r"\s+", " ", (text or "").strip().lower())
    if not lower:
        return False
    if _looks_like_off_domain_gather_request(lower):
        return False
    if _looks_like_property_comparison_request(lower):
        return False
    if _parse_inr_amounts(lower) or _extract_property_type_from_text(lower):
        return False
    if re.search(
        r"\b(callback|call\s*back|site\s+visit|schedule\s+(?:a\s+)?visit|book\s+(?:a\s+)?visit)\b",
        lower,
        re.IGNORECASE,
    ):
        return False
    if re.search(
        r"\b(next|more|another|other|remaining|rest|list|relist|repeat|show)\b.{0,40}"
        r"\b(properties|property|projects|options|apartments|villas|plots|results|listings)\b",
        lower,
        re.IGNORECASE,
    ):
        return False
    if re.search(
        r"\b(find|search|show|suggest|recommend)\b.{0,50}"
        r"\b(properties|property|apartments|apartment|villas|villa|plots|plot)\b",
        lower,
        re.IGNORECASE,
    ):
        return False
    if re.search(
        r"\b(budget|price\s+range|under|within|above|below|less\s+than|more\s+than|area|location)\b",
        lower,
        re.IGNORECASE,
    ):
        return False
    if re.fullmatch(
        r"(?:tell\s+me(?:\s+about)?|tell\s+me\s+more|details(?:\s+please)?|more\s+details|more\s+info|explain)",
        lower,
        re.IGNORECASE,
    ):
        return False
    if re.search(
        r"\b(tell|share|give|explain|details?|detail|about|know|information|info|what\s+about)\b",
        lower,
        re.IGNORECASE,
    ):
        return True
    return False


class TranscriptionLogger(FrameProcessor):
    def __init__(self, speaking_event=None, tts_service=None, idle_speech_ref=None, idle_agent_ref=None, tool_handler=None, idle_stage_ref=None, stt_language="en", context_ref=None, turn_ts_ref=None, latency_trace_ref=None, assistant_audio_active_ref=None, interrupt_transport_callback=None, speaker_signal_ref=None, shadow_turn_adapter: TurnTakingAdapter | None = None, stt_provider_profile: dict | None = None, audible_output_state_provider=None, greeting_done_ref=None, call_closing_ref=None, transcript_ledger_ref=None, **kwargs):
        super().__init__(**kwargs)
        self._idle_speech_ref = idle_speech_ref
        self._idle_agent_ref = idle_agent_ref
        self._speaking_event = speaking_event
        self._tts_service = tts_service
        self._tool_handler = tool_handler
        self._idle_stage_ref = idle_stage_ref  # reset to 0 when user speaks
        self._stt_language = stt_language
        self._context_ref = context_ref if context_ref is not None else []
        self._barge_fired = False  # only fire once per user turn
        # Shared mutable ref [start_ts, stt_text] for cross-processor latency tracking
        self._turn_ts_ref = turn_ts_ref if turn_ts_ref is not None else [None, ""]
        self._latency_trace_ref: list = latency_trace_ref if latency_trace_ref is not None else [{}]
        self._assistant_audio_active_ref = assistant_audio_active_ref if assistant_audio_active_ref is not None else [False]
        self._interrupt_transport_callback = interrupt_transport_callback
        self._interrupt_followup_task: asyncio.Task | None = None
        self._interrupt_followup_active = False
        self._interrupt_prompt_spoken = False
        self._interrupt_followup_generation_id = 0
        self._interrupt_grace_s = 0.45
        self._interrupt_resume_wait_s = 1.2
        self._true_interrupt_audio_gap_s = 0.9
        self._early_commit_candidate: dict | None = None
        self._suppress_duplicate_final: dict | None = None
        self._suppress_non_turn_final: dict | None = None
        self._interrupt_dispatched = False
        self._noise_interrupt_timestamps: list[float] = []
        self._noise_interrupt_window_s = 45.0
        self._noise_interrupt_escalation_count = 2
        self._speaking_phase = SPEAKING_PHASE_BARGEABLE
        self._assistant_audio_started_at: float | None = None
        self._no_barge_in_ms = NO_BARGE_IN_MS
        self._current_assistant_is_synthetic = False
        self._speaker_signal_ref = speaker_signal_ref if speaker_signal_ref is not None else [{}]
        self._shadow_turn_adapter = shadow_turn_adapter
        self._stt_provider_profile = dict(stt_provider_profile or {})
        self._supports_interim_semantics = bool(self._stt_provider_profile.get("supports_interim_semantics", True))
        self._speech_start_candidate_ts: float | None = None
        self._saw_interim_this_turn = False
        self._audible_output_state_provider = audible_output_state_provider
        self._greeting_done_ref = greeting_done_ref if greeting_done_ref is not None else [True]
        self._call_closing_ref = call_closing_ref if call_closing_ref is not None else [False]
        self._transcript_ledger_ref = transcript_ledger_ref if transcript_ledger_ref is not None else [[]]
        self._soft_hold_active = False
        self._soft_hold_started_at: float | None = None
        self._soft_hold_source_reason = ""
        self._soft_hold_last_prompt = ""

    def _clear_soft_hold(self, reason: str) -> None:
        if self._soft_hold_active:
            logger.info(
                f"[SoftHold] cleared reason={reason} source={self._soft_hold_source_reason or '-'} "
                f"age_ms={int(max(0.0, (time.time() - (self._soft_hold_started_at or time.time())) * 1000))}"
            )
        self._soft_hold_active = False
        self._soft_hold_started_at = None
        self._soft_hold_source_reason = ""
        self._soft_hold_last_prompt = ""

    def _soft_hold_is_active(self) -> bool:
        if not self._soft_hold_active:
            return False
        started_at = self._soft_hold_started_at or time.time()
        if (time.time() - started_at) > SOFT_HOLD_WINDOW_S:
            self._clear_soft_hold("timeout_expired")
            return False
        return True

    def soft_hold_is_active(self) -> bool:
        return self._soft_hold_is_active()

    def _start_soft_hold(self, reason: str, prompt_text: str = "") -> None:
        self._soft_hold_active = True
        self._soft_hold_started_at = time.time()
        self._soft_hold_source_reason = reason or ""
        self._soft_hold_last_prompt = prompt_text or ""
        logger.info(
            f"[SoftHold] started source={self._soft_hold_source_reason or '-'} "
            f"prompt={self._soft_hold_last_prompt!r}"
        )

    async def _speak_progress_check_preserving_gather(
        self,
        reply: str,
        text: str,
        *,
        synthetic: bool = False,
        response_mode: str | None = None,
    ) -> None:
        field = str(getattr(self._tool_handler, "_pending_gather_field", None) or "").strip()
        prompt = str(getattr(self._tool_handler, "_pending_gather_prompt", "") or "").strip()
        if field:
            logger.warning(
                f"[GatherResume] ProgressCheck would clear active gather state; "
                f"preserving field={field} text={text!r}"
            )
            logger.info(f"[GatherResume] preserved field={field} reason=liveness_check_mid_gather")
            if prompt and prompt.lower() not in (reply or "").lower():
                reply = f"{reply.rstrip()} {prompt}"
        await self._speak_logged_direct_text(
            reply,
            synthetic=synthetic,
            response_mode=response_mode,
        )
        if field and self._tool_handler:
            self._tool_handler.set_pending_gather_resume_state(
                field,
                prompt or reply,
                source="liveness_check_mid_gather",
            )

    def _is_affirmative(self, text: str) -> bool:
        affirmative_tokens = {
            "yes", "yeah", "sure", "okay", "ok", "alright",
            "please", "go", "ahead", "do", "it", "both", "yep", "yup",
        }
        tokens = re.sub(r"[^\w\s]", " ", (text or "").lower()).split()
        return bool(tokens) and all(token in affirmative_tokens for token in tokens)

    def _extract_booking_intent(self, text: str) -> str | None:
        """Return the explicit booking action requested by the user, if present."""
        t = (text or "").lower()
        if any(p in t for p in [
            "site visit", "visit the site", "visit", "schedule",
            "book a visit", "want to visit", "show me the site",
        ]):
            return "site_visit"
        if any(p in t for p in [
            "callback", "call me", "call back", "contact me",
            "reach out", "specialist call",
        ]):
            return "callback"
        return None

    def _inject_booking_intent_directive(
        self,
        intent: str,
        property_name: str,
        *,
        source: str,
    ) -> bool:
        if not (self._context_ref and self._context_ref[0]):
            return False
        name = str(property_name or "this property").strip() or "this property"
        if intent == "site_visit":
            today_str = _dt.date.today().strftime("%A, %d %B %Y")
            caller_name = ""
            if self._tool_handler:
                caller_name = str(
                    getattr(self._tool_handler, "call_context", {}).get("senderName") or ""
                ).strip()
            name_instruction = (
                f"Use caller first name '{caller_name.split()[0]}' for firstName. "
                if caller_name else
                "Also ask for the caller's first name before calling schedule_site_visit. "
            )
            directive = (
                f"[SITE VISIT] User requested a site visit for '{name}'. "
                f"Today's date is {today_str}. "
                "Collect the preferred visit date and time if not already provided. "
                "Resolve relative dates like 'tomorrow' or 'next Monday' using today's date. "
                f"{name_instruction}"
                "Then call schedule_site_visit with the resolved ISO date. "
                "Do not ask the user to choose between callback and site visit again."
            )
            log_label = "SiteVisitIntent"
        elif intent == "callback":
            directive = (
                f"[CALLBACK] User explicitly requested a callback for '{name}'. "
                "Call submit_callback immediately. Do not ask the user to choose "
                "between callback and site visit again."
            )
            log_label = "CallbackIntent"
        else:
            return False
        self._context_ref[0].messages.append({"role": "system", "content": directive})
        logger.info(
            f"[{log_label}] explicit_booking_intent source={source or '-'} "
            f"property={name!r}"
        )
        return True

    def _build_site_visit_collection_prompt(self, first_name: str = "") -> str:
        clean_name = str(first_name or "").strip().split()[0] if str(first_name or "").strip() else ""
        if clean_name:
            return f"Thank you, {clean_name}. What date and time would you prefer for the site visit?"
        return "Sure. May I have your first name and the preferred visit date and time?"

    async def _begin_site_visit_collection(
        self,
        user_text: str,
        property_name: str,
        *,
        source: str,
        property_id: str | None = None,
        location: str | None = None,
    ) -> bool:
        if not self._tool_handler:
            return False
        name = str(property_name or self._tool_handler.safe_callback_property_name() or "this property").strip()
        caller_name = str(self._tool_handler.call_context.get("senderName") or "").strip()
        reply = self._build_site_visit_collection_prompt(caller_name)
        self._tool_handler.set_pending_user_offer(
            "site_visit",
            property_id=property_id or getattr(self._tool_handler, "_active_property_id", None),
            property_name=name,
            location=location or self._tool_handler._gathered_search.get("location") or "",
            source=source or "deterministic_site_visit_collection",
        )
        self._tool_handler.clear_pending_property_lookup()
        if self._context_ref and self._context_ref[0]:
            _ctx = self._context_ref[0]
            _ctx.messages.append({"role": "user", "content": user_text})
            _ctx.messages.append({"role": "assistant", "content": reply})
        if self._latency_trace_ref and isinstance(self._latency_trace_ref[0], dict):
            self._latency_trace_ref[0]["cache_path_hit"] = True
            self._latency_trace_ref[0]["path_label"] = "deterministic_site_visit_collection"
        logger.info(
            f"[SiteVisitIntent] deterministic_followup_path=site_visit_collection "
            f"source={source or '-'} property={name!r}"
        )
        await self._speak_logged_direct_text(
            reply,
            response_mode="deterministic_site_visit_collection",
        )
        return True

    async def _ask_site_visit_property_choice(self, user_text: str, *, source: str) -> bool:
        if not self._tool_handler:
            return False
        if not self._tool_handler.has_active_shortlist_context():
            return False
        reply = "Which property would you like to schedule a site visit for?"
        self._tool_handler.set_pending_user_offer(
            "site_visit",
            location=self._tool_handler._gathered_search.get("location") or "",
            source=source or "deterministic_site_visit_property_choice",
        )
        if getattr(self._tool_handler, "_last_presented_properties", None):
            self._tool_handler._selection_pending = True
        if self._context_ref and self._context_ref[0]:
            _ctx = self._context_ref[0]
            _ctx.messages.append({"role": "user", "content": user_text})
            _ctx.messages.append({"role": "assistant", "content": reply})
        if self._latency_trace_ref and isinstance(self._latency_trace_ref[0], dict):
            self._latency_trace_ref[0]["cache_path_hit"] = True
            self._latency_trace_ref[0]["path_label"] = "deterministic_site_visit_property_choice"
        logger.info(
            f"[SiteVisitIntent] deterministic_followup_path=site_visit_property_choice "
            f"source={source or '-'}"
        )
        await self._speak_logged_direct_text(
            reply,
            response_mode="deterministic_site_visit_property_choice",
        )
        return True

    def _pending_site_visit_needs_property(self) -> bool:
        if not self._tool_handler:
            return False
        offer = getattr(self._tool_handler, "_pending_user_offer", None) or {}
        if str(offer.get("offer_type") or "").strip().lower() != "site_visit":
            return False
        return not (
            str(offer.get("property_id") or "").strip()
            or str(offer.get("property_name") or "").strip()
            or getattr(self._tool_handler, "_active_property_id", None)
            or getattr(self._tool_handler, "_active_property_name", None)
        )

    async def _continue_site_visit_after_property_selection(
        self,
        user_text: str,
        selected: dict,
        *,
        source: str,
    ) -> bool:
        if not self._tool_handler or not isinstance(selected, dict):
            return False
        prop_id = str(selected.get("property_id") or selected.get("project_slug") or "").strip()
        name = str(selected.get("name") or selected.get("project_name") or "").strip()
        location = str(
            selected.get("location")
            or selected.get("micro_market")
            or self._tool_handler._gathered_search.get("location")
            or ""
        ).strip()
        if prop_id or name:
            self._tool_handler._mark_explicit_property_focus({
                "property_id": prop_id,
                "name": name,
            })
        return await self._begin_site_visit_collection(
            user_text,
            name or "this property",
            source=source or "site_visit_property_selected",
            property_id=prop_id,
            location=location,
        )

    async def _handle_property_first_resolution(
        self,
        user_text: str,
        property_query: str,
        *,
        source: str,
        location_hint: str = "",
    ) -> bool:
        if not self._tool_handler or not str(property_query or "").strip():
            return False
        _th = self._tool_handler
        _th.clear_transient_property_routing_state()
        query_to_resolve = _th.property_resolve_name_for_turn(property_query, user_text)
        resolved = await _th.resolve_property_by_name_hybrid(
            query_to_resolve,
            raw_text=user_text,
            location_hint=location_hint,
            limit=5,
        )
        match_type = resolved.get("match_type")
        candidates = (resolved.get("candidates") or [])[:5]
        if match_type == "single" and candidates:
            reply = _th.build_property_first_confirmation_text(candidates[0])
            _th.set_pending_property_lookup(
                "single_confirm",
                query_to_resolve,
                candidates=candidates[:1],
                location_hint=location_hint,
            )
        elif match_type == "multiple" and candidates:
            if len(candidates) == 1:
                reply = _th.build_property_first_confirmation_text(candidates[0])
                _th.set_pending_property_lookup(
                    "single_confirm",
                    query_to_resolve,
                    candidates=candidates[:1],
                    location_hint=location_hint,
                )
            else:
                reply = _th.build_property_first_options_text(candidates[:3])
                _th.set_pending_property_lookup(
                    "multiple_select",
                    query_to_resolve,
                    candidates=candidates[:3],
                    location_hint=location_hint,
                )
        else:
            return False
        if self._context_ref and self._context_ref[0]:
            _ctx = self._context_ref[0]
            _ctx.messages.append({"role": "user", "content": user_text})
            _ctx.messages.append({"role": "assistant", "content": reply})
        if self._latency_trace_ref and isinstance(self._latency_trace_ref[0], dict):
            self._latency_trace_ref[0]["cache_path_hit"] = True
            self._latency_trace_ref[0]["path_label"] = "deterministic_property_first_resolution"
        logger.info(
            f"[PropertyFirst] deterministic_followup_path=property_first_resolution "
            f"source={source or '-'} query={query_to_resolve!r} match_type={match_type}"
        )
        await self._speak_logged_direct_text(
            reply,
            response_mode="deterministic_property_first_resolution",
        )
        return True

    def _is_pending_offer_affirmative(self, text: str) -> bool:
        """
        Return True when a vague affirmative follows an active callback/site-visit offer.
        """
        if not self._tool_handler:
            return False
        pending_offer = getattr(self._tool_handler, "_pending_user_offer", None) or {}
        if not pending_offer:
            return False
        offer_type = str(pending_offer.get("offer_type") or "").strip().lower()
        if offer_type not in {"callback", "site_visit"}:
            return False
        pending_lookup = getattr(self._tool_handler, "_pending_property_lookup", None) or {}
        pending_lookup_mode = str(pending_lookup.get("mode") or "").strip().lower()
        if pending_lookup_mode in {"single_confirm", "multiple_select"}:
            return False
        if self._is_awaiting_site_visit_datetime():
            return False
        recent_assistant_turns = [
            str(entry.get("spoken_text") or "").lower()
            for entry in (getattr(self._tool_handler, "_spoken_turn_ledger", []) or [])[-3:]
            if isinstance(entry, dict) and entry.get("source") == "tts_input"
        ]
        for turn in reversed(recent_assistant_turns):
            if re.search(r"\bare\s+you\s+asking\s+about\b|\bwhich\s+one\s+are\s+you\s+asking\s+about\b", turn):
                return False
            if re.search(r"\b(callback|call\s+back)\b", turn) and re.search(r"\bsite\s+visit\b", turn):
                return self._is_affirmative(text)
        return False

    def _is_awaiting_site_visit_datetime(self) -> bool:
        if not self._tool_handler:
            return False
        offer = getattr(self._tool_handler, "_pending_user_offer", None) or {}
        if str(offer.get("offer_type") or "").strip().lower() != "site_visit":
            return False
        recent_tts_turns = [
            str(entry.get("spoken_text") or "").lower()
            for entry in (getattr(self._tool_handler, "_spoken_turn_ledger", []) or [])[-3:]
            if isinstance(entry, dict) and entry.get("source") == "tts_input"
        ]
        if not recent_tts_turns:
            last_prompt = getattr(self._tool_handler, "_last_spoken_prompt", None) or {}
            recent_tts_turns = [str(last_prompt.get("spoken_text") or "").lower()]
        datetime_keywords = {
            "date", "time", "when", "preferred", "visit date",
            "o'clock", "schedule", "day",
        }
        explicit_datetime_keywords = {
            "date", "time", "when", "preferred", "visit date", "o'clock", "day",
        }
        for turn in recent_tts_turns:
            if not any(keyword in turn for keyword in datetime_keywords):
                continue
            is_offer_choice_prompt = bool(
                re.search(r"\b(callback|call\s+back)\b", turn)
                and re.search(r"\bsite\s+visit\b", turn)
            )
            has_explicit_datetime_wording = any(
                keyword in turn for keyword in explicit_datetime_keywords
            )
            if is_offer_choice_prompt and not has_explicit_datetime_wording:
                continue
            return True
        return False

    def _inject_offer_clarification(self, guard_name: str = "", text: str = "") -> None:
        """Inject LLM directive to ask callback vs site visit."""
        logger.info(f"[OfferClarify] intercepted at {guard_name or '-'} text={text!r}")
        explicit_intent = self._extract_booking_intent(text)
        if explicit_intent and self._tool_handler:
            property_name = self._tool_handler.safe_callback_property_name()
            if self._inject_booking_intent_directive(
                explicit_intent,
                property_name,
                source=f"offer_clarify_{guard_name or 'unknown'}",
            ):
                return
        if not (self._context_ref and self._context_ref[0]):
            return
        self._context_ref[0].messages.append({
            "role": "system",
            "content": (
                "[OFFER CLARIFY] User gave ambiguous affirmative after "
                "callback/site-visit offer. Ask: 'Would you prefer a "
                "callback or a site visit?' in one natural sentence."
            ),
        })

    def _build_soft_hold_reentry_reply(self) -> str:
        return "Yes, I'm here. How can I help you?"

    def _refresh_speaking_phase(self) -> str:
        if not self._assistant_audio_started_at:
            self._speaking_phase = SPEAKING_PHASE_BARGEABLE
            return self._speaking_phase
        elapsed_ms = (time.time() - self._assistant_audio_started_at) * 1000.0
        self._speaking_phase = (
            SPEAKING_PHASE_NO_BARGE
            if elapsed_ms < self._no_barge_in_ms
            else SPEAKING_PHASE_BARGEABLE
        )
        return self._speaking_phase

    def mark_assistant_audio_started(self):
        self._assistant_audio_started_at = time.time()
        self._speaking_phase = SPEAKING_PHASE_NO_BARGE
        self._current_assistant_is_synthetic = global_state_manager.current_assistant_is_synthetic()
        if self._tool_handler:
            try:
                self._tool_handler.note_shortlist_audio_started()
            except Exception as exc:
                logger.debug(f"[Shortlist] audio start hook failed: {exc}")

    def mark_assistant_audio_stopped(self):
        self._assistant_audio_started_at = None
        self._speaking_phase = SPEAKING_PHASE_BARGEABLE
        self._current_assistant_is_synthetic = False
        if self._tool_handler:
            try:
                self._tool_handler.note_shortlist_audio_completed("audio_stopped")
            except Exception as exc:
                logger.debug(f"[Shortlist] audio stop hook failed: {exc}")

    def _speaker_separation_gate(self, decision: InterruptDecision, text: str, *, is_final: bool) -> InterruptDecision:
        if not SPEAKER_SEPARATION_V1_ENABLED or not decision.should_commit:
            return decision
        if decision.kind in {"hold", "synthetic_checkin_reply"}:
            return decision
        signal = dict(self._speaker_signal_ref[0] or {})
        if not signal:
            return decision
        signal["text"] = text
        signal["decision_kind"] = decision.kind
        global_state_manager.record_speaker_separation_signal(signal)
        if signal.get("background_voice_suspected"):
            return InterruptDecision(kind="background_voice", should_commit=False, reason="background_voice_gate")
        if not signal.get("playback_reference_ok", True):
            return InterruptDecision(kind="background_voice", should_commit=False, reason="playback_reference_gate")
        if not signal.get("continuity_ok", True) and not is_final:
            return InterruptDecision(kind="background_voice", should_commit=False, reason="continuity_gate")
        if not signal.get("near_field_ok", True) and not is_final:
            return InterruptDecision(kind="background_voice", should_commit=False, reason="near_field_gate")
        return decision

    async def _cancel_interrupt_followup(self):
        self._interrupt_followup_active = False
        self._interrupt_prompt_spoken = False
        if self._interrupt_followup_task and not self._interrupt_followup_task.done():
            self._interrupt_followup_task.cancel()
            try:
                await self._interrupt_followup_task
            except asyncio.CancelledError:
                pass
        self._interrupt_followup_task = None

    def _build_noise_resume_prompt(self) -> str:
        now = time.time()
        self._noise_interrupt_timestamps = [
            ts for ts in self._noise_interrupt_timestamps
            if (now - ts) <= self._noise_interrupt_window_s
        ]
        self._noise_interrupt_timestamps.append(now)
        if len(self._noise_interrupt_timestamps) >= self._noise_interrupt_escalation_count:
            return "There seems to be some background noise. If possible, please move to a quieter place, and I'll continue."
        return "I heard some background noise. I'll continue."

    async def _resume_interrupted_speech(self, reason: str):
        resume_text = (global_state_manager.get_interrupted_text() or "").strip()
        if not resume_text:
            resume_text = (global_state_manager.latest_assistant_text or "").strip()
        if not resume_text and self._tool_handler:
            try:
                _last_prompt = self._tool_handler._last_spoken_prompt or {}
                resume_text = str(_last_prompt.get("spoken_text") or "").strip()
                if not resume_text:
                    resume_text = str(getattr(self._tool_handler, "_shortlist_presentation_text", "") or "").strip()
            except Exception as exc:
                logger.debug(f"[INTERRUPT_RESUME] fallback lookup failed: {exc}")
        if not resume_text:
            logger.warning(f"[INTERRUPT_RESUME] no resume text available reason={reason}")
            global_state_manager.clear_resume()
            return
        if not self._tts_service:
            logger.warning(f"[INTERRUPT_RESUME] no TTS service available reason={reason}")
            global_state_manager.clear_resume()
            return
        if "resume_confirmation" in (reason or ""):
            resume_text = f"Sure, let me continue. {resume_text}"
        logger.info(f"[INTERRUPT_RESUME] reason={reason} text={resume_text[:80]!r}")
        self._interrupt_followup_active = False
        self._interrupt_prompt_spoken = False
        self._interrupt_dispatched = False
        global_state_manager.set_state(AgentState.SPEAKING)
        await self._speak_logged_direct_text(resume_text, synthetic=True)
        global_state_manager.note_resume_result(True, reason=reason)
        global_state_manager.clear_resume()

    async def _speak_checkin_and_resume(self, prompt_text: str, reason: str):
        logger.info(f"[INTERRUPT_CHECKIN] reason={reason} prompt={prompt_text!r}")
        self._interrupt_followup_active = False
        self._interrupt_prompt_spoken = False
        self._interrupt_dispatched = False
        global_state_manager.set_state(AgentState.SPEAKING)
        await self._speak_logged_direct_text(prompt_text, synthetic=True)
        if global_state_manager.get_interrupted_text():
            await self._resume_interrupted_speech(f"{reason}_resume")

    async def _handle_deterministic_interrupt(self, user_text: str, reason: str):
        prompt_text, should_resume = build_deterministic_interrupt_reply(user_text)
        if not prompt_text:
            prompt_text = self._build_noise_resume_prompt()
            should_resume = True
        logger.info(
            f"[INTERRUPT_DETERMINISTIC] reason={reason} resume={should_resume} "
            f"user_text={user_text!r} prompt={prompt_text!r}"
        )
        self._interrupt_followup_active = False
        self._interrupt_prompt_spoken = False
        self._interrupt_dispatched = False
        global_state_manager.set_state(AgentState.SPEAKING)
        await self._speak_logged_direct_text(prompt_text, synthetic=True)
        if should_resume and global_state_manager.get_interrupted_text():
            await self._resume_interrupted_speech(f"{reason}_resume")

    def _is_silent_hold_request(self, user_text: str) -> bool:
        cleaned = re.sub(r"[^\w\s]", " ", (user_text or "").lower()).strip()
        cleaned = re.sub(r"\s+", " ", cleaned)
        if not cleaned:
            return False
        return bool(re.fullmatch(
            r"(?:wait\s*){1,5}|hold on|one second|just a second|give me a second|"
            r"give me a moment|wait a minute|one moment|please wait|can you wait|wait can",
            cleaned,
        ))

    async def _handle_soft_hold(self, user_text: str, reason: str) -> None:
        prompt_text, _ = build_deterministic_interrupt_reply(user_text)
        prompt_text = prompt_text or "Sure. Is there anything else I can help you with?"
        self._start_soft_hold(reason or "hold_intent", prompt_text)
        self._interrupt_followup_active = False
        self._interrupt_prompt_spoken = False
        self._interrupt_dispatched = False
        global_state_manager.set_state(AgentState.IDLE)
        if self._is_silent_hold_request(user_text):
            logger.info(f"[SoftHold] silent_hold_engaged text={user_text!r}")
            return
        await self._speak_logged_direct_text(prompt_text, synthetic=True)

    async def _speak_logged_direct_text(self, text: str, *, synthetic: bool = False, response_mode: str | None = None):
        if not text:
            return
        text = _cleanup_tts_text(text)
        if not text:
            return
        _trace = self._latency_trace_ref[0] if self._latency_trace_ref else None
        if isinstance(_trace, dict):
            _existing_mode = _trace.get("response_mode")
            _trace["response_mode"] = (
                response_mode
                or ("deterministic_direct" if _existing_mode in {None, "tool_wait_filler"} else _existing_mode)
            )
            if not _trace.get("path_label"):
                _trace["path_label"] = (
                    "deterministic_direct"
                    if not _trace.get("cache_path_hit")
                    else "prefetch_cache"
                )
            if not _trace.get("router_decision_at"):
                _trace["router_decision_at"] = time.time()
                _turn_start = _trace.get("turn_start")
                if _turn_start:
                    _trace["router_ms"] = int((_trace["router_decision_at"] - _turn_start) * 1000)
        if self._tool_handler:
            _kind = "assistant_reply"
            if self._tool_handler._pending_variant_selection:
                _kind = "variant_clarification"
            elif self._tool_handler.shortlist_is_pending_delivery() or self._tool_handler.shortlist_is_committed():
                _kind = "shortlist"
            elif self._tool_handler.current_locked_property_target() or self._tool_handler._active_property_id:
                _kind = "property_detail"
            self._tool_handler.remember_spoken_prompt(
                text,
                kind=_kind,
                property_ids=[
                    str(
                        (self._tool_handler.current_locked_property_target() or {}).get("property_id")
                        or self._tool_handler._active_property_id
                        or ""
                    ).strip()
                ],
                question_expected=text.rstrip().endswith("?"),
                source="direct_speech",
            )
        _record_transcript_turn(self._transcript_ledger_ref, "assistant", text, source="direct_speech")
        global_state_manager.begin_assistant_output(synthetic=synthetic, text=text)
        if synthetic:
            global_state_manager.remember_synthetic_message(text)
            global_state_manager.note_synthetic_prompt_triggered(text)
        await self.push_frame(LLMFullResponseStartFrame(), FrameDirection.DOWNSTREAM)
        await self.push_frame(LLMTextFrame(text), FrameDirection.DOWNSTREAM)
        await self.push_frame(LLMFullResponseEndFrame(), FrameDirection.DOWNSTREAM)

    def _assistant_audio_is_recent(self) -> bool:
        try:
            last_audio_ts = (self._latency_trace_ref[0] or {}).get("tts_audio_last")
        except Exception:
            last_audio_ts = None
        try:
            ledger = global_state_manager.current_turn_ledger()
            cursor = ledger.playout_cursor if ledger else None
            audio_started_at = float(cursor.audio_started_at or 0.0) if cursor else 0.0
            played_audio_ms = float(cursor.played_audio_ms or 0.0) if cursor else 0.0
        except Exception:
            audio_started_at = 0.0
            played_audio_ms = 0.0
        if audio_started_at and played_audio_ms > 0:
            # Cartesia can emit all audio frames quickly while the browser/WebRTC
            # transport is still playing buffered audio. Treat the assistant as
            # interruptible until estimated playout has drained.
            estimated_playout_end = audio_started_at + (played_audio_ms / 1000.0) + self._true_interrupt_audio_gap_s
            if time.time() <= estimated_playout_end:
                return True
        if not last_audio_ts:
            return False
        return (time.time() - last_audio_ts) <= self._true_interrupt_audio_gap_s

    def _get_audible_output_state(self) -> dict:
        try:
            state = self._audible_output_state_provider() if self._audible_output_state_provider else None
        except Exception as exc:
            logger.debug(f"[AUDIO_STATE] audible output provider failed: {exc}")
            state = None
        if not isinstance(state, dict):
            state = {}
        state.setdefault("live", False)
        state.setdefault("queue_chunks", 0)
        state.setdefault("queued_ms", 0)
        state.setdefault("playout_end_in_ms", 0)
        return state

    def _assistant_audio_is_live(self) -> bool:
        audible_state = self._get_audible_output_state()
        if audible_state.get("live"):
            if not self._assistant_audio_active_ref[0]:
                self._assistant_audio_active_ref[0] = True
            return True
        audio_recent = self._assistant_audio_is_recent()
        if audio_recent:
            return True
        if bool(self._assistant_audio_active_ref[0]):
            try:
                last_audio_ts = (self._latency_trace_ref[0] or {}).get("tts_audio_last")
            except Exception:
                last_audio_ts = None
            if last_audio_ts and (time.time() - last_audio_ts) > self._true_interrupt_audio_gap_s:
                logger.info(
                    f"[AUDIO_STATE] Clearing stale assistant audio-active flag "
                    f"(recent={audio_recent} queue_chunks={audible_state.get('queue_chunks')} "
                    f"queued_ms~={audible_state.get('queued_ms')} "
                    f"playout_end_in_ms={audible_state.get('playout_end_in_ms')})"
                )
                self._assistant_audio_active_ref[0] = False
                self.mark_assistant_audio_stopped()
                global_state_manager.finish_assistant_output(generation_id=global_state_manager.current_output_generation() or None)
                if global_state_manager.is_speaking():
                    global_state_manager.set_state(AgentState.IDLE)
                return False
        return bool(self._assistant_audio_active_ref[0])

    async def _dispatch_true_interruption(self, source: str, text: str = "") -> bool:
        if self._interrupt_dispatched:
            return False
        if not self._assistant_audio_is_live():
            return False

        _interrupt_detected_at = time.time()
        self._interrupt_dispatched = True
        _fallback_resume = (
            global_state_manager.get_interrupted_text()
            or global_state_manager.current_assistant_text()
            or global_state_manager.latest_assistant_text
        )
        _resume_seed = global_state_manager.build_unheard_resume_seed(_fallback_resume or "")
        global_state_manager.prime_resume_seed(_resume_seed)
        global_state_manager.note_resume_seed(_resume_seed)
        if self._tool_handler:
            _committed_ms = int(max(0, ((time.time() - (self._turn_ts_ref[0] or time.time())) * 1000)))
            self._tool_handler.mark_last_spoken_prompt_truncated(source, committed_audio_ms=_committed_ms)
        logger.info(
            f"[INTERRUPT_DISPATCH] source={source} text={text!r} "
            f"audio_active={self._assistant_audio_active_ref[0]} recent={self._assistant_audio_is_recent()} "
            f"audible_state={self._get_audible_output_state()}"
        )
        try:
            await self.push_frame(InterruptionFrame(), FrameDirection.DOWNSTREAM)
        except Exception as e:
            logger.warning(f"[INTERRUPT_DISPATCH] InterruptionFrame dispatch failed: {e}")
        try:
            if self._tts_service:
                from pipecat.frames.frames import CancelFrame
                await self._tts_service.cancel(CancelFrame())
                logger.info(
                    f"[INTERRUPT_DISPATCH] TTS cancel sent detect_to_cancel_ms="
                    f"{int(max(0.0, (time.time() - _interrupt_detected_at) * 1000))}"
                )
        except Exception as e:
            logger.warning(f"[INTERRUPT_DISPATCH] TTS cancel failed: {e}")
        try:
            if self._interrupt_transport_callback:
                _res = self._interrupt_transport_callback(source, text)
                if inspect.isawaitable(_res):
                    await _res
                logger.info("[INTERRUPT_DISPATCH] Transport interruption callback completed")
        except Exception as e:
            logger.warning(f"[INTERRUPT_DISPATCH] Transport interruption callback failed: {e}")
        return True

    async def _interrupt_followup_worker(self):
        try:
            await asyncio.sleep(self._interrupt_grace_s)
            if (
                not self._interrupt_followup_active
                or self._interrupt_followup_generation_id != global_state_manager.current_output_generation()
            ):
                return
            self._interrupt_prompt_spoken = True
            logger.info("[INTERRUPT_PROMPT] Non-substantive interruption detected; continuing with a brief notice")
            await self._speak_logged_direct_text(self._build_noise_resume_prompt(), synthetic=True)
            await asyncio.sleep(self._interrupt_resume_wait_s)
            if (
                not self._interrupt_followup_active
                or self._interrupt_followup_generation_id != global_state_manager.current_output_generation()
            ):
                return
            logger.info("[INTERRUPT_PROMPT] No follow-up speech detected; resuming prior response")
            await self._resume_interrupted_speech("no_followup_after_prompt")
        except asyncio.CancelledError:
            raise
        finally:
            if self._interrupt_followup_task and self._interrupt_followup_task.done():
                self._interrupt_followup_task = None

    async def _start_interrupt_followup(self):
        await self._cancel_interrupt_followup()
        self._interrupt_followup_active = True
        self._interrupt_prompt_spoken = False
        self._interrupt_followup_generation_id = global_state_manager.current_output_generation()
        self._interrupt_followup_task = asyncio.create_task(self._interrupt_followup_worker())

    async def process_frame(self, frame, direction):
        await super().process_frame(frame, direction)
        if isinstance(frame, EndFrame):
            self._clear_soft_hold("end_frame")
            await self.push_frame(frame, direction)
            return
        if isinstance(frame, UserStartedSpeakingFrame):
            if self._call_closing_ref and self._call_closing_ref[0]:
                logger.info("[ClosingGate] Ignored UserStartedSpeakingFrame while call is closing")
                return
            if self._speech_start_candidate_ts is None:
                self._speech_start_candidate_ts = time.time()
            await self.push_frame(frame, direction)
            return
        if isinstance(frame, TranscriptionFrame):
            if self._interrupt_followup_active:
                await self._cancel_interrupt_followup()
            # â”€â”€ GLOBAL HELLO ROUTING â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
            # Handle "hello", "hi", "are you there" at ANY point during active conversation
            text = (frame.text or "").strip()
            _canon_final = _canonical_short_slot_text(text)
            if self._suppress_duplicate_final:
                _age = time.time() - self._suppress_duplicate_final.get("ts", 0)
                if (
                    _age < 2.5
                    and self._suppress_duplicate_final.get("text") == _canon_final
                ):
                    logger.info(f"[EarlyCommit] Suppressed duplicate FINAL after interim commit: {text!r}")
                    self._suppress_duplicate_final = None
                    return
                if _age >= 2.5:
                    self._suppress_duplicate_final = None
            if self._suppress_non_turn_final:
                _age = time.time() - self._suppress_non_turn_final.get("ts", 0)
                if (
                    _age < 2.5
                    and self._suppress_non_turn_final.get("text") == _canon_final
                ):
                    logger.info(f"[InterruptSuppress] Suppressed non-turn FINAL after interim handling: {text!r}")
                    self._suppress_non_turn_final = None
                    return
                if _age >= 2.5:
                    self._suppress_non_turn_final = None
            if self._greeting_done_ref and not self._greeting_done_ref[0]:
                logger.info(f"[GreetingGate] Ignored user speech during greeting: {text!r}")
                self._speech_start_candidate_ts = None
                self._saw_interim_this_turn = False
                return
            if self._call_closing_ref and self._call_closing_ref[0]:
                logger.info(f"[ClosingGate] Ignored user speech while call is closing: {text!r}")
                self._clear_soft_hold("call_closing")
                self._speech_start_candidate_ts = None
                self._saw_interim_this_turn = False
                return
            try:
                _outbound_idle_stage_ref[0] = 0
                _last_user_speech_ref[0] = time.time()
                _call_ending_ref[0] = False
            except NameError:
                pass
            _record_transcript_turn(self._transcript_ledger_ref, "user", text, source="stt_final")
            if self._tool_handler:
                _caller_first_name = _extract_caller_first_name_from_text(text)
                if _caller_first_name and not str(self._tool_handler.call_context.get("senderName") or "").strip():
                    self._tool_handler.call_context["senderName"] = _caller_first_name
                    logger.info(f"[SiteVisit] captured caller firstName from speech: {_caller_first_name!r}")
                    if self._is_awaiting_site_visit_datetime():
                        _reply = self._build_site_visit_collection_prompt(_caller_first_name)
                        if self._context_ref and self._context_ref[0]:
                            _ctx = self._context_ref[0]
                            _ctx.messages.append({"role": "user", "content": text})
                            _ctx.messages.append({"role": "assistant", "content": _reply})
                        if self._latency_trace_ref and isinstance(self._latency_trace_ref[0], dict):
                            self._latency_trace_ref[0]["cache_path_hit"] = True
                            self._latency_trace_ref[0]["path_label"] = "deterministic_site_visit_datetime_prompt"
                        logger.info(
                            f"[SiteVisit] deterministic_followup_path=date_time_prompt "
                            f"firstName={_caller_first_name!r}"
                        )
                        await self._speak_logged_direct_text(
                            _reply,
                            response_mode="deterministic_site_visit_datetime_prompt",
                        )
                        return
            _soft_hold_active = self._soft_hold_is_active()
            if _soft_hold_active and self._tool_handler and self._tool_handler.is_progress_check(text):
                _reply = self._build_soft_hold_reentry_reply()
                logger.info(f"[SoftHold] reentry_greeting_handled text={text!r}")
                self._speech_start_candidate_ts = None
                self._saw_interim_this_turn = False
                if self._context_ref and self._context_ref[0]:
                    _ctx = self._context_ref[0]
                    _ctx.messages.append({"role": "user", "content": text})
                    _ctx.messages.append({"role": "assistant", "content": _reply})
                await self._speak_logged_direct_text(_reply, synthetic=True)
                return
            if self._tool_handler and self._tool_handler.is_progress_check(text):
                _reply = self._tool_handler.build_progress_check_reply()
                if _reply:
                    if _soft_hold_active:
                        logger.info(f"[SoftHold] suppressed progress-check text={text!r}")
                        return
                    logger.info(f"[ProgressCheck] Handling liveness check text={text!r}")
                    if global_state_manager.is_speaking() and self._assistant_audio_is_live():
                        if self._tool_handler.shortlist_is_pending_delivery():
                            self._tool_handler.note_shortlist_interrupted("progress_check")
                        await self._dispatch_true_interruption("progress_check", text)
                        self.mark_assistant_audio_stopped()
                    global_state_manager.set_state(AgentState.IDLE)
                    self._speech_start_candidate_ts = None
                    self._saw_interim_this_turn = False
                    if self._context_ref and self._context_ref[0]:
                        _ctx = self._context_ref[0]
                        _ctx.messages.append({"role": "user", "content": text})
                        _ctx.messages.append({"role": "assistant", "content": _reply})
                    await self._speak_progress_check_preserving_gather(
                        _reply,
                        text,
                        synthetic=True,
                    )
                    return
            self._early_commit_candidate = None
            if self._speech_start_candidate_ts:
                global_state_manager.append_stt_observability_timing(
                    "speechStartToFinalMs",
                    int((time.time() - self._speech_start_candidate_ts) * 1000),
                )
            if not self._supports_interim_semantics and not self._saw_interim_this_turn:
                global_state_manager.increment_stt_observability("noInterimFallbackCount", 1)

            # â”€â”€ Chennai locality normalization (Sarvam mishear correction) â”€
            _orig_text = text
            text = _normalize_chennai_locality(text)
            if text != _orig_text:
                logger.info(f"[STT_Normalize] '{_orig_text}' -> '{text}'")
                # Update frame so downstream pipeline sees corrected text
                try:
                    frame.text = text
                except Exception:
                    pass

            if self._tool_handler and hasattr(self._tool_handler, "rewrite_confirmation_reply"):
                _rewritten = self._tool_handler.rewrite_confirmation_reply(text)
                if _rewritten and _rewritten != text:
                    logger.info(f"[ValueConfirm] Rewrote user reply '{text}' -> '{_rewritten}'")
                    text = _rewritten
                    try:
                        frame.text = text
                    except Exception:
                        pass

            if (
                self._stt_provider_profile.get("sttProvider") == "sarvam"
                and self._stt_provider_profile.get("mode") == "codemix"
            ):
                global_state_manager.increment_stt_observability("codemixTranscriptCount", 1)
            elif self._stt_provider_profile.get("sttProvider") == "azure":
                _frame_lang = str(getattr(frame, "language", "") or "").strip()
                if _frame_lang:
                    _azure_updates = {"sttFinalLanguage": _frame_lang}
                    if self._stt_provider_profile.get("language_strategy") == "auto":
                        _azure_updates["sttAutoDetectedLanguage"] = _frame_lang
                    global_state_manager.update_stt_observability(_azure_updates)

            # â”€â”€ STATE: User started speaking â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
            # Check if user interrupted while agent was speaking
            if global_state_manager.is_speaking():
                if not self._assistant_audio_is_live():
                    logger.info("[STATE] speaking state stale - treating user speech as normal turn")
                    global_state_manager.set_state(AgentState.IDLE)
                else:
                    self._refresh_speaking_phase()
                    _interrupted_prompt = (
                        global_state_manager.current_assistant_text()
                        or global_state_manager.latest_assistant_text
                        or global_state_manager.get_interrupted_text()
                        or ""
                    )
                    _decision = classify_interrupt_decision(
                        frame.text or "",
                        interrupted_prompt=_interrupted_prompt,
                        last_topic=global_state_manager.last_topic,
                        assistant_is_synthetic=self._current_assistant_is_synthetic,
                        speaking_phase=self._speaking_phase,
                        is_final=True,
                    )
                    global_state_manager.note_interrupt_candidate(
                        _decision.kind,
                        text=frame.text or "",
                        reason=_decision.reason,
                    )
                    if self._shadow_turn_adapter:
                        self._shadow_turn_adapter.on_end_of_turn(
                            frame.text or "",
                            {
                                "candidate_kind": _decision.kind,
                                "speaking_phase": self._speaking_phase,
                                "production_commit": _decision.should_commit,
                            },
                        )
                    _decision = self._speaker_separation_gate(_decision, frame.text or "", is_final=True)
                    logger.info(
                        f"[INTERRUPT_CLASSIFY] kind={_decision.kind} commit={_decision.should_commit} "
                        f"pause={_decision.should_pause} resume={_decision.should_resume} "
                        f"reason={_decision.reason} text={frame.text!r}"
                    )
                    if not _decision.should_commit:
                        logger.info(f"[INTERRUPT_IGNORE] kind={_decision.kind} text={text!r}")
                        self._speech_start_candidate_ts = None
                        self._saw_interim_this_turn = False
                        return
                    logger.info(f"[STATE] User interrupted during SPEAKING state")
                    global_state_manager.note_interrupt_commit(
                        _decision.kind,
                        text=frame.text or "",
                        reason=_decision.reason,
                    )
                    if self._tool_handler and self._tool_handler.shortlist_is_pending_delivery():
                        self._tool_handler.note_shortlist_interrupted(_decision.reason or "final_interrupt")
                    if not self._supports_interim_semantics:
                        global_state_manager.increment_stt_observability("finalOnlyInterruptCommits", 1)
                    await self._dispatch_true_interruption("final_speech_interrupt", frame.text or "")
                    global_state_manager.record_interruption(global_state_manager.get_interrupted_text())
                    self.mark_assistant_audio_stopped()
                    if _decision.kind == "synthetic_checkin_reply":
                        await self._cancel_interrupt_followup()
                        global_state_manager.set_state(AgentState.IDLE)
                        return
                    if _decision.kind == "hold":
                        await self._cancel_interrupt_followup()
                        if _decision.should_resume:
                            self._clear_soft_hold("resume_confirmation")
                            await self._resume_interrupted_speech(_decision.reason or "resume_confirmation")
                            self._speech_start_candidate_ts = None
                            self._saw_interim_this_turn = False
                        else:
                            await self._handle_soft_hold(frame.text or "", _decision.reason or "hold_intent")
                            self._speech_start_candidate_ts = None
                            self._saw_interim_this_turn = False
                        return
                    global_state_manager.set_state(AgentState.THINKING)
                    logger.info("[INTERRUPT] Contextual interruption - routing through normal LLM turn")
            
            # Set state to LISTENING when user speech is finalized
            global_state_manager.set_state(AgentState.LISTENING)
            self._speech_start_candidate_ts = None
            self._saw_interim_this_turn = False
            if self._soft_hold_is_active():
                if is_resume_confirmation(text):
                    logger.info(f"[SoftHold] resume_confirmation_handled text={text!r}")
                    self._clear_soft_hold("resume_confirmation")
                    await self._resume_interrupted_speech("resume_confirmation")
                    return
                _hold_prompt, _hold_should_resume = build_deterministic_interrupt_reply(text)
                if _hold_prompt and not _hold_should_resume:
                    logger.info(f"[SoftHold] repeated_hold_handled text={text!r}")
                    await self._handle_soft_hold(text, "hold_intent")
                    return
                logger.info(f"[SoftHold] substantive_followup_resumed text={text!r}")
                self._clear_soft_hold("substantive_followup")
            else:
                _hold_prompt, _hold_should_resume = build_deterministic_interrupt_reply(text)
                if _hold_prompt and not _hold_should_resume:
                    logger.info(f"[SoftHold] final_hold_handled text={text!r}")
                    await self._handle_soft_hold(text, "hold_intent")
                    return
            # Increment turn counter
            global_state_manager.increment_turn()

            confidence = 1.0
            try:
                if frame.result and hasattr(frame.result, 'channel'):
                    confidence = frame.result.channel.alternatives[0].confidence
                elif frame.result and isinstance(frame.result, dict):
                    confidence = frame.result.get('channel', {}).get('alternatives', [{}])[0].get('confidence', 1.0)
            except Exception:
                confidence = 1.0
            logger.info(f"ðŸŽ™ï¸ [STT_FINAL] lang={frame.language} confidence={confidence:.2f} text={frame.text!r}")

            if self._context_ref and self._context_ref[0]:
                _removed = _strip_recent_synthetic_context_messages(self._context_ref[0])
                if _removed:
                    logger.info(f"[SyntheticContext] Removed {_removed} synthetic assistant message(s) before real turn")

            _now_stt = time.time()
            self._turn_ts_ref[0] = _now_stt
            self._turn_ts_ref[1] = text[:60]
            self._latency_trace_ref[0] = {
                "turn_start": _now_stt, "stt_final": _now_stt,
                "llm_start": None, "llm_first_token": None, "llm_end": None,
                "tool_start": None, "tool_end": None,
                "tts_start": None, "tts_end": None,
                "response_mode": None,
                "path_label": None,
                "router_decision_at": None,
                "router_ms": None,
                "tool_ms": None,
                "post_tool_ms": None,
                "first_sentence_ready_at": None,
                "first_sentence_ms": None,
                "tts_request_start": None,
                "tts_audio_first": None,
                "tts_ttfa_ms": None,
                "e2e_first_audio_ms": None,
                "cache_path_hit": False,
                "tool_skipped_for_cached_fact": False,
                "interrupt_recovery": False,
            }
            self._barge_fired = False
            self._interrupt_dispatched = False
            global_state_manager.clear_resume()
            if self._tool_handler is not None:
                self._tool_handler._turn_llm_fired = False
                self._tool_handler._turn_terminal_response_emitted = False
                self._tool_handler._last_inject_was_detail = False
                self._tool_handler._results_injected_this_turn = False
                self._tool_handler._gather_attempt_counts = {}
            if self._speaking_event:
                self._speaking_event.clear()

            if self._tool_handler:
                _th = self._tool_handler
                _routing = _th.classify_routing_intent(text)
                _routing_intent = _routing.get("intent") or "normal"
                _routing_count = _routing.get("requested_result_count")
                _ctx_messages = []
                if self._context_ref and self._context_ref[0] and hasattr(self._context_ref[0], "messages"):
                    _ctx_messages = self._context_ref[0].messages
                _expected_field = _detect_expected_gather_field(
                    _ctx_messages,
                    city=(_th._gathered_search.get("city") or "Chennai"),
                ) if _ctx_messages else None
                _search_key_snapshot = "|".join([
                    str(_th._gathered_search.get("city") or "").strip().lower(),
                    str(_th._gathered_search.get("location") or "").strip().lower(),
                    str(_th._gathered_search.get("property_type") or "").strip().lower(),
                    str(_th._gathered_search.get("bedrooms") or "").strip().lower(),
                    str(_th._gathered_search.get("project_category") or "").strip().lower(),
                    str(_th._gathered_search.get("construction_state") or "").strip().lower(),
                    str(_th._gathered_search.get("min_price") or ""),
                    str(_th._gathered_search.get("max_price") or ""),
                ])
                _scope_key_snapshot = _th._build_conversation_scope_key()
                _backend_key_match = bool(_search_key_snapshot and _search_key_snapshot == getattr(_th, '_backend_search_key', ''))
                _scope_key_match = bool(_scope_key_snapshot and _scope_key_snapshot == getattr(_th, '_conversation_scope_key', ''))
                _pending_budget_confirmation = bool(getattr(_th, "_pending_budget_confirmation", None))
                _pending_zero_result_mode = ((_th._zero_result_state or {}).get("mode") if getattr(_th, "_zero_result_state", None) else None)
                _locked_property_target = ((_th.current_locked_property_target() or {}).get("property_id") if hasattr(_th, "current_locked_property_target") else None)
                logger.info(
                    f"[RoutingAudit] intent={_routing_intent} expected_gather_field={_expected_field} "
                    f"selection_pending={getattr(_th, '_selection_pending', False)} "
                    f"shortlist_stage={getattr(_th, '_shortlist_presentation_stage', SHORTLIST_STAGE_INACTIVE)} "
                    f"variant_pending={bool(getattr(_th, '_pending_variant_selection', None))} "
                    f"active_property_id={getattr(_th, '_active_property_id', None)} "
                    f"backend_key_match={_backend_key_match} "
                    f"scope_key_match={_scope_key_match} "
                    f"result_count={_routing_count or _th._gathered_search.get('result_count')} "
                    f"citywide_search={bool(_th._gathered_search.get('_citywide_search'))} "
                    f"budget_flexible={bool(_th._gathered_search.get('_budget_flexible'))} "
                    f"pending_budget_confirmation={_pending_budget_confirmation} "
                    f"pending_zero_result_mode={_pending_zero_result_mode} "
                    f"locked_property_target={_locked_property_target} "
                    f"shortlist_exposure={getattr(_th, '_shortlist_exposure_bucket', 'none')} "
                    f"response_mode={(self._latency_trace_ref[0] or {}).get('response_mode')}"
                )
                _callback_ack_reply = _th.build_recent_callback_ack_response(text)
                if _callback_ack_reply and self._is_pending_offer_affirmative(text):
                    self._inject_offer_clarification("CallbackAck", text)
                    await self.push_frame(frame, direction)
                    return
                if _callback_ack_reply:
                    self._latency_trace_ref[0]["cache_path_hit"] = True
                    self._latency_trace_ref[0]["path_label"] = "deterministic_callback_ack"
                    logger.info(f"[CallbackIntent] deterministic_followup_path=callback_ack text={text!r}")
                    if self._context_ref and self._context_ref[0]:
                        _ctx = self._context_ref[0]
                        _ctx.messages.append({"role": "user", "content": text})
                        _ctx.messages.append({"role": "assistant", "content": _callback_ack_reply})
                    await self._speak_logged_direct_text(
                        _callback_ack_reply,
                        response_mode="deterministic_callback_ack",
                    )
                    return
                _pending_offer_explicit_intent = self._extract_booking_intent(text)
                if (
                    _pending_offer_explicit_intent == "site_visit"
                    and not (
                        getattr(_th, "_active_property_id", None)
                        or getattr(_th, "_active_property_name", None)
                    )
                    and _th.has_active_shortlist_context()
                ):
                    if await self._ask_site_visit_property_choice(
                        text,
                        source="shortlist_site_visit_intent",
                    ):
                        return
                if (
                    _pending_offer_explicit_intent
                    and getattr(_th, "_pending_user_offer", None)
                    and (
                        getattr(_th, "_active_property_id", None)
                        or getattr(_th, "_active_property_name", None)
                        or (_th._pending_user_offer or {}).get("property_name")
                    )
                ):
                    _offer_property_name = _th.safe_callback_property_name()
                    if _pending_offer_explicit_intent == "site_visit":
                        if await self._begin_site_visit_collection(
                            text,
                            _offer_property_name,
                            source="pending_offer_explicit_intent",
                        ):
                            return
                    if self._inject_booking_intent_directive(
                        _pending_offer_explicit_intent,
                        _offer_property_name,
                        source="pending_offer_explicit_intent",
                    ):
                        await self.push_frame(frame, direction)
                        return
                if _th.is_callback_request(text):
                    _callback_property_name = _th.safe_callback_property_name()
                    _th.clear_pending_property_lookup()
                    _th.clear_pending_property_callback_offer()
                    _th.clear_pending_user_offer("callback_requested")
                    if self._context_ref and self._context_ref[0]:
                        _ctx = self._context_ref[0]
                        _ctx.messages.append({
                            "role": "system",
                            "content": (
                                "USER REQUESTED A CALLBACK. You MUST call submit_callback IMMEDIATELY "
                                f"with propertyName='{_callback_property_name}' and "
                                f"city='{_th._gathered_search.get('city') or 'Chennai'}'. "
                                "Do not treat the callback sentence as a property name. "
                                "Do not search, refine filters, or ask the user to choose a property first. "
                                "Do not say any acknowledgement before the tool call. "
                                "After the tool returns, do not continue; the tool handler will speak the confirmation."
                            ),
                        })
                        logger.info(
                            f"[CallbackIntent] Direct callback request -> force submit_callback "
                            f"propertyName={_callback_property_name!r}"
                        )
                        await self.push_frame(frame, direction)
                        return
                if _th.is_property_booking_intent(text) and (
                    getattr(_th, "_active_property_id", None)
                    or getattr(_th, "_active_property_name", None)
                ):
                    _booking_property_name = _th.safe_callback_property_name()
                    _explicit_booking_intent = self._extract_booking_intent(text)
                    if _explicit_booking_intent:
                        if _explicit_booking_intent == "site_visit":
                            if await self._begin_site_visit_collection(
                                text,
                                _booking_property_name,
                                source="active_property_booking_next_steps",
                            ):
                                return
                        if self._inject_booking_intent_directive(
                            _explicit_booking_intent,
                            _booking_property_name,
                            source="active_property_booking_next_steps",
                        ):
                            await self.push_frame(frame, direction)
                            return
                    _booking_reply = _th.build_property_booking_next_steps_text(_booking_property_name)
                    _th.set_pending_property_callback_offer(_booking_property_name)
