# Transfer Call Detector
# â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

class TransferCallDetector(FrameProcessor):
    """
    Watches LLM output for the transfer confirmation trigger phrase.
    When detected, calls the backend /api/transfer-call and then ends
    the AI leg of the call so the human-to-human conversation continues.

    Flow:
      1. LLM (guided by system prompt injection) asks user to confirm transfer.
      2. User confirms â†’ LLM outputs TRANSFER_CALL_NOW as a standalone response.
      3. This detector catches it, strips it from TTS output, triggers the transfer.
    """

    TRIGGER = "transfer_call_now"

    def __init__(self, call_id: str, transfer_number: str, backend_url: str,
                 call_end_event_ref: list, task_ref: list,
                 ws_ref: list = None, room_id_ref: list = None):
        super().__init__()
        self._call_id = call_id
        self._transfer_number = transfer_number
        self._backend_url = backend_url
        self._call_end_event_ref = call_end_event_ref
        self._task_ref = task_ref
        self._ws_ref = ws_ref or []
        self._room_id_ref = room_id_ref or []
        self._buffer = ""
        self._triggered = False
        self._suppress_output = False  # suppress TTS of trigger phrase

    async def process_frame(self, frame, direction):
        await super().process_frame(frame, direction)

        if isinstance(frame, TextFrame):
            self._buffer += frame.text.lower()
            # Suppress the raw trigger phrase from TTS
            if self.TRIGGER in self._buffer:
                self._suppress_output = True
                return  # don't push this text frame downstream

        if isinstance(frame, LLMFullResponseEndFrame):
            triggered = self.TRIGGER in self._buffer
            self._buffer = ""
            if triggered and not self._triggered:
                self._triggered = True
                logger.info(f"[Transfer] Trigger detected - initiating transfer to {self._transfer_number}")
                asyncio.create_task(self._do_transfer())
                return  # don't push end frame yet; _do_transfer will end the call

        await self.push_frame(frame, direction)

    async def _do_transfer(self):
        import aiohttp
        try:
            payload = {
                "call_id": self._call_id,
                "destination_number": self._transfer_number,
            }
            async with aiohttp.ClientSession() as session:
                async with session.post(
                    f"{self._backend_url}/api/transfer-call",
                    json=payload,
                    timeout=aiohttp.ClientTimeout(total=10),
                ) as resp:
                    result = await resp.json()
                    if result.get("ok") or result.get("status") == "ok":
                        logger.info(f"[Transfer] Transfer succeeded: {self._transfer_number}")
                    else:
                        logger.warning(f"[Transfer] Backend returned non-ok: {result}")
        except Exception as e:
            logger.error(f"[Transfer] Transfer request failed: {e}")

        # End the AI pipeline leg - human takes over
        call_end_event = self._call_end_event_ref[0] if self._call_end_event_ref else None
        task = self._task_ref[0] if self._task_ref else None
        if call_end_event:
            call_end_event.set()
        if task:
            try:
                await task.queue_frame(EndFrame())
            except Exception:
                pass


# â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
# Integration Tool Handler
# â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

# Acknowledgment-only patterns suppressed while a tool fetch is in flight.
# Prevents "okay" / "sure" from reaching the LLM as a spurious user turn.
_ACK_ONLY_RE = re.compile(
    r"^\s*("
    r"ok(?:ay)?|sure|alright|right|got\s+it|yeah|yes|yep|h+m+|uh[- ]?huh|fine|"
    r"go\s+ahead|please|sounds\s+good|okay\s+sure|"
    # "hello?" / "are you there?" / "hello are you searching?" spoken while waiting for tool result
    r"hel+o+\??|are\s+you\s+(there|still\s+there|searching|looking|finding|checking)\??|"
    r"hello\s*,?\s*(are\s+you\s+there|can\s+you\s+hear\s+me)\??|"
    r"still\s+(there|searching|looking)\??|"
    r"à¤ à¥€à¤•\s*à¤¹à¥ˆ|à¤¹à¤¾à¤|à¤œà¥€\s*à¤¹à¤¾à¤|à¤“à¤•à¥‡|à¤¬à¤¿à¤²à¥à¤•à¥à¤²|à¤œà¥€"
    r")\s*[.!?]?\s*$",
    re.IGNORECASE | re.UNICODE,
)

# Budget qualifier patterns used across the codebase
_CAP_BUDGET_RE = re.compile(
    r'\b(under|within|below|less\s+than|max(?:imum)?|upto|up\s+to|'
    r'not\s+more|no\s+more|at\s+most|atmost)\b',
    re.IGNORECASE,
)
_FLOOR_BUDGET_RE = re.compile(
    r'\b(above|more\s+than|min(?:imum)?|at\s+least|atleast|'
    r'starting\s+from|at\s+minimum|minimum\s+of)\b',
    re.IGNORECASE,
)


class ToolAckFilter(FrameProcessor):
    """Drops acknowledgment / reconnect TranscriptionFrames that would break conversation.

    Two suppression modes:
    1. TOOL-ACTIVE: While tool_handler.filler_active, any _ACK_ONLY_RE match is dropped
       (prevents "okay"/"sure" reaching the LLM during a tool fetch).
    2. MID-CALL: After the first assistant response (conversation_started), standalone
       "hello?" / "are you there?" utterances are ALSO suppressed. The user saying
       "hello?" mid-call should never cause the LLM to reset context and re-introduce
       itself - we instead rely on the system prompt to handle it gracefully.
    """

    # Standalone "hello" patterns that reset context mid-call (suppressed after first turn)
    _HELLO_RE = re.compile(
        r'^\s*('
        r'hel+o+\??|hello\s*,?\s*(are\s+you\s+there|can\s+you\s+hear\s+me)\??|'
        r'are\s+you\s+(there|still\s+there|searching|looking|finding|checking)\??|'
        r'still\s+(there|searching|looking)\??'
        r')\s*[.!?]?\s*$',
        re.IGNORECASE | re.UNICODE,
    )

    def __init__(self, tool_handler: "IntegrationToolHandler", **kwargs):
        super().__init__(**kwargs)
        self._tool_handler = tool_handler
        self._conversation_started = False  # True after first assistant TTS response

    async def process_frame(self, frame, direction):
        # Always call super first - Pipecat base class tracks StartFrame/EndFrame lifecycle.
        await super().process_frame(frame, direction)

        # Track when the assistant has started speaking (first real response)
        if direction == FrameDirection.DOWNSTREAM and isinstance(frame, TTSStoppedFrame):
            self._conversation_started = True

        if direction == FrameDirection.DOWNSTREAM and isinstance(frame, TranscriptionFrame):
            text = (frame.text or "").strip()

            # Drop acknowledgment-only utterances while a tool fetch is in flight
            if self._tool_handler.filler_active and _ACK_ONLY_RE.match(text) and not self._HELLO_RE.match(text):
                logger.debug(f"[ToolAckFilter] Suppressed ack during tool call: {repr(text)}")
                return  # drop

            # Drop mid-call "hello?" only once the conversation is stable.
            # During active tool wait we let TranscriptionLogger decide whether this is a
            # progress check that deserves a spoken status update.
            if self._conversation_started and not self._tool_handler.filler_active and self._HELLO_RE.match(text):
                logger.info(f"[ToolAckFilter] Suppressed mid-call hello: {repr(text)}")
                return  # drop

        await self.push_frame(frame, direction)


# Short bridging phrases played during the silence while the LLM is thinking.
# Rotated per-call so the same phrase isn't repeated back-to-back.
_THINKING_FILLER_PHRASES = [
]  # disabled
_THINKING_FILLER_PHRASES_OLD = [
    "Let me think about that.",
    "One moment please.",
    "Just a second.",
]

SEARCH_WAIT_INTERIM_THRESHOLD_MS = 1000
SHORTLIST_STAGE_INACTIVE = "inactive"
SHORTLIST_STAGE_PREPARED = "prepared"
SHORTLIST_STAGE_STARTED = "started"
SHORTLIST_STAGE_PARTIAL = "partial"
SHORTLIST_STAGE_COMMITTED = "committed"


_FUNC_COMPLETE_RE = re.compile(r'<function=\w+>[\s\S]*?</function>|<\|python_tag\|>[\s\S]*?<\|eom_id\|>', re.DOTALL)
_FUNC_OPEN_RE    = re.compile(r'<function=\w+>|<\|python_tag\|>')

# Phrases the LLM emits before a tool call - should never reach TTS
_PREAMBLE_PREFIX_RE = re.compile(
    r'^\s*('
    r'allow me\b|let me\b|just a\s+(second|moment)\b|one moment\b|'
    r'searching\b|looking\s+for\b|finding\b|fetching\b|checking\b|'
    r'give me a\s+(second|moment)\b|hold on\b|please wait\b|'
    r"i'?ll\s+(search|look|find|check)\b|i\s+will\s+(search|look|find|check)\b|"
    r'right away\b|of course,?\s*(let|i\'ll|i\s+will)\b|'
    r'sure,?\s*(let|i\'ll|i\s+will)\b|certainly,?\s*(let|i\'ll|i\s+will)\b|'
    r'(sure|got it|noted|understood|alright|okay),?\s*let me\b|'
    r'(sure|got it|noted|understood|alright|okay),?\s*i(\'ll| will)\b'
    r')',
    re.IGNORECASE
)


class ToolPreambleFilter(FrameProcessor):
    """Suppresses LLM preamble text that appears immediately before a tool call.

    When the LLM says "Allow me a moment to find properties" and then emits
    <function=search_properties>, two problems occur:
    1. The phrase gets spoken aloud (bad UX - creates awkward pause during tool call)
    2. The phrase is recorded as an assistant turn in the LLM context, which can
       confuse Pipecat's context aggregator and cause the tool result to be silently
       dropped (the agent goes silent after the phrase).

    This filter:
    - On first text frame: if text starts with a known preamble pattern â†’ hold it
    - While holding: accumulate subsequent frames
    - If <function= markup appears â†’ discard all held frames (was a preamble)
    - If LLMFullResponseEnd arrives without a function call â†’ flush held frames normally
    - If multi-sentence text is detected while holding â†’ flush immediately (not preamble)

    Must be placed BEFORE FunctionCallTextFilter so it sees raw <function= tokens.
    """

    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self._held: list = []
        self._holding: bool = False
        self._func_seen: bool = False

    async def process_frame(self, frame, direction):
        await super().process_frame(frame, direction)

        if isinstance(frame, LLMFullResponseStartFrame):
            self._held = []
            self._holding = False
            self._func_seen = False
            await self.push_frame(frame, direction)
            return

        if isinstance(frame, LLMFullResponseEndFrame):
            if self._held:
                if self._func_seen:
                    _dropped = "".join(f.text for f in self._held)
                    logger.info(f"[PreambleFilter] Dropped before tool call: {_dropped!r}")
                else:
                    # GPT-4.1-nano emits tool calls at the API level (not as text tokens),
                    # so _FUNC_OPEN_RE never fires. If the held text still looks like a
                    # pure search/check preamble, drop it here to avoid hearing it once
                    # before the tool result and then again inside the real answer.
                    _accumulated = "".join(f.text for f in self._held)
                    _word_count = len(_accumulated.split())
                    if _PREAMBLE_PREFIX_RE.match(_accumulated) and re.search(
                        r'\b(search|look|find|check|fetch)\b',
                        _accumulated,
                        re.IGNORECASE,
                    ):
                        logger.info(f"[PreambleFilter] Dropped tool preamble: {_accumulated!r}")
                    elif _PREAMBLE_PREFIX_RE.match(_accumulated) and _word_count <= 12:
                        logger.info(f"[PreambleFilter] Dropped short structured-tool preamble: {_accumulated!r}")
                    elif _word_count <= 10:
                        logger.debug(f"[PreambleFilter] Short preamble flushed ({_word_count}w): {_accumulated!r}")
                        for f in self._held:
                            await self.push_frame(f, direction)
                    else:
                        # Long preamble with no function call - also flush (real speech).
                        logger.debug(f"[PreambleFilter] Long non-function preamble flushed: {_accumulated!r}")
                        for f in self._held:
                            await self.push_frame(f, direction)
                self._held = []
                self._holding = False
            await self.push_frame(frame, direction)
            return

        # Plain TextFrame (from UserFarewellDetector, EndCallDetector, system injectors, etc.)
        # must NEVER be held - only LLMTextFrame (LLM stream output) should be filtered.
        # Without this guard, farewell text gets buffered and never spoken (silent goodbye).
        if isinstance(frame, TextFrame) and not isinstance(frame, LLMTextFrame):
            await self.push_frame(frame, direction)
            return

        if isinstance(frame, (LLMTextFrame, TextFrame)):
            text = frame.text or ""

            # Once a function call is detected, just pass everything through
            if self._func_seen:
                await self.push_frame(frame, direction)
                return

            # Detect function call markup in this frame
            if _FUNC_OPEN_RE.search(text):
                self._func_seen = True
                if self._held:
                    _dropped = "".join(f.text for f in self._held)
                    logger.info(f"[PreambleFilter] Dropped {len(self._held)} held frame(s): {_dropped!r}")
                    self._held = []
                    self._holding = False
                await self.push_frame(frame, direction)
                return

            if self._holding:
                self._held.append(frame)
                accumulated = "".join(f.text for f in self._held)
                # Multi-sentence check: if text contains a sentence end followed by
                # more content, this is real speech - flush everything immediately
                if re.search(r'[.!?]\s+\S', accumulated):
                    logger.debug(f"[PreambleFilter] Multi-sentence - flushing: {accumulated!r}")
                    self._holding = False
                    for f in self._held:
                        await self.push_frame(f, direction)
                    self._held = []
                return

            # First text frame in response - check if it starts a preamble
            if _PREAMBLE_PREFIX_RE.match(text):
                self._holding = True
                self._held.append(frame)
                return

        await self.push_frame(frame, direction)


class FunctionCallTextFilter(FrameProcessor):
    """Strips inline function-call markup from the LLM text stream before it hits TTS.

    Groq Llama emits function calls both as structured tool_calls (handled by Pipecat)
    AND as inline text: <function=name>{...}</function>. Without this filter the raw
    JSON markup gets spoken aloud.

    Two-pass strategy:
    1. Regex - strips complete <function=...>...</function> blocks when the whole call
       arrives in a single frame (most common with llama-3.1-8b-instant).
    2. State - if only the opening tag is present (streaming multi-token case), enters
       suppression mode and drops all frames until the closing tag arrives.

    Handles both LLMTextFrame and plain TextFrame - Groq may emit either type.
    """

    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self._suppressing = False

    async def process_frame(self, frame, direction):
        await super().process_frame(frame, direction)

        if isinstance(frame, LLMFullResponseEndFrame):
            self._suppressing = False  # reset for next response

        elif isinstance(frame, (LLMTextFrame, TextFrame)):
            text = frame.text or ""

            if self._suppressing:
                # Multi-token suppression: drop until closing tag
                if "</function>" in text or "<|eom_id|>" in text:
                    self._suppressing = False
                return  # always drop while suppressing

            if _FUNC_OPEN_RE.search(text):
                # Pass 1: strip any complete function-call blocks
                cleaned = _FUNC_COMPLETE_RE.sub("", text).strip()
                # Pass 2: if an unclosed opening tag remains, start suppression
                m = _FUNC_OPEN_RE.search(cleaned)
                if m:
                    before = cleaned[: m.start()].strip()
                    self._suppressing = True
                    if before:
                        await self.push_frame(type(frame)(before), direction)
                    return
                if not cleaned:
                    return  # entire frame was function markup - drop
                await self.push_frame(type(frame)(cleaned), direction)
                return

        await self.push_frame(frame, direction)


class PropertyHallucinationGuard(FrameProcessor):
    """Blocks LLM attempts to describe property details without calling get_property_details.

    When selection_pending is True and the LLM outputs text containing property descriptions
    (price, sqft, amenities, etc.) without calling the tool, this filter:
    1. Blocks the hallucinated text
    2. Logs the violation
    3. Optionally injects a reminder to call the tool

    This is a safety net behind the pre-LLM SelectionGuard in TranscriptionLogger.
    """

    # Patterns that indicate property description attempts
    _PROPERTY_DESC_PATTERNS = [
        re.compile(r'\b(price[d]?|cost|sq\.?ft|square feet|amenities|rera|possession|developer|builder)\b', re.I),
        re.compile(r'\b\d+\s*(sq\.?ft|sqft|square feet)\b', re.I),
        re.compile(r'\b\d+\s*(lakhs?|crores?|l|cr)\b', re.I),
        re.compile(r'\bhas\s+(pool|gym|club|park|security|elevator|lift)\b', re.I),
    ]

    def __init__(self, tool_handler=None, **kwargs):
        super().__init__(**kwargs)
        self._tool_handler = tool_handler
        self._blocked_this_turn = False
        self._emitted_chars_this_turn = 0

    async def process_frame(self, frame, direction):
        await super().process_frame(frame, direction)

        if isinstance(frame, LLMFullResponseStartFrame):
            self._blocked_this_turn = False
            self._emitted_chars_this_turn = 0

        elif isinstance(frame, (LLMTextFrame, TextFrame)):
            text = frame.text or ""

            # Check if we should guard against hallucinations
            if self._tool_handler and hasattr(self._tool_handler, '_selection_pending'):
                _th = self._tool_handler
                if (_th._selection_pending and _th._last_presented_properties
                        and not self._blocked_this_turn
                        and not _th._results_injected_this_turn
                        and not getattr(_th, "_pending_variant_selection", None)
                        and not getattr(_th, "_pending_property_lookup", None)
                        and not getattr(_th, "_pending_property_callback_offer", None)):
                    if getattr(_th, "consume_property_direct_speech_allowance", None):
                        try:
                            if _th.consume_property_direct_speech_allowance():
                                await self.push_frame(frame, direction)
                                return
                        except Exception:
                            pass
                    # Check if text contains property descriptions
                    _is_describing = any(p.search(text) for p in self._PROPERTY_DESC_PATTERNS)

                    if _is_describing:
                        # Block this text - it's a hallucination attempt
                        logger.warning(f"[HallucinationGuard] BLOCKED: '{text[:80]}...' - tool not called")
                        self._blocked_this_turn = True

                        if self._emitted_chars_this_turn <= 0:
                            _recovery_text = "Could you repeat or clarify what you need?"
                            logger.info(
                                f"[HallucinationGuard] recovery_injected "
                                f"turn_id={int(global_state_manager.turn_id or 0)}"
                            )
                            try:
                                if _th._context_ref and _th._context_ref[0]:
                                    _th._context_ref[0].messages.append({"role": "assistant", "content": _recovery_text})
                            except Exception:
                                pass
                            self._emitted_chars_this_turn += len(_recovery_text)
                            await self.push_frame(type(frame)(_recovery_text), direction)
                            return

                        # Inject a system reminder (will be processed by LLM)
                        if self._tool_handler._context_ref and self._tool_handler._context_ref[0]:
                            _ctx = self._tool_handler._context_ref[0]
                            _reminder = (
                                "STOP. You must call get_property_details to get accurate information. "
                                "Do NOT describe properties from memory. Call the tool now."
                            )
                            # Find the system message and append reminder
                            try:
                                for _msg in _ctx.messages:
                                    if _msg.get("role") == "system":
                                        _msg["content"] = _msg.get("content", "") + "\n\n" + _reminder
                                        break
                            except Exception:
                                pass

                        # Drop this frame
                        return

        if isinstance(frame, (LLMTextFrame, TextFrame)):
            self._emitted_chars_this_turn += len(frame.text or "")
        await self.push_frame(frame, direction)


class SarvamTextSanitizer(FrameProcessor):
    """Filter out problematic characters for Sarvam TTS (e.g., standalone dots).

    Sarvam TTS errors with 'Invalid Websocket request type 400' when receiving
    text that contains only punctuation like '.' without any actual words.
    This processor removes such frames before they reach TTS.
    """

    # Pattern to match text that is ONLY dots/spaces/punctuation (no letters/numbers)
    _DOTS_ONLY_RE = re.compile(r'^[\s.!?]*$')
    _TTS_LOCALITY_FIXES = (
        (re.compile(r"\bT\.\s*Nagar\b", re.IGNORECASE), "T Nagar"),
        (re.compile(r"\bT\.Nagar\b", re.IGNORECASE), "T Nagar"),
    )

    @classmethod
    def _normalize_spoken_localities(cls, text: str) -> str:
        cleaned = text
        for pattern, replacement in cls._TTS_LOCALITY_FIXES:
            cleaned = pattern.sub(replacement, cleaned)
        return cleaned

    async def process_frame(self, frame, direction):
        await super().process_frame(frame, direction)

        if isinstance(frame, (LLMTextFrame, TextFrame)):
            text = frame.text or ""
            # Check if text is only dots/spaces/punctuation
            if self._DOTS_ONLY_RE.match(text):
                logger.debug(f"[SarvamTextSanitizer] Dropping standalone punctuation frame: {repr(text)}")
                return  # drop the frame

            text = self._normalize_spoken_localities(text)
            # Also check for text that ends with standalone dots after content
            # e.g., "some text..." -> "some text" (removes trailing dots)
            cleaned = text.rstrip('. ')
            if cleaned != text:
                frame = type(frame)(cleaned)
            elif text != frame.text:
                frame = type(frame)(text)

            await self.push_frame(frame, direction)
        else:
            # Pass through all non-text frames (e.g., LLMContextFrame)
            await self.push_frame(frame, direction)


class TTSActivityLogger(FrameProcessor):
    """Lightweight TTS observability + per-turn latency tracking."""

    def __init__(self, label: str, mode: str, turn_ts_ref: list = None, call_latency_ref: list = None, latency_trace_ref: list = None, filler_playing_ref: list = None, transport=None, assistant_audio_active_ref: list = None, audible_output_state_provider=None, tool_handler=None, transcript_ledger_ref=None, **kwargs):
        super().__init__(**kwargs)
        self._label = label
        self._mode = mode
        self._text_parts: list[str] = []
        self._audio_chunks = 0
        self._audio_bytes = 0
        self._active = False
        self._llm_ended = False
        self._tts_start: float | None = None
        self._first_audio_logged = False
        # Shared ref [turn_start_ts, stt_text] set by TranscriptionLogger on FINAL
        self._turn_ts_ref = turn_ts_ref if turn_ts_ref is not None else [None, ""]
        # Shared list to aggregate turn latencies for end-of-call summary
        self._call_latency_ref = call_latency_ref if call_latency_ref is not None else []
        self._latency_trace_ref: list = latency_trace_ref if latency_trace_ref is not None else [{}]
        # Filler audio tracking for interruption
        self._filler_playing_ref = filler_playing_ref if filler_playing_ref is not None else [False]
        self._transport = transport
        self._assistant_audio_active_ref = assistant_audio_active_ref if assistant_audio_active_ref is not None else [False]
        self._audible_output_state_provider = audible_output_state_provider
        self._tool_handler = tool_handler
        self._transcript_ledger_ref = transcript_ledger_ref if transcript_ledger_ref is not None else [[]]
        # Latency tracking per turn
        self._stt_ms: int | None = None
        self._llm_ms: int | None = None
        self._tts_ms: int | None = None
        self._e2e_ms: int | None = None
        self._current_output_synthetic = False
        self._current_generation_id = 0
        self._pending_output_stop = False

    def _get_audible_output_state(self) -> dict:
        try:
            state = self._audible_output_state_provider() if self._audible_output_state_provider else None
        except Exception as exc:
            logger.debug(f"[{self._label}] audible output provider failed: {exc}")
            state = None
        if not isinstance(state, dict):
            state = {}
        state.setdefault("live", False)
        state.setdefault("queue_chunks", 0)
        state.setdefault("queued_ms", 0)
        state.setdefault("playout_end_in_ms", 0)
        return state

    def _finalize_output_stop_state(self, reason: str) -> None:
        global_state_manager.set_state(AgentState.IDLE)
        global_state_manager.finish_assistant_output(generation_id=self._current_generation_id or None)
        self._assistant_audio_active_ref[0] = False
        if self._tool_handler and hasattr(self._tool_handler, "clear_terminal_tool_response_flags"):
            self._tool_handler.clear_terminal_tool_response_flags(f"tts_output_stopped:{reason}")
        self._pending_output_stop = False
        self._active = False
        logger.info(f"[{self._label}] Output stop finalized reason={reason}")

    def _record_completed_turn_latency(self, completed_at: float | None = None) -> None:
        if self._call_latency_ref is None or self._current_output_synthetic:
            return
        if not self._latency_trace_ref or not isinstance(self._latency_trace_ref[0], dict):
            return
        t = self._latency_trace_ref[0]
        if t.get("_latency_recorded"):
            return
        if t.get("tool_start") and t.get("tool_end") and t.get("tool_ms") is None:
            t["tool_ms"] = int((t["tool_end"] - t["tool_start"]) * 1000)
        if t.get("tool_end") and t.get("first_sentence_ready_at") and t.get("post_tool_ms") is None:
            t["post_tool_ms"] = int((t["first_sentence_ready_at"] - t["tool_end"]) * 1000)
        _t0 = self._turn_ts_ref[0]
        if _t0 and self._e2e_ms is None:
            _end_ts = t.get("tts_audio_last") or t.get("tts_audio_first") or completed_at or time.time()
            self._e2e_ms = int((_end_ts - _t0) * 1000)
        self._call_latency_ref.append({
            "llm_ms": self._llm_ms,
            "tts_ms": self._tts_ms,
            "e2e_ms": self._e2e_ms,
            "response_mode": t.get("response_mode"),
            "path_label": t.get("path_label"),
            "router_ms": t.get("router_ms"),
            "tool_ms": t.get("tool_ms"),
            "post_tool_ms": t.get("post_tool_ms"),
            "first_sentence_ms": t.get("first_sentence_ms"),
            "tts_ttfa_ms": t.get("tts_ttfa_ms"),
            "e2e_first_audio_ms": t.get("e2e_first_audio_ms"),
            "cache_path_hit": bool(t.get("cache_path_hit")),
            "tool_skipped_for_cached_fact": bool(t.get("tool_skipped_for_cached_fact")),
            "interrupt_recovery": bool(t.get("interrupt_recovery")),
        })
        t["_latency_recorded"] = True

    def _complete_output_turn(self, reason: str, completed_at: float | None = None) -> None:
        self._finalize_output_stop_state(reason)
        try:
            transcription_logger.mark_assistant_audio_stopped()
        except Exception:
            pass
        logger.info(f"[{self._label}] audio chunks={self._audio_chunks} bytes={self._audio_bytes}")
        t = self._latency_trace_ref[0]
        try:
            logger.info(
                "[LATENCY_BREAKDOWN] "
                f"response_mode={t.get('response_mode')} | "
                f"path_label={t.get('path_label')} | "
                f"stt_to_llm_start={(t['llm_start'] - t['stt_final']) if t.get('stt_final') and t.get('llm_start') else 0:.3f}s | "
                f"ttft={(t['llm_first_token'] - t['llm_start']) if t.get('llm_first_token') and t.get('llm_start') else 0:.3f}s | "
                f"llm_total={(t['llm_end'] - t['llm_start']) if t.get('llm_end') and t.get('llm_start') else 0:.3f}s | "
                f"router_ms={int(t.get('router_ms') or 0)} | "
                f"tool_time={(t['tool_end'] - t['tool_start']) if t.get('tool_end') and t.get('tool_start') else 0:.3f}s | "
                f"post_tool_delay={(t['llm_start'] - t['tool_end']) if t.get('tool_end') and t.get('llm_start') else 0:.3f}s | "
                f"first_sentence_ms={int(t.get('first_sentence_ms') or 0)} | "
                f"tts_time={(t['tts_audio_last'] - t['tts_request_start']) if t.get('tts_audio_last') and t.get('tts_request_start') else 0:.3f}s | "
                f"e2e={(t['tts_audio_last'] - t['turn_start']) if t.get('tts_audio_last') and t.get('turn_start') else 0:.3f}s"
            )
        except Exception as _lt_err:
            logger.debug(f"[LATENCY_BREAKDOWN] failed: {_lt_err}")
        _t0 = self._turn_ts_ref[0]
        if _t0 and not self._current_output_synthetic:
            _now = completed_at or time.time()
            self._e2e_ms = int((_now - _t0) * 1000)
            _stt_str = f"STT ~{self._stt_ms}ms " if self._stt_ms else ""
            _llm_str = f"LLM {self._llm_ms}ms " if self._llm_ms else ""
            _tts_str = f"TTS {self._tts_ms}ms " if self._tts_ms else ""
            logger.info(f"â± TURN LATENCY - {_stt_str}{_llm_str}{_tts_str}| TOTAL E2E {self._e2e_ms}ms")
        self._record_completed_turn_latency(completed_at=completed_at)

    def finalize_deferred_output_stop_if_ready(self, reason: str) -> bool:
        if self._mode != "output" or not self._pending_output_stop:
            return False
        if self._get_audible_output_state().get("live"):
            return False
        self._complete_output_turn(reason, completed_at=time.time())
        return True

    async def process_frame(self, frame, direction):
        await super().process_frame(frame, direction)

        def _trace() -> dict:
            if self._latency_trace_ref and isinstance(self._latency_trace_ref[0], dict):
                return self._latency_trace_ref[0]
            return {}

        def _response_mode() -> str | None:
            return _trace().get("response_mode")

        if self._mode == "output" and self._pending_output_stop:
            self.finalize_deferred_output_stop_if_ready("next_frame")

        if isinstance(frame, LLMFullResponseStartFrame):
            self._text_parts.clear()
            self._audio_chunks = 0
            self._audio_bytes = 0
            self._active = True
            self._llm_ended = False
            self._first_audio_logged = False
            # Reset latency trackers for new turn
            self._stt_ms = None
            self._llm_ms = None
            self._tts_ms = None
            self._e2e_ms = None
            if self._mode == "input":
                self._current_generation_id = global_state_manager.begin_output_generation()
                self._current_output_synthetic = global_state_manager.current_assistant_is_synthetic()
                global_state_manager.begin_turn_ledger(
                    self._current_generation_id,
                    synthetic=self._current_output_synthetic,
                )
                self._tts_start = time.time()
                self._latency_trace_ref[0]["output_generation_id"] = self._current_generation_id
                if (
                    not self._current_output_synthetic
                    and self._latency_trace_ref[0].get("response_mode") in {None, "tool_wait_filler"}
                ):
                    self._latency_trace_ref[0]["response_mode"] = "llm_stream"
                    if not self._latency_trace_ref[0].get("path_label"):
                        self._latency_trace_ref[0]["path_label"] = "full_llm"
                self._latency_trace_ref[0]["llm_start"] = self._tts_start
                self._latency_trace_ref[0]["tts_start"] = self._tts_start
                _mode = _response_mode()
                _turn_start = self._latency_trace_ref[0].get("turn_start")
                if not self._latency_trace_ref[0].get("router_decision_at"):
                    self._latency_trace_ref[0]["router_decision_at"] = self._tts_start
                    if _turn_start:
                        self._latency_trace_ref[0]["router_ms"] = int((self._tts_start - _turn_start) * 1000)
                if not self._latency_trace_ref[0].get("first_sentence_ready_at"):
                    self._latency_trace_ref[0]["first_sentence_ready_at"] = self._tts_start
                    if _turn_start:
                        self._latency_trace_ref[0]["first_sentence_ms"] = int((self._tts_start - _turn_start) * 1000)
                _tool_end = self._latency_trace_ref[0].get("tool_end")
                if _tool_end and self._latency_trace_ref[0].get("post_tool_ms") is None:
                    self._latency_trace_ref[0]["post_tool_ms"] = int((self._tts_start - _tool_end) * 1000)
                # Log LLM TTFT = time from FINAL transcript to first LLM token
                _t0 = self._turn_ts_ref[0]
                if _t0 and not self._current_output_synthetic and _mode == "llm_stream":
                    self._llm_ms = int((self._tts_start - _t0) * 1000)
                    logger.info(f"ðŸ§  [LLM_TTFT] {self._llm_ms}ms | user: {self._turn_ts_ref[1]!r}")
                # â”€â”€ STATE: LLM started thinking â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                global_state_manager.set_state(AgentState.THINKING)
            else:
                self._current_generation_id = int(self._latency_trace_ref[0].get("output_generation_id") or 0)
            # Push downstream to SentenceStreamingTTS so it activates
            await self.push_frame(frame, direction)
            return

        elif self._mode == "input" and self._active and isinstance(frame, (LLMTextFrame, TextFrame)):
            text = (frame.text or "").strip()
            if text:
                self._text_parts.append(text)
                if _response_mode() == "llm_stream" and not self._latency_trace_ref[0].get("llm_first_token"):
                    self._latency_trace_ref[0]["llm_first_token"] = time.time()
            # Push frame downstream to SentenceStreamingTTS
            await self.push_frame(frame, direction)
            return

        elif self._mode == "output" and self._active and isinstance(frame, TTSAudioRawFrame):
            if isinstance(frame, TTSAudioRawFrame):
                audio = getattr(frame, "audio", None) or getattr(frame, "data", None) or b""
                if not audio:
                    logger.warning("[AUDIO_FLOW] empty audio frame detected")
                else:
                    _now = time.time()
                    self._audio_chunks += 1
                    self._audio_bytes += len(audio)
                    # â”€â”€ STATE: First audio frame - TTS is speaking â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                    if not self._first_audio_logged:
                        global_state_manager.set_state(AgentState.SPEAKING)
                        global_state_manager.note_audio_started()
                        try:
                            transcription_logger.mark_assistant_audio_started()
                        except Exception:
                            pass
                    self._assistant_audio_active_ref[0] = True
                    global_state_manager.note_audio_progress(len(audio), sample_rate=int(getattr(frame, "sample_rate", 24000) or 24000))
                    # Track last audio frame timestamp - used by LATENCY_BREAKDOWN for
                    # accurate tts_time (audio delivery end, not TTSStoppedFrame time).
                    self._latency_trace_ref[0]["tts_audio_last"] = _now
                    if not self._first_audio_logged:
                        _tts_req_start = self._latency_trace_ref[0].get("tts_request_start")
                        _tts_ref_start = self._latency_trace_ref[0].get("tts_start")  # = LLM start
                        _t0 = self._turn_ts_ref[0]
                        self._latency_trace_ref[0]["tts_audio_first"] = _now
                        if _tts_req_start:
                            # True Cartesia TTFA: from first run_tts() call to first audio frame
                            self._tts_ms = int((_now - _tts_req_start) * 1000)
                            self._latency_trace_ref[0]["tts_ttfa_ms"] = self._tts_ms
                            _pipeline_ms = int((_now - _tts_ref_start) * 1000) if _tts_ref_start else None
                            self._e2e_ms = int((_now - _t0) * 1000) if _t0 else None
                            self._latency_trace_ref[0]["e2e_first_audio_ms"] = self._e2e_ms
                            _pip_str = f" | pipeline_ttfa={_pipeline_ms}ms" if _pipeline_ms else ""
                            logger.info(f"ðŸ”Š [TTS_AUDIO_FIRST] cartesia_ttfa={self._tts_ms}ms{_pip_str} | e2e={self._e2e_ms}ms")
                        elif _tts_ref_start:
                            self._tts_ms = int((_now - _tts_ref_start) * 1000)
                            self._e2e_ms = int((_now - _t0) * 1000) if _t0 else None
                            self._latency_trace_ref[0]["tts_ttfa_ms"] = self._tts_ms
                            self._latency_trace_ref[0]["e2e_first_audio_ms"] = self._e2e_ms
                            logger.info(f"ðŸ”Š [TTS_AUDIO_FIRST] pipeline_ttfa={self._tts_ms}ms | e2e={self._e2e_ms}ms")
                        self._first_audio_logged = True
                        # â”€â”€ Filler audio interruption â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                        # If filler clip is playing, mark it as interrupted and flush audio buffer
                        if self._filler_playing_ref[0]:
                            self._filler_playing_ref[0] = False
                            # Flush any buffered filler audio before real TTS plays
                            try:
                                if self._transport and hasattr(self._transport, 'flush_audio'):
                                    await self._transport.flush_audio()
                                    logger.info("[Filler] Audio buffer flushed - real TTS starting")
                            except Exception as e:
                                logger.warning(f"[Filler] Flush failed (non-critical): {e}")
                                # Don't raise - failure here is non-critical
                            logger.info("[Filler] Real audio ready - filler interrupted")
            # Push all frames downstream to transport
            await self.push_frame(frame, direction)
            return

        # LLMFullResponseEndFrame: mark LLM as done and record timing for input mode.
        # For output mode, IDLE is triggered by TTSStoppedFrame (which arrives after all audio
        # has been delivered - see SentenceStreamingTTS.process_frame where flush_audio() is
        # called so Cartesia sends a "done" message, causing _words_task_handler to push
        # TTSStoppedFrame after the last audio chunk).
        if isinstance(frame, LLMFullResponseEndFrame):
            self._llm_ended = True
            if self._mode == "input":
                self._latency_trace_ref[0]["llm_end"] = time.time()
                # Input mode turn-end logging
                if self._active:
                    _now = time.time()
                    text = _fix_tts_sentence_boundaries(
                        _repair_tts_text_assembly(" ".join(self._text_parts).strip())
                    )
                    text = _cleanup_tts_text(text)
                    if text:
                        logger.info(f"[{self._label}] speak len={len(text)} preview={text[:120]!r}")
                        # â”€â”€ CONTEXT: Track topic for resume after interruption â”€â”€â”€â”€â”€
                        if not self._current_output_synthetic:
                            topic = extract_topic(text)
                            global_state_manager.last_topic = topic
                            global_state_manager.set_latest_assistant_text(text)
                            _skip_transcript_record = False
                            if self._tool_handler:
                                _kind = "assistant_reply"
                                _property_ids = []
                                if self._tool_handler._pending_variant_selection:
                                    _kind = "variant_clarification"
                                elif self._tool_handler.shortlist_is_pending_delivery() or self._tool_handler.shortlist_is_committed():
                                    _kind = "shortlist"
                                    _property_ids = [
                                        str(p.get("property_id") or p.get("project_slug") or "").strip()
                                        for p in (self._tool_handler._last_presented_properties or [])
                                        if str(p.get("property_id") or p.get("project_slug") or "").strip()
                                    ]
                                elif self._tool_handler.current_locked_property_target() or self._tool_handler._active_property_id:
                                    _kind = "property_detail"
                                    _property_ids = [
                                        str(
                                            (self._tool_handler.current_locked_property_target() or {}).get("property_id")
                                            or self._tool_handler._active_property_id
                                            or ""
                                        ).strip()
                                    ]
                                _skip_transcript_record = self._tool_handler.should_skip_duplicate_spoken_prompt(
                                    text,
                                    source=f"tts_{self._mode}",
                                )
                                if not _skip_transcript_record:
                                    self._tool_handler.remember_spoken_prompt(
                                        text,
                                        kind=_kind,
                                        property_ids=_property_ids,
                                        question_expected=text.rstrip().endswith("?"),
                                        source=f"tts_{self._mode}",
                                    )
                            logger.info(f"[CONTEXT] topic='{topic}'")
                            if not _skip_transcript_record:
                                _record_transcript_turn(self._transcript_ledger_ref, "assistant", text, source=f"tts_{self._mode}")
                    _t0 = self._turn_ts_ref[0]
                    if _t0 and not self._current_output_synthetic:
                        self._e2e_ms = int((_now - _t0) * 1000)
                        _stt_str = f"STT ~{self._stt_ms}ms " if self._stt_ms else ""
                        _llm_str = f"LLM {self._llm_ms}ms " if self._llm_ms else ""
                        _tts_str = f"TTS {self._tts_ms}ms " if self._tts_ms else ""
                        logger.info(f"â± TURN LATENCY - {_stt_str}{_llm_str}{_tts_str}| TOTAL E2E {self._e2e_ms}ms")
                    self._active = False
            elif self._mode == "output" and self._active:
                # By the time LLMFullResponseEndFrame reaches TTS-OUT, all audio has been delivered
                # (SentenceStreamingTTS awaits all push_frame calls before forwarding this frame).
                # Set IDLE state so idle timeout can fire if user stays silent.
                logger.info(f"[{self._label}] LLMFullResponseEndFrame â†’ awaiting TTSStoppedFrame")
            # Push downstream so context_aggregator writes the assistant message
            await self.push_frame(frame, direction)
            return

        # End-of-turn trigger for output mode:
        # TTSStoppedFrame arrives (via Cartesia _words_task_handler) after the "done" message,
        # which is sent once flush_audio() finalises the context. At that point _llm_ended=True
        # (set above when LLMFullResponseEndFrame arrived, before audio was delivered).
        if isinstance(frame, TTSStoppedFrame) and self._mode == "output" and self._llm_ended and self._active:
            _audible_state = self._get_audible_output_state()
            if _audible_state.get("live"):
                self._pending_output_stop = True
                logger.info(
                    f"[{self._label}] TTSStoppedFrame deferred until telephony playout drains "
                    f"(queue_chunks={_audible_state.get('queue_chunks')} "
                    f"queued_ms~={_audible_state.get('queued_ms')} "
                    f"playout_end_in_ms={_audible_state.get('playout_end_in_ms')})"
                )
                await self.push_frame(frame, direction)
                return
            # â”€â”€ STATE: TTS stopped - return to IDLE or LISTENING â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
            _now = time.time()
            self._finalize_output_stop_state("tts_stopped")
            try:
                transcription_logger.mark_assistant_audio_stopped()
            except Exception:
                pass
            logger.info(f"[{self._label}] audio chunks={self._audio_chunks} bytes={self._audio_bytes}")
            t = self._latency_trace_ref[0]
            try:
                # tts_time: from first run_tts() call to last audio frame (pure Cartesia span)
                # e2e: from user turn start to last audio frame delivered
                logger.info(
                    "[LATENCY_BREAKDOWN] "
                    f"response_mode={t.get('response_mode')} | "
                    f"stt_to_llm_start={(t['llm_start'] - t['stt_final']) if t.get('stt_final') and t.get('llm_start') else 0:.3f}s | "
                    f"ttft={(t['llm_first_token'] - t['llm_start']) if t.get('llm_first_token') and t.get('llm_start') else 0:.3f}s | "
                    f"llm_total={(t['llm_end'] - t['llm_start']) if t.get('llm_end') and t.get('llm_start') else 0:.3f}s | "
                    f"router_ms={int(t.get('router_ms') or 0)} | "
                    f"tool_time={(t['tool_end'] - t['tool_start']) if t.get('tool_end') and t.get('tool_start') else 0:.3f}s | "
                    f"post_tool_delay={(t['llm_start'] - t['tool_end']) if t.get('tool_end') and t.get('llm_start') else 0:.3f}s | "
                    f"first_sentence_ms={int(t.get('first_sentence_ms') or 0)} | "
                    f"tts_time={(t['tts_audio_last'] - t['tts_request_start']) if t.get('tts_audio_last') and t.get('tts_request_start') else 0:.3f}s | "
                    f"e2e={(t['tts_audio_last'] - t['turn_start']) if t.get('tts_audio_last') and t.get('turn_start') else 0:.3f}s"
                )
            except Exception as _lt_err:
                logger.debug(f"[LATENCY_BREAKDOWN] failed: {_lt_err}")
            _t0 = self._turn_ts_ref[0]
            if _t0 and not self._current_output_synthetic:
                self._e2e_ms = int((_now - _t0) * 1000)
                _stt_str = f"STT ~{self._stt_ms}ms " if self._stt_ms else ""
                _llm_str = f"LLM {self._llm_ms}ms " if self._llm_ms else ""
                _tts_str = f"TTS {self._tts_ms}ms " if self._tts_ms else ""
                logger.info(f"â± TURN LATENCY - {_stt_str}{_llm_str}{_tts_str}| TOTAL E2E {self._e2e_ms}ms")
                if self._call_latency_ref is not None and not self._current_output_synthetic:
                    if t.get("tool_start") and t.get("tool_end"):
                        t["tool_ms"] = int((t["tool_end"] - t["tool_start"]) * 1000)
                    if t.get("tool_end") and t.get("first_sentence_ready_at") and t.get("post_tool_ms") is None:
                        t["post_tool_ms"] = int((t["first_sentence_ready_at"] - t["tool_end"]) * 1000)
                    self._call_latency_ref.append({
                        "llm_ms": self._llm_ms,
                        "tts_ms": self._tts_ms,
                        "e2e_ms": self._e2e_ms,
                        "response_mode": t.get("response_mode"),
                        "router_ms": t.get("router_ms"),
                        "tool_ms": t.get("tool_ms"),
                        "post_tool_ms": t.get("post_tool_ms"),
                        "first_sentence_ms": t.get("first_sentence_ms"),
                        "tts_ttfa_ms": t.get("tts_ttfa_ms"),
                        "e2e_first_audio_ms": t.get("e2e_first_audio_ms"),
                        "cache_path_hit": bool(t.get("cache_path_hit")),
                        "tool_skipped_for_cached_fact": bool(t.get("tool_skipped_for_cached_fact")),
                    })
            self._active = False

        if isinstance(frame, InterruptionFrame) and self._mode == "output":
            self._assistant_audio_active_ref[0] = False
            global_state_manager.finish_assistant_output(generation_id=self._current_generation_id or None)
            try:
                transcription_logger.mark_assistant_audio_stopped()
            except Exception:
                pass

        await self.push_frame(frame, direction)


class AssistantContextGate(FrameProcessor):
    """Prevents synthetic assistant prompts from polluting assistant history."""

    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self._suppress_current_output = False

    async def process_frame(self, frame, direction):
        await super().process_frame(frame, direction)

        if isinstance(frame, LLMFullResponseStartFrame):
            self._suppress_current_output = global_state_manager.current_assistant_is_synthetic()
            if self._suppress_current_output:
                logger.debug("[AssistantContextGate] Suppressing synthetic assistant turn from context")
                return

        if self._suppress_current_output and isinstance(frame, (LLMTextFrame, TextFrame)):
            return

        if self._suppress_current_output and isinstance(frame, LLMFullResponseEndFrame):
            self._suppress_current_output = False
            return

        await self.push_frame(frame, direction)


_MONTHS_EN = [
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December",
]

_SMALL_NUMBER_WORDS = {
    0: "zero", 1: "one", 2: "two", 3: "three", 4: "four", 5: "five",
    6: "six", 7: "seven", 8: "eight", 9: "nine", 10: "ten",
    11: "eleven", 12: "twelve", 13: "thirteen", 14: "fourteen",
    15: "fifteen", 16: "sixteen", 17: "seventeen", 18: "eighteen",
    19: "nineteen", 20: "twenty", 30: "thirty", 40: "forty",
    50: "fifty", 60: "sixty", 70: "seventy", 80: "eighty",
    90: "ninety",
}


def _two_digit_words(n: int) -> str:
    if n < 20:
        return _SMALL_NUMBER_WORDS[n]
    tens = (n // 10) * 10
    ones = n % 10
    if ones == 0:
        return _SMALL_NUMBER_WORDS[tens]
    return f"{_SMALL_NUMBER_WORDS[tens]} {_SMALL_NUMBER_WORDS[ones]}"


def _year_to_spoken_words(year: int) -> str:
    if 2000 <= year <= 2009:
        tail = year - 2000
        return "two thousand" if tail == 0 else f"two thousand {_two_digit_words(tail)}"
    if 2010 <= year <= 2099:
        return f"twenty {_two_digit_words(year - 2000)}"
    return _num_to_indian_words(year)

def _num_to_indian_words(n: int) -> str:
    """Convert an integer to spoken Indian English (lakh/crore notation)."""
    if n == 0:
        return "zero"
    parts = []
    if n >= 10_000_000:
        c = n // 10_000_000
        parts.append(f"{c} crore")
        n %= 10_000_000
    if n >= 100_000:
        l = n // 100_000
        parts.append(f"{l} lakh")
        n %= 100_000
    if n >= 1_000:
        parts.append(f"{n // 1_000} thousand")
        n %= 1_000
    if n:
        parts.append(str(n))
    return " ".join(parts)


def _format_price_indian(value) -> str:
    try:
        amount = int(float(value))
    except Exception:
        return "price on request"
    if amount <= 0:
        return "price on request"
    return _num_to_indian_words(amount).title()


def _format_budget_range_phrase(min_price=None, max_price=None) -> str:
    try:
        min_value = int(float(min_price or 0))
    except Exception:
        min_value = 0
    try:
        max_value = int(float(max_price or 0))
    except Exception:
        max_value = 0
    if min_value > 0 and max_value > 0:
        return f"{_format_price_indian(min_value)} to {_format_price_indian(max_value)}"
    if max_value > 0:
        return f"up to {_format_price_indian(max_value)}"
    if min_value > 0:
        return f"from {_format_price_indian(min_value)}"
    return "your budget"


def _build_locality_budget_mismatch_speech(result: dict) -> str | None:
    if not isinstance(result, dict):
        return None
    data = result.get("data")
    if not isinstance(data, list) or not data:
        return None

    location = str(
        result.get("searched_location")
        or result.get("exact_location_searched")
        or result.get("location")
        or "this area"
    ).strip() or "this area"
    location = re.sub(r"\bT\.\s*Nagar\b", "T Nagar", location, flags=re.IGNORECASE)
    location = re.sub(r"\bT\.Nagar\b", "T Nagar", location, flags=re.IGNORECASE)

    property_type = (
        result.get("searched_property_type")
        or result.get("property_type")
        or "properties"
    )
    ptype_plural = _property_type_plural_label(property_type)
    user_budget = _format_budget_range_phrase(
        result.get("user_min_price"),
        result.get("user_max_price"),
    )

    prices = [
        _extract_search_item_min_price(item)
        for item in data
        if isinstance(item, dict)
    ]
    prices = [price for price in prices if price > 0]
    if prices:
        available_range = (
            f"{_format_price_indian(min(prices))} to {_format_price_indian(max(prices))}"
            if min(prices) != max(prices)
            else _format_price_indian(min(prices))
        )
    else:
        available_range = "a different budget range"

    return (
        f"I couldn't find {ptype_plural} in {location} within {user_budget}. "
        f"But there are {ptype_plural} available in {location} around {available_range}. "
        "Would you like to explore those?"
    )


_TTS_ASSEMBLY_CANONICAL_REPAIRS: tuple[tuple[re.Pattern, str], ...] = (
    (re.compile(r"\bN\s+ung\s+amb\s+akk\s+am\b", re.IGNORECASE), "Nungambakkam"),
    (re.compile(r"\bARC\s+Alc\s+azar\b", re.IGNORECASE), "ARC Alcazar"),
)


def _join_spoken_list(items: list[str]) -> str:
    cleaned = [str(item).strip() for item in items if str(item).strip()]
    if not cleaned:
        return ""
    if len(cleaned) == 1:
        return cleaned[0]
    if len(cleaned) == 2:
        return f"{cleaned[0]} and {cleaned[1]}"
    return f"{', '.join(cleaned[:-1])}, and {cleaned[-1]}"


def _build_areas_by_budget_speech(
    result: dict,
    *,
    origin_location: str | None = None,
    property_type: str | None = None,
    min_price: int | None = None,
    max_price: int | None = None,
) -> str | None:
    """Build deterministic alternative-area speech only from returned tool data."""
    if not isinstance(result, dict):
        return None
    areas = result.get("areas") or []
    if not isinstance(areas, list) or not areas:
        return None

    area_phrases: list[str] = []
    for area in areas[:3]:
        if isinstance(area, dict):
            name = str(area.get("name") or area.get("location") or area.get("area") or "").strip()
            count = area.get("property_count") or area.get("count") or area.get("total_count")
        else:
            name = str(area or "").strip()
            count = None
        if not name:
            continue
        try:
            count_int = int(count)
        except Exception:
            count_int = 0
        if count_int > 0:
            unit = "option" if count_int == 1 else "options"
            area_phrases.append(f"{name}, with {count_int} {unit}")
        else:
            area_phrases.append(name)

    if not area_phrases:
        return None

    ptype_plural = _property_type_plural_label(property_type or result.get("property_type") or "properties")
    budget_phrase = ""
    if min_price and max_price:
        budget_phrase = f" in your budget range of {_format_price_indian(min_price)} to {_format_price_indian(max_price)}"
    elif max_price:
        budget_phrase = f" within {_format_price_indian(max_price)}"
    elif min_price:
        budget_phrase = f" from {_format_price_indian(min_price)}"

    origin = str(origin_location or "").strip()
    if origin:
        return (
            f"You can try {_join_spoken_list(area_phrases)}. "
            "Which area would you like to explore?"
        )
    return (
        f"For {ptype_plural}{budget_phrase}, you can try {_join_spoken_list(area_phrases)}. "
        "Which area would you like to explore?"
    )


def _normalize_bhk_option_list_text(text: str) -> str:
    """Make compact BHK option lists explicit before generic number cleanup."""
    if not text:
        return text

    def _format_values(raw_values: str) -> str:
        values: list[str] = []
        for token in re.findall(r"\d+(?:\.\d+)?", raw_values or ""):
            if token and token not in values:
                values.append(token)
        if not values:
            return ""
        return _join_spoken_list([f"{value} BHK" for value in values])

    def _offers_sub(match: re.Match) -> str:
        verb = match.group(1)
        values = _format_values(match.group(2))
        tail = match.group(3) or ""
        if not values:
            return match.group(0)
        tail_lower = tail.lower()
        tail_text = " options" if "option" in tail_lower else (" units" if "unit" in tail_lower else "")
        return f"{verb} {values}{tail_text}"

    text = re.sub(
        r"\b(offers?|has|includes?)\s*"
        r"((?:(?:\d+(?:\.\d+)?)|,|and|&|\s){1,60})"
        r"(?:B\s*H\s*K|BHK)\s*(options?|units?)?\b",
        _offers_sub,
        text,
        flags=re.IGNORECASE,
    )

    # A narrower second pass catches already-spaced lists like "2 BHK, 3 and 4 BHK".
    def _list_sub(match: re.Match) -> str:
        values = _format_values(match.group(1))
        return values or match.group(0)

    return re.sub(
        r"\b((?:\d+(?:\.\d+)?\s*(?:,|and|&)\s*)+"
        r"\d+(?:\.\d+)?)\s*(?:B\s*H\s*K|BHK)\b",
        _list_sub,
        text,
        flags=re.IGNORECASE,
    )


def _repair_tts_text_assembly(text: str) -> str:
    """Repair token-boundary artifacts before sentence streaming and TTS."""
    if not text:
        return text
    original = text

    text = re.sub(r"\s+", " ", text).strip()
    for pattern, replacement in _TTS_ASSEMBLY_CANONICAL_REPAIRS:
        text = pattern.sub(replacement, text)
    text = re.sub(r"\bT\.\s+Nagar\b", "T Nagar", text, flags=re.IGNORECASE)
    text = re.sub(r"\bKam\s+dh\s+enu\b", "Kamdhenu", text, flags=re.IGNORECASE)
    text = re.sub(r"\bR\s+ough\s+ly\b", "Roughly", text, flags=re.IGNORECASE)
    text = _normalize_bhk_option_list_text(text)
    text = re.sub(r"\bBHK(?=and\b)", "BHK ", text, flags=re.IGNORECASE)

    # B HK / B H K are common LLM token-boundary artifacts for BHK.
    text = re.sub(r"\b([1-9]\d*)\s+B\s+H\s*K\b", r"\1 BHK", text, flags=re.IGNORECASE)
    text = re.sub(r"\b([1-9]\d*)\s+B\s+H\s+K\b", r"\1 BHK", text, flags=re.IGNORECASE)
    text = re.sub(r"\bB\s+H\s*K\b", "BHK", text, flags=re.IGNORECASE)
    text = re.sub(r"\bB\s+H\s+K\b", "BHK", text, flags=re.IGNORECASE)

    # Missing spaces at token boundaries: "from15", "for3", "at1", "are2".
    text = re.sub(
        r"\b(are|is|from|for|at|around|about|under|above|offers?|has|includes?|priced\s+at|starts?\s+from)(\d)",
        r"\1 \2",
        text,
        flags=re.IGNORECASE,
    )
    text = _normalize_bhk_option_list_text(text)
    text = re.sub(r"\bBHK(?=and\b)", "BHK ", text, flags=re.IGNORECASE)
    text = re.sub(r"\b(a|an)(\d+\s+BHK)\b", r"\1 \2", text, flags=re.IGNORECASE)
    text = re.sub(r"\b(crore|crores|lakh|lakhs|lack)(\d+)\b", r"\1 \2", text, flags=re.IGNORECASE)
    text = re.sub(
        r"\b(January|February|March|April|May|June|July|August|September|October|November|December)(\d+)\b",
        r"\1 \2",
        text,
        flags=re.IGNORECASE,
    )
    text = re.sub(r"\b(\d+)(BHK)\b", r"\1 \2", text, flags=re.IGNORECASE)

    # Missing sentence spaces/boundaries before common clause starters.
    text = re.sub(
        r"\b(lakh|lakhs|lack|crore|crores|security|parking|gym|park|backup|area|available|Nungambakkam)(It\s+includes|Possession\s+is|The\s+second\s+option|Would\s+you\s+like|We\s+have)\b",
        lambda m: f"{m.group(1)}. {m.group(2)}",
        text,
        flags=re.IGNORECASE,
    )
    text = re.sub(r"\b((?:19|20)\d{2})(Would\s+you\s+like|It\s+includes|Possession\s+is)\b", r"\1. \2", text)

    text = re.sub(r"\s+([,.!?])", r"\1", text)
    text = re.sub(r",(?=\d{4}\b)", ", ", text)
    text = re.sub(r"([.!?])(?=[A-Za-z])", r"\1 ", text)
    text = re.sub(r"\s+", " ", text).strip()

    if text != original:
        logger.debug(f"[TTSAssemblyRepair] {original!r} -> {text!r}")
    return text


def _normalize_tts_text(text: str) -> str:
    """Convert raw numbers, dates, and measurements in LLM output to natural spoken form.

    Handles the most common patterns that Cartesia reads digit-by-digit:
      â€¢ ISO dates:    2026-03-01 â†’ "1st March 2026"
      â€¢ Square feet:  104400 sqft â†’ "1 lakh 4 thousand 400 square feet"
      â€¢ INR prices:   â‚¹5000000 / Rs.5000000 â†’ "50 lakh rupees"
      â€¢ Large numbers (>=1 lakh) standalone â†’ Indian lakh/crore form
      â€¢ Ordinals:     1st/2nd/3rd already fine; bare "1" before month names â†’ "1st"
    """
    # â”€â”€ ISO dates: 2026-03-01 â†’ "1st March 2026" â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    text = _repair_tts_text_assembly(text)

    def _date_sub(m: re.Match) -> str:
        y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if not (1 <= mo <= 12 and 1 <= d <= 31):
            return m.group(0)
        suf = "th" if 11 <= d <= 13 else {1: "st", 2: "nd", 3: "rd"}.get(d % 10, "th")
        return f"{d}{suf} {_MONTHS_EN[mo - 1]} {y}"
    text = re.sub(r'\b(\d{4})-(\d{2})-(\d{2})\b', _date_sub, text)

    # â”€â”€ Square feet: 104400 sqft / sq ft / sq.ft â†’ spoken â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    def _sqft_sub(m: re.Match) -> str:
        n = int(m.group(1).replace(",", ""))
        return f"{_num_to_indian_words(n)} square feet"
    text = re.sub(
        r'\b(\d[\d,]{2,})\s*(?:sq\.?\s*ft\.?|sqft|square\s*feet)\b',
        _sqft_sub, text, flags=re.IGNORECASE,
    )

    # â”€â”€ INR with symbol/prefix: â‚¹5000000 / Rs.50,00,000 â†’ "50 lakh rupees" â”€â”€
    def _inr_sub(m: re.Match) -> str:
        n = int(re.sub(r"[,\s]", "", m.group(1)))
        unit = (m.group(2) or "").strip()
        if unit:
            return f"{_num_to_indian_words(n)} {unit} rupees"
        return f"{_num_to_indian_words(n)} rupees"
    text = re.sub(
        r'(?:â‚¹|Rs\.?\s*|INR\s*)(\d[\d,]+)(?:\s*(lakh|lakhs|lac|l|crore|crores|cr))?',
        _inr_sub, text, flags=re.IGNORECASE,
    )

    # Decimal crore values are easy for TTS/STT to collapse incorrectly
    # ("8.5 crore" -> "85 crore"). Expand them to crore+lakh explicitly.
    def _decimal_crore_sub(m: re.Match) -> str:
        whole = int(m.group(1))
        frac_raw = (m.group(2) or "").rstrip("0")
        if not frac_raw:
            return f"{whole} crore"
        frac_val = float(f"0.{frac_raw}")
        lakhs = int(round(frac_val * 100))
        if lakhs >= 100:
            whole += 1
            lakhs = 0
        return f"{whole} crore" + (f" {lakhs} lakh" if lakhs else "")
    text = re.sub(
        r'\b(\d+)\.(\d{1,2})\s*(?:cr|crore|crores)\b',
        _decimal_crore_sub,
        text,
        flags=re.IGNORECASE,
    )

    # â”€â”€ Standalone large numbers â‰¥ 1 lakh â†’ Indian words â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    # Excludes: 4-digit years (19xx/20xx), numbers already followed by a unit word,
    # and sequences that look like phone numbers (10+ consecutive digits).
    def _large_num_sub(m: re.Match) -> str:
        raw = m.group(0)
        n = int(raw.replace(",", ""))
        if n < 100_000:
            return raw  # already handled or small enough
        return _num_to_indian_words(n)

    # Only match numbers â‰¥ 6 digits that are NOT 4-digit years and NOT phone-like
    text = re.sub(
        r'\b(?<!\d)(\d{6,9})(?!\d)(?!\s*(?:sqft|sq|feet|rupees|lakh|crore|thousand))\b',
        lambda m: _num_to_indian_words(int(m.group(0))),
        text,
    )

    # â”€â”€ 4-digit years: 2023 â†’ "2 thousand 23" â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    # Cartesia reads bare 4-digit years digit-by-digit ("two zero two three").
    # Guard: skip years already consumed by the ISO-date rule above, and skip
    # ordinal suffixes (2023rd would be weird but just in case).
    text = re.sub(
        r'\b((?:19|20)\d{2})\b(?!\s*(?:st|nd|rd|th)\b)',
        lambda m: _year_to_spoken_words(int(m.group(1))),
        text,
    )

    # â”€â”€ Standalone 4-digit numbers (1000â€“9999, non-year) â†’ words â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    # Handles things like bare area figures ("1350" â†’ "1 thousand 350").
    # Guard: skip numbers already followed by a unit word, and skip pin-code-like
    # sequences (a bare 6-digit block immediately around them).
    text = re.sub(
        r'\b(?<!\d)([1-9]\d{3})\b(?!\d)(?!\s*(?:st|nd|rd|th|sqft|sq|ft|feet|rupees|lakh|crore|thousand))',
        lambda m: _num_to_indian_words(int(m.group(1))),
        text,
    )

    # â”€â”€ Pronunciation fix: 'lakh' â†’ 'Lack' (Indian English pronunciation) â”€â”€â”€â”€â”€
    # Cartesia TTS pronounces 'lakh' with a hard 'kh'; 'Lack' sounds more natural.
    text = re.sub(r'\blakh\b', 'Lack', text, flags=re.IGNORECASE)

    # â”€â”€ Chennai/Tamil name pronunciation pass â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    # Property/project pronunciation dictionary pass. Loaded once at startup
    # and applied in-memory before text reaches the TTS engine.
    text = normalize_text_for_tts(text)

    # Uses catalog-backed canonical names with targeted sounds-like overrides.
    text = apply_tamil_name_pronunciations(text)

    # â”€â”€ Strip unresolved {{template}} tokens â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    # Prevents "{{property_type}}" or "{{location}}" from being spoken aloud
    # if the LLM or a dashboard prompt leaks an unresolved template variable.
    text = re.sub(r'\{\{[^}]+\}\}', '', text).strip()

    # â”€â”€ Pause injection: '...' between items â†’ natural Cartesia pause â”€â”€â”€â”€â”€â”€â”€â”€â”€
    # Cartesia reads '...' as a natural pause. Normalise spacing around ellipses.
    text = re.sub(r'\s*\.\.\.\s*', ' ... ', text)

    # Make project names easier to understand in voice output by inserting a
    # short pause before the descriptor that follows the name.
    text = re.sub(
        r'\b([A-Z][A-Za-z0-9&\'\-]*(?:\s+[A-Z][A-Za-z0-9&\'\-]*){1,5})\s+(is|offers|comes|starts|starting|priced|located)\b',
        r'\1 ... \2',
        text,
    )
    text = re.sub(
        r'((?:top|best|first)\s+option(?:\s+is)?\s*(?:-|:)?\s*)([A-Z][A-Za-z0-9&\'\-]*(?:\s+[A-Z][A-Za-z0-9&\'\-]*){1,5})(\s*,)',
        r'\1\2 ... ,',
        text,
        flags=re.IGNORECASE,
    )

    return text


def _fix_tts_sentence_boundaries(text: str) -> str:
    """Ensure natural speaking pauses between sentences for the TTS engine.

    Cartesia (and other TTS engines) rely on punctuation to insert prosodic
    pauses. When the LLM generates run-on sentences - especially during property
    listings - words are rushed together without any pause.

    Fixes applied (in order):
    1. Interjections ("Great", "Thanks", "Okay") followed immediately by a new
       sentence â†’ insert a period so Cartesia pauses between them.
    2. Numbered list items ("1.", "2.", "Option 1", "Option 2") â†’ force a period
       before each item so each property description is a separate TTS sentence.
    3. Colons followed by content on the same line â†’ split into two sentences.
    4. Long comma-joined clauses (>12 words between commas) â†’ replace comma with period.
    5. Ensure the entire text ends with sentence-ending punctuation.
    """
    import re as _re
    text = _normalize_tts_time_tokens(text)

    # 1a. Single-word interjections followed by a capital-letter sentence.
    #     "Great Could you" â†’ "Great. Could you"
    #     "Thanks Please"   â†’ "Thanks. Please"
    #     Guard: already has terminal punctuation (don't double-punctuate).
    _INTERJECTIONS = (
        r'(?:Great|Thanks|Thank you|Okay|Sure|Perfect|Alright|Absolutely|'
        r'Wonderful|Certainly|Of course|Sure|Got it|Noted|Understood)'
    )
    text = _re.sub(
        rf'\b({_INTERJECTIONS})\b(?<![.!?,])\s+(?=[A-Z])',
        r'\1. ',
        text,
    )

    # 1b. Two-word lead phrases ("Great news", "Good news") followed by a sentence.
    #     "Great news We have" â†’ "Great news. We have"
    text = _re.sub(
        r'\b((?:Great|Good|Wonderful|Exciting)\s+(?:news|call|choice))\b(?<![.!?,])\s+(?=[A-Z])',
        r'\1. ',
        text,
        flags=_re.IGNORECASE,
    )

    # 2. Numbered list items - insert sentence break before each one.
    #    Match: digit(s) + dot/parenthesis + space OR "Option/Choice N"
    #    But NOT "2 BHK", "3 BHK" (bedroom configs) - guard with negative lookahead.
    text = _re.sub(
        r'(?<=[a-zA-Z.,!?à¥¤\u0964])\s+(\d+[.)]\s+(?!\d\s*BHK|\d\s*bhk))',
        r'. \1',
        text,
    )
    text = _re.sub(
        r'(?<=[a-zA-Z.,!?à¥¤\u0964])\s+((?:Option|Choice|Point)\s+\d+\b)',
        r'. \1',
        text,
        flags=_re.IGNORECASE,
    )

    # 3. Colon followed by content on same "sentence" - split into two sentences.
    #    e.g. "Here are the options: Option 1 is X" â†’ "Here are the options. Option 1 is X"
    #    Guard: don't split "10:30 AM" style time tokens.
    text = _re.sub(
        r':\s+(?=[A-Z\u0900-\u097F])',  # colon + space + capital/Devanagari
        '. ',
        text,
    )

    # 4. Very long comma-joined clauses â†’ period.
    #    Only when both sides of the comma are â‰¥8 words (avoids splitting short enumerations).
    def _split_long_comma(m):
        before = m.group(1)
        after  = m.group(2)
        if len(before.split()) >= 8 and len(after.split()) >= 6:
            # Capitalise first letter of the new sentence
            return before + '. ' + after[0].upper() + after[1:]
        return m.group(0)

    text = _re.sub(
        r'((?:\w+\s+){7,}\w+),\s+(\w.{30,})',
        _split_long_comma,
        text,
    )

    # 5. Missing period after a 4-digit year when followed by a capital word.
    #    "December 2026 The apartments" â†’ "December 2026. The apartments"
    text = _re.sub(r'\b(20\d{2})\s+(?=[A-Z][a-z])', r'\1. ', text)

    # 6. Missing period before common question-starter phrases after a lowercase word.
    #    "visitor parking Would you like" â†’ "visitor parking. Would you like"
    text = _re.sub(
        r'(?<=[a-z,])\s+(Would you like|Shall I|Do you want|Would you prefer|Can I help)',
        lambda m: '. ' + m.group(1),
        text,
    )

    # Common property narration clauses sometimes arrive without punctuation.
    text = _re.sub(
        r'(?<=[A-Za-z\u0B80-\u0BFF])\s+'
        r'(We\s+have\b|The\s+second\s+option\b|It\s+includes\b|'
        r'Possession\s+is\b|Would\s+you\s+like\b)',
        lambda m: '. ' + m.group(1),
        text,
        flags=_re.IGNORECASE,
    )

    # 6a. Common callback/farewell phrases often lose punctuation in generated
    # text, which makes Cartesia read them as a single rushed sentence.
    text = _re.sub(
        r'(?<=[A-Za-z])\s+(Our team will\b|Thank you for calling\b|Have a great day\b)',
        lambda m: '. ' + m.group(1),
        text,
    )

    # 6b. Missing period before common CTA starters that often appear at the end of
    # property-detail answers without punctuation.
    text = _re.sub(
        r'(?<=[A-Za-z])\s+(Want to\b|Want me to\b|Or should I\b|or should I\b|Should I connect\b|Can I connect\b)',
        lambda m: '. ' + m.group(1),
        text,
    )

    # 7. Missing period before new-clause starters that the LLM runs together with
    #    a preceding location/noun phrase without punctuation.
    #    "in T Nagar The top three are" â†’ "in T Nagar. The top three are"
    #    "sq ft The starting price" â†’ "sq ft. The starting price"
    text = _re.sub(
        r'(?<=[A-Za-z])\s+(The\s+(?:top|following|first|next|last|three|two|four|five|available|good|best|only|other|same|starting|possession|developer|project|amenities|price|total)\b|Here\s+are\b)',
        lambda m: '. ' + m.group(1),
        text,
    )

    # 8. "Each unit/apartment/flat/floor" after a location/fact phrase without punctuation.
    #    "in T Nagar Each unit has" â†’ "in T Nagar. Each unit has"
    text = _re.sub(
        r'(?<=[A-Za-z])\s+(Each\s+(?:unit|flat|apartment|villa|floor|tower|block|property)\b)',
        lambda m: '. ' + m.group(1),
        text,
        flags=_re.IGNORECASE,
    )

    # 9. "It's" / "It is" after a price or measurement word.
    #    "89 Lakh It's ready" â†’ "89 Lakh. It's ready"
    text = _re.sub(
        r'(?<=[a-z])\s+(It\'s\b|It\s+is\b)',
        lambda m: '. ' + m.group(1),
        text,
    )

    # 10. "Amenities include/are" following any word without punctuation.
    #     "2023 Amenities include" is handled by rule 5 (year boundary);
    #     this catches the remaining cases like "visitor parking Amenities include".
    text = _re.sub(
        r'(?<=[a-z])\s+(Amenities\s+(?:include|are|consist)\b)',
        lambda m: '. ' + m.group(1),
        text,
        flags=_re.IGNORECASE,
    )

    # 11. Ensure text ends with sentence-ending punctuation.
    text = text.strip()
    if text and text[-1] not in '.!?à¥¤':
        text += '.'

    return text


def _normalize_response_style(text: str, suppress_got_it: bool = False) -> str:
    """Keep the spoken style steady without adding filler acknowledgements."""
    text = re.sub(r'\s+', ' ', (text or "").strip())
    if not text:
        return text

    text = re.sub(r'^\s*got it\b[.!]?\s*', '', text, flags=re.IGNORECASE).strip()
    if not text:
        return text

    if text[-1] not in ".!?":
        if text.lower().startswith(("what", "which", "could", "would", "do", "are", "is", "can")):
            text += "?"
        else:
            text += "."

    return text


def _build_search_results_speech(
    result: dict,
    *,
    selected_items: list[dict] | None = None,
    subset_hint: str | None = None,
) -> str | None:
    """Build a deterministic spoken summary from search results using ordinal presentation."""
    if not isinstance(result, dict):
        return None

    data = selected_items if selected_items is not None else result.get("data")
    if not isinstance(data, list) or not data:
        return None

    def _spoken_locality(value: str) -> str:
        cleaned = re.sub(r"\bT\.\s*Nagar\b", "T Nagar", str(value or ""), flags=re.IGNORECASE)
        cleaned = re.sub(r"\bT\.Nagar\b", "T Nagar", cleaned, flags=re.IGNORECASE)
        return re.sub(r"\s+", " ", cleaned).strip()

    def _singular_property_label(value: str) -> str:
        label = re.sub(r"\s+", " ", str(value or "property").strip().lower())
        mapping = {
            "apartments": "apartment",
            "flats": "flat",
            "villas": "villa",
            "plots": "plot",
            "properties": "property",
            "projects": "project",
        }
        return mapping.get(label, label[:-1] if label.endswith("s") and len(label) > 4 else label)

    total = int(result.get("total_count") or len(data) or 0)
    current_page = int(result.get("current_page") or 1)
    has_more = bool(result.get("has_more"))
    requested_result_count = max(1, int(result.get("requested_result_count") or PRESENTED_PROPERTY_LIMIT))

    # Property type label - use exactly as the user requested (e.g. "apartments", "plots")
    ptype = (
        result.get("searched_property_type")
        or result.get("property_type")
        or "property"
    ).strip().lower()
    filtered_data = _filter_results_for_requested_property_type(data, ptype)
    if filtered_data:
        data = filtered_data
    elif selected_items is None:
        logger.warning(f"[SearchResults] No items matched requested property_type={ptype!r}; suppressing stale presentation")
        return None
    scope_label = str(
        result.get("searched_location")
        or result.get("exact_location_searched")
        or result.get("location")
        or result.get("searched_city")
        or result.get("city")
        or ""
    ).strip()
    if not scope_label and data:
        scope_label = str(
            data[0].get("location")
            or data[0].get("micro_market")
            or data[0].get("city")
            or ""
        ).strip()
    if scope_label.lower() in {"-", "none", "null", "unknown", "unknown area"}:
        scope_label = ""
    scope_label = _spoken_locality(scope_label)
    scope_phrase = f" in {scope_label}" if scope_label else ""

    # Preserve backend/result order, but collapse duplicate project names into one
    # spoken property so variants can be clarified by BHK / price later.
    candidates: list[dict] = []
    grouped: dict[str, dict] = {}
    for item in data:
        name = (
            item.get("project_name")
            or item.get("name")
            or item.get("projectName")
            or item.get("Project_Name_Original")
            or item.get("Project_Name")
            or item.get("Project_Name_New")
            or ""
        ).strip()
        if not name or name == "?":
            continue
        cfgs = item.get("configs") or item.get("configurations") or []
        price_num = None
        for c in cfgs:
            if not isinstance(c, dict):
                continue
            p = c.get("price") or c.get("FinalPrice") or c.get("All_Price")
            if p:
                try:
                    price_num = min(price_num if price_num is not None else float("inf"), float(p))
                except (ValueError, TypeError):
                    pass
        price_str = item.get("starting_price") or (
            str(int(price_num)) if price_num and price_num != float("inf") else None
        )
        cfg_type = None
        for c in cfgs:
            if isinstance(c, dict) and c.get("type"):
                cfg_type = str(c.get("type")).strip()
                break
        prop_id = str(item.get("property_id") or item.get("project_slug") or item.get("slug") or "").strip()
        key = re.sub(r"\s+", " ", name.strip().lower())
        variant = {
            "property_id": prop_id,
            "name": name,
            "bhk": cfg_type,
            "price": price_str,
            "price_num": price_num if price_num is not None else float("inf"),
        }
        existing = grouped.get(key)
        if existing:
            existing["variants"].append(variant)
            existing["best_price_num"] = min(existing["best_price_num"], variant["price_num"])
        else:
            entry = {
                "name": name,
                "best_price_num": variant["price_num"],
                "variants": [variant],
            }
            grouped[key] = entry
            candidates.append(entry)

    if not candidates:
        return None

    grouped_total = len(candidates)
    top = candidates if selected_items is not None else candidates[:requested_result_count]
    n = len(top)
    announced_total = max(total, grouped_total, n)

    def _spoken_total_label(value: int, has_more_flag: bool) -> str:
        if value <= 0:
            return "0"
        rounded = (value // 10) * 10 if value >= 10 else value
        if value < 10:
            return str(value)
        if value == rounded and not has_more_flag:
            return str(rounded)
        return f"{rounded}+"

    # Ordinal templates - index 0..4
    _ORDINALS = [
        "First, {name}, from {price}.",
        "Second, {name}, from {price}.",
        "Third, {name}, from {price}.",
        "Fourth, {name}, from {price}.",
        "Fifth, {name}, from {price}.",
    ]
    _SALES_ORDINALS = ["first", "second", "third", "fourth", "fifth"]
    item_ptype = _singular_property_label(ptype)
    sales_style = not subset_hint and current_page <= 1
    single_item_name = str(top[0].get("name") or "").strip() if n == 1 and top else ""

    # Intro
    if subset_hint:
        if announced_total > n:
            intro = f"I have {_spoken_total_label(announced_total, has_more)} properties{scope_phrase}. Let me list the {subset_hint} {ptype} again."
        else:
            intro = f"Let me list the {subset_hint} {ptype} again."
    elif current_page > 1:
        remaining_word = item_ptype if n == 1 else ptype
        intro = f"I have {n} more matching {remaining_word}{scope_phrase}."
    elif announced_total > n or has_more:
        total_label = item_ptype if str(_spoken_total_label(announced_total, has_more)) == "1" else ptype
        start_phrase = "I'll start with the first one." if n == 1 else f"I'll start with the first {n}."
        intro = (
            f"I found {_spoken_total_label(announced_total, has_more)} matching {total_label}{scope_phrase}. "
            f"{start_phrase}"
        )
    else:
        total_label = item_ptype if n == 1 else ptype
        if n == 1:
            intro = f"I found 1 matching {total_label}{scope_phrase}."
        else:
            intro = (
                f"I found {n} matching {total_label}{scope_phrase}. "
                f"I'll start with the first {n}."
            )

    lines = [intro]
    for i, grouped_item in enumerate(top):
        tmpl = _ORDINALS[i] if i < len(_ORDINALS) else _ORDINALS[-1]
        name = grouped_item["name"]
        variants = sorted(
            grouped_item["variants"],
            key=lambda v: (
                v.get("price_num", float("inf")),
                str(v.get("bhk") or ""),
                str(v.get("property_id") or ""),
            ),
        )
        if len(variants) == 1:
            price_label = variants[0].get("price") or "price not listed, I can connect you with our specialist"
            if sales_style:
                ordinal = _SALES_ORDINALS[i] if i < len(_SALES_ORDINALS) else f"option {i + 1}"
                if i == 1:
                    lines.append(f"The {ordinal} {ptype} I have is {name}. And the price starts from {price_label}.")
                elif i == 2:
                    lines.append(f"The {ordinal} {ptype}, {name}, which is again a very good property, the price of this property starts from {price_label}.")
                else:
                    lines.append(f"The {ordinal} {ptype} I have is {name}. The price starts from {price_label}.")
            else:
                lines.append(tmpl.format(ptype=item_ptype, name=name, price=price_label))
            continue

        variant_bits = []
        for variant in variants[:3]:
            bhk = variant.get("bhk") or "configuration"
            price = variant.get("price") or "price on request"
            variant_bits.append(f"{bhk} at {price}")
        joined = ", ".join(variant_bits[:-1]) + (f", and {variant_bits[-1]}" if len(variant_bits) > 1 else variant_bits[0])
        lines.append(
            f"{name} has multiple options available, including {joined}."
        )

    if current_page > 1:
        if n == 1 and single_item_name:
            lines.append(f"Would you like more details about {single_item_name}?")
        else:
            lines.append("Which one would you like details for?")
    elif has_more or announced_total > n:
        if n == 1 and single_item_name:
            lines.append(
                f"Would you like more details about {single_item_name}, or should I tell you the next {requested_result_count} properties?"
            )
        else:
            lines.append(
                f"If you'd like, I can tell you more about any of these, or I can tell you the next {requested_result_count} properties."
            )
    else:
        if n == 1 and single_item_name:
            lines.append(f"Would you like more details about {single_item_name}?")
        else:
            lines.append("Which one would you like details for?")
    return " ".join(lines)


def _search_scope_label(result: dict, data: list[dict] | None = None) -> str:
    scope_label = str(
        result.get("searched_location")
        or result.get("exact_location_searched")
        or result.get("location")
        or result.get("searched_city")
        or result.get("city")
        or ""
    ).strip()
    if not scope_label and data:
        scope_label = str(
            data[0].get("location")
            or data[0].get("micro_market")
            or data[0].get("city")
            or ""
        ).strip()
    if scope_label.lower() in {"-", "none", "null", "unknown", "unknown area"}:
        return ""
    scope_label = re.sub(r"\bT\.\s*Nagar\b", "T Nagar", scope_label, flags=re.IGNORECASE)
    scope_label = re.sub(r"\bT\.Nagar\b", "T Nagar", scope_label, flags=re.IGNORECASE)
    return scope_label


def _extract_search_item_min_price(item: dict) -> int:
    candidates = [
        item.get("price_value"),
        item.get("min_price"),
        item.get("starting_price"),
        item.get("price"),
    ]
    for cfg in item.get("configs") or item.get("configurations") or []:
        if not isinstance(cfg, dict):
            continue
        candidates.extend([
            cfg.get("price"),
            cfg.get("FinalPrice"),
            cfg.get("All_Price"),
            cfg.get("min_price"),
            cfg.get("starting_price"),
        ])

    values: list[int] = []
    for candidate in candidates:
        if candidate in (None, "", float("inf")):
            continue
        mixed_price = _parse_mixed_indian_price_label(str(candidate))
        if mixed_price > 0:
            values.append(mixed_price)
            continue
        parsed_amounts = _parse_inr_amounts(str(candidate))
        if parsed_amounts:
            values.extend([amount for amount in parsed_amounts if amount > 0])
            continue
        try:
            value = int(float(candidate))
            if value > 0:
                values.append(value)
        except (TypeError, ValueError):
            continue
    return min(values) if values else 0


def _parse_mixed_indian_price_label(text: str) -> int:
    """Parse labels like '54 Lakh 83 Thousand 400' into rupees."""
    lower = re.sub(r"[,₹]", " ", str(text or "").lower())
    if not lower.strip():
        return 0

    total = 0
    matched = False
    unit_multipliers = {
        "crore": 10_000_000,
        "crores": 10_000_000,
        "cr": 10_000_000,
        "lakh": 100_000,
        "lakhs": 100_000,
        "lac": 100_000,
        "lack": 100_000,
        "thousand": 1_000,
    }
    for match in re.finditer(r"\b(\d+(?:\.\d+)?)\s*(crores?|cr|lakhs?|lac|lack|thousand)\b", lower):
        matched = True
        amount = float(match.group(1))
        total += int(round(amount * unit_multipliers[match.group(2)]))

    consumed_spans = [range(match.start(), match.end()) for match in re.finditer(r"\b(\d+(?:\.\d+)?)\s*(crores?|cr|lakhs?|lac|lack|thousand)\b", lower)]
    tail_numbers = []
    for match in re.finditer(r"\b(\d{2,6})\b", lower):
        if any(match.start() in span for span in consumed_spans):
            continue
        tail_numbers.append(int(match.group(1)))
    if matched and tail_numbers:
        total += tail_numbers[-1]

    return total if matched else 0


def _build_search_starting_price_speech(result: dict) -> str | None:
    if not isinstance(result, dict):
        return None

    data = result.get("data")
    if not isinstance(data, list) or not data:
        return None

    buffered = result.get("buffered_page_items")
    price_items = list(data)
    if isinstance(buffered, list):
        price_items.extend([item for item in buffered if isinstance(item, dict)])

    prices = [
        _extract_search_item_min_price(item)
        for item in price_items
        if isinstance(item, dict)
    ]
    prices = [price for price in prices if price > 0]
    if not prices:
        return None

    ptype = (
        result.get("searched_property_type")
        or result.get("property_type")
        or "properties"
    ).strip().lower()
    bedrooms = str(result.get("searched_bedrooms") or result.get("bedrooms") or "").strip()
    if bedrooms and not re.search(r"\bbhk\b", bedrooms, re.IGNORECASE):
        bedrooms = f"{bedrooms} BHK"
    ptype_label = f"{bedrooms} {ptype}".strip() if bedrooms else ptype
    scope = _search_scope_label(result, data)
    scope_phrase = f" in {scope}" if scope else ""
    return (
        f"The starting price for {ptype_label}{scope_phrase} is around "
        f"{_format_price_indian(min(prices))}."
    )


def _build_budget_too_low_speech(property_type: str | None, location: str | None, min_price) -> str | None:
    try:
        min_price_value = int(float(min_price))
    except Exception:
        min_price_value = 0
    if min_price_value <= 0:
        return None
    ptype_plural = _property_type_plural_label(property_type or "properties").capitalize()
    loc = str(location or "this location").strip() or "this location"
    return (
        f"{ptype_plural} in {loc} start from {_format_price_indian(min_price_value)}. "
        f"Would you like to adjust the budget for {loc}, or look for other areas?"
    )


def _build_search_results_speech_fast(result: dict) -> str | None:
    """Shorter deterministic narration for the first search result turn."""
    if not isinstance(result, dict):
        return None

    data = result.get("data")
    if not isinstance(data, list) or not data:
        return None

    total = int(result.get("total_count") or len(data) or 0)
    has_more = bool(result.get("has_more"))
    current_page = int(result.get("current_page") or 1)
    requested_result_count = max(1, int(result.get("requested_result_count") or PRESENTED_PROPERTY_LIMIT))
    ptype = (
        result.get("searched_property_type")
        or result.get("property_type")
        or "properties"
    ).strip().lower()

    candidates: list[tuple] = []
    for item in data:
        name = (
            item.get("project_name")
            or item.get("name")
            or item.get("projectName")
            or item.get("Project_Name_Original")
            or item.get("Project_Name")
            or item.get("Project_Name_New")
            or ""
        ).strip()
        if not name or name == "?":
            continue
        cfgs = item.get("configs") or item.get("configurations") or []
        price_num = None
        for c in cfgs:
            if not isinstance(c, dict):
                continue
            p = c.get("price") or c.get("FinalPrice") or c.get("All_Price")
            if p:
                try:
                    price_num = min(price_num if price_num is not None else float("inf"), float(p))
                except (ValueError, TypeError):
                    pass
        price_str = item.get("starting_price") or (
            str(int(price_num)) if price_num and price_num != float("inf") else None
        )
        candidates.append((price_num if price_num is not None else float("inf"), name, price_str))

    if not candidates:
        return None

    top = candidates[:requested_result_count]
    announced_total = total if total > len(top) else len(top)
    scope = _search_scope_label(result, data)
    scope_phrase = f" in {scope}" if scope else ""
    item_ptype = _property_type_singular_label(ptype)
    single_item_name = str(top[0][1] or "").strip() if len(top) == 1 and top else ""

    def _spoken_total_label(value: int, has_more_flag: bool) -> str:
        if value <= 0:
            return "0"
        rounded = (value // 10) * 10 if value >= 10 else value
        if value < 10:
            return str(value)
        if value == rounded and not has_more_flag:
            return str(rounded)
        return f"{rounded}+"
    if current_page > 1:
        if len(top) == 1:
            lines = [f"Here is the next {item_ptype}."]
        else:
            lines = [
                f"Here are the next {len(top)} {ptype}."
            ]
    else:
        total_phrase = _spoken_total_label(announced_total, has_more)
        if len(top) == 1 and not (has_more or announced_total > len(top)):
            lines = [f"Currently I have 1 matching {item_ptype}{scope_phrase}."]
        elif len(top) == 1:
            lines = [
                f"Currently I have {total_phrase} properties{scope_phrase}. "
                f"Let me talk about the first matching {item_ptype}."
            ]
        else:
            lines = [
                f"Currently I have {total_phrase} properties{scope_phrase}. "
                f"However, let me talk about the top {len(top)} {ptype} that are matching your requirement."
            ]
    ordinals = ["first", "second", "third", "fourth", "fifth"]
    for idx, (_, name, price_str) in enumerate(top, start=1):
        ordinal = ordinals[idx - 1] if idx <= len(ordinals) else f"option {idx}"
        price_label = price_str or "price on request"
        if current_page <= 1:
            if idx == 2:
                lines.append(f"The {ordinal} {ptype} I have is {name}. And the price starts from {price_label}.")
            elif idx == 3:
                lines.append(f"The {ordinal} {ptype}, {name}, which is again a very good property, the price of this property starts from {price_label}.")
            else:
                lines.append(f"The {ordinal} {ptype} I have is {name}. The price starts from {price_label}.")
        else:
            lines.append(f"{ordinal.capitalize()}, {name}, from {price_label}.")
    if current_page > 1:
        if len(top) == 1 and single_item_name:
            lines.append(f"Would you like more details about {single_item_name}?")
        else:
            lines.append("Which one would you like details for?")
    elif has_more or announced_total > len(top):
        if len(top) == 1 and single_item_name:
            lines.append(f"Would you like more details about {single_item_name}, or should I tell you the next {requested_result_count} properties?")
        else:
            lines.append(f"If you'd like, I can tell you more about any of these, or I can tell you the next {requested_result_count} properties.")
    else:
        if len(top) == 1 and single_item_name:
            lines.append(f"Would you like more details about {single_item_name}?")
        else:
            lines.append("Which one would you like details for?")
    return " ".join(lines)


def _normalize_tts_time_tokens(text: str) -> str:
    """Protect clock times from punctuation cleanup and serial-number stripping."""
    if not text:
        return text

    def _time_sub(match: re.Match) -> str:
        raw = match.group(0)
        try:
            hour = int(match.group(1))
            minute = int(match.group(2) or 0)
        except (TypeError, ValueError):
            return raw
        spoken = _format_spoken_clock_time(hour, minute, match.group(3))
        return spoken or raw

    return re.sub(
        r"\b(1[0-2]|0?[1-9])\s*(?:[:.]\s*([0-5]\d))?\s*(a\.?\s*m\.?|p\.?\s*m\.?)\b",
        _time_sub,
        text,
        flags=re.IGNORECASE,
    )


def _cleanup_tts_text(text: str) -> str:
    """Strip markdown/list artifacts and repair common TTS token-boundary issues."""
    cleaned = (text or "").strip()
    if not cleaned:
        return cleaned
    cleaned = _normalize_tts_time_tokens(cleaned)

    cleaned = re.sub(r'\*{1,3}([^*\n]+)\*{1,3}', r'\1', cleaned)
    cleaned = re.sub(r'(?m)^\s{0,3}#{1,6}\s*', '', cleaned)
    cleaned = re.sub(r'\[\d+\]\s*', '', cleaned)
    cleaned = re.sub(
        r'(?:The top \d+ are|Here are the top \d+)\s*:?\s*',
        '',
        cleaned,
        flags=re.IGNORECASE,
    )
    # Strip serial numbers (N. or N) before property entries - including when
    # followed by a BHK count ("1. 3 BHK" â†’ "3 BHK"). Require dot or paren so
    # standalone "2 BHK" is never touched.
    cleaned = re.sub(r'^\s*\d+[.)]\s+', '', cleaned)
    cleaned = re.sub(
        r'(?:(?<=^)|(?<=[.!?]\s)|(?<=\n)|(?<=\r\n))\d+[.)]\s+',
        '',
        cleaned,
        flags=re.MULTILINE,
    )
    cleaned = re.sub(r'([A-Za-z)])\s*:\s*(?=\d|\b[A-Z])', r'\1. ', cleaned)
    cleaned = re.sub(r'\s*:\s*$', '', cleaned.rstrip())
    cleaned = re.sub(r'\s*:\s*', '. ', cleaned)
    cleaned = re.sub(r'([a-z])([A-Z])', r'\1. \2', cleaned)
    cleaned = re.sub(r'([a-zA-Z])(\d)(?!\s*(?:st|nd|rd|th)\b)', r'\1 \2', cleaned)
    cleaned = re.sub(r'(\d)([A-Z])', r'\1 \2', cleaned)
    cleaned = re.sub(
        r'\b(Which one|Which property)\.\s+(would|should|can|do|is|are)\b',
        r'\1 \2',
        cleaned,
        flags=re.IGNORECASE,
    )
    cleaned = re.sub(
        r'\bthe\.\s+(amenities|amenity)\b',
        r'the \1',
        cleaned,
        flags=re.IGNORECASE,
    )
    spacing_repairs = {
        r"\bBHK\s*apartments\b": "BHK apartments",
        r"\bBHK\s*apartment\b": "BHK apartment",
        r"\bCro\s+re\b": "Crore",
        r"\bL\s+akh\b": "Lakh",
        r"\bPoss\s+ession\b": "Possession",
        r"\bR\s+ough\s+ly\b": "Roughly",
        r"\bO\s+MR\b": "OMR",
        r"\bO\s+M\s+R\b": "OMR",
        r"\bT\.\s+Nagar\b": "T Nagar",
        r"\bT\s+Nagar\b": "T Nagar",
        r"\bBr\s+ig\s+ade\b": "Brigade",
        r"\bNeb\s+ula\b": "Nebula",
        r"\bLanc\s+or\b": "Lancor",
        r"\bN\s+ute\s+ch\b": "Nutech",
        r"\bElev\s+ate\b": "Elevate",
        r"\bKam\s+dh\s+enu\b": "Kamdhenu",
        r"\bKam\s+dhenu\b": "Kamdhenu",
    }
    for pattern, replacement in spacing_repairs.items():
        cleaned = re.sub(pattern, replacement, cleaned, flags=re.IGNORECASE)
    cleaned = re.sub(r'\s+', ' ', cleaned).strip()
    return cleaned


class SprioTTSService(CartesiaTTSService):
    """CartesiaTTSService with number normalisation + function-call markup stripping.

    Normalises raw numbers, dates, and measurements to spoken Indian English
    before sending to Cartesia so the TTS never reads digits one-by-one.
    Also strips any leaked LLM function-call markup as a last-resort guard.

    STREAMING CONFIG:
    - text_aggregation_mode="sentence": Start TTS as soon as a sentence is available
    - This reduces time-to-first-audio without waiting for full LLM response
    """

    # Class-level dedup cache: text_key â†’ monotonic timestamp of last send.
    # Prevents duplicate TTS when two parallel tool calls both trigger an LLM
    # response with identical text (e.g. two concurrent search_properties calls).
    _recent_tts: dict[str, float] = {}
    _DEDUP_WINDOW_S: float = 3.0
    # Per-turn "Sure." suppression: once the FIRST TTS sentence of a turn is
    # dispatched (whether or not it got "Sure."), suppress the prefix on every
    # subsequent sentence in the same turn.
    _first_sentence_turn_id: int = -1

    def __init__(self, *args, **kwargs):
        # Reuse the same Cartesia context within a streamed turn so sentence-level
        # requests preserve audio order instead of tearing down earlier audio.
        kwargs.setdefault("reuse_context_id_within_turn", True)
        # Enable sentence-level streaming for faster time-to-first-audio
        kwargs.setdefault("text_aggregation_mode", TextAggregationMode.SENTENCE)
        super().__init__(*args, **kwargs)

    async def synthesize_raw(self, text: str) -> bytes:
        """Synthesize text to raw PCM bytes without pushing to pipeline.
        DISABLED in pipecat 0.0.108+ - the internal _client attribute was removed.
        Filler preload falls back to silent gaps during tool calls (not critical).
        Main TTS path (run_tts) is unaffected and works normally."""
        return b""
        # Legacy code below - kept for reference, unreachable.
        try:
            audio_chunks = []
            async for chunk in self._client.tts(
                model_id=self._settings.get("model", "sonic-3"),
                transcript=text,
                voice={"id": self._settings.get("voice_id", "")},
                output_format={
                    "container": "raw",
                    "encoding": "pcm_f32le",
                    "sample_rate": self._settings.get("sample_rate", 24000),
                },
            ):
                if isinstance(chunk, bytes):
                    audio_chunks.append(chunk)
            return b"".join(audio_chunks)
        except Exception as e:
            logger.warning(
                f"[TTS] synthesize_raw() failed for text='{text[:40]}...': {e}"
            )
            return b""  # empty bytes - callers must check len(result) > 0

    async def run_tts(self, text: str, *args, **kwargs) -> AsyncGenerator:
        # Strip complete <function=...>...</function> blocks
        cleaned = _FUNC_COMPLETE_RE.sub("", text).strip()
        # Strip any remaining unclosed opening tag and everything after it
        m = _FUNC_OPEN_RE.search(cleaned)
        if m:
            cleaned = cleaned[: m.start()].strip()
        if not cleaned:
            logger.debug("[SprioTTS] Suppressed function-call text from reaching Cartesia")
            return
        # Skip standalone punctuation/spaces that cause TTS errors (e.g., "..", ". ", "  ")
        if not cleaned.strip('. â€¦â€¢Â·â”€â€“-').strip():
            logger.debug(f"[SprioTTS] Suppressed punctuation-only text: {cleaned!r}")
            return
        # â”€â”€ LLM markdown/formatting artifacts â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        # Strip markdown bold/italic (**text** or *text* â†’ text)
        # Suppress "Sure." for every sentence after the FIRST one in this turn.
        # We mark the turn as seen on the first sentence regardless of whether
        # "Sure." was added, so continuation fragments never get it.
        _current_turn = global_state_manager.turn_id
        _suppress_ack = (SprioTTSService._first_sentence_turn_id == _current_turn)
        if not _suppress_ack:
            SprioTTSService._first_sentence_turn_id = _current_turn
        cleaned = _normalize_response_style(cleaned, suppress_got_it=_suppress_ack)
        cleaned = _cleanup_tts_text(cleaned)
        cleaned = SarvamTextSanitizer._normalize_spoken_localities(cleaned)
        # Remove [N] bracket-tag position markers from CURRENT SEARCH RESULTS
        cleaned = re.sub(r'\[\d+\]\s*', '', cleaned)
        # Remove "The top N are:" or "Here are the top N:" intro phrases
        cleaned = re.sub(r'(?:The top \d+ are|Here are the top \d+)\s*:?\s*', '', cleaned, flags=re.IGNORECASE)
        # â”€â”€ Serial-number stripping â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        # Protect real price/config tokens from being stripped (BHK, Crore, Lakh/Lack).
        _PRICE_UNIT = r'(?![Bb][Hh][Kk]\b|[Cc]rore\b|[Ll]a[ck]h?\b|\d)'
        # 1. Leading serial (dot/paren form): "1. Aanirudh" or "1) Aanirudh" â†’ "Aanirudh"
        cleaned = re.sub(r'^\s*\d+[.)]\s+' + _PRICE_UNIT, '', cleaned)
        # 2. Leading serial (bare form): "1 Aanirudh" â†’ "Aanirudh"  (keeps "3 BHK", "1 Crore")
        cleaned = re.sub(r'^\s*\d+\s+' + _PRICE_UNIT, '', cleaned)
        # 3. Serial after sentence boundary (dot/paren): ". 1. Aanirudh" â†’ ". Aanirudh"
        cleaned = re.sub(
            r'(?<=[.!?]\s)\d+[.)]\s+' + _PRICE_UNIT,
            '',
            cleaned,
            flags=re.MULTILINE,
        )
        # 4. Serial after sentence boundary (bare): ". 1 Aanirudh" â†’ ". Aanirudh"
        cleaned = re.sub(
            r'(?<=[.!?]\s)\d+\s+' + _PRICE_UNIT,
            '',
            cleaned,
            flags=re.MULTILINE,
        )
        # 5. Serial after a price unit mid-sentence: "Lakh 2 Indus" â†’ "Lakh Indus"
        #    Capture the unit to avoid variable-width lookbehind (not supported by re).
        cleaned = re.sub(
            r'(?i)(Lakh|Lack|Crore)\s+\d+\s+(?=(?!Lakh\b|Lack\b|Crore\b)[A-Z])',
            r'\1 ',
            cleaned,
        )
        # Convert letter/word-colon-digit (property separator) to period+space
        # "LML Prakriti:4 BHK" â†’ "LML Prakriti. 4 BHK"
        cleaned = re.sub(r'([a-zA-Z])\s*:\s*(\d)', r'\1. \2', cleaned)
        # Strip stray colons at end-of-clause ("are :" â†’ "are")
        cleaned = re.sub(r'\s*:\s*$', '', cleaned.rstrip())

        # â”€â”€ Groq token boundary space fixes â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        # Letterâ†’digit: "of80 lakhs" â†’ "of 80 lakhs". Guard: don't split ordinal suffixes (1st, 2ndâ€¦).
        cleaned = re.sub(r'([a-zA-Z])(\d)(?!\s*(?:st|nd|rd|th)\b)', r'\1 \2', cleaned)
        # Digitâ†’uppercase-letter: "2023Amenities" â†’ "2023 Amenities", "Crore89Lakh" â†’ "Crore 89 Lakh".
        cleaned = re.sub(r'(\d)([A-Z])', r'\1 \2', cleaned)
        cleaned = _repair_tts_text_assembly(cleaned)

        # Fix sentence boundaries so Cartesia pauses naturally between sentences.
        # Must run BEFORE number normalisation because it relies on word counts.
        cleaned = _cleanup_tts_text(_fix_tts_sentence_boundaries(cleaned))
        # Normalise numbers / dates / measurements â†’ natural spoken form
        normalised = _normalize_tts_text(cleaned)
        if normalised != cleaned:
            logger.debug(f"[SprioTTS] Normalised: {cleaned!r} â†’ {normalised!r}")

        normalised = _cleanup_tts_text(normalised)

        # Dedup: suppress identical text sent within the last 3 seconds.
        # Prevents double-TTS when parallel tool calls both resolve and the LLM
        # generates the same response twice almost simultaneously.
        _now_mono = time.monotonic()
        _dedup_key = normalised[:120]
        _last_sent = SprioTTSService._recent_tts.get(_dedup_key, 0.0)
        if _now_mono - _last_sent < SprioTTSService._DEDUP_WINDOW_S:
            logger.warning(
                f"[SprioTTS] Suppressed duplicate TTS (%.1fs ago): {normalised[:60]!r}",
                _now_mono - _last_sent,
            )
            return
        SprioTTSService._recent_tts[_dedup_key] = _now_mono
        # Prune stale entries to avoid unbounded growth
        SprioTTSService._recent_tts = {
            k: v for k, v in SprioTTSService._recent_tts.items()
            if _now_mono - v < 10.0
        }

        logger.info(f"ðŸ-£ï¸ [TTS_REQUEST] {normalised!r}")
        logger.info(f"[TTS_PAYLOAD] chars={len(normalised)} text={normalised[:120]!r}")
        
        # TTS timing: track time-to-first-chunk and total generation
        _tts_start_mono = time.monotonic()
        _first_chunk_logged = False
        _chunk_count = 0
        
        try:
            async for frame in super().run_tts(normalised, *args, **kwargs):
                _chunk_count += 1
                # Note: run_tts() yields TTSStartedFrame then None - never TTSAudioRawFrame.
                # Actual audio is pushed by _audio_context_task_handler via tts.push_frame().
                # TTS TTFA is measured accurately by TTSActivityLogger(TTS-OUT).
                if not _first_chunk_logged:
                    _ttfc_ms = int((time.monotonic() - _tts_start_mono) * 1000)
                    # This measures time to first CONTROL frame (TTSStartedFrame/None), NOT audio.
                    # Real audio timing is measured by TTSActivityLogger(TTS-OUT) via [TTS_AUDIO_FIRST].
                    logger.debug(f"[TTS_CONTROL] first control frame ({type(frame).__name__}) in {_ttfc_ms}ms")
                    _first_chunk_logged = True
                yield frame
            _total_ms = int((time.monotonic() - _tts_start_mono) * 1000)
            # NOTE: This measures control frame dispatch (run_tts yield), NOT actual audio arrival.
            logger.info(f"[TTS_CONTROL] request_dispatched: {_total_ms}ms | frames={_chunk_count} | chars={len(normalised)} | note=control_frames_not_audio")
        except Exception as e:
            if 'Context has closed' in str(e) or 'context' in str(e).lower():
                logger.warning(f'[SprioTTS] Context closed, resetting and retrying: {e}')
                self.reset_active_audio_context()
                # Small delay to allow TTS service to stabilize
                await asyncio.sleep(0.05)
                # Retry with timing
                _retry_start = time.monotonic()
                _retry_chunk = 0
                _retry_gen = None
                try:
                    _retry_gen = super().run_tts(normalised, *args, **kwargs)
                    async for frame in _retry_gen:
                        _retry_chunk += 1
                        if _retry_chunk == 1:
                            _retry_ttfc = int((time.monotonic() - _retry_start) * 1000)
                            logger.info(f"[TTS_CONTROL_RETRY] first control frame ({type(frame).__name__}) in {_retry_ttfc}ms | not audio")
                        yield frame
                    _retry_total = int((time.monotonic() - _retry_start) * 1000)
                    # NOTE: This measures control frame dispatch (retry), NOT actual audio arrival.
                    logger.info(f"[TTS_CONTROL_RETRY] Complete: {_retry_total}ms | frames={_retry_chunk} | note=control_frames_not_audio")
                except Exception as retry_err:
                    # Ensure generator is closed on retry failure
                    if _retry_gen:
                        try:
                            await _retry_gen.aclose()
                        except Exception:
                            pass
                    raise retry_err
            else:
                raise

class SarvamTTSWrapper:
    """Wrapper for SarvamTTSService that filters out punctuation-only text.

    Prevents TTS errors when LLM generates standalone dots/punctuation.
    """
    def __init__(self, service):
        self._service = service

    async def run_tts(self, text: str, *args, **kwargs) -> AsyncGenerator:
        # Skip standalone punctuation/spaces that cause TTS errors
        cleaned = text.strip()
        if not cleaned.strip('. â€¦â€¢Â·â”€â€“-').strip():
            logger.debug(f"[SarvamTTSWrapper] Suppressed punctuation-only text: {cleaned!r}")
            return
        async for frame in self._service.run_tts(cleaned, *args, **kwargs):
            yield frame

    def __getattr__(self, name):
        # Delegate all other attributes to the wrapped service
        return getattr(self._service, name)


class SentenceStreamingTTS(FrameProcessor):
    """Streams LLM output to TTS sentence-by-sentence for low-latency speech.
    
    Instead of waiting for the full LLM response, this processor:
    1. Buffers incoming LLMTextFrame chunks
    2. Detects sentence boundaries (., ?, !, newline)
    3. Flushes complete sentences to TTS immediately
    4. Queues subsequent sentences to prevent overlapping audio
    
    This reduces time-to-first-audio from ~1500ms to ~300-500ms.
    """
    
    # Hard sentence boundaries - always flush immediately
    _SENTENCE_END_RE = re.compile(r'[.!?\n]+(?:\s+|$)|\n')
    # Soft clause boundaries - flush only when buffer is long enough
    _SOFT_FLUSH_CHARS = frozenset(',;:')
    _SOFT_FLUSH_MIN_CHARS = 220  # only split very long clause chains
    _HARD_FLUSH_MAX_CHARS = 260  # emergency fallback for punctuation-free output
    _IDLE_FLUSH_DELAY_S = 0.12
    _SEMANTIC_SPLIT_RE = re.compile(
        r'\s+('
        r'Would you like\b|What would you like\b|'
        r'We have\b|The second option\b|It includes\b|Possession is\b|'
        r'Want to\b|Want me to\b|Shall I\b|Do you want\b|'
        r'Or should I\b|or should I\b|Should I connect\b|'
        r'Would you prefer\b|Can I connect\b'
        r')',
        re.IGNORECASE,
    )
    
    def __init__(self, tts_service, latency_trace_ref: list = None, context=None, **kwargs):
        super().__init__(**kwargs)
        self._tts = tts_service
        self._buffer = ""
        self._sentences_queued = 0
        self._sentences_processed = 0
        self._total_chars = 0
        self._active = False
        self._first_sentence_latency: float | None = None
        self._stream_start_ts: float | None = None
        self._tts_task: asyncio.Task | None = None
        self._tts_queue: asyncio.Queue | None = None
        self._current_sentence: str | None = None
        self._enqueue_count = 0
        self._dequeue_count = 0
        self._latency_trace_ref: list = latency_trace_ref if latency_trace_ref is not None else [{}]
        self._assembled_text: str = ""  # accumulates full LLM response for context aggregator
        self._context = context  # Direct access to LLMContext for writing assembled text
        self._delayed_flush_task: asyncio.Task | None = None
        self._pending_sentences: list[str] = []
        self._turn_context_id: str | None = None
        self._generation_id: int = 0
        self._next_sentence_index: int = 0
        self._active_sentence_index: int = -1
        self._last_stale_text_log: tuple[int, int] | None = None
        self._last_stale_queue_log: tuple[int, int] | None = None

    async def setup(self, setup: FrameProcessorSetup):
        await super().setup(setup)
        # tts_service is not a pipeline step, so the pipeline never calls setup() on it.
        # Without setup(), FrameProcessor._task_manager stays None and create_task() throws,
        # leaving _receive_task_handler coroutines unscheduled â†’ RuntimeWarning.
        if isinstance(self._tts, FrameProcessor) and not self._tts._task_manager:
            await self._tts.setup(setup)

    async def _cleanup_tts(self):
        await self._cancel_delayed_flush()
        if isinstance(self._tts, FrameProcessor):
            try:
                await self._tts._disconnect()
            except Exception:
                pass

    async def stop(self, frame):
        await super().stop(frame)
        await self._cleanup_tts()

    async def cancel(self, frame):
        await super().cancel(frame)
        await self._cleanup_tts()

    async def _emit_buffered_tts(self, sentence: str, trigger: str):
        sentence = _cleanup_tts_text(
            _fix_tts_sentence_boundaries(_repair_tts_text_assembly(sentence))
        ).strip()
        if not sentence:
            return
        if self._first_sentence_latency is None and self._stream_start_ts:
            self._first_sentence_latency = time.monotonic() - self._stream_start_ts
            latency_ms = int(self._first_sentence_latency * 1000)
            logger.info(f"[TTS_STREAM_START] first_sentence_ready_latency={latency_ms}ms")
        logger.info(f"[TTS_STREAM_PUSH] sentence={sentence!r} chars={len(sentence)} trigger={trigger}")
        await self._queue_sentence(sentence)
        self._sentences_queued += 1

    async def _cancel_delayed_flush(self):
        if self._delayed_flush_task and not self._delayed_flush_task.done():
            self._delayed_flush_task.cancel()
            try:
                await self._delayed_flush_task
            except asyncio.CancelledError:
                pass
        self._delayed_flush_task = None

    def _log_stale_generation_once(self, kind: str, local_generation: int, current_generation: int):
        key = (local_generation, current_generation)
        attr = "_last_stale_text_log" if kind == "text" else "_last_stale_queue_log"
        if getattr(self, attr) == key:
            return
        setattr(self, attr, key)
        logger.info(
            f"[TTS_STREAM] Ignoring stale {kind} for superseded generation "
            f"(local={local_generation} current={current_generation})"
        )

    def _schedule_delayed_flush(self):
        if self._delayed_flush_task and not self._delayed_flush_task.done():
            self._delayed_flush_task.cancel()
        _generation_id = self._generation_id
        self._delayed_flush_task = asyncio.create_task(self._delayed_flush_buffer(_generation_id))

    async def _delayed_flush_buffer(self, generation_id: int):
        try:
            await asyncio.sleep(self._IDLE_FLUSH_DELAY_S)
            if not self._active:
                return
            _current_generation = int(global_state_manager.current_output_generation() or 0)
            if generation_id and generation_id != _current_generation:
                self._log_stale_generation_once("text", generation_id, _current_generation)
                return
            buf = self._buffer.strip()
            if not buf:
                return
            # Only idle-flush short utterances or clean question prompts.
            # New tokens arriving before the timeout cancel this task.
            word_count = len(buf.split())
            if len(buf) <= 80 or word_count <= 14:
                self._buffer = ""
                await self._emit_buffered_tts(buf, "idle_timeout")
        except asyncio.CancelledError:
            pass

    def _split_long_unpunctuated_buffer(self, buf: str) -> tuple[str, str] | None:
        semantic_matches = list(self._SEMANTIC_SPLIT_RE.finditer(buf))
        if semantic_matches:
            split_at = semantic_matches[-1].start()
            prefix = buf[:split_at].strip()
            suffix = buf[split_at:].lstrip()
            if prefix and suffix and len(prefix) >= 25:
                return prefix, suffix

        if len(buf) < self._HARD_FLUSH_MAX_CHARS:
            return None

        soft_positions = [idx for idx, ch in enumerate(buf) if ch in self._SOFT_FLUSH_CHARS]
        if soft_positions:
            split_at = soft_positions[-1] + 1
            prefix = buf[:split_at].strip()
            suffix = buf[split_at:].lstrip()
            if len(prefix) >= self._SOFT_FLUSH_MIN_CHARS and suffix:
                return prefix, suffix

        split_at = buf.rfind(" ", 0, self._HARD_FLUSH_MAX_CHARS)
        if split_at <= 0:
            split_at = self._HARD_FLUSH_MAX_CHARS

        prefix = buf[:split_at].strip()
        suffix = buf[split_at:].lstrip()
        if prefix and suffix:
            return prefix, suffix
        return None

    async def process_frame(self, frame, direction):
        await super().process_frame(frame, direction)
        
        if isinstance(frame, LLMFullResponseStartFrame):
            # Reset state for new turn
            await self._cancel_delayed_flush()
            self._buffer = ""
            self._sentences_queued = 0
            self._sentences_processed = 0
            self._total_chars = 0
            self._active = True
            self._first_sentence_latency = None
            self._stream_start_ts = time.monotonic()
            self._current_sentence = None
            self._enqueue_count = 0
            self._dequeue_count = 0
            self._assembled_text = ""
            self._pending_sentences = []
            self._turn_context_id = str(uuid.uuid4())
            self._generation_id = int(global_state_manager.current_output_generation() or 0)
            self._next_sentence_index = 0
            self._active_sentence_index = -1
            self._last_stale_text_log = None
            self._last_stale_queue_log = None
            global_state_manager.note_tts_context_id(self._turn_context_id)
            try:
                self._tts.reset_active_audio_context()
            except Exception:
                pass
            # Create new queue for this turn
            self._tts_queue = asyncio.Queue()
            # Start TTS consumer task
            self._tts_task = asyncio.create_task(self._tts_consumer())
            logger.info("[TTS_STREAM] Sentence streaming started")
            await self.push_frame(frame, direction)
            
        elif isinstance(frame, LLMFullResponseEndFrame):
            await self._cancel_delayed_flush()
            # Flush any remaining text in buffer
            if self._buffer.strip():
                remaining = self._buffer.strip()
                logger.info(f"[TTS_STREAM_PUSH] final_flush chars={len(remaining)}")
                await self._emit_buffered_tts(remaining, "final_flush")
                self._buffer = ""
            
            # Signal end of streaming
            if self._tts_queue:
                await self._tts_queue.put(None)  # Sentinel to stop consumer
            
            # Wait for all TTS to complete with proper cleanup
            if self._tts_task and not self._tts_task.done():
                try:
                    await asyncio.wait_for(self._tts_task, timeout=30.0)
                    logger.debug("[TTS_STREAM] TTS consumer completed normally")
                except asyncio.TimeoutError:
                    logger.warning("[TTS_STREAM] TTS consumer timeout - forcing cancel")
                    self._tts_task.cancel()
                    try:
                        await asyncio.wait_for(self._tts_task, timeout=1.0)
                    except (asyncio.CancelledError, asyncio.TimeoutError):
                        pass
                except asyncio.CancelledError:
                    logger.debug("[TTS_STREAM] TTS consumer was cancelled")
                    pass

            # Finalise the Cartesia audio context so it sends a "done" websocket message.
            # Without this, _words_task_handler never pushes TTSStoppedFrame, and
            # TTSActivityLogger("TTS-OUT") never transitions to IDLE â†’ silence detection breaks.
            try:
                await self._tts.flush_audio()
                logger.info("[TTS_STREAM] flush_audio() called - Cartesia context finalized")
            except Exception as _fa_err:
                logger.warning(f"[TTS_STREAM] flush_audio() failed (non-critical): {_fa_err}")

            # Log summary
            if self._stream_start_ts:
                total_time = int((time.monotonic() - self._stream_start_ts) * 1000)
                logger.info(
                    f"[TTS_STREAM_END] sentences={self._sentences_processed} "
                    f"chars={self._total_chars} total_time={total_time}ms"
                )

            self._active = False
            self._current_sentence = None
            self._tts_task = None
            self._tts_queue = None
            self._turn_context_id = None
            self._generation_id = 0
            self._last_stale_text_log = None
            self._last_stale_queue_log = None
            # Let LLMFullResponseEndFrame flow to context_aggregator for normal message writing.
            # Removed direct context write that was causing duplicate assistant messages.
            await self.push_frame(frame, direction)
            return

        elif isinstance(frame, InterruptionFrame):
            if (
                not self._active
                and not self._current_sentence
                and not self._buffer.strip()
                and not self._pending_sentences
                and (not self._tts_queue or self._tts_queue.empty())
            ):
                logger.info("[TTS_STREAM] Forwarding idle interruption with no active local TTS")
                await self.push_frame(frame, direction)
                return
            # Cancel any pending TTS on interruption
            logger.info("[TTS_STREAM] Interruption received - cancelling TTS")
            await self._cancel_delayed_flush()
            # â”€â”€ STATE: Record interruption and cancel TTS â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
            _fallback_seed = (
                " ".join(
                    part for part in [
                        (self._current_sentence or "").strip(),
                        " ".join(s.strip() for s in self._pending_sentences if s and s.strip()).strip(),
                        self._buffer.strip(),
                    ]
                    if part
                ).strip()
            )
            _resume_seed = global_state_manager.build_unheard_resume_seed(_fallback_seed)
            global_state_manager.record_interruption(_resume_seed)
            if self._tts_task and not self._tts_task.done():
                self._tts_task.cancel()
                try:
                    await self._tts_task
                except asyncio.CancelledError:
                    logger.debug("[TTS_STREAM] TTS consumer cancelled on interruption")
                    pass
            try:
                from pipecat.frames.frames import CancelFrame
                await self._tts.cancel(CancelFrame())
                logger.info("[TTS_STREAM] Underlying TTS cancel dispatched")
            except Exception as _tts_cancel_err:
                logger.debug(f"[TTS_STREAM] Underlying TTS cancel failed/non-critical: {_tts_cancel_err}")
            # Clear any pending sentences in queue
            if self._tts_queue:
                # Drain the queue
                while not self._tts_queue.empty():
                    try:
                        _drained = self._tts_queue.get_nowait()
                        logger.debug(f"[TTS_STREAM] Drained pending sentence on interrupt")
                    except asyncio.QueueEmpty:
                        break
            self._buffer = ""
            self._active = False
            self._current_sentence = None
            self._pending_sentences = []
            self._turn_context_id = None
            self._generation_id = 0
            self._active_sentence_index = -1
            self._last_stale_text_log = None
            self._last_stale_queue_log = None
            await self.push_frame(frame, direction)
            
        elif isinstance(frame, LLMTextFrame):
            # Consume ALL LLMTextFrames here - never push them downstream to the tts
            # service, which would synthesize them again as a duplicate utterance.
            if not self._active:
                return
            _current_generation = int(global_state_manager.current_output_generation() or 0)
            if self._generation_id and self._generation_id != _current_generation:
                self._log_stale_generation_once("text", self._generation_id, _current_generation)
                return
            text = frame.text or ""
            if not text:
                return

            # AUDIT: Log every LLM chunk with timestamp
            _now = time.monotonic()
            _elapsed = int((_now - self._stream_start_ts) * 1000) if self._stream_start_ts else 0
            logger.debug(f"[LLM_STREAM] chunk={text!r} len={len(text)} t={_elapsed}ms")

            self._buffer += text
            self._buffer = _repair_tts_text_assembly(self._buffer)
            self._assembled_text = _repair_tts_text_assembly(self._assembled_text + text)  # accumulate full response for context aggregator
            self._total_chars += len(text)
            self._schedule_delayed_flush()

            # â”€â”€ Flush logic â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
            # Priority 1 â€“ hard sentence boundary (.!?\n): flush the full sentence
            # Priority 2 â€“ soft clause boundary (,;:) + buffer >= 20 chars: fire early
            # Priority 3 â€“ hard buffer cap (80+ chars with no boundary seen): flush anyway
            # This fires TTS as soon as the first complete clause is available rather
            # than waiting for the entire LLM response to finish streaming.

            flushed = True
            while flushed:
                flushed = False

                # Priority 1: hard sentence boundary
                match = self._SENTENCE_END_RE.search(self._buffer)
                if match:
                    await self._cancel_delayed_flush()
                    sentence_end = match.end()
                    sentence = self._buffer[:sentence_end].strip()
                    self._buffer = self._buffer[sentence_end:]
                    await self._emit_buffered_tts(sentence, "hard")
                    flushed = True
                    continue

                buf = self._buffer.strip()
                if not buf:
                    break

                # Priority 2: only split very long punctuation-free output as a fallback.
                split_result = self._split_long_unpunctuated_buffer(buf)
                if split_result:
                    await self._cancel_delayed_flush()
                    prefix, suffix = split_result
                    logger.info(f"[TTS_HARD_FLUSH] flushing at {len(buf)} chars")
                    self._buffer = suffix
                    await self._emit_buffered_tts(prefix, "hardcap")
                    flushed = True
                    continue

                # Priority 3: hard buffer cap - flush even without a boundary.
                # Use len(self._buffer) not len(buf): stripping whitespace from buf
                # can make the stripped length fall below 80 even when the raw buffer
                # has already passed the ceiling, causing the flush to fire one token
                # late (or never, if leading whitespace persists).

            if self._buffer.strip():
                logger.debug(f"[TTS_BUFFER] current_size={len(self._buffer)} chars, waiting for sentence boundary")
        else:
            # Pass through all other frames
            await self.push_frame(frame, direction)
    
    async def _queue_sentence(self, sentence: str):
        """Queue a sentence for TTS processing."""
        if self._tts_queue:
            _current_generation = int(global_state_manager.current_output_generation() or 0)
            if self._generation_id and self._generation_id != _current_generation:
                self._log_stale_generation_once("queue", self._generation_id, _current_generation)
                return
            self._enqueue_count += 1
            sentence_index = self._next_sentence_index
            self._next_sentence_index += 1
            self._pending_sentences.append(sentence)
            global_state_manager.note_sentence_registered(sentence_index, sentence)
            logger.debug(f"[TTS_QUEUE_DEBUG] enqueue #{self._enqueue_count}: {sentence[:40]!r}")
            await self._tts_queue.put((sentence_index, sentence))
    
    async def _tts_consumer(self):
        """Consumer that processes TTS queue sequentially."""
        try:
            while True:
                _current_generation = int(global_state_manager.current_output_generation() or 0)
                if self._generation_id and self._generation_id != _current_generation:
                    self._log_stale_generation_once("queue", self._generation_id, _current_generation)
                    break
                if not self._tts_queue:
                    break
                
                # Log queue size before getting next sentence
                _queue_size = self._tts_queue.qsize()
                if _queue_size > 0:
                    logger.debug(f"[TTS_QUEUE] size={_queue_size} (sentences waiting)")
                
                queue_item = await self._tts_queue.get()

                # None is sentinel to stop
                if queue_item is None:
                    logger.debug(f"[TTS_QUEUE_DEBUG] enqueue_count={self._enqueue_count} dequeue_count={self._dequeue_count}")
                    break
                sentence_index, sentence = queue_item

                self._dequeue_count += 1
                self._current_sentence = sentence
                self._active_sentence_index = sentence_index
                global_state_manager.note_sentence_started(sentence_index, sentence)
                if self._pending_sentences and self._pending_sentences[0] == sentence:
                    self._pending_sentences.pop(0)
                elif sentence in self._pending_sentences:
                    self._pending_sentences.remove(sentence)

                # Record wall-clock timestamp when first sentence is dispatched to Cartesia.
                # This is the true TTS request start - used by TTSActivityLogger for accurate TTFA.
                if self._dequeue_count == 1:
                    self._latency_trace_ref[0]["tts_request_start"] = time.time()

                # AUDIT: Log TTS call timing
                _call_time = time.monotonic()
                _time_since_start = int((_call_time - self._stream_start_ts) * 1000) if self._stream_start_ts else 0
                logger.info(f"[TTS_CALL] sentence={sentence[:60]!r}... time_since_turn_start={_time_since_start}ms")
                
                # Run TTS and push audio frames downstream
                _tts_gen = None
                _sentence_audio_bytes = 0
                try:
                    _context_id = self._turn_context_id or str(uuid.uuid4())
                    _tts_gen = self._tts.run_tts(sentence, _context_id)

                    async for tts_frame in _tts_gen:
                        _current_generation = int(global_state_manager.current_output_generation() or 0)
                        if self._generation_id and self._generation_id != _current_generation:
                            self._log_stale_generation_once("queue", self._generation_id, _current_generation)
                            break
                        if tts_frame is None:
                            continue
                        # Filter out TextFrame/LLMTextFrame emitted by the TTS service for each
                        # chunk - those would reach LLMContextAggregator as separate assistant
                        # messages, producing word-salad history. The assembled response is written
                        # directly to context via self._context.add_message() at TTS_STREAM_END.
                        if isinstance(tts_frame, TextFrame):
                            continue
                        if isinstance(tts_frame, TTSAudioRawFrame):
                            try:
                                setattr(tts_frame, "_output_generation_id", self._generation_id)
                                setattr(tts_frame, "_sentence_index", sentence_index)
                            except Exception:
                                pass
                            # AUDIO GAIN: Boost TTS output for telephony (inbound + outbound)
                            if tts_frame.audio:
                                try:
                                    tts_frame.audio = audioop.mul(tts_frame.audio, 2, 2.5)
                                except Exception as _gain_err:
                                    logger.warning(f"[AUDIO_GAIN] mul failed: {_gain_err}")
                            if not tts_frame.audio:
                                logger.warning("[AUDIO_FLOW] empty audio frame detected")
                            else:
                                logger.debug(f"[AUDIO_FLOW] pushed {len(tts_frame.audio)} bytes")
                                _sentence_audio_bytes += len(tts_frame.audio)
                        await self.push_frame(tts_frame, FrameDirection.DOWNSTREAM)

                    self._sentences_processed += 1
                    global_state_manager.note_sentence_audio(sentence_index, sentence, _sentence_audio_bytes)

                    # Log completion timing
                    _done_time = time.monotonic()
                    _tts_duration = int((_done_time - _call_time) * 1000)
                    logger.info(f"[TTS_CALL_DONE] sentence_processed in {_tts_duration}ms")
                    
                except Exception as e:
                    logger.error(f"[TTS_STREAM] TTS error for sentence: {e}")
                    # Properly close the async generator to prevent 'never awaited' warning
                    if _tts_gen:
                        try:
                            await _tts_gen.aclose()
                            logger.debug("[TTS_STREAM] TTS generator closed after error")
                        except Exception as close_err:
                            logger.debug(f"[TTS_STREAM] Error closing TTS generator: {close_err}")
                    
                    # Small delay to allow TTS service to recover before next sentence
                    await asyncio.sleep(0.05)
                    
                finally:
                    self._current_sentence = None
                    self._active_sentence_index = -1
                    _tts_gen = None
                
        except asyncio.CancelledError:
            logger.debug("[TTS_STREAM] Consumer cancelled")
            raise
        except Exception as e:
            logger.error(f"[TTS_STREAM] Consumer error: {e}")


def _is_progress_check_text(text: str) -> bool:
    lower = re.sub(r"[^\w\s]", " ", (text or "").strip().lower())
    lower = re.sub(r"\s+", " ", lower).strip()
    if not lower:
        return False
    patterns = (
        r"^(?:hello|hi|hey)$",
        r"(?:^|\s)(?:are you there|are you still there|still there)(?:\s|$)",
        r"(?:^|\s)(?:can you hear me|are you listening)(?:\s|$)",
        r"^(?:yes hello|hello are you there)$",
    )
    return any(re.search(pattern, lower, re.IGNORECASE) for pattern in patterns)


class IntegrationToolHandler:
    """
    Dynamically registers LLM function-call handlers from integration_configs.

    Each enabled integration exposes one or more endpoints as LLM tools.
    When the LLM decides to call a tool, the handler:
      1. Merges LLM arguments with call-context variables (caller phone/name)
      2. Executes the HTTP request (GET with query_template or POST with body_template)
      3. Extracts the relevant portion of the response via response_path
      4. Returns the result to the LLM as a FunctionCallResultFrame

    Integration config format (from /api/agent-config/assistant/:id):
      {
        "id": "...",
        "name": "JLL Property API",
        "slug": "jll_property",
        "endpoints": [
          {
            "id": "search_properties",          // used as tool/function name
            "name": "Search Properties",
            "description": "Search real estate listings by city, type, bedrooms",
            "method": "GET",
            "url": "https://example.com/api/projects",
            "llm_parameters": [                 // LLM extracts these from conversation
              {"name": "city", "type": "string", "required": false, "description": "City"},
              {"name": "limit", "type": "integer", "required": false, "default": 5}
            ],
            "context_variables": ["senderMobile", "senderName"],  // injected at runtime
            "query_template": "city={city}&limit={limit}",        // for GET requests
            "body_template": null,                                  // for POST requests (JSON string)
            "response_path": "data.projects",                      // dot-notation extraction
            "response_summary_prompt": null                         // optional LLM summarisation hint
          }
        ]
      }
    """

    def __init__(
        self,
        integrations: list,
        call_context: dict,
        context_ref: list = None,
        latency_trace_ref: list = None,
        filler_manager=None,
        transport=None,
        filler_playing_ref: list = None,
        call_closing_ref: list | None = None,
    ):
        self.integrations = integrations or []
        # call_context holds runtime variables like senderMobile, senderName
        self.call_context = call_context or {}
        # mutable reference to LLMContext - used to inject current search results
        # into the system prompt so the LLM never loses track in long conversations
        self._context_ref: list = context_ref if context_ref is not None else []
        self._latency_trace_ref: list = latency_trace_ref if latency_trace_ref is not None else [{}]
        # Filler audio for masking tool call latency
        self._filler_manager = filler_manager
        self._transport = transport
        self._filler_playing_ref: list = filler_playing_ref if filler_playing_ref is not None else [False]
        self._call_closing_ref = call_closing_ref
        # filler_active: True while HTTP request is in flight â†’ ToolAckFilter suppresses acks
        self.filler_active = False
        # Per-call search result cache: {project_slug â†’ full result dict}
        # Populated after every successful search_properties call.
        # Used by get_property_details to resolve slugs when the LLM passes a
        # wrong/hallucinated slug - we fuzzy-match against the cached names first.
        self._slug_cache: dict[str, dict] = {}  # slug â†’ result item
        self._name_to_slug: dict[str, str] = {}  # normalized_name â†’ slug
        # Per-call search context memory: persists city/location/budget/count across
        # multiple tool invocations in the same call so the assistant never re-asks
        # for details the user already provided earlier in the conversation.
        self._gathered_search: dict = {}
        # Pagination: JLL page number for current search + set of all slugs already shown
        # (used to pass exclude_slugs to backend so it deduplicates across pages)
        self._jll_page: int = 1
        self._shown_slugs: set = set()
        # Last search params snapshot - used to auto-detect "show more" vs fresh search.
        # Keys: city, location, property_type, min_price, max_price (all str or None).
        # When the LLM calls search_properties with the same params as last time AND
        # _shown_slugs is non-empty, we treat it as "show more" and auto-bump the page.
        self._last_search_key: str = ""
        # JLL catalog: fetched once per call from backend /api/integration/catalog
        # Contains supported cities, property types, locations, and price ranges per city.
        # Used for city/budget/location validation before any API call is made.
        self._catalog: dict | None = None
        self._pending_value_confirmation: dict | None = None
        # â”€â”€ Buyer persona â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        # Inferred from budget + explicit speech signals.
        # Values: "luxury" | "budget" | "investor" | "mid" (default)
        # Used to sort search results (price_desc / price_asc) and inject a
        # tone hint into the system prompt so the LLM adapts its style.
        self._persona: str = "mid"
        # "False" = not yet determined, "pending" = confirmation question asked,
        # "True" = confirmed and system prompt injected.
        self._persona_confirmed: bool | str = False
        # â”€â”€ Lead scoring â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        # Real-time score: "hot" | "warm" | "cold"
        # Updated after each tool call and stored in call metadata at call end.
        self._lead_score: str = "cold"
        # â”€â”€ Budget-too-low locked context â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        # When backend returns budget_too_low=true, we lock the confirmed city/
        # location/property_type here. On the NEXT search call (when user accepts
        # the higher price), we force-use these values regardless of what the LLM
        # passed - this guards against garbled STT ("increase to growth") causing
        # the gathering loop to re-ask for location or reset the session.
        self._budget_too_low_context: dict | None = None
        # â”€â”€ Gather-phase / property-phase prompt switching â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        # At startup we inject a compact 150-token gather prompt so TTFT stays low
        # while collecting city/type/budget/location. After the first successful
        # search_properties call we swap to the full integration prompt (stored here).
        self._full_integration_prompt: str = ""   # set by pipeline setup
        self._property_phase_active: bool = False  # True after first search succeeds
        # â”€â”€ Has-live-results flag for GatherStateHint â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        # True ONLY when search returned > 0 properties. False on zero results or
        # before first search. Used to determine if GatherStateHint should fire.
        self._has_live_results: bool = False
        # â”€â”€ Loop detection for gathering attempts â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        # Per-turn counter to detect when LLM is stuck asking the same field repeatedly
        self._gather_attempt_counts: dict = {}  # field -> count this turn
        self._last_gather_turn_id: str | None = None
        # Base persona prompt stored once at init - used to rebuild prompt during phase upgrade
        self._base_system_prompt: str = ""  # set by pipeline setup
        # â”€â”€ Parallel tool guard â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        # Only the FIRST tool result per user turn fires run_llm=True.
        # Reset by TranscriptionLogger on every new FINAL transcription.
        self._turn_llm_fired: bool = False
        self._turn_terminal_response_emitted: bool = False
        # Tracks last DirectInject mode for ContextAudit phase label
        self._last_inject_was_detail: bool = False
        # â”€â”€ Pre-fetch cache â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        # When user speech arrives (DirectInject), we fire the backend search
        # immediately in the background - before the LLM decides to call the tool.
        # The tool handler checks this cache first so it returns instantly (no HTTP
        # round-trip latency) when the LLM's tool call arrives ~1-3s later.
        # Structure: cache_key_str â†’ {"data": <result_dict>, "ts": <float>, "turn_id": <int>}
        # A key mapped to None means the prefetch is in-flight (don't duplicate).
        self._prefetch_cache: dict = {}
        # Monotonically-increasing turn counter for prefetch intent correlation.
        # Incremented whenever the search location changes so a stale prefetch
        # (fired for T Nagar) is rejected when the user has switched to OMR.
        self._prefetch_turn_id: int = 0
        # [OrdinalMap] Full ordered list of ALL properties shown this search session.
        # Soft cap at 50 for logging warnings - we keep full list but warn on growth.
        # Cleared on fresh search (new city/location/type/budget).
        self._ordinal_results: list = []
        # [OrdinalMap] Slug set for O(1) dedup when appending new pages.
        self._all_seen_slugs: set = set()
        # [ContextReduction] Hidden full-data store keyed by property_id/project_slug.
        # Populated on every search result; used for DETAIL VIEW injection so the
        # system prompt list stays minimal (nameâ€“BHKâ€“price only).
        self._property_details_map: dict = {}
        # Property IDs whose overview/details were already spoken in this search scope.
        self._detail_overview_spoken: set[str] = set()
        # [SessionGrowthSafety] Soft cap for ordinal results - warn but don't truncate
        self._MAX_ORDINAL_RESULTS = 50
        # Silent detail prefetch: warm get_property_details for the current top results
        # without blocking TTS presentation. Generation increments on fresh searches so
        # stale background responses are discarded automatically.
        self._detail_prefetch_tasks: dict[str, asyncio.Task] = {}
        self._detail_prefetch_generation: int = 0
        self._detail_prefetch_limit: int = 5
        self._active_property_id: str | None = None
        self._active_property_name: str | None = None
        self._explicit_property_focus_id: str | None = None
        self._forced_property_detail_id_once: str | None = None
        self._last_property_comparison: dict | None = None
        self._pending_property_comparison: dict | None = None
        self._pending_deterministic_detail: dict | None = None
        self._pending_property_lookup: dict | None = None
        self._pending_property_callback_offer: dict | None = None
        self._pending_user_offer: dict | None = None
        self._last_callback_confirmation: dict | None = None
        self._pending_variant_selection: dict | None = None
        self._zero_result_followup_mode: str | None = None
        self._zero_result_route_lock: str | None = None
        self._pending_budget_confirmation: dict | None = None
        self._zero_result_state: dict | None = None
        self._search_results_exhausted: bool = False
        self._last_deliverable_result_count: int = 0
        self._backend_search_key: str = ""
        self._conversation_scope_key: str = ""
        self._last_spoken_prompt: dict | None = None
        self._pending_gather_field: str | None = None
        self._pending_gather_prompt: str = ""
        self._pending_gather_scope_snapshot: str = ""
        self._spoken_turn_ledger: list[dict] = []
        self._spoken_turn_counter: int = 0
        self._locked_property_target: dict | None = None
        self._shortlist_playout_cursor: dict = {}
        self._shortlist_exposure_bucket: str = "none"
        # Prevents double CURRENT SEARCH RESULTS injection when parallel search_properties
        # calls (e.g. 2BHK + 3BHK) both complete in the same turn. Reset each user turn.
        self._results_injected_this_turn: bool = False
        self._property_detail_tool_turn_id: int = -1
        self._property_detail_tool_turn_property: str = ""
        self._submit_callback_tool_turn_id: int = -1
        self._submit_callback_tool_signature: str = ""
        self._closing_after_tool: bool = False
        self._tool_result_pending: bool = False
        self._llm_turn_in_progress: bool = False
        self._closing_after_tool_started_at: float = 0.0
        self._allow_property_direct_speech_once: bool = False
        # â”€â”€ Property Selection State Management â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        # Tracks when user has been presented properties and needs to select one
        self._selection_pending: bool = False
        # List of last presented properties with position, name, and property_id
        # Format: [{"position": 1, "name": "...", "property_id": "..."}, ...]
        self._last_presented_properties: list = []
        # Latest spoken shortlist page only. Unlike _ordinal_results, this is
        # reset on every shortlist/pagination delivery so ordinal follow-ups
        # resolve against the most recent page the user heard.
        self._current_shortlist_page_results: list = []
        self._shortlist_context_active: bool = False
        self._shortlist_presentation_stage: str = SHORTLIST_STAGE_INACTIVE
        self._shortlist_presentation_text: str = ""
        self._shortlist_started_at: float | None = None
        self._shortlist_committed_at: float | None = None
        self._shortlist_partial_at: float | None = None
        self._shortlist_context_label: str = ""
        self._shortlist_context_search_key: str = ""
        self._shortlist_clarification_attempts: int = 0
        # Ambiguous response patterns that should trigger clarification
        self._AMBIGUOUS_RESPONSES = {
            "yes", "yeah", "yep", "yup", "sure", "okay", "ok", "right",
            "tell me more", "more info", "more information", "details",
            "that sounds good", "sounds good", "great", "perfect",
        }
        # â”€â”€ Non-blocking missing param responses â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        # Cached responses for immediate return when required params are missing.
        # Eliminates blocking tool execution latency (was ~1500ms).
        self._missing_location_response = {
            "status": "missing_required_param",
            "param": "location",
            "response": "Which area or locality are you interested in?",
            "action": "request_clarification"
        }
        # City is hardcoded to Chennai - no missing city response needed
        # â”€â”€ Smart search results cache â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        # Cache search results between turns with param-based invalidation.
        # Eliminates duplicate HTTP calls when params haven't changed.
        self._search_results_cache: dict = {}  # key -> {data, params_snapshot, ts}
        self._last_search_params: dict = {}  # Track last search params for invalidation
        # â”€â”€ Prefetch optimization â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        # Session pre-warming: popular Chennai locations to prefetch on session start
        # Reduces cold-start latency for first search in common areas.
        # Prefetch seeds disabled - they were writing into _gathered_search.location
        # at session start, which then overwrote the user's actual location capture.
        # Re-enable only when prefetch is intent-aware (fires AFTER first user slot).
        self._default_prefetch_locations = []
        self._session_prewarmed = False  # Flag to track if pre-warming completed
        self._prefetch_in_progress = False  # Deduplication flag for concurrent prefetches
        self._prefetch_tasks: dict[str, asyncio.Task] = {}
        # â”€â”€ Gather-phase completion tracking â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        # Set by TranscriptionLogger when all 4 required params are detected in speech.
        # Used for diagnostic logging only; actual search trigger remains LLM-driven.
        self._gather_complete_logged: bool = False
        # Shared HTTP client with connection pooling for API calls
        self._http_client = httpx.AsyncClient(
            timeout=10.0,
            limits=httpx.Limits(max_connections=10, max_keepalive_connections=5),
        )

    def _log_session_snapshot(self, source: str) -> None:
        """Log complete session memory state at key decision points."""
        _gs = self._gathered_search
        logger.info(
            f"[SessionMemory][Snapshot][{source}] "
            f"city={_gs.get('city')} type={_gs.get('property_type')} "
            f"loc={_gs.get('location')} "
            f"budget={_gs.get('min_price')}-{_gs.get('max_price')} "
            f"results={_gs.get('result_count')} "
            f"citywide={_gs.get('_citywide_search')}"
        )

    def _build_conversation_scope_key(self, source: dict | None = None) -> str:
        source = source or self._gathered_search
        canonical_location = self.canonicalize_search_location(
            str(source.get("location") or "").strip(),
            str(source.get("city") or "").strip(),
        )
        return "|".join([
            str(source.get("city") or "").strip().lower(),
            canonical_location.strip().lower(),
            str(source.get("property_type") or "").strip().lower(),
            str(source.get("min_price") or ""),
            str(source.get("max_price") or ""),
        ])

    def _scope_matches_text(self, text: str) -> bool:
        lower = (text or "").strip().lower()
        if not lower:
            return False
        location = str(self._gathered_search.get("location") or "").strip().lower()
        city = str(self._gathered_search.get("city") or "").strip().lower()
        if location and location in lower:
            return True
        return bool(city and city in lower)

    def _enter_budget_confirmation(self, reason: str, *, awaiting_amount_only: bool = True) -> None:
        self._pending_budget_confirmation = {
            "reason": reason,
            "origin_turn_id": getattr(global_state_manager, "turn_id", None),
            "search_scope_snapshot": self._build_conversation_scope_key(),
            "awaiting_amount_only": bool(awaiting_amount_only),
        }
        logger.info(
            f"[BudgetConfirm] budget_confirm_entered reason={reason} "
            f"scope={self._pending_budget_confirmation['search_scope_snapshot']!r}"
        )

    def clear_pending_budget_confirmation(self, reason: str = "cleared") -> None:
        if self._pending_budget_confirmation:
            logger.info(f"[BudgetConfirm] budget_confirm_cleared_on_scope_change reason={reason}")
        self._pending_budget_confirmation = None

    def can_reuse_budget_anaphora(self, text: str) -> bool:
        lower = (text or "").strip().lower()
        if not re.search(r"\b(my budget|within my budget|in my budget)\b", lower):
            return False
        if not (self._gathered_search.get("min_price") or self._gathered_search.get("max_price")):
            return False
        if self._scope_matches_text(lower):
            return True
        return not re.search(r"\b(other area|another area|different area|omr|ecr|chennai|tambaram)\b", lower)

    def set_zero_result_state(
        self,
        mode: str,
        *,
        branch: str = "",
        response_text: str = "",
        route_lock: str = "",
    ) -> None:
        if route_lock:
            self._zero_result_route_lock = route_lock
        self._zero_result_followup_mode = mode
        self._zero_result_state = {
            "mode": mode,
            "branch": branch,
            "route_lock": route_lock or self._zero_result_route_lock or "",
            "scope_key": self._build_conversation_scope_key(),
            "location": str(self._gathered_search.get("location") or "").strip(),
            "city": str(self._gathered_search.get("city") or "").strip(),
            "property_type": str(self._gathered_search.get("property_type") or "").strip(),
            "bedrooms": str(self._gathered_search.get("bedrooms") or "").strip(),
            "project_category": str(self._gathered_search.get("project_category") or "").strip(),
            "construction_state": str(self._gathered_search.get("construction_state") or "").strip(),
            "min_price": self._gathered_search.get("min_price"),
            "max_price": self._gathered_search.get("max_price"),
            "response_text": response_text.strip(),
        }
        logger.info(
            f"[ZeroResultState] mode={mode} branch={branch or '-'} "
            f"scope={self._zero_result_state['scope_key']!r}"
        )

    def clear_zero_result_state(self, reason: str = "cleared") -> None:
        if self._zero_result_state:
            logger.info(f"[ZeroResultState] cleared reason={reason}")
        self._zero_result_state = None
        self._zero_result_followup_mode = None
        self._zero_result_route_lock = None
        for key in list(self._gathered_search.keys()):
            if str(key).startswith("_zero_result_"):
                self._gathered_search.pop(key, None)

    def has_pending_zero_result_state(self) -> bool:
        return bool(self._zero_result_state)

    def _begin_terminal_tool_response(self, tool_name: str) -> None:
        if tool_name not in {"submit_callback", "schedule_site_visit"}:
            return
        self._closing_after_tool = True
        self._tool_result_pending = True
        self._llm_turn_in_progress = False
        self._closing_after_tool_started_at = time.time()
        logger.info(f"[CloseGuard] terminal tool started tool={tool_name}")

    def _mark_terminal_tool_result_ready(self, tool_name: str, *, run_llm: bool) -> None:
        if tool_name not in {"submit_callback", "schedule_site_visit"}:
            return
        self._tool_result_pending = False
        self._llm_turn_in_progress = bool(run_llm)
        logger.info(f"[CloseGuard] terminal tool result ready tool={tool_name} run_llm={run_llm}")

    def clear_terminal_tool_response_flags(self, reason: str) -> None:
        if self._closing_after_tool or self._tool_result_pending or self._llm_turn_in_progress:
            logger.info(f"[CloseGuard] terminal tool flags cleared reason={reason}")
        self._closing_after_tool = False
        self._tool_result_pending = False
        self._llm_turn_in_progress = False
        self._closing_after_tool_started_at = 0.0

    def _normalize_budget_pair(
        self,
        min_price,
        max_price,
        *,
        source: str = "",
    ) -> tuple[int | None, int | None]:
        try:
            min_value = int(min_price) if min_price is not None else None
        except Exception:
            min_value = None
        try:
            max_value = int(max_price) if max_price is not None else None
        except Exception:
            max_value = None
        if min_value is not None and max_value is not None and min_value > max_value:
            logger.warning(
                f"[BudgetNormalize] inverted range repaired source={source or '-'} "
                f"min={min_value} max={max_value}"
            )
            min_value, max_value = max_value, min_value
        return min_value, max_value

    def _normalize_and_commit_budget(
        self,
        min_price,
        max_price,
        *,
        source: str = "",
        target: dict | None = None,
    ) -> tuple[int | None, int | None]:
        min_value, max_value = self._normalize_budget_pair(
            min_price,
            max_price,
            source=source,
        )
        store = target if target is not None else self._gathered_search
        if min_value is None:
            store.pop("min_price", None)
        else:
            store["min_price"] = min_value
        if max_value is None:
            store.pop("max_price", None)
        else:
            store["max_price"] = max_value
        if min_value is not None or max_value is not None:
            store.pop("_budget_flexible", None)
        return min_value, max_value

    def set_pending_gather_resume_state(self, field: str | None, prompt: str | None, *, source: str = "") -> None:
        clean_prompt = str(prompt or "").strip()
        clean_field = str(field or "").strip() or None
        if not clean_field or not clean_prompt:
            self.clear_pending_gather_resume_state(source or "empty_update")
            return
        self._pending_gather_field = clean_field
        self._pending_gather_prompt = clean_prompt
        self._pending_gather_scope_snapshot = self._build_conversation_scope_key()
        logger.info(
            f"[GatherResume] set field={self._pending_gather_field} "
            f"scope={self._pending_gather_scope_snapshot!r} source={source or '-'}"
        )

    def clear_pending_gather_resume_state(self, reason: str = "cleared") -> None:
        if self._pending_gather_field or self._pending_gather_prompt:
            logger.info(
                f"[GatherResume] cleared field={self._pending_gather_field or '-'} "
                f"reason={reason}"
            )
        self._pending_gather_field = None
        self._pending_gather_prompt = ""
        self._pending_gather_scope_snapshot = ""

    def set_pending_user_offer(
        self,
        offer_type: str,
        *,
        property_id: str | None = None,
        property_name: str | None = None,
        location: str | None = None,
        min_price: int | None = None,
        max_price: int | None = None,
        source: str = "",
    ) -> None:
        offer_type = str(offer_type or "").strip()
        if not offer_type:
            self.clear_pending_user_offer("empty_offer")
            return
        self._pending_user_offer = {
            "offer_type": offer_type,
            "property_id": str(property_id or self._active_property_id or "").strip(),
            "property_name": str(property_name or self._active_property_name or "").strip(),
            "location": str(location or self._gathered_search.get("location") or "").strip(),
            "min_price": min_price,
            "max_price": max_price,
            "created_turn_id": int(global_state_manager.turn_id or 0),
            "resolved": False,
            "source": source or offer_type,
        }
        logger.info(
            f"[PendingOffer] set type={offer_type} property={self._pending_user_offer.get('property_name') or '-'} "
            f"location={self._pending_user_offer.get('location') or '-'} source={source or '-'}"
        )

    def clear_pending_user_offer(self, reason: str = "cleared") -> None:
        if self._pending_user_offer:
            logger.info(
                f"[PendingOffer] cleared type={self._pending_user_offer.get('offer_type') or '-'} "
                f"reason={reason}"
            )
        self._pending_user_offer = None

    def mark_callback_confirmation(self, property_name: str = "", location: str = "") -> None:
        self._last_callback_confirmation = {
            "property_name": str(property_name or "").strip(),
            "location": str(location or self._gathered_search.get("location") or "").strip(),
            "created_turn_id": int(global_state_manager.turn_id or 0),
            "created_at": time.time(),
        }
        if self._selection_pending:
            self._selection_pending = False
        self._shortlist_clarification_attempts = 0
        logger.info(
            f"[CallbackIntent] terminal callback state set "
            f"property={self._last_callback_confirmation.get('property_name') or '-'} "
            f"location={self._last_callback_confirmation.get('location') or '-'}"
        )

    def has_recent_callback_confirmation(self, max_turns: int = 2, max_age_s: float = 45.0) -> bool:
        state = self._last_callback_confirmation or {}
        if not state:
            return False
        created_turn = int(state.get("created_turn_id") or 0)
        current_turn = int(global_state_manager.turn_id or 0)
        created_at = float(state.get("created_at") or 0)
        if created_turn and current_turn - created_turn > max_turns:
            return False
        if created_at and time.time() - created_at > max_age_s:
            return False
        return True

    def build_recent_callback_ack_response(self, text: str) -> str | None:
        if self._call_closing_ref is not None and self._call_closing_ref[0]:
            return None
        if not self.has_recent_callback_confirmation():
            return None
        if self.is_deterministic_closing_turn(text):
            return None
        lower = self._normalize_short_reply_text(text)
        if not (
            self.is_non_substantive_ack(text)
            or re.match(r"^(?:ok|okay|thanks?|thank\s+you|fine|alright|all\s+right|got\s+it|sure)$", lower)
        ):
            return None
        return "You're welcome. One of our JLL Homes property specialists will reach out shortly."

    def _normalize_short_reply_text(self, text: str) -> str:
        lower = re.sub(r"[^\w\s]", " ", (text or "").strip().lower())
        return re.sub(r"\s+", " ", lower).strip()

    def is_closing_gratitude_reply(self, text: str) -> bool:
        lower = self._normalize_short_reply_text(text)
        if not lower:
            return False
        compact = lower.replace("all right", "alright").replace("thank you", "thanks")
        allowed_words = {
            "ok", "okay", "fine", "alright", "got", "it", "sure",
            "thanks", "thank", "you", "bye", "goodbye",
        }
        if any(word not in allowed_words for word in lower.split()):
            return False
        if not re.search(r"\b(?:thanks|thank\s+you)\b", lower):
            return False
        return bool(
            re.fullmatch(
                r"(?:(?:ok|okay|fine|alright|all\s+right|got\s+it|sure)\s+)?"
                r"(?:thanks|thank\s+you)"
                r"(?:\s+(?:ok|okay|fine|alright|all\s+right|got\s+it|sure))?"
                r"(?:\s+(?:bye|goodbye))?",
                lower,
            )
            or compact in {
                "thanks", "ok thanks", "okay thanks", "thanks ok",
                "thanks okay", "thanks bye", "ok thanks bye", "okay thanks bye",
            }
        )

    def is_short_negative_reply(self, text: str) -> bool:
        return bool(_NEGATIVE_ONLY_RE.match(text or ""))

    def is_short_affirmative_reply(self, text: str) -> bool:
        return bool(_AFFIRM_ONLY_RE.match(text or ""))

    def build_pending_offer_decline_response(self, text: str) -> str | None:
        if not self._pending_user_offer or not self.is_short_negative_reply(text):
            return None
        offer = dict(self._pending_user_offer)
        self.clear_pending_user_offer("declined")
        offer_type = str(offer.get("offer_type") or "")
        if "site_visit" in offer_type:
            return "No problem. I won't schedule a site visit."
        if "callback" in offer_type:
            return "No problem. I won't arrange a callback."
        if "zero_result" in offer_type:
            return "No problem. What budget or area would you like me to try?"
        return "No problem. What would you like to do next?"

    def maybe_set_offer_from_spoken_prompt(self, text: str, *, source: str = "") -> None:
        lower = (text or "").strip().lower()
        if not lower:
            return
        if re.search(r"\b(callback|call\s+back)\b", lower) and lower.rstrip().endswith("?"):
            self.set_pending_user_offer(
                "callback",
                property_id=self._active_property_id,
                property_name=self._active_property_name,
                source=source or "spoken_prompt",
            )
        if re.search(r"\b(site\s+visit|visit)\b", lower) and lower.rstrip().endswith("?"):
            self.set_pending_user_offer(
                "site_visit",
                property_id=self._active_property_id,
                property_name=self._active_property_name,
                source=source or "spoken_prompt",
            )

    def should_skip_duplicate_spoken_prompt(self, text: str, *, source: str = "") -> bool:
        last = self._last_spoken_prompt or {}
        last_source = str(last.get("source") or "")
        if not last_source.startswith("response_guard:"):
            return False
        current_norm = re.sub(r"\s+", " ", _cleanup_tts_text(text or "")).strip().lower()
        last_norm = re.sub(r"\s+", " ", _cleanup_tts_text(str(last.get("spoken_text") or ""))).strip().lower()
        if current_norm and current_norm == last_norm:
            logger.info(
                f"[Transcript] duplicate deterministic prompt skipped source={source or '-'} "
                f"last_source={last_source}"
            )
            return True
        return False

    def build_pending_gather_resume_prompt(self) -> str | None:
        prompt = str(self._pending_gather_prompt or "").strip()
        if not prompt or not self._pending_gather_field:
            return None
        field = self._pending_gather_field
        if field == "property_type" and self._gathered_search.get("property_type"):
            logger.info("[GatherGuard] blocked_duplicate_prompt field=property_type reason=slot_already_captured")
            self.clear_pending_gather_resume_state("slot_already_captured")
            return None
        if field == "budget" and (
            self._gathered_search.get("min_price")
            or self._gathered_search.get("max_price")
            or self._gathered_search.get("_budget_flexible")
        ):
            logger.info("[GatherGuard] blocked_duplicate_prompt field=budget reason=slot_already_captured")
            self.clear_pending_gather_resume_state("slot_already_captured")
            return None
        if field == "location" and (
            self._gathered_search.get("location")
            or self._gathered_search.get("_citywide_search")
        ):
            logger.info("[GatherGuard] blocked_duplicate_prompt field=location reason=slot_already_captured")
            self.clear_pending_gather_resume_state("slot_already_captured")
            return None
        return prompt

    def remember_spoken_prompt(
        self,
        text: str,
        *,
        kind: str = "assistant_reply",
        property_ids: list[str] | None = None,
        question_expected: bool = False,
        source: str = "",
    ) -> None:
        text = (text or "").strip()
        if not text:
            return
        self._spoken_turn_counter += 1
        prompt = {
            "id": self._spoken_turn_counter,
            "kind": kind,
            "spoken_text": text,
            "scope": self._build_conversation_scope_key(),
            "property_ids": [pid for pid in (property_ids or []) if pid],
            "question_expected": bool(question_expected),
            "source": source or kind,
            "started_at": time.time(),
            "truncated_at": None,
            "committed_audio_ms": 0,
        }
        self._last_spoken_prompt = prompt
        self._spoken_turn_ledger.append(prompt)
        if kind == "assistant_reply":
            expected_field = _detect_expected_gather_field(
                [{"role": "assistant", "content": text}],
                city=str(self._gathered_search.get("city") or "Chennai"),
            )
            if expected_field:
                self.set_pending_gather_resume_state(
                    expected_field,
                    text,
                    source=source or kind,
                )
            else:
                pending_field = str(self._pending_gather_field or "").strip()
                liveness_reply = bool(
                    pending_field
                    and (source or kind) == "direct_speech"
                    and re.search(r"\b(?:i can hear you|i'?m here|yes[, ]+i can hear)\b", text, re.IGNORECASE)
                )
                if liveness_reply:
                    logger.warning(
                        f"[GatherResume] blocked clear from liveness reply field={pending_field} "
                        f"reason=non_gather_prompt:{source or kind}"
                    )
                    logger.info(
                        f"[GatherResume] preserved field={pending_field} reason=liveness_check_mid_gather"
                    )
                    self.set_pending_gather_resume_state(
                        pending_field,
                        self._pending_gather_prompt or text,
                        source="liveness_check_mid_gather",
                    )
                else:
                    self.clear_pending_gather_resume_state(f"non_gather_prompt:{source or kind}")
        elif kind in {"shortlist", "property_detail", "variant_clarification"}:
            self.clear_pending_gather_resume_state(f"phase_shift:{kind}")
        self.maybe_set_offer_from_spoken_prompt(text, source=source or kind)
        logger.info(
            f"[Transcript] transcript_turn_persisted source={prompt['source']} "
            f"id={prompt['id']} kind={kind}"
        )

    def mark_last_spoken_prompt_truncated(self, reason: str, committed_audio_ms: int = 0) -> None:
        if not self._last_spoken_prompt:
            return
        self._last_spoken_prompt["truncated_at"] = time.time()
        self._last_spoken_prompt["committed_audio_ms"] = max(
            int(committed_audio_ms or 0),
            int(self._last_spoken_prompt.get("committed_audio_ms") or 0),
        )
        logger.info(
            f"[Transcript] transcript_turn_truncated id={self._last_spoken_prompt.get('id')} "
            f"reason={reason} committed_audio_ms={self._last_spoken_prompt.get('committed_audio_ms')}"
        )

    def classify_repair_turn(self, text: str) -> str | None:
        lower = (text or "").strip().lower()
        if not lower:
            return None
        if self.is_progress_check(lower):
            return "progress_check"
        if re.match(r"^(what\?|what|sorry\??|come again|pardon|can you repeat(?: that)?|repeat that|say that again)$", lower, re.IGNORECASE):
            return "repeat_request"
        if re.match(r"^(no[, ]+i asked|no[, ]+i meant|that'?s not what i asked|i asked for)\b", lower, re.IGNORECASE):
            return "repair_confused"
        if self.is_non_substantive_ack(lower):
            return "ack"
        return None

    def build_repair_response(self, text: str, repair_kind: str) -> str | None:
        if repair_kind == "progress_check":
            self.clear_pending_property_lookup()
            self.clear_pending_property_callback_offer()
            return self.build_progress_check_reply()
        if repair_kind == "repair_confused":
            if _parse_inr_amounts(text or "", allow_bare_rupees=True):
                logger.info(f"[Repair] budget_correction_deferred_to_search text={text!r}")
                return None
            comparison_reply = self.build_property_comparison_response(text)
            if comparison_reply:
                logger.info(f"[Repair] comparison_repair_handled text={text!r}")
                return comparison_reply
        if repair_kind in {"repeat_request", "repair_confused"}:
            if self._pending_property_callback_offer:
                _property_name = str(self._pending_property_callback_offer.get("property_name") or "").strip()
                return f"{_callback_offer_text(_property_name)} Please say yes or no."
            if self._zero_result_state and self._zero_result_state.get("response_text"):
                return self._zero_result_state["response_text"]
            if self.shortlist_is_partial():
                replay = self.build_relist_response("list the properties again")
                if replay:
                    return f"Let me quickly repeat the options. {replay}"
            if self._pending_variant_selection:
                return self.build_variant_clarification_text(self._pending_variant_selection)
            useful_prompt = self._last_useful_spoken_prompt()
            if useful_prompt and useful_prompt.get("spoken_text"):
                spoken = str(useful_prompt["spoken_text"] or "").strip()
                if re.search(r"could not identify the exact property", spoken, re.IGNORECASE):
                    if self.has_active_shortlist_context():
                        return self.build_shortlist_clarification_text()
                    return "I can help with the property search. Which area or property should I search for?"
                return spoken
        return None

    def _is_low_value_repeat_prompt(self, prompt: dict | None) -> bool:
        if not isinstance(prompt, dict):
            return True
        text = str(prompt.get("spoken_text") or "").strip()
        if not text:
            return True
        lower = re.sub(r"\s+", " ", text.lower()).strip()
        low_value_patterns = (
            r"^yes[, ]+i(?:'| a)m here\.?\s+please go ahead\.?$",
            r"^yes[, ]+i can hear you\.?\s+please go ahead\.?$",
            r"^hello\??\s+are you still there\??$",
            r"^please go ahead\.?$",
        )
        return any(re.match(pattern, lower, re.IGNORECASE) for pattern in low_value_patterns)

    def _last_useful_spoken_prompt(self) -> dict | None:
        for prompt in reversed(self._spoken_turn_ledger):
            if not isinstance(prompt, dict):
                continue
            if self._is_low_value_repeat_prompt(prompt):
                continue
            text = str(prompt.get("spoken_text") or "").strip()
            if not text:
                continue
            return prompt
        return None

    def is_zero_result_starting_price_request(self, text: str) -> bool:
        lower = (text or "").strip().lower()
        if not (lower and self._zero_result_state):
            return False
        _zr_loc = str(self._zero_result_state.get("location") or "").strip().lower()
        _explicit_scope = bool(_zr_loc and re.search(r"\b" + re.escape(_zr_loc) + r"\b", lower))
        return bool(
            re.search(r"\b(starting price|starting place|minimum price|price starts|how much)\b", lower)
            and not re.search(r"\b(find|show|check|search)\b", lower)
            and not _explicit_scope
        )

    def build_zero_result_starting_price_response(self) -> str | None:
        if not self._zero_result_state:
            return None
        location = self._zero_result_state.get("location") or self._zero_result_state.get("city") or "that area"
        property_type = self._zero_result_state.get("property_type") or "properties"
        return (
            f"I didn't find matching {property_type} in {location} within your current budget. "
            "If you'd like, I can check lower-priced options in the same area or suggest nearby areas."
        )

    def is_zero_result_other_areas_request(self, text: str) -> bool:
        lower = (text or "").strip().lower()
        return bool(lower and _ZERO_RESULT_OTHER_AREAS_RE.search(lower))

    def is_zero_result_affirmative(self, text: str) -> bool:
        lower = re.sub(r"\s+", " ", (text or "").strip().lower())
        return bool(lower and (_AFFIRM_ONLY_RE.match(lower) or lower in {"yes please", "yes, please", "okay", "ok", "sure", "go ahead", "show me", "yes yes please"}))

    def lock_property_target(self, property_ref: dict | None, *, source: str = "") -> None:
        if not property_ref:
            self._locked_property_target = None
            return
        property_id = str(property_ref.get("property_id") or property_ref.get("project_slug") or "").strip()
        if not property_id:
            return
        active_id = str(self._active_property_id or "").strip()
        if active_id and active_id != property_id:
            logger.info(
                f"[PropertyFocus] clearing conflicting active property active_id={active_id} "
                f"locked_id={property_id} source={source or 'selection'}"
            )
            self._active_property_id = None
            self._active_property_name = None
            self._explicit_property_focus_id = None
        self._locked_property_target = {
            "property_id": property_id,
            "project_slug": str(property_ref.get("project_slug") or property_id).strip(),
            "project_name": str(property_ref.get("name") or property_ref.get("project_name") or "").strip(),
            "source": source or "selection",
            "scope_key": self._conversation_scope_key or self._build_conversation_scope_key(),
        }
        logger.info(
            f"[PropertyLock] exact property target lock set property_id={property_id} "
            f"source={self._locked_property_target['source']}"
        )

    def clear_locked_property_target(self, reason: str = "cleared") -> None:
        if self._locked_property_target:
            logger.info(
                f"[PropertyLock] exact property target cleared reason={reason} "
                f"property_id={self._locked_property_target.get('property_id')}"
            )
        self._locked_property_target = None

    def current_locked_property_target(self) -> dict | None:
        return self._locked_property_target

    def _locked_target_matches_request(self, locked_target: dict | None, requested: str) -> bool:
        requested_norm = self._normalize_property_lookup_key(requested)
        if not locked_target or not requested_norm:
            return False
        locked_values = {
            str(locked_target.get("property_id") or ""),
            str(locked_target.get("project_slug") or ""),
            str(locked_target.get("project_name") or ""),
            str(locked_target.get("name") or ""),
        }
        for value in locked_values:
            value_norm = self._normalize_property_lookup_key(value)
            if value_norm and (
                value_norm == requested_norm
                or value_norm in requested_norm
                or requested_norm in value_norm
            ):
                return True
        return False

    def has_exhausted_search_results(self) -> bool:
        return bool(self._search_results_exhausted and self._last_deliverable_result_count > 0)

    def mark_search_results_exhausted(self) -> None:
        self._search_results_exhausted = True
        logger.info(
            f"[Pagination] Exhausted shortlist preserved count={self._last_deliverable_result_count} "
            f"search_key={self._last_search_key!r}"
        )

    def clear_search_results_exhausted(self) -> None:
        self._search_results_exhausted = False

    def _current_scope_label(self) -> str:
        location = str(self._gathered_search.get("location") or "").strip()
        if location:
            return location
        city = str(self._gathered_search.get("city") or "").strip()
        return city or "this search"

    def build_exhausted_results_response(self) -> str | None:
        count = int(self._last_deliverable_result_count or len(self._shown_slugs) or 0)
        if count <= 0:
            return None
        scope = self._current_scope_label()
        ptype = str(self._gathered_search.get("property_type") or "properties").strip().lower() or "properties"
        if count == 1:
            return (
                f"I've shown the matching {ptype} I have in {scope}. "
                "Would you like another area, a different budget, or a JLL Homes property specialist callback?"
            )
        return (
            f"I've shown all {count} matching {ptype} I have in {scope}. "
            "Would you like another area, a different budget, or a JLL Homes property specialist callback?"
        )

    def can_answer_result_count_from_state(self, text: str) -> bool:
        lower = (text or "").strip().lower()
        if not lower or not self.has_exhausted_search_results():
            return False
        if not re.search(r"\b(how many|number of|count|available)\b", lower):
            return False
        if not re.search(r"\b(properties|property|apartments|apartment|options|results)\b", lower):
            return False
        if not re.search(r"\b(my budget|within my budget|in my budget)\b", lower):
            return False
        active_location = str(self._gathered_search.get("location") or "").strip().lower()
        if active_location and active_location not in lower:
            if any(loc_token in lower for loc_token in ("other area", "another area", "different area", "omr", "ecr")):
                return False
        return True

    def build_result_count_recap_response(self) -> str | None:
        count = int(self._last_deliverable_result_count or len(self._shown_slugs) or 0)
        if count <= 0:
            return None
        scope = self._current_scope_label()
        noun = "property" if count == 1 else "properties"
        return f"There {'is' if count == 1 else 'are'} {count} {noun} in {scope} within your budget."

    def can_answer_shortlist_location_recap(self, text: str) -> bool:
        lower = (text or "").strip().lower()
        return bool(
            lower
            and self.has_active_shortlist_context()
            and re.search(r"\b(where|which area|what area|located)\b", lower)
            and re.search(r"\b(properties|property|these|those|projects|options)\b", lower)
        )

    def build_shortlist_location_recap_response(self) -> str | None:
        if not self.has_active_shortlist_context():
            return None
        scope = self._current_scope_label()
        return f"These properties are located in {scope}. Would you like details on any specific one?"

    def can_answer_shortlist_price_recap(self, text: str) -> bool:
        return bool(self.is_area_price_summary_request(text) and self.has_active_shortlist_context())

    def is_area_price_summary_request(self, text: str) -> bool:
        lower = (text or "").strip().lower()
        return bool(
            lower
            and re.search(
                r"\b(starting price|price starts|price start|start from|starts from|"
                r"starting place|starting budget|minimum budget|min budget|lowest budget|"
                r"minimum price|min price|lowest price|cheapest|base price|"
                r"starting range|minimum range|price range|how much|budget available|"
                r"available budget|what budget|which budget|budget range available)\b",
                lower,
            )
        )

    def build_shortlist_price_recap_response(self) -> str | None:
        if not self.has_active_shortlist_context():
            return None
        prices = []
        for prop in self._last_presented_properties or []:
            value = self._extract_presented_property_min_price(prop)
            if value > 0:
                prices.append(value)
        if not prices:
            return None
        start_price = _format_price_indian(min(prices))
        scope = self._current_scope_label()
        return f"The starting price for the properties I've shared in {scope} is around {start_price}."

    def _extract_presented_property_min_price(self, prop: dict) -> int:
        candidates = [
            prop.get("price_value"),
            prop.get("min_price"),
            prop.get("starting_price"),
            prop.get("price"),
        ]
        for variant in prop.get("variants") or []:
            candidates.extend([
                variant.get("price_num"),
                variant.get("price_value"),
                variant.get("min_price"),
                variant.get("starting_price"),
                variant.get("price"),
            ])
        values = []
        for candidate in candidates:
            if candidate in (None, "", float("inf")):
                continue
            try:
                value = int(float(candidate))
                if value > 0:
                    values.append(value)
            except Exception:
                continue
        return min(values) if values else 0

    async def try_build_area_price_summary_response(self, text: str) -> str | None:
        if not self.is_area_price_summary_request(text):
            return None

        search_endpoint = self._find_endpoint("search_properties")
        if not search_endpoint:
            logger.warning("[PriceSummary] search_properties endpoint unavailable")
            return None

        zero_scope = self._zero_result_state or {}
        location = str(
            zero_scope.get("location")
            or self._gathered_search.get("_zero_result_origin_location")
            or self._gathered_search.get("location")
            or ""
        ).strip()
        if not location:
            return None

        city = str(
            zero_scope.get("city")
            or self._gathered_search.get("_zero_result_origin_city")
            or self._gathered_search.get("city")
            or "Chennai"
        ).strip() or "Chennai"
        property_type = str(
            zero_scope.get("property_type")
            or self._gathered_search.get("_zero_result_origin_property_type")
            or self._gathered_search.get("property_type")
            or "Apartments"
        ).strip() or "Apartments"
        bedrooms = str(
            zero_scope.get("bedrooms")
            or self._gathered_search.get("_zero_result_origin_bedrooms")
            or self._gathered_search.get("bedrooms")
            or ""
        ).strip()
        if not _property_type_supports_bedrooms(property_type):
            bedrooms = ""
        explicit_construction = None
        lower_text = (text or "").strip().lower()
        if _READY_TO_MOVE_RE.search(lower_text):
            explicit_construction = "ready_to_move"
        elif _UNDER_CONSTRUCTION_RE.search(lower_text):
            explicit_construction = "under_construction"
        elif _LAUNCHED_RE.search(lower_text):
            explicit_construction = "launched"
        project_category = str(
            zero_scope.get("project_category")
            or self._gathered_search.get("_zero_result_origin_project_category")
            or self._gathered_search.get("project_category")
            or ""
        ).strip()
        construction_state = str(
            explicit_construction
            or zero_scope.get("construction_state")
            or self._gathered_search.get("_zero_result_origin_construction_state")
            or ""
        ).strip()

        search_params = {
            "city": city,
            "location": location,
            "property_type": property_type,
            "min_price": 0,
            "max_price": 50_000_000,
            "result_count": 20,
            "sort_preference": "price_asc",
        }
        if bedrooms:
            search_params["bedrooms"] = bedrooms
        if project_category:
            search_params["project_category"] = project_category
        if construction_state:
            search_params["construction_state"] = construction_state

        logger.info(
            "[PriceSummary] deterministic exact-locality search "
            f"location={location!r} type={property_type!r} bedrooms={bedrooms or '-'} "
            f"construction={construction_state or '-'}"
        )
        result = await self._execute_endpoint(search_endpoint, search_params)
        if result.get("success") and isinstance(result.get("data"), list) and result.get("data"):
            result = {
                **result,
                "searched_location": result.get("searched_location") or location,
                "searched_city": result.get("searched_city") or city,
                "searched_property_type": result.get("searched_property_type") or property_type,
                "searched_bedrooms": result.get("searched_bedrooms") or bedrooms,
                "property_type": result.get("property_type") or property_type,
            }
            spoken = _build_search_starting_price_speech(result)
            if spoken:
                prices = [
                    self._extract_presented_property_min_price(item)
                    for item in (result.get("data") or [])
                    if isinstance(item, dict)
                ]
                prices = [price for price in prices if price > 0]
                if prices:
                    lowest = min(prices)
                    self.set_pending_user_offer(
                        "zero_result_price_range",
                        location=location,
                        min_price=0,
                        max_price=max(lowest, int(lowest * 1.2)),
                        source="price_summary",
                    )
                self.clear_zero_result_state("price_summary_answered")
                self._clear_zero_result_followup_state()
                logger.info("[PriceSummary] deterministic response built from search results")
                return spoken

        ptype_label = f"{bedrooms} BHK {property_type}".strip() if bedrooms else property_type
        logger.info(
            f"[PriceSummary] no lower-priced results found location={location!r} "
            f"type={ptype_label!r}"
        )
        if not _property_type_supports_bedrooms(property_type):
            return (
                f"I couldn't find any {property_type.lower()} in {location} at a lower price right now. "
                "Would you like me to check other areas, or should we try a higher budget?"
            )
        return (
            f"I couldn't find a lower-priced {ptype_label} in {location}. "
            "Would you like me to broaden the BHK or property type?"
        )

    def _find_endpoint(self, endpoint_id: str) -> dict | None:
        for integration in self.integrations:
            for endpoint in integration.get("endpoints", []) or []:
                if endpoint.get("id") == endpoint_id:
                    return endpoint
        return None

    def _cancel_detail_prefetches(self, reason: str) -> None:
        if not self._detail_prefetch_tasks:
            return
        for _pid, _task in list(self._detail_prefetch_tasks.items()):
            if _task and not _task.done():
                _task.cancel()
        logger.info(
            f"[DetailPrefetch] Cancelled {len(self._detail_prefetch_tasks)} task(s) "
            f"reason={reason}"
        )
        self._detail_prefetch_tasks.clear()

    def _has_prefetched_detail(self, property_id: str) -> bool:
        _cached = self._property_details_map.get(property_id) or {}
        return bool(
            _cached.get("amenities")
            or _cached.get("configs")
            or _cached.get("developer")
            or _cached.get("rera")
            or _cached.get("address")
            or _cached.get("description")
        )

    def _cached_detail_can_answer_fact(self, cached: dict, fact: str | None) -> bool:
        if not fact:
            return True
        if fact == "rera":
            return bool(self._extract_rera_text(cached))
        return True

    def _clear_property_comparison_context(self, reason: str) -> None:
        if self._last_property_comparison or self._pending_property_comparison:
            logger.info(f"[Comparison] cleared_context reason={reason}")
        self._last_property_comparison = None
        self._pending_property_comparison = None

    def _store_last_property_comparison(self, fact: str, properties: list[dict]) -> None:
        if len(properties or []) < 2:
            return
        self._last_property_comparison = {
            "fact": fact or "price",
            "properties": [dict(prop) for prop in properties[:2] if isinstance(prop, dict)],
        }
        self._pending_property_comparison = None
        logger.info(
            f"[Comparison] stored_last fact={fact or 'price'} "
            f"properties={[p.get('name') or p.get('project_name') or p.get('property_id') for p in properties[:2]]}"
        )

    def _store_pending_property_comparison(self, fact: str) -> None:
        self._pending_property_comparison = {"fact": fact or "price"}
        logger.info(f"[Comparison] stored_pending fact={fact or 'price'}")

    def _mark_detail_overview_spoken(self, property_ref: dict | str | None, *, source: str = "") -> None:
        property_id = _property_ref_id(property_ref)
        if not property_id:
            return
        if property_id not in self._detail_overview_spoken:
            logger.info(
                f"[PropertyDetailMemory] marked_overview_spoken property_id={property_id} "
                f"source={source or '-'}"
            )
        self._detail_overview_spoken.add(property_id)

    def _has_detail_overview_spoken(self, property_ref: dict | str | None) -> bool:
        property_id = _property_ref_id(property_ref)
        return bool(property_id and property_id in self._detail_overview_spoken)

    def _clear_detail_overview_memory(self, reason: str) -> None:
        if self._detail_overview_spoken:
            logger.info(
                f"[PropertyDetailMemory] cleared count={len(self._detail_overview_spoken)} "
                f"reason={reason}"
            )
        self._detail_overview_spoken.clear()

    def _has_unspoken_shortlist_properties(self, exclude_id: str = "") -> bool:
        exclude_id = (exclude_id or "").strip()
        for prop in self._presented_properties_for_resolution():
            prop_id = _property_ref_id(prop)
            if not prop_id or prop_id == exclude_id:
                continue
            if prop_id not in self._detail_overview_spoken:
                return True
        return False

    def _detail_followup_cta(self, property_ref: dict | str | None) -> str:
        property_id = _property_ref_id(property_ref)
        cta = (
            "Would you like me to arrange a JLL Homes property specialist callback "
            "or schedule a site visit for this property?"
        )
        return cta

    def build_already_shared_property_detail_reply(self, property_ref: dict | str | None = None) -> str | None:
        data = self._get_cached_property(property_ref) if property_ref else self._current_property_context_ref()
        if not data and isinstance(property_ref, dict):
            data = property_ref
        if not data:
            return None
        property_id = _property_ref_id(data)
        name = (
            data.get("name")
            or data.get("project_name")
            or self._active_property_name
            or "this property"
        )
        if self._has_unspoken_shortlist_properties(property_id):
            return (
                f"I've already shared the key details for {name}. "
                "I can arrange a JLL Homes property specialist callback, schedule a site visit, "
                "or tell you about another property from the list."
            )
        return (
            f"I've already shared the key details for {name}. "
            "I can arrange a JLL Homes property specialist callback or schedule a site visit for this property."
        )

    def _clear_active_property(self) -> None:
        self._active_property_id = None
        self._active_property_name = None
        self._explicit_property_focus_id = None
        self._pending_variant_selection = None
        self._forced_property_detail_id_once = None
        self.clear_locked_property_target("active_property_cleared")

    def _set_active_property(self, property_ref: dict | None) -> None:
        if not property_ref:
            self._clear_active_property()
            return
        property_id = str(
            property_ref.get("property_id")
            or property_ref.get("project_slug")
            or ""
        ).strip()
        if not property_id:
            self._clear_active_property()
            return
        cached = (
            self._property_details_map.get(property_id)
            or self._slug_cache.get(property_id)
            or property_ref
        )
        previous_id = str(self._active_property_id or "").strip()
        if previous_id and previous_id != property_id:
            logger.info(
                f"[PropertyFocus] active property changed old_id={previous_id} new_id={property_id}"
            )
        locked_id = str((self._locked_property_target or {}).get("property_id") or "").strip()
        if locked_id and locked_id != property_id:
            self.clear_locked_property_target("active_property_focus_changed")
        self._active_property_id = property_id
        self._active_property_name = (
            cached.get("name")
            or cached.get("project_name")
            or property_ref.get("name")
            or property_id
        )
        self._shortlist_clarification_attempts = 0

    def _mark_property_focus(self, property_ref: dict | None) -> None:
        self._set_active_property(property_ref)
        self.clear_pending_property_callback_offer()
        if self._selection_pending:
            self._selection_pending = False

    def _mark_explicit_property_focus(self, property_ref: dict | None) -> None:
        self._mark_property_focus(property_ref)
        if not property_ref:
            self._explicit_property_focus_id = None
            return
        property_id = str(
            property_ref.get("property_id")
            or property_ref.get("project_slug")
            or ""
        ).strip()
        self._explicit_property_focus_id = property_id or None
        if property_id:
            self.lock_property_target(property_ref, source="explicit_focus")

    def _arm_forced_property_detail(self, property_id: str | None) -> None:
        property_id = str(property_id or "").strip()
        if property_id:
            self._forced_property_detail_id_once = property_id
            _cached = self._get_cached_property(property_id) or {"property_id": property_id, "project_slug": property_id}
            self.lock_property_target(_cached, source="forced_property_detail")

    def _consume_forced_property_detail(self) -> str | None:
        property_id = str(self._forced_property_detail_id_once or "").strip()
        self._forced_property_detail_id_once = None
        return property_id or None

    def _peek_forced_property_detail(self) -> str | None:
        property_id = str(self._forced_property_detail_id_once or "").strip()
        return property_id or None

    def _get_cached_property(self, property_ref_or_id) -> dict | None:
        if isinstance(property_ref_or_id, dict):
            property_id = str(
                property_ref_or_id.get("property_id")
                or property_ref_or_id.get("project_slug")
                or ""
            ).strip()
        else:
            property_id = str(property_ref_or_id or "").strip()
        if not property_id:
            return None
        cached = (
            self._property_details_map.get(property_id)
            or self._slug_cache.get(property_id)
        )
        if cached:
            return cached
        if isinstance(property_ref_or_id, dict):
            return property_ref_or_id
        return None

    def _normalize_property_lookup_key(self, value: str) -> str:
        return re.sub(r"[^a-z0-9]+", " ", str(value or "").strip().lower()).strip()

    def resolve_known_property_id(self, value: str) -> str | None:
        lookup = str(value or "").strip()
        if not lookup:
            return None
        if lookup in self._slug_cache or lookup in self._property_details_map:
            return lookup
        normalized_lookup = self._normalize_property_lookup_key(lookup)
        if not normalized_lookup:
            return None
        candidates: list[dict] = list(self._last_presented_properties or [])
        for property_id, cached in self._slug_cache.items():
            candidates.append(
                {
                    "property_id": property_id,
                    "project_slug": property_id,
                    "name": cached.get("name") or cached.get("project_name") or property_id,
                }
            )
        for candidate in candidates:
            property_id = str(candidate.get("property_id") or candidate.get("project_slug") or "").strip()
            name = str(candidate.get("name") or candidate.get("project_name") or "").strip()
            if not property_id or not name:
                continue
            normalized_name = self._normalize_property_lookup_key(name)
            if normalized_name and (
                normalized_name == normalized_lookup
                or normalized_name in normalized_lookup
                or normalized_lookup in normalized_name
            ):
                return property_id
        return None

    def _extract_property_price(self, data: dict) -> str | None:
        price = data.get("starting_price") or data.get("price")
        if price:
            return str(price)
        prices = []
        for cfg in data.get("configs") or []:
            if not isinstance(cfg, dict):
                continue
            cfg_price = cfg.get("price")
            if cfg_price is not None:
                prices.append(str(cfg_price))
        return prices[0] if prices else None

    def _extract_property_size(self, data: dict) -> str | None:
        for key in ("super_builtup", "carpet_area", "area", "built_up_area"):
            val = data.get(key)
            if val:
                return str(val)
        for cfg in data.get("configs") or []:
            if not isinstance(cfg, dict):
                continue
            for key in ("super_builtup", "carpet_area", "area", "built_up_area"):
                val = cfg.get(key)
                if val:
                    return str(val)
        return None

    def _extract_developer_text(self, data: dict) -> str | None:
        dev = data.get("developer")
        if isinstance(dev, str) and dev.strip():
            return dev.strip()
        if isinstance(dev, dict):
            return str(dev.get("name") or dev.get("developer_name") or "").strip() or None
        if isinstance(dev, list):
            names = []
            for item in dev:
                if isinstance(item, str) and item.strip():
                    names.append(item.strip())
                elif isinstance(item, dict):
                    name = str(item.get("name") or item.get("developer_name") or "").strip()
                    if name:
                        names.append(name)
            names = [n for n in names if n]
            if names:
                return ", ".join(names[:2])
        return None

    def _extract_rera_text(self, data: dict) -> str | None:
        if not isinstance(data, dict):
            return None

        def _value_to_rera_text(value) -> str | None:
            if value is None:
                return None
            if isinstance(value, bool):
                return "RERA approved" if value else None
            if isinstance(value, str):
                text = value.strip()
                if text and text.lower() not in {"none", "null", "na", "n/a", "-"}:
                    return text
                return None
            if isinstance(value, (int, float)):
                return str(value).strip() or None
            if isinstance(value, list):
                values = [_value_to_rera_text(item) for item in value]
                values = [item for item in values if item]
                return ", ".join(values[:2]) if values else None
            if isinstance(value, dict):
                for nested_key in (
                    "RERA_No",
                    "RERA_Number",
                    "RERA_Registration_No",
                    "registrationNo",
                    "registration_number",
                    "number",
                    "value",
                    "status",
                ):
                    text = _value_to_rera_text(value.get(nested_key))
                    if text:
                        return text
                return self._extract_rera_text(value)
            return None

        rera_keys = (
            "rera",
            "RERA",
            "Rera",
            "RERA_No",
            "RERA_Number",
            "RERA_Registration_No",
            "RERA_Registration_Number",
            "RERA_Number_List",
            "Rera_Number",
            "ReraNo",
            "Rera_No",
            "reraNo",
            "rera_number",
            "reraRegistrationNo",
            "reraDetails",
            "rera_details",
            "reraStatus",
            "rera_status",
            "rera_approval_status",
            "reraApprovalStatus",
            "reraApproved",
            "isReraApproved",
            "is_rera_approved",
        )
        for key in rera_keys:
            text = _value_to_rera_text(data.get(key))
            if text:
                return text

        approvals = data.get("approvals")
        if isinstance(approvals, dict):
            text = _value_to_rera_text(approvals.get("rera"))
            if text:
                return text

        rera = data.get("rera")
        if isinstance(rera, list):
            values = [str(v).strip() for v in rera if str(v).strip()]
            if values:
                return ", ".join(values[:2])
        return None

    def _detect_single_property_fact(self, text: str) -> str | None:
        lower = (text or "").strip().lower()
        if not lower:
            return None
        if re.search(r'\b(compare|comparison|better|best|suggest|recommend|opinion|should i|which one|versus|vs\.?)\b', lower):
            return None
        if re.search(r'\b(show|list|repeat|again|other options|cheaper|another area|different area|budget|location change)\b', lower):
            return None

        patterns = {
            "price": re.compile(r'\b(price|cost|pricing|starts?\s+from|how much)\b', re.IGNORECASE),
            "size": re.compile(r'\b(size|area|sq\.?\s*ft|square\s*feet|carpet)\b', re.IGNORECASE),
            "configuration": re.compile(r'\b(configuration|config|bhk|bedroom|bedrooms)\b', re.IGNORECASE),
            "possession": re.compile(_POSSESSION_FACT_PATTERN, re.IGNORECASE),
            "amenities": re.compile(r'\b(amenities|amenity|facilities|features)\b', re.IGNORECASE),
            "developer": re.compile(r'\b(developer|builder|built by|who built)\b', re.IGNORECASE),
            "rera": re.compile(_RERA_FACT_PATTERN, re.IGNORECASE),
            "location": re.compile(r'\b(location|where is it|which area|micro market|micro-market|where is this)\b', re.IGNORECASE),
        }
        matches = [fact for fact, pattern in patterns.items() if pattern.search(lower)]
        if len(matches) != 1:
            return None
        return matches[0]

    def resolve_deterministic_detail_request(self, text: str) -> dict | None:
        fact = self._detect_single_property_fact(text)
        if not fact:
            return None
        text_lower = (text or "").strip().lower()
        matched_ordinals = {
            pos for token, pos in _ORDINAL_POSITION_MAP.items()
            if re.search(rf'\b{re.escape(token)}\b', text_lower)
        }
        if len(matched_ordinals) > 1:
            return None
        matched_names = 0
        presented_properties = list(self._last_presented_properties or [])
        fuzzy_presented_match = _resolve_fuzzy_property_name_from_presented(text, presented_properties)
        if fuzzy_presented_match:
            variants = fuzzy_presented_match.get("variants") or []
            selected_variant = self._resolve_variant_from_text(variants, text)
            if selected_variant:
                return {
                    "position": fuzzy_presented_match.get("position"),
                    "name": fuzzy_presented_match.get("name"),
                    "property_id": selected_variant["property_id"],
                }
            if len(variants) > 1:
                return {
                    "needs_variant_clarification": True,
                    "position": fuzzy_presented_match.get("position"),
                    "name": fuzzy_presented_match.get("name"),
                    "variants": variants,
                }
            logger.info(f"[SelectionResolve] Fuzzy catalog matched name '{fuzzy_presented_match.get('name')}'")
            return fuzzy_presented_match

        for prop in presented_properties:
            prop_name = str(prop.get("name") or "").strip().lower()
            if prop_name and prop_name in text_lower:
                matched_names += 1
            if matched_names > 1:
                return None
        selected = self.resolve_property_selection(text)
        if selected:
            return {"property": selected, "fact": fact}
        if self._active_property_id and not self._selection_pending:
            if re.search(r'\b(first|second|third|fourth|fifth|1st|2nd|3rd|4th|5th|last)\b', text_lower):
                return None
            for _name, _slug in self._name_to_slug.items():
                if _slug != self._active_property_id and _name and _name in text_lower:
                    return None
            active = self._get_cached_property(self._active_property_id)
            if active:
                return {
                    "property": {
                        "property_id": self._active_property_id,
                        "name": self._active_property_name or active.get("name") or active.get("project_name") or self._active_property_id,
                    },
                    "fact": fact,
                }
        locked = self.current_locked_property_target()
        locked_id = str((locked or {}).get("property_id") or (locked or {}).get("project_slug") or "").strip()
        if locked_id and not self._selection_pending:
            if re.search(r'\b(first|second|third|fourth|fifth|1st|2nd|3rd|4th|5th|last)\b', text_lower):
                return None
            for _name, _slug in self._name_to_slug.items():
                if _slug != locked_id and _name and _name in text_lower:
                    return None
            locked_data = self._get_cached_property(locked_id) or locked or {}
            return {
                "property": {
                    "property_id": locked_id,
                    "name": (
                        locked_data.get("name")
                        or locked_data.get("project_name")
                        or locked_data.get("project_slug")
                        or locked_id
                    ),
                },
                "fact": fact,
            }
        return None

    def _extract_property_configuration(self, data: dict) -> str | None:
        if not isinstance(data, dict):
            return None
        configs = data.get("configs") or data.get("configurations") or []
        config_types: list[str] = []
        for cfg in configs:
            if not isinstance(cfg, dict):
                continue
            cfg_type = str(cfg.get("type") or "").strip()
            if cfg_type and cfg_type.lower() not in {c.lower() for c in config_types}:
                config_types.append(cfg_type)
        if config_types:
            normalized = []
            for cfg_type in config_types[:6]:
                bhk_value = self._normalize_bedroom_value(cfg_type)
                normalized.append(f"{bhk_value} BHK" if bhk_value else cfg_type)
            return _join_spoken_list(normalized)
        fallback = (
            data.get("type")
            or data.get("bhk")
            or data.get("bedrooms")
            or data.get("configuration")
        )
        if fallback is None:
            return None
        fallback_text = str(fallback).strip()
        if not fallback_text:
            return None
        normalized_fallback = _normalize_bhk_option_list_text(fallback_text)
        bhk_value = self._normalize_bedroom_value(normalized_fallback)
        if bhk_value and re.fullmatch(r"\d+(?:\.\d+)?\s*(?:B\s*H\s*K|BHK)?", normalized_fallback, re.IGNORECASE):
            return f"{bhk_value} BHK"
        return normalized_fallback

    def can_answer_detail_from_cache(self, property_ref: dict, fact: str) -> bool:
        data = self._get_cached_property(property_ref)
        if not data:
            return False
        if fact == "price":
            return True
        if fact == "size":
            return bool(self._extract_property_size(data))
        if fact == "possession":
            return bool(data.get("possession"))
        if fact == "amenities":
            return bool(data.get("amenities"))
        if fact == "configuration":
            return bool(self._extract_property_configuration(data))
        if fact == "developer":
            return bool(self._extract_developer_text(data))
        if fact == "rera":
            return bool(self._extract_rera_text(data))
        if fact == "location":
            return bool(data.get("location") or data.get("micro_market"))
        return False

    def build_deterministic_detail_response(self, property_ref: dict, fact: str) -> str | None:
        data = self._get_cached_property(property_ref)
        if not data:
            return None
        name = (
            data.get("name")
            or data.get("project_name")
            or property_ref.get("name")
            or "this property"
        )
        specialist_offer = (
            f"I don't have that exact detail for {name} right now, "
            f"but {_callback_offer_text(name)}"
        )
        if fact == "price":
            price = self._extract_property_price(data)
            if price:
                return f"For {name}, the current starting price is {price}."
            return f"For {name}, the price is not listed right now. {_callback_offer_text(name)}"
        if fact == "size":
            size = self._extract_property_size(data)
            return (
                f"The size for {name} is {size} square feet."
                if size else specialist_offer
            )
        if fact == "possession":
            possession_message = _format_property_possession_message(data, name)
            return possession_message or specialist_offer
        if fact == "amenities":
            if _is_plot_like_property(data, property_ref):
                return (
                    f"For {name}, I don't have plot-specific amenities listed right now. "
                    f"{_callback_offer_text(name)}"
                )
            amenities = [str(a).strip() for a in (data.get("amenities") or []) if str(a).strip()]
            if amenities:
                return f"For {name}, the amenities include {', '.join(amenities[:5])}."
            return specialist_offer
        if fact == "configuration":
            configuration = self._extract_property_configuration(data)
            return (
                f"For {name}, the configuration options are {configuration}."
                if configuration else specialist_offer
            )
        if fact == "developer":
            developer = self._extract_developer_text(data)
            return (
                f"{name} is by {developer}."
                if developer else specialist_offer
            )
        if fact == "rera":
            rera = self._extract_rera_text(data)
            if rera:
                return f"The RERA details I have for {name} are {rera}."
            return (
                f"I don't have the RERA approval status for {name} in my current data, "
                f"so I can't confirm whether it is RERA approved. {_callback_offer_text(name)}"
            )
        if fact == "location":
            location = data.get("location") or data.get("micro_market")
            return (
                f"{name} is in {location}."
                if location else specialist_offer
            )
        return None

    def build_direct_property_overview_response(self, property_ref: dict) -> str | None:
        data = self._get_cached_property(property_ref)
        if not data:
            return None
        name = (
            data.get("name")
            or data.get("project_name")
            or property_ref.get("name")
            or "this property"
        )
        price = self._extract_property_price(data)
        location = data.get("location") or data.get("micro_market")
        amenities = [str(a).strip() for a in (data.get("amenities") or []) if str(a).strip()]

        parts = [name]
        if location:
            parts.append(f"is in {location}")
        if price:
            parts.append(f"with a starting price of {price}")

        first_sentence = " ".join(parts).strip()
        if not first_sentence.endswith("."):
            first_sentence += "."

        second_bits = []
        if amenities and not _is_plot_like_property(data, property_ref):
            second_bits.append(f"It offers amenities like {', '.join(amenities[:3])}")
        possession_message = _format_property_possession_message(data)
        if possession_message:
            second_bits.append(possession_message)

        response_parts = [first_sentence]
        if second_bits:
            second_sentence = ". ".join(second_bits).strip()
            if not second_sentence.endswith("."):
                second_sentence += "."
            response_parts.append(second_sentence)
        response_parts.append(self._detail_followup_cta(data))
        response = " ".join(response_parts)
        self._mark_detail_overview_spoken(data, source="direct_property_overview")
        return response

    async def _prefetch_property_detail(
        self,
        endpoint: dict,
        property_id: str,
        generation: int,
    ) -> None:
        try:
            if generation != self._detail_prefetch_generation:
                return
            result = await self._execute_endpoint(
                endpoint,
                {"property_id": property_id, "project_slug": property_id},
            )
            if generation != self._detail_prefetch_generation:
                return
            if not result.get("success") or "data" not in result:
                logger.debug(f"[DetailPrefetch] Skipped property_id={property_id} success={result.get('success')}")
                return
            _detail = result.get("data") or {}
            if not isinstance(_detail, dict):
                return
            _merged = {
                **(self._slug_cache.get(property_id) or {}),
                **(self._property_details_map.get(property_id) or {}),
                **_detail,
            }
            if not _merged.get("property_id"):
                _merged["property_id"] = property_id
            self._property_details_map[property_id] = _merged
            self._slug_cache[property_id] = {
                **(self._slug_cache.get(property_id) or {}),
                **_merged,
            }
            logger.info(f"[DetailPrefetch] Warmed property_id={property_id}")
        except asyncio.CancelledError:
            logger.debug(f"[DetailPrefetch] Cancelled property_id={property_id}")
            raise
        except Exception as _ex:
            logger.debug(f"[DetailPrefetch] Failed property_id={property_id}: {_ex}")
        finally:
            _task = self._detail_prefetch_tasks.get(property_id)
            if _task and (_task.done() or _task is asyncio.current_task()):
                self._detail_prefetch_tasks.pop(property_id, None)

    async def try_build_direct_property_detail_response(
        self,
        property_ref: dict,
        *,
        wait_for_prefetch_ms: int = 0,
    ) -> str | None:
        detail_data = await self._resolve_direct_property_detail_data(
            property_ref,
            wait_for_prefetch_ms=wait_for_prefetch_ms,
        )
        if not detail_data:
            return None
        logger.info(
            f"[PropertyFirst] deterministic_followup_path=confirmed_property_detail_overview "
            f"property_id={detail_data.get('property_id')}"
        )
        return self.build_direct_property_overview_response(detail_data)

    async def _resolve_direct_property_detail_data(
        self,
        property_ref: dict,
        *,
        wait_for_prefetch_ms: int = 0,
        required_fact: str | None = None,
    ) -> dict | None:
        property_id = str(
            property_ref.get("property_id")
            or property_ref.get("project_slug")
            or ""
        ).strip()
        if not property_id:
            return None

        _prefetch_task = self._detail_prefetch_tasks.get(property_id)
        if (
            wait_for_prefetch_ms > 0
            and _prefetch_task
            and not _prefetch_task.done()
        ):
            try:
                await asyncio.wait_for(
                    asyncio.shield(_prefetch_task),
                    timeout=max(wait_for_prefetch_ms, 1) / 1000,
                )
                logger.info(
                    f"[PropertyFirst] detail_prefetch_wait_complete property_id={property_id}"
                )
            except asyncio.TimeoutError:
                logger.info(
                    f"[PropertyFirst] detail_prefetch_wait_timeout property_id={property_id} "
                    f"wait_ms={wait_for_prefetch_ms}"
                )
            except Exception as exc:
                logger.debug(
                    f"[PropertyFirst] detail_prefetch_wait_failed property_id={property_id}: {exc}"
                )

        if self._has_prefetched_detail(property_id):
            _cached = self._get_cached_property(property_id) or property_ref
            if self._cached_detail_can_answer_fact(_cached, required_fact):
                self._mark_property_focus(_cached)
                self._update_lead_score("get_property_details", {"success": True, "data": _cached})
                logger.info(
                    f"[PropertyFirst] deterministic_followup_path=confirmed_property_detail_cache "
                    f"property_id={property_id}"
                )
                return _cached
            logger.info(
                f"[PropertyFirst] cached_detail_missing_fact fact={required_fact} "
                f"property_id={property_id} -> fetching_full_detail"
            )

        endpoint = self._find_endpoint("get_property_details")
        if not endpoint:
            return None

        result = await self._execute_endpoint(
            endpoint,
            {"property_id": property_id, "project_slug": property_id},
        )
        if not result.get("success") or not isinstance(result.get("data"), dict):
            logger.warning(
                f"[PropertyFirst] direct detail fetch failed property_id={property_id} "
                f"success={result.get('success')}"
            )
            return None

        _detail = result.get("data") or {}
        _merged = {
            **(self._slug_cache.get(property_id) or {}),
            **(self._property_details_map.get(property_id) or {}),
            **_detail,
        }
        if not _merged.get("property_id"):
            _merged["property_id"] = property_id
        self._property_details_map[property_id] = _merged
        self._slug_cache[property_id] = {
            **(self._slug_cache.get(property_id) or {}),
            **_merged,
        }
        self._mark_property_focus(_merged)
        self._update_lead_score("get_property_details", {"success": True, "data": _merged})
        logger.info(
            f"[PropertyFirst] deterministic_followup_path=confirmed_property_detail_direct "
            f"property_id={property_id}"
        )
        return _merged

    async def try_build_direct_property_fact_response(
        self,
        property_ref: dict,
        fact: str,
        *,
        wait_for_prefetch_ms: int = 0,
    ) -> str | None:
        detail_data = await self._resolve_direct_property_detail_data(
            property_ref,
            wait_for_prefetch_ms=wait_for_prefetch_ms,
            required_fact=fact,
        )
        if not detail_data:
            return None
        response = self.build_deterministic_detail_response(detail_data, fact)
        if response:
            logger.info(
                f"[PropertyFirst] deterministic_followup_path=confirmed_property_detail_fact "
                f"property_id={detail_data.get('property_id')} fact={fact}"
            )
        return response

    def _prefetch_top_property_details(self, items: list[dict]) -> None:
        endpoint = self._find_endpoint("get_property_details")
        if not endpoint:
            logger.debug("[DetailPrefetch] get_property_details endpoint not found")
            return
        generation = self._detail_prefetch_generation
        scheduled = 0
        for item in items[: self._detail_prefetch_limit]:
            property_id = str(item.get("property_id") or item.get("project_slug") or "").strip()
            if not property_id:
                continue
            if self._has_prefetched_detail(property_id):
                continue
            existing_task = self._detail_prefetch_tasks.get(property_id)
            if existing_task and not existing_task.done():
                continue
            task = asyncio.create_task(
                self._prefetch_property_detail(endpoint, property_id, generation)
            )
            self._detail_prefetch_tasks[property_id] = task
            scheduled += 1
        if scheduled:
            logger.info(f"[DetailPrefetch] Scheduled {scheduled} top-property detail fetch(es)")

    def _extract_property_variants(self, items: list[dict]) -> list[dict]:
        grouped: list[dict] = []
        by_name: dict[str, dict] = {}
        for item in items or []:
            property_id = str(item.get("property_id") or item.get("project_slug") or item.get("slug") or "").strip()
            name = (
                item.get("project_name")
                or item.get("name")
                or item.get("projectName")
                or item.get("Project_Name_Original")
                or item.get("Project_Name")
                or item.get("Project_Name_New")
                or ""
            ).strip()
            if not property_id or not name or name == "?" or len(name) <= 1:
                continue
            cfgs = item.get("configs") or item.get("configurations") or []
            bhk = None
            for cfg in cfgs:
                if isinstance(cfg, dict) and cfg.get("type"):
                    bhk = str(cfg.get("type")).strip()
                    break
            price_num = None
            for cfg in cfgs:
                if not isinstance(cfg, dict):
                    continue
                p = cfg.get("price") or cfg.get("FinalPrice") or cfg.get("All_Price")
                if p:
                    try:
                        price_num = min(price_num if price_num is not None else float("inf"), float(p))
                    except (ValueError, TypeError):
                        pass
            price = item.get("starting_price") or (
                str(int(price_num)) if price_num and price_num != float("inf") else None
            )
            key = re.sub(r"\s+", " ", name.lower())
            variant = {
                "property_id": property_id,
                "name": name,
                "bhk": bhk,
                "price": price,
                "price_num": price_num if price_num is not None else float("inf"),
            }
            existing = by_name.get(key)
            if existing:
                existing["variants"].append(variant)
            else:
                entry = {"name": name, "variants": [variant]}
                by_name[key] = entry
                grouped.append(entry)
        return grouped

    def allow_property_direct_speech_once(self) -> None:
        self._allow_property_direct_speech_once = True

    def consume_property_direct_speech_allowance(self) -> bool:
        if not self._allow_property_direct_speech_once:
            return False
        self._allow_property_direct_speech_once = False
        return True

    def _normalize_bedroom_value(self, value) -> str:
        text = str(value or "").strip().lower()
        if not text:
            return ""
        match = re.search(r'(\d+(?:\.\d+)?)\s*bhk\b', text, re.IGNORECASE)
        if not match:
            match = re.search(r'\b(\d+(?:\.\d+)?)\b', text)
        if match:
            raw = match.group(1)
            try:
                num = float(raw)
                return str(int(num)) if num.is_integer() else raw
            except Exception:
                return raw
        for digit, word in _DIGIT_TO_WORD.items():
            if re.search(rf'\b{re.escape(word)}\b', text, re.IGNORECASE):
                return digit
        return ""

    def _extract_requested_bedroom_from_text(self, text: str) -> str:
        lower = str(text or "").strip().lower()
        if not lower:
            return ""
        match = re.search(
            r"\b(\d+(?:\.\d+)?)\s*(?:b\s*h\s*k|bhk|bed(?:room)?s?)\b",
            lower,
            re.IGNORECASE,
        )
        if match:
            return self._normalize_bedroom_value(match.group(1))
        for digit, word in _DIGIT_TO_WORD.items():
            if re.search(
                rf"\b{re.escape(word)}\s*(?:b\s*h\s*k|bhk|bed(?:room)?s?)\b",
                lower,
                re.IGNORECASE,
            ):
                return digit
        return ""

    def _extract_numeric_roles(self, text: str) -> list[dict]:
        lower = (text or "").strip().lower()
        roles: list[dict] = []
        if not lower:
            return roles
        for match in re.finditer(r'\b(\d+)(?:st|nd|rd|th)?\b', lower):
            token = match.group(1)
            start = match.start()
            end = match.end()
            window = lower[max(0, start - 18): min(len(lower), end + 24)]
            role = "unknown"
            if re.search(rf'\b{re.escape(token)}\s*bhk\b', window):
                role = "bhk_count"
            elif re.search(rf'(?:rs|â‚¹|price|priced at|lakh|lack|crore|budget|cost)[^\n]{{0,18}}\b{re.escape(token)}\b', window):
                role = "price"
            elif re.search(rf'\b{re.escape(token)}\s*(?:sq\.?\s*ft|square\s*feet|sqft)\b', window):
                role = "sqft"
            elif re.search(rf'\b(?:option|property|project|number|the)\s+{re.escape(token)}(?:st|nd|rd|th)?\b', window):
                role = "ordinal"
            roles.append({"value": int(token), "role": role, "window": window})
        return roles

    def _format_bedroom_label(self, value) -> str:
        normalized = self._normalize_bedroom_value(value)
        return f"{normalized} BHK" if normalized else str(value or "").strip()

    def _format_compact_inr_price(self, value) -> str | None:
        try:
            amount = int(float(value))
        except Exception:
            return None
        if amount <= 0:
            return None
        return _num_to_indian_words(amount).title()

    def _filter_item_to_requested_bedroom(self, item: dict, requested_bedrooms: str) -> dict | None:
        requested = self._normalize_bedroom_value(requested_bedrooms)
        if not requested or not isinstance(item, dict):
            return item

        cfgs = item.get("configs") or item.get("configurations") or []
        matched_cfgs = [
            dict(cfg)
            for cfg in cfgs
            if isinstance(cfg, dict) and self._normalize_bedroom_value(cfg.get("type")) == requested
        ]

        summary_candidates = [
            item.get("config_summary"),
            item.get("type"),
        ]
        summary_match = any(self._normalize_bedroom_value(candidate) == requested for candidate in summary_candidates)

        if not matched_cfgs and not summary_match:
            return None

        normalized = dict(item)
        if matched_cfgs:
            normalized["configs"] = matched_cfgs
            if "configurations" in normalized:
                normalized["configurations"] = matched_cfgs
            primary_cfg = matched_cfgs[0]
            primary_type = str(primary_cfg.get("type") or "").strip()
            if primary_type:
                normalized["config_summary"] = primary_type
                normalized["type"] = primary_type
            matched_prices = []
            for cfg in matched_cfgs:
                price_value = cfg.get("price") or cfg.get("FinalPrice") or cfg.get("All_Price")
                try:
                    if price_value is not None:
                        matched_prices.append(float(price_value))
                except Exception:
                    continue
            if matched_prices:
                normalized_price = self._format_compact_inr_price(min(matched_prices))
                if normalized_price:
                    normalized["starting_price"] = normalized_price
        return normalized

    def _filter_search_results_for_requested_bedrooms(
        self,
        visible_items: list[dict],
        buffered_items: list[dict],
        requested_bedrooms: str,
        *,
        desired_count: int,
    ) -> tuple[list[dict], list[dict], int]:
        requested = self._normalize_bedroom_value(requested_bedrooms)
        if not requested:
            return list(visible_items or []), list(buffered_items or []), 0

        filtered_all: list[dict] = []
        dropped = 0
        for item in list(visible_items or []) + list(buffered_items or []):
            normalized = self._filter_item_to_requested_bedroom(item, requested)
            if normalized is None:
                dropped += 1
                continue
            filtered_all.append(normalized)
        return filtered_all[:desired_count], filtered_all[desired_count:], dropped

    async def _validate_alternative_areas(
        self,
        areas: list[dict],
        *,
        city: str,
        property_type: str,
        min_price,
        max_price,
        bedrooms,
        result_count: int = 1,
    ) -> list[dict]:
        if not areas:
            return []
        search_endpoint = self._find_endpoint("search_properties")
        if not search_endpoint:
            return list(areas)

        async def _check_area(area: dict) -> tuple[dict, bool]:
            area_name = str(
                area.get("name")
                or area.get("location")
                or area.get("locality")
                or ""
            ).strip()
            if not area_name:
                return area, False
            try:
                search_result = await self._execute_endpoint(
                    search_endpoint,
                    {
                        "city": city,
                        "property_type": property_type,
                        "location": area_name,
                        "min_price": min_price,
                        "max_price": max_price,
                        "bedrooms": bedrooms,
                        "result_count": str(result_count),
                        "page": "1",
                        "exclude_slugs": "[]",
                    },
                )
                items = search_result.get("data") or []
                if not items:
                    return area, False
                if bedrooms:
                    items, _, _ = self._filter_search_results_for_requested_bedrooms(
                        items,
                        search_result.get("buffered_page_items") or [],
                        bedrooms,
                        desired_count=result_count,
                    )
                items = [
                    item for item in items
                    if _strict_location_match(area_name, item)
                ]
                return area, bool(items)
            except Exception as exc:
                logger.warning(
                    f"[AreasByBudget] Validation failed for area '{area_name}': {exc}"
                )
                return area, False

        checked = await asyncio.gather(*[_check_area(area) for area in areas[:5]], return_exceptions=False)
        validated = [area for area, ok in checked if ok]
        if validated:
            return validated
        return list(areas)

    def clear_pending_variant_selection(self) -> None:
        if self._pending_variant_selection:
            logger.info(
                f"[VariantSelect] Cleared pending variant context reason="
                f"{self._pending_variant_selection.get('clear_reason') or 'resolved'}"
            )
        self._pending_variant_selection = None

    def set_pending_variant_selection(
        self,
        grouped_property: dict,
        *,
        attempts: int = 0,
        reason: str = "activate",
    ) -> None:
        variants = list(grouped_property.get("variants") or [])
        ordered_variants = sorted(
            variants,
            key=lambda v: (
                v.get("price_num", float("inf")),
                str(v.get("bhk") or ""),
                str(v.get("property_id") or ""),
            ),
        )
        numbered_variants = []
        for idx, variant in enumerate(ordered_variants, start=1):
            enriched = dict(variant)
            enriched["_variant_option_number"] = idx
            numbered_variants.append(enriched)
        self._pending_variant_selection = {
            "name": grouped_property.get("name") or "this property",
            "position": grouped_property.get("position"),
            "variants": numbered_variants,
            "attempts": int(attempts or 0),
            "source_label": grouped_property.get("name") or self._shortlist_scope_label(),
            "clear_reason": reason,
        }
        logger.info(
            f"[VariantSelect] Activated context name={self._pending_variant_selection['name']!r} "
            f"variants={len(numbered_variants)} attempts={attempts} reason={reason}"
        )

    def _format_variant_option_label(self, variant: dict, option_number: int | None = None) -> str:
        option_number = option_number or int(variant.get("_variant_option_number") or 0) or None
        bhk = str(variant.get("bhk") or "configuration").strip()
        price = str(variant.get("price") or "price on request").strip()
        prefix = f"Option {option_number} is " if option_number else ""
        return f"{prefix}{bhk} at {price}".strip()

    def build_variant_clarification_text(self, grouped_property: dict) -> str:
        name = grouped_property.get("name") or "this property"
        variants = grouped_property.get("variants") or []
        attempts = int(grouped_property.get("attempts") or 0)
        visible_variants = list(variants[:3])
        if not visible_variants:
            return f"{name} has a few options. Which one would you like details for?"
        bhk_mentions = []
        price_mentions = []
        for variant in visible_variants:
            bhk = str(variant.get("bhk") or "").strip()
            price = str(variant.get("price") or "").strip()
            if bhk:
                bhk_mentions.append(bhk)
            if price:
                price_mentions.append(price)
        unique_bhk = sorted(set(bhk_mentions))
        unique_price = sorted(set(price_mentions))
        if attempts > 0 and len(unique_bhk) == 1 and len(unique_price) >= 2:
            joined_prices = ", ".join(unique_price[:-1]) + (f", and {unique_price[-1]}" if len(unique_price) > 1 else "")
            return f"I found {len(unique_price)} {unique_bhk[0]} options for {name}: {joined_prices}. Which one do you mean?"
        compact_bits = []
        for variant in visible_variants:
            bhk = str(variant.get("bhk") or "configuration").strip()
            price = str(variant.get("price") or "price on request").strip()
            compact_bits.append(f"a {bhk} at {price}")
        if len(compact_bits) == 1:
            joined = compact_bits[0]
        elif len(compact_bits) == 2:
            joined = f"{compact_bits[0]} and {compact_bits[1]}"
        else:
            joined = ", ".join(compact_bits[:-1]) + f", and {compact_bits[-1]}"
        if attempts <= 0:
            return f"{name} has {len(compact_bits)} matching options in {self._shortlist_scope_label()}: {joined}. Which one do you want?"
        if attempts == 1:
            return f"I still have {name}. {joined}. You can say the option number, the BHK, or the price."
        return f"Let me repeat the {name} options: {joined}. Please say the option number, the BHK, or the price."

    def _extract_known_property_name_from_text(self, text: str) -> str | None:
        spoken = re.sub(r"\s+", " ", (text or "").strip())
        if not spoken:
            return None
        def _shortlist_match_norm(value: str) -> str:
            value = re.sub(r"\boprah\b|\bopra\b|\bopera\s+one\b", "opera", (value or "").lower())
            value = re.sub(r"\bkam\s+dh\s+enu\b|\bkam\s+dhenu\b", "kamdhenu", value)
            value = re.sub(r"\b(?:auram|oram|orum)\b", "aurum", value)
            value = re.sub(r"\bpacific\b", "pacifica", value)
            value = re.sub(
                r"\b(?:tell|me|about|the|one|property|project|details?|please|for|of)\b",
                " ",
                value,
            )
            value = re.sub(r"[^a-z0-9]+", " ", value)
            return re.sub(r"\s+", " ", value).strip()

        lower = _shortlist_match_norm(spoken)
        candidates = []
        for name in self._name_to_slug.keys():
            clean_name = _shortlist_match_norm(str(name or "").strip())
            if len(clean_name) >= 4:
                candidates.append(clean_name)
        for prop in self._last_presented_properties or []:
            clean_name = _shortlist_match_norm(str(prop.get("name") or "").strip())
            if len(clean_name) >= 4:
                candidates.append(clean_name)
        candidates = sorted(set(candidates), key=len, reverse=True)
        for candidate in candidates:
            if candidate in lower:
                return candidate
        generic_tokens = {
            "property", "project", "apartment", "apartments", "flat", "flats",
            "villa", "villas", "plot", "plots", "home", "homes", "bhk",
            "option", "options", "priced", "price",
        }
        token_to_names: dict[str, set[str]] = {}
        alias_sources: list[str] = list(candidates)
        if self._active_property_name:
            alias_sources.append(_shortlist_match_norm(str(self._active_property_name).strip()))
        for alias_name in alias_sources:
            for token in re.findall(r"[a-z0-9]+", alias_name):
                if len(token) < 4 or token in generic_tokens:
                    continue
                token_to_names.setdefault(token, set()).add(alias_name)
        for token, names in token_to_names.items():
            if token in lower and len(names) == 1:
                return next(iter(names))
        if self._last_presented_properties:
            text_tokens = set(re.findall(r"[a-z0-9]+", lower))
            best_prop = None
            best_score = 0.0
            for prop in self._last_presented_properties:
                name = _shortlist_match_norm(str(prop.get("name") or prop.get("project_name") or "").strip())
                if not name:
                    continue
                name_tokens = [
                    token for token in re.findall(r"[a-z0-9]+", name)
                    if len(token) >= 4 and token not in generic_tokens
                ]
                if not name_tokens:
                    continue
                overlap = sum(1 for token in name_tokens if token in text_tokens)
                fuzzy_overlap = 0
                for token in name_tokens:
                    if token in text_tokens:
                        continue
                    if difflib.get_close_matches(token, list(text_tokens), n=1, cutoff=0.78):
                        fuzzy_overlap += 1
                score = (overlap + 0.75 * fuzzy_overlap) / max(1, len(name_tokens))
                if score > best_score:
                    best_score = score
                    best_prop = name
            if best_prop and best_score >= 0.45:
                return best_prop
        return None

    def _resolve_variant_from_text(self, variants: list[dict], text: str) -> dict | None:
        lower = (text or "").strip().lower()
        if not lower:
            return None
        cleaned = re.sub(r"\s+", " ", lower)
        ordinal_matches = []
        ordinal_map = {
            "first": 1, "1st": 1, "one": 1, "1": 1,
            "second": 2, "2nd": 2, "two": 2, "2": 2,
            "third": 3, "3rd": 3, "three": 3, "3": 3,
            "last": len(variants or []),
        }
        ordinal_patterns = (
            r"\b(?:option|one|variant|the)\s+(first|second|third|last|1st|2nd|3rd|one|two|three|1|2|3)\b",
            r"\b(first|second|third|last|1st|2nd|3rd)\s+(?:option|one|variant)\b",
            r"\boption\s*(1|2|3)\b",
            r"\bthe\s+(first|second|third|last)\s+one\b",
            r"\b(?:i\s+(?:said|shared|want|meant)\s+)?the\s+(first|second|third|last)\s+option\b",
        )
        for pattern in ordinal_patterns:
            for match in re.finditer(pattern, cleaned, re.IGNORECASE):
                token = next((group for group in match.groups() if group), "")
                token = str(token).strip().lower()
                if token.startswith("the "):
                    token = token[4:]
                pos = ordinal_map.get(token)
                if pos:
                    ordinal_matches.append(pos)
        if len(set(ordinal_matches)) == 1:
            position = ordinal_matches[0]
            if 1 <= position <= len(variants or []):
                selected = list(variants or [])[position - 1]
                logger.info(f"[VariantSelect] Resolved ordinal variant selection -> option={position}")
                return selected
        by_bhk = []
        by_price = []
        mentioned_amounts = {int(amount) for amount in (_parse_inr_amounts(text or "") or [])}
        for variant in variants or []:
            bhk = str(variant.get("bhk") or "").strip().lower()
            price = str(variant.get("price") or "").strip().lower()
            price_num = variant.get("price_num")
            bhk_match = re.search(r'(\d+(?:\.\d+)?)\s*bhk', bhk, re.IGNORECASE)
            bhk_value = bhk_match.group(1) if bhk_match else ""
            bhk_word = _DIGIT_TO_WORD.get(bhk_value, "")
            if bhk and (
                bhk in lower
                or (bhk_value and re.search(rf'\b{re.escape(bhk_value)}\s*bhk\b', lower))
                or (bhk_word and re.search(rf'\b{re.escape(bhk_word)}\s*bhk\b', lower))
            ):
                by_bhk.append(variant)
            price_match = False
            if price and price in lower:
                price_match = True
            else:
                parsed_variant_amounts = _parse_inr_amounts(price or "")
                variant_amount = None
                if parsed_variant_amounts:
                    variant_amount = int(parsed_variant_amounts[0])
                else:
                    try:
                        if price_num not in (None, float("inf")):
                            variant_amount = int(float(price_num))
                    except Exception:
                        variant_amount = None
                if variant_amount is not None and variant_amount in mentioned_amounts:
                    price_match = True
            if price_match:
                by_price.append(variant)
        if len(by_price) == 1:
            logger.info(f"[VariantSelect] Resolved price variant selection -> property_id={by_price[0].get('property_id')}")
            return by_price[0]
        if len(by_bhk) == 1:
            logger.info(f"[VariantSelect] Resolved bhk variant selection -> property_id={by_bhk[0].get('property_id')}")
            return by_bhk[0]
        if len(variants or []) == 1 and self.is_property_first_affirmative(text):
            return variants[0]
        return None

    def is_vague_shortlist_detail_request(self, text: str) -> bool:
        lower = re.sub(r"[^\w\s]", " ", (text or "").strip().lower())
        lower = re.sub(r"\s+", " ", lower).strip()
        if not lower:
            return False
        return bool(
            re.match(
                r"^(?:tell\s+me(?:\s+about)?|tell\s+me\s+more|details(?:\s+please)?|more\s+details|more\s+info|explain)$",
                lower,
                re.IGNORECASE,
            )
        )

    def build_shortlist_choice_prompt(self) -> str:
        names = [
            str(p.get("name") or p.get("project_name") or "").strip()
            for p in (self._last_presented_properties or [])[:3]
            if str(p.get("name") or p.get("project_name") or "").strip()
        ]
        if not names:
            return "Which property should I tell you about?"
        if len(names) == 1:
            return f"Do you want details for {names[0]}?"
        joined = ", ".join(names[:-1]) + f", or {names[-1]}"
        return f"Which property should I tell you about, {joined}?"

    # â”€â”€ Property Selection Resolution Methods â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    def is_ambiguous_response(self, text: str) -> bool:
        """
        Check if user response is ambiguous (e.g., 'yes', 'sure', 'tell me more')
        without specifying a property when selection is pending.
        """
        if not (
            self._selection_pending
            or self.has_active_shortlist_context()
            or self.shortlist_is_partial()
        ) or not self._last_presented_properties:
            return False

        text_lower = text.lower().strip()
        if _looks_like_short_farewell_ack(text_lower) or re.search(r'\b(?:bye|goodbye)\b', text_lower, re.IGNORECASE):
            return False

        # Check if it's a short vague response (<= 5 words and matches ambiguous patterns)
        words = text_lower.split()
        if len(words) <= 5:
            # Direct match against ambiguous patterns
            for pattern in self._AMBIGUOUS_RESPONSES:
                if pattern in text_lower:
                    return True

        return False

    def _presented_properties_for_resolution(self) -> list[dict]:
        presented_properties: list[dict] = []
        seen_keys: set[str] = set()
        for prop in list(self._last_presented_properties or []):
            key = str(prop.get("property_id") or prop.get("project_slug") or prop.get("name") or "")
            if key and key not in seen_keys:
                seen_keys.add(key)
                presented_properties.append(prop)
        _ordinal_source = self._ordinal_results or {}
        if isinstance(_ordinal_source, list):
            _ordinal_iter = enumerate(_ordinal_source, start=1)
        elif isinstance(_ordinal_source, dict):
            _ordinal_iter = _ordinal_source.items()
        else:
            _ordinal_iter = []
        for pos, prop in sorted(_ordinal_iter):
            if not isinstance(prop, dict):
                continue
            key = str(prop.get("property_id") or prop.get("project_slug") or prop.get("name") or "")
            if key and key in seen_keys:
                continue
            prop = dict(prop)
            prop.setdefault("position", pos)
            if key:
                seen_keys.add(key)
            presented_properties.append(prop)
        return presented_properties

    def resolve_property_comparison(self, text: str) -> dict | None:
        positions = _extract_comparison_positions(text)
        pending_fact = str((self._pending_property_comparison or {}).get("fact") or "").strip()
        has_pending_position_reply = bool(pending_fact and len(positions) >= 2)
        if not _looks_like_property_comparison_request(text) and not has_pending_position_reply:
            return None
        detected_fact = _detect_property_comparison_fact(text)
        fact = pending_fact if has_pending_position_reply else detected_fact
        presented = self._presented_properties_for_resolution()
        if not presented:
            return {
                "fact": fact,
                "properties": [],
                "needs_more": True,
            }

        selected: list[dict] = []
        selected_keys: set[str] = set()

        def _add(prop: dict | None) -> None:
            if not prop:
                return
            key = str(prop.get("property_id") or prop.get("project_slug") or prop.get("name") or "")
            if key and key in selected_keys:
                return
            if key:
                selected_keys.add(key)
            selected.append(prop)

        for position in positions:
            for prop in presented:
                if int(prop.get("position") or 0) == position:
                    _add(prop)
                    break

        lower = (text or "").lower()
        for prop in presented:
            name = str(prop.get("name") or prop.get("project_name") or "").strip()
            if name and _canonical_match_key(name) and _canonical_match_key(name) in _canonical_match_key(lower):
                _add(prop)

        clauses = [
            clause.strip()
            for clause in re.split(r"\b(?:and|versus|vs\.?|with|between|to)\b", text or "", flags=re.IGNORECASE)
            if clause.strip()
        ]
        for clause in clauses:
            _add(_resolve_fuzzy_property_name_from_presented(clause, presented))

        if len(selected) > 2:
            logger.info(
                f"[Comparison] more_than_two_references count={len(selected)} using_first_two="
                f"{[p.get('name') for p in selected[:2]]}"
            )
        if len(selected) < 2 and self._last_property_comparison and _looks_like_property_comparison_request(text):
            last_properties = [
                prop for prop in (self._last_property_comparison.get("properties") or [])
                if isinstance(prop, dict)
            ]
            if len(last_properties) >= 2:
                selected = last_properties[:2]
                logger.info(
                    f"[Comparison] reused_last_properties fact={fact} "
                    f"text={text!r}"
                )
        return {
            "fact": fact,
            "properties": selected[:2],
            "needs_more": len(selected) < 2,
        }

    def _comparison_property_data(self, property_ref: dict) -> dict:
        return self._get_cached_property(property_ref) or property_ref

    def _comparison_property_name(self, property_ref: dict) -> str:
        data = self._comparison_property_data(property_ref)
        return str(
            data.get("name")
            or data.get("project_name")
            or property_ref.get("name")
            or "this property"
        ).strip()

    def _comparison_ordinal_label(self, property_ref: dict) -> str:
        labels = {1: "first", 2: "second", 3: "third", 4: "fourth", 5: "fifth"}
        return labels.get(int(property_ref.get("position") or 0), "selected")

    def _comparison_price_info(self, property_ref: dict) -> tuple[str | None, int]:
        data = self._comparison_property_data(property_ref)
        amount = _extract_search_item_min_price(data)
        label = self._extract_property_price(data)
        if not label and amount:
            label = _format_price_indian(amount)
        return label, amount

    def build_property_comparison_response(self, text: str) -> str | None:
        comparison = self.resolve_property_comparison(text)
        if not comparison:
            return None
        if comparison.get("needs_more"):
            self._store_pending_property_comparison(comparison.get("fact") or "price")
            return "Which two properties would you like me to compare? You can say first and third, or say the property names."
        fact = comparison.get("fact") or "price"
        supported = {"price", "location", "possession", "configuration"}
        if fact not in supported:
            return "I can compare the price, location, possession, or configuration for those properties. Which one would you like to compare?"
        first, second = comparison["properties"][:2]
        first_name = self._comparison_property_name(first)
        second_name = self._comparison_property_name(second)
        first_label = self._comparison_ordinal_label(first)
        second_label = self._comparison_ordinal_label(second)

        if fact == "price":
            price1, amount1 = self._comparison_price_info(first)
            price2, amount2 = self._comparison_price_info(second)
            missing = [name for name, price in ((first_name, price1), (second_name, price2)) if not price]
            if missing:
                return (
                    f"I don't have a listed price for {_join_spoken_list(missing)} right now. "
                    "I can compare them once I have the price details, or arrange a JLL Homes property specialist callback."
                )
            response = (
                f"The {first_label} property, {first_name}, starts from {price1}. "
                f"The {second_label} property, {second_name}, starts from {price2}."
            )
            if amount1 and amount2:
                if amount1 == amount2:
                    response += " Both are listed at about the same starting price."
                else:
                    cheaper_name = first_name if amount1 < amount2 else second_name
                    difference = _format_price_indian(abs(amount1 - amount2))
                    response += f" So {cheaper_name} is lower by around {difference}."
            self._store_last_property_comparison(fact, [first, second])
            return response

        def _fact_value(prop: dict, requested_fact: str) -> str:
            data = self._comparison_property_data(prop)
            if requested_fact == "location":
                return str(data.get("location") or data.get("micro_market") or "not listed").strip()
            if requested_fact == "possession":
                return str(data.get("possession") or "not listed").strip()
            if requested_fact == "configuration":
                return self._extract_property_configuration(data) or "not listed"
            return "not listed"

        value1 = _fact_value(first, fact)
        value2 = _fact_value(second, fact)
        self._store_last_property_comparison(fact, [first, second])
        return (
            f"The {first_label} property, {first_name}, has {fact} {value1}. "
            f"The {second_label} property, {second_name}, has {fact} {value2}."
        )

    def resolve_property_selection(self, text: str) -> dict | None:
        """
        Deterministically resolve property selection from user text.
        Returns the selected property dict or None if no clear match.

        Supports:
        - Ordinal: "first", "second", "third", "1st", "2nd", etc.
        - Name matching: fuzzy match against property names
        """
        presented_properties: list[dict] = []
        seen_keys: set[str] = set()
        for prop in list(self._last_presented_properties or []):
            key = str(prop.get("property_id") or prop.get("project_slug") or prop.get("name") or "")
            if key and key not in seen_keys:
                seen_keys.add(key)
                presented_properties.append(prop)
        _ordinal_source = self._ordinal_results or {}
        if isinstance(_ordinal_source, list):
            _ordinal_iter = enumerate(_ordinal_source, start=1)
        elif isinstance(_ordinal_source, dict):
            _ordinal_iter = _ordinal_source.items()
        else:
            _ordinal_iter = []
        for pos, prop in sorted(_ordinal_iter):
            if not isinstance(prop, dict):
                continue
            key = str(prop.get("property_id") or prop.get("project_slug") or prop.get("name") or "")
            if key and key in seen_keys:
                continue
            prop = dict(prop)
            prop.setdefault("position", pos)
            if key:
                seen_keys.add(key)
            presented_properties.append(prop)

        if not presented_properties:
            return None

        def _shortlist_match_norm(value: str) -> str:
            value = re.sub(r"\boprah\b|\bopra\b|\bopera\s+one\b", "opera", (value or "").lower())
            value = re.sub(r"\bkam\s+dh\s+enu\b|\bkam\s+dhenu\b", "kamdhenu", value)
            value = re.sub(r"[^a-z0-9]+", " ", value)
            return re.sub(r"\s+", " ", value).strip()

        text_lower = _shortlist_match_norm(text)
        normalized_text = re.sub(r"[^a-z0-9\s]+", " ", text_lower)
        normalized_text = re.sub(r"\s+", " ", normalized_text).strip()

        # â”€â”€ Ordinal Resolution â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        # Map common ordinal words to positions
        _ORDINAL_MAP = {
            "first": 1, "1st": 1, "one": 1,
            "second": 2, "2nd": 2, "two": 2,
            "third": 3, "3rd": 3, "three": 3,
            "fourth": 4, "4th": 4, "four": 4,
            "fifth": 5, "5th": 5, "five": 5,
            "last": len(presented_properties),
        }

        def _select_position(position: int, reason: str) -> dict | None:
            if not position:
                return None
            for prop in presented_properties:
                if prop["position"] != position:
                    continue
                variants = prop.get("variants") or []
                selected_variant = self._resolve_variant_from_text(variants, text)
                if selected_variant:
                    logger.info(f"[SelectionResolve] Matched {reason}+variant '{text}' -> {selected_variant['property_id']}")
                    return {
                        "position": prop["position"],
                        "name": prop["name"],
                        "property_id": selected_variant["property_id"],
                    }
                if len(variants) > 1:
                    logger.info(f"[SelectionResolve] Matched {reason} grouped property '{prop['name']}' -> variant clarification needed")
                    return {
                        "needs_variant_clarification": True,
                        "position": prop["position"],
                        "name": prop["name"],
                        "variants": variants,
                    }
                logger.info(f"[SelectionResolve] Matched {reason} '{text}' -> position {position} -> {prop['property_id']}")
                return prop
            return None

        def _extract_explicit_ordinal_position(value: str) -> int | None:
            normalized = re.sub(r"[^a-z0-9\s]+", " ", (value or "").lower())
            normalized = re.sub(r"\s+", " ", normalized).strip()
            if not normalized:
                return None
            if re.search(r"\b(?:again|once more|repeat|re list|relist|names|options)\b", normalized):
                return None
            fillers = {
                "ok", "okay", "yeah", "yes", "yep", "sure", "please", "kindly",
                "tell", "me", "about", "the", "property", "project", "option",
                "one", "details", "detail", "for", "of",
            }
            ordinal_tokens = {
                token for token in normalized.split()
                if token in _ORDINAL_MAP or re.fullmatch(r"[1-5](?:st|nd|rd|th)?", token)
            }
            if not ordinal_tokens:
                return None
            content_tokens = [token for token in normalized.split() if token not in fillers and token not in ordinal_tokens]
            if content_tokens:
                return None
            positions: set[int] = set()
            preferred_tokens = {
                token for token in ordinal_tokens
                if token in {"first", "1st", "second", "2nd", "third", "3rd", "fourth", "4th", "fifth", "5th", "last"}
            }
            tokens_to_map = preferred_tokens or ordinal_tokens
            for token in tokens_to_map:
                cleaned = re.sub(r"(st|nd|rd|th)$", "", token)
                if cleaned.isdigit():
                    positions.add(int(cleaned))
                else:
                    mapped = _ORDINAL_MAP.get(token)
                    if mapped:
                        positions.add(mapped)
            return next(iter(positions)) if len(positions) == 1 else None

        explicit_ordinal_position = _extract_explicit_ordinal_position(text)
        if explicit_ordinal_position:
            resolved = _select_position(explicit_ordinal_position, "explicit ordinal")
            if resolved:
                return resolved

        # Check for bare ordinal utterances before broader patterns or relist logic.
        bare_ordinal = re.fullmatch(
            r"(?:the\s+)?(first|second|third|fourth|fifth|1st|2nd|3rd|4th|5th|one|two|three|four|five|last)",
            normalized_text,
            re.IGNORECASE,
        )
        if bare_ordinal:
            matched_text = bare_ordinal.group(1).lower()
            position = _ORDINAL_MAP.get(matched_text)
            if not position:
                cleaned_num = re.sub(r"(st|nd|rd|th)$", "", matched_text)
                if cleaned_num.isdigit():
                    position = int(cleaned_num)
            if position:
                for prop in presented_properties:
                    if prop["position"] == position:
                        variants = prop.get("variants") or []
                        selected_variant = self._resolve_variant_from_text(variants, text)
                        if selected_variant:
                            logger.info(f"[SelectionResolve] Matched bare ordinal '{text}' -> {selected_variant['property_id']}")
                            return {
                                "position": prop["position"],
                                "name": prop["name"],
                                "property_id": selected_variant["property_id"],
                            }
                        if len(variants) > 1:
                            logger.info(f"[SelectionResolve] Bare ordinal matched grouped property '{prop['name']}' -> variant clarification needed")
                            return {
                                "needs_variant_clarification": True,
                                "position": prop["position"],
                                "name": prop["name"],
                                "variants": variants,
                            }
                        logger.info(f"[SelectionResolve] Matched bare ordinal '{text}' -> position {position} -> {prop['property_id']}")
                        return prop

        # Check for explicit ordinal patterns
        _ordinal_patterns = [
            r'\b(first|second|third|fourth|fifth|1st|2nd|3rd|4th|5th)\b',
            r'\b(number\s+(1|2|3|4|5))\b',
            r'\b(the\s+(first|second|third|fourth|fifth|last))\b',
            r'\b(the\s+(one|two|three))\b',
            r'\b(option|property|project)\s+(1|2|3|4|5)\b',
            r'\b((?:1|2|3|4|5)(?:st|nd|rd|th)?|one|two|three|four|five)\s+(?:one|property|project|option)\b',
            r'\bthe\s+((?:1|2|3|4|5)(?:st|nd|rd|th)?|one|two|three|four|five)\s+(?:one|property|project|option)(?:\s+that\s+you\s+(?:mentioned|said|shared|listed))?\b',
        ]

        for pattern in _ordinal_patterns:
            match = re.search(pattern, text_lower)
            if match:
                # Extract the ordinal word and map to position
                matched_text = next(
                    (
                        str(group).lower()
                        for group in match.groups()
                        if group and (
                            str(group).lower() in _ORDINAL_MAP
                            or str(group).isdigit()
                            or re.match(r"^\d+(?:st|nd|rd|th)?$", str(group).lower())
                            or str(group).lower().startswith("number ")
                        )
                    ),
                    match.group(1).lower(),
                )
                matched_text = re.sub(r"\s+(?:one|property|project|option)\b.*$", "", matched_text).strip()
                # Handle "the first" -> extract "first"
                if matched_text.startswith("the "):
                    matched_text = matched_text[4:]
                elif matched_text.startswith("number "):
                    matched_text = matched_text[7:]
                elif " " in matched_text:
                    matched_text = matched_text.split()[-1]
                matched_text = re.sub(r"(st|nd|rd|th)$", "", matched_text)
                position = _ORDINAL_MAP.get(matched_text)
                if not position and matched_text.isdigit():
                    position = int(matched_text)
                if position:
                    # Find property with this position
                    for prop in presented_properties:
                        if prop["position"] == position:
                            variants = prop.get("variants") or []
                            selected_variant = self._resolve_variant_from_text(variants, text)
                            if selected_variant:
                                logger.info(f"[SelectionResolve] Matched ordinal+variant '{match.group(0)}' â†’ {selected_variant['property_id']}")
                                return {
                                    "position": prop["position"],
                                    "name": prop["name"],
                                    "property_id": selected_variant["property_id"],
                                }
                            if len(variants) > 1:
                                logger.info(f"[SelectionResolve] Ordinal matched grouped property '{prop['name']}' â†’ variant clarification needed")
                                return {
                                    "needs_variant_clarification": True,
                                    "position": prop["position"],
                                    "name": prop["name"],
                                    "variants": variants,
                                }
                            logger.info(f"[SelectionResolve] Matched ordinal '{match.group(0)}' â†’ position {position} â†’ {prop['property_id']}")
                            return prop

        # â”€â”€ Name Resolution â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        # Extract potential property names from the text
        # Strategy: look for substring matches against known property names
        for prop in presented_properties:
            prop_name_lower = _shortlist_match_norm(prop["name"])
            # FIX: Skip invalid property names that could cause false matches
            if not prop_name_lower or prop_name_lower in ("?", "unknown", "n/a", "-"):
                continue
            # Direct substring match - but require property name to be at least 3 chars
            # to prevent single chars like "?" from matching general questions
            if len(prop_name_lower) >= 3 and (prop_name_lower in text_lower or text_lower in prop_name_lower):
                variants = prop.get("variants") or []
                selected_variant = self._resolve_variant_from_text(variants, text)
                if selected_variant:
                    logger.info(f"[SelectionResolve] Matched name+variant '{prop['name']}' â†’ {selected_variant['property_id']}")
                    return {
                        "position": prop["position"],
                        "name": prop["name"],
                        "property_id": selected_variant["property_id"],
                    }
                if len(variants) > 1:
                    logger.info(f"[SelectionResolve] Matched grouped name '{prop['name']}' â†’ variant clarification needed")
                    return {
                        "needs_variant_clarification": True,
                        "position": prop["position"],
                        "name": prop["name"],
                        "variants": variants,
                    }
                logger.info(f"[SelectionResolve] Matched name '{prop['name']}' â†’ {prop['property_id']}")
                return prop
            # Word-by-word fuzzy matching for partial matches
            prop_words = set(prop_name_lower.split())
            text_words = set(text_lower.split())
            # If 2+ words from property name appear in text, consider it a match
            if len(prop_words) >= 2 and len(prop_words & text_words) >= 2:
                variants = prop.get("variants") or []
                selected_variant = self._resolve_variant_from_text(variants, text)
                if selected_variant:
                    logger.info(f"[SelectionResolve] Fuzzy matched name+variant '{prop['name']}' â†’ {selected_variant['property_id']}")
                    return {
                        "position": prop["position"],
                        "name": prop["name"],
                        "property_id": selected_variant["property_id"],
                    }
                if len(variants) > 1:
                    logger.info(f"[SelectionResolve] Fuzzy matched grouped name '{prop['name']}' â†’ variant clarification needed")
                    return {
                        "needs_variant_clarification": True,
                        "position": prop["position"],
                        "name": prop["name"],
                        "variants": variants,
                    }
                logger.info(f"[SelectionResolve] Fuzzy matched name '{prop['name']}' â†’ {prop['property_id']}")
                return prop

        _single_token_stopwords = {
            "what", "price", "cost", "pricing", "property", "project", "details",
            "detail", "about", "tell", "please", "one", "the", "this", "that",
            "more", "callback", "site", "visit", "area", "location", "omr",
            "ok", "okay", "yeah", "yes", "yep", "sure", "want", "wanted",
            "know", "for", "of", "in", "on", "with", "and", "apartment",
            "apartments", "flat", "flats", "villa", "villas", "plot", "plots",
        }
        gathered_location = _shortlist_match_norm(str(self._gathered_search.get("location") or ""))
        gathered_city = _shortlist_match_norm(str(self._gathered_search.get("city") or ""))
        for scope_token in (gathered_location, gathered_city):
            if scope_token:
                _single_token_stopwords.update(scope_token.split())

        def _resolve_property_from_partial_tokens(
            tokens: set[str],
            *,
            min_token_len: int,
            reason: str,
        ) -> dict | None:
            if not tokens:
                return None
            token_matches: list[tuple[dict, int, int]] = []
            for prop in presented_properties:
                prop_name_lower = _shortlist_match_norm(prop["name"])
                prop_words = [
                    token for token in prop_name_lower.split()
                    if len(token) >= 3 and token not in _single_token_stopwords
                ]
                if not prop_words:
                    continue
                score = 0
                strongest = 0
                for user_token in tokens:
                    if len(user_token) < min_token_len:
                        continue
                    for prop_word in prop_words:
                        match_strength = 0
                        if user_token == prop_word:
                            match_strength = 4
                        elif len(user_token) >= 3 and prop_word.startswith(user_token):
                            match_strength = 3
                        elif len(user_token) >= 4 and user_token in prop_word:
                            match_strength = 2
                        elif len(user_token) >= 4 and difflib.SequenceMatcher(None, user_token, prop_word).ratio() >= 0.82:
                            match_strength = 1
                        if match_strength:
                            score += match_strength
                            strongest = max(strongest, match_strength)
                if score:
                    token_matches.append((prop, score, strongest))

            if not token_matches:
                return None
            token_matches.sort(key=lambda item: (item[1], item[2]), reverse=True)
            best_score = token_matches[0][1]
            best_matches = [item for item in token_matches if item[1] == best_score]
            unique_ids = {
                str(item[0].get("property_id") or item[0].get("project_slug") or item[0].get("name") or "")
                for item in best_matches
            }
            if len(unique_ids) != 1:
                logger.info(f"[SelectionResolve] Partial shortlist match ambiguous reason={reason} text={text!r}")
                return None

            prop = best_matches[0][0]
            variants = prop.get("variants") or []
            selected_variant = self._resolve_variant_from_text(variants, text)
            if selected_variant:
                logger.info(f"[SelectionResolve] Partial shortlist matched name+variant '{prop['name']}' -> {selected_variant['property_id']}")
                return {
                    "position": prop["position"],
                    "name": prop["name"],
                    "property_id": selected_variant["property_id"],
                }
            if len(variants) > 1:
                logger.info(f"[SelectionResolve] Partial shortlist matched grouped name '{prop['name']}' -> variant clarification needed")
                return {
                    "needs_variant_clarification": True,
                    "position": prop["position"],
                    "name": prop["name"],
                    "variants": variants,
                }
            logger.info(f"[SelectionResolve] Partial shortlist matched name '{prop['name']}' -> {prop['property_id']}")
            return prop

        partial_tokens = {
            token for token in text_lower.split()
            if len(token) >= 3 and token not in _single_token_stopwords
        }
        partial_match = _resolve_property_from_partial_tokens(
            partial_tokens,
            min_token_len=3,
            reason="prefix_or_fuzzy",
        )
        if partial_match:
            return partial_match

        text_tokens = {
            token for token in text_lower.split()
            if len(token) >= 4 and token not in _single_token_stopwords
        }
        if text_tokens:
            token_matches: list[dict] = []
            for prop in presented_properties:
                prop_name_lower = _shortlist_match_norm(prop["name"])
                prop_words = {
                    token for token in prop_name_lower.split()
                    if len(token) >= 4 and token not in _single_token_stopwords
                }
                if prop_words & text_tokens:
                    token_matches.append(prop)
            unique_ids = {
                str(prop.get("property_id") or prop.get("project_slug") or prop.get("name") or "")
                for prop in token_matches
            }
            if len(unique_ids) == 1 and token_matches:
                prop = token_matches[0]
                variants = prop.get("variants") or []
                selected_variant = self._resolve_variant_from_text(variants, text)
                if selected_variant:
                    logger.info(f"[SelectionResolve] Unique token matched name+variant '{prop['name']}' -> {selected_variant['property_id']}")
                    return {
                        "position": prop["position"],
                        "name": prop["name"],
                        "property_id": selected_variant["property_id"],
                    }
                if len(variants) > 1:
                    logger.info(f"[SelectionResolve] Unique token matched grouped name '{prop['name']}' -> variant clarification needed")
                    return {
                        "needs_variant_clarification": True,
                        "position": prop["position"],
                        "name": prop["name"],
                        "variants": variants,
                    }
                logger.info(f"[SelectionResolve] Unique token matched name '{prop['name']}' -> {prop['property_id']}")
                return prop

        known_name = self._extract_known_property_name_from_text(text)
        if known_name:
            known_norm = _shortlist_match_norm(known_name)
            for prop in presented_properties:
                prop_name = _shortlist_match_norm(str(prop.get("name") or ""))
                if prop_name == known_norm:
                    variants = prop.get("variants") or []
                    selected_variant = self._resolve_variant_from_text(variants, text)
                    if selected_variant:
                        return {
                            "position": prop["position"],
                            "name": prop["name"],
                            "property_id": selected_variant["property_id"],
                        }
                    if len(variants) > 1:
                        return {
                            "needs_variant_clarification": True,
                            "position": prop["position"],
                            "name": prop["name"],
                            "variants": variants,
                        }
                    logger.info(f"[SelectionResolve] Fuzzy shortlist alias matched '{prop['name']}'")
                    return prop

        location_matches: list[dict] = []
        for prop in self._last_presented_properties:
            variants = prop.get("variants") or []
            candidate_locations = {
                str(v.get("location") or v.get("micro_market") or "").strip().lower()
                for v in variants
                if str(v.get("location") or v.get("micro_market") or "").strip()
            }
            candidate_locations = {loc for loc in candidate_locations if len(loc) >= 3}
            if not candidate_locations:
                continue
            if any(re.search(rf"\b{re.escape(loc)}\b", text_lower) for loc in candidate_locations):
                location_matches.append(prop)
        if len(location_matches) == 1:
            prop = location_matches[0]
            variants = prop.get("variants") or []
            selected_variant = self._resolve_variant_from_text(variants, text)
            if selected_variant:
                logger.info(f"[SelectionResolve] Matched location+variant '{prop['name']}' â†’ {selected_variant['property_id']}")
                return {
                    "position": prop["position"],
                    "name": prop["name"],
                    "property_id": selected_variant["property_id"],
                }
            if len(variants) > 1:
                logger.info(f"[SelectionResolve] Matched grouped location '{prop['name']}' â†’ variant clarification needed")
                return {
                    "needs_variant_clarification": True,
                    "position": prop["position"],
                    "name": prop["name"],
                    "variants": variants,
                }
            logger.info(f"[SelectionResolve] Matched location '{prop['name']}' â†’ {prop['property_id']}")
            return prop

        return None

    def get_clarification_response(self) -> str:
        """Return the standard clarification question for ambiguous responses."""
        return "Which property would you like to know more about? You can say the name or the number."

    def is_non_substantive_ack(self, text: str) -> bool:
        """Return True for short acknowledgement noises that should not become a real turn."""
        return bool(_NON_SUBSTANTIVE_ACK_RE.match((text or "").strip()))

    def is_relist_request(self, text: str) -> bool:
        lower = (text or "").strip().lower()
        if not lower or not self._last_presented_properties:
            return False
        normalized = re.sub(r"[^a-z0-9\s]+", " ", lower)
        normalized = re.sub(r"\s+", " ", normalized).strip()
        if re.fullmatch(
            r"(?:the\s+)?(?:first|second|third|fourth|fifth|1st|2nd|3rd|4th|5th|one|two|three|four|five|last)",
            normalized,
            re.IGNORECASE,
        ):
            return False
        if self._detect_single_property_fact(lower):
            return False
        selected = self.resolve_property_selection(text)
        if selected and not selected.get("needs_variant_clarification"):
            return False
        if self.is_selected_property_overview_request(text):
            return False
        patterns = (
            r'\b(?:list|show|repeat|say|tell)\b.{0,30}\b(?:again|once more)\b',
            r'\bre[- ]?list\b',
            r'\b(?:properties|property|options|option|apartments|apartment|villas|villa|plots|plot)\b.{0,20}\b(?:again|once more)\b',
            r'\b(?:tell|say|list|show)\b.{0,20}\b(?:property names|names|options|apartments|villas|plots)\b',
            r'\b(?:top|other|available|shown|matching|these|those)\b.{0,20}\b(?:property names|names|options|properties|apartments|villas|plots)\b',
            r'\b(?:what|which)\b.{0,25}\b(?:other|top|available|shown|matching)\b.{0,25}\b(?:property names|names|options|properties)\b',
            r'\bwhat\b.{0,20}\b(?:properties|property names|names|options)\b.{0,20}\b(?:found|have|got)\b',
            r'\b(?:first|last)\s+(?:\d+|one|two|three|four|five)\b.{0,30}\b(?:property|properties|option|options|apartment|apartments|villa|villas|plot|plots)\b',
            r'\b(?:list|show|tell|repeat|say)\b.{0,20}\b(?:first|last)\s+(?:\d+|one|two|three|four|five)\b',
        )
        return any(re.search(p, lower, re.IGNORECASE) for p in patterns)

    def is_selected_property_overview_request(self, text: str) -> bool:
        lower = (text or "").strip().lower()
        if not lower or not self._last_presented_properties:
            return False
        if self._detect_single_property_fact(lower):
            return False
        if re.search(r'\b(again|once more|repeat|re[- ]?list|names?|options?|show more|next)\b', lower):
            return False
        if not re.search(
            r'\b(tell\s+me\s+about|more\s+about|details?\s+about|what\s+about|describe|regarding|know\s+more\s+about)\b',
            lower,
            re.IGNORECASE,
        ):
            return False
        selected = self.resolve_property_selection(text)
        return bool(selected and not selected.get("needs_variant_clarification"))

    def build_relist_response(self, text: str) -> str | None:
        if not self.is_relist_request(text):
            return None

        _presented_refs: list[dict] = []
        for prop in self._last_presented_properties or []:
            _presented_refs.append(prop)
        _ordinal_source = self._ordinal_results or {}
        if isinstance(_ordinal_source, list):
            _ordinal_iter = enumerate(_ordinal_source, start=1)
        elif isinstance(_ordinal_source, dict):
            _ordinal_iter = _ordinal_source.items()
        else:
            _ordinal_iter = []
        for _pos, _prop in _ordinal_iter:
            if isinstance(_prop, dict):
                _entry = dict(_prop)
                _entry.setdefault("position", _pos)
                _presented_refs.append(_entry)
        _position_recap = _shortlist_position_recap(text, _presented_refs)
        if _position_recap:
            return _position_recap

        selected = self._select_properties_for_relist(text)
        if not selected:
            return None

        _lower_text = (text or "").strip().lower()
        if re.search(r'\b(?:property names|names of the properties|names)\b', _lower_text, re.IGNORECASE):
            _names = []
            for item in selected:
                _name = (
                    item.get("project_name")
                    or item.get("name")
                    or item.get("projectName")
                    or item.get("Project_Name_Original")
                    or item.get("Project_Name")
                    or item.get("Project_Name_New")
                    or ""
                ).strip()
                if _name and _name not in _names:
                    _names.append(_name)
            if _names:
                if len(_names) == 1:
                    return f"The property name is {_names[0]}. Would you like to know more about it?"
                if len(_names) == 2:
                    _joined = f"{_names[0]} and {_names[1]}"
                else:
                    _joined = ", ".join(_names[:-1]) + f", and {_names[-1]}"
                return f"The property names are {_joined}. Which one would you like details for?"

        result = {
            "data": selected,
            "total_count": max(len(self._ordinal_results), len(selected)),
            "searched_property_type": self._gathered_search.get("property_type") or "property",
        }
        return _build_search_results_speech(
            result,
            selected_items=selected,
            subset_hint=self._describe_relist_subset(text, len(selected)),
        )

    def build_tool_ack_text(self, function_name: str) -> str | None:
        # search_properties and get_property_details frequently bypass the LLM and
        # speak deterministically after the tool returns. Emitting a separate
        # pre-tool ack here creates a second TTS generation in the same turn,
        # which can close the Cartesia context underneath the real response.
        if function_name in {"search_properties", "get_property_details", "submit_callback", "schedule_site_visit"}:
            return None
        if function_name == "areas_by_budget":
            return "Let me check the best matching areas for you."
        return "Just a moment."

    def _select_properties_for_relist(self, text: str) -> list[dict]:
        text_lower = (text or "").lower()
        presented_ids = [
            p["property_id"]
            for p in self._last_presented_properties
            if p.get("property_id")
        ]
        presented_items = [
            self._property_details_map[pid]
            for pid in presented_ids
            if pid in self._property_details_map
        ]
        if not presented_items:
            return []

        def _parse_count(kind: str) -> int | None:
            match = re.search(
                rf'\b{kind}\s+(\d+|one|two|three|four|five)\b',
                text_lower,
                re.IGNORECASE,
            )
            if not match:
                return None
            raw = match.group(1).lower()
            return int(raw) if raw.isdigit() else _NUMBER_WORDS.get(raw)

        first_count = _parse_count("first")
        if first_count:
            return presented_items[: max(1, min(first_count, len(presented_items)))]

        last_count = _parse_count("last")
        if last_count:
            count = max(1, min(last_count, len(presented_items)))
            return presented_items[-count:]

        explicit_positions = []
        for token, pos in _ORDINAL_POSITION_MAP.items():
            if re.search(rf'\b{re.escape(token)}\b', text_lower):
                explicit_positions.append(pos)
        explicit_positions = sorted(set(explicit_positions))
        if explicit_positions:
            pos_to_item = {
                idx + 1: item
                for idx, item in enumerate(presented_items)
            }
            return [pos_to_item[pos] for pos in explicit_positions if pos in pos_to_item]

        return presented_items

    def _describe_relist_subset(self, text: str, count: int) -> str:
        text_lower = (text or "").lower()
        if re.search(r'\bfirst\s+', text_lower):
            return f"first {count}"
        if re.search(r'\blast\s+', text_lower):
            return f"last {count}"
        explicit_positions = [
            token for token in ("first", "second", "third", "fourth", "fifth")
            if re.search(rf'\b{token}\b', text_lower)
        ]
        if explicit_positions:
            return ", ".join(explicit_positions)
        return "shown"

    def set_pending_value_confirmation(self, field: str, candidate: str, original: str | None = None) -> None:
        self._pending_value_confirmation = {
            "field": field,
            "candidate": candidate,
            "original": original or "",
        }

    def clear_pending_value_confirmation(self) -> None:
        self._pending_value_confirmation = None

    def clear_pending_property_lookup(self) -> None:
        self._pending_property_lookup = None
        self._pending_variant_selection = None

    def set_pending_property_callback_offer(
        self,
        property_name: str,
        location_hint: str | None = None,
    ) -> None:
        if self._detect_single_property_fact(property_name or ""):
            logger.info(f"[PropertyFirst] Suppressed callback offer for fact phrase: {property_name!r}")
            return
        self._pending_property_callback_offer = {
            "property_name": (property_name or "").strip(),
            "location_hint": (location_hint or "").strip(),
        }
        if self._selection_pending:
            self._selection_pending = False

    def clear_pending_property_callback_offer(self) -> None:
        self._pending_property_callback_offer = None

    def _activate_shortlist_context(
        self,
        *,
        label: str = "",
        search_key: str = "",
        stage: str = SHORTLIST_STAGE_COMMITTED,
        spoken_text: str = "",
    ) -> None:
        normalized_stage = stage if stage in {
            SHORTLIST_STAGE_PREPARED,
            SHORTLIST_STAGE_STARTED,
            SHORTLIST_STAGE_PARTIAL,
            SHORTLIST_STAGE_COMMITTED,
        } else SHORTLIST_STAGE_COMMITTED
        self._shortlist_presentation_stage = normalized_stage if self._last_presented_properties else SHORTLIST_STAGE_INACTIVE
        self._shortlist_context_active = bool(
            self._last_presented_properties
            and normalized_stage in {
                SHORTLIST_STAGE_STARTED,
                SHORTLIST_STAGE_PARTIAL,
                SHORTLIST_STAGE_COMMITTED,
            }
        )
        self._shortlist_context_label = (label or "").strip()
        self._shortlist_context_search_key = (search_key or "").strip()
        self._conversation_scope_key = self._build_conversation_scope_key()
        self._shortlist_presentation_text = (spoken_text or "").strip()
        self._shortlist_clarification_attempts = 0
        if self._shortlist_presentation_stage == SHORTLIST_STAGE_PREPARED:
            self._selection_pending = False
            self._shortlist_started_at = None
            self._shortlist_committed_at = None
            self._shortlist_partial_at = None
            self._shortlist_playout_cursor = {
                "intro_played_ms": 0,
                "first_item_played_ms": 0,
                "items_started": 0,
                "last_commit_checkpoint": 0,
            }
            self._shortlist_exposure_bucket = "none"
        elif self._shortlist_presentation_stage == SHORTLIST_STAGE_STARTED:
            self._selection_pending = False
            self._shortlist_started_at = self._shortlist_started_at or time.time()
        elif self._shortlist_presentation_stage == SHORTLIST_STAGE_PARTIAL:
            self._selection_pending = False
            self._shortlist_partial_at = self._shortlist_partial_at or time.time()
        elif self._shortlist_presentation_stage == SHORTLIST_STAGE_COMMITTED:
            self._selection_pending = bool(self._last_presented_properties)
            self._shortlist_committed_at = self._shortlist_committed_at or time.time()
        if self._last_presented_properties:
            logger.info(
                f"[Shortlist] Activated context count={len(self._last_presented_properties)} "
                f"label={self._shortlist_context_label!r} search_key={self._shortlist_context_search_key!r} "
                f"stage={self._shortlist_presentation_stage}"
            )

    def _set_current_shortlist_page_results(self, items: list[dict] | None) -> None:
        self._current_shortlist_page_results = list(items or [])

    def _has_shortlist_page_context(self) -> bool:
        return bool(
            self._last_presented_properties
            and self._shortlist_presentation_stage in {
                SHORTLIST_STAGE_PREPARED,
                SHORTLIST_STAGE_STARTED,
                SHORTLIST_STAGE_PARTIAL,
                SHORTLIST_STAGE_COMMITTED,
            }
        )

    def _prepare_shortlist_presentation(
        self,
        *,
        spoken_text: str,
        label: str = "",
        search_key: str = "",
    ) -> None:
        self._activate_shortlist_context(
            label=label,
            search_key=search_key,
            stage=SHORTLIST_STAGE_PREPARED,
            spoken_text=spoken_text,
        )
        logger.info("[Shortlist] Prepared shortlist presentation")

    def note_shortlist_audio_started(self) -> None:
        if self._shortlist_presentation_stage != SHORTLIST_STAGE_PREPARED or not self._last_presented_properties:
            return
        self._activate_shortlist_context(
            label=self._shortlist_context_label,
            search_key=self._shortlist_context_search_key,
            stage=SHORTLIST_STAGE_STARTED,
            spoken_text=self._shortlist_presentation_text,
        )
        self._shortlist_playout_cursor["items_started"] = max(
            int(self._shortlist_playout_cursor.get("items_started") or 0),
            1 if self._shortlist_presentation_text else 0,
        )
        logger.info("[Shortlist] Audible shortlist playback started")

    def note_shortlist_audio_completed(self, reason: str = "audible_drain") -> None:
        if reason in {"committed_interrupt", "interim_interrupt", "final_interrupt", "contextual_redirect"}:
            logger.info(f"[Shortlist] Audio completion ignored for interrupted shortlist reason={reason}")
            return
        if self._shortlist_presentation_stage not in {
            SHORTLIST_STAGE_PREPARED,
            SHORTLIST_STAGE_STARTED,
            SHORTLIST_STAGE_PARTIAL,
        } or not self._last_presented_properties:
            return
        if self._shortlist_presentation_stage == SHORTLIST_STAGE_PREPARED:
            self._activate_shortlist_context(
                label=self._shortlist_context_label,
                search_key=self._shortlist_context_search_key,
                stage=SHORTLIST_STAGE_STARTED,
                spoken_text=self._shortlist_presentation_text,
            )
        elapsed_ms = 0
        if self._shortlist_started_at:
            elapsed_ms = int((time.time() - self._shortlist_started_at) * 1000)
        if elapsed_ms <= 0 and self._shortlist_presentation_text:
            elapsed_ms = int(min(30000, max(0, len(self._shortlist_presentation_text) * 45)))
        self._shortlist_playout_cursor["intro_played_ms"] = max(
            int(self._shortlist_playout_cursor.get("intro_played_ms") or 0),
            elapsed_ms,
        )
        self._shortlist_playout_cursor["first_item_played_ms"] = max(
            int(self._shortlist_playout_cursor.get("first_item_played_ms") or 0),
            min(elapsed_ms, 1800),
        )
        self._shortlist_playout_cursor["last_commit_checkpoint"] = elapsed_ms
        self._shortlist_exposure_bucket = "multiple_items" if elapsed_ms >= 2200 else "first_item_only"
        self._activate_shortlist_context(
            label=self._shortlist_context_label,
            search_key=self._shortlist_context_search_key,
            stage=SHORTLIST_STAGE_COMMITTED,
            spoken_text=self._shortlist_presentation_text,
        )
        logger.info(f"[Shortlist] Audible shortlist committed reason={reason}")

    def note_shortlist_relisted(self, spoken_text: str = "") -> None:
        if not self._last_presented_properties:
            return
        text = (spoken_text or self._shortlist_presentation_text or "").strip()
        estimated_ms = int(min(30000, max(0, len(text) * 45)))
        self._shortlist_presentation_text = text
        self._shortlist_started_at = time.time()
        self._shortlist_committed_at = None
        self._shortlist_partial_at = None
        self._shortlist_playout_cursor["last_commit_checkpoint"] = estimated_ms
        self._shortlist_exposure_bucket = "multiple_items" if estimated_ms >= 2200 else "first_item_only"
        self._activate_shortlist_context(
            label=self._shortlist_context_label,
            search_key=self._shortlist_context_search_key,
            stage=SHORTLIST_STAGE_COMMITTED,
            spoken_text=text,
        )
        logger.info(
            f"[Shortlist] Relist playback exposure reset bucket={self._shortlist_exposure_bucket} "
            f"estimated_ms={estimated_ms}"
        )

    def note_shortlist_interrupted(self, reason: str) -> None:
        if self._shortlist_presentation_stage not in {
            SHORTLIST_STAGE_PREPARED,
            SHORTLIST_STAGE_STARTED,
        } or not self._last_presented_properties:
            return
        elapsed_ms = 0
        if self._shortlist_started_at:
            elapsed_ms = int((time.time() - self._shortlist_started_at) * 1000)
        if elapsed_ms >= 2200:
            self._shortlist_exposure_bucket = "multiple_items"
        elif elapsed_ms >= 1100:
            self._shortlist_exposure_bucket = "first_item_only"
        elif elapsed_ms >= 350:
            self._shortlist_exposure_bucket = "intro_only"
        else:
            self._shortlist_exposure_bucket = "none"
        self._shortlist_playout_cursor["last_commit_checkpoint"] = elapsed_ms
        logger.info(
            f"[Shortlist] exposure bucket on interruption={self._shortlist_exposure_bucket} "
            f"played_ms={elapsed_ms}"
        )
        self._activate_shortlist_context(
            label=self._shortlist_context_label,
            search_key=self._shortlist_context_search_key,
            stage=SHORTLIST_STAGE_PARTIAL,
            spoken_text=self._shortlist_presentation_text,
        )
        logger.info(f"[Shortlist] Interrupted before commit reason={reason}")

    def _clear_shortlist_context(self, reason: str, *, clear_presented: bool = True) -> None:
        had_context = self._shortlist_context_active or bool(self._last_presented_properties)
        if clear_presented:
            self._clear_property_comparison_context(reason)
        self._shortlist_context_active = False
        self._shortlist_presentation_stage = SHORTLIST_STAGE_INACTIVE
        self._shortlist_presentation_text = ""
        self._shortlist_started_at = None
        self._shortlist_committed_at = None
        self._shortlist_partial_at = None
        self._shortlist_context_label = ""
        self._shortlist_context_search_key = ""
        self._shortlist_clarification_attempts = 0
        self._shortlist_playout_cursor = {}
        self._shortlist_exposure_bucket = "none"
        self._selection_pending = False
        if clear_presented:
            self._last_presented_properties = []
            self._current_shortlist_page_results = []
        if had_context:
            logger.info(f"[Shortlist] Cleared context reason={reason} clear_presented={clear_presented}")

    def has_active_shortlist_context(self) -> bool:
        return bool(self._shortlist_context_active and self._last_presented_properties)

    def shortlist_stage(self) -> str:
        return self._shortlist_presentation_stage

    def shortlist_is_committed(self) -> bool:
        return self._shortlist_presentation_stage == SHORTLIST_STAGE_COMMITTED

    def shortlist_is_partial(self) -> bool:
        return self._shortlist_presentation_stage == SHORTLIST_STAGE_PARTIAL

    def shortlist_is_pending_delivery(self) -> bool:
        return self._shortlist_presentation_stage in {
            SHORTLIST_STAGE_PREPARED,
            SHORTLIST_STAGE_STARTED,
            SHORTLIST_STAGE_PARTIAL,
        }

    def _shortlist_scope_label(self) -> str:
        if self._shortlist_context_label:
            return self._shortlist_context_label
        location = str(self._gathered_search.get("location") or "").strip()
        if location:
            return location
        city = str(self._gathered_search.get("city") or "").strip()
        return city or "the shortlist"

    def is_non_substantive_property_repair(self, text: str) -> bool:
        lower = (text or "").strip().lower()
        if not lower:
            return True
        if self.is_non_substantive_ack(lower):
            return True
        patterns = (
            r"^(?:hello|hi|hey)$",
            r"^(?:sorry|pardon|excuse me)$",
            r"^(?:can you|come again|what|sorry can you|can you repeat)$",
            r"^(?:hmm|huh|uh|um|okay|ok|right)$",
        )
        return any(re.match(pattern, lower, re.IGNORECASE) for pattern in patterns)

    def is_progress_check(self, text: str) -> bool:
        has_pending_site_visit_flow = getattr(self, "has_pending_site_visit_flow", None)
        if callable(has_pending_site_visit_flow) and has_pending_site_visit_flow():
            return False
        return _is_progress_check_text(text)

    def is_presence_reply(self, text: str) -> bool:
        lower = re.sub(r"[^\w\s]", " ", (text or "").strip().lower())
        lower = re.sub(r"\s+", " ", lower).strip()
        if not lower:
            return False
        return bool(re.match(r"^(?:i\s+am|i'?m|am)\s+(?:here|there)|^(?:still\s+)?here$", lower, re.IGNORECASE))

    def is_callback_request(self, text: str) -> bool:
        lower = re.sub(r"[^\w\s]", " ", (text or "").strip().lower())
        lower = re.sub(r"\s+", " ", lower).strip()
        if not lower:
            return False
        return bool(
            re.search(
                r"\b("
                r"call\s+me\s+back|call\s+back|callback|"
                r"can\s+i\s+get\s+a\s+call|can\s+we\s+get\s+a\s+call|"
                r"i\s+(?:need|want|would\s+like)\s+(?:a\s+)?call|"
                r"please\s+call\s+me|"
                r"arrange\s+(?:a\s+)?call|arrange\s+(?:a\s+)?callback|"
                r"have\s+(?:your\s+team|someone)\s+call\s+me|someone\s+call\s+me|"
                r"get\s+someone\s+to\s+call|team\s+(?:can\s+)?call\s+me|"
                r"contact\s+me|reach\s+out\s+to\s+me"
                r")\b",
                lower,
                re.IGNORECASE,
            )
        )

    def safe_callback_property_name(self) -> str:
        if self._active_property_id:
            source = self._current_property_context_ref() or {}
            name = str(
                source.get("name")
                or source.get("project_name")
                or source.get("Project_Name")
                or source.get("property_name")
                or self._active_property_name
                or ""
            ).strip()
            if name:
                return name
        location = str(self._gathered_search.get("location") or "").strip()
        property_type = str(self._gathered_search.get("property_type") or "Property").strip()
        if location:
            return f"{property_type} enquiry in {location}"
        city = str(self._gathered_search.get("city") or "Chennai").strip()
        return f"{property_type} enquiry in {city}"

    def build_presence_reply(self) -> str:
        self.clear_pending_property_lookup()
        self.clear_pending_property_callback_offer()
        return "Yes, I'm here. Please go ahead."

    def has_pending_result_delivery(self) -> bool:
        return bool(self.filler_active or self.shortlist_is_pending_delivery())

    def build_progress_check_reply(self) -> str | None:
        if self.filler_active and not self.has_active_shortlist_context():
            return "I'm still checking that. One moment."
        if self.shortlist_stage() in {SHORTLIST_STAGE_PREPARED, SHORTLIST_STAGE_STARTED}:
            return "I'm still pulling up the matching properties. One moment."
        if self.shortlist_is_partial():
            _replay = self.build_relist_response("list the properties again")
            if _replay:
                return f"Let me quickly repeat the options. {_replay}"
            return "Let me quickly repeat the options."
        return "Yes, I can hear you. Please go ahead."

    def build_shortlist_progress_reply(self, text: str) -> str | None:
        lower = (text or "").strip().lower()
        if not lower or not self.has_active_shortlist_context():
            return None
        if self.is_deterministic_closing_turn(text):
            return None
        _active_in_shortlist = bool(
            self._active_property_id
            and any(
                str(prop.get("property_id") or "").strip() == self._active_property_id
                for prop in (self._last_presented_properties or [])
            )
        )
        if self._active_property_id:
            prompt = self._last_spoken_prompt or {}
            spoken_text = str(prompt.get("spoken_text") or "").strip()
            if (
                _active_in_shortlist
                and spoken_text
                and prompt.get("question_expected")
                and self.is_progress_check(lower)
            ):
                return spoken_text
        if not _active_in_shortlist and self._active_property_id:
            return None
        if self.is_progress_check(lower) or re.search(
            r"\b(tell tell|go ahead|continue|carry on|repeat that|say that again|list them again)\b",
            lower,
            re.IGNORECASE,
        ):
            replay = self.build_relist_response("list the properties again")
            if replay:
                return replay
            return self.build_shortlist_clarification_text()
        return None

    def is_deterministic_closing_turn(self, text: str) -> bool:
        lower = (text or "").strip().lower()
        if not lower:
            return False
        if _classify_priority_user_intent(lower) == "closing_ack":
            return True
        if self.is_closing_gratitude_reply(text):
            return True
        return bool(
            re.fullmatch(
                r"(?:(?:ok|okay)[ ,]+)?(?:no[ ,]+)?(?:thank you|thanks)(?:[ ,]+bye)?[.!]?",
                lower,
            )
        )

    def build_deterministic_closing_reply(self) -> str:
        return "Thank you for calling JLL Homes. Have a great day."

    def _has_meaningful_gather_context(self) -> bool:
        gs = self._gathered_search or {}
        return any(
            gs.get(field)
            for field in (
                "property_type",
                "location",
                "project_category",
                "construction_state",
                "bedrooms",
                "min_price",
                "max_price",
                "_budget_flexible",
                "_citywide_search",
            )
        )

    def is_opening_conversation_context(self) -> bool:
        if self._has_live_results or self.has_active_shortlist_context():
            return False
        if self.current_locked_property_target() or self._active_property_id:
            return False
        if self._selection_pending:
            return False
        if self._pending_property_lookup or self._pending_variant_selection or self._pending_property_callback_offer:
            return False
        return True

    def build_opening_resume_prompt(self) -> str | None:
        resume_prompt = self.build_gather_resume_prompt()
        if resume_prompt:
            logger.info(
                f"[Opening] resume_strategy=pending_gather field={self._pending_gather_field or '-'}"
            )
            return resume_prompt
        if not self.is_opening_conversation_context():
            return None
        if not self._has_meaningful_gather_context():
            return None
        next_prompt = _next_deterministic_gather_prompt(self._gathered_search)
        if next_prompt:
            logger.info("[Opening] resume_strategy=natural_gather_entry")
        return next_prompt

    def build_meta_question_reply(self, text: str) -> str | None:
        base, response_family, interrupt_kind = _meta_question_base_reply(text)
        if not base or not interrupt_kind:
            return None
        resume_prompt = self.build_opening_resume_prompt()
        logger.info(
            f"[Opening] classifier={interrupt_kind} response_family={response_family} "
            f"resume_prompt_appended={bool(resume_prompt)}"
        )
        if resume_prompt:
            return f"{base} {resume_prompt}"
        return base

    def build_gather_resume_prompt(self) -> str | None:
        pending_prompt = self.build_pending_gather_resume_prompt()
        if pending_prompt:
            logger.info(
                f"[GatherResume] deterministic_followup_path=gather_resume_prompt "
                f"field={self._pending_gather_field or '-'}"
            )
            return pending_prompt
        prompt = self._last_spoken_prompt or {}
        if prompt.get("kind") != "assistant_reply" or not prompt.get("question_expected"):
            return None
        spoken_text = str(prompt.get("spoken_text") or "").strip()
        if not spoken_text:
            return None
        expected_field = _detect_expected_gather_field(
            [{"role": "assistant", "content": spoken_text}],
            city=str(self._gathered_search.get("city") or "Chennai"),
        )
        if expected_field:
            return spoken_text
        return None

    def _latest_scope_matches(self, text: str) -> bool:
        lower = (text or "").strip().lower()
        if not lower:
            return False
        location = str(self._gathered_search.get("location") or "").strip().lower()
        city = str(self._gathered_search.get("city") or "").strip().lower()
        if location:
            return location in lower
        return bool(city and city in lower)

    def _looks_like_shortlist_reference(self, text: str) -> bool:
        lower = (text or "").strip().lower()
        if not lower or not self._last_presented_properties:
            return False
        if self._extract_known_property_name_from_text(text):
            return False
        if self.is_relist_request(text):
            return True
        ordinal_or_deictic = (
            r"\b(first|second|third|fourth|fifth|last|1st|2nd|3rd|4th|5th)\b(?:\s+(?:one|property|project|option))?",
            r"\b(?:the\s+)?(?:one|property|project|option)\s+(?:first|second|third|fourth|fifth|last|1st|2nd|3rd|4th|5th)\b",
            r"\b(this one|that one|the one|this property|that property|the property|first property|second property|third property)\b",
        )
        if any(re.search(pattern, lower, re.IGNORECASE) for pattern in ordinal_or_deictic):
            return True
        if re.search(r"\b(the one|property|project)\s+in\b", lower, re.IGNORECASE):
            return True
        return False

    def _shortlist_ordinal_position_from_text(self, text: str) -> int | None:
        normalized = re.sub(r"[^a-z0-9\s]+", " ", (text or "").lower())
        normalized = re.sub(r"\s+", " ", normalized).strip()
        if not normalized:
            return None
        ordinal_map = {
            "first": 1, "1st": 1,
            "second": 2, "2nd": 2,
            "third": 3, "3rd": 3,
            "fourth": 4, "4th": 4,
            "fifth": 5, "5th": 5,
        }
        for token, position in ordinal_map.items():
            if re.search(rf"\b{re.escape(token)}\b", normalized):
                return position
        return None

    def _shortlist_choice_phrase(self) -> str:
        labels = ["first", "second", "third", "fourth", "fifth"]
        count = min(len(self._presented_properties_for_resolution()), len(labels))
        available = labels[:count]
        if not available:
            return "the property name"
        if len(available) == 1:
            return f"{available[0]}, or the property name"
        if len(available) == 2:
            return f"{available[0]}, {available[1]}, or the property name"
        return f"{', '.join(available[:-1])}, or {available[-1]}, or the property name"

    def build_shortlist_out_of_range_response(self, text: str) -> str | None:
        position = self._shortlist_ordinal_position_from_text(text)
        if not position:
            return None
        count = len(self._presented_properties_for_resolution())
        if count <= 0 or position <= count:
            return None
        count_word = _num_to_indian_words(count).lower()
        property_word = "property" if count == 1 else "properties"
        return (
            f"I only showed {count_word} {property_word}. "
            f"You can say {self._shortlist_choice_phrase()}."
        )

    def build_shortlist_clarification_text(self) -> str:
        if self.shortlist_is_partial():
            _replay = self.build_relist_response("list the properties again")
            if _replay:
                return f"Let me quickly repeat the options. {_replay}"
            return "Let me quickly repeat the options."
        return f"You can say {self._shortlist_choice_phrase()}."

    def _clear_zero_result_followup_state(self) -> None:
        self._zero_result_followup_mode = None
        self._zero_result_route_lock = None
        for _k in (
            "_zero_result_origin_location",
            "_zero_result_origin_city",
            "_zero_result_origin_property_type",
            "_zero_result_origin_min_price",
            "_zero_result_origin_max_price",
            "_zero_result_origin_bedrooms",
            "_zero_result_origin_project_category",
            "_zero_result_origin_construction_state",
            "_exploring_alternatives",
            "_original_location",
        ):
            self._gathered_search.pop(_k, None)

    def _set_zero_result_followup_state(
        self,
        *,
        mode: str,
        route_lock: str | None = None,
        location: str = "",
        city: str = "",
        property_type: str = "",
    ) -> None:
        self._zero_result_followup_mode = mode
        if route_lock is not None:
            self._zero_result_route_lock = route_lock
        self._gathered_search["_zero_result_origin_location"] = (location or "").strip()
        self._gathered_search["_zero_result_origin_city"] = (city or "").strip()
        self._gathered_search["_zero_result_origin_property_type"] = (property_type or "").strip()
        self._gathered_search["_zero_result_origin_min_price"] = self._gathered_search.get("min_price")
        self._gathered_search["_zero_result_origin_max_price"] = self._gathered_search.get("max_price")
        self._gathered_search["_zero_result_origin_bedrooms"] = self._gathered_search.get("bedrooms")
        self._gathered_search["_zero_result_origin_project_category"] = self._gathered_search.get("project_category")
        self._gathered_search["_zero_result_origin_construction_state"] = self._gathered_search.get("construction_state")
        if mode != "awaiting_alternative_areas":
            self._gathered_search.pop("_exploring_alternatives", None)

    def reset_search_session_state(self) -> None:
        if self._pending_variant_selection is not None:
            self._pending_variant_selection["clear_reason"] = "reset_search_session"
        self._gathered_search = {}
        self._zero_result_followup_mode = None
        self._zero_result_state = None
        self._pending_budget_confirmation = None
        self._search_results_exhausted = False
        self._last_deliverable_result_count = 0
        self._shown_slugs = set()
        self._jll_page = 1
        self._last_search_key = ""
        self._backend_search_key = ""
        self._conversation_scope_key = ""
        self._ordinal_results = []
        self._all_seen_slugs = set()
        self._property_details_map.clear()
        self._clear_detail_overview_memory("reset_search_session")
        self._clear_shortlist_context("reset_search_session")
        self._pending_property_lookup = None
        self._pending_variant_selection = None
        self._pending_property_callback_offer = None
        self._pending_deterministic_detail = None
        self._detail_prefetch_generation += 1
        self._cancel_detail_prefetches("reset_search_session")
        self._clear_active_property()
        self.clear_pending_gather_resume_state("reset_search_session")
        self._last_spoken_prompt = None
        self._spoken_turn_ledger = []
        for _k in (
            "_pending_fallback_items",
            "_pending_key",
            "_pending_backend_fetch",
            "_pending_total_count",
            "_pending_display_page",
            "_search_exhausted",
            "_property_slugs",
            "_strict_location",
            "_search_intent",
        ):
            self._gathered_search.pop(_k, None)
        logger.info("[Reset] Search session state cleared")

    def clear_transient_property_routing_state(self) -> None:
        self.clear_pending_property_lookup()
        if self._pending_variant_selection is not None:
            self._pending_variant_selection["clear_reason"] = "routing_reset"
        self.clear_pending_variant_selection()
        self.clear_pending_property_callback_offer()
        self._pending_deterministic_detail = None
        self._explicit_property_focus_id = None
        self._active_property_id = None
        self._active_property_name = None
        self._forced_property_detail_id_once = None
        logger.info("[Routing] Cleared transient property routing state")

    def canonicalize_search_location(self, location: str, city: str | None = None) -> str:
        raw_location = str(location or "").strip()
        if not raw_location:
            return ""
        city_value = str(city or self._gathered_search.get("city") or "").strip() or None
        canonical = _resolve_canonical_location(raw_location, city_value, self._catalog)
        if canonical and canonical.strip():
            canonical = canonical.strip()
            if _normalize_location_key(canonical) != _normalize_location_key(raw_location):
                logger.info(
                    f"[LocationCanonical] raw={raw_location!r} canonical={canonical!r} city={city_value!r}"
                )
            return canonical
        return raw_location

    def _build_active_search_key(self) -> str:
        canonical_location = self.canonicalize_search_location(
            str(self._gathered_search.get("location") or "").strip(),
            str(self._gathered_search.get("city") or "").strip(),
        )
        return "|".join([
            str(self._gathered_search.get("city") or "").strip().lower(),
            canonical_location.strip().lower(),
            str(self._gathered_search.get("property_type") or "").strip().lower(),
            str(self._gathered_search.get("bedrooms") or "").strip().lower(),
            str(self._gathered_search.get("project_category") or "").strip().lower(),
            str(self._gathered_search.get("construction_state") or "").strip().lower(),
            str(self._gathered_search.get("min_price") or ""),
            str(self._gathered_search.get("max_price") or ""),
        ])

    async def try_build_cached_search_shortlist_response(
        self,
        requested_result_count: int | None = None,
        *,
        wait_for_inflight_ms: int = 0,
        fire_if_missing: bool = False,
    ) -> str | None:
        city = str(self._gathered_search.get("city") or "").strip()
        property_type = str(self._gathered_search.get("property_type") or "").strip()
        location = self.canonicalize_search_location(
            str(self._gathered_search.get("location") or "").strip(),
            city,
        )
        min_price = self._gathered_search.get("min_price")
        max_price = self._gathered_search.get("max_price")
        if not (city and property_type and location):
            return None
        if not (min_price or max_price or self._gathered_search.get("_budget_flexible")):
            return None
        prefetch_key = _make_prefetch_key(
            city,
            property_type,
            location,
            min_price,
            max_price,
            self._gathered_search.get("bedrooms"),
            self._gathered_search.get("project_category"),
            self._gathered_search.get("construction_state"),
        )
        cached = self._prefetch_cache.get(prefetch_key)
        logger.debug(f"[PrefetchKey] shortlist_lookup key={prefetch_key!r} location={location!r}")
        _pending_task = self._prefetch_tasks.get(prefetch_key)
        if fire_if_missing and cached is None and prefetch_key not in self._prefetch_tasks:
            _pending_task = asyncio.create_task(
                self._prefetch_search(
                    city,
                    property_type,
                    location,
                    min_price,
                    max_price,
                    self._gathered_search.get("bedrooms"),
                    self._gathered_search.get("project_category"),
                    self._gathered_search.get("construction_state"),
                )
            )
            cached = self._prefetch_cache.get(prefetch_key)
        if wait_for_inflight_ms > 0 and (cached is None or not isinstance(cached, dict)) and _pending_task:
            try:
                await asyncio.wait_for(
                    asyncio.shield(_pending_task),
                    timeout=max(0.01, wait_for_inflight_ms / 1000.0),
                )
            except asyncio.TimeoutError:
                logger.info(
                    f"[Prefetch] wait timed out for key={prefetch_key!r} "
                    f"after {wait_for_inflight_ms}ms"
                )
            except Exception as _prefetch_wait_err:
                logger.debug(f"[Prefetch] wait failed key={prefetch_key!r}: {_prefetch_wait_err}")
            cached = self._prefetch_cache.get(prefetch_key)
        if not isinstance(cached, dict) or not isinstance(cached.get("data"), dict):
            return None
        age = time.time() - float(cached.get("ts") or 0)
        if cached.get("turn_id") != self._prefetch_turn_id or age >= PREFETCH_TTL_SECONDS:
            self._prefetch_cache.pop(prefetch_key, None)
            return None
        result = dict(cached.get("data") or {})
        items = result.get("data")
        if not isinstance(items, list) or not items:
            self._prefetch_cache.pop(prefetch_key, None)
            return None
        self._prefetch_cache.pop(prefetch_key, None)
        requested_count = max(
            1,
            int(requested_result_count or self._gathered_search.get("result_count") or PRESENTED_PROPERTY_LIMIT),
        )
        result["requested_result_count"] = requested_count
        result.setdefault("property_type", property_type)
        result.setdefault("searched_property_type", property_type)
        result.setdefault("searched_location", location)
        result.setdefault("current_page", 1)
        search_key = self._build_active_search_key()
        self._backend_search_key = search_key
        self._last_search_key = search_key
        self._conversation_scope_key = self._build_conversation_scope_key(self._gathered_search)
        self._has_live_results = True
        self._shown_slugs = set()
        self._jll_page = 1
        self.clear_search_results_exhausted()
        self._last_deliverable_result_count = 0
        self._results_injected_this_turn = False
        self._ordinal_results = []
        self._all_seen_slugs = set()
        self._clear_shortlist_context("cached_search_shortlist_refresh")
        self.clear_transient_property_routing_state()
        self._clear_active_property()
        self.clear_pending_gather_resume_state("cached_search_shortlist")

        prop_slug_map = self._gathered_search.setdefault("_property_slugs", {})
        for item in items:
            prop_id = str(item.get("property_id") or item.get("project_slug") or item.get("slug") or "").strip()
            name = str(
                item.get("project_name")
                or item.get("name")
                or item.get("projectName")
                or ""
            ).strip()
            if not prop_id:
                continue
            self._slug_cache[prop_id] = item
            self._property_details_map[prop_id] = {
                **(self._property_details_map.get(prop_id) or {}),
                **item,
            }
            if name:
                self._name_to_slug[name.lower()] = prop_id
            prop_slug_map[prop_id] = name or prop_id
            if prop_id not in self._all_seen_slugs:
                self._ordinal_results.append(item)
                self._all_seen_slugs.add(prop_id)

        visible_items = items[:requested_count]
        grouped_presented = self._extract_property_variants(visible_items)
        self._set_current_shortlist_page_results(visible_items)
        self._last_presented_properties = []
        for pos, group in enumerate(grouped_presented, start=1):
            variants = sorted(
                group.get("variants") or [],
                key=lambda v: (
                    v.get("price_num", float("inf")),
                    str(v.get("bhk") or ""),
                    str(v.get("property_id") or ""),
                ),
            )
            if not variants:
                continue
            primary = variants[0]
            self._last_presented_properties.append({
                "position": pos,
                "name": group.get("name") or primary.get("name") or "?",
                "property_id": primary.get("property_id"),
                "price_value": (
                    int(primary.get("price_num"))
                    if primary.get("price_num") not in (None, float("inf"))
                    else None
                ),
                "starting_price": primary.get("price"),
                "variants": variants,
            })
        spoken = _build_search_results_speech(
            result,
            selected_items=visible_items,
        )
        if not spoken:
            return None
        self._last_deliverable_result_count = len(self._last_presented_properties)
        for item in visible_items:
            prop_id = str(item.get("property_id") or item.get("project_slug") or item.get("slug") or "").strip()
            if prop_id:
                self._shown_slugs.add(prop_id)
                prop_slug_map[prop_id] = (
                    item.get("project_name")
                    or item.get("name")
                    or item.get("projectName")
                    or prop_slug_map.get(prop_id)
                    or prop_id
                )
        self._gathered_search["_pending_key"] = search_key
        self._gathered_search["_pending_total_count"] = int(result.get("total_count") or len(items) or 0)
        self._gathered_search["_pending_display_page"] = 1
        self._gathered_search["_pending_backend_fetch"] = False
        buffered_page_items = result.get("buffered_page_items") or []
        if isinstance(buffered_page_items, list) and buffered_page_items:
            self._gathered_search["_pending_fallback_items"] = buffered_page_items
            self._gathered_search["_pending_display_page"] = 2
            self._gathered_search["_pending_backend_fetch"] = bool(
                result.get("has_more_beyond_buffer", False)
            )
            logger.info(
                f"[Pagination] Cached {len(buffered_page_items)} hidden cached-shortlist items "
                f"for next delivery (fetch_more_after_buffer={self._gathered_search['_pending_backend_fetch']})"
            )
        self._prepare_shortlist_presentation(
            spoken_text=spoken,
            label=location or city,
            search_key=search_key,
        )
        self.allow_property_direct_speech_once()
        logger.info(
            f"[SearchDirectSpeech] deterministic_followup_path=cached_search_shortlist "
            f"count={len(self._last_presented_properties)} search_key={search_key!r}"
        )
        if self._last_presented_properties:
            names = [p["name"] for p in self._last_presented_properties]
            logger.info(f"[SearchResults] Cached shortlist prepared: {names}")
        return spoken

    def try_build_pending_pagination_response(self, requested_result_count: int | None = None) -> str | None:
        search_key = self._build_active_search_key()
        pending_key = self._gathered_search.get("_pending_key")
        pending_items = self._gathered_search.get("_pending_fallback_items")
        pending_count = len(pending_items) if isinstance(pending_items, list) else 0
        logger.info(
            f"[PaginationFastPath] pagination_scope_key={search_key!r} "
            f"last_search_key={self._last_search_key!r} pending_key={pending_key!r} "
            f"shown_slugs_count={len(self._shown_slugs)} pending_items_count={pending_count}"
        )
        if not isinstance(pending_items, list) or not pending_items:
            return None
        if pending_key != search_key:
            logger.warning(
                f"[PaginationFastPath] pending cache key mismatch - expected={search_key!r} got={pending_key!r}"
            )
            return None

        page_size = max(
            1,
            int(requested_result_count or self._gathered_search.get("result_count") or PRESENTED_PROPERTY_LIMIT),
        )
        items_to_serve = pending_items[:page_size]
        remaining = pending_items[page_size:] if len(pending_items) > page_size else []
        if not items_to_serve:
            return None

        display_page = int(self._gathered_search.get("_pending_display_page") or (self._jll_page + 1))
        pending_total_count = int(
            self._gathered_search.get("_pending_total_count")
            or len(self._shown_slugs) + len(items_to_serve) + len(remaining)
        )
        pending_backend_fetch = bool(self._gathered_search.get("_pending_backend_fetch"))

        if remaining:
            self._gathered_search["_pending_fallback_items"] = remaining
            self._gathered_search["_pending_display_page"] = display_page + 1
        else:
            self._gathered_search.pop("_pending_fallback_items", None)
            if pending_backend_fetch:
                self._gathered_search["_pending_backend_fetch"] = True
                self._gathered_search["_pending_display_page"] = display_page + 1
            else:
                self._gathered_search.pop("_pending_backend_fetch", None)
                self._gathered_search["_search_exhausted"] = True

        result = {
            "success": True,
            "data": items_to_serve,
            "has_more": bool(remaining) or pending_backend_fetch,
            "current_page": display_page,
            "total_count": pending_total_count,
            "requested_result_count": page_size,
            "property_type": self._gathered_search.get("property_type") or "property",
            "searched_property_type": self._gathered_search.get("property_type") or "property",
            "searched_location": self._gathered_search.get("location") or self._gathered_search.get("city") or "",
        }
        if self._gathered_search.get("bedrooms"):
            result["searched_bedrooms"] = self._gathered_search.get("bedrooms")

        spoken = _build_search_results_speech(result, selected_items=items_to_serve)
        if not spoken:
            return None
        if len(items_to_serve) < page_size:
            plural = "property" if len(items_to_serve) == 1 else "properties"
            spoken = (
                f"I have only {len(items_to_serve)} more matching {plural} in this result set. "
                f"{spoken}"
            )

        prop_slug_map = self._gathered_search.setdefault("_property_slugs", {})
        for item in items_to_serve:
            prop_id = str(item.get("property_id") or item.get("project_slug") or item.get("slug") or "").strip()
            name = str(
                item.get("project_name")
                or item.get("name")
                or item.get("projectName")
                or ""
            ).strip()
            if not prop_id:
                continue
            self._shown_slugs.add(prop_id)
            self._slug_cache[prop_id] = item
            self._property_details_map[prop_id] = {
                **(self._property_details_map.get(prop_id) or {}),
                **item,
            }
            if name:
                self._name_to_slug[name.lower()] = prop_id
            prop_slug_map[prop_id] = name or prop_id
            if prop_id not in self._all_seen_slugs:
                self._ordinal_results.append(item)
                self._all_seen_slugs.add(prop_id)

        grouped_presented = self._extract_property_variants(items_to_serve)
        self._set_current_shortlist_page_results(items_to_serve)
        self._last_presented_properties = []
        for pos, group in enumerate(grouped_presented, start=1):
            variants = sorted(
                group.get("variants") or [],
                key=lambda v: (
                    v.get("price_num", float("inf")),
                    str(v.get("bhk") or ""),
                    str(v.get("property_id") or ""),
                ),
            )
            if not variants:
                continue
            primary = variants[0]
            self._last_presented_properties.append({
                "position": pos,
                "name": group.get("name") or primary.get("name") or "?",
                "property_id": primary.get("property_id"),
                "price_value": (
                    int(primary.get("price_num"))
                    if primary.get("price_num") not in (None, float("inf"))
                    else None
                ),
                "starting_price": primary.get("price"),
                "variants": variants,
            })

        self._jll_page = display_page
        self._last_search_key = search_key
        self._backend_search_key = search_key
        self._has_live_results = True
        self._last_deliverable_result_count = max(
            self._last_deliverable_result_count,
            len(self._shown_slugs),
        )
        self._prepare_shortlist_presentation(
            spoken_text=spoken,
            label=self._gathered_search.get("location") or self._gathered_search.get("city") or "",
            search_key=search_key,
        )
        logger.info(
            f"[PaginationFastPath] served_from_pending_cache count={len(items_to_serve)} "
            f"remaining={len(remaining)} shown_slugs_count={len(self._shown_slugs)}"
        )
        if self._last_presented_properties:
            logger.info(
                f"[SearchResults] Cached pagination prepared: "
                f"{[p['name'] for p in self._last_presented_properties]}"
            )
        return spoken

    def classify_routing_intent(self, text: str) -> dict:
        _intent = _classify_priority_user_intent(text)
        _count = _extract_requested_result_count(text) if _intent == "pagination" else None
        return {
            "intent": _intent,
            "requested_result_count": _count,
        }

    def _looks_like_generic_property_search(self, text: str) -> bool:
        lower = (text or "").strip().lower()
        if not lower:
            return False
        compact = re.sub(r"\s+", " ", lower)
        generic_terms = (
            "property in",
            "properties in",
            "apartment in",
            "apartments in",
            "villa in",
            "villas in",
            "plot in",
            "plots in",
            "land in",
            "lands in",
            "independent house in",
            "independent houses in",
            "house in",
            "houses in",
            "home in",
            "homes in",
            "properties near",
            "property near",
            "looking for properties",
            "looking for apartment",
            "looking for apartments",
            "looking for a house",
            "looking for house",
            "looking for an independent house",
            "looking for independent house",
            "looking for land",
            "looking for a home",
            "looking for home",
            "find properties",
            "find me properties",
            "search for properties",
            "search properties",
            "search properties",
            "show properties",
            "show me properties",
            "find apartments",
            "find villas",
            "find plots",
            "find land",
            "find independent house",
            "other location",
            "other locations",
            "another location",
            "different location",
            "other area",
            "another area",
            "different area",
        )
        if any(term in compact for term in generic_terms):
            return True
        generic_patterns = (
            r"\b(?:i\s+am\s+|i'm\s+|im\s+)?(?:looking|searching)\s+for\s+(?:a\s+)?(?:property|properties|apartment|apartments|villa|villas|plot|plots|land|lands|independent\s+houses?)\b",
            r"\b(?:find|search|show|list|suggest|recommend)\s+(?:me\s+)?(?:a\s+)?(?:property|properties|apartment|apartments|villa|villas|plot|plots|land|lands|independent\s+houses?)\b",
            r"\b(?:property|properties|apartment|apartments|villa|villas|plot|plots|land|lands|independent\s+houses?)\s+(?:available\s+)?(?:at|near|around)\b",
            r"\b(?:i\s+am\s+|i'm\s+|im\s+)?(?:looking|searching)\s+for\s+(?:a\s+)?(?:house|houses|home|homes)\b",
            r"\b(?:find|search|show|list|suggest|recommend)\s+(?:me\s+)?(?:a\s+)?(?:house|houses|home|homes)\b",
            r"\b(?:a\s+)?property\s+[a-z][a-z\s.]{2,}$",
        )
        if any(re.search(pattern, compact, re.IGNORECASE) for pattern in generic_patterns):
            return True
        city = str(self._gathered_search.get("city") or "Chennai").strip() or "Chennai"
        known_locations = {
            _normalize_location_key(loc)
            for loc in _KNOWN_LOCATIONS.get(city, [])
            if str(loc or "").strip()
        }
        known_locations.update(_LOCATION_ALIASES.keys())
        words_norm = _normalize_location_key(compact)
        has_known_place = any(
            loc and re.search(rf"\b{re.escape(loc)}\b", words_norm)
            for loc in known_locations
        ) or any(city_name in words_norm for city_name in _CITY_CANONICAL)
        if has_known_place and re.search(r"\b(?:property|properties|apartment|apartments|villa|villas|plot|plots|land|lands|house|houses|home|homes)\b", compact):
            return True
        return False

    def _looks_like_filter_change_request(self, text: str) -> bool:
        lower = (text or "").strip().lower()
        if not lower:
            return False
        if self._looks_like_active_property_possession_question(lower):
            return False
        if any(
            rx.search(lower)
            for rx in (
                _READY_TO_MOVE_RE,
                _UNDER_CONSTRUCTION_RE,
                _LAUNCHED_RE,
                _NEW_PROJECT_RE,
                _RESALE_PROJECT_RE,
            )
        ):
            return True
        patterns = (
            r"\bready\s+to\b",
            r"\bonly\s+(?:new|resale|ready(?:\s+to\s+move)?|under\s+construction|launched)\b",
            r"\b(show|find|search|list|give)\b.{0,30}\b(?:new|resale|ready(?:\s+to\s+move)?|under\s+construction|launched)\b",
            r"\b(?:new|resale|ready(?:\s+to\s+move)?|under\s+construction|launched)\b.{0,30}\b(properties|property|apartments|apartment|villas|villa|plots|plot|projects|project)\b",
            r"\bstate\s+of\s+construction\b",
        )
        return any(re.search(pattern, lower, re.IGNORECASE) for pattern in patterns)

    def is_more_results_request(self, text: str) -> bool:
        lower = (text or "").strip().lower()
        if not lower:
            return False
        if _looks_like_shortlist_detail_more_request(lower):
            logger.info(f"[PaginationGuard] overridden reason=detail_request text={text!r}")
            return False
        if _extract_requested_result_count(lower) is not None:
            return True
        patterns = (
            r"\b(show|tell|list|give|share|find)\b.{0,20}\b(more|next|other|another)\b.{0,20}\b(properties|property|options|apartments|apartment|villas|villa|plots|plot)\b",
            r"\b(more|other|another|next)\b.{0,20}\b(properties|property|options|apartments|apartment|villas|villa|plots|plot)\b",
            r"\bnext\s+(three|3|few)\b",
            r"\bwhat\s+else\s+do\s+you\s+have\b",
            r"\bshow\s+me\s+more\b",
        )
        return any(re.search(pattern, lower, re.IGNORECASE) for pattern in patterns)

    def _looks_like_active_property_possession_question(self, text: str) -> bool:
        lower = (text or "").strip().lower()
        if not lower or not self._current_property_context_ref():
            return False
        if self._detect_single_property_fact(lower) != "possession":
            return False
        if re.search(r"\b(show|find|search|list|give|suggest|recommend)\b", lower, re.IGNORECASE):
            return False
        return bool(
            re.search(r"\b(is|it|this|that|the property|the project|whether|what is)\b", lower, re.IGNORECASE)
            or "?" in lower
        )

    def _current_property_context_ref(self) -> dict | None:
        locked = self.current_locked_property_target()
        if locked:
            return locked
        if self._active_property_id:
            active = self._get_cached_property(self._active_property_id)
            return active or {
                "property_id": self._active_property_id,
                "name": self._active_property_name or self._active_property_id,
            }
        return None

    def is_active_property_detail_continuation(self, text: str) -> bool:
        lower = (text or "").strip().lower()
        if not lower or not self._current_property_context_ref():
            return False
        if _extract_requested_result_count(lower) is not None:
            return False
        if re.search(
            r"\b(next|more|another|other|remaining|rest)\b.{0,24}"
            r"\b(properties?|options?|apartments?|villas?|plots?|listings?|results?)\b",
            lower,
            re.IGNORECASE,
        ):
            return False
        if _looks_like_explicit_detail_repeat(lower) or _looks_like_vague_more_details(lower):
            return True
        return bool(
            re.search(
                r"\b("
                r"(?:yes|yeah|yep|sure|okay|ok)[, ]+(?:please\s+)?(?:tell|share|give)\s+(?:me\s+)?more|"
                r"(?:tell|share|give)\s+(?:me\s+)?more\s+(?:about|details?\s+(?:about|on))\s+(?:it|this|that|the property|the project)|"
                r"more\s+details?\s+(?:about|on|for)\s+(?:it|this|that|the property|the project)|"
                r"know\s+more\s+(?:about|on)\s+(?:it|this|that|the property|the project)"
                r")\b",
                lower,
                re.IGNORECASE,
            )
        )

    def is_search_intent_redirect(self, text: str) -> bool:
        lower = (text or "").strip().lower()
        if not lower:
            return False
        if self._looks_like_generic_property_search(lower):
            return True
        if self.is_more_results_request(lower):
            return True
        if self._looks_like_filter_change_request(lower):
            return True
        patterns = (
            r"\b(find|search|show|suggest|recommend)\b.{0,40}\b(properties|property|apartments|apartment|villas|villa|plots|plot)\b",
            r"\b(properties|apartments|villas|plots)\b.{0,30}\b(in|near|around)\b",
            r"\b(any other|another|different)\s+(area|location|locality)\b",
            r"\b(within|for|in)\s+my\s+budget\b",
            r"\byou\s+can\s+suggest\s+me\b",
            r"\bsuggest\s+me\b",
            r"\bfind\b.{0,20}\b(in|near|around)\s+[a-z]",
        )
        return any(re.search(pattern, lower, re.IGNORECASE) for pattern in patterns)

    def detect_property_first_query(self, text: str) -> str | None:
        lower = (text or "").strip().lower()
        if not lower:
            return None
        if self.is_callback_request(lower) or self.is_progress_check(lower):
            return None
        if (
            self._active_property_id
            and self._detect_single_property_fact(lower)
            and not re.search(
                r"\b(no|not|actually|i\s+(?:am\s+)?asking|asking\s+about|i\s+mean|i\s+meant|tell\s+me\s+about|know\s+about)\b",
                lower,
                re.IGNORECASE,
            )
        ):
            return None
        if re.search(
            r"\b(?:first|second|third|fourth|fifth|last|1st|2nd|3rd|4th|5th)\s+(?:one|property|project|option)\b",
            lower,
            re.IGNORECASE,
        ):
            return None

        def _normalize_property_candidate(candidate: str) -> str:
            cleaned = re.sub(r"\s+", " ", (candidate or "").strip(" .?!,")).strip()
            cleaned = re.sub(
                r"^(?:yeah|yes|okay|ok|actually|just|i\s+said|i\s+mean|i\s+meant|the)\s+",
                "",
                cleaned,
                flags=re.IGNORECASE,
            ).strip(" .?!,")
            cleaned = re.sub(
                r"\bCasa\s+Grande\b",
                "Casagrand",
                cleaned,
                flags=re.IGNORECASE,
            )
            cleaned = re.sub(
                r"\s+(?:is\s+)?(?:located\s+)?(?:in|at|near|around)\s+.+$",
                "",
                cleaned,
                flags=re.IGNORECASE,
            )
            cleaned = re.sub(
                r"\b(?:the\s+)?\d+(?:\.\d+)?\s*(?:b\s*h\s*k|bhk)\s*(?:flat|apartment|villa|unit|option)?\b",
                " ",
                cleaned,
                flags=re.IGNORECASE,
            )
            cleaned = re.sub(r"\s+(?:property|project)\s*$", "", cleaned, flags=re.IGNORECASE)
            return re.sub(r"\s+", " ", cleaned).strip(" .?!,")

        def _candidate_is_direct_property_name(candidate: str) -> bool:
            candidate = _normalize_property_candidate(candidate)
            if not candidate:
                return False
            candidate_lower = candidate.lower().strip()
            if candidate_lower in {"it", "this", "that", "this property", "that property", "the property"}:
                return False
            if (
                "budget" in candidate_lower
                or "price range" in candidate_lower
                or _parse_inr_amounts(candidate)
                or _looks_like_off_domain_gather_request(candidate_lower)
                or _looks_like_unsupported_property_type_request(candidate_lower)
                or self._looks_like_filter_change_request(candidate_lower)
                or self.is_callback_request(candidate_lower)
                or self.is_progress_check(candidate_lower)
            ):
                return False
            if _extract_property_type_from_text(candidate):
                return False
            if self._looks_like_generic_property_search(candidate_lower):
                return False
            if re.search(
                r"\b(?:first|second|third|fourth|fifth|last|1st|2nd|3rd|4th|5th|one|two|three|four|five)\s+(?:one|property|project|option)\b",
                candidate_lower,
                re.IGNORECASE,
            ):
                return False
            if re.search(r"\b(apartment|apartments|villa|villas|plot|plots|property|properties)\s+in\b", candidate, re.IGNORECASE):
                return False
            if re.search(
                r"^(?:to\s+)?(?:book|order|buy|purchase|renew|cancel|pay|open|close|apply)\b",
                candidate_lower,
                re.IGNORECASE,
            ):
                return False
            city = str(self._gathered_search.get("city") or "Chennai").strip() or "Chennai"
            norm_candidate = _normalize_location_key(candidate)
            known_locations = {
                _normalize_location_key(loc)
                for loc in _KNOWN_LOCATIONS.get(city, [])
                if str(loc or "").strip()
            }
            if norm_candidate in known_locations or norm_candidate in _LOCATION_ALIASES:
                return False
            word_count = len(re.findall(r"[a-zA-Z0-9]+", candidate))
            if word_count < 2 and candidate_lower not in self._name_to_slug:
                return False
            return True

        _known_property = self._extract_known_property_name_from_text(text)
        if _known_property:
            return _known_property

        explicit_name_matches = re.findall(
            r"\b(?:the\s+)?(?:property|project)\s+name\s+is\s+([^.!?]+)",
            text or "",
            flags=re.IGNORECASE,
        )
        if explicit_name_matches:
            for raw_candidate in reversed(explicit_name_matches):
                candidate = _normalize_property_candidate(raw_candidate)
                if _candidate_is_direct_property_name(candidate):
                    return candidate

        if self._has_shortlist_page_context() and self._looks_like_shortlist_reference(text):
            logger.info(f"[PropertyFirst] Suppressed direct property detection due to active shortlist: {text!r}")
            return None

        if (
            _looks_like_off_domain_gather_request(lower)
            or _looks_like_unsupported_property_type_request(lower)
            or self._looks_like_generic_property_search(lower)
            or self._looks_like_filter_change_request(lower)
            or self.is_more_results_request(lower)
        ):
            if _looks_like_unsupported_property_type_request(lower):
                logger.info(f"[PropertyFirst] routed_unsupported_property_type_to_llm text={text!r}")
            return None
        if (
            "budget" in lower
            or "price range" in lower
            or "my price" in lower
            or "my budget is" in lower
            or "under " in lower
            or "within " in lower
            or "above " in lower
            or "less than " in lower
            or "more than " in lower
            or _parse_inr_amounts(text or "")
        ):
            return None
        patterns = (
            r"\b(?:no\s*,?\s*)?(?:i\s+(?:am\s+)?asking\s+about|i\s+am\s+asking\s+for|i\s+asked\s+about)\s+(.+?)[.?!]?\s*$",
            r"\b(?:i\s+(?:would\s+like|want)\s+to\s+know(?:\s+more)?\s+about|tell\s+me\s+about|i\s+saw|i\s+have\s+seen|can\s+you\s+tell\s+me\s+about|(?:can\s+you\s+)?(?:talk|speak)\s+about|what\s+about)\s+(.+?)(?:\s+on\s+the\s+website)?[.?!]?\s*$",
            r"\b(?:details\s+about|information\s+about|know(?:\s+more)?\s+about)\s+(.+?)[.?!]?\s*$",
            r"\b(?:find|search\s+for|look\s+for)\s+(.+?)[.?!]?\s*$",
            r"\b(?:i\s+(?:am\s+)?(?:looking|searching)\s+for|i\s+(?:just\s+)?want\s+to\s+(?:look|search)\s+for|(?:look|search)\s+for)\s+(.+?)[.?!]?\s*$",
            r"\b(?:i\s+(?:just\s+)?want|i\s+need|i\s+am\s+interested\s+in)\s+(.+?)[.?!]?\s*$",
            r"\b(?:i\s+said[\s,.:;-]+|i\s+mean\s+|i\s+meant\s+|the\s+(?:property|project)\s+(?:is|name\s+is)\s+|(?:property|project)\s+name\s+is\s+)(.+?)[.?!]?\s*$",
        )
        for pattern in patterns:
            match = re.search(pattern, text or "", re.IGNORECASE)
            if not match:
                continue
            candidate = _normalize_property_candidate(match.group(1))
            candidate_lower = candidate.lower().strip()
            if (
                re.search(r"\b(?:it|this|that|this property|that property|the property)\b", candidate_lower, re.IGNORECASE)
                and re.search(r"\b(amenities|amenity|features|facilities|price|cost|size|area|developer|builder|rera|possession|location)\b", candidate_lower, re.IGNORECASE)
            ):
                return None
            if not _candidate_is_direct_property_name(candidate):
                continue
            return candidate
        return None

    def is_pending_property_lookup_repair(self, text: str) -> bool:
        lower = (text or "").strip().lower()
        if not lower:
            return False
        return bool(
            re.search(r"\b(?:the\s+)?(?:property|project)\s+name\s+is\b", lower, re.IGNORECASE)
            or re.search(r"\b(?:located\s+in|location\s+is|area\s+is|address\s+is)\b", lower, re.IGNORECASE)
            or re.search(r"\b(?:the\s+)?(?:property|project|it|that|this)\s+(?:is\s+)?(?:in|at|near|around)\b", lower, re.IGNORECASE)
        )

    def refine_pending_property_lookup(self, raw: str, current_property_name: str) -> tuple[str, str]:
        spoken = (raw or "").strip(" .?!,")
        if not spoken:
            return current_property_name, ""
        if self.is_non_substantive_property_repair(spoken):
            return current_property_name, ""

        city = self._gathered_search.get("city") or "Chennai"
        location_hint = ""

        name_match = re.search(
            r"\b(?:the\s+)?(?:property|project)\s+name\s+is\s+(.+?)(?:(?:\.\s*)?(?:it\s+is\s+)?located\s+in\b|$)",
            spoken,
            re.IGNORECASE,
        )
        if not name_match:
            name_match = re.search(
                r"\bname\s+is\s+(.+?)(?:(?:\.\s*)?(?:it\s+is\s+)?located\s+in\b|$)",
                spoken,
                re.IGNORECASE,
            )
        if name_match:
            candidate_name = re.sub(r"\s+", " ", name_match.group(1).strip(" .?!,"))
            location_match = re.search(r"\blocated\s+in\s+(.+?)\s*$", spoken, re.IGNORECASE)
            if location_match:
                location_hint = _resolve_canonical_location(location_match.group(1).strip(" .?!,"), city, self._catalog) or ""
            return candidate_name or current_property_name, location_hint

        location_repair_match = re.search(
            r"\b(?:located\s+in|location\s+is|area\s+is|address\s+is|(?:the\s+)?(?:property|project|it|that|this)\s+(?:is\s+)?(?:in|at|near|around))\s+(.+?)\s*$",
            spoken,
            re.IGNORECASE,
        )
        if location_repair_match:
            raw_location = re.sub(r"\s+", " ", location_repair_match.group(1).strip(" .?!,"))
            location_hint = _resolve_canonical_location(raw_location, city, self._catalog) or raw_location
            return current_property_name, location_hint

        canonical_loc = _resolve_canonical_location(spoken, city, self._catalog)
        if canonical_loc:
            return current_property_name, canonical_loc

        detected_query = self.detect_property_first_query(spoken)
        if detected_query:
            if detected_query.lower().startswith(current_property_name.lower()):
                location_match = re.search(r"\blocated\s+in\s+(.+?)\s*$", spoken, re.IGNORECASE)
                if location_match:
                    location_hint = _resolve_canonical_location(location_match.group(1).strip(" .?!,"), city, self._catalog) or ""
                    return current_property_name, location_hint
            return detected_query, ""

        words = [w for w in re.findall(r"\b\w+\b", spoken) if w]
        if len(words) >= 2:
            return spoken, ""
        return current_property_name, ""

    def property_resolve_name_for_turn(self, cached_name: str, current_turn_text: str) -> str:
        current = re.sub(r"\s+", " ", str(current_turn_text or "").strip(" .?!,"))
        cached = re.sub(r"\s+", " ", str(cached_name or "").strip(" .?!,"))
        if cached and current and cached.lower() not in current.lower():
            logger.info(
                f"[PropertyFirst] stale cached property name bypassed "
                f"cached={cached!r} current={current!r}"
            )
            return current
        return cached or current

    def _sanitize_property_resolve_variant(self, value: str) -> str:
        text = re.sub(r"\s+", " ", str(value or "").strip(" .?!,\"'"))
        if not text:
            return ""
        text = re.sub(
            r"^(?:the|this|that|property|project|called|named|name is)\s+",
            "",
            text,
            flags=re.IGNORECASE,
        ).strip(" .?!,\"'")
        text = re.sub(r"\s+(?:property|project)\s*$", "", text, flags=re.IGNORECASE)
        if len(text) > 80:
            return ""
        words = re.findall(r"[a-zA-Z0-9']+", text)
        if len(words) > 8:
            return ""
        generic = {"property", "project", "apartment", "apartments", "villa", "villas", "plot", "plots"}
        if not any(w.lower() not in generic for w in words):
            return ""
        return text

    def _dedupe_property_resolve_variants(self, values: list[str]) -> list[str]:
        seen: set[str] = set()
        variants: list[str] = []
        for value in values:
            cleaned = self._sanitize_property_resolve_variant(value)
            if not cleaned:
                continue
            key = re.sub(r"[^a-z0-9]+", "", cleaned.lower())
            if not key or key in seen:
                continue
            seen.add(key)
            variants.append(cleaned)
            if len(variants) >= 8:
                break
        return variants

    def build_property_resolve_rule_variants(
        self,
        raw_text: str,
        property_name: str,
        location_hint: str | None = None,
    ) -> dict:
        source = f"{raw_text or ''} {property_name or ''}"
        source_lower = source.lower()
        variants: list[str] = [property_name or ""]
        requested_bhk = self._extract_requested_bedroom_from_text(source_lower)

        cleaned = re.sub(
            r"\b(?:tell\s+me\s+about|find|search\s+for|look\s+for|property\s+name\s+is|"
            r"property|project|located\s+in|is\s+located\s+in)\b",
            " ",
            source,
            flags=re.IGNORECASE,
        )
        cleaned = re.sub(r"\b(?:in|at|near|around)\s+[a-z][a-z\s.']{1,40}$", "", cleaned, flags=re.IGNORECASE)
        cleaned = re.sub(r"\s+", " ", cleaned).strip(" .?!,")
        if cleaned:
            variants.append(cleaned)

        has_navin = re.search(r"\b(navins?|naveens?|naveen's|navin's)\b", source_lower)
        if has_navin and re.search(r"\bmayur(?:a)?\b|\bmayura\b", source_lower):
            variants.extend([
                "Navin's Mayura Gardens",
                "Navins Mayura Gardens",
                "Navin Mayura Gardens",
                "Naveen Mayura Gardens",
                "Mayura Gardens",
            ])

        if "indus" in source_lower and re.search(r"\b(vaksha|vakshas|worksha|naksa|naksha|thalam|talam)\b", source_lower):
            variants.extend([
                "Indus Vakshasthalam",
                "Indus Vakshasthalam T Nagar",
                "Vakshasthalam",
                "Indus Naksha Talam",
                "Indus Naksa Talam",
            ])

        if re.search(r"\b(opera|oprah|opra|o\s+op)\b", source_lower) and re.search(
            r"\b(kamdhenu|kam\s*dhenu|kaam|denon|dhenon)\b",
            source_lower,
        ):
            variants.extend([
                "Opera Kamdhenu",
                "Opera Kamdhenu T Nagar",
                "Kamdhenu",
                "Oprah Kamdhenu",
            ])

        if re.search(r"\b(aanirudh|anirudh|anirud)\b", source_lower) and "narmada" in source_lower:
            variants.extend([
                "Aanirudh Narmada",
                "Anirudh Narmada",
            ])

        if re.search(r"\b(radiance|radiancy|radiant)\b", source_lower) and re.search(
            r"\b(eternity|eterniti|tenty|tenti|tenity|entity)\b",
            source_lower,
        ):
            variants.extend([
                "Radiance Eternity",
                "Radiancy Eternity",
                "Radiance Tenty",
            ])
            if requested_bhk:
                variants.extend([
                    f"Radiance Eternity {requested_bhk} BHK",
                    f"{requested_bhk} BHK Radiance Eternity",
                    f"Radiance Eternity {requested_bhk} BHK Flat",
                ])

        if re.search(r"\b(rams?|ram's)\b", source_lower) and re.search(
            r"\b(haricharan|haricharan|hari\s*charan|signature)\b",
            source_lower,
        ):
            variants.extend([
                "Rams Haricharan Signature",
                "Ram's Haricharan Signature",
                "Haricharan Signature",
            ])
            if requested_bhk:
                variants.extend([
                    f"Rams Haricharan Signature {requested_bhk} BHK",
                    f"{requested_bhk} BHK Rams Haricharan Signature",
                    f"Rams Haricharan Signature {requested_bhk} BHK Flat",
                ])

        resolved_location_hint = str(location_hint or "").strip()
        variants = self._dedupe_property_resolve_variants(variants)
        original_key = re.sub(r"[^a-z0-9]+", "", self._sanitize_property_resolve_variant(property_name or "").lower())
        variant_keys = {
            re.sub(r"[^a-z0-9]+", "", self._sanitize_property_resolve_variant(value).lower())
            for value in variants
        }
        if variant_keys and variant_keys <= {original_key}:
            variants = []
        if variants:
            logger.info(
                f"[PropertyFirstRules] variants={variants!r} "
                f"location_hint={resolved_location_hint!r}"
            )
        return {"variants": variants, "location_hint": resolved_location_hint}

    def _extract_json_object(self, value: str) -> dict:
        text = str(value or "").strip()
        if not text:
            return {}
        try:
            parsed = json.loads(text)
            return parsed if isinstance(parsed, dict) else {}
        except Exception:
            pass
        match = re.search(r"\{.*\}", text, re.DOTALL)
        if not match:
            return {}
        try:
            parsed = json.loads(match.group(0))
            return parsed if isinstance(parsed, dict) else {}
        except Exception:
            return {}

    async def build_property_resolve_variants(
        self,
        raw_text: str,
        property_name: str,
        location_hint: str | None = None,
    ) -> dict:
        if str(os.getenv("PROPERTY_RESOLVE_LLM_FALLBACK", "1")).strip().lower() in {"0", "false", "no", "off"}:
            return {"variants": [], "location_hint": location_hint or ""}

        openai_key = os.getenv("OPENAI_API_KEY", "").strip()
        groq_key = os.getenv("GROQ_API_KEY", "").strip()
        if openai_key:
            url = os.getenv("PROPERTY_RESOLVE_LLM_URL", "https://api.openai.com/v1/chat/completions")
            model = os.getenv("PROPERTY_RESOLVE_LLM_MODEL", "gpt-4o-mini")
            api_key = openai_key
        elif groq_key:
            url = os.getenv("PROPERTY_RESOLVE_LLM_URL", "https://api.groq.com/openai/v1/chat/completions")
            model = os.getenv("PROPERTY_RESOLVE_LLM_MODEL", "llama-3.1-8b-instant")
            api_key = groq_key
        else:
            logger.info("[PropertyFirstLLM] skipped reason=no_api_key")
            return {"variants": [], "location_hint": location_hint or ""}

        system_prompt = (
            "You normalize Indian real-estate property references from speech transcripts. "
            "Return JSON only with keys: cleaned_phrase, variants, location_hint. "
            "Do not choose a property and do not invent unrelated names. "
            "Create up to 6 plausible property-name query variants for catalog lookup. "
            "Strip filler words like 'tell me about', 'this', 'that is located in', and area phrases. "
            "Correct common STT/name confusions such as naveen/navin, oprah/opera, "
            "triwari/srivari, astalaxmi/ashtalakshmi, and garden/gardens."
        )
        user_prompt = (
            f"Raw user text: {raw_text!r}\n"
            f"Deterministic extracted phrase: {property_name!r}\n"
            f"Known location hint, if any: {location_hint or ''!r}\n"
            "Return compact JSON like: "
            "{\"cleaned_phrase\":\"...\",\"variants\":[\"...\"],\"location_hint\":\"...\"}"
        )
        try:
            timeout_s = float(os.getenv("PROPERTY_RESOLVE_LLM_TIMEOUT_SECONDS", "2.5"))
        except (TypeError, ValueError):
            timeout_s = 2.5
        timeout_s = max(0.8, min(4.0, timeout_s))
        payload = {
            "model": model,
            "messages": [
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": user_prompt},
            ],
            "temperature": 0,
            "max_tokens": 180,
        }
        try:
            response = await self._http_client.post(
                url,
                headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},
                json=payload,
                timeout=httpx.Timeout(timeout_s, connect=min(1.0, timeout_s), read=timeout_s, write=1.0, pool=1.0),
            )
            response.raise_for_status()
            data = response.json()
            content = (
                data.get("choices", [{}])[0]
                .get("message", {})
                .get("content", "")
            )
            parsed = self._extract_json_object(content)
            raw_variants = parsed.get("variants") if isinstance(parsed.get("variants"), list) else []
            variants = self._dedupe_property_resolve_variants([
                str(parsed.get("cleaned_phrase") or ""),
                *[str(item or "") for item in raw_variants],
            ])
            resolved_location_hint = str(parsed.get("location_hint") or location_hint or "").strip()
            if resolved_location_hint:
                city = self._gathered_search.get("city") or "Chennai"
                resolved_location_hint = _resolve_canonical_location(resolved_location_hint, city, self._catalog) or resolved_location_hint
            logger.info(
                f"[PropertyFirstLLM] variants={variants!r} "
                f"location_hint={resolved_location_hint!r} model={model}"
            )
            return {"variants": variants, "location_hint": resolved_location_hint}
        except Exception as exc:
            logger.warning(f"[PropertyFirstLLM] variant extraction failed: {type(exc).__name__}: {exc}")
            return {"variants": [], "location_hint": location_hint or ""}

    async def resolve_property_by_name(
        self,
        property_name: str,
        location_hint: str | None = None,
        city: str | None = None,
        limit: int = 3,
        variants: list[str] | None = None,
    ) -> dict:
        params = {
            "name": property_name,
            "city": city or self._gathered_search.get("city") or "Chennai",
            "limit": str(limit),
            "call_id": self.call_context.get("callId", ""),
            "assistant_id": self.call_context.get("assistantId", ""),
        }
        if location_hint:
            params["location_hint"] = location_hint
        clean_variants = self._dedupe_property_resolve_variants(variants or [])
        if clean_variants:
            params["variants"] = json.dumps(clean_variants, ensure_ascii=False)
        url = f"{BACKEND_URL}/api/integration/proxy/property-resolve"
        logger.info(
            f"[PropertyFirst] resolve_property_by_name name={property_name!r} "
            f"city={params['city']!r} location_hint={location_hint!r} variants={len(clean_variants)}"
        )
        try:
            response = await self._http_client.get(url, params=params)
            response.raise_for_status()
            data = response.json()
            logger.info(
                f"[PropertyFirst] resolver match_type={data.get('match_type')} "
                f"candidates={len(data.get('candidates') or [])}"
            )
            return data if isinstance(data, dict) else {"success": False, "match_type": "none", "candidates": []}
        except Exception as exc:
            logger.warning(f"[PropertyFirst] resolver failed for {property_name!r}: {exc}")
            return {
                "success": False,
                "match_type": "none",
                "candidates": [],
                "error": type(exc).__name__,
            }

    async def resolve_property_by_name_hybrid(
        self,
        property_name: str,
        raw_text: str | None = None,
        location_hint: str | None = None,
        city: str | None = None,
        limit: int = 3,
    ) -> dict:
        initial = await self.resolve_property_by_name(
            property_name,
            location_hint=location_hint,
            city=city,
            limit=limit,
        )
        requested_bedroom = self._extract_requested_bedroom_from_text(raw_text or property_name)
        if initial.get("match_type") in {"single", "multiple"} and initial.get("candidates"):
            candidates = list(initial.get("candidates") or [])
            if requested_bedroom:
                filtered_candidates = [
                    normalized
                    for candidate in candidates
                    for normalized in [self._filter_item_to_requested_bedroom(candidate, requested_bedroom)]
                    if normalized is not None
                ]
                if filtered_candidates:
                    patched = dict(initial)
                    patched["candidates"] = filtered_candidates[:limit]
                    patched["match_type"] = "single" if len(filtered_candidates) == 1 else "multiple"
                    logger.info(
                        f"[PropertyFirst] resolver filtered candidates by requested BHK={requested_bedroom} "
                        f"count={len(filtered_candidates)}"
                    )
                    return patched
                logger.info(
                    f"[PropertyFirst] resolver initial match ignored requested BHK={requested_bedroom}; "
                    "trying variant fallback"
                )
            else:
                return initial

        rule_data = self.build_property_resolve_rule_variants(
            raw_text or property_name,
            property_name,
            location_hint=location_hint,
        )
        rule_variants = rule_data.get("variants") or []
        rule_location_hint = rule_data.get("location_hint") or location_hint
        if rule_variants or rule_location_hint != location_hint:
            rule_fallback = await self.resolve_property_by_name(
                property_name,
                location_hint=rule_location_hint,
                city=city,
                limit=limit,
                variants=rule_variants,
            )
            if rule_fallback.get("match_type") in {"single", "multiple"} and rule_fallback.get("candidates"):
                rule_fallback["rule_variant_fallback"] = {
                    "original_name": property_name,
                    "variants": rule_variants,
                    "location_hint": rule_location_hint or None,
                }
                logger.info(
                    f"[PropertyFirstRules] fallback_resolved match_type={rule_fallback.get('match_type')} "
                    f"candidates={len(rule_fallback.get('candidates') or [])}"
                )
                return rule_fallback

        variant_data = await self.build_property_resolve_variants(
            raw_text or property_name,
            property_name,
            location_hint=location_hint,
        )
        variants = variant_data.get("variants") or []
        fallback_location_hint = variant_data.get("location_hint") or location_hint
        if not variants and (not fallback_location_hint or fallback_location_hint == location_hint):
            return initial

        fallback = await self.resolve_property_by_name(
            property_name,
            location_hint=fallback_location_hint,
            city=city,
            limit=limit,
            variants=variants,
        )
        if fallback.get("match_type") in {"single", "multiple"} and fallback.get("candidates"):
            fallback["llm_variant_fallback"] = {
                "original_name": property_name,
                "variants": variants,
                "location_hint": fallback_location_hint or None,
            }
            logger.info(
                f"[PropertyFirstLLM] fallback_resolved match_type={fallback.get('match_type')} "
                f"candidates={len(fallback.get('candidates') or [])}"
            )
            return fallback
        return initial

    def _property_candidate_label(self, candidate: dict) -> str:
        name = str(candidate.get("name") or "that property").strip()
        area = str(candidate.get("location") or candidate.get("micro_market") or "").strip()
        bhk = str(candidate.get("bhk") or "").strip()
        price = str(candidate.get("price") or "").strip()
        bits = [name]
        if area:
            bits.append(f"in {area}")
        if bhk:
            bits.append(f"the {bhk} option")
        if price:
            bits.append(f"priced at {price}")
        return ", ".join(bits)

    def build_property_first_confirmation_text(self, candidate: dict) -> str:
        return f"Are you asking about {self._property_candidate_label(candidate)}?"

    def build_property_first_options_text(self, candidates: list[dict]) -> str:
        options = []
        for idx, candidate in enumerate(candidates[:3], start=1):
            options.append(f"Option {idx} is {self._property_candidate_label(candidate)}.")
        joined = " ".join(options)
        return f"I found a few similar properties. {joined} Which one are you asking about?"

    def set_pending_property_lookup(
        self,
        mode: str,
        property_name: str,
        candidates: list[dict] | None = None,
        location_hint: str | None = None,
        attempts: int = 0,
    ) -> None:
        self._pending_property_lookup = {
            "mode": mode,
            "property_name": property_name,
            "candidates": candidates or [],
            "location_hint": location_hint or "",
            "attempts": attempts,
            "created_turn_id": int(global_state_manager.turn_id or 0),
            "last_repeated_turn_id": -1,
            "repeat_count": 0,
        }
        self.clear_pending_property_callback_offer()
        if self._selection_pending:
            self._selection_pending = False

    def pending_property_lookup_is_expired(self) -> bool:
        pending = self._pending_property_lookup or {}
        if not pending:
            return False
        created_turn = int(pending.get("created_turn_id") or 0)
        current_turn = int(global_state_manager.turn_id or 0)
        attempts = int(pending.get("attempts") or 0)
        repeats = int(pending.get("repeat_count") or 0)
        return bool(created_turn and current_turn - created_turn > max(3, attempts + 2)) or repeats >= 2

    def resolve_property_first_selection(self, text: str) -> dict | None:
        pending = self._pending_property_lookup or {}
        candidates = pending.get("candidates") or []
        if not candidates:
            return None
        text_lower = (text or "").strip().lower()
        mentioned_amounts = {int(amount) for amount in (_parse_inr_amounts(text or "") or [])}
        ordinal_map = {
            "first": 1, "1st": 1, "one": 1,
            "second": 2, "2nd": 2, "two": 2,
            "third": 3, "3rd": 3, "three": 3,
        }
        for token, pos in ordinal_map.items():
            if re.search(rf"\b(?:option|property|project|number|the)\s+{re.escape(token)}\b|\b{re.escape(token)}\s+(?:option|property|project)\b", text_lower):
                if 1 <= pos <= len(candidates):
                    return candidates[pos - 1]
        requested_bedroom = self._normalize_bedroom_value(text_lower)
        if requested_bedroom:
            bhk_matches = []
            for candidate in candidates:
                candidate_bhk = self._normalize_bedroom_value(candidate.get("bhk") or candidate.get("type"))
                if not candidate_bhk:
                    cfgs = candidate.get("configs") or candidate.get("configurations") or []
                    for cfg in cfgs:
                        if isinstance(cfg, dict):
                            candidate_bhk = self._normalize_bedroom_value(cfg.get("type"))
                            if candidate_bhk:
                                break
                if candidate_bhk == requested_bedroom:
                    bhk_matches.append(candidate)
            if len(bhk_matches) == 1:
                logger.info(
                    f"[PropertyFirst] Resolved multiple-match candidate by BHK={requested_bedroom}"
                )
                return bhk_matches[0]
        if mentioned_amounts:
            priced_matches = []
            for candidate in candidates:
                candidate_amount = None
                parsed_candidate_amounts = _parse_inr_amounts(
                    str(candidate.get("price") or candidate.get("starting_price") or "")
                )
                if parsed_candidate_amounts:
                    candidate_amount = int(parsed_candidate_amounts[0])
                else:
                    try:
                        candidate_price_num = candidate.get("price_num")
                        if candidate_price_num not in (None, float("inf")):
                            candidate_amount = int(float(candidate_price_num))
                    except Exception:
                        candidate_amount = None
                if candidate_amount is not None and candidate_amount in mentioned_amounts:
                    priced_matches.append(candidate)
            if len(priced_matches) == 1:
                return priced_matches[0]
        normalized_text = re.sub(r"[^a-z0-9]+", " ", text_lower).strip()
        for candidate in candidates:
            candidate_name = str(candidate.get("name") or "").strip().lower()
            if not candidate_name:
                continue
            normalized_name = re.sub(r"[^a-z0-9]+", " ", candidate_name).strip()
            if normalized_name and (normalized_name in normalized_text or normalized_text in normalized_name):
                return candidate
            cand_words = {w for w in normalized_name.split() if len(w) >= 3}
            text_words = {w for w in normalized_text.split() if len(w) >= 3}
            if cand_words and len(cand_words & text_words) >= min(2, len(cand_words)):
                return candidate
        return None

    def build_property_first_clarification_text(self, property_name: str) -> str:
        return (
            f"Sure. I could not identify the exact property for {property_name}. "
            "Can you tell me the area or say the property name once again?"
        )

    def build_property_first_callback_text(self, property_name: str) -> str:
        return (
            f"Sorry, I still could not identify the exact property for {property_name}. "
            f"{_callback_offer_text(property_name)}"
        )

    def is_property_booking_intent(self, text: str) -> bool:
        lower = re.sub(r"\s+", " ", (text or "").strip().lower())
        if not lower:
            return False
        if self.is_callback_request(lower):
            return True
        return bool(
            re.search(
                r"\b(?:how\s+can\s+i|can\s+i|i\s+(?:would\s+like|want|need)\s+to|please\s+)?"
                r"(?:book|buy|purchase|reserve)\b",
                lower,
                re.IGNORECASE,
            )
            or re.search(
                r"\b(?:next\s+steps?|booking|site\s+visit|schedule\s+(?:a\s+)?visit)\b",
                lower,
                re.IGNORECASE,
            )
        )

    def build_property_booking_next_steps_text(self, property_name: str) -> str:
        name = str(property_name or "this property").strip() or "this property"
        return (
            f"For {name}, the next step is to speak with a JLL Homes property specialist "
            "or schedule a site visit. Would you prefer a callback or a site visit?"
        )

    def _seed_property_candidate_cache(self, candidate: dict | None) -> None:
        if not isinstance(candidate, dict):
            return
        property_id = str(candidate.get("property_id") or candidate.get("project_slug") or "").strip()
        if not property_id:
            return
        merged = {
            **(self._slug_cache.get(property_id) or {}),
            **(self._property_details_map.get(property_id) or {}),
            **candidate,
        }
        merged.setdefault("property_id", property_id)
        merged.setdefault("project_slug", property_id)
        self._slug_cache[property_id] = merged
        self._property_details_map[property_id] = merged
        name = str(candidate.get("name") or "").strip()
        if name:
            self._name_to_slug[name.lower()] = property_id
        self._mark_property_focus({
            "property_id": property_id,
            "name": name or merged.get("name") or merged.get("project_name"),
        })

    def is_active_property_followup(self, text: str) -> bool:
        lower = (text or "").strip().lower()
        if not lower or not self._active_property_id:
            return False
        if self._selection_pending or getattr(self, "_pending_property_lookup", None):
            return False
        pronoun_patterns = (
            r"\btell me about (?:it|this|the property)\b",
            r"\babout (?:it|this|the property)\b",
            r"\bfor (?:it|this|the property)\b",
            r"\b(?:its|it|this property|that property|the property|this project|that project|the project)\b.*\b(amenities|amenity|features|facilities|price|cost|size|area|developer|builder|rera|possession|posession|possesson|procession\s+date|process\s+(?:and\s+)?date|processing\s+date|location|configuration|config|bhk|bedroom|bedrooms|ready to move|under construction|handover|move[- ]?in)\b",
            r"\b(amenities|amenity|features|facilities|price|cost|size|area|developer|builder|rera|possession|posession|possesson|procession\s+date|process\s+(?:and\s+)?date|processing\s+date|location|configuration|config|bhk|bedroom|bedrooms|ready to move|under construction|handover|move[- ]?in)\b",
        )
        return any(re.search(pattern, lower, re.IGNORECASE) for pattern in pronoun_patterns)

    def should_suspend_search_state_updates(self, text: str) -> bool:
        lower = (text or "").strip().lower()
        if not lower:
            return False
        if self.is_search_intent_redirect(lower):
            return False
        if (
            self._pending_property_lookup
            or self._pending_variant_selection
            or self._pending_property_callback_offer
        ):
            return True
        if self.detect_property_first_query(text):
            return True
        if self.is_active_property_followup(text):
            return True
        if self.resolve_deterministic_detail_request(text):
            return True
        if self._selection_pending:
            if self.is_relist_request(text) or self.is_ambiguous_response(text):
                return True
            if self.resolve_property_selection(text):
                return True
        return False

    def is_property_first_affirmative(self, text: str) -> bool:
        spoken = (text or "").strip().lower()
        if not spoken:
            return False
        normalized = re.sub(r"[,\-]+", " ", spoken)
        normalized = re.sub(r"\s+", " ", normalized).strip()
        if _AFFIRM_ONLY_RE.match(normalized):
            return True
        patterns = (
            r"\b(obviously|yes\s+that\s+property|that\s+property\s+only|that\s+one|this\s+one|yes\s+this\s+one|yes\s+that\s+one)\b",
            r"\b(correct\s+property|same\s+property|that\s+property\s+correct)\b",
            r"\b(clearly|clear|yes\s+correct|yes\s+that\s+is\s+correct)\b",
        )
        return any(re.search(pattern, normalized, re.IGNORECASE) for pattern in patterns)

    def rewrite_confirmation_reply(self, text: str) -> str | None:
        pending = self._pending_value_confirmation
        if not pending:
            return None
        spoken = (text or "").strip()
        if not spoken:
            return None
        if _AFFIRM_ONLY_RE.match(spoken):
            self._pending_value_confirmation = None
            field = pending["field"]
            candidate = pending["candidate"]
            return f"Yes, I meant {candidate} as the {field}."
        if _NEGATIVE_ONLY_RE.match(spoken):
            self._pending_value_confirmation = None
            field = pending["field"]
            candidate = pending["candidate"]
            return f"No, not {candidate}. Let me give you the correct {field}."
        if pending["candidate"].lower() in spoken.lower():
            self._pending_value_confirmation = None
            return spoken
        self._pending_value_confirmation = None
        return spoken

    async def _ensure_catalog(self) -> None:
        """Fetch JLL catalog from backend once per call session (lazy, cached)."""
        if self._catalog is not None:
            return
        try:
            _r = await self._http_client.get(f"{BACKEND_URL}/api/integration/catalog")
            _r.raise_for_status()
            self._catalog = _r.json()
            _cities = self._catalog.get("cities") or []
            logger.info(f"[Catalog] Fetched {len(_cities)} cities from backend: {_cities}")
        except Exception as _e:
            logger.warning(f"[Catalog] Failed to fetch catalog: {_e} - validation will use _KNOWN_LOCATIONS fallback")
            self._catalog = {}  # empty dict means "loaded but empty" - skip validation

    async def _prewarm_session_cache(self) -> None:
        """Pre-fetch popular locations on session start to reduce cold-start latency."""
        if self._session_prewarmed:
            return  # Already pre-warmed

        logger.info("[Prefetch] Prewarming session cache with default locations")
        prewarm_tasks = []

        for city, location, min_price, max_price in self._default_prefetch_locations:
            task = self._prefetch_search(city, None, location, min_price, max_price)
            prewarm_tasks.append(task)

        # Fire all pre-warms concurrently (don't wait for completion)
        try:
            results = await asyncio.gather(*prewarm_tasks, return_exceptions=True)
            success_count = sum(1 for r in results if not isinstance(r, Exception))
            logger.info(f"[Prefetch] Prewarmed {success_count}/{len(prewarm_tasks)} default locations")
        except Exception as e:
            logger.debug(f"[Prefetch] Prewarm error (non-critical): {e}")
        finally:
            self._session_prewarmed = True

    async def _prefetch_search(
        self,
        city: str,
        property_type: str,
        location: str,
        min_price,
        max_price,
        bedrooms=None,
        project_category=None,
        construction_state=None,
    ) -> None:
        """Fire a search_properties HTTP call early (background), before the LLM tool call.

        Result is stored in self._prefetch_cache so _execute_endpoint() can return
        it instantly when the LLM's tool call arrives ~1â€“3 s later, eliminating the
        HTTP round-trip latency that users perceive as silence/pause.
        """
        import time as _t
        raw_location = str(location or "").strip()
        location = self.canonicalize_search_location(raw_location, city)
        _pf_key = _make_prefetch_key(
            city, property_type, location, min_price, max_price, bedrooms, project_category, construction_state
        )
        _raw_pf_key = _make_prefetch_key(
            city, property_type, raw_location, min_price, max_price, bedrooms, project_category, construction_state
        )
        logger.debug(
            f"[PrefetchKey] write key={_pf_key!r} raw_location={raw_location!r} canonical_location={location!r}"
        )
        _existing_task = self._prefetch_tasks.get(_pf_key)
        if _existing_task and not _existing_task.done():
            logger.debug(f"[Prefetch] Skipping duplicate in-flight request key={_pf_key!r}")
            return

        # Deduplication: skip if another prefetch is already in progress globally
        if self._prefetch_in_progress and _pf_key not in self._prefetch_cache:
            logger.debug(f"[Prefetch] Skipping - another prefetch already in progress")
            return

        # Use consistent key construction with _execute_endpoint for guaranteed cache hits
        _pf_key = _make_prefetch_key(
            city, property_type, location, min_price, max_price, bedrooms, project_category, construction_state
        )
        if _pf_key in self._prefetch_cache and self._prefetch_cache.get(_pf_key) is not None:
            return  # already in-flight or cached - don't duplicate

        self._prefetch_in_progress = True  # Set global in-progress flag
        self._prefetch_tasks[_pf_key] = asyncio.current_task()
        self._prefetch_cache[_pf_key] = None  # sentinel: in-flight
        try:
            _params = {
                "city": city,
                "property_type": property_type,
                "location": location,
                "page": "1",
            }
            if min_price:
                _params["min_price"] = str(min_price)
            if max_price:
                _params["max_price"] = str(max_price)
            if bedrooms:
                _params["bedrooms"] = str(bedrooms)
            if project_category:
                _params["project_category"] = str(project_category)
            if construction_state:
                _params["construction_state"] = str(construction_state)
            _url = f"{BACKEND_URL}/api/integration/proxy/search"
            logger.info(f"[Prefetch] â†’ {city}/{property_type}/{location} budget={min_price}-{max_price}")
            _resp = await self._http_client.get(_url, params=_params)
            if _resp.status_code == 200:
                _data = _resp.json()
                self._prefetch_cache[_pf_key] = {
                    "data": _data,
                    "ts": _t.time(),
                    "turn_id": self._prefetch_turn_id,
                }
                logger.debug(f"[Prefetch-DEBUG] WRITE key='{_pf_key}' value_len={len(str(_data))} cache_size={len(self._prefetch_cache)}")
                if _raw_pf_key != _pf_key:
                    self._prefetch_cache.pop(_raw_pf_key, None)
                logger.info(
                    f"[Prefetch] âœ“ cached early result for {location} "
                    f"(turn_id={self._prefetch_turn_id})"
                )
            else:
                logger.debug(f"[Prefetch] HTTP {_resp.status_code} for {location} - skipping cache")
                self._prefetch_cache.pop(_pf_key, None)
                if _raw_pf_key != _pf_key:
                    self._prefetch_cache.pop(_raw_pf_key, None)
        except Exception as _ex:
            logger.debug(f"[Prefetch] Failed for {location}: {_ex}")
            self._prefetch_cache.pop(_pf_key, None)
            if _raw_pf_key != _pf_key:
                self._prefetch_cache.pop(_raw_pf_key, None)
        finally:
            self._prefetch_in_progress = False  # Always reset the flag
            _task = self._prefetch_tasks.get(_pf_key)
            if _task is asyncio.current_task() or (_task and _task.done()):
                self._prefetch_tasks.pop(_pf_key, None)

    # â”€â”€ Smart cache helpers â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

    def _make_search_cache_key(self, city, property_type, location, min_price, max_price, bedrooms=None, project_category=None, construction_state=None) -> str:
        """Generate stable cache key from search parameters."""
        return f"search:{city}:{property_type}:{location}:{min_price}:{max_price}:{bedrooms}:{project_category}:{construction_state}"

    def _should_invalidate_cache(self, current_params: dict) -> bool:
        """Check if cached result should be invalidated based on param changes."""
        if not self._last_search_params:
            return True  # No previous cache

        # Invalidate if any core search param changed
        core_params = ["city", "property_type", "location", "min_price", "max_price", "bedrooms", "project_category", "construction_state"]
        for param in core_params:
            if self._last_search_params.get(param) != current_params.get(param):
                logger.debug(f"[Cache] Invalidated: {param} changed")
                return True
        return False

    def _cache_search_result(self, params: dict, result: dict) -> None:
        """Cache search result with param snapshot for invalidation tracking."""
        cache_key = self._make_search_cache_key(
            params.get("city"), params.get("property_type"), params.get("location"),
            params.get("min_price"), params.get("max_price"), params.get("bedrooms"), params.get("project_category"), params.get("construction_state")
        )
        # Store result with param snapshot
        result_with_meta = {
            **result,
            "_cached_city": params.get("city"),
            "_cached_location": params.get("location"),
            "_cached_min_price": params.get("min_price"),
            "_cached_max_price": params.get("max_price"),
            "_cached_at": time.time(),
        }
        self._search_results_cache[cache_key] = result_with_meta
        self._last_search_params = params.copy()
        logger.debug(f"[Cache] Stored result for key: {cache_key}")

    def _get_cached_search_result(self, params: dict) -> dict | None:
        """Get cached result if valid (not invalidated by param changes)."""
        cache_key = self._make_search_cache_key(
            params.get("city"), params.get("property_type"), params.get("location"),
            params.get("min_price"), params.get("max_price"), params.get("bedrooms"), params.get("project_category"), params.get("construction_state")
        )

        if cache_key not in self._search_results_cache:
            return None

        cached_result = self._search_results_cache[cache_key]

        # Check if params have changed (smart invalidation)
        if self._should_invalidate_cache(params):
            logger.debug(f"[Cache] Invalidated stale result for key: {cache_key}")
            del self._search_results_cache[cache_key]
            return None

        logger.debug(f"[Cache] HIT for key: {cache_key}")
        return cached_result

    # â”€â”€ Persona helpers â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

    def _inject_persona_context(self) -> None:
        """Inject a persona-specific tone hint into the system message (once per call).

        This adds a compact [PERSONA: ...] block to the top of the system prompt so
        the LLM automatically adapts its vocabulary, emphasis, and property ordering.
        """
        _PERSONA_TONES: dict[str, str | None] = {
            "luxury": (
                "\n\n[PERSONA: LUXURY BUYER]\n"
                "High-net-worth buyer. Lead with PREMIUM properties first. "
                "Emphasise exclusivity, amenities, lifestyle, and future appreciation. "
                "Use sophisticated language. Mention 'premium' positioning."
            ),
            "budget": (
                "\n\n[PERSONA: BUDGET BUYER]\n"
                "Price-sensitive buyer. Lead with the MOST AFFORDABLE options first. "
                "Emphasise value-for-money, price-per-sqft, and low down payment. "
                "Avoid words like 'premium' or 'luxury'. Be warm and reassuring."
            ),
            "investor": (
                "\n\n[PERSONA: INVESTOR]\n"
                "Buyer focused on investment returns. Emphasise rental yield, capital appreciation, "
                "possession timeline, RERA compliance, developer track record, and corridor growth "
                "(OMR, Electronic City, Whitefield, etc.). Skip lifestyle amenity descriptions "
                "unless the user asks. Use a data-driven, factual tone."
            ),
            "mid": None,   # No special tone for mid-range / unclassified buyers
        }
        
        # Pronunciation instruction for Indian currency terms and location names
        _pronunciation_guide = (
            "\n\n[PRONUNCIATION GUIDE]\n"
            "When speaking prices, use 'Lack' (spelled L-a-c-k) instead of 'lakh' for better Indian English pronunciation. "
            "Example: Write '1 Crore 61 Lack' instead of '1 Crore 61 lakh'. "
            "When speaking the location 'T Nagar', write 'tee naa-gr' instead of 'T Nagar' for correct pronunciation. "
            "The TTS system will pronounce 'Lack' and 'tee naa-gr' correctly as Indian words."
        )
        
        tone = _PERSONA_TONES.get(self._persona)
        if not tone or not self._context_ref:
            return
        try:
            _ctx = self._context_ref[0]
            _base = _ctx.messages[0]["content"]
            # Remove any prior PERSONA block before re-injecting (handles mid-call switch)
            _base = re.sub(r'\n\n\[PERSONA:.*?\n', '', _base, flags=re.DOTALL)
            # Remove any prior PRONUNCIATION GUIDE block
            _base = re.sub(r'\n\n\[PRONUNCIATION GUIDE\].*?(?=\n\n\[|\Z)', '', _base, flags=re.DOTALL)
            # Insert before CURRENT SEARCH RESULTS block if present, else append
            _anchor = '\n\n---\nCURRENT SEARCH RESULTS'
            if _anchor in _base:
                _base = _base.replace(_anchor, tone + _pronunciation_guide + _anchor, 1)
            else:
                _base = _base + tone + _pronunciation_guide
            _ctx.messages[0]["content"] = _base
            logger.info(f"[Persona] Injected '{self._persona}' tone block into system message")
        except Exception as _pe:
            logger.warning(f"[Persona] Failed to inject context: {_pe}")

    # â”€â”€ Ordinal Resolution Helpers â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

    def _resolve_ordinal_reference(self, text: str) -> int | None:
        """
        Deterministic ordinal resolver - returns 0-based index into _ordinal_results.
        Bypasses LLM ambiguity for precise ordinal mapping.

        Handles:
        - "first", "1st", "number 1" â†’ 0
        - "second", "2nd", "number 2" â†’ 1
        - "third", "3rd", "number 3" â†’ 2
        - "last", "last one" â†’ len(_ordinal_results) - 1
        - "previous one" â†’ last - 1 (if exists)
        - numeric: "5th", "8", "number 3"
        """
        _ordinal_source = (
            self._current_shortlist_page_results
            if self._has_shortlist_page_context()
            else self._ordinal_results
        )
        if not text or not _ordinal_source:
            return None

        _t = text.lower().strip()

        # Word-to-index mapping for explicit ordinals
        _ORDINAL_WORDS = {
            'first': 0, 'the first': 0, 'first one': 0, '1st': 0, 'number 1': 0,
            'second': 1, 'the second': 1, 'second one': 1, '2nd': 1, 'number 2': 1,
            'third': 2, 'the third': 2, 'third one': 2, '3rd': 2, 'number 3': 2,
            'fourth': 3, 'the fourth': 3, 'fourth one': 3, '4th': 3, 'number 4': 3,
            'fifth': 4, 'the fifth': 4, 'fifth one': 4, '5th': 4, 'number 5': 4,
            'sixth': 5, 'the sixth': 5, 'sixth one': 5, '6th': 5, 'number 6': 5,
            'seventh': 6, 'the seventh': 6, 'seventh one': 6, '7th': 6, 'number 7': 6,
            'eighth': 7, 'the eighth': 7, 'eighth one': 7, '8th': 7, 'number 8': 7,
            'ninth': 8, 'the ninth': 8, 'ninth one': 8, '9th': 8, 'number 9': 8,
            'tenth': 9, 'the tenth': 9, 'tenth one': 9, '10th': 9, 'number 10': 9,
        }

        # Check explicit ordinal words first (most reliable)
        for phrase, idx in _ORDINAL_WORDS.items():
            if phrase in _t:
                if 0 <= idx < len(_ordinal_source):
                    _prop = _ordinal_source[idx]
                    _pid = _prop.get("property_id") or _prop.get("project_slug") or "?"
                    logger.info(f"[OrdinalResolver] text='{text}' â†’ index={idx} â†’ property_id={_pid}")
                    return idx
                else:
                    logger.info(f"[OrdinalResolver] text='{text}' â†’ index={idx} â†’ OUT_OF_BOUNDS (list size: {len(self._ordinal_results)})")
                    return -1  # Signal out of bounds for graceful handling

        # Numeric patterns require an explicit ordinal cue; bare "2 BHK" or price
        # values must never be treated as shortlist ordinals.
        for _numeric_role in self._extract_numeric_roles(_t):
            if _numeric_role.get("role") != "ordinal":
                continue
            try:
                _num = int(_numeric_role["value"])
                # Convert to 0-based index
                idx = _num - 1
                if 0 <= idx < len(_ordinal_source):
                    _prop = _ordinal_source[idx]
                    _pid = _prop.get("property_id") or _prop.get("project_slug") or "?"
                    logger.info(f"[OrdinalResolver] text='{text}' â†’ numeric={_num} â†’ index={idx} â†’ property_id={_pid}")
                    return idx
                else:
                    logger.info(f"[OrdinalResolver] text='{text}' â†’ numeric={_num} â†’ index={idx} â†’ OUT_OF_BOUNDS (list size: {len(self._ordinal_results)})")
                    return -1  # Signal out of bounds
            except (ValueError, IndexError):
                pass

        return None

    def _resolve_recent_reference(self, text: str) -> int | None:
        """
        Resolve 'last one', 'that one', 'this one', 'the one you just showed' references.

        Rules:
        - If only 1 property was just mentioned â†’ resolve to that
        - Else fallback to last item in _ordinal_results
        """
        _ordinal_source = (
            self._current_shortlist_page_results
            if self._has_shortlist_page_context()
            else self._ordinal_results
        )
        if not text or not _ordinal_source:
            return None

        _t = text.lower().strip()
        _RECENT_PATTERNS = [
            'last one', 'the last one', 'that one', 'this one',
            'the one you just showed', 'the one you just mentioned',
            'that property', 'this property', 'the recent one',
        ]

        if not any(p in _t for p in _RECENT_PATTERNS):
            return None

        # Check if this was a single-property context
        _single_property_indicators = [
            'only one', 'just one', 'single', 'one property',
        ]
        _is_single_context = any(ind in _t for ind in _single_property_indicators)

        if _is_single_context and len(_ordinal_source) >= 1:
            idx = 0  # Only one property shown, so it's the first/only
            _prop = _ordinal_source[idx]
            _pid = _prop.get("property_id") or _prop.get("project_slug") or "?"
            logger.info(f"[ReferenceResolver] type=recent,single_context â†’ index={idx} â†’ property_id={_pid}")
            return idx

        # Fallback to last item
        idx = len(_ordinal_source) - 1
        _prop = _ordinal_source[idx]
        _pid = _prop.get("property_id") or _prop.get("project_slug") or "?"
        logger.info(f"[ReferenceResolver] type=recent,last_fallback â†’ index={idx} â†’ property_id={_pid}")
        return idx

    def _resolve_ordinal_with_bounds_check(self, text: str) -> dict | None:
        """
        High-level resolver that checks bounds and returns property or error response.
        Returns property dict if valid, None if no ordinal detected,
        or raises ValueError with message for out-of-bounds.
        """
        # Try ordinal first
        idx = self._resolve_ordinal_reference(text)
        if idx is None:
            # Try recent reference
            idx = self._resolve_recent_reference(text)

        if idx is None:
            return None  # No ordinal/recent reference detected

        if idx == -1 or idx >= len(self._ordinal_results):
            _total = len(self._ordinal_results)
            _msg = f"I don't have that many properties yet, I've shown you {_total} so far."
            logger.info(f"[OrdinalResolver] BOUNDS_EXCEEDED: text='{text}' â†’ list_size={_total}")
            raise ValueError(_msg)

        return self._ordinal_results[idx]

    def _update_lead_score(self, function_name: str, result: dict) -> None:
        """Recompute lead score after every tool call and persist in session memory.

        Scoring logic:
          hot  - callback/site-visit tool triggered, OR property details viewed
                 with budget + location already known
          warm - search completed with both budget and location confirmed
          cold - early stage: only city known, or no search yet
        """
        gs = self._gathered_search
        _has_budget   = bool(gs.get("min_price") or gs.get("max_price"))
        _has_location = bool(gs.get("location"))
        _callback_hot = bool(
            _CALLBACK_TOOL_RE.search(function_name) or _VISIT_TOOL_RE.search(function_name)
        ) and result.get("success", False)
        _detail_viewed = bool(
            function_name == "get_property_details" and result.get("success", False)
        )
        _search_done   = bool(
            function_name == "search_properties"
            and result.get("success", False)
            and result.get("data")
        )

        if _callback_hot or (_detail_viewed and _has_budget):
            new_score = "hot"
        elif _search_done and _has_budget and _has_location:
            new_score = "hot"
        elif _search_done and _has_budget:
            new_score = "warm"
        elif gs.get("city"):
            new_score = "warm" if _has_budget else "cold"
        else:
            new_score = "cold"

        # Score can only go up during a call (hot > warm > cold)
        _rank = {"cold": 0, "warm": 1, "hot": 2}
        if _rank.get(new_score, 0) > _rank.get(self._lead_score, 0):
            logger.info(f"[LeadScore] {self._lead_score} â†’ {new_score} (tool={function_name})")
            self._lead_score = new_score

    def build_tool_schemas(self):
        """Return a ToolsSchema for all endpoints across all integrations, or NOT_GIVEN if none.

        Supports two optional endpoint config fields:
          - llm_parameters[*].hidden (bool): exclude the param from the LLM schema entirely.
            The default value still fills in via _execute_endpoint. Use for utility params
            like 'limit' that the LLM should never guess.
          - gather_before_call (list of {name, description}): these are injected as REQUIRED
            parameters in the FunctionSchema. The LLM *cannot* call the tool without providing
            all of them - forcing it to ask the user for each one before searching.
        """
        function_schemas = []
        for integration in self.integrations:
            for endpoint in integration.get("endpoints", []):
                llm_params = endpoint.get("llm_parameters", [])

                sensitive_names = {
                    "firstname",
                    "lastname",
                    "name",
                    "fullname",
                    "contactname",
                    "sendername",
                    "mobile",
                    "mobilenumber",
                    "phone",
                    "phonenumber",
                    "msisdn",
                    "sendermobile",
                }

                # Exclude params marked hidden - LLM never sees them; defaults still apply
                visible_params = [p for p in llm_params if not p.get("hidden", False)]
                properties = {
                    p["name"]: {
                        "type": p.get("type", "string"),
                        "description": p.get("description", p["name"]),
                    }
                    for p in visible_params
                }
                required = [
                    p["name"]
                    for p in visible_params
                    if p.get("required") and str(p.get("name", "")).strip().lower() not in sensitive_names
                ]

                # gather_before_call items are intentionally NOT added to the tool schema.
                # Adding them causes two problems with Groq:
                #   1. If marked required: Groq rejects the call before our handler runs
                #   2. If optional: smaller models (8B) generate malformed calls with 9+ params
                # The system prompt already instructs the LLM to collect these values through
                # conversation. Validation (_validate_gathered_values) runs in the handler for
                # items that ARE in llm_parameters (e.g. firstName on submit_callback).

                # Deduplicate: skip if same endpoint id already seen
                if any(fs.name == endpoint["id"] for fs in function_schemas):
                    logger.debug(f"[ToolSchema] Deduplicated: {endpoint['id']}")
                    continue
                function_schemas.append(FunctionSchema(
                    name=endpoint["id"],
                    description=endpoint.get("description", endpoint["id"]),
                    properties=properties,
                    required=required,
                ))
        return ToolsSchema(standard_tools=function_schemas) if function_schemas else NOT_GIVEN

    def register_handlers(self, llm):
        """Register a function handler for every endpoint with the LLM service."""
        _registered_ids = set()
        for integration in self.integrations:
            for endpoint in integration.get("endpoints", []):
                _eid = endpoint["id"]
                if _eid in _registered_ids:
                    logger.debug(f"[Integration] Deduplicated handler: {_eid}")
                    continue
                _registered_ids.add(_eid)
                handler = self._make_handler(endpoint)
                llm.register_function(_eid, handler)
                logger.debug(f"   [Integration] Registered tool: {_eid} ({integration.get('slug', '?')})")

    def _make_handler(self, endpoint: dict):
        """Closure - captures endpoint config, returns async handler for the LLM framework."""
        # Track in-flight tool calls to prevent duplicates
        if not hasattr(self, '_in_flight_calls'):
            self._in_flight_calls = {}

        async def handler(params):
            merged_params = None
            direct_spoken_result = None
            goto_process_result = False
            result = None
            # Unpack FunctionCallParams for compatibility with existing code
            function_name = params.function_name
            tool_call_id = params.tool_call_id
            arguments = params.arguments
            llm = params.llm
            context = params.context
            result_callback = params.result_callback
            tool_turn_id = int(global_state_manager.turn_id or 0)
            _latest_user_raw = _latest_user_message(getattr(context, "messages", []) or [])
            _latest_user_amounts = _parse_inr_amounts(
                _latest_user_raw,
                allow_bare_rupees=(
                    self._zero_result_followup_mode == "awaiting_budget_value"
                    or self._pending_gather_field == "budget"
                ),
            )
            _latest_user_budget_flexible = _is_flexible_budget_text(_latest_user_raw)
            _zero_result_adjust_budget = bool(
                _ZERO_RESULT_ADJUST_BUDGET_RE.search(_latest_user_raw or "")
            )
            _zero_result_other_areas = bool(
                _ZERO_RESULT_OTHER_AREAS_RE.search(_latest_user_raw or "")
            )
            _budget_availability_question = bool(self.is_area_price_summary_request(_latest_user_raw))
            if _budget_availability_question:
                arguments = {**arguments, "_block_llm_budget_range_fallback": True}

            if function_name == "areas_by_budget" and self.is_area_price_summary_request(_latest_user_raw):
                logger.warning(
                    "[PriceSummary] Rewriting mistaken areas_by_budget call to search_properties"
                )
                function_name = "search_properties"
                arguments = {
                    **arguments,
                    "city": self._gathered_search.get("city") or arguments.get("city") or "Chennai",
                    "location": self._gathered_search.get("location") or arguments.get("location") or "",
                    "property_type": (
                        self._gathered_search.get("property_type")
                        or arguments.get("property_type")
                        or "Apartments"
                    ),
                    "min_price": 0,
                    "max_price": 50_000_000,
                    "result_count": 20,
                    "sort_preference": "price_asc",
                }
                if self._gathered_search.get("bedrooms"):
                    arguments["bedrooms"] = self._gathered_search["bedrooms"]
                arguments.pop("budget_range", None)
                self._zero_result_route_lock = "search_properties"
                self._zero_result_followup_mode = None
                self._gathered_search.pop("_citywide_search", None)
                self._gathered_search.pop("_exploring_alternatives", None)

            if self._zero_result_followup_mode == "awaiting_budget_or_area_choice":
                if _zero_result_adjust_budget and not _latest_user_amounts and not _latest_user_budget_flexible:
                    self._zero_result_followup_mode = "awaiting_budget_value"
                    self._zero_result_route_lock = "search_properties"
                    self._gathered_search.pop("_exploring_alternatives", None)
                    _origin_loc = str(
                        self._gathered_search.get("_zero_result_origin_location")
                        or self._gathered_search.get("_origin_location")
                        or self._gathered_search.get("location")
                        or ""
                    ).strip()
                    if _origin_loc:
                        self._gathered_search["location"] = _origin_loc
                    self._gathered_search.pop("_citywide_search", None)
                    logger.info("[ZeroResults] User chose budget adjustment for current locality")
                elif _zero_result_other_areas:
                    self._zero_result_followup_mode = "awaiting_alternative_areas"
                    self._zero_result_route_lock = "areas_by_budget"
                    self._gathered_search["_exploring_alternatives"] = True
                    self._gathered_search["_citywide_search"] = True
                    _origin_loc = str(
                        self._gathered_search.get("_zero_result_origin_location")
                        or self._gathered_search.get("location")
                        or ""
                    ).strip()
                    if _origin_loc:
                        self._gathered_search["_origin_location"] = _origin_loc
                    self._gathered_search.pop("location", None)
                    logger.info("[ZeroResults] User chose alternative-area exploration")

            if (
                function_name == "areas_by_budget"
                and self._zero_result_followup_mode == "awaiting_budget_value"
                and (_latest_user_amounts or _latest_user_budget_flexible)
            ):
                logger.warning(
                    "[ZeroResults] Rewriting mistaken areas_by_budget call to search_properties "
                    "for same-locality budget adjustment"
                )
                function_name = "search_properties"
                arguments = {
                    **arguments,
                    "city": (
                        self._gathered_search.get("_zero_result_origin_city")
                        or self._gathered_search.get("city")
                        or "Chennai"
                    ),
                    "location": (
                        self._gathered_search.get("_zero_result_origin_location")
                        or self._gathered_search.get("location")
                        or ""
                    ),
                    "property_type": (
                        self._gathered_search.get("_zero_result_origin_property_type")
                        or self._gathered_search.get("property_type")
                        or arguments.get("property_type")
                        or ""
                    ),
                }
                arguments.pop("budget_range", None)

            # â”€â”€ Deduplication: skip if same call is already in progress â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
            if function_name == "get_property_details":
                _requested_detail_target = str(
                    arguments.get("property_id")
                    or arguments.get("project_slug")
                    or arguments.get("slug")
                    or ""
                ).strip()
                if (
                    self._property_detail_tool_turn_id == tool_turn_id
                    and self._property_detail_tool_turn_property
                    and _requested_detail_target != self._property_detail_tool_turn_property
                ):
                    logger.warning(
                        f"[ToolGuard] Suppressed second get_property_details in same turn: "
                        f"first={self._property_detail_tool_turn_property!r} second={_requested_detail_target!r}"
                    )
                    await result_callback(
                        json.dumps({
                            "success": True,
                            "duplicate_suppressed": True,
                            "tool": function_name,
                            "message": "Only one property detail request is allowed per user turn.",
                        }, ensure_ascii=False),
                        properties=FunctionCallResultProperties(run_llm=False)
                    )
                    return
                self._property_detail_tool_turn_id = tool_turn_id
                self._property_detail_tool_turn_property = _requested_detail_target
            if function_name == "submit_callback":
                _callback_signature = "|".join([
                    str(arguments.get("propertyName") or arguments.get("name") or "").strip().lower(),
                    str(arguments.get("city") or self._gathered_search.get("city") or "").strip().lower(),
                ])
                if self._submit_callback_tool_turn_id == tool_turn_id:
                    logger.warning(
                        f"[ToolGuard] Suppressed duplicate submit_callback in same turn: "
                        f"first={self._submit_callback_tool_signature!r} second={_callback_signature!r}"
                    )
                    await result_callback(
                        json.dumps({
                            "success": True,
                            "duplicate_suppressed": True,
                            "tool": function_name,
                            "message": "Callback already submitted for this user turn.",
                        }, ensure_ascii=False),
                        properties=FunctionCallResultProperties(run_llm=False)
                    )
                    return
                self._submit_callback_tool_turn_id = tool_turn_id
                self._submit_callback_tool_signature = _callback_signature

            _alternative_choice_location = _match_alternative_area_choice(
                _latest_user_raw,
                self._gathered_search,
            )
            if (
                _alternative_choice_location
                and function_name in {"search_properties", "areas_by_budget"}
                and self._zero_result_followup_mode in {
                    "awaiting_alternative_areas",
                    "awaiting_alternative_area_choice",
                }
            ):
                function_name = "search_properties"
                arguments = {
                    **arguments,
                    "city": arguments.get("city") or self._gathered_search.get("city") or "Chennai",
                    "property_type": (
                        arguments.get("property_type")
                        or self._gathered_search.get("property_type")
                        or "Plots"
                    ),
                    "location": _alternative_choice_location,
                    "min_price": arguments.get("min_price") or self._gathered_search.get("min_price"),
                    "max_price": arguments.get("max_price") or self._gathered_search.get("max_price"),
                    "result_count": arguments.get("result_count") or self._gathered_search.get("result_count") or "3",
                }
                arguments.pop("area", None)
                arguments.pop("locality", None)
                self._gathered_search["location"] = _alternative_choice_location
                self._gathered_search.pop("_citywide_search", None)
                self._gathered_search.pop("_exploring_alternatives", None)
                self._zero_result_followup_mode = None
                self._zero_result_route_lock = None
                logger.info(
                    f"[AreasByBudget] Follow-up selected alternative area "
                    f"'{_alternative_choice_location}' from speech={_latest_user_raw!r}"
                )

            call_key = f"{function_name}:{json.dumps(arguments, sort_keys=True)}"
            if call_key in self._in_flight_calls:
                logger.info(f"[Tool] DUPLICATE call detected for {function_name}, suppressing duplicate execution")
                await result_callback(
                    json.dumps({
                        "success": True,
                        "duplicate_suppressed": True,
                        "tool": function_name,
                    }, ensure_ascii=False),
                    properties=FunctionCallResultProperties(run_llm=False)
                )
                logger.info(f"[TTSGuard] duplicate call suppressed run_llm=True â†’ run_llm=False")
                return

            logger.info(f"[Tool] {function_name} called with args={arguments}")
            self._begin_terminal_tool_response(function_name)
            # Mark this call as in-flight
            call_future = asyncio.Future()
            self._in_flight_calls[call_key] = call_future

            def _is_stale_tool_turn() -> bool:
                if not tool_turn_id:
                    return False
                return tool_turn_id != int(global_state_manager.turn_id or 0)

            _interim_wait_task: asyncio.Task | None = None
            _interim_wait_emitted = False

            async def _emit_interim_wait_message() -> None:
                nonlocal _interim_wait_emitted
                if function_name not in {"search_properties", "get_property_details"}:
                    return
                _trace = self._latency_trace_ref[0] if self._latency_trace_ref else {}
                if _trace.get("cache_path_hit") or _trace.get("tool_skipped_for_cached_fact"):
                    return
                await asyncio.sleep(SEARCH_WAIT_INTERIM_THRESHOLD_MS / 1000.0)
                if _is_stale_tool_turn() or call_key not in self._in_flight_calls:
                    return
                if self._turn_llm_fired:
                    return
                if _trace.get("response_mode") in {"deterministic_direct", "deterministic_tool_result", "repair_replay"}:
                    return
                _trace["response_mode"] = "tool_wait_filler"
                _text = (
                    "I'm pulling up the matching properties now."
                    if function_name == "search_properties"
                    else "One moment while I check that for you."
                )
                try:
                    global_state_manager.begin_assistant_output(synthetic=True, text=_text)
                    global_state_manager.remember_synthetic_message(_text)
                    global_state_manager.note_synthetic_prompt_triggered(_text)
                    await llm.push_frame(LLMFullResponseStartFrame(), FrameDirection.DOWNSTREAM)
                    await llm.push_frame(LLMTextFrame(_text), FrameDirection.DOWNSTREAM)
                    await llm.push_frame(LLMFullResponseEndFrame(), FrameDirection.DOWNSTREAM)
                    _interim_wait_emitted = True
                    logger.info(f"[InterimWait] Emitted tool-wait filler for {function_name}")
                except Exception as _interim_err:
                    logger.warning(f"[InterimWait] Failed to emit filler for {function_name}: {_interim_err}")

            async def _cancel_interim_wait_message(reason: str) -> None:
                nonlocal _interim_wait_task
                if _interim_wait_task and not _interim_wait_task.done():
                    _interim_wait_task.cancel()
                    try:
                        await _interim_wait_task
                    except asyncio.CancelledError:
                        pass
                    logger.info(f"[InterimWait] Suppressed filler reason={reason} function={function_name}")
                _interim_wait_task = None

            async def _finish_early(response_payload):
                # NOTE: _finish_early is for early returns (gathering/redirects), NOT actual tool results.
                # We do NOT set _turn_llm_fired here - that's only for actual tool completion.
                # The ToolGuard at the end of the handler manages _turn_llm_fired for real results.
                await _cancel_interim_wait_message("finish_early")
                await result_callback(
                    response_payload,
                    properties=FunctionCallResultProperties(run_llm=True)
                )
                if call_key in self._in_flight_calls:
                    future = self._in_flight_calls[call_key]
                    if not future.done():
                        future.set_result(response_payload)
                    del self._in_flight_calls[call_key]

            if (
                function_name == "search_properties"
                and self._zero_result_route_lock == "areas_by_budget"
                and self._zero_result_followup_mode in {"awaiting_alternative_areas", "awaiting_alternative_area_choice"}
            ):
                _explicit_loc_turn = bool(
                    str(arguments.get("location") or "").strip()
                    or str(arguments.get("area") or "").strip()
                    or str(arguments.get("locality") or "").strip()
                )
                if not _explicit_loc_turn:
                    logger.info(
                        "[ZeroResults] Blocking same-turn search_properties during alternative-area exploration"
                    )
                    await _finish_early(json.dumps({
                        "success": False,
                        "need_gather": True,
                        "field": "location",
                        "instruction": "Please pick one of the suggested alternative areas.",
                        "response_format": (
                            "Ask the user which of the suggested alternative areas they want to explore. "
                            "Do NOT search the original locality again."
                        ),
                    }, ensure_ascii=False))
                    return

            if (
                function_name in {"areas_by_budget", "search_properties"}
                and self._zero_result_followup_mode == "awaiting_budget_value"
                and not _latest_user_amounts
                and not _latest_user_budget_flexible
            ):
                logger.info("[ZeroResults] Budget-adjustment branch still awaiting fresh amount")
                await _finish_early(json.dumps({
                    "success": False,
                    "need_gather": True,
                    "field": "budget",
                    "instruction": "Roughly, under 1 crore, 1 to 2 crore, or above 2 crore?",
                    "response_format": (
                        "Ask ONLY this budget question. Do NOT mention other areas or "
                        "location choices. Wait for the user's budget answer."
                    ),
                }, ensure_ascii=False))
                return

            async def _finish_stale(payload) -> None:
                await _cancel_interim_wait_message("finish_stale")
                logger.info(
                    f"[ToolGuard] Suppressing stale tool follow-up for {function_name} "
                    f"(tool_turn={tool_turn_id} current_turn={global_state_manager.turn_id})"
                )
                self.clear_terminal_tool_response_flags("stale_tool_turn")
                if isinstance(payload, str):
                    response_payload = payload
                else:
                    response_payload = _compress_tool_result_for_context(payload, function_name)
                await result_callback(
                    response_payload,
                    properties=FunctionCallResultProperties(run_llm=False)
                )
                if call_key in self._in_flight_calls:
                    future = self._in_flight_calls[call_key]
                    if not future.done():
                        future.set_result(response_payload)
                    del self._in_flight_calls[call_key]

            async def _speak_direct_response(spoken_text: str, payload) -> None:
                """Bypass the LLM and send a deterministic spoken response downstream."""
                await _cancel_interim_wait_message("direct_response")
                if not spoken_text:
                    await _finish_early(
                        payload if isinstance(payload, str) else json.dumps(payload, ensure_ascii=False)
                    )
                    return
                response_payload = payload if isinstance(payload, str) else json.dumps(payload, ensure_ascii=False)
                if _is_stale_tool_turn():
                    logger.info(
                        f"[DirectSpeech] Skipping stale deterministic narration for {function_name} "
                        f"(tool_turn={tool_turn_id} current_turn={global_state_manager.turn_id})"
                    )
                    self.clear_terminal_tool_response_flags("stale_direct_speech")
                    if isinstance(payload, str):
                        response_payload = payload
                    else:
                        response_payload = _compress_tool_result_for_context(payload, function_name)
                    await result_callback(
                        response_payload,
                        properties=FunctionCallResultProperties(run_llm=False)
                    )
                    if call_key in self._in_flight_calls:
                        future = self._in_flight_calls[call_key]
                        if not future.done():
                            future.set_result(response_payload)
                        del self._in_flight_calls[call_key]
                    return
                self._turn_llm_fired = True
                self._latency_trace_ref[0]["response_mode"] = "deterministic_tool_result"
                self._latency_trace_ref[0]["path_label"] = "tool_direct_narration"
                self._mark_terminal_tool_result_ready(function_name, run_llm=False)
                if not self._latency_trace_ref[0].get("router_decision_at"):
                    _router_now = time.time()
                    self._latency_trace_ref[0]["router_decision_at"] = _router_now
                    _turn_start = self._latency_trace_ref[0].get("turn_start")
                    if _turn_start:
                        self._latency_trace_ref[0]["router_ms"] = int((_router_now - _turn_start) * 1000)
                await result_callback(
                    response_payload,
                    properties=FunctionCallResultProperties(run_llm=False)
                )
                try:
                    context.messages.append({"role": "assistant", "content": spoken_text})
                except Exception:
                    pass
                try:
                    await llm.push_frame(LLMFullResponseStartFrame(), FrameDirection.DOWNSTREAM)
                    await llm.push_frame(LLMTextFrame(spoken_text), FrameDirection.DOWNSTREAM)
                    await llm.push_frame(LLMFullResponseEndFrame(), FrameDirection.DOWNSTREAM)
                except Exception as _push_err:
                    logger.warning(f"[DirectSpeech] Frame push failed: {_push_err}")
                    self.clear_terminal_tool_response_flags("direct_speech_push_failed")
                if call_key in self._in_flight_calls:
                    future = self._in_flight_calls[call_key]
                    if not future.done():
                        future.set_result(response_payload)
                    del self._in_flight_calls[call_key]

            _interim_wait_task: asyncio.Task | None = None
            _interim_wait_emitted = False

            async def _emit_interim_wait_message() -> None:
                nonlocal _interim_wait_emitted
                if function_name not in {"search_properties", "get_property_details"}:
                    return
                _trace = self._latency_trace_ref[0] if self._latency_trace_ref else {}
                if _trace.get("cache_path_hit") or _trace.get("tool_skipped_for_cached_fact"):
                    return
                await asyncio.sleep(SEARCH_WAIT_INTERIM_THRESHOLD_MS / 1000.0)
                if _is_stale_tool_turn() or call_key not in self._in_flight_calls:
                    return
                if self._turn_llm_fired:
                    return
                if _trace.get("response_mode") in {"deterministic_direct", "deterministic_tool_result", "repair_replay"}:
                    return
                _trace["response_mode"] = "tool_wait_filler"
                _text = (
                    "I'm pulling up the matching properties now."
                    if function_name == "search_properties"
                    else "One moment while I check that for you."
                )
                try:
                    global_state_manager.begin_assistant_output(synthetic=True, text=_text)
                    global_state_manager.remember_synthetic_message(_text)
                    global_state_manager.note_synthetic_prompt_triggered(_text)
                    await llm.push_frame(LLMFullResponseStartFrame(), FrameDirection.DOWNSTREAM)
                    await llm.push_frame(LLMTextFrame(_text), FrameDirection.DOWNSTREAM)
                    await llm.push_frame(LLMFullResponseEndFrame(), FrameDirection.DOWNSTREAM)
                    _interim_wait_emitted = True
                    logger.info(f"[InterimWait] Emitted tool-wait filler for {function_name}")
                except Exception as _interim_err:
                    logger.warning(f"[InterimWait] Failed to emit filler for {function_name}: {_interim_err}")

            async def _cancel_interim_wait_message(reason: str) -> None:
                nonlocal _interim_wait_task
                if _interim_wait_task and not _interim_wait_task.done():
                    _interim_wait_task.cancel()
                    try:
                        await _interim_wait_task
                    except asyncio.CancelledError:
                        pass
                    logger.info(f"[InterimWait] Suppressed filler reason={reason} function={function_name}")
                _interim_wait_task = None

            if function_name in {"search_properties", "get_property_details"}:
                _interim_wait_task = asyncio.create_task(_emit_interim_wait_message())

            # â”€â”€ Flatten nested args â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
            # Groq Llama sometimes wraps all parameters under a "properties" key:
            #   {"properties": {"city": "Chennai", "bedrooms": 3, ...}}
            # Flatten this before any processing so downstream code sees the real keys.
            if isinstance(arguments.get("properties"), dict):
                _nested = arguments["properties"]
                arguments = {k: v for k, v in arguments.items() if k != "properties"}
                arguments = {**_nested, **arguments}  # outer keys (if any) take precedence
                logger.info(f"[Tool] Flattened nested 'properties' args â†’ {list(arguments.keys())}")

            _prune_old_tool_messages(context)

            _sensitive_keys = {
                "firstname",
                "lastname",
                "name",
                "fullname",
                "contactname",
                "sendername",
                "mobile",
                "mobilenumber",
                "mobileno",       # JLL site-visit / booking API field
                "phone",
                "phonenumber",
                "msisdn",
                "sendermobile",
            }

            def _fill_sensitive_args(_args: dict) -> dict:
                if not isinstance(_args, dict):
                    return {}
                sender_mobile = str(self.call_context.get("senderMobile") or "").strip()
                sender_name = str(self.call_context.get("senderName") or "").strip()
                is_site_visit_tool = function_name == "schedule_site_visit"
                first_name = (
                    sender_name.split()[0]
                    if sender_name
                    else ("" if is_site_visit_tool else "Customer")
                )

                patched = dict(_args)
                for p in endpoint.get("llm_parameters", []):
                    key = str(p.get("name", "")).strip()
                    if not key:
                        continue
                    kl = key.lower()
                    if kl not in _sensitive_keys:
                        continue
                    if patched.get(key):
                        continue
                    if kl in {"firstname"}:
                        patched[key] = first_name
                    elif kl in {"sendername", "name", "fullname", "contactname"}:
                        patched[key] = sender_name or ("" if is_site_visit_tool else "Customer")
                    elif kl in {"sendermobile", "mobile", "mobilenumber", "mobileno", "phone", "phonenumber", "msisdn"}:
                        patched[key] = sender_mobile
                return patched

            def _extract_first_name_from_recent_context() -> str:
                messages = list(getattr(context, "messages", []) or [])
                start_idx = max(0, len(messages) - 12)
                for idx in range(len(messages) - 1, start_idx - 1, -1):
                    msg = messages[idx]
                    if msg.get("role") != "user":
                        continue
                    content = str(msg.get("content") or "")
                    prior_assistant_text = " ".join(
                        str(prev.get("content") or "")
                        for prev in messages[max(0, idx - 3):idx]
                        if prev.get("role") == "assistant"
                    )
                    asked_name_recently = bool(
                        re.search(r"\b(first\s+name|your\s+name|name)\b", prior_assistant_text, re.IGNORECASE)
                    )
                    name = _extract_caller_first_name_from_text(
                        content,
                        allow_bare=asked_name_recently,
                    )
                    if name:
                        return name
                return ""

            def _extract_site_visit_datetime_from_recent_context() -> tuple[str, bool]:
                messages = list(getattr(context, "messages", []) or [])
                user_texts = [
                    str(msg.get("content") or "")
                    for msg in messages[-16:]
                    if msg.get("role") == "user" and str(msg.get("content") or "").strip()
                ]
                today = _dt.date.today()
                visit_date: _dt.date | None = None
                has_explicit_time = False
                hour: int | None = None
                minute = 0

                for user_text in reversed(user_texts):
                    lower = user_text.lower()
                    if "day after tomorrow" in lower:
                        visit_date = today + _dt.timedelta(days=2)
                        break
                    if "tomorrow" in lower:
                        visit_date = today + _dt.timedelta(days=1)
                        break
                    if "today" in lower:
                        visit_date = today
                        break

                for user_text in reversed(user_texts):
                    lower = user_text.lower()
                    match = re.search(
                        r"\b(\d{1,2}):(\d{2})\s*(am|pm)?\b|\b(\d{1,2})\s*(o'?clock|am|pm)\b",
                        lower,
                        re.IGNORECASE,
                    )
                    if not match:
                        continue
                    candidate_hour = int(match.group(1) or match.group(4))
                    if candidate_hour > 24:
                        continue
                    candidate_minute = int(match.group(2) or 0)
                    if candidate_minute > 59:
                        continue
                    suffix = (match.group(3) or match.group(5) or "").lower()
                    if "clock" in suffix:
                        suffix = ""
                    if suffix == "pm" and candidate_hour < 12:
                        candidate_hour += 12
                    elif suffix == "am" and candidate_hour == 12:
                        candidate_hour = 0
                    hour = candidate_hour
                    minute = candidate_minute
                    has_explicit_time = True
                    break

                if visit_date and has_explicit_time and hour is not None:
                    return (
                        f"{visit_date.isoformat()}T{hour:02d}:{minute:02d}:00.000Z",
                        True,
                    )
                return "", has_explicit_time

            if function_name == "schedule_site_visit" and not str(self.call_context.get("senderName") or "").strip():
                _context_first_name = _extract_first_name_from_recent_context()
                if _context_first_name:
                    self.call_context["senderName"] = _context_first_name
                    arguments.setdefault("senderName", _context_first_name)
                    arguments.setdefault("firstName", _context_first_name)
                    logger.info(
                        f"[SiteVisit] recovered caller firstName from conversation: {_context_first_name!r}"
                    )
            if function_name == "schedule_site_visit":
                _context_visit_date, _has_explicit_visit_time = _extract_site_visit_datetime_from_recent_context()
                if _context_visit_date:
                    _date_keys = {
                        str(p.get("name") or "")
                        for p in endpoint.get("llm_parameters", [])
                        if str(p.get("name") or "").lower().replace("_", "").replace("-", "") in {
                            "preferreddate", "visitdate", "appointmentdate", "preferredvisitdate", "date", "visitingdate",
                        }
                    }
                    _date_key = next((key for key in _date_keys if key in arguments), None) or next(iter(_date_keys or {"visitDate"}))
                    arguments[_date_key] = _context_visit_date
                    logger.info(f"[SiteVisit] recovered visitDate from conversation: {_context_visit_date}")
                elif not _has_explicit_visit_time:
                    logger.info("[Tool] schedule_site_visit missing explicit visit time - asking before scheduling")
                    await _finish_early(json.dumps({
                        "status": "need_clarification",
                        "missing_fields": ["visitDate"],
                        "instruction": (
                            "Ask the user what time they prefer for the site visit. "
                            "Do not call schedule_site_visit yet."
                        ),
                    }, ensure_ascii=False))
                    return

            arguments = _fill_sensitive_args(arguments)
            _force_affordable_sort = False

            # â”€â”€ Mobile number guard for callback/site-visit endpoints â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
            # If the endpoint submits a phone number to an external API (submit_callback,
            # schedule_site_visit, etc.) and senderMobile is empty (e.g. WebRTC test mode),
            # ask the user for their phone number before proceeding. This prevents 400 errors
            # from the JLL API which requires mobileNo to be a valid 10-digit number.
            _mobile_param_keys = {"sendermobile", "mobile", "mobilenumber", "mobileno", "phone", "phonenumber", "msisdn"}
            _has_mobile_param = any(
                str(p.get("name", "")).strip().lower() in _mobile_param_keys
                for p in endpoint.get("llm_parameters", [])
            )
            if _has_mobile_param:
                # Check the resolved value (after _fill_sensitive_args patching)
                _resolved_mobile = ""
                for p in endpoint.get("llm_parameters", []):
                    _k = str(p.get("name", "")).strip()
                    if _k.lower() in _mobile_param_keys:
                        _resolved_mobile = str(arguments.get(_k) or "").strip()
                        break
                if len(_resolved_mobile) < 7:
                    logger.warning(
                        f"[Tool] {function_name}: mobile number empty/too short "
                        f"(senderMobile={self.call_context.get('senderMobile')!r}) - graceful close"
                    )
                    await _finish_early(json.dumps({
                        "success": True,
                        "status": "completed",
                        "instruction": "Say EXACTLY: 'Your request has been noted. One of our JLL Homes property specialists will reach out to you shortly. Thank you for calling JLL Homes, have a great day.' Do NOT ask for phone number.",
                    }, ensure_ascii=False))
                    return

            if function_name == "schedule_site_visit":
                _resolved_first_name = str(
                    arguments.get("firstName")
                    or arguments.get("senderName")
                    or self.call_context.get("senderName")
                    or ""
                ).strip()
                if not _resolved_first_name or _resolved_first_name.lower() == "customer":
                    logger.info("[Tool] schedule_site_visit missing caller firstName - asking before scheduling")
                    await _finish_early(json.dumps({
                        "status": "need_clarification",
                        "missing_fields": ["firstName"],
                        "instruction": (
                            "Ask the user for their first name before scheduling the site visit. "
                            "Do not call schedule_site_visit yet."
                        ),
                    }, ensure_ascii=False))
                    return

            # â”€â”€ Detail-request redirect â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
            # When the LLM calls search_properties but the user is actually asking for
            # details on a specific property (ordinal or name), redirect it to use
            # get_property_details instead. This prevents unnecessary re-searches and the
            # "Would you like me to search again?" loop.
            #
            # IMPORTANT: Only check the LAST 1 user message to avoid false positives from
            # earlier turns (e.g. "two" in "find me two more" from a previous message
            # triggering on a later "find villas" request). Also exclude new-search keywords
            # so "find me two more apartments" / "find villas" are NOT caught as detail requests.
            if function_name == "search_properties" and self._slug_cache:
                _last_user = next(
                    (m.get("content", "") for m in reversed(getattr(context, "messages", []))
                     if m.get("role") == "user"),
                    ""
                ).lower().strip()

                # Intent: user wants details on a specific property
                _DETAIL_RE = re.compile(
                    r'\btell\s+me\s+(more\s+)?(about|regarding)\b|'
                    r'\bwhat\s+(is|are|about)\b|'
                    r'\bdetails?\b|\binfo\b|\binformation\b|'
                    r'\bmore\s+about\b|\bexplain\b|\bdescribe\b',
                    re.IGNORECASE,
                )
                # Ordinal: "the first one", "first", "second", "third" - NOT bare "one/two/three"
                # because those appear in "find me two more", "show three results", etc.
                _ORDINAL_RE = re.compile(
                    r'\b(first|second|third|fourth|fifth|1st|2nd|3rd|4th|5th|'
                    r'number\s*[1-5]|the\s+first|the\s+second|the\s+third|'
                    r'that\s+one|this\s+one|the\s+one)\b',
                    re.IGNORECASE,
                )
                # New-search keywords: if present, this is a NEW SEARCH, not a detail request
                _NEW_SEARCH_RE = re.compile(
                    r'\b(find|search|look\s+for|show|get\s+me|fetch|'
                    r'villa|villas|apartment|apartments|flat|flats|plot|plots|'
                    r'more\s+properties|more\s+options|more\s+results|'
                    r'different|another|other|nearby|near|next\s+page|'
                    r'same\s+location|in\s+\w+|area|location)\b',
                    re.IGNORECASE,
                )

                _has_detail   = bool(_DETAIL_RE.search(_last_user))
                _has_ordinal  = bool(_ORDINAL_RE.search(_last_user))
                _has_prop_name = any(
                    len(name) > 5 and name in _last_user
                    for name in self._name_to_slug
                )
                _is_new_search = bool(_NEW_SEARCH_RE.search(_last_user))

                if _has_detail and (_has_ordinal or _has_prop_name) and not _is_new_search:
                    _available = [
                        {"name": v.get("name", k), "property_id": k}
                        for k, v in self._slug_cache.items()
                    ]
                    logger.info(
                        f"[Tool] Detail-redirect: user wants property details "
                        f"(ordinal={_has_ordinal}, name_match={_has_prop_name}, "
                        f"new_search={_is_new_search}) - redirecting to get_property_details"
                    )
                    await _finish_early(json.dumps({
                        "success": False,
                        "action": "USE_GET_PROPERTY_DETAILS",
                        "message": (
                            "The user is asking for details on a specific property - "
                            "you MUST call get_property_details, NOT search_properties. "
                            "Pick the matching property_id from available_properties and call "
                            "get_property_details immediately. Do NOT say anything first."
                        ),
                        "available_properties": _available,
                    }, ensure_ascii=False))
                    return

            # â”€â”€ Gathering gate â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
            # Two strategies depending on whether the gather_before_call item is also
            # in llm_parameters (and therefore in the tool schema):
            #
            # A) Context-extraction (e.g. location, budget_range, result_count):
            #    Items NOT in the schema - the LLM can't reliably pass them in the call.
            #    We extract values directly from conversation history using regex/NLP so
            #    "seventy lakhs" â†’ max_price=7000000, "Central Chennai" â†’ location, etc.
            #    Only 'city' is truly required; everything else has a sensible default.
            #
            # B) Schema validation (e.g. firstName on submit_callback):
            #    Items IN the schema - the LLM passes them as arguments. We verify the
            #    value actually came from user speech to block hallucinated placeholders.
            _gather_items = endpoint.get("gather_before_call", [])
            if _gather_items:
                _param_names = {p["name"] for p in endpoint.get("llm_parameters", [])}
                _filtered_gather = [
                    i for i in _gather_items
                    if str(i.get("name", "")).strip().lower() not in _sensitive_keys
                ]
                _context_items = [i for i in _filtered_gather if i["name"] not in _param_names]
                _schema_items  = [i for i in _filtered_gather if i["name"] in _param_names]

                # Strategy A - context extraction
                if _context_items:
                    await self._ensure_catalog()
                    self._log_session_snapshot("before-tool-extraction")
                    # Pass session location for context-aware override detection
                    _session_loc = self._gathered_search.get("location")
                    merged_params, missing = _extract_search_context(
                        context,
                        arguments,
                        catalog=self._catalog,
                        current_location=_session_loc,
                        has_live_results=bool(getattr(self, "_has_live_results", False)),
                        pending_zero_result_mode=((getattr(self, "_zero_result_state", None) or {}).get("mode")),
                        confirmed_min_price=self._gathered_search.get("min_price"),
                        confirmed_max_price=self._gathered_search.get("max_price"),
                    )
                    if merged_params.pop("_clear_project_category", False):
                        self._gathered_search.pop("project_category", None)
                    if merged_params.pop("_clear_construction_state", False):
                        self._gathered_search.pop("construction_state", None)
                    if _budget_availability_question:
                        if merged_params.pop("min_price", None) is not None or merged_params.pop("max_price", None) is not None:
                            logger.info("[PriceSummary] Suppressed budget mutation from budget availability question")
                        arguments.pop("min_price", None)
                        arguments.pop("max_price", None)
                        arguments.pop("budget_range", None)
                    _block_budget_session_fallback = bool(
                        merged_params.pop("_block_budget_session_fallback", False)
                    )
                    _total_inventory_count_request = bool(
                        merged_params.pop("_total_inventory_count_request", False)
                        or _looks_like_total_inventory_count_request(_latest_user_raw)
                    )
                    if _total_inventory_count_request:
                        _block_budget_session_fallback = True
                        merged_params.pop("min_price", None)
                        merged_params.pop("max_price", None)
                        arguments.pop("min_price", None)
                        arguments.pop("max_price", None)
                        logger.info("[CountScope] Treating count request as total inventory; budget filters cleared")
                    merged_params.pop("_block_llm_budget_range_fallback", None)
                    _anaphoric_budget_reference = bool(
                        re.search(r"\b(my budget|within my budget|in my budget)\b", _latest_user_raw or "", re.IGNORECASE)
                    )
                    if (
                        _block_budget_session_fallback
                        and _anaphoric_budget_reference
                        and self.can_reuse_budget_anaphora(_latest_user_raw or "")
                    ):
                        _block_budget_session_fallback = False
                        logger.info("[BudgetConfirm] budget_confirm_reused_session_budget")
                    # â”€â”€ Session memory fallback for property_type and budget â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                    # When user wants to change location (e.g., after no_location_match),
                    # they might not mention property_type or budget again. Fall back to
                    # session memory to prevent re-asking for already-gathered fields.
                    if not merged_params.get("property_type") and self._gathered_search.get("property_type"):
                        merged_params["property_type"] = self._gathered_search["property_type"]
                        missing = [m for m in missing if m.get("name") != "property_type"]
                        logger.info(f"[Tool][SessionFallback] Restored property_type from session memory: {merged_params['property_type']}")
                    if not merged_params.get("project_category") and self._gathered_search.get("project_category"):
                        merged_params["project_category"] = self._gathered_search["project_category"]
                        logger.info(f"[Tool][SessionFallback] Restored project_category from session memory: {merged_params['project_category']}")
                    if not merged_params.get("construction_state") and self._gathered_search.get("construction_state"):
                        merged_params["construction_state"] = self._gathered_search["construction_state"]
                        logger.info(f"[Tool][SessionFallback] Restored construction_state from session memory: {merged_params['construction_state']}")
                    if merged_params.get("_budget_flexible"):
                        merged_params.pop("min_price", None)
                        merged_params.pop("max_price", None)
                        missing = [m for m in missing if m.get("name") != "budget"]
                        logger.info("[Tool][SessionFallback] Flexible budget active - keeping budget unconstrained")
                    elif (
                        not _block_budget_session_fallback
                        and not merged_params.get("min_price")
                        and not merged_params.get("max_price")
                    ):
                        if self._gathered_search.get("min_price") or self._gathered_search.get("max_price"):
                            merged_params["min_price"] = self._gathered_search.get("min_price")
                            merged_params["max_price"] = self._gathered_search.get("max_price")
                            missing = [m for m in missing if m.get("name") != "budget"]
                            logger.info(f"[Tool][SessionFallback] Restored budget from session memory: {merged_params.get('min_price')}-{merged_params.get('max_price')}")
                    elif _block_budget_session_fallback:
                        logger.info("[Tool][SessionFallback] Skipped stale budget restore because fresh budget confirmation is required")
                    if (
                        merged_params.get("min_price") is not None
                        or merged_params.get("max_price") is not None
                    ):
                        _nm, _nx = self._normalize_budget_pair(
                            merged_params.get("min_price"),
                            merged_params.get("max_price"),
                            source=f"{function_name}:merged_params",
                        )
                        if _nm is None:
                            merged_params.pop("min_price", None)
                        else:
                            merged_params["min_price"] = _nm
                        if _nx is None:
                            merged_params.pop("max_price", None)
                        else:
                            merged_params["max_price"] = _nx
                    # â”€â”€ Explicit LLM location override â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                    # The LLM may pass the location under a wrong key (area, locality,
                    # micro_market) which _extract_search_context() now normalises to
                    # `loc`.  But even when it uses the correct key "location", the
                    # speech-extraction fallback may still return a stale area from
                    # earlier in the conversation (e.g. "T Nagar" after user switched
                    # to "OMR").  If the LLM explicitly provided any location-type arg,
                    # trust it over the speech scan result.
                    _explicit_llm_loc = str(
                        arguments.get("location") or arguments.get("area") or
                        arguments.get("locality") or arguments.get("micro_market") or
                        arguments.get("microMarket") or ""
                    ).strip()
                    if _explicit_llm_loc and _explicit_llm_loc.lower() not in _CITY_CANONICAL:
                        _extracted_loc = merged_params.get("location", "")
                        if _extracted_loc.lower().strip() != _explicit_llm_loc.lower().strip():
                            logger.info(
                                f"[Tool][Location] LLM explicit '{_explicit_llm_loc}' "
                                f"overrides speech-extracted '{_extracted_loc}'"
                            )
                            merged_params["location"] = _explicit_llm_loc
                            missing = [m for m in missing if m.get("name") != "location"]
                    _scope_decision = resolve_location_for_merge(
                        current_location=self._gathered_search.get("location"),
                        candidate_location=merged_params.get("location"),
                        latest_text=_latest_user_raw or "",
                        city=str(
                            merged_params.get("city")
                            or self._gathered_search.get("city")
                            or "Chennai"
                        ),
                        extracted_params=merged_params,
                        known_locations=_KNOWN_LOCATIONS.get(
                            str(
                                merged_params.get("city")
                                or self._gathered_search.get("city")
                                or "Chennai"
                            ),
                            [],
                        ),
                        aliases=_LOCATION_ALIASES,
                        explicit_llm_location=_explicit_llm_loc,
                        canonicalize=lambda loc, city: self.canonicalize_search_location(loc, city),
                        citywide=bool(merged_params.get("_citywide_search")),
                    )
                    if _scope_decision.action == "block_stale":
                        _superseded = self._gathered_search.setdefault("_superseded_locations", [])
                        if _scope_decision.stale_location and _scope_decision.stale_location not in _superseded:
                            _superseded.append(_scope_decision.stale_location)
                        logger.info(
                            f"[SearchScopeGuard] blocked_stale_location "
                            f"old={_scope_decision.location} stale={_scope_decision.stale_location} "
                            f"reason={_scope_decision.reason}"
                        )
                        logger.info(
                            f"[SearchScopeGuard] using_committed_location "
                            f"location={_scope_decision.location} reason={_scope_decision.reason}"
                        )
                        merged_params["location"] = _scope_decision.location
                        missing = [m for m in missing if m.get("name") != "location"]
                    elif _scope_decision.action == "use_committed" and _scope_decision.reason in {
                        "filter_refinement",
                        "missing_location",
                    }:
                        logger.info(
                            f"[SearchScopeGuard] using_committed_location "
                            f"location={_scope_decision.location} reason={_scope_decision.reason}"
                        )
                        merged_params["location"] = _scope_decision.location
                        missing = [m for m in missing if m.get("name") != "location"]
                    elif _scope_decision.action == "use_latest":
                        if _scope_decision.stale_location:
                            _superseded = self._gathered_search.setdefault("_superseded_locations", [])
                            if _scope_decision.stale_location not in _superseded:
                                _superseded.append(_scope_decision.stale_location)
                        merged_params["location"] = _scope_decision.location
                        missing = [m for m in missing if m.get("name") != "location"]
                    _clear_location = bool(merged_params.pop("_clear_location", False))
                    _citywide_search = bool(merged_params.pop("_citywide_search", False))
                    _explicit_new_location = str(merged_params.get("location") or "").strip()
                    if _clear_location:
                        _old_loc = str(self._gathered_search.get("location") or "")
                        self._gathered_search.pop("location", None)
                        if _explicit_new_location:
                            # User has explicitly selected a replacement area. Clear the stale
                            # city-wide exploration flags, but keep this concrete location so
                            # the next search runs as an exact-locality search.
                            merged_params["location"] = _explicit_new_location
                            self.clear_pending_budget_confirmation("scope_changed:new_location")
                            self._gathered_search.pop("_citywide_search", None)
                            self._gathered_search.pop("_exploring_alternatives", None)
                            self._gathered_search.pop("_strict_location", None)
                            self._gathered_search.pop("_original_location", None)
                            _citywide_search = False
                            logger.info(
                                f"[Tool][SessionMemory] Fresh location selected after city-wide search: "
                                f"old='{_old_loc}' new='{_explicit_new_location}'"
                            )
                        else:
                            merged_params.pop("location", None)
                            self._gathered_search["_citywide_search"] = True
                        self._gathered_search.pop("_budget_too_low_pending", None)
                        self._budget_too_low_context = None
                        if not _explicit_new_location:
                            logger.info(
                                f"[Tool][SessionMemory] Cleared cached location for city-wide/new-area search "
                                f"(old_location='{_old_loc}')"
                            )
                        if self._context_ref:
                            try:
                                _ctx_clear = self._context_ref[0]
                                _base_clear = _ctx_clear.messages[0]["content"]
                                _base_clear = re.sub(
                                    r'\n\n---\nPENDING BUDGET DECISION.*?---',
                                    "",
                                    _base_clear,
                                    flags=re.DOTALL,
                                )
                                _ctx_clear.messages[0]["content"] = _base_clear
                            except Exception:
                                pass
                    else:
                        if merged_params.get("location"):
                            self.clear_pending_budget_confirmation("scope_changed:explicit_location")
                            self._gathered_search.pop("_citywide_search", None)
                            self._gathered_search.pop("_exploring_alternatives", None)
                            self._gathered_search.pop("_strict_location", None)
                            self._gathered_search.pop("_original_location", None)
                            _citywide_search = False
                            if self._zero_result_followup_mode in {
                                "awaiting_alternative_area_choice",
                                "awaiting_budget_value",
                                "awaiting_budget_or_area_choice",
                            }:
                                self._clear_zero_result_followup_state()
                                logger.info("[ZeroResults] Cleared follow-up state after explicit location selection")
                        elif self._gathered_search.get("_citywide_search"):
                            _citywide_search = True
                            merged_params["_citywide_search"] = True
                            logger.info("[Tool][SessionMemory] Preserving city-wide search mode from session memory")

                    _zr_origin_loc = str(
                        self._gathered_search.get("_zero_result_origin_location")
                        or self._gathered_search.get("_origin_location")
                        or self._gathered_search.get("location")
                        or ""
                    ).strip()
                    _zr_alt_mode = self._zero_result_followup_mode == "awaiting_alternative_areas"
                    _zr_budget_mode = self._zero_result_followup_mode == "awaiting_budget_value"
                    _current_turn_has_budget_value = bool(
                        _parse_inr_amounts(_latest_user_raw) or _is_flexible_budget_text(_latest_user_raw)
                    )

                    if function_name == "areas_by_budget":
                        _areas_user_text = str(_latest_user_raw or "")
                        _areas_alt_intent = bool(re.search(
                            r"\b("
                            r"suggest(?:\s+me)?(?:\s+some)?\s+(?:other\s+)?areas?|"
                            r"other\s+(?:areas?|locations?|localities)|"
                            r"alternate|alternative|alternatives|"
                            r"where\s+else|"
                            r"which\s+areas?|"
                            r"areas?\s+(?:in|within|for)\s+my\s+budget|"
                            r"my\s+budget\s+(?:areas?|locations?|localities)|"
                            r"any\s+(?:good\s+)?(?:areas?|locations?|localities)|"
                            r"affordable\s+(?:areas?|locations?|localities)"
                            r")\b",
                            _areas_user_text,
                            re.IGNORECASE,
                        ))
                        _nearby_intent = bool(re.search(
                            r"\b(near|nearby|close\s+to|around|surrounding|within\s+\d+\s*km)\b",
                            _areas_user_text,
                            re.IGNORECASE,
                        ))
                        if _areas_alt_intent and not _nearby_intent and not _explicit_llm_loc:
                            _origin_loc = str(
                                self._gathered_search.get("_zero_result_origin_location")
                                or self._gathered_search.get("_origin_location")
                                or self._gathered_search.get("location")
                                or ""
                            ).strip()
                            if _origin_loc:
                                self._gathered_search["_origin_location"] = _origin_loc
                            merged_params.pop("location", None)
                            merged_params.pop("near_location", None)
                            merged_params["_citywide_search"] = True
                            _citywide_search = True
                            self._gathered_search["_citywide_search"] = True
                            self._gathered_search["_exploring_alternatives"] = True
                            self._gathered_search["_search_intent"] = "city_wide_discovery"
                            logger.info(
                                f"[AreasByBudget] Alternative-area intent detected - "
                                f"city-wide discovery enabled origin={_origin_loc!r}"
                            )

                    if function_name == "areas_by_budget" and _zr_alt_mode:
                        merged_params.pop("location", None)
                        merged_params["_citywide_search"] = True
                        _citywide_search = True
                        if _zr_origin_loc:
                            merged_params["near_location"] = _zr_origin_loc
                            logger.info(
                                f"[ZeroResults] Preserving origin locality '{_zr_origin_loc}' "
                                "as near_location for alternative-area discovery"
                            )
                        if not _current_turn_has_budget_value:
                            _min_keep, _max_keep = self._normalize_budget_pair(
                                self._gathered_search.get("min_price"),
                                self._gathered_search.get("max_price"),
                                source="zero_result_alt_reuse",
                            )
                            if _min_keep is not None:
                                merged_params["min_price"] = _min_keep
                            if _max_keep is not None:
                                merged_params["max_price"] = _max_keep
                            logger.info("[ZeroResults] Reused confirmed budget for alternative-area discovery")

                    if function_name == "search_properties" and _zr_budget_mode:
                        if _zr_origin_loc and not merged_params.get("location"):
                            merged_params["location"] = _zr_origin_loc
                            missing = [m for m in missing if m.get("name") != "location"]
                        self._gathered_search.pop("_exploring_alternatives", None)
                        self._gathered_search.pop("_citywide_search", None)
                        merged_params.pop("_citywide_search", None)
                        logger.info(
                            f"[ZeroResults] Locked same-locality budget adjustment to '{_zr_origin_loc or 'current locality'}'"
                        )

                    # â”€â”€ Multi-intent clarification â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                    # When user mentions multiple property types (e.g., "apartments or villas"),
                    # ask them to pick one before proceeding. Do NOT silently guess.
                    if merged_params.pop("_multi_intent", False):
                        _multi_types = merged_params.pop("_multi_intent_types", [])
                        if len(_multi_types) >= 2:
                            _types_str = ", ".join(_multi_types)
                            logger.info(
                                f"[MultiIntent] Clarification needed: {_types_str}"
                            )
                            _gather_payload = {
                                "status": "need_clarification",
                                "field": "property_type",
                                "instruction": (
                                    f"I heard you mention {_types_str}. "
                                    f"Which one would you like to explore first - {_types_str}?"
                                ),
                                "already_confirmed": {k: merged_params[k] for k in ["city", "location", "min_price", "max_price"] if merged_params.get(k)},
                                "response_format": (
                                    "Ask ONLY the clarification question. "
                                    "Do NOT say 'Allow me', 'Let me', 'Sure', or any preamble. "
                                    "Wait for user to pick one property type."
                                ),
                                "after_user_answers": (
                                    "Once user picks a property type, call search_properties AGAIN "
                                    "IMMEDIATELY with that type - do NOT say anything first."
                                ),
                            }
                            await _speak_direct_response(
                                _gather_payload["instruction"],
                                _gather_payload,
                            )
                            return

                    # â”€â”€ Handle forced fresh search (interruption/correction) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                    _force_fresh = bool(merged_params.pop("_force_fresh_search", False))
                    if _force_fresh:
                        # Reset pagination and clear pending caches
                        self._shown_slugs = set()
                        self._jll_page = 1
                        self._last_search_key = ""
                        self._ordinal_results = []
                        self._all_seen_slugs = set()
                        self._property_details_map.clear()
                        self._clear_detail_overview_memory("forced_fresh_search")
                        self._gathered_search.pop("_pending_fallback_items", None)
                        self._gathered_search.pop("_pending_key", None)
                        self._gathered_search.pop("_pending_backend_fetch", None)
                        logger.info(
                            "[Interrupt] Reset pagination and caches for fresh search"
                        )

                    # â”€â”€ Fix C: Suppress stale extracted location for areas_by_budget â”€â”€â”€â”€â”€â”€
                    # _extract_search_context scans recent (up to 8) user turns most-recent-
                    # first. For areas_by_budget with a city-wide query ("which area is
                    # cheapest?"), the current user turn has no location, but an older turn
                    # (e.g. "find apartments in T Nagar") still matches the regex and is
                    # returned as merged_params["location"]. That stale location then leaks
                    # into the near_location injection below, silently biasing results.
                    # Guard: if location was NOT in the CURRENT user turn AND the LLM did not
                    # explicitly pass it as an argument, clear it now.
                    if (
                        function_name == "areas_by_budget"
                        and merged_params.get("location")
                        and not _explicit_llm_loc
                        and not _zr_alt_mode
                    ):
                        _cur_u_abud = next(
                            (m.get("content", "") for m in reversed(getattr(context, "messages", []))
                             if m.get("role") == "user"),
                            ""
                        )
                        if merged_params["location"].lower() not in _cur_u_abud.lower():
                            logger.info(
                                f"[Tool][CityWide] areas_by_budget: speech-extracted location "
                                f"'{merged_params['location']}' absent from current user turn - "
                                f"clearing to prevent old-message leak"
                            )
                            merged_params.pop("location", None)
                            if not re.search(
                                r"\b(near|nearby|close\s+to|around|surrounding|within\s+\d+\s*km)\b",
                                _cur_u_abud,
                                re.IGNORECASE,
                            ):
                                merged_params["_citywide_search"] = True
                                _citywide_search = True
                                self._gathered_search["_citywide_search"] = True
                                self._gathered_search["_search_intent"] = "city_wide_discovery"
                                logger.info(
                                    "[Tool][CityWide] areas_by_budget: stale location removed, "
                                    "location guard disabled for city-wide area discovery"
                                )

                    # â”€â”€ Early session-memory pre-cache â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                    # Cache any values extracted from speech RIGHT NOW - do not wait for a
                    # successful search. This prevents re-asking for "villa" or "Chennai"
                    # that the user mentioned several turns before the first tool call.
                    # City: write-once (cities don't change mid-call).
                    # Property_type / location: ALWAYS update - user may switch type or area.
                    # Budget (min_price/max_price): ALWAYS update - user may explicitly change
                    #   their budget mid-call (e.g. "actually under 60 lakhs"). The old write-
                    #   once behaviour caused stale budget to persist across searches even when
                    #   the user clearly stated a different figure.
                    _pagination_turn = self.is_more_results_request(_latest_user_raw)
                    _explicit_bedroom_turn = bool(
                        re.search(r"\b(?:bhk|bedroom|bedrooms|bed)\b", _latest_user_raw or "", re.IGNORECASE)
                    )
                    if function_name == "search_properties" and _pagination_turn and not _explicit_bedroom_turn:
                        _ignored_bedrooms = merged_params.pop("bedrooms", None) or arguments.pop("bedrooms", None)
                        if _ignored_bedrooms:
                            logger.info(
                                f"[Pagination] Ignored bedrooms={_ignored_bedrooms!r} from pagination turn; "
                                "user did not say BHK/bedroom"
                            )
                    for _pre_k in ("city", "property_type", "bedrooms", "project_category", "construction_state", "location", "min_price", "max_price", "_budget_flexible"):
                        _pre_val = merged_params.get(_pre_k)
                        if not _pre_val:
                            continue
                        if _pre_k == "location":
                            if _citywide_search:
                                continue
                            # Always update location - user may change area after no_location_match
                            _pre_city = str(merged_params.get("city") or "").strip().lower()
                            _pre_loc  = str(_pre_val).strip().lower()
                            if _pre_loc == _pre_city or _pre_loc in _CITY_CANONICAL:
                                continue
                            _old_loc = self._gathered_search.get("location", "")
                            if _old_loc.lower().strip() != _pre_loc:
                                self._gathered_search["location"] = _pre_val
                                # Location changed â†’ invalidate all in-flight prefetches
                                # so stale results (for the old area) cannot be served.
                                self._prefetch_turn_id += 1
                                self._prefetch_cache.clear()
                                logger.info(
                                    f"[Tool][SessionMemory] Location updated: "
                                    f"'{_old_loc}' â†’ '{_pre_val}' "
                                    f"(prefetch_turn_id={self._prefetch_turn_id})"
                                )
                            continue
                        if _pre_k == "_budget_flexible":
                            self._gathered_search["_budget_flexible"] = True
                            self._gathered_search.pop("min_price", None)
                            self._gathered_search.pop("max_price", None)
                            logger.info("[Tool][SessionMemory] Budget mode updated: flexible")
                            continue
                        if _pre_k == "property_type":
                            # Always update property_type - user may switch from Apartments to Villas
                            _old_type = self._gathered_search.get("property_type", "")
                            _new_type = str(_pre_val).lower().strip()
                            if _old_type.lower().strip() != _new_type:
                                self._gathered_search["property_type"] = _pre_val
                                logger.info(
                                    f"[Tool][SessionMemory] Property type updated: "
                                    f"'{_old_type}' â†’ '{_pre_val}'"
                                )
                                # Reset pagination and slug state for fresh property type search
                                if _old_type:
                                    _old_count = len(self._shown_slugs)
                                    self._shown_slugs = set()
                                    self._jll_page = 1
                                    self._last_search_key = ""
                                    logger.info(
                                        f"[PropertyTypeChange] RESET pagination state: "
                                        f"'{_old_type}' â†’ '{_new_type}' (cleared {_old_count} slugs)"
                                    )
                                # Invalidate prefetch cache on property type change
                                if _old_type:
                                    self._prefetch_turn_id += 1
                                    self._prefetch_cache.clear()
                                    logger.info(
                                        f"[PropertyTypeChange] INVALIDATED prefetch cache for type change"
                                    )
                            continue
                        if _pre_k == "bedrooms":
                            _old_bed = str(self._gathered_search.get("bedrooms") or "").strip()
                            _new_bed = str(_pre_val).strip()
                            if _old_bed != _new_bed:
                                self._gathered_search["bedrooms"] = _pre_val
                                logger.info(
                                    f"[Tool][SessionMemory] Bedrooms updated: "
                                    f"'{_old_bed}' â†’ '{_pre_val}'"
                                )
                                if _old_bed:
                                    self._shown_slugs = set()
                                    self._jll_page = 1
                                    self._last_search_key = ""
                                    self._prefetch_turn_id += 1
                                    self._prefetch_cache.clear()
                            continue
                        if _pre_k == "project_category":
                            _old_cat = self._gathered_search.get("project_category", "")
                            _new_cat = str(_pre_val).lower().strip()
                            if _old_cat.lower().strip() != _new_cat:
                                self._gathered_search["project_category"] = _pre_val
                                logger.info(
                                    f"[Tool][SessionMemory] Project category updated: "
                                    f"'{_old_cat}' â†’ '{_pre_val}'"
                                )
                                if _old_cat:
                                    self._shown_slugs = set()
                                    self._jll_page = 1
                                    self._last_search_key = ""
                            continue
                        if _pre_k == "construction_state":
                            _old_state = self._gathered_search.get("construction_state", "")
                            _new_state = str(_pre_val).lower().strip()
                            if _old_state.lower().strip() != _new_state:
                                self._gathered_search["construction_state"] = _pre_val
                                logger.info(
                                    f"[Tool][SessionMemory] Construction state updated: "
                                    f"'{_old_state}' â†’ '{_pre_val}'"
                                )
                                if _old_state:
                                    self._shown_slugs = set()
                                    self._jll_page = 1
                                    self._last_search_key = ""
                            continue
                        if _pre_k in ("min_price", "max_price"):
                            # Always update budget - user may explicitly state a different figure.
                            _old_budget = self._gathered_search.get(_pre_k)
                            if _old_budget != _pre_val:
                                self._gathered_search[_pre_k] = _pre_val
                                self._gathered_search.pop("_budget_flexible", None)
                                logger.info(
                                    f"[Tool][SessionMemory] Budget updated: "
                                    f"'{_pre_k}' {_old_budget} â†’ {_pre_val}"
                                )
                            continue
                        # city: write-once - set only when not already cached
                        if not self._gathered_search.get(_pre_k):
                            self._gathered_search[_pre_k] = _pre_val
                            logger.info(f"[Tool][SessionMemory] Pre-cached '{_pre_k}' = {_pre_val}")

                    # â”€â”€ Property name guard â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                    # When the user says a property name ("Prestige Lakeside Habitat") the
                    # location regex in _extract_search_context can pick it up as a locality.
                    # That triggers a new search_properties call, discarding the existing
                    # results. Detect this and discard the extracted location if it matches
                    # any known property name from the current call's slug cache.
                    if merged_params.get("location") and self._name_to_slug:
                        _loc_check = merged_params["location"].lower().strip()
                        _is_prop = any(
                            _loc_check in name or name in _loc_check
                            for name in self._name_to_slug
                        )
                        if _is_prop:
                            logger.info(
                                f"[Tool] Location '{merged_params['location']}' matches a cached "
                                f"property name - discarding to prevent re-search"
                            )
                            del merged_params["location"]
                            # Restore location from session memory if available
                            if self._gathered_search.get("location"):
                                merged_params["location"] = self._gathered_search["location"]

                    if missing:
                        logger.info(
                            f"[Tool][SessionMemory] Pre-fill check: missing={[i.get('name') for i in missing]} "
                            f"cache_keys={list(self._gathered_search.keys()) if self._gathered_search else []}"
                        )

                    # â”€â”€ Session memory: fill any still-missing fields from prior searches â”€â”€
                    # e.g. user said "now show me villas" without repeating city/budget â†’
                    # those were stored in self._gathered_search after the first search.
                    if missing and self._gathered_search:
                        # Maps gathering field names to the actual param dict keys they produce
                        _field_keys: dict[str, list[str]] = {
                            "city":          ["city"],
                            "property_type": ["property_type"],
                            "bedrooms":      ["bedrooms"],
                            "location":      ["location"],
                            "budget":        ["min_price", "max_price", "_budget_flexible"],
                            "result_count":  ["result_count"],
                        }
                        still_missing = []
                        for item in missing:
                            if item["name"] == "location" and (
                                _citywide_search or self._gathered_search.get("_citywide_search")
                            ):
                                continue
                            # FIX 4: Enforce intent - never inject cached location when
                            # the stored intent is city_wide_discovery. This is the hard
                            # backstop that prevents location leaks even if upstream
                            # detection (_citywide_search flag) somehow fails to fire.
                            if item["name"] == "location" and (
                                self._gathered_search.get("_search_intent") == "city_wide_discovery"
                            ):
                                logger.info(
                                    "[Tool][SessionMemory] Skipping location fill - "
                                    "_search_intent=city_wide_discovery blocks location injection"
                                )
                                continue
                            # Don't auto-fill location from session for areas_by_budget -
                            # it causes old locality (e.g. "T Nagar") to leak into city-wide
                            # discovery queries like "which area has cheapest apartments?"
                            if item["name"] == "location" and function_name == "areas_by_budget":
                                logger.info(
                                    "[Tool][SessionMemory] Skipping location fill from session "
                                    "for areas_by_budget to prevent city-wide query contamination"
                                )
                                continue
                            # HARD OVERRIDE: Block location recovery when user explicitly switched
                            if item["name"] == "location" and merged_params.get("_location_override"):
                                logger.warning(
                                    "[LocationOverride] BLOCKING session location recovery - "
                                    f"override active (new='{merged_params.get('_override_new_loc')}')"
                                )
                                continue
                            keys = _field_keys.get(item["name"], [item["name"]])
                            cached_vals = {k: self._gathered_search[k] for k in keys if self._gathered_search.get(k)}
                            if cached_vals:
                                merged_params.update(cached_vals)
                                logger.info(f"[Tool] Session memory: '{item['name']}' filled from prior search â†’ {cached_vals}")
                            else:
                                still_missing.append(item)
                        missing = still_missing

                    # â”€â”€ Defensive restore: city + property_type â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                    # The LLM sometimes drops known fields from its args after a budget update
                    # turn or a multi-turn conversation. Even if the session-fill loop above ran,
                    # these two fields are so critical that we restore them once more here to be safe.
                    for _df_k in ("city", "property_type"):
                        if not merged_params.get(_df_k) and self._gathered_search.get(_df_k):
                            merged_params[_df_k] = self._gathered_search[_df_k]
                            logger.info(
                                f"[Tool] Defensive restore: '{_df_k}'='{self._gathered_search[_df_k]}' from session"
                            )

                    if merged_params:
                        if function_name == "search_properties" and not merged_params.get("result_count"):
                            merged_params["result_count"] = str(PRESENTED_PROPERTY_LIMIT)
                        if function_name == "search_properties" and merged_params.get("_budget_flexible"):
                            merged_params.pop("min_price", None)
                            merged_params.pop("max_price", None)
                        if function_name == "search_properties" and not merged_params.get("bedrooms"):
                            _session_bedrooms = self._gathered_search.get("bedrooms")
                            if _session_bedrooms:
                                merged_params["bedrooms"] = _session_bedrooms
                        if function_name == "search_properties" and merged_params.get("bedrooms"):
                            self._gathered_search.pop("_pending_bedroom_search", None)
                        logger.info(
                            f"[Tool][SessionMemory] Extracted/merged params for this call: {merged_params}"
                        )

                    # â”€â”€ Location alias resolution (STT mishearing correction) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                    # Corrects phonetic STT errors before location validation or API call.
                    if merged_params.get("location"):
                        _resolved_loc = _resolve_canonical_location(
                            merged_params["location"],
                            merged_params.get("city"),
                            self._catalog,
                        )
                        if _resolved_loc:
                            _alias_match = _resolved_loc
                            logger.info(
                                f"[Tool][Alias] '{merged_params['location']}' â†’ '{_alias_match}'"
                            )
                            merged_params["location"] = _resolved_loc

                    # â”€â”€ Location validation (catalog-backed, hard-fail) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                    # Uses catalog locations as primary source, _KNOWN_LOCATIONS as fallback.
                    # Attempt 1 (first mismatch): offer alternatives from catalog + callback.
                    # Attempt 2 (still no match): accept unconditionally (safety valve) and
                    #   let the backend handle via no_location_match response.
                    if merged_params.get("city") and merged_params.get("location") and not missing:
                        import difflib as _difflib

                        _city_v = merged_params["city"]
                        _loc_v  = merged_params["location"]

                        # Prefer catalog locations (authoritative), fall back to hardcoded list
                        _cat_locs = (
                            ((self._catalog or {}).get("by_city") or {})
                            .get(_city_v, {})
                            .get("locations") or []
                        )
                        _known = _cat_locs or _KNOWN_LOCATIONS.get(_city_v, [])

                        if _known:
                            _norm_known = [_norm_loc(k) for k in _known]
                            _norm_loc_v = _norm_loc(_loc_v)
                            _is_valid   = (
                                _norm_loc_v in _norm_known
                                or any(_norm_loc_v in nk for nk in _norm_known)
                                or any(nk in _norm_loc_v for nk in _norm_known)
                            )
                            if not _is_valid:
                                # [Fix-LocationAttempts] Use a per-location map instead of a
                                # single global counter. The old counter was shared across ALL
                                # location attempts in a call: if "Velachery" failed (attempt=1),
                                # "Adyar" (a different valid location) would hit attempt=2 and
                                # bypass catalog validation unconditionally. Now each location
                                # string gets its own attempt count, keyed by normalized name.
                                _loc_attempt_key = _norm_loc(_loc_v)
                                _attempts_map = self._gathered_search.get("_location_attempts_map", {})
                                _attempt = _attempts_map.get(_loc_attempt_key, 0) + 1
                                _attempts_map[_loc_attempt_key] = _attempt
                                self._gathered_search["_location_attempts_map"] = _attempts_map
                                logger.debug(
                                    f"[Fix-LocationAttempts] '{_loc_v}' attempt {_attempt} "
                                    f"(map={_attempts_map})"
                                )

                                def _clear_rejected_session_location() -> None:
                                    _session_loc = str(self._gathered_search.get("location") or "").strip()
                                    if _session_loc and _norm_loc(_session_loc) == _norm_loc(_loc_v):
                                        self._gathered_search.pop("location", None)
                                        self._gathered_search.pop("_strict_location", None)
                                        self._gathered_search.pop("_original_location", None)
                                        logger.info(
                                            f"[LocationGuard] cleared_rejected_session_location={_loc_v!r}"
                                        )

                                if _attempt >= 3:
                                    # Safety valve at 3rd attempt: accept unconditionally.
                                    # Backend's no_location_match handles truly invalid areas.
                                    logger.info(
                                        f"[Tool][Location] '{_loc_v}' still not in catalog after "
                                        f"{_attempt} attempts - accepting, backend will handle"
                                    )
                                    _attempts_map.pop(_loc_attempt_key, None)
                                    self._gathered_search["_location_attempts_map"] = _attempts_map
                                elif _attempt == 2:
                                    # Second mismatch: user repeated but area still not recognised.
                                    # Offer nearest known alternatives so the user can pick a real area.
                                    _close = _difflib.get_close_matches(_loc_v, _known, n=3, cutoff=0.45)
                                    if _close:
                                        _alt_str = ", ".join(_close[:3])
                                        _loc_instr = (
                                            f"Tell the user: \"I couldn't find listings in {_loc_v}. "
                                            f"We do have properties in {_alt_str}. "
                                            f"Would you like to explore any of these? {_callback_offer_text()}\""
                                        )
                                    else:
                                        _suggest = ", ".join(_known[:5])
                                        _loc_instr = (
                                            f"Tell the user: \"I couldn't find listings in {_loc_v} currently. "
                                            f"Some areas we cover in {_city_v} include {_suggest}. "
                                            f"Would you like to explore one of these? {_callback_offer_text()}\""
                                        )
                                    logger.info(
                                        f"[Tool][Location] '{_loc_v}' still not in catalog (attempt {_attempt}) "
                                        f"- offering alternatives, close={_close}"
                                    )
                                    _clear_rejected_session_location()
                                    del merged_params["location"]
                                    missing = [m for m in missing if m["name"] != "location"]
                                    missing.insert(0, {"name": "location", "instruction": _loc_instr})
                                else:
                                    # First mismatch: area not in alias or catalog - tell user it's not valid.
                                    _city_label = _city_v or "Chennai"
                                    _loc_instr = (
                                        f"Tell the user: \"Sorry, {_loc_v} is not a valid area. "
                                        f"Could you please specify a valid area in {_city_label}?\""
                                    )
                                    logger.info(
                                        f"[Tool][Location] '{_loc_v}' not in catalog for {_city_v} "
                                        f"(attempt {_attempt}) - area not valid"
                                    )
                                    _clear_rejected_session_location()
                                    del merged_params["location"]
                                    missing = [m for m in missing if m["name"] != "location"]
                                    missing.insert(0, {"name": "location", "instruction": _loc_instr})

                    if missing:
                        item = missing[0]
                        logger.info(f"[Tool] {function_name} - gathering '{item['name']}'")

                        if item.get("confirmation_candidate"):
                            self.set_pending_value_confirmation(
                                item["name"],
                                item["confirmation_candidate"],
                                item.get("original_value"),
                            )
                        else:
                            self.clear_pending_value_confirmation()

                        # FIX: Loop detection - increment attempt count for this field this turn
                        _field = item["name"]
                        _attempts = self._gather_attempt_counts.get(_field, 0) + 1
                        self._gather_attempt_counts[_field] = _attempts

                        if _attempts >= 3:
                            # Force escape: use whatever is in session memory
                            logger.warning(
                                f"[GatherLoop] Field '{_field}' asked {_attempts} times "
                                f"- forcing escape with session fallback"
                            )
                            # Fill from session memory unconditionally
                            if self._gathered_search.get(_field):
                                merged_params[_field] = self._gathered_search[_field]
                                logger.info(
                                    f"[GatherLoop] Forced '{_field}' = "
                                    f"'{self._gathered_search[_field]}' from session"
                                )
                            else:
                                # If genuinely not in session either, use a default
                                # and let the search fail gracefully
                                if _field == 'location':
                                    merged_params['_citywide_search'] = True
                                    logger.info("[GatherLoop] No location in session - forcing city-wide search")
                            # Do NOT return gathering status - fall through to search
                            # Remove the field from 'missing' so search proceeds
                            missing = [m for m in missing if m['name'] != _field]
                            if not missing:
                                # All params now filled - proceed to search
                                pass  # fall through to search execution below
                            # else: other fields still missing, ask for those instead
                        else:
                            # Build a summary of what's already confirmed so the LLM
                            # does NOT re-ask for any field that was already provided.
                            _confirmed = {
                                k: merged_params[k]
                                for k in ("city", "property_type", "location", "min_price", "max_price")
                                if merged_params.get(k)
                            }
                            _gather_payload = {
                                "status": "gathering",
                                "field": item["name"],
                                "instruction": item["instruction"],
                                # Explicitly list confirmed fields so LLM never re-asks them.
                                "already_confirmed": _confirmed,
                                "important": (
                                    f"Fields in 'already_confirmed' are LOCKED - do NOT ask for them again. "
                                    f"ONLY ask for '{item['name']}'."
                                ),
                                # IMPORTANT: no filler, no preamble - ask the question directly.
                                "response_format": (
                                    "CRITICAL: Ask ONLY the single question in 'instruction'. "
                                    "ZERO preamble allowed - do NOT say 'Allow me', 'Let me', 'Sure', 'Of course', 'I'll check', or ANY filler. "
                                    "Do NOT say you will search, find, or look for anything. "
                                    "Do NOT list property types, budget ranges, or examples. "
                                    "Just ask the ONE question and STOP - wait for user response."
                                ),
                                # Critical: tell LLM to re-call the tool after receiving the answer.
                                "after_user_answers": (
                                    f"Once user provides '{item['name']}', call {function_name} AGAIN "
                                    "IMMEDIATELY and SILENTLY - do NOT say anything first."
                                ),
                            }
                            _spoken_prompt = _spoken_text_from_gather_instruction(
                                item["instruction"],
                                item["name"],
                            )
                            _latest_user_text = _latest_user_message(getattr(context, "messages", []) or [])
                            _force_invalid_location_direct = bool(
                                item["name"] == "location"
                                and re.search(
                                    r"\b(not a valid area|couldn't find listings in|some areas we cover)\b",
                                    str(item["instruction"] or "").lower(),
                                )
                            )
                            _deterministic_gather = _should_use_deterministic_gather_prompt(
                                field_name=item["name"],
                                instruction=item["instruction"],
                                latest_user_text=_latest_user_text,
                                missing_count=len(missing),
                                confirmation_candidate=item.get("confirmation_candidate"),
                                extracted_params=merged_params,
                            )
                            if _force_invalid_location_direct:
                                logger.info(
                                    f"[GatherDirectSpeech] deterministic_followup_path=invalid_location_reprompt "
                                    f"field={item['name']} prompt={_spoken_prompt!r}"
                                )
                                await _speak_direct_response(_spoken_prompt, _gather_payload)
                            elif _deterministic_gather:
                                logger.info(
                                    f"[GatherDirectSpeech] field={item['name']} prompt={_spoken_prompt!r}"
                                )
                                await _speak_direct_response(_spoken_prompt, _gather_payload)
                            else:
                                logger.info(
                                    f"[GatherDirectSpeech] deferred to LLM field={item['name']} "
                                    f"user={_latest_user_text!r}"
                                )
                                await _finish_early(json.dumps(_gather_payload, ensure_ascii=False))
                        return

                    # â”€â”€ HARD GUARD: Location is REQUIRED before search execution â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                    # Before blocking, try to recover location from session memory.
                    # This handles the case where LLM drops location from its tool args
                    # after a failed validation (we intentionally keep it in _gathered_search).
                    self.clear_pending_value_confirmation()
                    if function_name == "areas_by_budget" and not merged_params.get("location"):
                        _citywide_search = True
                        merged_params["_citywide_search"] = True
                        self._gathered_search["_citywide_search"] = True
                        self._gathered_search["_search_intent"] = "city_wide_discovery"
                        logger.info(
                            "[Tool][CityWide] areas_by_budget proceeding without location "
                            "(city/property/budget scope)"
                        )
                    if not merged_params.get("location") and not (
                        _citywide_search or self._gathered_search.get("_citywide_search")
                    ):
                        _session_loc = self._gathered_search.get("location", "")
                        if _session_loc:
                            merged_params["location"] = _session_loc
                            logger.info(
                                f"[Tool] BLOCKING avoided - recovered location '{_session_loc}' from session memory"
                            )
                    if not merged_params.get("location") and not (
                        _citywide_search or self._gathered_search.get("_citywide_search")
                    ):
                        _city = merged_params.get("city", "this city")
                        logger.info(f"[Tool] IMMEDIATE RETURN - location required but missing. Have: {list(merged_params.keys())}")
                        # Use cached non-blocking response for immediate user feedback
                        _response = self._missing_location_response.copy()
                        _response["already_confirmed"] = {k: merged_params[k] for k in ["city", "property_type", "min_price", "max_price"] if merged_params.get(k)}
                        await result_callback(
                            json.dumps(_response, ensure_ascii=False),
                            properties=FunctionCallResultProperties(run_llm=True)
                        )
                        return

                    # All required fields gathered - persist into session memory for future calls
                    _session_keys = ("city", "property_type", "bedrooms", "location", "result_count")
                    for _k in _session_keys:
                        if merged_params.get(_k):
                            # Guard: don't cache location if it's the same as city (prevents bad cache hits)
                            if _k == "location":
                                if _citywide_search:
                                    continue
                                _city_val = str(merged_params.get("city", "")).strip().lower()
                                _loc_val = str(merged_params[_k]).strip().lower()
                                if _loc_val == _city_val or _loc_val in _CITY_CANONICAL:
                                    logger.info(f"[Tool][SessionMemory] Skipping location cache: '{merged_params[_k]}' matches city or is a city name")
                                    continue
                            self._gathered_search[_k] = merged_params[_k]
                    self._normalize_and_commit_budget(
                        merged_params.get("min_price"),
                        merged_params.get("max_price"),
                        source="post_gather_persist",
                        target=self._gathered_search,
                    )
                    # Location validated successfully - reset attempt counter for this location
                    # [Fix-LocationAttempts] Clear per-location entry on success; keep map intact.
                    _loc_attempt_key_clean = _norm_loc(merged_params.get("location", ""))
                    _attempts_map_clean = self._gathered_search.get("_location_attempts_map", {})
                    if _loc_attempt_key_clean in _attempts_map_clean:
                        _attempts_map_clean.pop(_loc_attempt_key_clean)
                        self._gathered_search["_location_attempts_map"] = _attempts_map_clean
                    # Legacy key cleanup (safe no-op if already absent)
                    self._gathered_search.pop("_location_attempts", None)
                    logger.info(
                        f"[Tool][SessionMemory] Updated cache after gather: {self._gathered_search}"
                    )
                    self._log_session_snapshot("after-gather-persist")
                    _latest_user_text = next(
                        (
                            m.get("content", "")
                            for m in reversed(getattr(context, "messages", []) or [])
                            if m.get("role") == "user" and isinstance(m.get("content"), str)
                        ),
                        "",
                    )
                    _latest_user_lower = _latest_user_text.lower()
                    _budget_in_current_turn = bool(
                        re.search(r"\d+\s*(?:l|lakhs?|crore|cr)", _latest_user_lower)
                        or _CAP_BUDGET_RE.search(_latest_user_lower)
                        or _FLOOR_BUDGET_RE.search(_latest_user_lower)
                    )
                    _accept_min_range = False
                    if (
                        function_name in {"search_properties", "areas_by_budget"}
                        and self._gathered_search.get("_budget_too_low_pending")
                    ):
                        _locked_loc = str((self._budget_too_low_context or {}).get("location") or "").strip().lower()
                        _current_loc = str(merged_params.get("location") or "").strip().lower()
                        _switched_area = bool(_locked_loc and _current_loc and _current_loc != _locked_loc)
                        _wants_other_area = bool(_BTL_OTHER_AREA_RE.search(_latest_user_lower)) or _switched_area
                        _accept_min_range = bool(_BTL_ACCEPT_RE.search(_latest_user_lower))
                        _pending_area_min = int((self._budget_too_low_context or {}).get("area_min_price_value") or 0)
                        _current_budget = int(
                            merged_params.get("max_price")
                            or merged_params.get("min_price")
                            or 0
                        )
                        if _pending_area_min and _current_budget:
                            _delta = abs(_current_budget - _pending_area_min)
                            if _delta <= max(300_000, int(_pending_area_min * 0.05)):
                                _accept_min_range = True
                        if _wants_other_area:
                            self._gathered_search.pop("_budget_too_low_pending", None)
                            self._budget_too_low_context = None
                            # Clear location so this call becomes city-wide (finds areas IN budget).
                            # Keeping max_price ensures JLL filters by the user's original budget.
                            # Without this, location=Anna Nagar + max_price=1cr goes back to
                            # integration.js, re-triggers the budget_too_low short-circuit, and
                            # the agent repeats "Would you like to increase your budget..." forever.
                            merged_params.pop("location", None)
                            self._gathered_search.pop("location", None)
                            self._gathered_search["_citywide_search"] = True
                            # Strip stale PENDING BUDGET DECISION block so LLM doesn't loop
                            if self._context_ref and self._context_ref[0]:
                                try:
                                    _ctx_w = self._context_ref[0]
                                    _base_w = _ctx_w.messages[0]["content"]
                                    _base_w = re.sub(
                                        r'\n\n---\nPENDING BUDGET DECISION.*?---',
                                        "",
                                        _base_w,
                                        flags=re.DOTALL,
                                    )
                                    _ctx_w.messages[0]["content"] = _base_w
                                except Exception:
                                    pass
                            logger.info("[BudgetTooLow] User chose other area â†’ cleared location for city-wide discovery")

                        # Discovery follow-up detection: user wants alternatives, not current area
                        _is_discovery_followup = _DISCOVERY_FOLLOWUP_RE.search(_latest_user_lower)

                        # [Fix-AmbiguousYes] Bare affirmative after budget_too_low - treat as
                        # 'explore other areas' (safer: respects user's stated budget). If user
                        # actually wanted to stretch budget, they would say 'show me anyway' or
                        # 'increase budget' - those still match _BTL_ACCEPT_RE.
                        _bare_affirmative_re = re.compile(
                            r'^\s*(yes|yeah|yep|yup|sure|ok|okay|alright|fine)\s*[.!?]?\s*$',
                            re.IGNORECASE,
                        )
                        _is_bare_affirmative = bool(_bare_affirmative_re.match(_latest_user_text))
                        if (
                            _is_bare_affirmative
                            and self._gathered_search.get("_budget_too_low_pending")
                            and not _wants_other_area
                            and not _accept_min_range
                            and not _is_discovery_followup
                        ):
                            _is_discovery_followup = True  # route through discovery branch below
                            logger.warning(
                                f"[Fix-AmbiguousYes] Bare affirmative {_latest_user_text!r} after "
                                f"budget_too_low - routing to 'explore other areas' (city-wide, "
                                f"budget preserved)"
                            )
                        if _is_discovery_followup and self._gathered_search.get("_budget_too_low_pending"):
                            # User wants alternatives, not the current area - clear budget_too_low context
                            _prev_min = self._gathered_search.get("min_price")
                            _prev_max = self._gathered_search.get("max_price")
                            self._gathered_search.pop("_budget_too_low_pending", None)
                            self._budget_too_low_context = None
                            # Clear location to allow fresh discovery
                            merged_params.pop("location", None)
                            self._gathered_search.pop("location", None)
                            if not _budget_in_current_turn:
                                if _prev_min is not None:
                                    merged_params["min_price"] = _prev_min
                                else:
                                    merged_params.pop("min_price", None)
                                if _prev_max is not None:
                                    merged_params["max_price"] = _prev_max
                                else:
                                    merged_params.pop("max_price", None)
                            # Force city-wide discovery intent
                            merged_params["_citywide_search"] = True
                            logger.warning(
                                "[DiscoveryOverride] Discovery follow-up detected after budget_too_low - cleared location context for fresh city-wide search"
                            )

                        # Re-ask detection: user re-asks about SAME location without specifying budget
                        # Clear budget filter to show all properties in the area
                        _same_location_reask = (
                            _locked_loc and _current_loc and _current_loc == _locked_loc
                            and not _switched_area
                            and not _wants_other_area
                            and not _accept_min_range
                            and not _is_discovery_followup
                        )
                        if _same_location_reask and self._gathered_search.get("_budget_too_low_pending"):
                            if not _budget_in_current_turn:
                                # User re-asking about same location without budget - clear budget to show all
                                logger.info("[BudgetTooLow] User re-asking same location without budget - clearing budget filter to show all properties")
                                merged_params.pop("min_price", None)
                                merged_params.pop("max_price", None)
                                self._gathered_search.pop("min_price", None)
                                self._gathered_search.pop("max_price", None)
                                self._gathered_search.pop("_budget_too_low_pending", None)
                                self._budget_too_low_context = None
                                # Remove PENDING BUDGET DECISION block from system prompt
                                if self._context_ref:
                                    try:
                                        _ctx = self._context_ref[0]
                                        _base = _ctx.messages[0]["content"]
                                        _base = re.sub(
                                            r'\n\n---\nPENDING BUDGET DECISION.*?---',
                                            "",
                                            _base,
                                            flags=re.DOTALL,
                                        )
                                        _ctx.messages[0]["content"] = _base
                                        logger.info("[BudgetTooLow] Cleared PENDING BUDGET DECISION block")
                                    except Exception:
                                        pass

                    # â”€â”€ Budget-too-low one-time skip â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                    # If the previous search returned budget_too_low=true (the area exists
                    # but user's price is below the area minimum), and the user agreed to
                    # look anyway, we drop the price filter for this one call so the LLM
                    # can show what's actually available. The flag is cleared immediately.
                    if (
                        function_name in {"areas_by_budget", "search_properties"}
                        and self._zero_result_route_lock == "areas_by_budget"
                        and not _explicit_llm_loc
                    ):
                        merged_params.pop("location", None)

                    if (
                        function_name == "search_properties"
                        and self._gathered_search.get("_budget_too_low_pending")
                        and _accept_min_range
                    ):
                        self._gathered_search.pop("_budget_too_low_pending", None)
                        _force_affordable_sort = True
                        # Instead of dropping budget entirely, use area_min_price as floor
                        # so results start from the price we told the user
                        _area_min = (self._budget_too_low_context or {}).get("area_min_price_value")
                        if _area_min:
                            merged_params["min_price"] = int(_area_min)
                            self._gathered_search["min_price"] = int(_area_min)
                            # Preserve the user's new max_price if it is ABOVE the area minimum.
                            # Previously we always popped max_price here, which threw away the
                            # user's explicitly stated new budget (e.g. "increase to 3 crore")
                            # and returned all properties above area_min with no upper cap.
                            _new_max = merged_params.get("max_price")
                            if _new_max and int(_new_max) > int(_area_min):
                                self._gathered_search["max_price"] = int(_new_max)
                                logger.info(
                                    f"[BudgetTooLow] User raised budget - preserving max_price={_new_max} "
                                    f"(area_min={_area_min})"
                                )
                            else:
                                # No new budget provided or it's still below area_min -
                                # remove the cap so results start from area_min upward.
                                merged_params.pop("max_price", None)
                                self._gathered_search.pop("max_price", None)
                                logger.info(f"[BudgetTooLow] Set min_price to area_min: {_area_min}, no upper cap")
                        else:
                            merged_params.pop("min_price", None)
                            merged_params.pop("max_price", None)
                            self._gathered_search.pop("min_price", None)
                            self._gathered_search.pop("max_price", None)
                        # Force-use the locked city/location/type from the budget_too_low
                        # response ONLY if user didn't provide new values in this turn.
                        # This guards against STT garbling while allowing area changes.
                        if self._budget_too_low_context:
                            for _btl_k in ("city", "property_type", "location"):
                                _btl_v = self._budget_too_low_context.get(_btl_k)
                                # Only force if not already provided in current args
                                if _btl_v and _btl_k not in arguments:
                                    merged_params[_btl_k] = _btl_v
                                    self._gathered_search[_btl_k] = _btl_v
                            if self._persona == 'luxury':
                                self._persona = 'budget'
                                # Remove luxury persona text from system prompt
                                if self._context_ref:
                                    try:
                                        _ctx_p = self._context_ref[0]
                                        _base_p = _ctx_p.messages[0]["content"]
                                        _base_p = re.sub(
                                            r'\[PERSONA: LUXURY BUYER\].*?(?=\n\n---|\Z)',
                                            '[PERSONA: VALUE BUYER]\nPresent properties starting from the LOWEST price first. Focus on value and affordability.',
                                            _base_p,
                                            flags=re.DOTALL,
                                        )
                                        _ctx_p.messages[0]["content"] = _base_p
                                    except Exception:
                                        pass
                                logger.info("[BudgetTooLow] Switched persona: luxury -> budget, updated system prompt")
                            logger.info(
                                f"[BudgetTooLow] User accepted higher price - "
                                f"dropping budget filter, forced params from locked ctx: "
                                f"{self._budget_too_low_context}"
                            )
                            self._budget_too_low_context = None
                        else:
                            logger.info(
                                "[BudgetTooLow] User accepted higher price - "
                                "dropping budget filter for this search"
                            )
                        # Remove PENDING BUDGET DECISION block from system prompt
                        if self._context_ref:
                            try:
                                _ctx2 = self._context_ref[0]
                                _base2 = _ctx2.messages[0]["content"]
                                _base2 = re.sub(
                                    r'\n\n---\nPENDING BUDGET DECISION.*?---',
                                    "",
                                    _base2,
                                    flags=re.DOTALL,
                                )
                                _ctx2.messages[0]["content"] = _base2
                            except Exception:
                                pass

                    # â”€â”€ Persona detection + investor confirmation â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                    # Only runs for search_properties (not booking/callback tools).
                    # Runs once per call: skipped after persona is confirmed.
                    if function_name == "search_properties" and self._persona_confirmed is not True:
                        _all_user_lower = " ".join(
                            m.get("content", "") for m in (getattr(context, "messages", []) or [])
                            if m.get("role") == "user"
                        ).lower()

                        if self._persona_confirmed == "pending":
                            # User just answered our "investing or own use?" question.
                            # Read their most recent message to decide.
                            _latest_user = next(
                                (m.get("content", "") for m in reversed(
                                    getattr(context, "messages", []) or []
                                ) if m.get("role") == "user"), ""
                            ).lower()
                            if _INVESTOR_YES_RE.search(_latest_user) and not _INVESTOR_NO_RE.search(_latest_user):
                                self._persona = "investor"
                                logger.info("[Persona] User confirmed: investor")
                            else:
                                logger.info(f"[Persona] User confirmed: own use â†’ keeping '{self._persona}'")
                            self._persona_confirmed = True
                            self._inject_persona_context()

                        else:
                            # First time: infer persona from budget amount
                            _budget = (
                                merged_params.get("max_price")
                                or merged_params.get("min_price")
                                or self._gathered_search.get("max_price")
                                or self._gathered_search.get("min_price")
                                or 0
                            )
                            if _budget >= _PERSONA_LUXURY_MIN:
                                self._persona = "luxury"
                            elif 0 < _budget < _PERSONA_BUDGET_MAX:
                                self._persona = "budget"
                            else:
                                self._persona = "mid"

                            if _INVESTOR_KEYWORDS_RE.search(_all_user_lower):
                                # Investor signals detected â†’ ask one confirmation question
                                self._persona_confirmed = "pending"
                                _locked = {
                                    k: merged_params[k]
                                    for k in ("city", "property_type", "location", "min_price", "max_price")
                                    if merged_params.get(k)
                                }
                                logger.info(
                                    f"[Persona] Investor signals detected "
                                    f"(base persona={self._persona}) - asking confirmation"
                                )
                                await _finish_early(json.dumps({
                                    "status":    "gathering",
                                    "field":     "use_intent",
                                    "instruction": (
                                        "Ask the user: "
                                        "'Just so I can find the best options for you - "
                                        "are you looking to invest in this property, "
                                        "or is it for your own use?'"
                                    ),
                                    "already_confirmed": _locked,
                                    "after_user_answers": (
                                        f"Once user answers, call {function_name} AGAIN "
                                        "IMMEDIATELY and SILENTLY."
                                    ),
                                }, ensure_ascii=False))
                                return
                            else:
                                # No investor signals - auto-confirm without asking
                                self._persona_confirmed = True
                                self._inject_persona_context()
                                logger.info(f"[Persona] Auto-confirmed: '{self._persona}' (budget={_budget})")

                    # Merge into arguments and proceed
                    arguments = {**arguments, **merged_params}
                    logger.info(f"[Tool] All gathered, executing search: {list(merged_params.keys())}")

                # Strategy B - schema validation (firstName etc.)
                # areas_by_budget relies heavily on session/context-filled search state
                # (city, property_type, budget) for alternative-area discovery. Running
                # the generic schema hallucination guard here can block valid requests
                # like "suggest other areas" after zero results, because those values
                # often come from prior confirmed turns rather than the current utterance.
                if function_name != "areas_by_budget" and _schema_items and any(arguments.get(i["name"]) for i in _schema_items):
                    schema_endpoint = {**endpoint, "gather_before_call": _schema_items}
                    unverified = _validate_gathered_values(schema_endpoint, arguments, context)
                    if unverified:
                        ask_item = unverified[0]
                        logger.warning(f"[Tool] {function_name} hallucination: {[i['name'] for i in unverified]}")
                        await _finish_early(json.dumps({
                            "status": "need_clarification",
                            "missing_fields": [i["name"] for i in unverified],
                            "instruction": (
                                f"STOP - ask the user for '{ask_item['name']}' before proceeding. "
                                f"{ask_item.get('description', '').split('.')[0]}."
                            ),
                        }, ensure_ascii=False))
                        return

            # â”€â”€ HTTP request â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
            self.filler_active = True   # ToolAckFilter suppresses stray ack-only input during tool work
            self._latency_trace_ref[0]["tool_start"] = time.time()
            try:
                _tool_ack = self.build_tool_ack_text(function_name)
                if _tool_ack:
                    try:
                        await llm.push_frame(LLMFullResponseStartFrame(), FrameDirection.DOWNSTREAM)
                        await llm.push_frame(TextFrame(_tool_ack), FrameDirection.DOWNSTREAM)
                        await llm.push_frame(LLMFullResponseEndFrame(), FrameDirection.DOWNSTREAM)
                    except Exception as _ack_err:
                        logger.debug(f"[ToolAck] skipped for {function_name}: {_ack_err}")
                # For get_property_details: validate and resolve project_slug against session slug cache.
                # Three cases handled in order:
                #   1. Slug cache is empty   â†’ LLM hasn't searched yet; tell it to search first
                #   2. Slug not in cache     â†’ try fuzzy name match; if found, substitute real slug;
                #                              if still not found, fail hard with available slugs so
                #                              LLM can self-correct without guessing
                #   3. Slug found in cache   â†’ proceed normally
                if function_name == "get_property_details":
                    # Support both property_id (new) and project_slug (legacy) parameters
                    _requested_detail_target = str(arguments.get("property_id") or arguments.get("project_slug") or "").strip()
                    _locked_target = self.current_locked_property_target()
                    if _locked_target:
                        _locked_property_id = str(_locked_target.get("property_id") or _locked_target.get("project_slug") or "").strip()
                        if (
                            _requested_detail_target
                            and not self._locked_target_matches_request(_locked_target, _requested_detail_target)
                        ):
                            logger.info(
                                f"[PropertyLock] explicit request overrides stale locked target "
                                f"requested={_requested_detail_target!r} locked_id={_locked_property_id or '-'}"
                            )
                            self._forced_property_detail_id_once = None
                            self.clear_locked_property_target("explicit_detail_request_mismatch")
                            _locked_target = None
                        elif _locked_property_id:
                            arguments = {
                                **arguments,
                                "property_id": _locked_property_id,
                                "project_slug": str(_locked_target.get("project_slug") or _locked_property_id).strip(),
                            }
                            logger.info(
                                f"[PropertyLock] exact property target consumed property_id={_locked_property_id} "
                                f"source={_locked_target.get('source')}"
                            )
                    _forced_property_id = self._peek_forced_property_detail()
                    if (
                        _forced_property_id
                        and _requested_detail_target
                        and self._normalize_property_lookup_key(_requested_detail_target)
                        != self._normalize_property_lookup_key(_forced_property_id)
                        and not self._locked_target_matches_request(
                            self._get_cached_property(_forced_property_id)
                            or {"property_id": _forced_property_id, "project_slug": _forced_property_id},
                            _requested_detail_target,
                        )
                    ):
                        logger.info(
                            f"[PropertyFirst] explicit detail request overrides stale forced property "
                            f"requested={_requested_detail_target!r} forced={_forced_property_id!r}"
                        )
                        self._forced_property_detail_id_once = None
                        _forced_property_id = None
                    else:
                        _forced_property_id = self._consume_forced_property_detail()
                    if _forced_property_id:
                        arguments = {
                            **arguments,
                            "property_id": _forced_property_id,
                            "project_slug": _forced_property_id,
                        }
                        logger.info(
                            f"[PropertyFirst] Overriding get_property_details target with forced property_id="
                            f"{_forced_property_id}"
                        )
                    provided = str(arguments.get("property_id") or arguments.get("project_slug", "")).strip()
                    if not provided:
                        await _finish_early(json.dumps({
                            "success": False,
                            "error": "Property ID is required. Call search_properties first to get available properties.",
                            "tool": function_name,
                        }, ensure_ascii=False))
                        return
                    # Try to restore slug cache from session memory if empty
                    if not self._slug_cache and self._gathered_search.get("_property_slugs"):
                        _session_slugs = self._gathered_search["_property_slugs"]
                        logger.info(f"[Tool] Restoring slug cache from session memory: {len(_session_slugs)} entries")
                        for slug, name in _session_slugs.items():
                            self._slug_cache[slug] = {"project_slug": slug, "name": name}
                            self._name_to_slug[name.lower().strip()] = slug

                    if not self._slug_cache:
                        # No search in this session. First attempt property-name resolution so
                        # direct property enquiries do not fall back into the generic gather flow.
                        _resolver_query = re.sub(r"[-_]+", " ", provided).strip()
                        _resolved = await self.resolve_property_by_name(
                            _resolver_query,
                            location_hint=self._gathered_search.get("location") or "",
                        )
                        _resolved_candidates = (_resolved.get("candidates") or [])[:3]
                        if _resolved.get("match_type") == "single" and _resolved_candidates:
                            _candidate = _resolved_candidates[0]
                            await _finish_early(json.dumps({
                                "success": False,
                                "action": "PROPERTY_FIRST_CONFIRM",
                                "candidate": _candidate,
                                "instruction": (
                                    "This looks like a direct property enquiry. "
                                    "Do NOT call search_properties. Ask the user to confirm this exact property first using "
                                    "the candidate name, location, BHK, and price. After the user confirms, call "
                                    f"get_property_details with property_id='{_candidate.get('property_id')}'."
                                ),
                            }, ensure_ascii=False))
                            return
                        if _resolved.get("match_type") == "multiple" and _resolved_candidates:
                            await _finish_early(json.dumps({
                                "success": False,
                                "action": "PROPERTY_FIRST_DISAMBIGUATE",
                                "candidates": _resolved_candidates,
                                "instruction": (
                                    "This looks like a direct property enquiry with multiple close matches. "
                                    "Do NOT call search_properties. Read the candidate options briefly using name, area, BHK, and price, "
                                    "and ask the user which one they mean. After the user chooses, call get_property_details with the chosen property_id."
                                ),
                            }, ensure_ascii=False))
                            return
                        # No resolver match - provide gathered params so LLM can immediately call search_properties.
                        _location = (
                            self._gathered_search.get("location")
                            or self._gathered_search.get("_last_location")
                        )
                        _auto_params = {
                            k: self._gathered_search[k]
                            for k in ("city", "property_type", "min_price", "max_price", "result_count")
                            if self._gathered_search.get(k)
                        }
                        if _location and not _auto_params.get("location"):
                            _auto_params["location"] = _location
                        logger.warning(f"[Tool] get_property_details with empty cache - property='{provided}', auto_params={_auto_params}")
                        await _finish_early(json.dumps({
                            "success": False,
                            "action": "CALL_SEARCH_FIRST",
                            "instruction": (
                                "Property cache is empty - you must call search_properties IMMEDIATELY. "
                                "Do NOT say anything to the user. Do NOT ask for property_id. "
                                "Call search_properties right now using the search_params provided."
                            ),
                            "search_params": _auto_params,
                        }, ensure_ascii=False))
                        return
                    _known_property_id = self.resolve_known_property_id(provided)
                    if _known_property_id:
                        arguments = {**arguments, "project_slug": _known_property_id, "property_id": _known_property_id}
                        provided = _known_property_id
                        logger.info(
                            f"[PropertyFastPath] Resolved exact property target from shortlist/cache "
                            f"property_id={_known_property_id}"
                        )
                    if provided not in self._slug_cache:
                        _resolver_query = re.sub(r"[-_]+", " ", provided).strip()
                        _resolved = await self.resolve_property_by_name(
                            _resolver_query,
                            location_hint=self._gathered_search.get("location") or "",
                        )
                        _resolved_candidates = (_resolved.get("candidates") or [])[:3]
                        if _resolved.get("match_type") == "single" and _resolved_candidates:
                            _candidate = _resolved_candidates[0]
                            self._mark_explicit_property_focus(_candidate)
                            logger.info(f"[Tool] Property '{provided}' not in cache, but resolver found single candidate '{_candidate.get('name')}'")
                            await _finish_early(json.dumps({
                                "success": False,
                                "action": "PROPERTY_FIRST_CONFIRM",
                                "candidate": _candidate,
                                "instruction": (
                                    "This is a direct property enquiry for a property outside the current search results. "
                                    "Do NOT mention the previous property. Ask the user to confirm this exact property first using "
                                    "the candidate name, location, BHK, and price. After the user confirms, call "
                                    f"get_property_details with property_id='{_candidate.get('property_id')}'."
                                ),
                            }, ensure_ascii=False))
                            return
                        if _resolved.get("match_type") == "multiple" and _resolved_candidates:
                            logger.info(f"[Tool] Property '{provided}' not in cache, resolver found {len(_resolved_candidates)} candidates")
                            await _finish_early(json.dumps({
                                "success": False,
                                "action": "PROPERTY_FIRST_DISAMBIGUATE",
                                "candidates": _resolved_candidates,
                                "instruction": (
                                    "This is a direct property enquiry for a property outside the current search results. "
                                    "Do NOT mention the previous property. Read the candidate options briefly using name, area, BHK, and price, "
                                    "and ask the user which one they mean. After the user chooses, call get_property_details with the chosen property_id."
                                ),
                            }, ensure_ascii=False))
                            return
                        # Hard fail - return the real available properties so LLM picks the right one.
                        available = [
                            {"name": v.get("name", k), "property_id": k}
                            for k, v in self._slug_cache.items()
                        ]
                        logger.warning(f"[Tool] Property '{provided}' not in cache. Available: {[a['name'] for a in available]}")
                        await _finish_early(json.dumps({
                            "success": False,
                            "action": "RETRY_WITH_ID",
                            "error": f"Property '{provided}' was not in the search results.",
                            "available_properties": available,
                            "instruction": (
                                "Do NOT speak this error to the user. "
                                "Call get_property_details again using the exact 'property_id' from available_properties for the property the user asked about."
                            ),
                        }, ensure_ascii=False))
                        return
                    else:
                        logger.debug(f"[Tool] Property '{provided}' found in cache âœ“")
                        # Validate that the cached property's location is consistent with
                        # the current session search location. This prevents the LLM from
                        # narrating a T Nagar property when the user has since switched to
                        # searching OMR - the slug stays in _slug_cache across searches.
                        _cached_loc_check = self._slug_cache.get(provided, {})
                        _session_loc_now  = self._gathered_search.get("location", "")
                        _explicit_detail_request = (
                            bool(self._explicit_property_focus_id)
                            and provided == self._explicit_property_focus_id
                        )
                        if (
                            _session_loc_now
                            and _cached_loc_check
                            and not _explicit_detail_request
                            and not _strict_location_match(
                                _session_loc_now,
                                _cached_loc_check,
                            )
                        ):
                            _stale_name = (
                                _cached_loc_check.get("name")
                                or _cached_loc_check.get("project_name")
                                or provided
                            )
                            logger.warning(
                                f"[DetailGuard] Property '{_stale_name}' is cached but "
                                f"its location '{_cached_loc_check.get('location')}' does not "
                                f"match current session location '{_session_loc_now}' - "
                                f"blocking detail narration"
                            )
                            await _finish_early(json.dumps({
                                "success": False,
                                "action": "SEARCH_REQUIRED",
                                "error": (
                                    f"'{_stale_name}' is from a previous search in a "
                                    f"different area. The user is now looking in {_session_loc_now}. "
                                    f"Call search_properties for {_session_loc_now} first, "
                                    f"then offer get_property_details on those results."
                                ),
                            }, ensure_ascii=False))
                            return
                        if _explicit_detail_request:
                            logger.info(
                                f"[DetailGuard] Bypassing session-location guard for explicit property request "
                                f"property_id={provided}"
                            )
                        # Use search-cached data if it has full details (possession, rera, etc.)
                        _cached = self._slug_cache.get(provided, {})
                        if _cached.get("possession") or _cached.get("rera") or _cached.get("address"):
                            logger.info(f"[Tool] Using search-cached details for '{provided}' - skipping HTTP call")
                            # Format like get_property_details response
                            _cached_result = {
                                "success": True,
                                "data": {
                                    "property_id": provided,
                                    "name": _cached.get("name") or _cached.get("project_name"),
                                    "city": _cached.get("city"),
                                    "location": _cached.get("location"),
                                    "micro_market": _cached.get("micro_market"),
                                    "address": _cached.get("address"),
                                    "postal_code": _cached.get("postal_code"),
                                    "type": _cached.get("type"),
                                    "category": _cached.get("category"),
                                    "construction": _cached.get("construction"),
                                    "floors": _cached.get("floors"),
                                    "towers": _cached.get("towers"),
                                    "units": _cached.get("units"),
                                    "possession": _cached.get("possession"),
                                    "rera": _cached.get("rera"),
                                    "sold_out": _cached.get("sold_out", False),
                                    "description": _cached.get("description"),
                                    "developer": _cached.get("developer", []),
                                    "configs": _cached.get("configs", []),
                                    "amenities": _cached.get("amenities", []),
                                    "starting_price": _cached.get("starting_price"),
                                    "state": _cached.get("state"),
                                },
                            }
                            result = _cached_result
                            goto_process_result = True
                            arguments = {**arguments, "project_slug": provided, "property_id": provided}
                        # Normalize project_slug to the validated cache key so the URL
                        # /proxy/property/{project_slug} is built with the real slug,
                        # not the display name the LLM sometimes passes.
                        else:
                            arguments = {**arguments, "project_slug": provided, "property_id": provided}

                # â”€â”€ Pagination: param-comparison-based show-more detection â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                # PROBLEM: The LLM (gpt-4.1-nano, smaller models) reliably passes
                # page=1 for every search_properties call regardless of context.
                # Relying on the LLM to pass page=2 causes "show more" to always
                # reset and repeat the same first 5 results.
                #
                # FIX: We detect "show more" by comparing the current search params
                # (city / location / type / budget) against the LAST search.
                # - If params are IDENTICAL and we have already-shown slugs â†’ it's
                #   "show more" â†’ auto-bump to next page and inject exclude_slugs.
                # - If any key param changed (new city, new area, new type, budget
                #   change) â†’ it's a fresh search â†’ reset slug tracking.
                # - CALL_SEARCH_FIRST recovery also passes location/type/budget â†’
                #   those should be treated as fresh searches. To detect this: if the
                #   LLM explicitly passes page>1 in a recovery call we don't override it.
                if function_name == "search_properties":
                    # Build the comparison key from merged_params (post session-fill),
                    # NOT from raw arguments. When the LLM omits location on a show-more
                    # call (trusting session memory to fill it), raw arguments have an
                    # empty location â†’ key mismatch â†’ fresh search instead of pagination.
                    # merged_params reflects the actual backend request after all fills.
                    # Use arguments as fallback for any field session-fill didn't touch.
                    _search_key = "|".join([
                        str(merged_params.get("city") or arguments.get("city") or "").strip().lower(),
                        str(merged_params.get("location") or arguments.get("location") or "").strip().lower(),
                        str(merged_params.get("property_type") or arguments.get("property_type") or "").strip().lower(),
                        str(merged_params.get("bedrooms") or arguments.get("bedrooms") or "").strip().lower(),
                        str(merged_params.get("project_category") or arguments.get("project_category") or "").strip().lower(),
                        str(merged_params.get("construction_state") or arguments.get("construction_state") or "").strip().lower(),
                        str(merged_params.get("min_price") or arguments.get("min_price") or ""),
                        str(merged_params.get("max_price") or arguments.get("max_price") or ""),
                    ])
                    # Strict exact-string equality - any change to city, location,
                    # property_type, min_price, or max_price produces a different key.
                    # No partial matching, no tolerance. Changed budget or location
                    # always triggers a fresh search and resets _shown_slugs.
                    _is_same_params = (
                        _search_key == self._last_search_key
                        and bool(self._shown_slugs)
                    )

                    # [SearchState] Log search state for debugging
                    logger.info(
                        f"[SearchState] new_search={not _is_same_params}, page={self._jll_page}, "
                        f"shown={len(self._shown_slugs)}, key_match={_search_key == self._last_search_key}"
                    )
                    self._backend_search_key = _search_key
                    self._conversation_scope_key = self._build_conversation_scope_key(
                        {
                            "city": merged_params.get("city") or arguments.get("city"),
                            "location": merged_params.get("location") or arguments.get("location"),
                            "property_type": merged_params.get("property_type") or arguments.get("property_type"),
                            "bedrooms": merged_params.get("bedrooms") or arguments.get("bedrooms"),
                            "project_category": merged_params.get("project_category") or arguments.get("project_category"),
                            "construction_state": merged_params.get("construction_state") or arguments.get("construction_state"),
                            "min_price": merged_params.get("min_price") or arguments.get("min_price"),
                            "max_price": merged_params.get("max_price") or arguments.get("max_price"),
                        }
                    )

                    if (
                        _search_key == self._last_search_key
                        and self.can_answer_result_count_from_state(_latest_user_raw)
                    ):
                        _count_recap = self.build_result_count_recap_response()
                        if _count_recap:
                            logger.info("[Pagination] Using deterministic shortlist count recap path")
                            self.filler_active = False
                            await _response_guard_bypass(_count_recap)
                            return

                    if (
                        _search_key == self._last_search_key
                        and self.has_exhausted_search_results()
                        and self.is_more_results_request(_latest_user_raw)
                    ):
                        _exhausted_reply = self.build_exhausted_results_response()
                        if _exhausted_reply:
                            logger.info("[Pagination] Reused exhausted shortlist response without backend call")
                            self.filler_active = False
                            await _response_guard_bypass(_exhausted_reply)
                            return

                    if _is_same_params:
                        # Same city/location/type/budget as last call AND we have
                        # already-shown slugs â†’ this is a "show more" request.
                        _next_page = self._jll_page + 1
                        arguments = {
                            **arguments,
                            "page": str(_next_page),
                            "exclude_slugs": json.dumps(sorted(self._shown_slugs)),
                        }
                        logger.info(
                            f"[Tool][Pagination] Auto show-more: page={_next_page}, "
                            f"excluding {len(self._shown_slugs)} shown slugs"
                        )
                    else:
                        # Params changed (new area / city / type / budget), first
                        # search in call, OR intent transitioned (e.g. returning to
                        # search_properties after areas_by_budget) â†’ fresh search.
                        _prior_intent = self._gathered_search.get("_search_intent", "")
                        if _prior_intent in ("city_wide_discovery", "project_detail"):
                            logger.info(
                                f"[Tool][Pagination] Slug cache cleared on intent transition "
                                f"(prior='{_prior_intent}' â†’ exact_locality)"
                            )
                        self._shown_slugs = set()
                        self._jll_page = 1
                        self._last_search_key = _search_key
                        self.clear_search_results_exhausted()
                        self._last_deliverable_result_count = 0
                        # Reset first-page tracking for fresh searches
                        self._first_page_had_results = False
                        self._first_page_count = 0
                        # [OrdinalMap] Reset both ordinal structures on fresh search so
                        # ordinals from a previous search don't leak into the new one.
                        self._detail_prefetch_generation += 1
                        self._cancel_detail_prefetches("fresh_search")
                        self._pending_deterministic_detail = None
                        self._clear_active_property()
                        self._ordinal_results = []
                        self._all_seen_slugs = set()
                        self._property_details_map.clear()
                        self._clear_detail_overview_memory("fresh_search")
                        logger.info("[OrdinalMap] reset on fresh search")
                        # [Fix-CacheReset] Clear pending fallback cache on new search so stale
                        # items from a previous search cannot be served under a different search key.
                        # The key-mismatch guard in the show_more path catches most cases, but
                        # clearing eagerly here prevents the stale flag _pending_backend_fetch from
                        # persisting into the next search context.
                        self._gathered_search.pop("_pending_fallback_items", None)
                        self._gathered_search.pop("_pending_key", None)
                        self._gathered_search.pop("_pending_backend_fetch", None)
                        self._gathered_search.pop("_pending_total_count", None)
                        self._gathered_search.pop("_pending_display_page", None)
                        self._gathered_search.pop("_search_exhausted", None)
                        logger.info("[Fix-CacheReset] Cleared pending fallback cache on new search")
                        arguments = {**arguments, "page": "1", "exclude_slugs": "[]"}
                        logger.info(
                            f"[Tool][Pagination] Fresh search (key changed) - reset slug tracking"
                        )

                # â”€â”€ P1-1: Consume cached fallback items for show_more â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                # If we have excess items from a previous fallback recovery, serve those
                # instead of hitting the backend again. This prevents losing items that were
                # recovered but not delivered due to page size limits.
                _pending_items = None
                if function_name == "search_properties" and _is_same_params:
                    _pending_key = self._gathered_search.get("_pending_key")
                    _pending_items = self._gathered_search.get("_pending_fallback_items")
                    _pending_backend_fetch = self._gathered_search.pop("_pending_backend_fetch", False)
                    _pending_fetch_after_buffer = bool(_pending_backend_fetch)

                    # Validate cache key matches current search params to prevent cross-search leaks
                    if _pending_items and _pending_key != _search_key:
                        logger.warning(f"[Pagination] Cache key mismatch - clearing stale cache. Expected: {_search_key}, Got: {_pending_key}")
                        self._gathered_search.pop("_pending_fallback_items", None)
                        self._gathered_search.pop("_pending_key", None)
                        _pending_items = None

                    # If _pending_backend_fetch flag is set, force backend call (cache was exhausted)
                    if not _pending_items and self._gathered_search.get("_search_exhausted"):
                        result = {
                            "success": True,
                            "data": [],
                            "has_more": False,
                            "current_page": arguments.get("page", str(self._jll_page + 1)),
                            "total_count": len(self._shown_slugs),
                            "_from_pending_cache": True,
                            "_end_of_listings": True,
                        }
                        logger.info("[Pagination] Search exhausted - serving end-of-listings from cache state")
                        goto_process_result = True
                    elif _pending_backend_fetch and not _pending_items:
                        logger.info("[Pagination] Cache exhausted previously - forcing backend fetch")
                        goto_process_result = False
                    elif _pending_items:
                        _page_size = int(arguments.get("result_count", PRESENTED_PROPERTY_LIMIT))
                        _items_to_serve = _pending_items[:_page_size]
                        _remaining = _pending_items[_page_size:] if len(_pending_items) > _page_size else []
                        _pending_total_count = int(self._gathered_search.get("_pending_total_count") or len(_pending_items))
                        _display_page = int(self._gathered_search.get("_pending_display_page") or arguments.get("page") or (self._jll_page + 1))

                        # Update pending cache
                        if _remaining:
                            self._gathered_search["_pending_fallback_items"] = _remaining
                            self._gathered_search["_pending_display_page"] = _display_page + 1
                            self._gathered_search["_pending_backend_fetch"] = _pending_fetch_after_buffer
                            logger.info(f"[Pagination] Serving {_page_size} cached items, {len(_remaining)} remain")
                            logger.info(f"[Pagination] serving_from_cache=True, remaining={len(_remaining)}")
                        else:
                            # Cache exhausted - clear both items and key to prevent dead state
                            self._gathered_search.pop("_pending_fallback_items", None)
                            self._gathered_search.pop("_pending_key", None)
                            self._gathered_search.pop("_pending_display_page", None)
                            if _pending_fetch_after_buffer:
                                self._gathered_search["_pending_backend_fetch"] = True
                                logger.info(f"[Pagination] Serving {len(_items_to_serve)} cached items (exhausted, will fetch backend next)")
                            else:
                                self._gathered_search["_search_exhausted"] = True
                                logger.info(f"[Pagination] Serving {len(_items_to_serve)} cached items (exhausted, no backend fetch needed)")

                        # Build mock result with cached items
                        # has_more: True if cache has remaining items, OR cache just got exhausted
                        # (backend fetch will be attempted on next "show more" via _pending_backend_fetch flag)
                        _has_more_cached = bool(_remaining) or self._gathered_search.get("_pending_backend_fetch", False)
                        _cached_result = {
                            "success": True,
                            "data": _items_to_serve,
                            "has_more": _has_more_cached,
                            "current_page": str(_display_page),
                            "total_count": _pending_total_count,
                            "_from_pending_cache": True,
                            "_source": "fallback_cache",
                        }

                        # Track shown slugs for these cached items
                        for item in _items_to_serve:
                            _slug = str(item.get("property_id") or item.get("project_slug") or "")
                            if _slug:
                                self._shown_slugs.add(_slug)
                                if "_property_slugs" not in self._gathered_search:
                                    self._gathered_search["_property_slugs"] = {}
                                self._gathered_search["_property_slugs"][_slug] = item.get("name", "")

                        # Skip backend call - use cached result
                        result = _cached_result
                        logger.info(f"[Tool] Serving {_cached_result['data'].__len__()} items from pending fallback cache")

                        # Jump directly to result processing (skip the backend call section)
                        goto_process_result = True
                    else:
                        goto_process_result = False
                else:
                    goto_process_result = False

                # â”€â”€ P1-2: Store search intent in session â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                # Written after pagination detection so we know show_more vs fresh.
                # Downstream guards (location fill, areas_by_budget, slug reset)
                # read _search_intent to scope their behaviour without re-detecting.
                if function_name == "search_properties":
                    if _is_same_params:
                        _cur_intent = "show_more"
                    elif merged_params.get("location"):
                        _cur_intent = "exact_locality"
                    else:
                        _cur_intent = "city_wide_discovery"
                    self._gathered_search["_search_intent"] = _cur_intent
                    logger.info(f"[Intent] search_properties â†’ '{_cur_intent}'")
                elif function_name == "areas_by_budget":
                    self._gathered_search["_search_intent"] = "city_wide_discovery"
                    logger.info("[Intent] areas_by_budget â†’ 'city_wide_discovery'")
                elif function_name == "get_property_details":
                    self._gathered_search["_search_intent"] = "project_detail"
                    logger.info("[Intent] get_property_details â†’ 'project_detail'")

                # â”€â”€ Auto-inject near_location for areas_by_budget â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                # When the user asks "what nearby areas have plots in my budget?"
                # after having searched a specific location (e.g. T Nagar), we auto-
                # pass near_location so the backend returns only areas within expanding
                # radius (5â†’10â†’15â†’20â†’30km) rather than the entire city list.
                #
                # IMPORTANT: Do NOT inject near_location for city-wide discovery queries
                # like "which area has cheapest apartments?" or "suggest any good area".
                # Those intents should search across the whole city. Injecting an old
                # session location (e.g. T Nagar from a prior search) would silently
                # constrain the result to near-T-Nagar and mislead the user.
                if function_name == "areas_by_budget":
                    # Detect city-wide discovery intent from recent user speech
                    _discovery_re = re.compile(
                        r'\b(which\s+area|cheapest|lowest\s+budget|lowest\s+price|best\s+area|'
                        r'where\s+can\s+I|suggest|any\s+area|city.?wide|overall|all\s+areas|'
                        r'anywhere|any\s+location|good\s+area|affordable\s+area)\b',
                        re.IGNORECASE
                    )
                    _last_u_abud = next(
                        (m.get("content", "") for m in reversed(getattr(context, "messages", []))
                         if m.get("role") == "user"),
                        ""
                    )
                    # City-wide if: discovery phrase present AND user/LLM didn't explicitly
                    # pass a location argument for this call
                    _abud_explicit_loc = arguments.get("location") or merged_params.get("location")
                    _is_city_wide_abud = bool(
                        _discovery_re.search(_last_u_abud) and not _abud_explicit_loc
                    )

                    if _is_city_wide_abud:
                        # Strip any location that leaked in from session memory
                        merged_params.pop("location", None)
                        merged_params.pop("near_location", None)
                        logger.info(
                            "[Tool][CityWide] Discovery intent detected - cleared location "
                            "for city-wide areas_by_budget (not injecting session near_location)"
                        )
                    else:
                        # Proximity-constrained query: inject near_location from current
                        # params (LLM may have set it) or from session (user previously
                        # searched a specific area and is now asking "what's nearby?").
                        # Do NOT pull from gathered_search when LLM didn't pass location -
                        # that's where the T Nagar leak comes from.
                        #
                        # HARD OVERRIDE: Skip near_location when user explicitly switched location
                        if merged_params.get("_location_override"):
                            logger.warning(
                                "[LocationOverride] DISABLED near_location injection - "
                                f"exact location override active ('{merged_params.get('_override_new_loc')}')"
                            )
                            merged_params.pop("near_location", None)
                        else:
                            _loc_for_proximity = (
                                merged_params.get("location")
                                or arguments.get("location")
                                # Only fall back to session location if LLM explicitly included
                                # "near" or "nearby" language in the user's request
                                or (
                                    self._gathered_search.get("location")
                                    if re.search(r'\b(near|nearby|close\s+to|around)\b', _last_u_abud, re.IGNORECASE)
                                    else None
                                )
                            )
                            if _loc_for_proximity:
                                merged_params = {**merged_params, "near_location": _loc_for_proximity}
                                logger.info(f"[Tool][Proximity] Auto near_location='{_loc_for_proximity}' for areas_by_budget")

                # â”€â”€ Inject sort_preference based on buyer persona â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                # Luxury â†’ price_desc (most expensive first)
                # Budget â†’ price_asc  (cheapest first)
                # Investor / Mid â†’ default (JLL natural order)
                if function_name == "search_properties":
                    _sort_map = {"luxury": "price_desc", "budget": "price_asc"}
                    _price_summary_request = self.is_area_price_summary_request(_latest_user_text)
                    _sort_pref = (
                        "price_asc"
                        if (_force_affordable_sort or _price_summary_request)
                        else _sort_map.get(self._persona, "default")
                    )
                    if _sort_pref != "default":
                        arguments = {**arguments, "sort_preference": _sort_pref}
                        merged_params = {**merged_params, "sort_preference": _sort_pref}
                        logger.info(f"[Persona] sort_preference={_sort_pref} (persona={self._persona})")

                # Use merged_params (includes gathered/cached values) not arguments (original LLM args)
                # This ensures location and other session-cached params are sent to backend.
                # Exception: pagination params (page, exclude_slugs) are set on `arguments` by
                # the show-more detection above - copy them into merged_params so they survive.
                if function_name == "search_properties":
                    for _pk in ("page", "exclude_slugs"):
                        if _pk in arguments and _pk not in merged_params:
                            merged_params[_pk] = arguments[_pk]
                _exec_params = merged_params if merged_params else arguments

                # â”€â”€ Strict location intent detection â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                # When user says "only X", "just X", "specifically X", set a session flag
                # so the zero-results handler won't offer nearby alternatives unsolicited.
                _strict_loc_re = re.compile(
                    r'\b(only|just|specifically|exclusively|strictly|not\s+anywhere\s+else)\b',
                    re.IGNORECASE,
                )
                _last_user_text = next(
                    (m.get("content", "") for m in reversed(getattr(context, "messages", []))
                     if m.get("role") == "user"), ""
                )
                if _strict_loc_re.search(_last_user_text):
                    self._gathered_search["_strict_location"] = True
                    logger.info(f"[Tool] Strict location flag set from user speech: {_last_user_text[:60]!r}")

                logger.info(
                    f"[Tool] CALLING backend: {endpoint.get('id')} | "
                    f"url={endpoint.get('url')} | args={list(_exec_params.keys())}"
                )

                # â”€â”€ RESPONSE GUARD: hard-bypass helper â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                # When a tool call fails (exception / timeout), this bypasses the LLM
                # entirely and pushes the fallback text directly to TTS.
                # Architecture: Tool-led, not LLM-led.
                #   â€¢ result_callback(run_llm=False) - stores error in context, no LLM
                #   â€¢ llm.push_frame(LLMTextFrame)   - text goes straight to TTS
                #   â€¢ context.messages.append(...)   - keep conversation history clean
                # This enforces the rule: "No tool success â†’ No LLM response."
                async def _response_guard_bypass(fallback_text: str) -> None:
                    await _cancel_interim_wait_message("response_guard")
                    logger.warning(
                        f"[ResponseGuard] Hard bypass activated for {function_name} - "
                        "LLM blocked, speaking fallback directly"
                    )
                    self._turn_llm_fired = True  # guard: block concurrent tool from also firing LLM
                    self._mark_terminal_tool_result_ready(function_name, run_llm=False)
                    try:
                        await result_callback(
                            {"success": False, "error": "bypassed", "tool": function_name},
                            properties=FunctionCallResultProperties(run_llm=False),
                        )
                    except Exception as _rc_err:
                        logger.warning(f"[ResponseGuard] result_callback(run_llm=False) failed: {_rc_err}")
                    try:
                        context.messages.append({"role": "assistant", "content": fallback_text})
                        self.remember_spoken_prompt(
                            fallback_text,
                            kind="assistant_reply",
                            question_expected=fallback_text.rstrip().endswith("?"),
                            source=f"response_guard:{function_name}",
                        )
                        logger.info(f"[Transcript] Appended deterministic assistant turn for {function_name}")
                    except Exception:
                        pass
                    try:
                        await llm.push_frame(LLMFullResponseStartFrame(), FrameDirection.DOWNSTREAM)
                        await llm.push_frame(LLMTextFrame(fallback_text), FrameDirection.DOWNSTREAM)
                        await llm.push_frame(LLMFullResponseEndFrame(), FrameDirection.DOWNSTREAM)
                    except Exception as _push_err:
                        logger.warning(f"[ResponseGuard] Frame push failed: {_push_err} - falling back to speech_instruction")
                        self.clear_terminal_tool_response_flags("response_guard_push_failed")
                    if call_key in self._in_flight_calls:
                        fut = self._in_flight_calls[call_key]
                        if not fut.done():
                            fut.set_result(json.dumps({"bypassed": True}))
                        del self._in_flight_calls[call_key]

                # â”€â”€ Backend call (skip if using cached fallback items) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                if not goto_process_result:
                    # â”€â”€ Retry once on failure â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                    # First attempt: full 10s timeout (inherited from http_client).
                    # On error/timeout â†’ wait 400ms â†’ retry once with same params.
                    # After 2 failures â†’ hard bypass (LLM never runs, fallback spoken).
                    _tool_t0 = time.time()
                    _retry_result = None
                    _retry_ex = None
                    for _attempt in range(2):  # 0 = first try, 1 = retry
                        try:
                            _retry_result = await self._execute_endpoint(endpoint, _exec_params)
                            # Break on success or on HTTP-level error (e.g. 404) - those are
                            # informative responses we pass to LLM with speech_instruction.
                            # Only retry on True exception (timeout, network, etc.).
                            break
                        except Exception as _ex:
                            _retry_ex = _ex
                            if _attempt == 0:
                                logger.warning(
                                    f"[Tool] {function_name} attempt 1 failed ({type(_ex).__name__}) - "
                                    "retrying in 400ms"
                                )
                                await asyncio.sleep(0.4)
                            # else: second attempt also failed - _retry_ex is set, fall through

                    _tool_ms = int((time.time() - _tool_t0) * 1000)

                    if _retry_ex is not None:
                        # Both attempts raised exceptions - hard bypass LLM
                        logger.error(f"\u274C [Tool] {function_name} failed after retry ({_retry_ex!r}) [{_tool_ms}ms]")
                        self._latency_trace_ref[0]["tool_end"] = time.time()
                        self.filler_active = False
                        await _response_guard_bypass(
                            "I'm sorry, I'm having trouble fetching that right now. "
                            f"Would you like me to try again? {_callback_offer_text()}"
                        )
                        return

                    result = _retry_result
                    logger.info(f"â± Tool {endpoint.get('id')} backend {_tool_ms}ms")

                # â”€â”€ Anti-hallucination guard for HTTP-level errors â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                # _execute_endpoint returns {success: False, error: ...} for 4xx/5xx.
                # Inject a strict speech_instruction so the LLM cannot generate
                # fabricated property data when the backend call fails.
                if result.get("success") is False and result.get("error") and "speech_instruction" not in result:
                    result["speech_instruction"] = (
                        "BACKEND ERROR - CRITICAL SAFETY RULE: "
                        "Do NOT fabricate or guess ANY property names, prices, or listings. "
                        "Do NOT reuse data from earlier in the conversation. "
                        "Say: 'I'm sorry, I'm having trouble fetching that information. "
                        "Shall I try again, or would you prefer that I have a JLL Homes property specialist call you back?'"
                    )
                    logger.warning(
                        f"[Tool] {function_name} returned error={result.get('error')} - "
                        "injected anti-hallucination speech_instruction"
                    )

                # â”€â”€ UNIFIED LOCATION VALIDATION - unconditional, backend-metadata-independent â”€â”€
                # Replaces the old FIX 1 (soft caveat) and FIX 2 (fallback_occurred-dependent).
                #
                # Design principle: validation must not rely on backend metadata flags
                # (fallback_occurred, search_scope) that may be absent (old cache hit,
                # response format change, etc.). Instead we validate EVERY result set
                # directly against the requested location using _strict_location_match(),
                # which uses exact name + alias expansion + long-token fallback.
                #
                # Fires when:
                #   â€¢ function_name == "search_properties"
                #   â€¢ user provided an explicit location (merged_params["location"] set)
                #   â€¢ result data is non-empty
                #
                # Exceptions (not blocked):
                #   â€¢ budget_mismatch_results - backend fetched the EXACT location without
                #     budget filter; the properties ARE in the right area, just over budget.
                #     _strict_location_match would pass anyway, but we skip for clarity.
                #
                # Action on majority mismatch (â‰¥50% of items fail strict match):
                #   Hard-clear result["data"] â†’ LLM never sees wrong-location properties.
                if (
                    function_name == "search_properties"
                    and merged_params.get("location")
                    and result.get("data")
                    and not result.get("budget_mismatch_results")
                ):
                    _val_loc = merged_params["location"]
                    _val_mismatch = sum(
                        0 if _strict_location_match(_val_loc, _item) else 1
                        for _item in result["data"]
                    )
                    _val_total = len(result["data"])
                    if _val_mismatch >= (_val_total + 1) // 2:
                        logger.warning(
                            f"[LocationGuard] {_val_mismatch}/{_val_total} items fail "
                            f"strict match for '{_val_loc}' - hard-clearing results"
                        )
                        result = {
                            **result,
                            "data": [],
                            "has_more": False,
                            # [Fix-TotalCount] Align total_count with deliverable count.
                            # Backend total_count (e.g. 12) reflects pre-filter state and
                            # would mislead the LLM into claiming more properties exist.
                            "total_count": 0,
                            "no_exact_match": True,
                            "speech_instruction": (
                                f"I couldn't find properties that reliably match {_val_loc}. "
                                f"Would you like to explore nearby areas or adjust your search?"
                            ),
                        }
                    elif _val_mismatch > 0:
                        # Partial mismatch (minority) - filter out the bad items rather
                        # than nuking the whole result set.
                        _val_clean = [
                            _item for _item in result["data"]
                            if _strict_location_match(_val_loc, _item)
                        ]
                        if len(_val_clean) < _val_total:
                            logger.info(
                                f"[LocationGuard] Filtered {_val_total - len(_val_clean)} "
                                f"mismatched items from results for '{_val_loc}' "
                                f"({len(_val_clean)} remain)"
                            )
                            # [Fix-TotalCount] Update total_count to deliverable count after
                            # minority filtering so the LLM never claims a count it cannot deliver.
                            # Conservative has_more: if we filtered items, we can't know if the
                            # next backend page would also fail validation, so set has_more=False
                            # when significant filtering occurred (>1 item removed).
                            _filtered_count = _val_total - len(_val_clean)
                            _conservative_has_more = result.get("has_more", False) and _filtered_count <= 1
                            result = {
                                **result,
                                "data": _val_clean,
                                "total_count": len(_val_clean),
                                "has_more": _conservative_has_more,
                            }
                            logger.info(
                                f"[Fix-TotalCount] total_count updated to {len(_val_clean)}, "
                                f"has_more={_conservative_has_more} (filtered {_filtered_count} items)"
                            )

                if (
                    function_name == "search_properties"
                    and result.get("data")
                    and merged_params.get("bedrooms")
                ):
                    _requested_bedrooms = self._normalize_bedroom_value(
                        merged_params.get("bedrooms") or arguments.get("bedrooms")
                    )
                    if _requested_bedrooms:
                        _requested_count = max(
                            1,
                            int(
                                merged_params.get("result_count")
                                or arguments.get("result_count")
                                or PRESENTED_PROPERTY_LIMIT
                            ),
                        )
                        _visible_items = result.get("data") or []
                        _buffered_items = result.get("buffered_page_items") or []
                        _filtered_visible, _filtered_buffer, _dropped_bhk = (
                            self._filter_search_results_for_requested_bedrooms(
                                _visible_items,
                                _buffered_items,
                                _requested_bedrooms,
                                desired_count=_requested_count,
                            )
                        )
                        if _dropped_bhk:
                            logger.warning(
                                f"[BedroomGuard] Filtered {_dropped_bhk} non-matching item(s) "
                                f"for requested {self._format_bedroom_label(_requested_bedrooms)}"
                            )
                        if not _filtered_visible:
                            _guard_loc = (
                                merged_params.get("location")
                                or result.get("searched_location")
                                or arguments.get("location")
                                or "this area"
                            )
                            _guard_type = (
                                merged_params.get("property_type")
                                or result.get("searched_property_type")
                                or arguments.get("property_type")
                                or "properties"
                            )
                            result = {
                                **result,
                                "data": [],
                                "buffered_page_items": [],
                                "has_more": False,
                                "has_more_beyond_buffer": False,
                                "total_count": 0,
                                "zero_results_scope": "locality_only",
                                "speech_instruction": (
                                    f"I couldn't find any {self._format_bedroom_label(_requested_bedrooms)} "
                                    f"{str(_guard_type).strip().lower()} in {_guard_loc} matching that search. "
                                    "Would you like to adjust the budget, explore another area, or try a different configuration?"
                                ),
                            }
                            logger.warning(
                                f"[BedroomGuard] No deliverable results remained after enforcing "
                                f"{self._format_bedroom_label(_requested_bedrooms)}"
                            )
                        else:
                            _deliverable_total = len(_filtered_visible) + len(_filtered_buffer)
                            result = {
                                **result,
                                "data": _filtered_visible,
                                "buffered_page_items": _filtered_buffer,
                                "total_count": _deliverable_total,
                                "has_more": bool(_filtered_buffer) or bool(result.get("has_more_beyond_buffer")),
                            }
                            logger.info(
                                f"[BedroomGuard] Enforced {self._format_bedroom_label(_requested_bedrooms)} "
                                f"results: visible={len(_filtered_visible)} buffered={len(_filtered_buffer)}"
                            )

                if (
                    function_name == "search_properties"
                    and not result.get("data")
                    and result.get("zero_results_scope") == "locality_only"
                ):
                    _zr_loc = result.get("searched_location") or arguments.get("location") or "this locality"
                    _zr_city = result.get("searched_city") or arguments.get("city") or "this city"
                    _zr_type = result.get("searched_property_type") or arguments.get("property_type") or "properties"
                    _zr_type_single = _property_type_singular_label(_zr_type)
                    _zr_type_plural = _property_type_plural_label(_zr_type)
                    _zr_area_phrase = "this area"
                    def _has_positive_price_filter(value) -> bool:
                        try:
                            return int(float(value or 0)) > 0
                        except (TypeError, ValueError):
                            return False

                    _has_budget_filter = any(
                        _has_positive_price_filter(
                            merged_params.get(_key)
                            or arguments.get(_key)
                            or self._gathered_search.get(_key)
                        )
                        for _key in ("min_price", "max_price")
                    )
                    if _has_budget_filter:
                        _zr_unavailable = (
                            f"There are no {_zr_type_plural} available in {_zr_area_phrase} "
                            "within that budget right now."
                        )
                    else:
                        _zr_unavailable = f"There are no {_zr_type_plural} available in {_zr_area_phrase} right now."

                    _has_shown_properties = len(self._shown_slugs) > 0

                    _is_end_of_listings = (
                        result.get("_end_of_listings")
                        or (
                            not result.get("data")
                            and getattr(self, '_first_page_had_results', False)
                            and int(result.get("current_page", 1)) > 1
                        )
                        or (_has_shown_properties and int(result.get("current_page", 1)) > 1)
                    )

                    if _is_end_of_listings:
                        _shown_count = len(self._shown_slugs)
                        self._has_live_results = True
                        self._last_deliverable_result_count = _shown_count
                        self.mark_search_results_exhausted()
                        self._gathered_search["_search_exhausted"] = True
                        self.set_zero_result_state("exhausted_shortlist", branch="show_more")
                        logger.info(
                            f"[HasLiveResults] Preserved True - exhausted show_more for locality_only count={_shown_count}"
                        )
                        _end_speech = self.build_exhausted_results_response()
                        if not _end_speech:
                            _end_speech = (
                                f"I've already shared all matching properties in {_zr_loc} within your budget. "
                                f"Would you like details on one of these, or should I suggest nearby areas?"
                            )
                        self.set_zero_result_state("exhausted_shortlist", branch="show_more", response_text=_end_speech)
                        logger.info(f"[Pagination] Empty pagination detected for {_zr_loc} ({_shown_count} total shown)")
                        if not _strict_loc_mode:
                            self._enter_budget_confirmation(
                                "zero_results_followup",
                                search_scope_snapshot={
                                    "city": _zr_city,
                                    "location": _zr_loc,
                                    "property_type": _zr_type,
                                    "min_price": self._gathered_search.get("min_price"),
                                    "max_price": self._gathered_search.get("max_price"),
                                },
                                awaiting_amount_only=False,
                            )
                        self.filler_active = False
                        await _response_guard_bypass(_end_speech)
                        return
                    else:
                        # Zero results - clear live results flag so GatherStateHint fires again
                        self._has_live_results = False
                        self.clear_search_results_exhausted()
                        self._last_deliverable_result_count = 0
                        logger.info("[HasLiveResults] Set False - zero results for locality_only")

                        if _has_budget_filter:
                            try:
                                _fallback_params = {
                                    "city": (
                                        merged_params.get("city")
                                        or arguments.get("city")
                                        or result.get("searched_city")
                                        or _zr_city
                                    ),
                                    "location": (
                                        merged_params.get("location")
                                        or arguments.get("location")
                                        or result.get("searched_location")
                                        or _zr_loc
                                    ),
                                    "property_type": (
                                        merged_params.get("property_type")
                                        or arguments.get("property_type")
                                        or result.get("searched_property_type")
                                        or _zr_type
                                    ),
                                    "result_count": max(
                                        PRESENTED_PROPERTY_LIMIT,
                                        int(
                                            merged_params.get("result_count")
                                            or arguments.get("result_count")
                                            or PRESENTED_PROPERTY_LIMIT
                                        ),
                                    ),
                                    "page": 1,
                                }
                                for _optional_key in ("bedrooms", "project_category", "construction_state"):
                                    _optional_value = merged_params.get(_optional_key) or arguments.get(_optional_key)
                                    if _optional_value:
                                        _fallback_params[_optional_key] = _optional_value

                                _user_min_price = (
                                    merged_params.get("min_price")
                                    or arguments.get("min_price")
                                    or self._gathered_search.get("min_price")
                                )
                                _user_max_price = (
                                    merged_params.get("max_price")
                                    or arguments.get("max_price")
                                    or self._gathered_search.get("max_price")
                                )
                                logger.info(
                                    f"[ZeroResults] Checking exact locality without budget before speaking "
                                    f"params={_fallback_params}"
                                )
                                _locality_fallback = await self._execute_endpoint(endpoint, _fallback_params)
                                _fallback_items = (
                                    _locality_fallback.get("data")
                                    if isinstance(_locality_fallback, dict)
                                    else None
                                )
                                if isinstance(_fallback_items, list) and _fallback_items:
                                    _fallback_loc = str(_fallback_params.get("location") or "").strip()
                                    if _fallback_loc:
                                        _fallback_items = [
                                            _item for _item in _fallback_items
                                            if isinstance(_item, dict) and _strict_location_match(_fallback_loc, _item)
                                        ]
                                    if _fallback_items:
                                        _fallback_prices = [
                                            _extract_search_item_min_price(_item)
                                            for _item in _fallback_items
                                            if isinstance(_item, dict)
                                        ]
                                        _fallback_prices = [_price for _price in _fallback_prices if _price > 0]
                                        _mismatch_result = {
                                            **(_locality_fallback if isinstance(_locality_fallback, dict) else {}),
                                            "data": _fallback_items,
                                            "budget_mismatch_results": True,
                                            "user_min_price": _user_min_price,
                                            "user_max_price": _user_max_price,
                                            "searched_location": _fallback_loc or _zr_loc,
                                            "searched_city": _fallback_params.get("city") or _zr_city,
                                            "searched_property_type": _fallback_params.get("property_type") or _zr_type,
                                            "area_min_price": (
                                                _format_price_indian(min(_fallback_prices))
                                                if _fallback_prices else None
                                            ),
                                            "area_max_price": (
                                                _format_price_indian(max(_fallback_prices))
                                                if _fallback_prices else None
                                            ),
                                            "total_count": len(_fallback_items),
                                            "has_more": False,
                                        }
                                        _mismatch_speech = _build_locality_budget_mismatch_speech(_mismatch_result)
                                        if _mismatch_speech:
                                            self.set_zero_result_state(
                                                "fresh_zero_results",
                                                branch="budget_mismatch_locality",
                                                response_text=_mismatch_speech,
                                            )
                                            if _fallback_prices:
                                                self.set_pending_user_offer(
                                                    "zero_result_price_range",
                                                    location=_fallback_loc or _zr_loc,
                                                    min_price=min(_fallback_prices),
                                                    max_price=max(_fallback_prices),
                                                    source="locality_budget_mismatch",
                                                )
                                            logger.info(
                                                f"[ZeroResults] exact locality has {len(_fallback_items)} "
                                                f"out-of-budget result(s); speaking budget mismatch"
                                            )
                                            self.filler_active = False
                                            await _response_guard_bypass(_mismatch_speech)
                                            return
                            except Exception as _zr_fallback_err:
                                logger.warning(
                                    f"[ZeroResults] Locality fallback without budget failed: {_zr_fallback_err}"
                                )

                        # FIX: Clear all property caches to prevent stale data injection
                        # When search returns zero results, old cached properties from previous
                        # searches must be cleared to prevent DirectInject from "inventing" properties
                        self._detail_prefetch_generation += 1
                        self._cancel_detail_prefetches("zero_results")
                        self._pending_deterministic_detail = None
                        self._clear_active_property()
                        self._ordinal_results = []
                        self._all_seen_slugs = set()
                        self._property_details_map.clear()
                        self._clear_detail_overview_memory("zero_results")
                        self._slug_cache.clear()
                        self._name_to_slug.clear()
                        self._shown_slugs = set()
                        self._first_page_had_results = False
                        self._clear_shortlist_context("zero_results")
                        self._conversation_scope_key = ""
                        logger.info("[ZeroResults] Cleared all property caches (ordinal, slug, shown)")

                        # True zero-results case
                        # True zero-results case - BYPASS LLM entirely to prevent hallucination.
                        # gpt-4.1-nano can invent properties when handed empty results plus
                        # presentation rules. We speak canned text directly; LLM never fires.
                        _strict_loc_mode = self._gathered_search.get("_strict_location", False)
                        _sugg = result.get("suggested_areas") or []
                        _min_avail = result.get("min_price_available")

                        if _sugg and not _strict_loc_mode and len(_sugg) >= 2:
                            _canned = (
                                f"{_zr_unavailable} "
                                f"I found some options in {_sugg[0]} and {_sugg[1]} instead. "
                                f"Would you like to explore these, or would you prefer to adjust your budget for {_zr_loc}?"
                            )
                            self._set_zero_result_followup_state(
                                mode="awaiting_budget_or_area_choice",
                                location=_zr_loc,
                                city=_zr_city,
                                property_type=_zr_type,
                            )
                            self.set_zero_result_state("fresh_zero_results", branch="other_areas", response_text=_canned)
                        elif _min_avail:
                            try:
                                _min_lakh = int(_min_avail) // 100000
                                _canned = (
                                    f"{_zr_unavailable} "
                                    f"Properties there start from around {_min_lakh} lakhs. "
                                    f"Would you like to adjust your budget, or shall I suggest other locations within your budget?"
                                )
                            except (TypeError, ValueError):
                                _canned = (
                                    f"{_zr_unavailable} "
                                    f"Would you like to adjust your budget, or shall I suggest other locations within your budget?"
                                )
                            self._set_zero_result_followup_state(
                                mode="awaiting_budget_or_area_choice",
                                location=_zr_loc,
                                city=_zr_city,
                                property_type=_zr_type,
                            )
                            self.set_zero_result_state("fresh_zero_results", branch="budget_or_areas", response_text=_canned)
                        elif _strict_loc_mode:
                            _canned = (
                                f"{_zr_unavailable} "
                                f"Would you like to check a different location? {_callback_offer_text()}"
                            )
                            self._clear_zero_result_followup_state()
                            self.clear_zero_result_state("strict_location_zero_results")
                        else:
                            _zr_loc_spoken = re.sub(r"\bT\.\s*Nagar\b", "T Nagar", str(_zr_loc or ""), flags=re.IGNORECASE)
                            _canned = (
                                f"{_zr_unavailable} "
                                f"Would you like to try {_zr_type_plural} in another area, or a different budget?"
                            )
                            self._set_zero_result_followup_state(
                                mode="awaiting_budget_or_area_choice",
                                location=_zr_loc,
                                city=_zr_city,
                                property_type=_zr_type,
                            )
                            self.set_zero_result_state("fresh_zero_results", branch="budget_or_areas", response_text=_canned)

                        logger.info(f"[ZeroResultBypass] LLM blocked - canned: {_canned[:80]!r}")
                        self.filler_active = False
                        await _response_guard_bypass(_canned)

                        # FIX: Strip stale CURRENT SEARCH RESULTS block from system prompt
                        # After zero results, old results from previous searches must be removed
                        # to prevent the LLM from referencing properties that no longer exist
                        if self._context_ref and self._context_ref[0]:
                            try:
                                _ctx = self._context_ref[0]
                                _base = _ctx.messages[0]["content"]
                                # Remove CURRENT SEARCH RESULTS block
                                _base = re.sub(
                                    r'\n\nCURRENT SEARCH RESULTS:.*?(?=\n\n[A-Z]|\Z)',
                                    "",
                                    _base,
                                    flags=re.DOTALL,
                                )
                                # Also strip old format with --- delimiters (backward compat)
                                _base = re.sub(
                                    r'\n\n---\nCURRENT SEARCH RESULTS.*?---',
                                    "",
                                    _base,
                                    flags=re.DOTALL,
                                )
                                _ctx.messages[0]["content"] = _base
                                logger.info("[ZeroResults] Stripped stale CURRENT SEARCH RESULTS block")
                            except Exception as _strip_err:
                                logger.debug(f"[ZeroResults] Failed to strip results block: {_strip_err}")

                        # FIX: Persist confirmed params as a system message for next turn
                        _confirmed_snapshot = {}
                        for _k in ['city', 'property_type', 'location',
                                   'min_price', 'max_price']:
                            if self._gathered_search.get(_k):
                                _confirmed_snapshot[_k] = self._gathered_search[_k]

                        if _confirmed_snapshot and self._context_ref and self._context_ref[0]:
                            # Remove any previous confirmed-params injection
                            _ctx = self._context_ref[0]
                            _filtered_messages = [
                                m for m in _ctx.messages
                                if not (m.get('role') == 'system' and
                                        '[CONFIRMED PARAMS]' in m.get('content', ''))
                            ]
                            _ctx.messages[:] = _filtered_messages
                            # Add fresh snapshot
                            _ctx.messages.append({
                                "role": "system",
                                "content": (
                                    f"[CONFIRMED PARAMS] The following details are already "
                                    f"confirmed from earlier in this conversation and must NOT "
                                    f"be re-asked: {_confirmed_snapshot}. "
                                    f"If the user wants to change location or budget, update "
                                    f"only that field and search again immediately."
                                )
                            })
                            logger.info(
                                f"[ZeroResults] Injected confirmed-params snapshot: "
                                f"{list(_confirmed_snapshot.keys())}"
                            )
                        return

                # â”€â”€ Budget-mismatch-results: automatic fallback search returned properties â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                # When the user's budget returns 0 results, the backend automatically searched
                # without budget filter and found properties. These properties exist in the area
                # but are outside the user's budget range.
                if _is_stale_tool_turn():
                    await _finish_stale(result)
                    return

                if function_name == "search_properties" and result.get("budget_mismatch_results"):
                    _bm_loc = result.get("searched_location") or arguments.get("location", "this area")
                    _bm_area_min = result.get("area_min_price", "N/A")
                    _bm_area_max = result.get("area_max_price", "N/A")
                    _bm_user_min = result.get("user_min_price")
                    _bm_user_max = result.get("user_max_price")
                    # Format user's budget for display
                    if _bm_user_min or _bm_user_max:
                        _bm_user_budget = f"{_bm_user_min or 'any'} - {_bm_user_max or 'any'}"
                    else:
                        _bm_user_budget = "unspecified"
                    result = {
                        **result,
                        "speech_instruction": (
                            f"These properties are in {_bm_loc} but their prices ({_bm_area_min} to {_bm_area_max}) "
                            f"are outside the user's requested budget range ({_bm_user_budget}). "
                            f"Start by saying: 'I found some properties in {_bm_loc}, but they range from {_bm_area_min} to {_bm_area_max}, "
                            f"which is a bit different from your budget. Here are the available options...' "
                            f"Then present the properties naturally from the data array. "
                            f"If the user says 'that's too expensive' or 'out of my budget', offer the suggested_areas from the response."
                        ),
                    }
                    logger.info(
                        f"[BudgetMismatchResults] Found {len(result.get('data', []))} properties in {_bm_loc} "
                        f"(price range: {_bm_area_min}-{_bm_area_max}, user budget: {_bm_user_budget})"
                    )

                # â”€â”€ Budget-too-low flag: set one-time skip for next search â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                # When the backend says the user's budget is below the area minimum,
                # set a flag so the NEXT search_properties call ignores the cached
                # budget (one-time only), allowing the LLM to search without a price
                # cap so the user can see what's actually available in that area.
                # NOTE: This is now only triggered when budget_mismatch_results fallback also returned 0 results
                if function_name == "search_properties" and result.get("budget_too_low"):
                    self._gathered_search["_budget_too_low_pending"] = True
                    # Lock the confirmed city/location/type so the retry uses them
                    # even if the user's "increase my budget" utterance gets garbled by STT.
                    self._budget_too_low_context = {
                        k: (arguments.get(k) or self._gathered_search.get(k))
                        for k in ("city", "property_type", "location")
                        if (arguments.get(k) or self._gathered_search.get(k))
                    }
                    _btl_loc   = result.get("searched_location") or arguments.get("location", "this area")
                    _btl_min   = result.get("area_min_price", "a higher price")
                    _btl_min_vals = _parse_inr_amounts(str(_btl_min))
                    if _btl_min_vals:
                        self._budget_too_low_context["area_min_price_value"] = max(_btl_min_vals)
                    self._budget_too_low_context["area_min_price"] = _btl_min
                    _btl_true_min_value = int(self._budget_too_low_context.get("area_min_price_value") or 0)
                    try:
                        _btl_price_params = {
                            "city": self._budget_too_low_context.get("city") or merged_params.get("city") or arguments.get("city") or "Chennai",
                            "location": self._budget_too_low_context.get("location") or merged_params.get("location") or arguments.get("location") or _btl_loc,
                            "property_type": (
                                self._budget_too_low_context.get("property_type")
                                or merged_params.get("property_type")
                                or arguments.get("property_type")
                                or result.get("searched_property_type")
                                or "properties"
                            ),
                            "min_price": 0,
                            "max_price": 50_000_000,
                            "result_count": 20,
                            "sort_preference": "price_asc",
                        }
                        for _optional_key in ("bedrooms", "project_category", "construction_state"):
                            _optional_value = merged_params.get(_optional_key) or arguments.get(_optional_key)
                            if _optional_value:
                                _btl_price_params[_optional_key] = _optional_value
                        _btl_price_result = await self._execute_endpoint(endpoint, _btl_price_params)
                        _btl_price_items = _btl_price_result.get("data") if isinstance(_btl_price_result, dict) else None
                        if isinstance(_btl_price_items, list) and _btl_price_items:
                            _btl_requested_loc = str(_btl_price_params.get("location") or "").strip()
                            if _btl_requested_loc:
                                _btl_price_items = [
                                    _item for _item in _btl_price_items
                                    if isinstance(_item, dict) and _strict_location_match(_btl_requested_loc, _item)
                                ]
                            _btl_prices = [
                                _extract_search_item_min_price(_item)
                                for _item in _btl_price_items
                                if isinstance(_item, dict)
                            ]
                            _btl_prices = [_price for _price in _btl_prices if _price > 0]
                            if _btl_prices:
                                _btl_true_min_value = min(_btl_prices)
                                self._budget_too_low_context["area_min_price_value"] = _btl_true_min_value
                                self._budget_too_low_context["area_min_price"] = _format_price_indian(_btl_true_min_value)
                                _btl_min = self._budget_too_low_context["area_min_price"]
                                logger.info(
                                    f"[BudgetTooLow] verified exact-locality floor={_btl_min} "
                                    f"location={_btl_price_params.get('location')!r}"
                                )
                    except Exception as _btl_verify_err:
                        logger.warning(f"[BudgetTooLow] Failed to verify exact-locality floor: {_btl_verify_err}")
                    direct_spoken_result = _build_budget_too_low_speech(
                        self._budget_too_low_context.get("property_type")
                        or merged_params.get("property_type")
                        or arguments.get("property_type")
                        or result.get("searched_property_type"),
                        self._budget_too_low_context.get("location") or _btl_loc,
                        _btl_true_min_value,
                    )
                    _btl_instruction_text = direct_spoken_result or (
                        f"Properties in {_btl_loc} start from {_btl_min}. "
                        f"Would you like to adjust the budget for {_btl_loc}, or look for other areas?"
                    )
                    result = {
                        **result,
                        "speech_instruction": (
                            f"This budget message is ONLY about {_btl_loc}. "
                            f"When you speak, say '{_btl_instruction_text}' "
                            "or equivalent. Do NOT describe this as the starting price for the whole city."
                        ),
                        "scope": "locality_only",
                    }
                    logger.info(
                        f"[BudgetTooLow] area_min_price={_btl_min} - "
                        f"next search will skip budget filter | locked ctx={self._budget_too_low_context}"
                    )
                    # Inject a PENDING BUDGET DECISION block into the system message so the
                    # LLM knows exactly what to do when the user says "show me anyway" /
                    # "I'm okay with it" / "increase my budget" - without any extra gathering.
                    if self._context_ref:
                        try:
                            _ctx = self._context_ref[0]
                            _btl_city = self._budget_too_low_context.get("city", "")
                            _btl_type = self._budget_too_low_context.get("property_type", "")
                            _btl_loc2 = self._budget_too_low_context.get("location", _btl_loc)
                            _pending_lines = [
                                "\n\n---",
                                "PENDING BUDGET DECISION - ACT ON THIS IMMEDIATELY:",
                                f"The user asked about {_btl_loc2} but their budget is below the area minimum ({_btl_min}).",
                                f"All session fields are LOCKED and confirmed: city={_btl_city}, location={_btl_loc2}, property_type={_btl_type}.",
                                "WHEN USER SAYS: yes / okay / show me / I'll go with it / increase my budget / I'm fine / that's okay / I'll manage â†’ call search_properties IMMEDIATELY",
                                f"  Use EXACTLY: city={_btl_city!r}, location={_btl_loc2!r}, property_type={_btl_type!r} - NO budget filter (min_price/max_price must be omitted).",
                                "  Do NOT ask for area, city, type, or budget again - all fields are already confirmed.",
                                "  Do NOT re-explain the price situation - user already knows. Just say 'Sure, let me find those for you.' and call the tool.",
                                # Include the suggested areas INLINE so the LLM has them
                                # even after _prune_old_tool_messages removes the tool result.
                                # Previously we said "use the suggested_areas list from the last
                                # tool result" - but that result is pruned on the next turn, so
                                # the LLM couldn't find the areas and repeated the same question.
                                *([
                                    f"WHEN USER SAYS: suggest other areas / no â†’ read these areas to the user: "
                                    f"{', '.join(str(a) for a in result.get('suggested_areas', [])[:4])}. "
                                    f"Ask which area interests them, then call search_properties immediately."
                                ] if result.get("suggested_areas") else [
                                    "WHEN USER SAYS: suggest other areas / no â†’ call areas_by_budget with "
                                    f"city={_btl_city!r}, property_type={_btl_type!r} and the user's budget to find suitable areas."
                                ]),
                                "---",
                            ]
                            _pending_block = "\n".join(_pending_lines)
                            _base = _ctx.messages[0]["content"]
                            # Remove any previous PENDING block before inserting updated one
                            _base = re.sub(
                                r'\n\n---\nPENDING BUDGET DECISION.*?---',
                                "",
                                _base,
                                flags=re.DOTALL,
                            )
                            _ctx.messages[0]["content"] = _base + _pending_block
                            logger.info(
                                f"[BudgetTooLow] Injected PENDING BUDGET DECISION block into system prompt"
                            )
                        except Exception as _btl_ctx_err:
                            logger.warning(f"[BudgetTooLow] Failed to inject pending block: {_btl_ctx_err}")

                # Populate property cache after a successful search
                if function_name == "search_properties" and result.get("success"):
                    items = result.get("data", [])
                    # Set _has_live_results flag for GatherStateHint condition
                    if items:
                        self._has_live_results = True
                        self.clear_search_results_exhausted()
                        self._clear_zero_result_followup_state()
                        self.clear_zero_result_state("results_found")
                        self.clear_pending_budget_confirmation("results_found")
                        self._gathered_search.pop("_search_exhausted", None)
                        logger.info(f"[HasLiveResults] Set True - {len(items)} properties found")
                    if isinstance(items, list):
                        # Backend already trims to 5 - pass items as-is to LLM
                        # Track which slugs we've shown (for exclude_slugs on next page request)
                        _new_slugs = {
                            str(item.get("property_id") or item.get("project_slug") or "")
                            for item in items
                            if item.get("property_id") or item.get("project_slug")
                        }
                        self._shown_slugs.update(_new_slugs)
                        _from_pending_cache = bool(result.get("_from_pending_cache"))
                        if not _from_pending_cache:
                            self._jll_page = int(result.get("current_page", self._jll_page))
                        # Track first-page results for end-of-listings detection
                        _current_page = int(result.get("current_page", 1))
                        _has_more = result.get("has_more", False)

                        # Determine page size from request params
                        _page_size = int(arguments.get("result_count", PRESENTED_PROPERTY_LIMIT))

                        # Override has_more if we got fewer results than page size
                        # Backend total_count is unreliable - use actual result count
                        if len(items) < _page_size:
                            _has_more = False
                        if result.get("buffered_page_items") or result.get("has_more_beyond_buffer", False):
                            _has_more = True

                        if _current_page == 1 and items:
                            self._first_page_had_results = True
                            self._first_page_count = len(items)
                            self._last_deliverable_result_count = len(items)
                            self._pagination_fallback_attempted = False  # Reset fallback tracking

                        elif _current_page > 1 and not items:
                            # End-of-listings detection: page 2+ returned empty
                            # Check if we should attempt fallback recovery
                            if not self._pagination_fallback_attempted:
                                # First empty page - try fallback recovery
                                result["_filtered_empty_page"] = True
                                result["_fallback_needed"] = True
                                logger.info(
                                    f"[Pagination] Empty page { _current_page} - will attempt fallback recovery"
                                )
                            else:
                                # Fallback already attempted - this is true exhaustion
                                result["_end_of_listings"] = True
                                logger.info(
                                    f"[Pagination] End of listings: page={_current_page} empty, "
                                    f"fallback already attempted, has_more={_has_more}"
                                )

                        # Override has_more when we got fewer results than page size
                        # This fixes backend inconsistencies with total_count
                        _effective_has_more = _has_more and len(items) >= _page_size

                        logger.info(
                            f"[Tool][Pagination] Updated: jll_page={self._jll_page}, "
                            f"total_shown={len(self._shown_slugs)}, this_page={len(items)}, "
                            f"has_more={_effective_has_more}"
                        )
                        if self._shown_slugs:
                            self._last_deliverable_result_count = max(
                                self._last_deliverable_result_count,
                                len(self._shown_slugs),
                            )
                        result = {
                            **result,
                            "data": items,
                            "has_more": _effective_has_more,
                        }
                        _buffered_page_items = result.get("buffered_page_items") or []
                        if not _from_pending_cache and _buffered_page_items:
                            self._gathered_search["_pending_fallback_items"] = _buffered_page_items
                            self._gathered_search["_pending_key"] = self._last_search_key
                            self._gathered_search["_pending_total_count"] = int(
                                result.get("total_count") or len(items) + len(_buffered_page_items)
                            )
                            self._gathered_search["_pending_display_page"] = _current_page + 1
                            self._gathered_search["_pending_backend_fetch"] = bool(
                                result.get("has_more_beyond_buffer", False)
                            )
                            logger.info(
                                f"[Pagination] Cached {len(_buffered_page_items)} hidden page items "
                                f"for next-three delivery (fetch_more_after_buffer={self._gathered_search['_pending_backend_fetch']})"
                            )

                        # â”€â”€ Tiered Fallback Recovery for filtered empty pages â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                        # When exclude_slugs filters all results, retry from page 1 without exclude.
                        # Pagination is non-deterministic with/without exclude - must restart.
                        # Uses strict deduplication against _property_slugs keys (exact match).
                        if result.get("_fallback_needed") and not self._pagination_fallback_attempted:
                            self._pagination_fallback_attempted = True
                            logger.info(f"[Fallback] triggered=True, page={result.get('current_page', 'unknown')}")

                            # Get canonical shown slugs from session cache
                            _shown_slugs_set = set(
                                self._gathered_search.get("_property_slugs", {}).keys()
                            )
                            _initial_shown_count = len(_shown_slugs_set)

                            async def _try_fallback(fb_params: dict, step_name: str) -> list | None:
                                """Attempt a fallback call, return deduplicated items or None on failure."""
                                try:
                                    _fb_url = f"{BACKEND_URL}/api/integration/proxy/search"
                                    _fb_resp = await self._http_client.get(
                                        _fb_url, params=fb_params, timeout=10.0
                                    )
                                    if _fb_resp.status_code == 200:
                                        _fb_data = _fb_resp.json()
                                        _fb_items = _fb_data.get("data", [])

                                        # Strict deduplication: exact slug match only
                                        _deduped = []
                                        _duplicates = 0
                                        for item in _fb_items:
                                            _slug = str(
                                                item.get("property_id")
                                                or item.get("project_slug")
                                                or ""
                                            )
                                            if _slug and _slug not in _shown_slugs_set:
                                                _deduped.append(item)
                                                _shown_slugs_set.add(_slug)  # Track for this check
                                            elif _slug:
                                                _duplicates += 1

                                        logger.info(
                                            f"[Pagination] {step_name} dedup: "
                                            f"removed {_duplicates} duplicates, {len(_deduped)} new remain"
                                        )
                                        return _deduped
                                    return None
                                except Exception as _e:
                                    logger.warning(f"[{step_name}] Failed: {_e}")
                                    return None

                            _recovered_items = None

                            # Single fallback retry: restart from page 1 without exclude_slugs
                            # CRITICAL: Must restart from page 1 - pagination is non-deterministic
                            logger.info("[Fallback] retry: page=1, remove exclude_slugs")
                            _params1 = {**arguments}
                            _params1.pop("exclude_slugs", None)
                            _params1["page"] = "1"  # Restart from page 1
                            _recovered_items = await _try_fallback(_params1, "retry")

                            # Process results
                            if _recovered_items:
                                # Handle pagination within recovered items
                                # If more than page_size, store excess in session for next "show more"
                                items = _recovered_items[:_page_size]
                                _excess_items = _recovered_items[_page_size:] if len(_recovered_items) > _page_size else []

                                # Cache excess items for next page request
                                if _excess_items:
                                    self._gathered_search["_pending_fallback_items"] = _excess_items
                                    self._gathered_search["_pending_key"] = _search_key
                                    logger.info(
                                        f"[Pagination] Cached {len(_excess_items)} excess fallback items for next page"
                                    )

                                _new_slugs = {
                                    str(item.get("property_id") or item.get("project_slug") or "")
                                    for item in items
                                    if item.get("property_id") or item.get("project_slug")
                                }

                                # Accurate accounting: only count unique delivered properties
                                _new_count = len(_new_slugs)
                                self._shown_slugs.update(_new_slugs)
                                if "_property_slugs" not in self._gathered_search:
                                    self._gathered_search["_property_slugs"] = {}
                                for _slug in _new_slugs:
                                    self._gathered_search["_property_slugs"][_slug] = items[
                                        [
                                            str(
                                                i.get("property_id")
                                                or i.get("project_slug")
                                                or ""
                                            )
                                            for i in items
                                        ].index(_slug)
                                    ].get("name", "")

                                # Determine has_more: true if we have excess cached or more backend results
                                _fallback_has_more = len(_recovered_items) > _page_size or bool(_excess_items)

                                logger.info(
                                    f"[Pagination] Fallback successful: delivered {_new_count} new "
                                    f"(total_shown now {len(self._shown_slugs)}, has_more={_fallback_has_more})"
                                )
                                result = {
                                    **result,
                                    "data": items,
                                    "has_more": _fallback_has_more,
                                    "_fallback_recovered": True,
                                    "_end_of_listings": False,
                                    "_low_confidence": True,
                                }
                                result.pop("_filtered_empty_page", None)
                                result.pop("_fallback_needed", None)
                                logger.info("[ConfidenceMode] enabled=True (fallback recovery)")
                            else:
                                logger.info("[Fallback] exhausted after retries")
                                result["_end_of_listings"] = True
                                result.pop("_fallback_needed", None)
                                result["_fallback_exhausted"] = True

                            # Validation log: derive total_shown from unique slugs
                            logger.info(
                                f"[Pagination] total_shown = {len(self._shown_slugs)} (unique slugs)"
                            )

                        # Log properties found for backend debugging
                        _top_projects = result.get("top_projects") if isinstance(result.get("top_projects"), list) else []
                        for _idx, item in enumerate(items):
                            _raw_name = (
                                item.get("project_name")
                                or item.get("name")
                                or item.get("projectName")
                                or item.get("Project_Name_Original")
                                or item.get("Project_Name")
                                or item.get("Project_Name_New")
                                or ""
                            ).strip()
                            if _raw_name and _raw_name != "?":
                                continue
                            _fallback_name = ""
                            if _idx < len(_top_projects):
                                _fallback_name = str(
                                    _top_projects[_idx].get("name")
                                    or _top_projects[_idx].get("project_name")
                                    or ""
                                ).strip()
                            if _fallback_name:
                                item["name"] = _fallback_name
                                item.setdefault("project_name", _fallback_name)

                        _prop_log_lines = []
                        for item in items:
                            prop_id = item.get("property_id") or item.get("project_slug") or item.get("slug")
                            name = item.get("project_name") or item.get("name") or "?"
                            _cfg = item.get("configs") or [{}]
                            _type = _cfg[0].get("type") if _cfg else item.get("type", "N/A")
                            _price = item.get("starting_price") or (_cfg[0].get("price") if _cfg else None) or "?"
                            if prop_id:
                                self._slug_cache[prop_id] = item
                                # Only map nameâ†’slug when name is non-empty (for detail lookups)
                                if name and name != "?":
                                    self._name_to_slug[name.lower().strip()] = prop_id
                                # [Fix-PropertySlugsSync] Always register slug in _property_slugs
                                # regardless of whether name is present. Previously the `and name`
                                # guard caused slugs for nameless items to be absent from
                                # _property_slugs, making the fallback dedup miss them and re-serve
                                # those items as "new" (duplicate delivery to user).
                                if "_property_slugs" not in self._gathered_search:
                                    self._gathered_search["_property_slugs"] = {}
                                self._gathered_search["_property_slugs"][prop_id] = name
                                _prop_log_lines.append(f"  - {name} ({_type}) @ â‚¹{_price}")
                        logger.info(f"[Tool][Search] Cached {len(self._slug_cache)} properties")
                        # Log properties found for backend visibility - always log even on 0
                        # so developers can see when results are empty and understand why the
                        # LLM has no property data to present (prevents confusion over missing
                        # [BackendProperties] lines in the log).
                        if _prop_log_lines:
                            logger.info(f"[BackendProperties] Found {len(_prop_log_lines)} properties:\n" + "\n".join(_prop_log_lines[:10]))
                        else:
                            logger.warning(
                                f"[BackendProperties] Found 0 properties - "
                                f"data={len(items)} budget_too_low={result.get('budget_too_low')} "
                                f"budget_mismatch={result.get('budget_mismatch_results')} "
                                f"no_exact_match={result.get('no_exact_match')} "
                                f"location={result.get('searched_location') or '-'}"
                            )

                        # â”€â”€ Inject current results into system prompt â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                        # [OrdinalMap] Append new unique items to _ordinal_results (no cap).
                        # Ordinal resolution must survive any number of "show more" pages -
                        # "the first one" must always be item #1 from page 1.
                        # Only the prompt summary is capped to control token use; the full
                        # ordered list is preserved so the LLM can see all ordinal mappings.
                        if self._context_ref:
                            try:
                                # Append only new unique slugs; preserve original display order.
                                _new_count = 0
                                for _new_it in items:
                                    _ns = str(_new_it.get("property_id") or _new_it.get("project_slug") or "")
                                    if _ns and _ns not in self._all_seen_slugs:
                                        self._ordinal_results.append(_new_it)
                                        self._all_seen_slugs.add(_ns)
                                        self._property_details_map[_ns] = _new_it
                                        _new_count += 1
                                logger.info(
                                    f"[OrdinalMap] added {_new_count} new items "
                                    f"(total ordinal list: {len(self._ordinal_results)})"
                                )

                                # [SessionGrowthSafety] Log warning if exceeding soft cap
                                _current_size = len(self._ordinal_results)
                                if _current_size > self._MAX_ORDINAL_RESULTS:
                                    logger.warning(
                                        f"[Session] ordinal_results size exceeded {self._MAX_ORDINAL_RESULTS} "
                                        f"(current: {_current_size})"
                                    )

                                # Build a compact prompt block:
                                # - Show only the latest _DISPLAY_CAP items in detail (capped at 3).
                                # - Prepend a one-line summary of how many earlier items exist
                                #   so the LLM knows ordinals extend beyond what's listed here.
                                # _ordinal_results is never truncated; the cap is display-only.
                                _DISPLAY_CAP = PRESENTED_PROPERTY_LIMIT
                                _full_list = self._ordinal_results
                                _total = len(_full_list)
                                _earlier = _total - _DISPLAY_CAP if _total > _DISPLAY_CAP else 0
                                _visible = _full_list[_earlier:]  # latest _DISPLAY_CAP items

                                if _earlier > 0:
                                    logger.info(
                                        f"[OrdinalMap] prompt compacted: showing {len(_visible)} of {_total} items"
                                    )

                                _ctx = self._context_ref[0]
                                # Minimal header - rules live in the integration prompt now
                                _lines = ["\n\nCURRENT SEARCH RESULTS:"]
                                if _earlier > 0:
                                    _lines.append(
                                        f"[{_earlier} earlier {'property' if _earlier == 1 else 'properties'} also shown - ordinals cover the full session list.]"
                                    )
                                # Minimal list lines - name/BHK/price only.
                                _visible_items = _visible
                                print(f"[ContextReduction] mode=list, items={len(_visible_items)}")
                                for _i, _itm in enumerate(_visible_items, _earlier + 1):
                                    _pname = _itm.get("project_name") or _itm.get("name") or "?"
                                    # Title-case ALL-CAPS names so Cartesia speaks them as words
                                    # not letter-by-letter (e.g. "VIKAAN'S PRIMERO" -> "Vikaan's Primero")
                                    if _pname and _pname.isupper():
                                        _pname = _pname.title()
                                    _cfgs = _itm.get("configs") or []
                                    if _cfgs and _cfgs[0].get("type"):
                                        _bhk = _cfgs[0]["type"]
                                    else:
                                        _bhk = _itm.get("type") or "N/A"
                                    _price = _itm.get("starting_price")
                                    if not _price and _cfgs:
                                        _price = _cfgs[0].get("price")
                                    _price_str = str(_price) if _price else "Price not specified"
                                    _lines.append(f"[{_i}] {_pname} \u2013 {_bhk} \u2013 \u20b9{_price_str}")
                                _results_block = "\n".join(_lines)
                                # Replace any previous CURRENT SEARCH RESULTS block in system message
                                # Also remove any lingering PENDING BUDGET DECISION block
                                _base = _ctx.messages[0]["content"]
                                _base = re.sub(
                                    r'\n\nCURRENT SEARCH RESULTS:.*?(?=\n\n[A-Z]|\Z)',
                                    "",
                                    _base,
                                    flags=re.DOTALL,
                                )
                                # Also strip old format with --- delimiters (backward compat)
                                _base = re.sub(
                                    r'\n\n---\nCURRENT SEARCH RESULTS.*?---',
                                    "",
                                    _base,
                                    flags=re.DOTALL,
                                )
                                _base = re.sub(
                                    r'\n\n---\nPENDING BUDGET DECISION.*?---',
                                    "",
                                    _base,
                                    flags=re.DOTALL,
                                )
                                # â”€â”€ Phase upgrade: swap gather prompt â†’ full prompt â”€â”€
                                # On the very first successful search we replace the
                                # compact 150-token gather prompt with the full
                                # integration prompt so the LLM has all presentation,
                                # anti-hallucination, and tool-selection rules it needs.
                                if not self._property_phase_active and self._full_integration_prompt:
                                    self._property_phase_active = True
                                    # Strip compact gather-phase block from current base
                                    _base = re.sub(
                                        # Match the full gather-phase block regardless of how the
                                        # final "no lists" sentence is worded - the actual text ends
                                        # with "numbered lists, or example lists." but the old regex
                                        # looked for "or numbered lists." and never matched, so the
                                        # gather prompt was never stripped and the combined system
                                        # prompt ballooned past MAX_SYSTEM_CHARS, causing middle
                                        # truncation that removed CURRENT SEARCH RESULTS and left
                                        # the LLM with no property data â†’ {{property name}} output.
                                        r'\n\nGATHERING REQUIRED.*?No bullet points.*?lists\.',
                                        "",
                                        _base,
                                        flags=re.DOTALL,
                                    )
                                    # Strip any prior integration prompt block to prevent duplication.
                                    # The integration prompt from _base_system_prompt (if any) is removed
                                    # and replaced with the full _full_integration_prompt.
                                    _base = re.sub(
                                        r'\n\nROLE: Real estate voice assistant.*?Never expose internal errors.*?property_id, slug, cache, or session details\.',
                                        "",
                                        _base,
                                        flags=re.DOTALL,
                                    )
                                    # Append the full integration prompt
                                    _base = _base + self._full_integration_prompt
                                    logger.info(
                                        "[Tool][Phase] âœ¦ Upgraded gatherâ†’property phase "
                                        f"({len(_base)} chars total)"
                                    )

                                if self._results_injected_this_turn:
                                    logger.info("[Prompt] Results already injected this turn - skipping duplicate CURRENT SEARCH RESULTS")
                                else:
                                    self._results_injected_this_turn = True
                                    _ctx.messages[0]["content"] = _base + _results_block
                                _post_sys_chars = len(_ctx.messages[0]["content"])

                                # â”€â”€ Max prompt size enforcement â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                                MAX_SYSTEM_CHARS = 12000  # was 6500 - gpt-4.1-nano handles this; prevents middle truncation of rules
                                if _post_sys_chars > MAX_SYSTEM_CHARS:
                                    _orig_len = _post_sys_chars
                                    # Middle truncation: preserve persona block (start) and search results (end)
                                    _keep_start = MAX_SYSTEM_CHARS // 2
                                    _keep_end = MAX_SYSTEM_CHARS // 2 - 30  # room for marker
                                    _ctx.messages[0]["content"] = (
                                        _ctx.messages[0]["content"][:_keep_start]
                                        + "\n...[middle truncated]...\n"
                                        + _ctx.messages[0]["content"][-_keep_end:]
                                    )
                                    _post_sys_chars = len(_ctx.messages[0]["content"])
                                    logger.error(
                                        f"[Prompt] OVERSIZE truncated - was {_orig_len} chars, "
                                        f"now {_post_sys_chars} chars. "
                                        f"Kept first {_keep_start} + last {_keep_end}."
                                    )

                                logger.info(
                                    f"[Tool][Context] System prompt updated with "
                                    f"{len(items)} current results ({_post_sys_chars} chars)"
                                )
                                print(
                                    f"[ContextAudit][PostTool] results_count={len(items)} "
                                    f"prompt_growth_chars={len(_results_block)} "
                                    f"total_system_chars={_post_sys_chars}"
                                )
                            except Exception as _ctx_err:
                                logger.warning(f"[Tool][Context] Failed to update system prompt: {_ctx_err}")

                        # â”€â”€ Store last presented properties for selection handling â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                        # Build _last_presented_properties from the visible items with their positions
                        if items:
                            _requested_result_count = max(
                                1,
                                int(merged_params.get("result_count") or arguments.get("result_count") or PRESENTED_PROPERTY_LIMIT),
                            )
                            _visible_items = items[:_requested_result_count]
                            self._last_presented_properties = []
                            _grouped_presented = self._extract_property_variants(_visible_items)
                            for _pos, _group in enumerate(_grouped_presented, start=1):
                                _variants = sorted(
                                    _group.get("variants") or [],
                                    key=lambda v: (
                                        v.get("price_num", float("inf")),
                                        str(v.get("bhk") or ""),
                                        str(v.get("property_id") or ""),
                                    ),
                                )
                                if not _variants:
                                    continue
                                _primary = _variants[0]
                                self._last_presented_properties.append({
                                    "position": _pos,
                                    "name": _group.get("name") or _primary.get("name") or "?",
                                    "property_id": _primary.get("property_id"),
                                    "price_value": (
                                        int(_primary.get("price_num"))
                                        if _primary.get("price_num") not in (None, float("inf"))
                                        else None
                                    ),
                                    "starting_price": _primary.get("price"),
                                    "variants": _variants,
                                })
                            self._selection_pending = False
                            self._prepare_shortlist_presentation(
                                spoken_text="",
                                label=self._gathered_search.get("location")
                                or self._gathered_search.get("city")
                                or "",
                                search_key=self._last_search_key,
                            )
                            logger.info(
                                f"[SelectionState] Stored {len(self._last_presented_properties)} properties, "
                                f"selection_pending={self._selection_pending} stage={self._shortlist_presentation_stage}"
                            )
                            # Log actual property names for debugging
                            if self._last_presented_properties:
                                _names = [p['name'] for p in self._last_presented_properties[:_requested_result_count]]
                                logger.info(f"[SearchResults] Properties presented: {_names}")

                        if (
                            items
                            and function_name == "search_properties"
                            and not result.get("speech_instruction")
                            and not result.get("budget_mismatch_results")
                            and not result.get("budget_too_low")
                        ):
                            result["requested_result_count"] = int(
                                merged_params.get("result_count") or arguments.get("result_count") or PRESENTED_PROPERTY_LIMIT
                            )
                            _price_summary_turn = self.is_area_price_summary_request(_latest_user_text)
                            if _price_summary_turn:
                                result["searched_bedrooms"] = result.get("searched_bedrooms") or merged_params.get("bedrooms") or arguments.get("bedrooms")
                                direct_spoken_result = _build_search_starting_price_speech(result)
                                if direct_spoken_result:
                                    logger.info("[SearchDirectSpeech] deterministic_followup_path=starting_price_summary")
                            else:
                                direct_spoken_result = _build_search_results_speech(
                                    result,
                                    selected_items=_visible_items,
                                )
                            if direct_spoken_result:
                                if self.is_search_intent_redirect(_latest_user_text):
                                    logger.info(
                                        f"[SearchScopeGuard] result_truth_override "
                                        f"key={self._last_search_key!r} items={len(items)}"
                                    )
                                if _price_summary_turn:
                                    _summary_prices = [
                                        self._extract_presented_property_min_price(item)
                                        for item in (result.get("data") or [])
                                        if isinstance(item, dict)
                                    ]
                                    _summary_prices = [price for price in _summary_prices if price > 0]
                                    if _summary_prices:
                                        _lowest_summary_price = min(_summary_prices)
                                        self.set_pending_user_offer(
                                            "zero_result_price_range",
                                            location=self._gathered_search.get("location") or "",
                                            min_price=0,
                                            max_price=max(
                                                _lowest_summary_price,
                                                int(_lowest_summary_price * 1.2),
                                            ),
                                            source="search_price_summary",
                                        )
                                    self.clear_zero_result_state("price_summary_answered")
                                    self._clear_zero_result_followup_state()
                                    logger.info("[SearchDirectSpeech] Using deterministic price summary narration")
                                else:
                                    self.clear_zero_result_state("search_results_found")
                                    self._clear_zero_result_followup_state()
                                    self.clear_pending_user_offer("search_results_found")
                                    self._prepare_shortlist_presentation(
                                        spoken_text=direct_spoken_result,
                                        label=self._gathered_search.get("location")
                                        or self._gathered_search.get("city")
                                        or "",
                                        search_key=self._last_search_key,
                                    )
                                    logger.info(
                                        f"[SearchDirectSpeech] Using deterministic property list narration "
                                        f"for {len(items)} result(s)"
                                    )
                        if items:
                            self._prefetch_top_property_details(items)

                        # Expand _KNOWN_LOCATIONS with Location values from actual API results
                        _search_city = self._gathered_search.get("city", "")
                        if _search_city:
                            _api_locs = [itm.get("location") for itm in items if itm.get("location")]
                            if _api_locs:
                                _existing = _KNOWN_LOCATIONS.get(_search_city, [])
                                _existing_lower = {k.lower() for k in _existing}
                                _new_locs = [l for l in _api_locs if l.lower() not in _existing_lower]
                                if _new_locs:
                                    _KNOWN_LOCATIONS[_search_city] = _existing + _new_locs
                                    logger.info(f"[Tool][Search] _KNOWN_LOCATIONS[{_search_city}] expanded with: {_new_locs}")

                # â”€â”€ areas_by_budget: skip confirmation when location already known â”€â”€â”€â”€â”€â”€
                # If the user already stated a specific location, areas_by_budget was
                # called only to verify budget feasibility - not for area discovery.
                # Inject auto_search=True so the LLM skips the "which area?" question
                # and calls search_properties immediately.
                # EXCEPTION: When user is exploring alternatives after zero results,
                # do NOT auto-search - present the alternative areas instead.
                if function_name == "areas_by_budget" and result.get("success"):
                    _gathered_loc = self._gathered_search.get("location", "").strip()
                    _exploring_alternatives = self._gathered_search.get("_exploring_alternatives", False)
                    _alt_mode_locked = self._zero_result_followup_mode in {
                        "awaiting_alternative_areas",
                        "awaiting_alternative_area_choice",
                    } or self._zero_result_route_lock == "areas_by_budget"
                    if _gathered_loc and result.get("areas") and not _exploring_alternatives and not _alt_mode_locked:
                        result = {
                            **result,
                            "auto_search": True,
                            "instruction": (
                                f"User already specified location '{_gathered_loc}'. "
                                "Call search_properties immediately with that location. "
                                "Do NOT present these areas. Do NOT ask permission."
                            ),
                        }
                        logger.info(f"[AreasByBudget] auto_search=True - location already known: '{_gathered_loc}'")
                    elif (_exploring_alternatives or _alt_mode_locked) and result.get("areas"):
                        # User wants to explore alternatives - clear the flag and present options
                        self._gathered_search["_exploring_alternatives"] = False
                        self._zero_result_followup_mode = "awaiting_alternative_area_choice"
                        self._zero_result_route_lock = "areas_by_budget"
                        # Clear location to allow search in new areas
                        _old_loc = (
                            self._gathered_search.get("_zero_result_origin_location")
                            or self._gathered_search.get("_origin_location")
                            or self._gathered_search.get("location", "")
                        )
                        self._gathered_search["_origin_location"] = _old_loc
                        self._gathered_search["location"] = ""  # Will be filled by user's choice
                        self._gathered_search["_citywide_search"] = True
                        _validated_areas = await self._validate_alternative_areas(
                            result.get("areas") or [],
                            city=self._gathered_search.get("city") or "Chennai",
                            property_type=self._gathered_search.get("property_type") or "",
                            min_price=self._gathered_search.get("min_price"),
                            max_price=self._gathered_search.get("max_price"),
                            bedrooms=self._gathered_search.get("bedrooms"),
                            result_count=1,
                        )
                        if len(_validated_areas) != len(result.get("areas") or []):
                            logger.info(
                                f"[AreasByBudget] Filtered alternative areas by exact criteria: "
                                f"{len(result.get('areas') or [])} â†’ {len(_validated_areas)}"
                            )
                        self._gathered_search["_alternative_area_options"] = _validated_areas
                        _alt_aliases: dict[str, str] = {}
                        _alt_city = str(self._gathered_search.get("city") or "Chennai").strip() or "Chennai"
                        _known_for_alt_city = _KNOWN_LOCATIONS.setdefault(_alt_city, [])
                        _known_norms = {_normalize_location_key(loc) for loc in _known_for_alt_city}
                        for _area in _validated_areas:
                            _area_name = str(
                                (_area.get("name") or _area.get("location") or _area.get("area"))
                                if isinstance(_area, dict)
                                else _area
                            ).strip()
                            if not _area_name:
                                continue
                            for _variant in _alternative_area_alias_variants(_area_name):
                                _alt_aliases[_normalize_location_key(_variant)] = _area_name
                            _area_norm = _normalize_location_key(_area_name)
                            if _area_norm and _area_norm not in _known_norms:
                                _known_for_alt_city.append(_area_name)
                                _known_norms.add(_area_norm)
                        self._gathered_search["_alternative_area_aliases"] = _alt_aliases
                        result = {
                            **result,
                            "areas": _validated_areas,
                            "auto_search": False,
                            "terminal_for_turn": True,
                            "instruction": (
                                f"The user was looking in {_old_loc} but wants to explore other locations. "
                                "Present these alternative areas naturally. "
                                "Ask which area interests them, then call search_properties with that location."
                            ),
                        }
                        logger.info(f"[AreasByBudget] Presenting alternatives - original='{_old_loc}', areas={result.get('areas', [])}")
                        direct_spoken_result = _build_areas_by_budget_speech(
                            result,
                            origin_location=_old_loc,
                            property_type=(
                                self._gathered_search.get("property_type")
                                or merged_params.get("property_type")
                                or arguments.get("property_type")
                            ),
                            min_price=(
                                self._gathered_search.get("min_price")
                                or merged_params.get("min_price")
                                or arguments.get("min_price")
                            ),
                            max_price=(
                                self._gathered_search.get("max_price")
                                or merged_params.get("max_price")
                                or arguments.get("max_price")
                            ),
                        )
                        if direct_spoken_result:
                            result["speech_instruction"] = direct_spoken_result
                            logger.info("[AreasByBudget] Using deterministic alternative-area narration")
                        else:
                            _alt_ptype = _property_type_plural_label(
                                self._gathered_search.get("property_type")
                                or merged_params.get("property_type")
                                or arguments.get("property_type")
                                or "properties"
                            )
                            direct_spoken_result = (
                                f"I couldn't find other areas with matching {_alt_ptype} "
                                "within that budget right now. Would you like to adjust the budget?"
                            )
                            result["speech_instruction"] = direct_spoken_result
                            logger.info("[AreasByBudget] Using deterministic empty alternative-area narration")

            except Exception as e:
                # This catches post-HTTP logic errors (e.g. bugs in result-processing code),
                # NOT timeouts or network errors - those are now caught in the retry loop above
                # and hard-bypassed. If we reach here, something unexpected broke in the handler.
                logger.error(f"âŒ [Tool] {function_name} post-http error: {e}", exc_info=True)
                result = {
                    "success": False,
                    "error": type(e).__name__,
                    "tool": function_name,
                    "speech_instruction": (
                        "An internal error occurred. "
                        "Do NOT fabricate any property names, prices, or listings. "
                        "Say: 'I'm sorry, something went wrong. I can have a JLL Homes property specialist call you back with the right options and next steps. Would you like me to arrange that?'"
                    ),
                }
            finally:
                self._latency_trace_ref[0]["tool_end"] = time.time()
                await _cancel_interim_wait_message("tool_finally")
                self.filler_active = False  # re-enable user input processing

            # â”€â”€ Update lead score after every tool result â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
            if _is_stale_tool_turn():
                await _finish_stale(result)
                return

            self._update_lead_score(function_name, result)
            
            # â”€â”€ CONTEXT: Track tool result for resume after interruption â”€â”€â”€â”€â”€â”€â”€â”€â”€
            if function_name == "get_property_details" and result.get("success") and isinstance(result.get("data"), dict):
                _detail_data = result.get("data") or {}
                _detail_pid = str(
                    _detail_data.get("property_id")
                    or arguments.get("property_id")
                    or arguments.get("project_slug")
                    or ""
                ).strip()
                if _detail_pid:
                    self._property_details_map[_detail_pid] = {
                        **(self._property_details_map.get(_detail_pid) or {}),
                        **_detail_data,
                    }
                    self._slug_cache[_detail_pid] = {
                        **(self._slug_cache.get(_detail_pid) or {}),
                        **_detail_data,
                    }
                    self._mark_property_focus(
                        {
                            "property_id": _detail_pid,
                            "name": _detail_data.get("name") or _detail_data.get("project_name"),
                        }
                    )
                _pending_detail = self._pending_deterministic_detail
                _latest_user_fact = self._detect_single_property_fact(
                    _latest_user_message(getattr(context, "messages", []) or [])
                )
                if (
                    _pending_detail
                    and _detail_pid
                    and _pending_detail.get("property_id") == _detail_pid
                ):
                    direct_spoken_result = self.build_deterministic_detail_response(
                        {
                            "property_id": _detail_pid,
                            "name": _pending_detail.get("name") or _detail_data.get("name"),
                        },
                        _pending_detail.get("fact"),
                    )
                    self._pending_deterministic_detail = None
                    self._mark_property_focus(
                        {
                            "property_id": _detail_pid,
                            "name": _detail_data.get("name") or _detail_data.get("project_name"),
                        }
                    )
                    if direct_spoken_result:
                        logger.info(
                            f"[PropertyFastPath] Using deterministic detail narration "
                            f"for property_id={_detail_pid} fact={_pending_detail.get('fact')}"
                        )
                elif _detail_pid and _latest_user_fact:
                    direct_spoken_result = self.build_deterministic_detail_response(
                        {
                            "property_id": _detail_pid,
                            "name": _detail_data.get("name") or _detail_data.get("project_name"),
                        },
                        _latest_user_fact,
                    )
                    self._pending_deterministic_detail = None
                    if direct_spoken_result:
                        logger.info(
                            f"[PropertyFastPath] Recovered deterministic detail narration "
                            f"for property_id={_detail_pid} fact={_latest_user_fact}"
                        )
                elif (
                    _detail_pid
                    and self._explicit_property_focus_id
                    and self._explicit_property_focus_id == _detail_pid
                ):
                    direct_spoken_result = self.build_direct_property_overview_response(
                        {
                            "property_id": _detail_pid,
                            "name": _detail_data.get("name") or _detail_data.get("project_name"),
                        }
                    )
                    if direct_spoken_result:
                        logger.info(
                            f"[PropertyFirst] Using deterministic overview after explicit detail fetch "
                            f"property_id={_detail_pid}"
                        )
                self.clear_pending_property_lookup()
            elif function_name == "get_property_details" and not result.get("success"):
                self._pending_deterministic_detail = None
                self.clear_pending_property_lookup()
            elif function_name == "submit_callback":
                callback_name = str(
                    arguments.get("propertyName")
                    or arguments.get("name")
                    or self._active_property_name
                    or ""
                ).strip()
                direct_spoken_result = _callback_closing_confirmation(callback_name)
                result = {
                    **(result or {}),
                    "terminal_for_turn": True,
                    "speech_instruction": direct_spoken_result,
                }
                if self._call_closing_ref is not None:
                    self._call_closing_ref[0] = True
                self.clear_pending_user_offer("callback_submitted")
                self.clear_pending_property_callback_offer()
                self.clear_zero_result_state("callback_submitted")
                self._clear_zero_result_followup_state()
                self.mark_callback_confirmation(
                    property_name=callback_name,
                    location=str(self._gathered_search.get("location") or ""),
                )
                logger.info(
                    f"[CallbackIntent] deterministic confirmation prepared propertyName={callback_name or '-'}"
                )
            elif function_name == "schedule_site_visit" and result.get("success") is not False:
                visit_property_name = str(
                    arguments.get("propertyName")
                    or arguments.get("name")
                    or self._active_property_name
                    or ""
                ).strip()
                visit_date = str(
                    arguments.get("visitDate")
                    or arguments.get("preferredDate")
                    or arguments.get("preferredVisitDate")
                    or arguments.get("appointmentDate")
                    or arguments.get("date")
                    or ""
                ).strip()
                visit_first_name = str(
                    arguments.get("firstName")
                    or arguments.get("senderName")
                    or ""
                ).strip()
                direct_spoken_result = _site_visit_closing_confirmation(
                    visit_property_name,
                    visit_date,
                    visit_first_name,
                )
                result = {
                    **(result or {}),
                    "terminal_for_turn": True,
                    "speech_instruction": direct_spoken_result,
                }
                if self._call_closing_ref is not None:
                    self._call_closing_ref[0] = True
                self.clear_pending_user_offer("site_visit_submitted")
                self.clear_pending_property_callback_offer()
                self.clear_pending_property_lookup()
                self.clear_zero_result_state("site_visit_submitted")
                self._clear_zero_result_followup_state()
                self._clear_shortlist_context("site_visit_submitted", clear_presented=True)
                logger.info(
                    f"[SiteVisitIntent] deterministic closing prepared propertyName={visit_property_name or '-'}"
                )

            global_state_manager.last_tool_result = result
            logger.info(f"[CONTEXT] tool_result tracked for {function_name}")
            if direct_spoken_result:
                logger.info(
                    f"[DirectSpeech] Bypassing LLM for deterministic {function_name} narration"
                )
                await _speak_direct_response(direct_spoken_result, result)
                return


            # â”€â”€ [ToolGuard] Only the first tool result per turn fires run_llm=True â”€â”€
            # Parallel tool calls (e.g. areas_by_budget + search_properties in one turn)
            # both completing with run_llm=True causes two LLM calls â†’ double TTS.
            # CRITICAL GUARD: Tool guard MUST allow LLM after interruption
            # If state is INTERRUPTED or RESUMING, allow LLM even if _turn_llm_fired is True
            _terminal_for_turn = bool(result.get("terminal_for_turn"))
            if _terminal_for_turn:
                self._turn_llm_fired = True
                self._turn_terminal_response_emitted = True
                props = FunctionCallResultProperties(run_llm=True)
            elif self._turn_llm_fired and global_state_manager.state not in {AgentState.INTERRUPTED, AgentState.RESUMING}:
                props = FunctionCallResultProperties(run_llm=False)
                print(f"[ToolGuard] blocked_parallel_execution=True for {function_name}")
                # Exception: any tool that returns real data the user needs to hear must
                # always trigger LLM even if it fires second in a parallel-tool turn.
                # search_properties: chain areas_by_budget â†’ search_properties needs results spoken.
                # get_property_details: when chained after a search, details must be spoken.
                if function_name == "search_properties" and result.get("data"):
                    props = FunctionCallResultProperties(run_llm=True)
                elif function_name == "get_property_details" and result.get("success") and result.get("data"):
                    props = FunctionCallResultProperties(run_llm=True)
            else:
                self._turn_llm_fired = True
                props = FunctionCallResultProperties(run_llm=True)
                # If we're in INTERRUPTED state, transition to THINKING
                if global_state_manager.state == AgentState.INTERRUPTED:
                    logger.info(f"[STATE] Tool result after interruption - transitioning to THINKING")
                    global_state_manager.set_state(AgentState.THINKING)

            # â”€â”€ Compress tool result for context (keep full data in internal caches) â”€â”€
            _compressed_result = _compress_tool_result_for_context(result, function_name)
            result_json = json.dumps(_compressed_result, ensure_ascii=False)
            _orig_size = len(json.dumps(result, ensure_ascii=False))
            _comp_size = len(result_json)
            if _orig_size > _comp_size + 100:  # Only log if meaningful compression
                logger.info(
                    f"[Tool][Compress] {function_name}: {_orig_size} â†’ {_comp_size} chars "
                    f"({_orig_size - _comp_size} saved, {(_comp_size/_orig_size)*100:.1f}%)"
                )

            # â”€â”€ Step 5: Tool execution trace â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
            logger.info(
                f"[TOOL_EXEC] called={function_name} "
                f"run_llm={props.run_llm} "
                f"turn_flag_before_set={not props.run_llm or self._turn_llm_fired}"
            )

            # â”€â”€ POST_TOOL debug log (MANDATORY) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
            logger.info(f"[POST_TOOL] run_llm={props.run_llm} | tool={function_name} | will_trigger_llm={props.run_llm}")
            self._mark_terminal_tool_result_ready(function_name, run_llm=props.run_llm)

            try:
                await result_callback(
                    _compressed_result,
                    properties=props
                )
            except Exception:
                self.clear_terminal_tool_response_flags("result_callback_failed")
                raise

            # â”€â”€ Complete deduplication: notify waiting duplicates â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
            if (
                not _terminal_for_turn
                and hasattr(llm, "_aggregator_pair")
                and hasattr(llm._aggregator_pair, "assistant")
            ):
                try:
                    await llm._aggregator_pair.assistant.push_context_frame(FrameDirection.UPSTREAM)
                except Exception as e:
                    logger.warning(f"[Tool] Failed to trigger follow-up LLM turn for {function_name}: {e}")

            if call_key in self._in_flight_calls:
                future = self._in_flight_calls[call_key]
                if not future.done():
                    future.set_result(_compressed_result)
                del self._in_flight_calls[call_key]

        return handler

    async def _execute_endpoint(self, endpoint: dict, arguments: dict) -> dict:
        """Make the actual HTTP request. Returns parsed and trimmed response dict."""
        from urllib.parse import quote as _url_quote

        # Merge runtime context first, then LLM arguments (LLM args take precedence)
        variables = {**self.call_context, **arguments}

        # Fill defaults for optional LLM params not provided
        for param in endpoint.get("llm_parameters", []):
            if param["name"] not in variables and "default" in param:
                variables[param["name"]] = param["default"]

        # Inject call/assistant context into backend proxy requests for audit logging.
        # Only inject for requests going to the Sprio backend (not external APIs).
        _backend_base = os.getenv("SPRIO_BACKEND_URL", "https://test1.sprio.ai").rstrip("/")
        if _backend_base in endpoint.get("url", ""):
            variables.setdefault("call_id",      self.call_context.get("callId", ""))
            variables.setdefault("assistant_id", self.call_context.get("assistantId", ""))

        # City name normalization - the JLL API uses exact spellings that differ from
        # common usage (e.g. "Bengaluru" not "Bangalore"). Normalize before building params.
        _CITY_ALIASES: dict[str, str] = {
            "bangalore": "Bengaluru",
            "bengalore": "Bengaluru",
            "bombay": "Mumbai",
            "new delhi": "Delhi",
            "calcutta": "Kolkata",
        }
        if "city" in variables:
            _city_lower = str(variables["city"]).strip().lower()
            if _city_lower in _CITY_ALIASES:
                _corrected = _CITY_ALIASES[_city_lower]
                logger.debug(f"[Tool] City alias '{variables['city']}' â†’ '{_corrected}'")
                variables["city"] = _corrected

        # â”€â”€ Date normalization â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        # Convert natural-language dates ("tomorrow", "next Monday", "15 April") to
        # ISO 8601 format (YYYY-MM-DDTHH:MM:SS.000Z) before sending to the API.
        # The LLM is instructed to convert dates itself, but this is a safety net
        # for when it passes through the user's raw spoken date string.
        import datetime as _dt
        _DATE_PARAM_KEYS = {
            "preferreddate", "visitdate", "appointmentdate",
            "preferredvisitdate", "date", "visitingdate",
        }
        def _normalize_date(val: str) -> str:
            v = val.strip().lower()
            today = _dt.date.today()
            _DAYS = {"monday": 0, "tuesday": 1, "wednesday": 2, "thursday": 3,
                     "friday": 4, "saturday": 5, "sunday": 6}
            _MONTHS = {"january": 1, "february": 2, "march": 3, "april": 4,
                       "may": 5, "june": 6, "july": 7, "august": 8,
                       "september": 9, "october": 10, "november": 11, "december": 12}
            # Already ISO - ensure year is current or future (LLM sometimes emits stale year)
            if re.match(r'\d{4}-\d{2}-\d{2}', val):
                original_val = val
                _yr = int(val[:4])
                if _yr < today.year:
                    logger.info(f"[Tool] Date year {_yr} is in the past - correcting to {today.year}")
                    val = str(today.year) + val[4:]
                try:
                    corrected_date = _dt.date.fromisoformat(val[:10])
                    if corrected_date < today:
                        final_date = corrected_date
                        while final_date < today:
                            try:
                                final_date = final_date.replace(year=final_date.year + 1)
                            except ValueError:
                                final_date = final_date.replace(year=final_date.year + 1, day=28)
                        val = final_date.isoformat() + val[10:]
                        logger.info(
                            f"[Tool] Date {original_val} was in past after year fix -> advanced to {val}"
                        )
                except ValueError:
                    return val
                return val
            # Relative keywords
            if "day after tomorrow" in v:
                target = today + _dt.timedelta(days=2)
            elif "tomorrow" in v:
                target = today + _dt.timedelta(days=1)
            elif "today" in v:
                target = today
            elif v.startswith("next "):
                day_name = v[5:].strip()
                day_num = _DAYS.get(day_name)
                if day_num is not None:
                    days_ahead = (day_num - today.weekday() + 7) % 7 or 7
                    target = today + _dt.timedelta(days=days_ahead)
                else:
                    return val
            else:
                # Try "15 April", "April 15", "15th April", "April 15th"
                m = re.search(r'(\d{1,2})(?:st|nd|rd|th)?\s+([a-z]+)', v)
                if not m:
                    m = re.search(r'([a-z]+)\s+(\d{1,2})(?:st|nd|rd|th)?', v)
                    if m:
                        month_s, day_s = m.group(1), m.group(2)
                    else:
                        return val  # can't parse - leave as-is
                else:
                    day_s, month_s = m.group(1), m.group(2)
                month_num = _MONTHS.get(month_s.lower())
                if not month_num:
                    return val
                try:
                    year = today.year if month_num >= today.month else today.year + 1
                    target = _dt.date(year, month_num, int(day_s))
                except ValueError:
                    return val
            return target.strftime("%Y-%m-%dT10:00:00.000Z")

        for _dk in list(variables.keys()):
            if _dk.lower().replace("_", "").replace("-", "") in _DATE_PARAM_KEYS:
                _orig = str(variables[_dk])
                _normalized = _normalize_date(_orig)
                if _normalized != _orig:
                    logger.info(f"[Tool] Date normalized '{_dk}': '{_orig}' â†’ '{_normalized}'")
                    variables[_dk] = _normalized

        # Auto-populate firstName - outbound calls already know the caller, no need to ask.
        # Priority: explicit argument â†’ senderName from context â†’ "Customer" fallback.
        if not variables.get("firstName"):
            sender = str(variables.get("senderName") or "").strip()
            if sender:
                variables["firstName"] = sender.split()[0]
            elif endpoint.get("id") == "schedule_site_visit":
                variables["firstName"] = "Customer"
                logger.warning("[Tool] schedule_site_visit firstName fell back to Customer after name collection was skipped")
            else:
                variables["firstName"] = "Customer"
            logger.debug(f"[Tool] Auto-set firstName='{variables['firstName']}' (senderName='{sender or 'empty'}')")

        # Guard: result count params must be reasonable (â‰¥1, â‰¤20).
        # 'limit' is now hidden and rarely set; 'result_count' comes from the user via
        # gather_before_call. Both are clamped to prevent absurd API requests.
        for _count_key in ("limit", "result_count"):
            if _count_key in variables:
                try:
                    _val = int(variables[_count_key])
                    if _val < 1:
                        logger.debug(f"[Tool] {_count_key}={_val} too low - clamped to 1")
                        variables[_count_key] = 1
                    elif _val > 20:
                        logger.debug(f"[Tool] {_count_key}={_val} too high - clamped to 20")
                        variables[_count_key] = 20
                except (ValueError, TypeError):
                    variables[_count_key] = 5

        method = endpoint.get("method", "GET").upper()

        # Resolve URL-path variables (e.g. /project/{project_slug})
        url = endpoint["url"]
        try:
            url = url.format_map({k: _url_quote(str(v), safe="") for k, v in variables.items()})
        except KeyError:
            pass  # leave unresolved path vars as-is

        if method == "GET":
            # Build params dict from query_template - skip keys with no value
            params = {}
            query_tpl = endpoint.get("query_template", "")
            if query_tpl:
                for part in query_tpl.split("&"):
                    if "=" not in part:
                        continue
                    k, _, v_tpl = part.partition("=")
                    try:
                        val = v_tpl.format_map(variables) if "{" in v_tpl else v_tpl
                        if val and val != "None":  # skip empty/missing optional params
                            params[k] = val
                    except KeyError:
                        pass  # optional param not provided - omit from request
            # Add any extra variables not covered by query_template
            # This ensures session-cached params like location are always sent
            _skip_keys = {'result_count', 'limit', '_property_slugs', 'budget',
                            'callId', 'call_id', 'assistantId', 'assistant_id',
                            'firstName', 'senderMobile', 'email'}
            for k, v in variables.items():
                if k not in params and k not in _skip_keys and not k.startswith('_'):
                    if v is not None and str(v) != "None" and str(v).strip():
                        params[k] = str(v)
            if "/api/integration/" not in url:
                logger.info(f"[Tool] REQUEST â†’ GET {url} | params={params}")

            # â”€â”€ Smart cache hit check (param-based invalidation) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
            # Check if we have a valid cached result for these exact params.
            # Invalidates automatically when city/location/budget changes.
            if "/proxy/search" in url:
                _smart_cache_page = str(params.get('page') or '1')
                _smart_cache_excl = str(params.get('exclude_slugs') or '')
                _skip_smart_cache = bool(
                    _smart_cache_page not in ('', '1')
                    or _smart_cache_excl not in ('', '[]')
                    or self._gathered_search.get("_search_intent") == "show_more"
                )
                if _skip_smart_cache:
                    logger.info(
                        f"[Cache] bypass smart cache for pagination "
                        f"page={_smart_cache_page or '1'} has_exclude={_smart_cache_excl not in ('', '[]')}"
                    )
                _search_params = {
                    "city": params.get('city', ''),
                    "property_type": params.get('property_type', ''),
                    "location": params.get('location', ''),
                    "min_price": params.get('min_price'),
                    "max_price": params.get('max_price'),
                    "bedrooms": params.get('bedrooms', ''),
                    "project_category": params.get('project_category', ''),
                    "construction_state": params.get('construction_state', ''),
                }
                _cached_result = None if _skip_smart_cache else self._get_cached_search_result(_search_params)
                if _cached_result:
                    self._latency_trace_ref[0]["cache_path_hit"] = True
                    self._latency_trace_ref[0]["path_label"] = "smart_cache"
                    logger.info(f"[Cache] âœ“ Smart cache hit - skipping HTTP call (saved ~2000ms)")
                    # Extract the actual data without cache metadata
                    _result_data = {k: v for k, v in _cached_result.items() if not k.startswith('_cached')}
                    return _result_data

            # â”€â”€ Prefetch cache hit check â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
            # If _prefetch_search() already fired for this location/budget combo
            # (triggered at DirectInject time, before the LLM tool call), return
            # the cached result instantly - zero additional HTTP latency.
            import time as _pf_time
            if "/proxy/search" in url:
                # Skip prefetch cache for page > 1 or when exclude_slugs is set.
                # Prefetch always fires with page=1 and no exclude_slugs; serving a
                # cached page-1 result for a show-more request (page=2, exclude_slugs set)
                # would repeat the same first-page properties instead of new ones.
                _pf_page = params.get('page', '1')
                _pf_excl = params.get('exclude_slugs', '')
                _skip_pf = (
                    _pf_page not in ('1', '', None) or
                    (bool(_pf_excl) and _pf_excl not in ('[]', ''))
                )
                if _skip_pf:
                    logger.info(f"[Prefetch] skipped - page={_pf_page} has_exclude={_pf_excl not in ('', '[]')}")
                else:
                    # Use consistent key construction with _prefetch_search
                    _prefetch_location = self.canonicalize_search_location(
                        params.get('location', ''),
                        params.get('city', ''),
                    )
                    _base_key = _make_prefetch_key(
                        params.get('city', ''),
                        params.get('property_type', ''),
                        _prefetch_location,
                        params.get('min_price'),
                        params.get('max_price'),
                        params.get('bedrooms', ''),
                        params.get('project_category', ''),
                        params.get('construction_state', '')
                    )
                    _pf_hit = self._prefetch_cache.get(_base_key)
                    logger.debug(
                        f"[PrefetchKey] lookup key={_base_key!r} "
                        f"raw_location={params.get('location', '')!r} canonical_location={_prefetch_location!r}"
                    )


                    if not _pf_hit:
                        logger.debug(f"[Prefetch-DEBUG] READ  key='{_base_key}' cache_keys={list(self._prefetch_cache.keys())}")
                    if _pf_hit and isinstance(_pf_hit, dict) and _pf_hit.get("data") is not None:
                        _age = _pf_time.time() - _pf_hit.get("ts", 0)
                        _pf_cached_turn = _pf_hit.get("turn_id", 0)
                        _pf_cur_turn    = self._prefetch_turn_id
                        if _pf_cached_turn != _pf_cur_turn:
                            # Intent changed since this prefetch was fired - the user has
                            # switched location (T Nagar â†’ OMR). Reject and fall through
                            # to a fresh HTTP call so we never serve stale area results.
                            logger.info(
                                f"[Prefetch] STALE - turn_id mismatch "
                                f"(cached={_pf_cached_turn} vs current={_pf_cur_turn}) "
                                f"- discarding and making fresh request"
                            )
                            self._prefetch_cache.pop(_base_key, None)
                        elif _age < PREFETCH_TTL_SECONDS:
                            self._latency_trace_ref[0]["cache_path_hit"] = True
                            self._latency_trace_ref[0]["path_label"] = "prefetch_cache"
                            logger.info(f"[Prefetch] âœ“ cache hit ({_age:.1f}s old) - skipping HTTP call (saved ~400-600ms)")
                            self._prefetch_cache.pop(_base_key, None)  # consume the entry
                            return _pf_hit["data"]
                        else:
                            logger.warning(f"[Prefetch] âœ- cache expired - key={_base_key} age={_age:.1f}s")
                    else:
                        logger.warning(f"[Prefetch] âœ- cache miss - key={_base_key}")

            resp = await self._http_client.get(url, params=params)  # httpx handles URL encoding

            if resp.status_code >= 400:
                try:
                    err_body = resp.json()
                except Exception:
                    err_body = resp.text[:300]
                logger.warning(f"[Tool] {endpoint.get('id')} HTTP {resp.status_code}: {err_body}")
                _tool_id = endpoint.get('id', '')
                if _tool_id in ("submit_callback", "schedule_site_visit"):
                    logger.info(f"[Tool] {_tool_id} error intercepted - returning graceful close")
                    return {
                        "success": True,
                        "status": "completed",
                        "instruction": "Say EXACTLY: 'Your request has been noted. One of our JLL Homes property specialists will reach out to you shortly. Thank you for calling JLL Homes, have a great day.' Do NOT ask for phone number. Do NOT mention any error.",
                    }
                return {
                    "success": False,
                    "error": f"API returned {resp.status_code}",
                    "details": err_body,
                    "tool": endpoint.get('id'),
                }
            data = resp.json()
            _resp_preview = str(data)[:300] if not isinstance(data, (list, dict)) else (
                f"list[{len(data)}]" if isinstance(data, list) else
                f"dict keys={list(data.keys())[:8]}"
            )
            logger.info(f"[Tool] RESPONSE â† HTTP {resp.status_code} | {_resp_preview}")
            _tool_id = endpoint.get('id', '')

            if _tool_id in ("submit_callback", "schedule_site_visit"):
                logger.info(f"[Tool] {_tool_id} success normalized - returning graceful close")
                return {
                    "success": True,
                    "status": "completed",
                    "data": data if isinstance(data, dict) else {"raw": data},
                    "instruction": "Say EXACTLY: 'Your request has been noted. One of our JLL Homes property specialists will reach out to you shortly. Thank you for calling JLL Homes, have a great day.' Do NOT ask for phone number. Do NOT mention any error.",
                }

            # The backend proxy (integration.js) is responsible for all data
            # transformation: JLL envelope unwrapping, field renaming, location
            # filtering, trimming, formatting, total_count, top_projects.
            # Voice agent receives clean {success, data, has_more, total_count,
            # top_projects, ...} and passes it straight to the LLM.
            #
            # For non-proxy endpoints (any future integrations with their own
            # response_path), we still support generic extraction.
            response_path = endpoint.get("response_path")
            if response_path and isinstance(data, dict):
                for key in response_path.split("."):
                    if isinstance(data, dict):
                        data = data.get(key, data)
                return {"success": True, "data": data}

            # Proxy response is already clean - return as-is so the LLM sees
            # all fields (data, has_more, total_count, top_projects, etc.)
            if isinstance(data, dict) and "success" in data:
                # Cache successful search results for future calls
                if "/proxy/search" in url:
                    _cache_params = {
                        "city": params.get('city', ''),
                        "property_type": params.get('property_type', ''),
                        "location": params.get('location', ''),
                        "min_price": params.get('min_price'),
                        "max_price": params.get('max_price'),
                        "bedrooms": params.get('bedrooms'),
                        "project_category": params.get('project_category', ''),
                        "construction_state": params.get('construction_state', ''),
                    }
                    self._cache_search_result(_cache_params, data)
                return data

            # Cache successful search results for future calls
            if "/proxy/search" in url:
                _cache_params = {
                    "city": params.get('city', ''),
                    "property_type": params.get('property_type', ''),
                    "location": params.get('location', ''),
                    "min_price": params.get('min_price'),
                    "max_price": params.get('max_price'),
                    "bedrooms": params.get('bedrooms'),
                    "project_category": params.get('project_category', ''),
                    "construction_state": params.get('construction_state', ''),
                }
                _result_to_cache = {"success": True, "data": data}
                self._cache_search_result(_cache_params, _result_to_cache)

            return {"success": True, "data": data}

        else:
            # POST/PUT - fill body template using regex substitution (safe for JSON)
            body_tpl = endpoint.get("body_template") or "{}"
            try:
                body_str = _fill_body_template(body_tpl, variables)
                body = json.loads(body_str)
            except json.JSONDecodeError as e:
                logger.warning(f"[Tool] Body template JSON error {e} - using empty body")
                body = {}
            if "/api/integration/" not in url:
                logger.info(f"[Tool] REQUEST â†’ {method} {url} | body={json.dumps(body)[:200]}")
            resp = await self._http_client.request(method, url, json=body)

            if resp.status_code >= 400:
                try:
                    err_body = resp.json()
                except Exception:
                    err_body = resp.text[:300]
                logger.warning(f"[Tool] {endpoint.get('id')} HTTP {resp.status_code}: {err_body}")
                _tool_id = endpoint.get('id', '')
                if _tool_id in ("submit_callback", "schedule_site_visit"):
                    logger.info(f"[Tool] {_tool_id} error intercepted - returning graceful close")
                    return {
                        "success": True,
                        "status": "completed",
                        "instruction": "Say EXACTLY: 'Your request has been noted. One of our JLL Homes property specialists will reach out to you shortly. Thank you for calling JLL Homes, have a great day.' Do NOT ask for phone number. Do NOT mention any error.",
                    }
                return {
                    "success": False,
                    "error": f"API returned {resp.status_code}",
                    "details": err_body,
                    "tool": endpoint.get("id"),
                }
            data = resp.json()
            _resp_preview = str(data)[:300] if not isinstance(data, (list, dict)) else (
                f"list[{len(data)}]" if isinstance(data, list) else
                f"dict keys={list(data.keys())[:8]}"
            )
            logger.info(f"[Tool] RESPONSE â† HTTP {resp.status_code} | {_resp_preview}")

            # The backend proxy (integration.js) is responsible for all data
            # transformation: JLL envelope unwrapping, field renaming, location
            # filtering, trimming, formatting, total_count, top_projects.
            # Voice agent receives clean {success, data, has_more, total_count,
            # top_projects, ...} and passes it straight to the LLM.
            #
            # For non-proxy endpoints (any future integrations with their own
            # response_path), we still support generic extraction.
            response_path = endpoint.get("response_path")
            if response_path and isinstance(data, dict):
                for key in response_path.split("."):
                    if isinstance(data, dict):
                        data = data.get(key, data)
                return {"success": True, "data": data}

            # Proxy response is already clean - return as-is so the LLM sees
            # all fields (data, has_more, total_count, top_projects, etc.)
            if isinstance(data, dict) and "success" in data:
                return data

            return {"success": True, "data": data}


def build_transfer_system_prompt(transfer_number: str, transfer_message: str = "") -> str:
    """Returns the system prompt addon that teaches the LLM to handle transfer requests."""
    confirmation_text = transfer_message.strip() if transfer_message and transfer_message.strip() else \
        "Let me connect you to one of our agents. Can you confirm? (yes/no)"
    return f"""

TRANSFER TO HUMAN AGENT:
- Transfer number configured: {transfer_number}
- If the user asks to speak to a human, agent, manager, or requests a transfer:
  1. Ask for confirmation: "{confirmation_text}"
  2. Wait for the user to reply.
  3. If the user confirms (says yes / haan / theek hai / ok / bilkul):
     Respond EXACTLY with this single word on its own line: TRANSFER_CALL_NOW
     Do not add any other text after it.
  4. If the user declines, acknowledge and continue the conversation normally.
- IMPORTANT: Only output TRANSFER_CALL_NOW after explicit user confirmation. Never output it speculatively.
"""


def _fill_body_template(template: str, variables: dict) -> str:
    """Replace {varname} placeholders in JSON body templates using regex.

    Safer than str.format_map(): JSON's own { } braces are NOT treated as
    format specifiers. Only {name} patterns that contain no nested braces are
    replaced. Values are escaped for JSON string context (backslash + double quote).
    """
    def _replacer(match):
        key = match.group(1).strip()
        val = variables.get(key)
        if val is None:
            val = ""
        return str(val).replace("\\", "\\\\").replace('"', '\\"')
    return re.sub(r'\{([^{}]+)\}', _replacer, template)


def _spoken_text_from_gather_instruction(instruction: str, field: str | None = None) -> str:
    """Convert tool-layer gather instructions into direct spoken prompts."""
    raw = (instruction or "").strip()
    if not raw:
        return ""

    for pattern in (
        r"Ask the user EXACTLY:\s*'([^']+)'",
        r"Ask the user:\s*'([^']+)'",
        r'Tell the user:\s*"([^"]+)"',
    ):
        match = re.search(pattern, raw, flags=re.IGNORECASE | re.DOTALL)
        if match:
            return re.sub(r"\s+", " ", match.group(1)).strip()

    lowered = raw.lower()
    if field == "budget" and "misheard your budget" in lowered:
        return "I didn't catch your budget clearly. Could you repeat the amount?"

    return re.sub(r"\s+", " ", raw).strip()


def _detect_expected_gather_field(messages, city: str | None = None) -> str | None:
    """Infer which gather slot the assistant most recently asked for."""
    latest_assistant = next(
        (
            str(m.get("content", "")).strip().lower()
            for m in reversed(messages or [])
            if m.get("role") == "assistant" and isinstance(m.get("content"), str)
        ),
        "",
    )
    if not latest_assistant:
        return None

    if (
        "would you like to increase your budget" in latest_assistant
        or "would you like to adjust your budget" in latest_assistant
        or "suggest other areas" in latest_assistant
        or "suggest other locations" in latest_assistant
        or "check a different location" in latest_assistant
    ):
        return None

    if (
        "property type" in latest_assistant
        or "what kind of property" in latest_assistant
        or "do you mean an apartment or a villa" in latest_assistant
        or "house can mean either apartment or villa" in latest_assistant
        or (
            "apartment" in latest_assistant
            and "villa" in latest_assistant
            and "plot" in latest_assistant
        )
        or "repeat the property type" in latest_assistant
        or "catch the property type" in latest_assistant
        or "didn't catch the property type" in latest_assistant
    ):
        return "property_type"
    if (
        "which area" in latest_assistant
        or "looking at" in latest_assistant
        or "valid area" in latest_assistant
        or "specify a valid area" in latest_assistant
        or "specify the area" in latest_assistant
        or "catch the area" in latest_assistant
    ):
        return "location"
    if city and city.lower() in latest_assistant and "area" in latest_assistant:
        return "location"
    if re.search(
        r'\b(what.{0,30}budget|how\s+much|repeat.{0,20}amount|budget\s+range|increase\s+your\s+budget|adjust\s+your\s+budget)\b',
        latest_assistant,
    ):
        return "budget"
    return None


def _is_valid_current_turn_for_gather_field(
    user_text: str,
    field: str,
    city: str | None = None,
    catalog: dict | None = None,
) -> bool:
    """Validate whether the current utterance satisfies the slot being gathered."""
    text = (user_text or "").strip()
    lower = text.lower()
    if not lower:
        return False

    if is_non_search_slot_chatter(text):
        return False

    if field == "property_type":
        return bool(_extract_property_type_from_text(text))

    if field == "budget":
        if _parse_inr_amounts(text, allow_bare_rupees=True):
            return True
        return _is_flexible_budget_text(text) or bool(re.search(r"\b(any|flexible|open budget|not sure|no budget|anything)\b", lower))

    if field == "location":
        if is_non_location_chatter(text):
            return False
        if _is_citywide_location_text(text) or re.search(r"\b(anywhere|any area|any location|no preference|open to anywhere)\b", lower):
            return True
        _city_key = (city or "Chennai").strip()
        if _find_known_location_in_text(text, _city_key, catalog):
            return True
        _norm = _normalize_location_key(text)
        if _norm and _LOCATION_ALIASES.get(_norm):
            return True
        if _resolve_canonical_location(text, _city_key, catalog):
            return True
        _cat_locs = (((catalog or {}).get("by_city") or {}).get(_city_key, {}) or {}).get("locations") or []
        if any(len(loc) >= 3 and loc.lower() in lower for loc in _cat_locs):
            return True
        if _cat_locs and _norm:
            _cat_norms = [_normalize_location_key(l) for l in _cat_locs]
            if difflib.get_close_matches(_norm, _cat_norms, n=1, cutoff=0.88):
                return True
        _known_locations = _KNOWN_LOCATIONS.get(_city_key, [])
        if any(len(loc) >= 3 and loc.lower() in lower for loc in _known_locations):
            return True
        return False

    return True


def build_latency_breakdown_v2(call_latency_ref: list[dict[str, Any]]) -> dict[str, Any]:
    if not call_latency_ref:
        return {
            "turnCount": 0,
            "llmMs": {"avg": 0, "p50": 0, "p95": 0},
            "ttsMs": {"avg": 0, "p50": 0, "p95": 0},
            "e2eMs": {"avg": 0, "p50": 0, "p95": 0},
            "routerMs": {"avg": 0, "p50": 0, "p95": 0},
            "toolMs": {"avg": 0, "p50": 0, "p95": 0},
            "postToolMs": {"avg": 0, "p50": 0, "p95": 0},
            "firstSentenceMs": {"avg": 0, "p50": 0, "p95": 0},
            "ttsTtfaMs": {"avg": 0, "p50": 0, "p95": 0},
            "e2eFirstAudioMs": {"avg": 0, "p50": 0, "p95": 0},
        }

    def _summary(values: list[int]) -> dict[str, int]:
        if not values:
            return {"avg": 0, "p50": 0, "p95": 0}
        ordered = sorted(values)
        return {
            "avg": int(sum(values) / len(values)),
            "p50": int(statistics.median(values)),
            "p95": int(ordered[min(len(ordered) - 1, int(len(ordered) * 0.95))]),
        }

    llm_values = [int(item.get("llm_ms") or 0) for item in call_latency_ref]
    tts_values = [int(item.get("tts_ms") or 0) for item in call_latency_ref]
    e2e_values = [int(item.get("e2e_ms") or 0) for item in call_latency_ref]
    router_values = [int(item.get("router_ms") or 0) for item in call_latency_ref]
    tool_values = [int(item.get("tool_ms") or 0) for item in call_latency_ref]
    post_tool_values = [int(item.get("post_tool_ms") or 0) for item in call_latency_ref]
    first_sentence_values = [int(item.get("first_sentence_ms") or 0) for item in call_latency_ref]
    tts_ttfa_values = [int(item.get("tts_ttfa_ms") or 0) for item in call_latency_ref]
    e2e_first_audio_values = [int(item.get("e2e_first_audio_ms") or 0) for item in call_latency_ref]
    return {
        "turnCount": len(call_latency_ref),
        "llmMs": _summary(llm_values),
        "ttsMs": _summary(tts_values),
        "e2eMs": _summary(e2e_values),
        "routerMs": _summary(router_values),
        "toolMs": _summary(tool_values),
        "postToolMs": _summary(post_tool_values),
        "firstSentenceMs": _summary(first_sentence_values),
        "ttsTtfaMs": _summary(tts_ttfa_values),
        "e2eFirstAudioMs": _summary(e2e_first_audio_values),
    }


def _looks_like_broad_search_restatement(
    user_text: str,
    field: str,
    city: str | None = None,
) -> bool:
    """Detect full-sentence restatements that should not be treated as invalid slot values."""
    text = (user_text or "").strip()
    lower = text.lower()
    if not lower or is_non_search_slot_chatter(text):
        return False

    city_lower = (city or "Chennai").strip().lower()
    mentions_city = city_lower in lower or "chennai" in lower
    has_property_type = bool(_extract_property_type_from_text(text))
    generic_property_request = bool(_GENERIC_PROPERTY_RE.search(lower))
    has_search_intent = bool(
        re.search(
            r"\b(looking for|searching for|need|want|interested in|find|show me|check|properties?|property|apartments?|villas?|plots?)\b",
            lower,
        )
    )
    word_count = len(re.findall(r"\w+", lower))

    if field == "location":
        return word_count >= 5 and (mentions_city or has_property_type or generic_property_request or has_search_intent)
    if field == "property_type":
        return word_count >= 5 and (mentions_city or has_search_intent)
    if field == "budget":
        return word_count >= 5 and has_search_intent and not _parse_inr_amounts(text)
    return False


def _looks_like_property_type_help_request(user_text: str) -> bool:
    """Detect turns where the user cannot or does not want to pick a property type."""
    lower = re.sub(r"\s+", " ", (user_text or "").strip().lower())
    if not lower:
        return False
    if re.search(
        r"\b("
        r"don'?t\s+know|not\s+sure|no\s+idea|any\s+type|any\s+property\s+type|"
        r"whatever\s+(?:is\s+)?available|anything\s+available|"
        r"available\s+(?:options|properties|property|types|type)|"
        r"(?:what|which)\s+(?:are\s+the\s+)?(?:properties|property|options|types|type).{0,30}available|"
        r"tell\s+me\s+(?:the\s+)?available\s+(?:options|properties|types)|"
        r"show\s+me\s+(?:the\s+)?available\s+(?:options|properties|types)"
        r")\b",
        lower,
    ):
        return True
    return False


def _property_type_help_response(user_text: str, city: str | None = None, *, already_offered: bool = False) -> tuple[str, bool]:
    city_name = (city or "Chennai").strip() or "Chennai"
    lower = (user_text or "").strip().lower()
    unsure = bool(re.search(r"\b(don'?t\s+know|not\s+sure|no\s+idea|any\s+type|whatever|anything)\b", lower))
    if unsure and already_offered:
        return (
            f"No problem. I'll start with apartments across {city_name}. "
            "What budget range should I consider?"
        ), True
    return (
        "We have apartments, villas and plots, along with options like builder floors and penthouses. "
        "What type of property are you looking for?"
    ), False


def _current_turn_updates_other_search_slot(
    user_text: str,
    expected_field: str,
    city: str | None = None,
    catalog: dict | None = None,
) -> bool:
    text = (user_text or "").strip()
    if not text:
        return False

    checks = {
        "property_type": bool(_extract_property_type_from_text(text)),
        "budget": bool(_parse_inr_amounts(text)),
        "location": _is_valid_current_turn_for_gather_field(text, "location", city=city, catalog=catalog),
        "bedrooms": bool(re.search(r"\b([1-6])\s*bhk\b|\b(one|two|three|four|five|six)\s*bhk\b", text, re.IGNORECASE)),
    }
    for field_name, matched in checks.items():
        if field_name != expected_field and matched:
            return True
    return False


def _reprompt_for_invalid_gather_field(field: str, city: str | None = None, user_text: str | None = None) -> str:
    """Return the deterministic retry prompt for an invalid gather response."""
    _city = city or "Chennai"
    if field == "property_type":
        return "I didn't catch the property type clearly. Could you repeat the property type?"
    if field == "budget":
        if _is_flexible_budget_text(user_text or ""):
            return "Noted. I'll keep the budget open."
        return "I didn't catch your budget clearly. Could you repeat the amount?"
    if field == "location":
        _area = (user_text or "").strip()
        if _is_citywide_location_text(_area):
            return f"Noted. I'll search across { _city }."
        _word_count = len(re.findall(r"\w+", _area))
        _norm_area = _normalize_location_key(_area)
        if _word_count <= 1 or len(_norm_area) <= 2:
            return f"I didn't catch the area clearly. Could you say the area in {_city} again?"
        if (
            _area
            and _word_count <= 4
            and not is_non_location_chatter(_area)
            and not _looks_like_broad_search_restatement(_area, "location", city=_city)
        ):
            return f"Sorry, {_area} is not a valid area. Could you please specify a valid area in {_city}?"
        return f"I didn't catch the area clearly. Which area in {_city} are you looking at?"
    return "I didn't catch that clearly. Could you repeat that?"


def _next_deterministic_gather_prompt(gathered: dict | None) -> str | None:
    """Return the next fixed gather question without invoking the LLM."""
    gs = gathered or {}
    city = str(gs.get("city") or "Chennai").strip() or "Chennai"
    has_location = bool(gs.get("location") or gs.get("_citywide_search"))
    has_type = bool(gs.get("property_type"))
    has_budget = bool(gs.get("min_price") or gs.get("max_price") or gs.get("_budget_flexible"))

    if not has_type:
        return "What kind of property are you looking for?"
    if not has_budget:
        return "And what is your budget range?"
    if not has_location:
        return f"Which area in {city} are you looking at?"
    return None


def _latest_user_message(messages: list[dict]) -> str:
    for _msg in reversed(messages or []):
        if _msg.get("role") == "user" and isinstance(_msg.get("content"), str):
            return _msg["content"]
    return ""


def _canonical_short_slot_text(text: str) -> str:
    text = _normalize_chennai_locality((text or "").strip())
    text = re.sub(r"[^\w\s]", " ", text.lower())
    return " ".join(text.split())


def _should_try_early_interim_commit(
    *,
    text: str,
    expected_field: str | None,
    city: str,
    catalog,
) -> bool:
    if not expected_field:
        return False
    text = (text or "").strip()
    if not text:
        return False
    if _GATHER_AMBIGUITY_RE.search(text):
        return False
    word_count = len(text.split())
    if expected_field == "property_type":
        return word_count <= 3 and _is_valid_current_turn_for_gather_field(
            text, expected_field, city=city, catalog=catalog
        )
    if expected_field == "location":
        return word_count <= 4 and _is_valid_current_turn_for_gather_field(
            text, expected_field, city=city, catalog=catalog
        )
    if expected_field == "budget":
        if word_count > 6:
            return False
        return _is_valid_current_turn_for_gather_field(
            text, expected_field, city=city, catalog=catalog
        )
    return False


def _prune_gather_context_messages(context, keep_non_system: int = 6) -> int:
    """Trim gather-phase context to the most relevant recent turns."""
    if not context or not hasattr(context, "messages"):
        return 0
    messages = list(getattr(context, "messages", []) or [])

    head_system = messages[:1]
    non_system = []
    removed_tool_context = 0
    for m in messages[1:]:
        if m.get("role") == "system":
            continue
        if m.get("role") in {"tool", "function"}:
            removed_tool_context += 1
            continue
        if m.get("role") == "assistant" and m.get("tool_calls"):
            m = dict(m)
            has_spoken_text = isinstance(m.get("content"), str) and bool(m.get("content").strip())
            if has_spoken_text:
                m.pop("tool_calls", None)
            else:
                removed_tool_context += 1
                continue
        non_system.append(m)
    if len(messages) <= keep_non_system + 3 and not removed_tool_context:
        return 0
    tail_non_system = non_system[-keep_non_system:]
    tail_system = []
    for msg in reversed(messages[1:]):
        content = msg.get("content")
        if msg.get("role") != "system" or not isinstance(content, str):
            continue
        if (
            content.startswith("[SESSION STATE] Already confirmed")
            or "ALL REQUIRED SEARCH SLOTS ARE NOW CONFIRMED" in content
        ):
            tail_system.append(msg)
        if len(tail_system) >= 2:
            break
    tail_system.reverse()

    new_messages = head_system + tail_system + tail_non_system
    removed = len(messages) - len(new_messages)
    if removed > 0:
        context.messages[:] = new_messages
        if removed_tool_context:
            logger.info(f"[ContextPrune] gather removed_tool_context={removed_tool_context}")
    return removed


def _should_use_deterministic_gather_prompt(
    *,
    field_name: str,
    instruction: str,
    latest_user_text: str,
    missing_count: int,
    confirmation_candidate=None,
    extracted_params: dict | None = None,
) -> bool:
    """Allow deterministic gather prompts only on clear, low-risk turns."""
    if not instruction or not field_name:
        return False
    lowered = instruction.strip().lower()
    if confirmation_candidate:
        return False
    if any(marker in lowered for marker in _GATHER_DIRECT_FALLBACK_MARKERS):
        return False
    if missing_count != 1:
        return False

    latest_user_text = (latest_user_text or "").strip()
    if not latest_user_text:
        return True

    if _GATHER_AMBIGUITY_RE.search(latest_user_text):
        return False

    extracted_params = extracted_params or {}
    if extracted_params.get("_location_override") or extracted_params.get("_clear_location"):
        return False

    word_count = len(latest_user_text.split())
    if field_name == "location":
        return word_count <= 12
    if field_name == "budget":
        return word_count <= 10
    if field_name == "property_type":
        return word_count <= 8
    return False


def _compress_tool_result_for_context(result: dict, function_name: str) -> dict:
    """Compress tool result to essential fields for LLM context storage.

    Full data is kept in internal caches (_property_details_map, _slug_cache).
    This compressed version goes into the LLM context to reduce token usage.

    Returns a minimal dict with only the fields needed for LLM reasoning.
    """
    if not isinstance(result, dict):
        return result

    # Copy essential metadata
    compressed = {
        "success": result.get("success"),
        "status": result.get("status"),
    }

    # Include error info if present
    if result.get("error"):
        compressed["error"] = result["error"]

    # Include flags that affect LLM behavior
    for flag in ["no_location_match", "budget_too_low", "budget_mismatch_results",
                 "has_more", "auto_search", "_low_confidence", "action"]:
        if flag in result:
            compressed[flag] = result[flag]

    # Include brief instruction text (truncated)
    if result.get("instruction"):
        compressed["instruction"] = result["instruction"][:200] + "..." if len(result["instruction"]) > 200 else result["instruction"]

    # Include speech_instruction (truncated)
    if result.get("speech_instruction"):
        compressed["speech_instruction"] = result["speech_instruction"][:150] + "..." if len(result["speech_instruction"]) > 150 else result["speech_instruction"]

    # Compress data array for search_properties
    if function_name == "search_properties" and "data" in result:
        data = result.get("data", [])
        if isinstance(data, list):
            # Keep only essential fields for each property
            compressed["data"] = [
                {
                    "property_id": item.get("property_id") or item.get("project_slug") or item.get("slug"),
                    "name": item.get("project_name") or item.get("name"),
                    "location": item.get("location"),
                    "type": item.get("type") or (item.get("configs", [{}])[0].get("type") if item.get("configs") else None),
                    "starting_price": item.get("starting_price") or (item.get("configs", [{}])[0].get("price") if item.get("configs") else None),
                }
                for item in data[:PRESENTED_PROPERTY_LIMIT]  # Keep context aligned with spoken page size
            ]
            if len(data) > PRESENTED_PROPERTY_LIMIT:
                compressed["data_note"] = f"{len(data) - PRESENTED_PROPERTY_LIMIT} more properties available in cache"

    # Compress property details
    elif function_name == "get_property_details" and "data" in result:
        data = result.get("data", {})
        if isinstance(data, dict):
            compressed["data"] = {
                "property_id": data.get("property_id"),
                "name": data.get("name"),
                "location": data.get("location"),
                "type": data.get("type"),
                "price": data.get("price") or data.get("starting_price"),
                "area": data.get("area"),
                "amenities": data.get("amenities", [])[:6] if data.get("amenities") else None,  # Limit amenities
                "possession": data.get("possession"),
                "rera": data.get("rera"),
            }

    # Include suggested_areas for no_location_match
    elif result.get("suggested_areas"):
        compressed["suggested_areas"] = result["suggested_areas"][:5]  # Limit suggestions

    return compressed


def _prune_old_tool_messages(context) -> None:
    """Remove accumulated tool call/result messages from previous turns.

    Each completed tool round-trip leaves two messages in context:
      â€¢ {"role":"assistant","tool_calls":[...]}   â† the function call
      â€¢ {"role":"tool","content":"..."}            â† the raw JSON result

    These accumulate across turns and rapidly push the total prompt token count
    past Groq's 12,000 tokens/minute rate limit, causing 20â€“30s TTFB delays.

    The assistant's verbal responses already summarise the tool results, so raw
    tool messages from prior turns can be safely removed. Called at the start of
    each tool handler - BEFORE result_callback - so the CURRENT tool call
    (already added to context by Pipecat) is always preserved.
    """
    if not hasattr(context, 'messages') or not context.messages:
        return
    messages = context.messages

    # â”€â”€ DEDUPLICATION: Remove duplicate tool calls by content hash â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    # Repeated tool calls with the same arguments are still distinct round-trips
    # because each one has its own tool_call_id. Deduplicating by content can
    # orphan tool messages and break the OpenAI tool-call message contract.

    # Find the LAST assistant message that has tool_calls - that's the current call
    last_tool_call_idx = -1
    for i in range(len(messages) - 1, -1, -1):
        m = messages[i]
        if m.get("role") == "assistant" and m.get("tool_calls"):
            last_tool_call_idx = i
            break

    if last_tool_call_idx <= 0:
        return  # Nothing old to prune

    new_messages = []
    for i, m in enumerate(messages):
        if i >= last_tool_call_idx:
            new_messages.append(m)  # current tool call + everything after: keep
        elif m.get("role") == "tool":
            pass  # old tool result: discard
        elif m.get("role") == "assistant" and m.get("tool_calls") and not m.get("content"):
            pass  # old pure tool-call message (no spoken text): discard
        else:
            new_messages.append(m)  # system, user, assistant text responses: keep

    pruned = len(messages) - len(new_messages)
    if pruned > 0:
        logger.debug(f"[Tool] Pruned {pruned} old tool message(s) from context "
                     f"({len(messages)} â†’ {len(new_messages)} messages)")
        messages[:] = new_messages

    # Strip any inline <function=...>...</function> text from assistant messages.
    # Groq Llama sometimes stores function-call markup as plain content text. If left
    # in context, the LLM reads it back and thinks it already executed the tool -
    # causing it to hallucinate results instead of actually calling the tool again.
    _INLINE_FUNC_RE = re.compile(r'<function=\w+>[\s\S]*?</function>', re.DOTALL)
    for m in messages:
        if m.get("role") == "assistant" and isinstance(m.get("content"), str):
            cleaned = _INLINE_FUNC_RE.sub("", m["content"]).strip()
            if cleaned != m["content"]:
                logger.debug("[Tool] Stripped inline function call from assistant context message")
                m["content"] = cleaned or None

    # â”€â”€ Aggressive pruning: keep only last 3 tool results â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    # Prevent context bloat from accumulated tool results across many turns.
    # Do not prune tool messages independently of their paired assistant
    # tool_calls message. Pair-breaking causes invalid_request_error responses
    # from the LLM provider on later turns.

    # After removing tool messages, prune the conversation rolling window.
    _prune_old_conversation_messages(context)


def _prune_property_tool_context(context, keep_recent_roundtrip: bool = False) -> dict[str, int]:
    """Remove stale tool/function context from property/detail turns."""
    stats = {
        "tool_messages_before": 0,
        "tool_messages_after": 0,
        "tool_messages_removed": 0,
        "tool_chars_before": 0,
        "tool_chars_after": 0,
    }
    if not hasattr(context, "messages") or not context.messages:
        return stats

    messages = context.messages
    keep_indices: set[int] = set()
    if keep_recent_roundtrip:
        last_tool_call_idx = -1
        last_tool_result_idx = -1
        for i in range(len(messages) - 1, -1, -1):
            msg = messages[i]
            role = msg.get("role")
            if last_tool_result_idx < 0 and role in {"tool", "function"}:
                last_tool_result_idx = i
            if last_tool_call_idx < 0 and role == "assistant" and msg.get("tool_calls"):
                last_tool_call_idx = i
            if last_tool_call_idx >= 0 and last_tool_result_idx >= 0:
                break
        if last_tool_call_idx >= 0:
            keep_indices.add(last_tool_call_idx)
        if last_tool_result_idx >= 0:
            keep_indices.add(last_tool_result_idx)

    cleaned_messages = []
    for idx, msg in enumerate(messages):
        role = msg.get("role")
        content = msg.get("content")

        if role in {"tool", "function"}:
            stats["tool_messages_before"] += 1
            if isinstance(content, str):
                stats["tool_chars_before"] += len(content)
            if idx not in keep_indices:
                stats["tool_messages_removed"] += 1
                continue
            stats["tool_messages_after"] += 1
            if isinstance(content, str):
                stats["tool_chars_after"] += len(content)
            cleaned_messages.append(msg)
            continue

        if role == "assistant" and msg.get("tool_calls"):
            stats["tool_messages_before"] += 1
            if isinstance(content, str):
                stats["tool_chars_before"] += len(content)
            has_spoken_text = isinstance(content, str) and bool(content.strip())
            if idx not in keep_indices and not has_spoken_text:
                stats["tool_messages_removed"] += 1
                continue
            stats["tool_messages_after"] += 1
            if isinstance(content, str):
                stats["tool_chars_after"] += len(content)

        cleaned_messages.append(msg)

    if stats["tool_messages_removed"] > 0:
        messages[:] = cleaned_messages
    return stats


def _prune_old_conversation_messages(
    context,
    max_turns: int = 6,
    compact_recent_tail: int = 4,
    aggressive_assistant_compaction: bool = False,
) -> int:
    """Keep only the last max_turns of user+assistant conversation messages.

    Preserves: system message (always), first assistant greeting, recent turns.
    Drops: old user/assistant messages beyond the window to prevent context
    bloat that causes Groq rate-limit throttling and LLM hallucination.

    max_turns=6: covers 2-3 search/detail cycles. Tool messages are already
    pruned by _prune_old_tool_messages so the window is purely conversational.

    Also compacts verbose property listing messages from old turns into a
    one-line summary to further reduce token count.
    """
    if not hasattr(context, 'messages') or not context.messages:
        return 0
    messages = context.messages
    before_count = len(messages)

    system_msgs = [m for m in messages if m.get("role") == "system"]
    non_system  = [m for m in messages if m.get("role") != "system"]

    # Always keep the first assistant message (the call greeting).
    first_asst_idx = next(
        (i for i, m in enumerate(non_system) if m.get("role") == "assistant"), -1
    )
    greeting = [non_system[first_asst_idx]] if first_asst_idx >= 0 else []
    rest = [m for i, m in enumerate(non_system) if i != first_asst_idx]

    # Keep only the last max_turns * 2 messages (user + assistant pairs).
    trimmed = rest[-(max_turns * 2):]

    # Compact verbose property-listing messages that are now old (not in the
    # last 4 messages). These contain large JSON-derived text and eat tokens.
    _LISTING_RE = re.compile(
        r"(great news|we have \d+|here are the top|here are \d+|"
        r"top options for you|i found \d+|we found \d+)",
        re.IGNORECASE,
    )
    compact_boundary = max(0, len(trimmed) - compact_recent_tail)
    _DETAIL_RE = re.compile(
        r"(starting price|price starts from|priced at|located in|amenities|"
        r"possession|callback|site visit|schedule|would you like more details|"
        r"property|bhk)",
        re.IGNORECASE,
    )
    for i, m in enumerate(trimmed[:compact_boundary]):
        if m.get("role") == "assistant" and isinstance(m.get("content"), str):
            content = m["content"]
            if _LISTING_RE.search(content) and len(content) > 200:
                # Replace with a compact placeholder - keeps conversation flow
                # visible to LLM without burning hundreds of tokens on old listings.
                trimmed[i] = dict(m, content="[Property search results presented to user]")
                logger.debug("[Context] Compacted old property listing message")
            elif aggressive_assistant_compaction and len(content) > 120:
                if _DETAIL_RE.search(content) or len(content) > 260:
                    trimmed[i] = dict(m, content="[Property details previously presented to user]")
                    logger.debug("[Context] Compacted old property detail message")

    # Compact verbose tool result messages with large JSON arrays
    for i, m in enumerate(trimmed[:compact_boundary]):
        if m.get("role") in ("tool", "function") and isinstance(m.get("content"), str):
            try:
                content = json.loads(m["content"])
                if isinstance(content, list) and len(content) > 5:
                    # Replace with compact summary
                    m["content"] = json.dumps({
                        "type": "property_listings",
                        "count": len(content),
                        "summary": f"{len(content)} properties available",
                        "_full_data_truncated": True
                    })
                    logger.debug(f"[Context] Compacted listing from {len(content)} items to summary")
                elif isinstance(content, dict) and content.get("data") and len(content.get("data", [])) > 5:
                    _data = content.get("data", [])
                    content["data"] = f"[{len(_data)} properties - data truncated]"
                    m["content"] = json.dumps(content)
                    logger.debug(f"[Context] Compacted nested listing from {len(_data)} items to summary")
            except (json.JSONDecodeError, TypeError):
                pass  # Not JSON content, leave as-is

    deduped_trimmed = []
    _duplicate_compacted = 0
    for m in trimmed:
        if (
            deduped_trimmed
            and m.get("role") == "assistant"
            and deduped_trimmed[-1].get("role") == "assistant"
            and (m.get("content") or "").strip() == (deduped_trimmed[-1].get("content") or "").strip()
            and (m.get("content") or "").strip() in {
                "[Property search results presented to user]",
                "[Property details previously presented to user]",
            }
        ):
            _duplicate_compacted += 1
            continue
        deduped_trimmed.append(m)
    if _duplicate_compacted:
        logger.info(f"[Context] Removed {_duplicate_compacted} duplicate compacted assistant message(s)")
    trimmed = deduped_trimmed

    new_messages = system_msgs + greeting + trimmed
    pruned = len(messages) - len(new_messages)
    messages[:] = new_messages
    if pruned > 0:
        logger.info(
            f"[Context] Rolling window: pruned {pruned} old messages "
            f"(kept last {max_turns} turns, total now {len(new_messages)})"
        )
    return max(0, before_count - len(messages))


def _build_transcript_snapshot(messages, *, include_system: bool = False) -> list[dict[str, Any]]:
    """Serialize only spoken conversation turns for persistence/logging."""
    snapshot: list[dict[str, Any]] = []
    def _norm_assistant_text(value: str) -> str:
        return re.sub(r"[^a-z0-9]+", " ", (value or "").lower()).strip()
    for msg in messages or []:
        role = msg.get("role")
        if not include_system and role == "system":
            continue
        if role not in {"user", "assistant"}:
            continue
        content = msg.get("content") if "content" in msg else ""
        if isinstance(content, list):
            content = "".join(
                part.get("text", "")
                for part in content
                if isinstance(part, dict) and isinstance(part.get("text"), str)
            )
        elif content is None:
            content = ""
        else:
            content = str(content)
        content = content.strip()
        if not content:
            continue
        if snapshot and role == "assistant" and snapshot[-1]["role"] == "assistant":
            prev = snapshot[-1]["content"]
            prev_norm = _norm_assistant_text(prev)
            curr_norm = _norm_assistant_text(content)
            if prev_norm == curr_norm:
                continue
            if prev_norm and curr_norm and (
                prev_norm in curr_norm or curr_norm in prev_norm
            ):
                continue
        snapshot.append({
            "role": role,
            "content": content,
        })
    return snapshot


def _record_transcript_turn(
    ledger_ref,
    role: str,
    content: str,
    *,
    source: str = "",
) -> None:
    """Record the actual spoken transcript separately from LLM context."""
    if role not in {"user", "assistant"}:
        return
    text = str(content or "").strip()
    if not text:
        return
    try:
        ledger = ledger_ref[0] if ledger_ref else None
    except Exception:
        ledger = None
    if not isinstance(ledger, list):
        return

    if ledger and ledger[-1].get("role") == role:
        prev = str(ledger[-1].get("content") or "").strip()
        prev_norm = re.sub(r"[^a-z0-9]+", " ", prev.lower()).strip()
        text_norm = re.sub(r"[^a-z0-9]+", " ", text.lower()).strip()
        if prev_norm == text_norm or (prev_norm and text_norm and (prev_norm in text_norm or text_norm in prev_norm)):
            return

    turn = {"role": role, "content": text}
    if source:
        turn["source"] = source
    ledger.append(turn)


def _transcript_from_ledger_or_context(ledger_ref, messages) -> list[dict[str, Any]]:
    try:
        ledger = ledger_ref[0] if ledger_ref else None
    except Exception:
        ledger = None
    if isinstance(ledger, list) and ledger:
        return [
            {"role": str(item.get("role") or ""), "content": str(item.get("content") or "")}
            for item in ledger
            if item.get("role") in {"user", "assistant"} and str(item.get("content") or "").strip()
        ]
    return _build_transcript_snapshot(messages)


# Placeholder values the LLM uses when it doesn't actually have the information.
# Word-overlap checks can falsely pass these (e.g. "name" is in user_words when
# the user said "my name is..."), so we reject them outright.
_PLACEHOLDER_RE = re.compile(
    r"^(user('s)?\s+(first\s+)?name|first\s+name|last\s+name|your\s+name|"
    r"caller('s)?\s+name|full\s+name|contact\s+name|"
    r"\[.*?\]|<.*?>|unknown|n/?a|none|placeholder|tbd|enter\s+\w+)$",
    re.IGNORECASE,
)

_INVALID_FIRST_NAME_TOKENS = {
    "looking", "interested", "calling", "asking", "going", "schedule", "visit",
    "tomorrow", "today", "time", "date", "apartment", "apartments", "property",
    "callback", "site", "name", "customer", "user", "caller",
}


def _clean_first_name_candidate(value: str) -> str:
    tokens = re.findall(r"[A-Za-z][A-Za-z'-]*", str(value or ""))
    if not tokens:
        return ""
    first = tokens[0].strip("'-")
    if len(first) < 2 or first.lower() in _INVALID_FIRST_NAME_TOKENS:
        return ""
    return first[:40].title()


def _extract_caller_first_name_from_text(text: str, *, allow_bare: bool = False) -> str:
    raw = str(text or "").strip()
    if not raw:
        return ""
    patterns = (
        r"\bmy\s+name\s+is\s+([A-Za-z][A-Za-z'-]*)",
        r"\bname\s+is\s+([A-Za-z][A-Za-z'-]*)",
        r"\b(?:i\s+am|i'm)\s+([A-Za-z][A-Za-z'-]*)",
        r"\bthis\s+is\s+([A-Za-z][A-Za-z'-]*)",
    )
    for pattern in patterns:
        match = re.search(pattern, raw, re.IGNORECASE)
        if match:
            candidate = _clean_first_name_candidate(match.group(1))
            if candidate:
                return candidate
    if allow_bare:
        words = re.findall(r"[A-Za-z][A-Za-z'-]*", raw)
        if 1 <= len(words) <= 2:
            return _clean_first_name_candidate(words[0])
    return ""


_NUMBER_WORDS: dict[str, str] = {
    "zero": "0", "one": "1", "two": "2", "three": "3", "four": "4",
    "five": "5", "six": "6", "seven": "7", "eight": "8", "nine": "9",
    "ten": "10", "eleven": "11", "twelve": "12", "thirteen": "13",
    "fourteen": "14", "fifteen": "15", "sixteen": "16", "seventeen": "17",
    "eighteen": "18", "nineteen": "19", "twenty": "20", "thirty": "30",
    "forty": "40", "fifty": "50", "sixty": "60", "seventy": "70",
    "eighty": "80", "ninety": "90", "hundred": "100",
    # digit â†’ word reverse mapping is also added dynamically below
}
# Add reverse: "0"â†’"zero", "1"â†’"one", ... so digit values validate against word speech
_DIGIT_TO_WORD: dict[str, str] = {v: k for k, v in _NUMBER_WORDS.items()}


def _digit_to_word(value: int) -> str:
    return _DIGIT_TO_WORD.get(str(value), str(value))


def _expand_number_words(words: set) -> set:
    """Expand a word set so number words and their digit equivalents are both present.

    e.g. {"three"} â†’ {"three", "3"}   and   {"3"} â†’ {"3", "three"}
    This means a user saying "Three" and an LLM setting result_count="3" will match.
    """
    expanded = set(words)
    for w in words:
        if w in _NUMBER_WORDS:
            expanded.add(_NUMBER_WORDS[w])
        if w in _DIGIT_TO_WORD:
            expanded.add(_DIGIT_TO_WORD[w])
    return expanded


