def _normalize_location_key(value: str) -> str:
    value = re.sub(r"[^\w\s]", " ", (value or "").lower())
    value = re.sub(r"\s+", " ", value).strip()
    return value


def _alternative_area_alias_variants(location: str) -> set[str]:
    norm = _normalize_location_key(location)
    if not norm:
        return set()

    variants = {
        norm,
        norm.replace(" ", ""),
    }
    if norm == "thiruporur":
        variants.update({"tirupur", "thirupur", "tiru porur", "thiru porur", "tiruppur"})
    if norm == "puliyamangalam":
        variants.update({"puliya mangalam", "pulia mangalam", "puli mangalam", "puliyamangalam"})
    return {v for v in variants if v}


def _match_alternative_area_choice(text: str, gathered_search: dict | None) -> str | None:
    raw = str(text or "").strip()
    if not raw or not isinstance(gathered_search, dict):
        return None

    options = gathered_search.get("_alternative_area_options") or []
    aliases = dict(gathered_search.get("_alternative_area_aliases") or {})
    for option in options:
        if isinstance(option, dict):
            name = str(option.get("name") or option.get("location") or option.get("area") or "").strip()
        else:
            name = str(option or "").strip()
        if not name:
            continue
        for variant in _alternative_area_alias_variants(name):
            aliases.setdefault(_normalize_location_key(variant), name)

    if not aliases:
        return None

    norm_text = _normalize_location_key(raw)
    compact_text = norm_text.replace(" ", "")
    for alias, canonical in aliases.items():
        alias_norm = _normalize_location_key(alias)
        if not alias_norm:
            continue
        alias_compact = alias_norm.replace(" ", "")
        if (
            re.search(r"(?<![a-z0-9])" + re.escape(alias_norm) + r"(?![a-z0-9])", norm_text)
            or (len(alias_compact) >= 4 and alias_compact in compact_text)
        ):
            return str(canonical or "").strip() or None
    return None


def _catalog_location_alias_variants(location: str) -> set[str]:
    norm = _normalize_location_key(location)
    if not norm:
        return set()

    variants = {
        norm,
        norm.replace(" ", ""),
    }

    swap_pairs = (
        (" road", " rd"),
        (" rd", " road"),
        (" street", " st"),
        (" st", " street"),
        (" avenue", " ave"),
        (" ave", " avenue"),
        (" nagar", " ngr"),
        (" colony", " colny"),
        (" salai", " sali"),
        (" mount poonamalle", " mount poonamallee"),
        (" poonamalle", " poonamallee"),
        (" chromepet", " chrompet"),
        (" chrompet", " chromepet"),
    )

    expanded = set(variants)
    for base in list(expanded):
        for src, dst in swap_pairs:
            if src in base:
                swapped = base.replace(src, dst)
                expanded.add(swapped)
                expanded.add(swapped.replace(" ", ""))

    if " and " in norm:
        expanded.add(norm.replace(" and ", " & "))
    if " & " in location.lower():
        expanded.add(_normalize_location_key(location.replace("&", "and")))

    return {item for item in expanded if item}


