def _load_chennai_catalog_locations() -> list[str]:
    try:
        catalog_path = os.path.join(
            os.path.dirname(__file__),
            "..",
            "backend",
            "src",
            "data",
            "jll-catalog.json",
        )
        with open(catalog_path, "r", encoding="utf-8") as f:
            data = json.load(f)
        locations = (((data.get("by_city") or {}).get("Chennai") or {}).get("locations")) or []
        seen: set[str] = set()
        unique_locations: list[str] = []
        for loc in locations:
            clean = str(loc or "").strip()
            if clean and clean not in seen:
                seen.add(clean)
                unique_locations.append(clean)
        return unique_locations
    except Exception as e:
        logger.warning(f"[LocationAliases] Failed to load Chennai catalog locations: {e}")
        return []


_CHENNAI_CATALOG_LOCATIONS = _load_chennai_catalog_locations()

