def _norm_loc(s: str) -> str:
    """Normalize location string for comparison (remove punctuation, normalize spaces)."""
    return s.lower().replace(".", " ").replace("-", " ").replace("  ", " ").strip()


def _location_keyword_variants(location: str) -> set[str]:
    norm = _normalize_location_key(location)
    if not norm:
        return set()

    variants = {
        norm,
        norm.replace(" ", ""),
    }

    token_swaps = (
        (" nagar", "nagar"),
        (" layout", "layout"),
        (" road", "rd"),
        ("puram", "pur"),
        ("iyur", "yur"),
        ("aiy", "ay"),
        ("cheri", "cherry"),
        ("chery", "cherry"),
    )
    for src, dst in token_swaps:
        if src in norm:
            swapped = norm.replace(src, dst)
            variants.add(swapped)
            variants.add(swapped.replace(" ", ""))

    return {v for v in variants if v}


def _resolve_canonical_location(raw_location: str, city: str | None, catalog: dict | None = None) -> str | None:
    norm_raw = _normalize_location_key(raw_location)
    if not norm_raw:
        return None

    known_locations: list[str] = []
    if city:
        known_locations.extend(
            (((catalog or {}).get("by_city") or {}).get(city, {}) or {}).get("locations") or []
        )
        known_locations.extend(_KNOWN_LOCATIONS.get(city, []))

    if not known_locations:
        return None

    known_keys = {_normalize_location_key(str(item or "")) for item in known_locations if str(item or "").strip()}
    alias_match = _LOCATION_ALIASES.get(norm_raw)
    if alias_match and _normalize_location_key(alias_match) in known_keys:
        return alias_match

    canonical_by_keyword: dict[str, str] = {}
    for known in known_locations:
        for variant in _location_keyword_variants(known):
            canonical_by_keyword.setdefault(variant, known)

    direct_match = canonical_by_keyword.get(norm_raw) or canonical_by_keyword.get(norm_raw.replace(" ", ""))
    if direct_match:
        return direct_match

    match = difflib.get_close_matches(
        norm_raw.replace(" ", ""),
        list(canonical_by_keyword.keys()),
        n=1,
        cutoff=0.84,
    )
    if match:
        return canonical_by_keyword[match[0]]

    decision = _catalog_fuzzy_decision(
        raw_location,
        known_locations,
        aliases={},
        accept_threshold=0.9,
        confirm_threshold=0.74,
    )
    if decision.action == "accept":
        return decision.value

    return None

# â”€â”€ Persona detection - investor keyword pattern â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
# Location commit guard: only concrete catalog/known/alias locations can enter session memory.
def _find_known_location_in_text(text: str, city: str | None, catalog: dict | None = None) -> str | None:
    """Find a known/catalog locality embedded in a natural-language utterance."""
    raw = str(text or "").strip()
    if not raw:
        return None

    city_key = (city or "Chennai").strip() or "Chennai"
    known_locations: list[str] = []
    known_locations.extend(
        (((catalog or {}).get("by_city") or {}).get(city_key, {}) or {}).get("locations") or []
    )
    known_locations.extend(_KNOWN_LOCATIONS.get(city_key, []))

    lower = raw.lower()
    seen: set[str] = set()
    for loc in known_locations:
        loc_s = str(loc or "").strip()
        loc_key = loc_s.lower()
        if not loc_s or loc_key in seen:
            continue
        seen.add(loc_key)
        if len(loc_s) >= 3 and re.search(r"(?<![a-z0-9])" + re.escape(loc_key) + r"(?![a-z0-9])", lower):
            return loc_s

    norm_text = _normalize_location_key(raw)
    compact_text = norm_text.replace(" ", "")
    for alias_key, canonical in _LOCATION_ALIASES.items():
        alias_norm = _normalize_location_key(alias_key)
        if not alias_norm or len(alias_norm) < 3:
            continue
        alias_compact = alias_norm.replace(" ", "")
        if (
            re.search(r"(?<![a-z0-9])" + re.escape(alias_norm) + r"(?![a-z0-9])", norm_text)
            or (len(alias_compact) >= 3 and alias_compact in compact_text)
        ):
            return canonical

    return None


_GENERIC_NON_LOCATION_WORDS = {
    "a", "an", "the", "any", "some", "all", "this", "that",
    "property", "properties", "home", "homes", "house", "houses",
    "apartment", "apartments", "flat", "flats", "villa", "villas",
    "plot", "plots", "real", "estate", "looking", "searching",
    "finding", "buying", "selling", "renting", "budget", "price",
    "range", "category",
}

_LOCATION_CONFIRM_ONLY_ALIASES: dict[str, str] = {
    _normalize_location_key("andy burger"): "Adambakkam",
    _normalize_location_key("andy burgher"): "Adambakkam",
    _normalize_location_key("andey burger"): "Adambakkam",
}


def _is_commit_safe_location_candidate(
    location: str,
    city: str | None,
    catalog: dict | None = None,
) -> bool:
    """Return True only for concrete catalog/known/alias locations."""
    raw = str(location or "").strip()
    if not raw:
        return False
    norm = _normalize_location_key(raw)
    if not norm or norm in _CITY_CANONICAL:
        return False

    city_key = (city or "Chennai").strip() or "Chennai"
    if _resolve_canonical_location(raw, city_key, catalog):
        return True

    catalog_locations = (
        (((catalog or {}).get("by_city") or {}).get(city_key, {}) or {}).get("locations")
        or []
    )
    known_locations = list(catalog_locations) or _KNOWN_LOCATIONS.get(city_key, [])
    norm_compact = norm.replace(" ", "")
    for known in known_locations:
        known_norm = _normalize_location_key(str(known or ""))
        if known_norm and norm_compact == known_norm.replace(" ", ""):
            return True

    words = [w.lower() for w in re.findall(r"[a-z0-9]+", raw)]
    if not words or any(w in _GENERIC_NON_LOCATION_WORDS for w in words):
        return False

    return False


# Persona detection - investor keyword pattern.
# Triggers a confirmation question ("investing or own use?") before first search.
_INVESTOR_KEYWORDS_RE = re.compile(
    r'\b(invest(?:ment|ing)?|rental\s+yield|roi|returns?|passive\s+income|'
    r'portfolio|lease|tenant|appreciation|resale\s+value|buy\s+to\s+rent)\b',
    re.IGNORECASE,
)

# Investor intent confirmation - positive/negative answer detection
_INVESTOR_YES_RE = re.compile(
    r'\b(invest(?:ment|ing)?|rental|yield|returns?|income|lease|yes.*invest|invest.*yes)\b',
    re.IGNORECASE,
)
_INVESTOR_NO_RE = re.compile(
    r'\b(own\s+use|personal\s+use|myself|my\s+family|live|stay|reside|'
    r'self\s+use|end\s+use|not\s+invest|no)\b',
    re.IGNORECASE,
)

# Callback / site-visit tool name patterns - used to detect "hot" lead signals
_CALLBACK_TOOL_RE = re.compile(
    r'(callback|call_back|submit_callback|arrange_callback|request_callback)', re.IGNORECASE
)
_VISIT_TOOL_RE = re.compile(
    r'(site_visit|visit_booking|book_visit|schedule_visit|book_site)', re.IGNORECASE
)

