    # Units: English + Tamil ("kodi" = crore, "latcham/laksham" = lakh)
    r'\s*(lakh|lakhs?|crore|crores?|cr(?=[\s,.]|$)'
    r'|kodi|kodis?|koadi'
    r'|latcham|latchams?|laksham|lakshams?)',
