_BUDGET_CRORE_ALIAS_PATTERN = "|".join(
    re.escape(alias)
    for alias in sorted(set(_BUDGET_CRORE_ALIASES), key=len, reverse=True)
)
_BUDGET_CRORE_SAFE_ALIAS_RE = re.compile(
    rf'\b(?:grow|grove|grore|crow|crows|core|coor|croar|croer|krore|karor|{_BUDGET_CRORE_ALIAS_PATTERN})\b',
    re.IGNORECASE,
)
_BUDGET_CRORE_CONTEXT_ALIAS_RE = re.compile(
    rf'\b(?P<amount>{_BUDGET_NUMBER_PREFIX_RE})[\s.,:-]+'
    rf'(?P<unit>gross|groce|gros|crows?|grow|grove|grore|crow|core|coor|croar|croer|krore|karor|{_BUDGET_CRORE_ALIAS_PATTERN})\b',
    re.IGNORECASE,
)


def _normalize_budget_stt_units(text: str) -> str:
    """Normalize budget-only STT unit confusions without rewriting normal prose."""
    if not text:
        return text

    def _replace_contextual_crore(match: re.Match) -> str:
        raw = match.group(0)
        amount = match.group("amount")
        normalized = f"{amount} crore"
        if raw.lower() != normalized.lower():
            logger.info(
                f"[BudgetSTTGuard] normalized_unit raw={raw!r} normalized={normalized!r}"
            )
        return normalized

    normalized_text = _BUDGET_CRORE_CONTEXT_ALIAS_RE.sub(_replace_contextual_crore, text)
    normalized_text = _BUDGET_CRORE_SAFE_ALIAS_RE.sub("crore", normalized_text)
    return normalized_text


# [Fix-AmbiguousYes] Bare affirmatives (yes/ok/sure/yeah) removed - they are
