def _parse_inr_amounts(text: str, *, allow_bare_rupees: bool = False) -> list[int]:
    """Extract INR values from natural text.

    Handles English and Tamil number words + units:
      'seventy lakhs'  â†’ 7_000_000
      '1 kodi'         â†’ 10_000_000  (kodi = crore in Tamil)
      'oru kodi'       â†’ 10_000_000  (oru = one in Tamil)
      'aimbathu latcham' â†’ 5_000_000 (aimbathu=50, latcham=lakh)
      '80,00,000'      â†’ 8_000_000   (Indian digit format from Azure STT)
      '1,50,00,000'    â†’ 15_000_000  (1.5 crore in Indian format)
    """
    # â”€â”€ STT phonetic mishearing normalization â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    # Azure/Deepgram can mishear "crore" as "gross", "grow", "grove", "crow", "core", etc.
    # "lakh" is sometimes misheard as "lock" or "luck".
    # Also handle "3. Grow." where STT inserts a period between number and unit.
    text = _normalize_budget_stt_units(text)
    text = re.sub(
        rf'\b({_BUDGET_NUMBER_PREFIX_RE})\s+(?:pro|bro|core|coor|cro|croar|croer|krore|karor)\b',
        r'\1 crore',
        text,
        flags=re.IGNORECASE,
    )
    # "N. crore" â†’ "N crore"  (period inserted by STT between digit and unit word)
    text = re.sub(
        r'(\d)\.\s+(?=(?:crore|lakh|lakhs?|cr\b|kodi|latcham)\b)',
        r'\1 ', text, flags=re.IGNORECASE
    )
    # INDIAN_DIGIT_FMT_PRE: handle Azure STT digit-format numbers before word parser.
    import re as _re_indian
    _indian_results: list[int] = []
    _INDIAN_COMMA_RE = _re_indian.compile(r'\b(\d{1,3}(?:,\d{2}){1,3},\d{3})\b')
    for _m in _INDIAN_COMMA_RE.finditer(text):
        try:
            _val = int(_m.group(1).replace(",", ""))
            if _val >= 100_000:
                _indian_results.append(_val)
        except ValueError:
            pass
    if not _indian_results:
        _PLAIN_BIG_RE = _re_indian.compile(r'(?<![\d,])(\d{6,10})(?![\d,])')
        for _m in _PLAIN_BIG_RE.finditer(text):
            try:
                _val = int(_m.group(1))
                if 100_000 <= _val <= 5_000_000_000:
                    _indian_results.append(_val)
            except ValueError:
                pass
    if _indian_results:
        return _indian_results
    _LAKH_UNITS  = {"lakh", "lakhs", "latcham", "latchams", "laksham", "lakshams"}
    _CRORE_UNITS = {"crore", "crores", "cr", "kodi", "kodis", "koadi"}
    result = []
    matches = list(_INR_AMOUNT_RE.finditer(text))
    i = 0
    while i < len(matches):
        m = matches[i]
        raw, unit = m.group(1), m.group(2).lower().rstrip('s')
        # strip trailing 's' for plural normalisation (kodisâ†’kodi, lakhsâ†’lakh)
        unit_norm = unit.rstrip('s')
        try:
            num = float(raw)
        except ValueError:
            num = _INR_WORD_VAL.get(raw.lower(), 0.0)
        if not num:
            i += 1
            continue
        if unit_norm in {"lakh", "latcham", "laksham"}:
            total = int(num * 100_000)
        else:
            total = int(num * 10_000_000)  # crore / kodi
            # Combine "1 crore 61 lakhs" into a single INR amount.
            if i + 1 < len(matches):
                m2 = matches[i + 1]
                raw2, unit2 = m2.group(1), m2.group(2).lower().rstrip('s')
                unit2_norm = unit2.rstrip('s')
                _between = text[m.end():m2.start()]
                if unit2_norm in {"lakh", "latcham", "laksham"} and re.fullmatch(r'[\s,.-]*(?:and\s+)?', _between, re.IGNORECASE):
                    try:
                        num2 = float(raw2)
                    except ValueError:
                        num2 = _INR_WORD_VAL.get(raw2.lower(), 0.0)
                    if num2:
                        total += int(num2 * 100_000)
                        i += 1
        result.append(total)
        i += 1
    if result:
        return result

    if not allow_bare_rupees:
        return result

    bare_results: list[int] = []
    for _m in re.finditer(r'(?<![a-z0-9])(?:rs\.?|inr|₹)?\s*(\d[\d,]{0,11})(?:\s*(?:rupees?|rs))?(?![a-z0-9])', text, re.IGNORECASE):
        raw = (_m.group(1) or "").replace(",", "")
        try:
            value = int(raw)
        except ValueError:
            continue
        if value > 0:
            bare_results.append(value)

    if bare_results:
        return bare_results

    for word, value in _INR_WORD_VAL.items():
        if value > 0 and re.search(rf'\b{re.escape(word)}\s+rupees?\b', text, re.IGNORECASE):
            return [int(value)]

    return result


# â”€â”€ Strict location alias map â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
# Used by the location validation guard to decide whether a returned property
# truly matches the requested location. Maps each canonical form to ALL valid
# representations that appear in JLL data, including dotted abbreviations and
# full-form names. This prevents two classes of error:
#   (a) False negative: "T Nagar" request rejects a valid "T. Nagar" result
#   (b) False positive: "T Nagar" tokens match "Thyagaraya Nagar" (a distinct area)
#
# Items not in this map fall back to a full-name substring check (the requested
# location normalised string must appear verbatim in the item's location field),
# followed by a token match requiring tokens â‰¥5 chars to avoid matching generic
# words like "nagar" or "road".
_LOC_ALIAS_MAP: dict[str, list[str]] = {
    # Chennai micro-markets
    "t nagar":        ["t nagar", "t. nagar", "tnagar", "t.nagar"],
    "anna nagar":     ["anna nagar", "annanagar", "anna nagar west", "anna nagar east"],
    "velachery":      ["velachery", "velacherry"],
    "adyar":          ["adyar"],
    "porur":          ["porur"],
    "pallavaram":     ["pallavaram"],
    "tambaram":       ["tambaram"],
    "chromepet":      ["chromepet"],
    "perambur":       ["perambur"],
    "kilpauk":        ["kilpauk"],
    "nungambakkam":   ["nungambakkam"],
    "teynampet":      ["teynampet"],
    "mylapore":       ["mylapore"],
    "mogappair":      ["mogappair"],
    "poonamallee":    ["poonamallee", "poonamallee high road"],
    "ambattur":       ["ambattur"],
    "avadi":          ["avadi"],
    "thirumangalam":  ["thirumangalam"],
    # Chennai corridors (expand to all sub-localities JLL uses)
    "omr":            ["omr", "old mahabalipuram road", "rajiv gandhi salai",
                       "sholinganallur", "perumbakkam", "kelambakkam", "siruseri",
                       "navallur", "navalur", "karapakkam", "thoraipakkam",
                       "thaiyur", "shollinganallur", "perungudi", "egattur",
                       "medavakkam"],
    "ecr":            ["ecr", "east coast road", "kottivakkam", "injambakkam",
                       "akkarai", "uthandi", "neelankarai", "kovalam",
                       "marakkanam", "palavakkam", "vettuvankeni", "kanathur"],
    "gsth":           ["gsth", "grand southern trunk", "tambaram", "chromepet",
                       "pallavaram", "perungalathur", "vandalur", "guduvanchery",
                       "urapakkam"],
    # Bengaluru
    "sarjapur":       ["sarjapur", "sarjapura", "sarjapur road", "attibele"],
    "whitefield":     ["whitefield", "white field", "kadugodi", "hoodi", "varthur"],
    "electronic city":["electronic city", "electronics city", "hosa road", "begur"],
    "hebbal":         ["hebbal", "yelahanka", "devanahalli", "bagalur", "kogilu"],
    "marathahalli":   ["marathahalli"],
    "jp nagar":       ["jp nagar", "j p nagar", "j.p.nagar"],
    "jayanagar":      ["jayanagar"],
    # Hyderabad
    "hitech city":    ["hitech city", "hi-tech city", "hitec city", "madhapur",
                       "kondapur", "gachibowli", "nanakramguda", "raidurgam"],
    "kokapet":        ["kokapet", "narsingi", "puppalaguda", "financial district"],
    "bachupally":     ["bachupally"],
    "kompally":       ["kompally"],
    "nizampet":       ["nizampet"],
}


def _strict_location_match(req_loc: str, item: dict) -> bool:
    """Return True if the property item plausibly belongs to the requested location.

    Strategy (in priority order):
      1. Full-name exact substring: normalised requested location appears verbatim
         in the normalised item location string. This handles dotted-abbreviation
         variants ("T. Nagar" â†’ "t nagar" found in "t. nagar" after normalisation).
      2. Alias expansion: if req_loc is in _LOC_ALIAS_MAP, check whether any alias
         appears in the item location string. Handles corridor expansions (OMR â†’
         Sholinganallur) and full-name lookups (T Nagar â†’ Thyagaraya Nagar).
      3. Long-token fallback: tokens â‰¥5 chars from req_loc appear in item location.
         Minimum of 5 chars prevents "road"/"nagar" false positives.

    All comparisons are done on normalised strings (lowercase, dotsâ†’space, hyphensâ†’space).
    """
    def _norm(s: str) -> str:
        return re.sub(r'\s+', ' ', re.sub(r'[.\-]', ' ', (s or "").lower())).strip()

    item_loc = _norm(" ".join([item.get("location") or "", item.get("micro_market") or ""]))
    req_n    = _norm(req_loc)

    # 1. Full-name substring
    if req_n and req_n in item_loc:
        return True

    # 2. Alias expansion
    for alias in _LOC_ALIAS_MAP.get(req_n, []):
        alias_n = _norm(alias)
        if alias_n and alias_n in item_loc:
            return True

    # 3. Long-token fallback (â‰¥5 chars only to avoid generic words)
    long_tokens = [t for t in req_n.split() if len(t) >= 5]
    if long_tokens and any(t in item_loc for t in long_tokens):
        return True

    return False


# Correction patterns that indicate user is explicitly overriding/changing previous location
_CORRECTION_PATTERNS = [
    "no actually", "no, actually", "no actually", "actually", "sorry", "not that",
    "change", "instead", "switch to", "what about", "show in",
    "make it", "update to", "different area", "other area",
]


# Discovery follow-up patterns for post-budget_too_low scenarios
# When user asks for alternatives after being told budget is too low
_DISCOVERY_FOLLOWUP_RE = re.compile(
    r'\b('
    r'better\s+(?:option|options|alternative|alternatives)|'
    r'other\s+(?:option|options|choice|choices|area|areas)|'
    r'suggest\s+(?:alternative|alternatives|other|else)|'
    r'what\s+else|'
    r'any\s+other|'
    r'show\s+(?:me\s+)?(?:other|more|different)'
    r')\b',
    re.IGNORECASE,
)

_ZERO_RESULT_ADJUST_BUDGET_RE = re.compile(
    r'\b('
    r'adjust(?:\s+my)?\s+budget|'
    r'increase(?:\s+my)?\s+budget|'
    r'raise(?:\s+my)?\s+budget|'
    r'update(?:\s+my)?\s+budget|'
    r'change(?:\s+my)?\s+budget|'
    r'stretch(?:\s+my)?\s+budget|'
    r'my\s+budget'
    r')\b',
    re.IGNORECASE,
)

_ZERO_RESULT_OTHER_AREAS_RE = re.compile(
    r'\b('
    r'other\s+(?:area|areas|location|locations|locality|localities)|'
    r'another\s+(?:area|areas|location|locations|locality|localities|place)|'
    r'different\s+(?:area|areas|location|locations|locality|localities|place)|'
    r'nearby\s+(?:area|areas|location|locations)|'
    r'suggest(?:\s+(?:me|some))?\s+(?:other|nearby)|'
    r'what\s+else|'
    r'any\s+other'
    r')\b',
    re.IGNORECASE,
)


def _is_valid_location(loc: str | None) -> bool:
    """Check if location is a valid, meaningful value (not None, empty, or 'None' string)."""
    if not loc:
        return False
    loc_str = str(loc).strip()
    return loc_str and loc_str.lower() not in ("none", "null", "")


def _extract_search_context(
    context, 
    arguments: dict, 
    catalog: dict | None = None,
    current_location: str | None = None,
    has_live_results: bool = False,
    pending_zero_result_mode: str | None = None,
    confirmed_min_price: int | None = None,
    confirmed_max_price: int | None = None,
) -> tuple[dict, list[dict]]:
    """Gathering orchestrator: extract search params from USER SPEECH, not LLM args.

    Enforces sequential gathering: property type â†’ budget â†’ location â†’ count.
    City is hardcoded to Chennai (Chennai-only deployment).
    Budget is parsed from natural language ("seventy lakhs" â†’ max_price=7000000).

    Args:
        context: The conversation context
        arguments: Tool arguments from LLM
        catalog: Optional catalog data for validation
        current_location: Session's current location (for context-aware override detection)

    Returns (params, missing) where missing is a list of {name, instruction} dicts
    for each field still needed - only the first is surfaced to the LLM at a time.
    """
    messages = getattr(context, "messages", []) or []
    user_texts = [
        m.get("content", "")
        for m in messages[-30:]
        if m.get("role") == "user" and isinstance(m.get("content"), str)
    ]
    joined = " ".join(user_texts)
    lower  = joined.lower()
    params: dict = {}

    # â”€â”€ Interruption/Hard Correction detection â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    # Detect user interrupting mid-flow to correct course: "No no not that...", "Wait..."
    _INTERRUPT_PATTERNS = [
        "no no", "no, no", "nope nope", "wait", "stop", "actually",
        "not that", "not this", "not those", "change", "different",
        "i said", "i meant", "correction", "correct that"
    ]
    # Check MOST RECENT user turn first for interruption signals
    _latest_user_raw = user_texts[-1] if user_texts else ""
    _latest_user_text = _latest_user_raw.lower()
    _latest_user_is_non_location_chatter = is_non_location_chatter(_latest_user_raw)
    _latest_assistant_raw = next(
        (
            m.get("content", "")
            for m in reversed(messages)
            if m.get("role") == "assistant" and isinstance(m.get("content"), str)
        ),
        "",
    )
    _latest_assistant_text = _latest_assistant_raw.lower()
    _has_pending_budget_decision = any(
        isinstance(m, dict)
        and m.get("role") == "system"
        and isinstance(m.get("content"), str)
        and "PENDING BUDGET DECISION" in m.get("content", "")
        for m in messages[-10:]
    )
    _latest_expected_gather_field = _detect_expected_gather_field(messages, city="Chennai")
    _latest_turn_allows_bare_rupee_budget = bool(
        _has_pending_budget_decision
        or _latest_expected_gather_field == "budget"
        or re.search(r'(?:₹|\brs\.?\b|\binr\b|\brupees?\b|\bbudget\b|\bamount\b)', _latest_user_text, re.IGNORECASE)
    )
    _has_interrupt = any(p in _latest_user_text for p in _INTERRUPT_PATTERNS)
    if _has_interrupt:
        params["_force_fresh_search"] = True
        logger.info(f"[Interrupt] detected=True â†’ forcing fresh search")

    # [Fix-BudgetScope] Budget amounts use a most-recent-first single-turn strategy:
    # scan turns newest-first and stop at the FIRST turn that contains any INR amount.
    # This prevents budget contamination when the user changes budget across turns -
    # e.g., "under 80L" then "under 50L" then "under 40L": each new turn has one
    # amount; stopping at the first match means we only parse THAT turn, not all of them.
    # If a single turn contains two amounts ("between 50 and 80 lakhs") they are correctly
    # treated as a range because both exist in the same utterance.
    _budget_joined = ""
    _budget_lower  = ""
    for _idx in range(len(user_texts) - 1, -1, -1):  # newest first
        _bt = user_texts[_idx]
        if is_non_search_slot_chatter(_bt):
            continue
        _bt_amounts = _parse_inr_amounts(
            _bt,
            allow_bare_rupees=(
                _idx == len(user_texts) - 1
                and _latest_turn_allows_bare_rupee_budget
            ),
        )
        if _bt_amounts:
            _budget_joined = _bt
            _budget_lower  = _bt.lower()
            logger.debug(
                f"[Fix-BudgetScope] Budget found in turn: {_bt[:60]!r} "
                f"amounts={_bt_amounts}"
            )
            break
    if not _budget_joined:
        # No amount in any turn - budget will fall through to LLM-arg fallback below
        logger.debug("[Fix-BudgetScope] No INR amounts in any user turn - using LLM args")

    _total_inventory_count_request = _looks_like_total_inventory_count_request(_latest_user_raw)
    if _total_inventory_count_request:
        params["_total_inventory_count_request"] = True
        params["_block_budget_session_fallback"] = True
        _budget_joined = ""
        _budget_lower = ""
        logger.info(
            f"[CountScope] Total inventory count requested without budget scope; "
            f"ignoring stale prior budget latest_user={_latest_user_raw!r}"
        )

    # â”€â”€ City - always Chennai (Chennai-only deployment) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    # City is hardcoded to Chennai; no need to gather from user speech.
    _current_turn_budget_amounts = _parse_inr_amounts(
        _latest_user_raw,
        allow_bare_rupees=_latest_turn_allows_bare_rupee_budget,
    )
    _budget_flexible = _is_flexible_budget_text(_latest_user_raw)
    # Detect time-like strings mistakenly spoken when a budget was expected
    # (e.g. "2:00 o'clock" instead of "2 crore").
    _TIME_AS_BUDGET_RE = re.compile(
        r"\b\d{1,2}:\d{2}\b|\bo'?clock\b|\b\d{1,2}\s*(?:am|pm)\b", re.IGNORECASE
    )
    _user_said_time_not_budget = bool(
        _TIME_AS_BUDGET_RE.search(_latest_user_raw)
        and not _current_turn_budget_amounts
    )
    # Match budget-asking phrases only - NOT price nouns (crore/lakh) that appear
    # in search result listings, which would cause false reconfirmation.
    _BUDGET_ASK_RE = re.compile(
        r'\b(budget|how\s+much|price\s+range|spending\s+limit|what.*spend|what.*afford)\b',
        re.IGNORECASE,
    )
    _explicit_budget_confirm_marker = any(
        isinstance(m, dict)
        and m.get("role") == "system"
        and isinstance(m.get("content"), str)
        and "BUDGET_CONFIRM_PENDING" in m.get("content", "")
        for m in messages[-12:]
    )
    _budget_question_active = bool(
        _explicit_budget_confirm_marker
        or _has_pending_budget_decision
        or _user_said_time_not_budget
    )
    _other_area_meta_choice = bool(_ZERO_RESULT_OTHER_AREAS_RE.search(_latest_user_raw))
    _budget_meta_without_amount = bool(
        _ZERO_RESULT_ADJUST_BUDGET_RE.search(_latest_user_raw)
        and not _current_turn_budget_amounts
        and not _budget_flexible
    )
    _budget_needs_reconfirmation = bool(
        _budget_question_active
        and _latest_user_raw.strip()
        and not _current_turn_budget_amounts
        and not _budget_flexible
        and not _other_area_meta_choice
    )
    if _budget_needs_reconfirmation:
        params["_block_budget_session_fallback"] = True
        _reason = "time_pattern_detected" if _user_said_time_not_budget else "no_inr_amount_parsed"
        logger.warning(
            f"[BudgetConfirm] Fresh budget expected but current turn had no parsed amount; "
            f"reason={_reason} latest_user={_latest_user_raw!r} stale_budget_turn={_budget_joined!r}"
        )
    if _budget_meta_without_amount:
        params["_block_budget_session_fallback"] = True
        params["_block_llm_budget_range_fallback"] = True
        _budget_joined = ""
        _budget_lower = ""
        logger.info(
            f"[BudgetConfirm] Meta budget turn without amount - ignoring stale prior budget "
            f"latest_user={_latest_user_raw!r}"
        )

    params["city"] = "Chennai"

    if _budget_flexible:
        params["_budget_flexible"] = True
        logger.info(f"[Extract] Flexible budget accepted from latest turn: {_latest_user_raw!r}")

    # â”€â”€ Property type - user speech ONLY (like city - no LLM-arg fallback) â”€â”€
    # Accepting arguments.get("property_type") allows the LLM to inject a default
    # from llm_parameters (e.g. "Apartments") before the user has said anything,
    # which skips the gathering question entirely. Extract from speech only.
    ptype = ""
    for _turn in range(len(user_texts) - 1, -1, -1):
        _candidate_type = _extract_property_type_from_text(user_texts[_turn] or "")
        if _candidate_type:
            ptype = _candidate_type
            break
    if ptype:
        params["property_type"] = ptype
    _current_turn_ptype = _extract_property_type_from_text(_latest_user_text)

    # Generic "properties" requests are valid search intent.
    # Leave property_type empty so the backend searches across all types.
    _generic_property_request = (
        not ptype
        and bool(_GENERIC_PROPERTY_RE.search(lower))
    )
    if _generic_property_request:
        params["_generic_property_request"] = True

    for _turn in reversed(user_texts):
        _turn_lower = _turn.lower()
        if _RESALE_PROJECT_RE.search(_turn_lower):
            params["project_category"] = "Resale"
            break
        if _NEW_PROJECT_RE.search(_turn_lower):
            params["project_category"] = "New"
            break
        if _ALL_CATEGORY_CLEAR_RE.search(_turn_lower) and "project_category" not in arguments:
            params["_clear_project_category"] = True
            break

    for _turn in reversed(user_texts):
        _turn_lower = _turn.lower()
        if _READY_TO_MOVE_RE.search(_turn_lower):
            params["construction_state"] = "ready_to_move"
            break
        if _UNDER_CONSTRUCTION_RE.search(_turn_lower):
            params["construction_state"] = "under_construction"
            break
        if _LAUNCHED_RE.search(_turn_lower):
            params["construction_state"] = "launched"
            break
        if _ALL_CONSTRUCTION_CLEAR_RE.search(_turn_lower) and "construction_state" not in arguments:
            params["_clear_construction_state"] = True
            break

    # â”€â”€ Multi-intent detection â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    # Detect queries like "apartments or villas", "2BHK or 3BHK in OMR or ECR"
    # When user presents alternatives with "or", mark for special handling.
    _MULTI_INTENT_RE = re.compile(
        r'\b(or|else)\b',
        re.IGNORECASE
    )
    if _MULTI_INTENT_RE.search(lower):
        # Check if multiple property types are mentioned
        _types_found = set()
        for kw, val in _PROPERTY_TYPE_ALIASES:
            if kw in lower:
                _types_found.add(val)
        if len(_types_found) >= 2:
            params["_multi_intent"] = True
            params["_multi_intent_types"] = list(_types_found)
            logger.info(f"[MultiIntent] detected=True, types={list(_types_found)}")
        elif _MULTI_INTENT_RE.search(lower):
            # Single type but still has "or" pattern (location alternatives, etc.)
            params["_multi_intent"] = True
            params["_multi_intent_types"] = [ptype] if ptype else []
            logger.info(f"[MultiIntent] detected=True (single type with alternatives), primary={ptype}")

    # â”€â”€ Micro-market / area - only extract from recent user speech â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    # We look at only the last 5 user messages (not all history) to avoid
    # picking up area-like words from unrelated earlier parts of the conversation.
    # The regex also has a strict blacklist to reject generic English words that
    # incidentally follow "in" (e.g. "in properties", "in buying", "in touch").
    _NOT_LOCATION_WORDS = {
        "a", "an", "the", "any", "some", "all", "this", "that", "it",
        "properties", "property", "apartments", "apartment", "flats", "flat",
        "villas", "villa", "plots", "plot", "house", "houses", "home", "homes",
        "buying", "selling", "renting", "investing", "looking", "searching",
        "finding", "living", "staying", "real", "estate", "india", "residential",
        "touch", "total", "terms", "general", "market", "options",
        # Guard against "tell me about X" / "I want to know more about the first one"
        "tell", "about", "more", "know", "details", "detail",
        "first", "second", "third", "fourth", "fifth",
        "one", "two", "three", "four", "five", "number", "no",
        "show", "see", "get", "give", "find", "list", "need",
        "hear", "hearing", "listen", "listening", "speak", "speaking",
        "talk", "talking", "here", "there", "continue", "resume",
        # [Fix-LocationFilter] Pronouns and budget/price words that produce garbage
        # locations like "my budget", "your listings", "our price range".
        # "in my budget" â†’ candidate="my budget" â†’ first_word="my" was NOT blocked before.
        "my", "your", "our", "their", "its",
        "price", "range", "budget", "amount", "cost", "limit", "value",
        "category", "preferred", "current", "available", "listed", "offered",
        "existing", "following", "mentioned", "selected", "chosen", "given",
        "future", "past", "recent", "specific", "particular", "typical",
        "above", "below", "between", "within", "around", "nearby", "near",
        "under", "construction", "ready", "move", "launched", "launch",
        "resale",
    }
    city_lower = str(params.get("city") or "").strip().lower()
    # Accept any location-alias parameter the LLM might use: location, area,
    # locality, micro_market, microMarket - LLM occasionally uses wrong key names.
    loc = str(
        arguments.get("location") or arguments.get("area") or
        arguments.get("locality") or arguments.get("micro_market") or
        arguments.get("microMarket") or ""
    ).strip()
    if not loc and params.get("city") and not _latest_user_is_non_location_chatter:
        # Collect the last 8 user turns, most-recent-LAST (so we can iterate reversed)
        recent_user_texts = [
            m.get("content", "")
            for m in messages[-20:]
            if m.get("role") == "user" and isinstance(m.get("content"), str)
        ][-8:]

        # â”€â”€ Scan MOST RECENT FIRST â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        # Joining all turns into one string causes re.search to find the FIRST
        # (oldest) occurrence, not the LATEST. If a user said "T Nagar" earlier
        # and now says "OMR", the join would return T Nagar. Instead, iterate
        # in reverse: newest turn first, stop at the first valid location found.
        _loc_re = re.compile(r'\bin\s+((?:\w+\s*){1,3}?)(?:\s*[,.]|\s*$)', re.IGNORECASE)
        for _turn in reversed(recent_user_texts):
            lm = _loc_re.search(_turn)
            if not lm:
                continue
            candidate = lm.group(1).strip()
            first_word = candidate.split()[0].lower() if candidate.split() else ""
            # [Fix-LocationFilter] Reject candidate if ANY word in it is a non-location
            # word. Guards against "in my budget range" â†’ "my budget range",
            # "in your listings" â†’ "your listings", etc. The first_word check alone was
            # insufficient because "my" was missing from the original set.
            _all_candidate_words = [w.lower() for w in candidate.split()]
            _any_bad_word = any(w in _NOT_LOCATION_WORDS for w in _all_candidate_words)
            if _any_bad_word:
                logger.debug(f"[Fix-LocationFilter] Rejected invalid location candidate: {candidate!r}")
            if (
                not _any_bad_word
                and first_word not in _NOT_LOCATION_WORDS
                and candidate.lower() not in _CITY_CANONICAL
                and candidate.lower() != city_lower
                and len(candidate) > 2
            ):
                loc = candidate
                # STT comma-split fix: "T Nagar" â†’ "tea, Nagar" - extend if single token
                if loc and len(loc.split()) == 1:
                    _comma_m = re.search(
                        re.escape(loc) + r'\s*,\s*(\w+)',
                        _turn, re.IGNORECASE
                    )
                    if _comma_m:
                        _combined = f"{loc} {_comma_m.group(1)}"
                        if _combined.lower() not in _CITY_CANONICAL:
                            logger.info(f"[Extract] Comma-split combined: '{loc}' â†’ '{_combined}'")
                            loc = _combined
                break  # found in this turn - stop, don't scan older turns

        # Keep recent_joined available for bare-area fallback below
        recent_joined = " ".join(recent_user_texts)

    # â”€â”€ [Fix-LatestTurnArea] Latest-turn concrete area beats stale history â”€â”€â”€
    # If the MOST RECENT user turn contains a concrete known area (e.g. "OMR"),
    # it wins - even if the "in X" loop above picked up something like
    # "different areas" from an older turn. Prevents stale generic phrases from
    # clobbering a fresh area name the user just uttered.
    if params.get("city") and not _latest_user_is_non_location_chatter:
        _lt_msgs = [
            m.get("content", "")
            for m in messages[-20:]
            if m.get("role") == "user" and isinstance(m.get("content"), str)
        ]
        if _lt_msgs:
            _lt_text = _lt_msgs[-1].lower()
            for _lt_area in _KNOWN_LOCATIONS.get(params["city"], []):
                if len(_lt_area) >= 3 and re.search(
                    r'\b' + re.escape(_lt_area.lower()) + r'\b', _lt_text
                ):
                    if loc and loc.lower() != _lt_area.lower():
                        logger.info(
                            f"[Fix-LatestTurnArea] Latest turn {_lt_msgs[-1][:30]!r} "
                            f"has '{_lt_area}' - overriding stale loc='{loc}' from older turn"
                        )
                    else:
                        logger.info(f"[Fix-LatestTurnArea] Latest-turn area match: '{_lt_area}'")
                    loc = _lt_area
                    break

    # â”€â”€ Fallback: bare area name (no "in" prefix) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    # Handles "try Velachery", "what about Koramangala?", "Adyar please" after
    # a no_location_match response suggested alternative areas.
    # Scan MOST RECENT FIRST - same reason as above.
    if not loc and params.get("city") and not _latest_user_is_non_location_chatter:
        _city_known = _KNOWN_LOCATIONS.get(params["city"], [])
        recent_user_texts_bare = [
            m.get("content", "")
            for m in messages[-20:]
            if m.get("role") == "user" and isinstance(m.get("content"), str)
        ][-8:]
        for _turn_bare in reversed(recent_user_texts_bare):
            _turn_bare_lower = _turn_bare.lower()
            for _area in _city_known:
                # len >= 3 allows 3-char acronyms like OMR, ECR, GST
                if len(_area) >= 3 and _area.lower() in _turn_bare_lower:
                    loc = _area
                    logger.info(f"[Extract] Bare area match: '{_area}' (from turn: {_turn_bare[:40]!r})")
                    break
            if not loc:
                # Also check alias keys for bare utterances like "thayapakkam" â†’ "Rayapakkam"
                for _akey, _aval in _LOCATION_ALIASES.items():
                    if len(_akey) >= 4 and re.search(r'\b' + re.escape(_akey) + r'\b', _turn_bare_lower):
                        loc = _aval
                        logger.info(f"[Extract] Alias bare match: '{_akey}' â†’ '{_aval}' (from turn: {_turn_bare[:40]!r})")
                        break
            if loc:
                break  # found - stop scanning older turns

    if loc and loc.lower() in _CITY_CANONICAL:
        loc = ""
    if loc and loc.lower() == city_lower:
        loc = ""
    if any(phrase in lower for phrase in (
        "not sure", "dont know", "don't know", "no preference",
        "anywhere", "any area", "any location", "any locality",
        "doesn't matter", "does not matter", "doesnt matter",
        "no area", "no specific", "open to",
    )):
        loc = ""
    if loc:
        _loc_lower = loc.lower().strip()
        if (
            _READY_TO_MOVE_RE.search(_loc_lower)
            or _UNDER_CONSTRUCTION_RE.search(_loc_lower)
            or _LAUNCHED_RE.search(_loc_lower)
            or _NEW_PROJECT_RE.search(_loc_lower)
            or _RESALE_PROJECT_RE.search(_loc_lower)
            or _loc_lower in {"ready to", "ready to move", "under construction", "launched", "resale", "new"}
        ):
            logger.info(f"[Extract] Discarded non-location phrase from location slot: {loc!r}")
            loc = ""
    if loc and len(loc) > 2:
        params["location"] = loc

    # â”€â”€ Short location-switch detection â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    # If user says just a location (OMR?, Adyar?, etc.) without qualifiers,
    # this is likely a location SWITCH, not a show_more. Mark for fresh search.
    _loc_now = params.get("location", "")
    if (
        _loc_now
        and len(joined.strip()) <= 30  # Short query like "OMR?"
        and not _CAP_BUDGET_RE.search(lower)
        and not _FLOOR_BUDGET_RE.search(lower)
    ):
        _has_prior_loc = _is_valid_location(current_location)
        _loc_changed = _has_prior_loc and _loc_now.lower().strip() != current_location.lower().strip()
        if _loc_changed:
            # Treat as explicit location switch (fresh search), but keep the new
            # concrete location available for session-memory commit.
            params["_clear_location"] = True
            params["_citywide_search"] = False
            logger.info(
                f"[Extract] Location switch detected (short query): '{_loc_now}'"
            )

    # â”€â”€ HARD LOCATION OVERRIDE detection â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    # Detect correction phrases + location change that must fully reset context.
    # Requires ALL of: correction pattern, extracted location, valid prior location,
    # AND extracted location is DIFFERENT from current_location.
    # e.g., "No, actually OMR" when current_location="T Nagar" â†’ override=True
    # e.g., "No, actually tell me more about OMR" when current_location="OMR" â†’ override=False
    _correction_match = any(p in lower for p in _CORRECTION_PATTERNS)
    _has_valid_prior = _is_valid_location(current_location)
    _loc_changed = (
        _loc_now
        and _has_valid_prior
        and _loc_now.lower().strip() != current_location.lower().strip()
    )
    if _correction_match and _loc_changed:
        params["_location_override"] = True
        params["_override_old_loc"] = current_location
        params["_override_new_loc"] = _loc_now
        logger.warning(
            f"[LocationOverride] HARD RESET: '{current_location}' â†’ '{_loc_now}' "
            f"(correction_match={_correction_match}, loc_changed={_loc_changed})"
        )
    elif _correction_match and _loc_now and not _has_valid_prior:
        # Correction pattern with location but no valid prior location - fresh search intent
        params["_clear_location"] = True
        logger.info(
            f"[LocationOverride] Fresh search intent (no prior location): '{_loc_now}'"
        )

    # â”€â”€ Budget - parse INR amounts from speech; integer LLM args as fallback â”€
    # Budget qualifier patterns determine whether a single stated amount is a cap,
    # a floor, or a centre point:
    #   "under 50 lakhs" / "within 50 lakhs" / "max 50 lakhs"
    #       â†’ max_price=50L, min_price=catalog city minimum (don't start from â‚¹0)
    #   "above 50 lakhs" / "more than 50 lakhs" / "at least 50 lakhs"
    #       â†’ min_price=50L, no max cap
    #   "50 lakhs" (plain, no qualifier)
    #       â†’ treat as budget centre Â±20%: min=40L, max=60L
    # _CAP_BUDGET_RE and _FLOOR_BUDGET_RE are defined at module level
    # [Fix-BudgetScope] Use scoped buffer (_budget_joined / _budget_lower) so only
    # the last 3 user turns are scanned. This prevents old budget mentions from being
    # combined with the current one into an incorrect range.
    amounts = _parse_inr_amounts(
        _budget_joined,
        allow_bare_rupees=(
            bool(_budget_joined)
            and _budget_joined == _latest_user_raw
            and _latest_turn_allows_bare_rupee_budget
        ),
    )
    _budget_change_signal = bool(re.search(
        r"\b(change\s+my\s+budget|change\s+the\s+budget|new\s+budget|"
        r"update\s+(?:my\s+)?budget|revise\s+(?:my\s+)?budget|instead|actually|"
        r"make\s+it|increase|decrease|raise|lower)\b",
        _latest_user_text,
        re.IGNORECASE,
    ))
    _fresh_budget_statement = bool(re.search(
        r"\b(my\s+budget\s+is|budget\s+is|i\s+have\s+a\s+budget|i\s+can\s+spend|"
        r"under|within|below|above|less\s+than|more\s+than)\b",
        _budget_lower,
        re.IGNORECASE,
    ))
    _explicit_budget_range = bool(re.search(
        r"\bbetween\b|\bfrom\b.{0,20}\bto\b",
        _budget_lower,
        re.IGNORECASE,
    ))
    _fresh_search_budget_turn = bool(
        len(amounts) == 1
        and _budget_joined == _latest_user_raw
        and re.search(
            r"\b(find|search|show|suggest|recommend|looking\s+for|look\s+for|need|want)\b",
            _latest_user_text,
            re.IGNORECASE,
        )
        and (
            bool(_current_turn_ptype)
            or bool(_generic_property_request)
            or bool(re.search(r"\b(properties|property|apartments?|flats?|villas?|plots?)\b", _latest_user_text, re.IGNORECASE))
        )
    )
    _budget_correction_turn = bool(
        len(amounts) == 1
        and _budget_joined == _latest_user_raw
        and re.search(
            r"\b(i\s+asked\s+for|asked\s+for|i\s+meant|meant|not|instead|actually)\b",
            _latest_user_text,
            re.IGNORECASE,
        )
    )
    _confirmed_budget = None
    try:
        _confirmed_budget = int(confirmed_max_price or confirmed_min_price or 0) or None
    except (TypeError, ValueError):
        _confirmed_budget = None
    _budget_overwrite_skipped = False
    if amounts and has_live_results and not pending_zero_result_mode and _confirmed_budget:
        _candidate_budget = max(amounts)
        _diff_ratio = abs(_candidate_budget - _confirmed_budget) / max(_confirmed_budget, 1)
        _allow_live_budget_update = bool(
            _budget_change_signal
            or (len(amounts) == 1 and _fresh_budget_statement and _diff_ratio > 0.20)
            or (_fresh_search_budget_turn and _diff_ratio > 0.20)
            or (_budget_correction_turn and _diff_ratio > 0.20)
        )
        if _allow_live_budget_update and (_fresh_search_budget_turn or _budget_correction_turn):
            logger.info(
                f"[BudgetGuard] allowed_overwrite confirmed={_confirmed_budget} "
                f"candidate={_candidate_budget} reason="
                f"{'budget_correction' if _budget_correction_turn else 'fresh_search_with_budget'}"
            )
        if not _allow_live_budget_update:
            logger.info(
                f"[BudgetGuard] skipped_overwrite confirmed={_confirmed_budget} "
                f"candidate={_candidate_budget} reason=live_results_active"
            )
            amounts = []
            _budget_joined = ""
            _budget_lower = ""
            _budget_overwrite_skipped = True
            params["_block_llm_budget_range_fallback"] = True
    if len(amounts) >= 2 and _budget_change_signal and not _explicit_budget_range:
        _largest_amount = max(amounts)
        logger.info(f"[BudgetGuard] correction_multi_amount using_largest={_largest_amount} amounts={amounts}")
        amounts = [_largest_amount]
    if len(amounts) >= 2:
        # Explicit range stated by user ("between 40 and 60 lakhs") - only valid when
        # BOTH amounts appear in the same recent turn or consecutive turns.
        params["min_price"], params["max_price"] = sorted(amounts)[:2]
        logger.info(f"[Fix-BudgetScope] Budget range (recent turns): {sorted(amounts)[:2]}")
    elif len(amounts) == 1:
        _amt = amounts[0]
        if _CAP_BUDGET_RE.search(_budget_lower):
            # "under 50 lakhs" â†’ cap only; use catalog city min as floor
            params["max_price"] = _amt
            _inline_cat_min = None
            if params.get("city") and catalog:
                _inline_cat_min = (
                    (catalog.get("by_city") or {})
                    .get(params["city"], {})
                    .get("min_price")
                )
            if _inline_cat_min:
                params["min_price"] = int(_inline_cat_min)
            logger.info(
                f"[Extract] Budget cap: max={_amt} "
                f"min={params.get('min_price', 'not set')} (catalog floor)"
            )
        elif _FLOOR_BUDGET_RE.search(_budget_lower):
            # "above 50 lakhs" â†’ floor only
            params["min_price"] = _amt
            logger.info(f"[Extract] Budget floor: min={_amt}")
        else:
            # Plain amount â†’ treat as centre, Â±20%
            params["min_price"] = int(_amt * 0.8)
            params["max_price"] = int(_amt * 1.2)
            logger.info(
                f"[Extract] Budget centre: {_amt} â†’ "
                f"min={params['min_price']} max={params['max_price']}"
            )
    if (
        len(amounts) == 1
        and not _CAP_BUDGET_RE.search(_budget_lower)
        and not _FLOOR_BUDGET_RE.search(_budget_lower)
        and _LUXURY_INTENT_RE.search(joined)
    ):
        params["min_price"] = amounts[0]
        params.pop("max_price", None)
        params["_implied_luxury_budget"] = True
        logger.info(f"[Extract] Luxury budget override: min={amounts[0]} max=unset")

    if _budget_needs_reconfirmation:
        params.pop("min_price", None)
        params.pop("max_price", None)
    if not params.get("min_price") and not params.get("max_price") and not _budget_overwrite_skipped:
        try:
            arg_min = arguments.get("min_price")
            arg_max = arguments.get("max_price")
            if arg_min is not None:
                params["min_price"] = int(arg_min)
            if arg_max is not None:
                params["max_price"] = int(arg_max)
        except (ValueError, TypeError):
            pass
        # LLM sometimes passes budget_range as "N-N" (point) or "A-B" (range).
        # Parse and spread point budgets Â±20% so they don't over-constrain JLL.
        if (
            not params.get("min_price")
            and not params.get("max_price")
            and not params.get("_block_llm_budget_range_fallback")
            and not _budget_overwrite_skipped
        ):
            _llm_br = str(arguments.get("budget_range") or "").strip()
            if _llm_br and "-" in _llm_br:
                try:
                    _br_lo, _br_hi = (int(x) for x in _llm_br.split("-", 1))
                    if _br_lo > 0 or _br_hi > 0:
                        if _br_lo == _br_hi:
                            # Point budget - spread Â±20%
                            params["min_price"] = int(_br_lo * 0.8)
                            params["max_price"] = int(_br_hi * 1.2)
                            logger.info(
                                f"[Extract] budget_range fallback (pointâ†’spread): "
                                f"{_br_lo} â†’ min={params['min_price']} max={params['max_price']}"
                            )
                        else:
                            params["min_price"] = _br_lo
                            params["max_price"] = _br_hi
                            logger.info(f"[Extract] budget_range fallback (range): min={_br_lo} max={_br_hi}")
                except (ValueError, TypeError):
                    pass

    if (
        not params.get("min_price")
        and not params.get("max_price")
        and not _budget_overwrite_skipped
        and _LUXURY_INTENT_RE.search(joined)
    ):
        params["min_price"] = _LUXURY_BUDGET_FLOOR
        params["_implied_luxury_budget"] = True
        logger.info(
            f"[Extract] Luxury intent detected -> implied min_price={_LUXURY_BUDGET_FLOOR}"
        )

    # â”€â”€ Bedrooms / BHK - resolve from the MOST RECENT matching turn first â”€â”€
    # Joining all user turns lets an old "4 BHK" override a fresh "two BHK".
    # Scan newest-first and support both digits and number words.
    _BHK_WORDS = r'(\d+(?:\.\d+)?|one|two|three|four|five|six)'
    _BHK_RE = re.compile(
        rf'\b{_BHK_WORDS}\s*(?:bhk|bed|bedroom|bedrooms)\b',
        re.IGNORECASE,
    )
    for _turn in reversed(user_texts):
        if is_non_search_slot_chatter(_turn):
            continue
        _bhk_match = _BHK_RE.search(_turn.lower())
        if not _bhk_match:
            continue
        _bhk_value = _bhk_match.group(1).strip().lower()
        _bhk_value = _NUMBER_WORDS.get(_bhk_value, _bhk_value)
        try:
            _bhk_num = float(_bhk_value)
            params["bedrooms"] = str(int(_bhk_num)) if _bhk_num.is_integer() else _bhk_value
            logger.info(f"[Extract] Bedrooms detected: {params['bedrooms']} BHK")
            break
        except (TypeError, ValueError):
            continue

    # â”€â”€ Result count - detect explicit "next two", "show three properties" etc. â”€â”€
    # Guard against BHK phrases so "2 BHK" does not become result_count=2.
    _COUNT_WORDS = r'(\d+|one|two|three|four|five|six|seven|eight|nine|ten|twelve|fifteen|twenty)'
    _NO_BHK = r'(?!\s*bhk|\s*bed|\s*bedroom)'
    _RESULT_COUNT_PATTERNS = (
        rf'(?:show|see|want|give|find|get|list|need|tell)\s+(?:me\s+)?(?:the\s+)?(?:next\s+)?{_COUNT_WORDS}{_NO_BHK}\s+'
        rf'(?:properties?|results?|listings?|options?|apartments?|villas?|plots?)(?:\b|$)',
        rf'(?:next|another|only|just)\s+{_COUNT_WORDS}{_NO_BHK}\s+'
        rf'(?:properties?|results?|listings?|options?|apartments?|villas?|plots?)(?:\b|$)',
        rf'{_COUNT_WORDS}\s+(?:more\s+)?(?:properties?|results?|listings?|options?|apartments?|villas?|plots?){_NO_BHK}(?:\b|$)',
    )
    for _turn in reversed(user_texts):
        _turn_lower = _turn.lower()
        if is_non_search_slot_chatter(_turn):
            continue
        cm = None
        for _pattern in _RESULT_COUNT_PATTERNS:
            cm = re.search(_pattern, _turn_lower, re.IGNORECASE)
            if cm:
                break
        if not cm:
            continue
        raw = next((g for g in cm.groups() if g), "").strip().lower()
        params["result_count"] = _NUMBER_WORDS.get(raw, raw)
        break

    # â”€â”€ Sequential required-field check (ask one at a time) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    # Sequence: city â†’ (validate city) â†’ property_type â†’ (validate type) â†’
    #           budget â†’ (validate budget) â†’ location
    # Validation uses the JLL catalog (passed in from IntegrationToolHandler).
    # Location is SKIPPED when user explicitly says they have no area preference.
    _NO_AREA_PHRASES = [
        "not sure", "dont know", "don't know", "no preference",
        "anywhere", "any area", "any location", "any locality",
        "doesn't matter", "does not matter", "doesnt matter",
        "no area", "no specific", "open to anywhere", "open to any area",
        "open to any location", "open to any locality",
    ]
    _user_skipped_location = _is_citywide_location_text(_latest_user_raw) or any(phrase in lower for phrase in _NO_AREA_PHRASES)
    if _user_skipped_location:
        logger.info(f"[Extract] City-wide location accepted from speech: {_latest_user_raw!r}")

    # Discovery questions: user is asking the agent to pick an area, not searching
    # a specific known locality. These must trigger city-wide mode so the session's
    # cached location (e.g. "T Nagar" from a prior search) is NOT injected.
    # Pattern is anchored to question words + area/price intent to avoid false
    # positives like "which apartment in T Nagar has the best price?" (that sentence
    # has an explicit location so it should NOT trigger city-wide).
    _DISCOVERY_QUESTION_RE = re.compile(
        r'\b('
        # Explicit area-question phrases
        r'which\s+area|what\s+area|what\s+location|'
        r'which\s+location|which\s+locality|what\s+locality|'
        r'best\s+area|cheapest\s+area|affordable\s+area|good\s+area|'
        r'lowest\s+(?:budget|price)\s+(?:area|location|locality)|'
        r'suggest\s+(?:a|an|some)?\s*(?:good|affordable|cheap|best)?\s*(?:area|location|locality)|'
        r'where\s+(?:can\s+I|should\s+I|is\s+(?:it|there))\s+(?:find|look|buy|get|search)|'
        # Natural affordability phrasing - user wants agent to surface cheaper options
        # without specifying a location ("anything cheaper", "low budget homes", etc.)
        r'cheaper\s+(?:options?|properties|homes?|apartments?|villas?|plots?)|'
        r'affordable\s+(?:homes?|properties|options?|apartments?|villas?|plots?)|'
        r'low\s+(?:budget|cost|price)\s+(?:homes?|properties|options?|apartments?|villas?|plots?)|'
        r'anything\s+cheaper|something\s+affordable|something\s+cheaper|'
        r'options?\s+under\s+\d|options?\s+(?:within|below|under)\s+(?:my\s+)?budget|'
        # Short standalone discovery modifiers (no location, no property noun required)
        # e.g. "cheaper?", "affordable?", "lower budget?", "something lower?"
        r'(?:^|\s)cheaper\s*\?|(?:^|\s)affordable\s*\?|'
        r'lower\s+(?:budget|price|cost)\s*\??|'
        r'something\s+(?:lower|less\s+expensive|more\s+affordable)\s*\??|'
        r'any\s+(?:cheaper|affordable|budget)\s+(?:option|property|place|area)\s*\??|'
        r'(?:^|\s)better\s+(?:option|options|property|properties|deal)\s*\??|'
        r'(?:^|\s)other\s+(?:option|options|choice|choices|property|properties)\s*\??'
        r')\b',
        re.IGNORECASE,
    )
    # Only classify as city-wide discovery if the CURRENT user utterance has no
    # explicit location. Using params.get("location") was wrong because it includes
    # locations extracted from OLD turns (up to 8 turns back). A user saying "cheaper
    # options?" (current turn, city-wide intent) would have had their discovery intent
    # suppressed by "T Nagar" found in turn 6.
    # [Fix-Discovery] Check current turn only for location suppression of discovery mode.
    _current_turn_text = (user_texts[-1] if user_texts else "").lower()
    _loc_re_cur = re.compile(r'\bin\s+((?:\w+\s*){1,3}?)(?:\s*[,.]|\s*$)', re.IGNORECASE)
    _current_turn_has_loc = False
    _cur_lm = _loc_re_cur.search(_current_turn_text)
    if _cur_lm:
        _cur_candidate = _cur_lm.group(1).strip()
        _cur_first_word = _cur_candidate.split()[0].lower() if _cur_candidate.split() else ""
        _cur_bad = any(w.lower() in _NOT_LOCATION_WORDS for w in _cur_candidate.split())
        if (
            not _cur_bad
            and _cur_first_word not in _NOT_LOCATION_WORDS
            and _cur_candidate.lower() not in _CITY_CANONICAL
            and len(_cur_candidate) > 2
        ):
            _current_turn_has_loc = True
    _has_explicit_loc_in_speech = _current_turn_has_loc
    logger.debug(
        f"[Fix-Discovery] current_turn_has_loc={_current_turn_has_loc} "
        f"(extracted_loc={params.get('location')!r}, current_turn={_current_turn_text[:60]!r})"
    )
    _user_discovery_question = (
        bool(_DISCOVERY_QUESTION_RE.search(lower))
        and not _has_explicit_loc_in_speech
    )

    if _user_discovery_question:
        logger.info(
            f"[Extract] City-wide discovery question detected - "
            f"setting _citywide_search=True, _clear_location=True"
        )

    if _user_discovery_question:
        _same_scope_other_properties = bool(
            re.search(
                r'\b(other|more|next|another)\s+(property|properties|option|options|apartment|apartments|villa|villas|plot|plots)\b',
                lower,
                re.IGNORECASE,
            )
            and not re.search(
                r'\b(anywhere\s+in|in\s+chennai|across\s+chennai|other\s+area|another\s+area|different\s+area|any\s+other\s+area)\b',
                lower,
                re.IGNORECASE,
            )
        )
        if _same_scope_other_properties:
            _user_discovery_question = False
            logger.info("[Extract] Kept vague 'other properties' request in current search scope")

    _CHANGE_AREA_PHRASES = [
        "other area", "another area", "different area",
        "other locality", "another locality", "different locality",
        "other location", "another location", "different location",
        "any other area", "some other area",
    ]
    _user_wants_new_area = any(phrase in lower for phrase in _CHANGE_AREA_PHRASES)
    if _user_skipped_location or _user_wants_new_area or _user_discovery_question:
        params["_clear_location"] = True
    if _user_skipped_location or _user_discovery_question:
        params["_citywide_search"] = True

    # â”€â”€ Catalog lookups (all safe if catalog is None/empty) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    _cat        = catalog or {}
    _cat_cities = [c.lower() for c in (_cat.get("cities") or [])]
    city        = params.get("city")

    # City-specific catalog data (populated after city is known)
    _city_data  = {}
    _cat_types  = []
    _cat_min    = None
    _cat_max    = None
    if city:
        _city_data = (_cat.get("by_city") or {}).get(city) or {}
        _raw_types = _city_data.get("property_types") or (_cat.get("property_types") or [])
        _cat_types = [t.lower() for t in _raw_types]
        _cat_min   = _city_data.get("min_price")   # cheapest property in city
        _cat_max   = _city_data.get("max_price")   # most expensive in city

    # Helper: format price as Indian spoken form for messages
    def _fmt(n):
        if not n: return ""
        n = int(n)
        if n >= 10_000_000: return f"{n/10_000_000:.1f} Crore"
        if n >= 100_000:    return f"{n//100_000} Lakh"
        return f"â‚¹{n:,}"

    def _confirmation_prompt(field: str, original: str, candidate: str) -> str:
        field_label = "location" if field == "location" else "property type"
        if original and _canonical_match_key(original) != _canonical_match_key(candidate):
            return (
                f"It sounds like I may have misheard your {field_label}. "
                f"Did you mean {candidate}, or did you have a different {field_label} in mind?"
            )
        return (
            f"Just to confirm, should I search for {candidate} as the {field_label}, "
            f"or would you like a different {field_label}?"
        )

    missing: list[dict] = []

    # â”€â”€ Step 1: City - always Chennai (no validation needed) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    # City is hardcoded to Chennai; skip validation for Chennai-only deployment.

    # â”€â”€ Step 1: Property type â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    if not params.get("property_type") and not params.get("_generic_property_request"):
        missing.append({
            "name": "property_type",
            "instruction": (
                "Ask the user EXACTLY: 'What kind of property are you looking for?' "
                "Do not add examples. Do not paraphrase."
            ),
        })

    # â”€â”€ Step 1b: Validate property type against catalog â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    elif params.get("property_type") and _cat_types and params["property_type"].lower() not in _cat_types:
        _ptype     = params["property_type"]
        _type_candidates = _city_data.get("property_types") or _cat.get("property_types") or []
        _type_match = _best_catalog_candidate(_ptype, _type_candidates, cutoff=0.45)
        if _type_match:
            missing.append({
                "name": "property_type",
                "instruction": _confirmation_prompt("property_type", _ptype, _type_match),
                "confirmation_candidate": _type_match,
                "original_value": _ptype,
            })
        else:
            _avail_str = ", ".join(_type_candidates)
            missing.append({
                "name": "property_type",
                "instruction": (
                    f"The property type '{_ptype}' is not available in {city}. "
                    f"Tell the user: \"I'm sorry, {_ptype} aren't available in {city} through JLL. "
                    f"We do have {_avail_str}. Which would you prefer?\""
                ),
            })

    # â”€â”€ Step 2: Budget â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    elif _budget_needs_reconfirmation:
        missing.append({
            "name": "budget",
            "instruction": (
                "It sounds like I may have misheard your budget. "
                "Could you please tell me the amount once more?"
            ),
        })

    elif (
        not params.get("min_price")
        and not params.get("max_price")
        and not params.get("_budget_flexible")
        and not params.get("_total_inventory_count_request")
    ):
        missing.append({
            "name": "budget",
            "instruction": "Ask the user: 'What is your budget?'",
        })

    # â”€â”€ Step 2b: Validate budget against catalog price range â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    elif _cat_min and _cat_max:
        _user_budget = params.get("max_price") or params.get("min_price") or 0
        if _user_budget and int(_user_budget) < int(_cat_min):
            missing.append({
                "name": "budget",
                "instruction": (
                    f"User budget {_fmt(_user_budget)} is below JLL's minimum for {city} ({_fmt(_cat_min)}). "
                    f"Tell the user: \"I'm sorry, properties in {city} start from {_fmt(_cat_min)}. "
                    f"Your budget of {_fmt(_user_budget)} may be a bit low. "
                    f"Would you like to adjust your budget so I can find suitable options for you?\""
                ),
            })

    # â”€â”€ Step 3: Location (separate check - NOT elif) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    # IMPORTANT: This must be a standalone `if not missing` check, NOT an `elif`.
    # The preceding elif chain (Steps 1â€“2b) means that when Step 2b runs (catalog
    # has price data), an `elif` for Step 3 would be silently skipped, causing
    # location to NEVER be asked. By checking `if not missing` separately, location
    # is always asked once type + budget are confirmed, regardless of whether
    # the catalog-price validation branch ran.
    _catalog_locations = []
    if city:
        _catalog_locations = list(dict.fromkeys(
            (_city_data.get("locations") or []) + (_city_data.get("micro_markets") or [])
        ))

    if (
        not missing
        and params.get("location")
        and _catalog_locations
        and _canonical_match_key(params["location"]) not in {_canonical_match_key(x) for x in _catalog_locations}
    ):
        _loc_aliases = {
            alias: canonical
            for alias, canonical in _LOCATION_ALIASES.items()
            if _canonical_match_key(canonical) in {_canonical_match_key(x) for x in _catalog_locations}
        }
        _loc_confirm_aliases = {
            alias: canonical
            for alias, canonical in _LOCATION_CONFIRM_ONLY_ALIASES.items()
            if _canonical_match_key(canonical) in {_canonical_match_key(x) for x in _catalog_locations}
        }
        _confirm_alias_match = _loc_confirm_aliases.get(_normalize_location_key(params["location"]))
        if _confirm_alias_match:
            missing.append({
                "name": "location",
                "instruction": _confirmation_prompt("location", params["location"], _confirm_alias_match),
                "confirmation_candidate": _confirm_alias_match,
                "original_value": params["location"],
            })
            _loc_decision = None
        else:
            _loc_decision = _catalog_fuzzy_decision(
                params["location"],
                _catalog_locations,
                aliases=_loc_aliases,
                accept_threshold=0.9,
                confirm_threshold=0.58,
            )
        if _loc_decision and _loc_decision.action == "accept":
            logger.info(
                f"[LocationFuzzy] accepted raw={params['location']!r} canonical={_loc_decision.value!r} "
                f"score={_loc_decision.score:.2f} reason={_loc_decision.reason}"
            )
            params["location"] = _loc_decision.value
        elif _loc_decision and _loc_decision.action == "confirm":
            missing.append({
                "name": "location",
                "instruction": _confirmation_prompt("location", params["location"], _loc_decision.value),
                "confirmation_candidate": _loc_decision.value,
                "original_value": params["location"],
            })

    if not missing and not params.get("location") and not _user_skipped_location:
        missing.append({
            "name": "location",
            "instruction": (
                f"Ask the user EXACTLY: 'Which area in {city} are you looking at?' "
                "Do not suggest areas. Do not say for example. Do not paraphrase. "
                "If the user says 'anywhere' or 'any', accept it and search city-wide."
            ),
        })

    if not params.get("result_count"):
        params["result_count"] = str(PRESENTED_PROPERTY_LIMIT)

    return params, missing


def _validate_gathered_values(endpoint: dict, arguments: dict, context) -> list:
    """Check that each gather_before_call value actually came from the user's speech.

    The LLM sometimes satisfies required schema fields by hallucinating values rather
    than asking the user. This function verifies each gathered value by checking that
    at least one word from the provided value appears in the user's actual messages.

    Number words and digits are treated as equivalent: user saying "Three" correctly
    validates result_count="3" and vice-versa.

    Returns the list of gather_before_call items that appear to be hallucinated
    (i.e. their value has no word-level overlap with anything the user said).
    Returns [] if all values are verified or if there are no gather_before_call items.
    """
    gather_items = endpoint.get("gather_before_call", [])
    if not gather_items:
        return []

    # Build word set from everything the user actually said in this conversation,
    # then expand with number-word â†” digit equivalents
    raw_user_words: set = set()
    if hasattr(context, 'messages'):
        for m in context.messages:
            if m.get("role") == "user" and m.get("content"):
                raw_user_words.update(re.findall(r'\b\w+\b', m["content"].lower()))
    user_words = _expand_number_words(raw_user_words)

    unverified = []
    for item in gather_items:
        name = item["name"]
        value = str(arguments.get(name, "")).strip()

        if not value or _PLACEHOLDER_RE.match(value):
            # Empty or an obvious placeholder ("User's first name", "[Name]", etc.)
            unverified.append(item)
            continue

        # Tokenise the provided value, expand number equivalents, check for ANY overlap
        value_words = _expand_number_words(set(re.findall(r'\b\w+\b', value.lower())))
        if value_words and not value_words.intersection(user_words):
            unverified.append(item)

    return unverified


def _compress_system_prompt(prompt: str) -> str:
    """Reduce token count of a system prompt without losing behavioral instructions.

    Strips decorative formatting that wastes tokens without adding meaning:
    - Lines that are only separator characters (â”€, â•, -, =, #, *, ~, etc.)
    - Decorative markdown-style headers (## HEADING ##, === HEADING ===, etc.)
    - Runs of more than one blank line compressed to a single blank line
    - Trailing whitespace on each line
    - Leading/trailing whitespace on the entire prompt

    Does NOT remove any text that contains actual words/instructions.
    Returns the compressed prompt string.
    """
    lines = prompt.splitlines()
    out = []
    blank_run = 0

    for line in lines:
        stripped = line.strip()

        # Skip lines that are ONLY separator / decorative characters
        # e.g.  "â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€", "==========", "##########", "* * * * *"
        if stripped and re.fullmatch(r'[\-=â”€â•#*~_|â–ªâ–ºâ€¢Â·\s]+', stripped):
            continue

        # Collapse decorator-only headers like "--- SECTION ---" or "=== HEADING ==="
        # if the line contains no lowercase letters it's likely a pure formatting header
        # BUT keep ALL-CAPS instruction labels like "RESPONSE RULES:" (ends with colon)
        # IMPORTANT: Only apply this to lines that actually contain Latin alpha characters.
        # Non-Latin scripts (Tamil, Hindi, Arabic, etc.) have no upper/lower case - every
        # such line satisfies stripped == stripped.upper(), which would silently delete ALL
        # non-Latin instructions from the prompt. Guard against this by first checking that
        # the line contains meaningful Latin alpha content before applying the all-caps filter.
        if stripped and not stripped.endswith(':') and stripped == stripped.upper():
            # all-caps line with no colon - likely a section banner, not an instruction
            # keep it only if it contains meaningful words (length check: > 4 chars of alpha)
            alpha_chars = re.sub(r'[^A-Za-z]', '', stripped)
            if len(alpha_chars) > 0 and len(alpha_chars) <= 4:
                # e.g. "JLL", "OK", decoration - skip
                continue
            # If alpha_chars == 0 (pure non-Latin script like Tamil/Hindi), KEEP the line.
            # If alpha_chars > 4 (e.g. "TOOLS AVAILABLE"), KEEP the line.
            # only skip if 0 < alpha_chars <= 4 (short Latin acronyms/decorators)

        if stripped == '':
            blank_run += 1
            if blank_run <= 1:
                out.append('')
        else:
            blank_run = 0
            out.append(stripped)

    return '\n'.join(out).strip()


def _build_gather_phase_prompt(integrations: list) -> str:
    """Compact scripted prompt used ONLY during the gather phase (before first search).

    Uses exact scripted phrasing so gpt-4.1-nano asks confidently without
    improvising examples or paraphrasing. City is hardcoded to Chennai.
    Order: property type -> budget -> area. After the first successful
    search_properties call, the full prompt is swapped in automatically
    by IntegrationToolHandler.
    """
    if not integrations:
        return ""
    return (
        "\n\nGATHERING REQUIRED - you are Riya at JLL Homes. Collect these 3 details, "
        "in this exact order, before calling any search tool.\n"
        "\n"
        "CRITICAL FIRST CHECK - DO THIS BEFORE ANYTHING ELSE:\n"
        "Scan the user's MOST RECENT message. For each slot, mark it CAPTURED or MISSING:\n"
        "- Property type CAPTURED if user mentioned: apartment, flat, villa, independent house, plot, land, builder floor, penthouse, senior living, row house, villament, duplex apartment, or utsav plots.\n"
        "- Budget CAPTURED if user mentioned any rupee amount (e.g. '50 lakhs', '1 crore', '80L', 'under 60 lakhs').\n"
        "- Area CAPTURED if user mentioned any Chennai locality (e.g. T Nagar, OMR, ECR, Anna Nagar, Velachery, Adyar, Tambaram, Pammal, etc.).\n"
        "SKIP the slot question for every CAPTURED field. Only ask the FIRST missing slot.\n"
        "Example: user says 'I want apartments in Chennai' -> property type is CAPTURED (apartments). Skip Slot 1. Go directly to Slot 2 (budget).\n"
        "\n"
        "CRITICAL ANTI-IMPROVISATION RULES:\n"
        "- Say the scripted sentences WORD FOR WORD. Do not paraphrase.\n"
        "- NEVER add 'for example', 'such as', 'like', or any list of examples.\n"
        "- NEVER list area names, property types, or budget ranges as examples.\n"
        "- Ask the question and STOP. No helpful suggestions after the question.\n"
        "- The user knows what they want. Do not prompt them with options.\n"
        "\n"
        "RECOGNIZE ALREADY-MENTIONED DETAILS:\n"
        "- RECOGNIZE property type from user speech: apartment, flat, villa, independent house, plot, land, builder floor, penthouse, senior living, row house, villament, duplex apartment, or utsav plots - do NOT re-ask if already mentioned.\n"
        "- If user says independent house, treat it as villa. If user says land, treat it as plot. If user says only house or home, ask whether they mean apartment or villa.\n"
        "- RECOGNIZE budget from user speech: amounts like '50 lakhs', '1 crore', '80L', 'under 60 lakhs' - do NOT re-ask if already mentioned.\n"
        "- RECOGNIZE area from user speech: area names like 'T Nagar', 'OMR', 'Anna Nagar', 'Velachery', 'Adyar', etc. - do NOT re-ask if already mentioned.\n"
        "- If user says 'find apartments in Chennai', they already gave property type (apartments) and area (Chennai) - skip those questions.\n"
        "\n"
        "Slot 1 - PROPERTY TYPE. If missing, say EXACTLY this and nothing more:\n"
        "   What kind of property are you looking for?\n"
        "   If user says only house or home, ask: By house, do you mean an apartment or a villa?\n"
        "   If user genuinely unsure, say: Most buyers start with apartments, shall we look at those?\n"
        "\n"
        "Slot 2 - BUDGET. Once type is known, say EXACTLY this and nothing more:\n"
        "   And what is your budget range?\n"
        "   If user says any or not sure, say: Roughly, under 1 crore, 1 to 2 crore, or above 2 crore?\n"
        "\n"
        "Slot 3 - AREA. Once budget is known, say EXACTLY this and nothing more:\n"
        "   Which area in Chennai are you looking at?\n"
        "   If user says anywhere or any, search city-wide immediately without further questions.\n"
        "   Do NOT suggest areas. Do NOT say for example. Just ask and wait.\n"
        "\n"
        "RULES - non-negotiable:\n"
        "- Ask ONE question per turn. Never bundle two slots.\n"
        "- Speak confidently. Never say could you please specify or if you dont mind.\n"
        "- Keep every reply under 12 words.\n"
        "- Do NOT call any tool until all 3 are collected.\n"
        "- If user asks something else, answer in ONE sentence, then ask the next missing slot.\n"
        "- After all 3 captured, call search_properties immediately. No preamble - the search speaks for itself.\n"
        "\n"
        "SPEECH FORMAT: Short sentences. End every sentence with a period. "
        "No bullets, dashes, asterisks, numbered lists, or example lists."
    )


def _build_compact_gather_phase_prompt(integrations: list) -> str:
    """Smaller gather prompt optimized for lower TTFT and cache reuse."""
    if not integrations:
        return ""
    return (
        "\n\nGATHER MODE: Riya at JLL Homes in Chennai.\n"
        "Goal: capture property_type, budget, and location before search.\n"
        "Read only the latest user turn first. If a slot is already present, never ask for it again.\n"
        "Ask only the first missing slot.\n"
        "Map independent house to Villas. Map land to Plots. For only house or home, ask whether apartment or villa; if repeated after clarification, default to apartments.\n"
        "Exact prompts:\n"
        "property_type: What kind of property are you looking for?\n"
        "budget: And what is your budget range?\n"
        "location: Which area in Chennai are you looking at?\n"
        "Rules: one question only, no examples, no filler, no lists.\n"
        "If user is unsure about property_type, say: Most buyers start with apartments, shall we look at those?\n"
        "If user is unsure about budget, say: Roughly, under 1 crore, 1 to 2 crore, or above 2 crore?\n"
        "If user says any area or anywhere, search city-wide.\n"
        "After all three slots are confirmed, call search_properties immediately and say nothing before the tool call."
    )


