def _detect_llm_prompt_phase(messages: list[dict]) -> str:
    if not messages:
        return "gather"
    system_text = "\n".join(
        m.get("content", "")
        for m in messages
        if m.get("role") == "system" and isinstance(m.get("content"), str)
    )
    if "PROPERTY DETAILS" in system_text or "DETAIL VIEW:" in system_text:
        return "detail"
    if "CURRENT SEARCH RESULTS" in system_text or "RESULT HANDLING:" in system_text:
        return "property"
    return "gather"


def _supports_extended_prompt_cache(model_name: str) -> bool:
    model_name = (model_name or "").lower()
    return model_name.startswith("gpt-5") or model_name.startswith("gpt-4.1")


def _requires_max_completion_tokens(model_name: str) -> bool:
    model_name = (model_name or "").lower().strip()
    if not model_name:
        return False
    return (
        model_name.startswith("gpt-5")
        or model_name.startswith(("o1", "o3", "o4", "o5"))
        or any(
            marker in model_name
            for marker in (
                "-gpt-5",
                "_gpt-5",
                "/gpt-5",
                "-o1",
                "_o1",
                "/o1",
                "-o3",
                "_o3",
                "/o3",
                "-o4",
                "_o4",
                "/o4",
                "-o5",
                "_o5",
                "/o5",
            )
        )
    )


def _normalize_openai_token_limit_param(params: dict, *, force: bool = False) -> dict:
    model_name = str(params.get("model") or "")
    if (force or _requires_max_completion_tokens(model_name)) and "max_tokens" in params:
        params["max_completion_tokens"] = params.pop("max_tokens")
    return params


# â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
# LLM Factory
# â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

def create_llm_service(config: dict, assistant_id: str | None = None):
    """Create the appropriate LLM service based on assistant config."""
    provider = config.get("llmProvider", "groq")
    raw_model = config.get("llmModel", "llama-3.3-70b-versatile")
    logger.info(f"[LLM Config] From DB: llmProvider={provider}, llmModel={raw_model}")
    
    # Fix 1: Increase max_tokens for reasoning models
    is_reasoning_model = "gpt-oss" in raw_model or "deepseek" in raw_model
    default_tokens = 1200 if is_reasoning_model else 200
    max_tokens = int(config.get("maxTokens", default_tokens))
    
    # Fix 2: Override reasoning models for voice use (need fast responses)
    VOICE_INCOMPATIBLE_MODELS = ["gpt-oss-120b", "deepseek-r1"]
    model = raw_model
    if any(m in raw_model for m in VOICE_INCOMPATIBLE_MODELS):
        logger.warning(f"[LLM] Model {raw_model} is a reasoning model - switching to llama-3.1-8b-instant for voice")
        model = "llama-3.1-8b-instant"

    # Respect database llmProvider and llmModel settings - no auto-switching
    has_integrations = bool(config.get("integrations"))

    # Fix 4: GPT models with integrations need more tokens for structured tool responses.
    # Default 200 is too low - truncates responses and confuses the pipeline.
    if has_integrations and provider == "openai":
        max_tokens = max(max_tokens, 600)
        logger.info(f"[LLM] OpenAI + integrations â†’ max_tokens raised to {max_tokens}")

    temperature = config.get("temperature", 0.7)

    if provider == "openai" and os.getenv("OPENAI_API_KEY"):
        from pipecat.services.openai.llm import OpenAILLMService
        class SprioOpenAILLMService(OpenAILLMService):
            def __init__(self, *, gather_model=None, prompt_cache_namespace=None, prompt_cache_retention=None, requires_max_completion_tokens=False, **kwargs):
                self._sprio_default_model = kwargs.get("model")
                self._sprio_gather_model = gather_model or kwargs.get("model")
                self._sprio_prompt_cache_namespace = (prompt_cache_namespace or "sprio")[:48]
                self._sprio_prompt_cache_retention = prompt_cache_retention or "in_memory"
                self._sprio_requires_max_completion_tokens = requires_max_completion_tokens
                super().__init__(**kwargs)

            def build_chat_completion_params(self, params_from_context) -> dict:
                params = super().build_chat_completion_params(params_from_context)
                phase = _detect_llm_prompt_phase(params.get("messages") or [])
                params["model"] = self._sprio_gather_model if phase == "gather" else self._sprio_default_model
                _normalize_openai_token_limit_param(params, force=self._sprio_requires_max_completion_tokens)
                params["prompt_cache_key"] = f"{self._sprio_prompt_cache_namespace}:{phase}:{params['model']}"[:64]
                retention = self._sprio_prompt_cache_retention
                if retention == "24h" and not _supports_extended_prompt_cache(str(params["model"])):
                    retention = "in_memory"
                params["prompt_cache_retention"] = retention
                return params
        # Azure OpenAI South India - cuts Indiaâ†’US round-trip (~400ms) to ~30ms.
        # Set AZURE_OPENAI_ENDPOINT=https://<resource>.openai.azure.com and
        # AZURE_OPENAI_API_KEY in .env to activate.
        _azure_endpoint = os.getenv("AZURE_OPENAI_ENDPOINT", "").rstrip("/")
        _azure_key      = os.getenv("AZURE_OPENAI_API_KEY", "")
        _gather_model = config.get("gatherLlmModel") or os.getenv("OPENAI_GATHER_MODEL") or model
        _cache_ns = re.sub(r"[^a-zA-Z0-9:_-]", "-", f"sprio:{assistant_id or 'default'}")
        _cache_retention = os.getenv("OPENAI_PROMPT_CACHE_RETENTION", "in_memory").strip() or "in_memory"
        _requires_completion_tokens = (
            _requires_max_completion_tokens(model)
            or _requires_max_completion_tokens(_gather_model)
        )
        if _azure_endpoint and _azure_key:
            # Use pipecat's native AzureLLMService - handles Azure's URL shape,
            # api-version query param, and deployment routing correctly.
            from pipecat.services.azure.llm import AzureLLMService
            class SprioAzureLLMService(AzureLLMService):
                def __init__(self, *, gather_model=None, prompt_cache_namespace=None, prompt_cache_retention=None, requires_max_completion_tokens=False, **kwargs):
                    self._sprio_default_model = kwargs.get("model")
                    self._sprio_gather_model = gather_model or kwargs.get("model")
                    self._sprio_prompt_cache_namespace = (prompt_cache_namespace or "sprio")[:48]
                    self._sprio_prompt_cache_retention = prompt_cache_retention or "in_memory"
                    self._sprio_requires_max_completion_tokens = requires_max_completion_tokens
                    super().__init__(**kwargs)

                def build_chat_completion_params(self, params_from_context) -> dict:
                    params = super().build_chat_completion_params(params_from_context)
                    phase = _detect_llm_prompt_phase(params.get("messages") or [])
                    params["model"] = self._sprio_gather_model if phase == "gather" else self._sprio_default_model
                    _normalize_openai_token_limit_param(params, force=self._sprio_requires_max_completion_tokens)
                    params["prompt_cache_key"] = f"{self._sprio_prompt_cache_namespace}:{phase}:{params['model']}"[:64]
                    retention = self._sprio_prompt_cache_retention
                    if retention == "24h" and not _supports_extended_prompt_cache(str(params["model"])):
                        retention = "in_memory"
                    params["prompt_cache_retention"] = retention
                    return params
            _azure_deployment = os.getenv("AZURE_OPENAI_DEPLOYMENT", model)
            _azure_api_version = os.getenv("AZURE_OPENAI_API_VERSION", "2024-10-21")
            _azure_requires_completion_tokens = (
                _requires_completion_tokens
                or _requires_max_completion_tokens(_azure_deployment)
            )
            logger.info(f"   LLM  â†’ Azure OpenAI (deployment={_azure_deployment}, api-version={_azure_api_version}) @ {_azure_endpoint} [South India low-latency]")
            return SprioAzureLLMService(
                api_key=_azure_key,
                endpoint=_azure_endpoint,
                model=_azure_deployment,
                gather_model=_gather_model,
                prompt_cache_namespace=_cache_ns,
                prompt_cache_retention=_cache_retention,
                requires_max_completion_tokens=_azure_requires_completion_tokens,
                api_version=_azure_api_version,
                params=AzureLLMService.InputParams(
                    temperature=temperature,
                    max_tokens=max_tokens,
                ),
            )
        logger.info(f"   LLM  â†’ OpenAI ({model}), max_tokens={max_tokens}")
        return SprioOpenAILLMService(
            api_key=os.getenv("OPENAI_API_KEY"),
            model=model,
            gather_model=_gather_model,
            prompt_cache_namespace=_cache_ns,
            prompt_cache_retention=_cache_retention,
            requires_max_completion_tokens=_requires_completion_tokens,
            params=OpenAILLMService.InputParams(
                temperature=temperature,
                max_tokens=max_tokens,
            ),
        )
    else:
        from pipecat.services.groq.llm import GroqLLMService
        logger.info(f"   LLM  â†’ Groq ({model})")
        try:
            return GroqLLMService(
                api_key=os.getenv("GROQ_API_KEY"),
                model=model,
                params=GroqLLMService.InputParams(
                    temperature=temperature,   # from DB config
                    max_tokens=max_tokens,    # from dashboard config
                ),
            )
        except Exception:
            return GroqLLMService(
                api_key=os.getenv("GROQ_API_KEY"),
                model=model,
            )


# â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
# Concurrent call tracking (per-process, event-loop-safe)
# â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
_MAX_CONCURRENT_CALLS = int(os.getenv("MAX_CONCURRENT_CALLS", "100"))
_active_calls: list[int] = [0]       # mutable so closures can write
_call_semaphore: list = [None]        # asyncio.Semaphore created lazily (needs running loop)

# â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
# Bot Entry Point
# â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•

async def bot(runner_args: RunnerArguments):

    # â”€â”€ Concurrency gate â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    if _call_semaphore[0] is None:
        _call_semaphore[0] = asyncio.Semaphore(_MAX_CONCURRENT_CALLS)
    async with _call_semaphore[0]:
        _active_calls[0] += 1
        logger.info(f"[Bot] Call started - active={_active_calls[0]}/{_MAX_CONCURRENT_CALLS}")
        try:
            await _bot_inner(runner_args)
        except Exception as exc:
            logger.error(
                f"[Bot] Pipeline crashed - call isolated: {type(exc).__name__}: {exc}",
                exc_info=True,
            )
        finally:
            _active_calls[0] -= 1
            logger.info(f"[Bot] Call ended - active={_active_calls[0]}/{_MAX_CONCURRENT_CALLS}")


async def _bot_inner(runner_args: RunnerArguments):

    # â”€â”€ Resolve assistant_id from the per-request closure body â”€â”€â”€â”€
    # The /api/offer handler captures assistant_id in its local scope and
    # passes it via runner_args.body - no shared global dict needed, so
    # concurrent offers never overwrite each other.
    _body = getattr(runner_args, 'body', None) or {}
    if isinstance(_body, str):
        try:
            _body = json.loads(_body)
        except Exception:
            _body = {}
    assistant_id = (_body.get("assistant_id") if isinstance(_body, dict) else None) or ASSISTANT_ID

    if assistant_id:
        logger.info(f"ðŸ“‹ Using assistant_id from offer: {assistant_id}")

    if assistant_id:
        logger.info(f"ðŸ“‹ Loading config for assistant: {assistant_id}")
    else:
        logger.info("ðŸ“‹ No assistant_id - using defaults")

    config = fetch_assistant_config(assistant_id) or {}

    cfg_first = config.get("firstMessage")
    if assistant_id and isinstance(cfg_first, str) and cfg_first.strip():
        greeting = re.sub(r"\s+", " ", cfg_first).strip()
        logger.info(f"   Greeting: using firstMessage from assistant config â†’ {greeting!r}")
    else:
        greeting = DEFAULT_GREETING
        if assistant_id:
            logger.info("   Greeting: assistant has no firstMessage, using default")
        else:
            logger.info("   Greeting: no assistant_id, using default")

    if isinstance(config.get("systemPrompt"), str) and config.get("systemPrompt").strip():
        raw_base_prompt = config.get("systemPrompt").strip()
        logger.info("   System prompt: loaded from assistant config")
    else:
        raw_base_prompt = DEFAULT_SYSTEM_PROMPT
        logger.info("   System prompt: using DEFAULT_SYSTEM_PROMPT")

    # Compress the user-written base prompt to strip decorative formatting and collapse
    # blank lines - reduces token count by ~30-50% on verbose prompts without removing
    # any behavioral instructions. Applied before appending runtime-injected sections.
    base_prompt = _compress_system_prompt(raw_base_prompt)
    orig_len = len(raw_base_prompt.split())
    comp_len = len(base_prompt.split())
    logger.info(f"   System prompt compressed: {orig_len} â†’ {comp_len} words ({orig_len - comp_len} saved)")

    system_prompt = base_prompt + "\nRESPONSE LENGTH: Keep replies 1-2 short sentences. 3rd sentence only when necessary."

    kb = config.get("knowledgeBase", [])
    if kb:
        kb_text = "\n\n".join([
            f"--- {item.get('filename', 'File')} ---\n{item.get('textPreview', '')}"
            for item in kb if item.get('textPreview')
        ])
        if kb_text:
            system_prompt = system_prompt + f"\n\n--- Knowledge Base ---\n{kb_text}"
            logger.info(f"   Knowledge Base: {len(kb)} file(s) injected into system prompt")

    voice_id = config.get("ttsVoiceId") or DEFAULT_VOICE_ID
    stt_language = config.get("sttLanguage") or DEFAULT_STT_LANGUAGE
    stt_model = (
        config.get("sttModel")
        or config.get("stt_model")
        or ("nova-3" if (config.get("sttProvider") or "deepgram") == "deepgram" else "")
    )
    # Provider selection must come from assistant config stored by the dashboard.
    # Env-level fixed providers caused runtime drift from DB/admin settings.
    stt_provider = config.get("sttProvider") or "deepgram"
    if os.getenv("STT_PROVIDER_OVERRIDE") or os.getenv("STT_PROVIDER"):
        logger.info(
            "[STT Config] Ignoring fixed STT provider env override in favor of assistant config"
        )
    assistant_name = config.get("name") or "Priya (Default)"

    logger.info(f"ðŸŽ™ï¸  Sprio Voice - Pipecat Agent")
    logger.info(f"   Assistant: {assistant_name}")

    voice_speed = float(config.get("voiceSpeed", 0.7))
    logger.info(f"   Voice Speed: {voice_speed}")

    silence_timeout = int(config.get("silenceTimeout", 30))
    end_call_phrases = config.get("endCallPhrases", ["goodbye", "bye"])
    end_call_phrases = list(dict.fromkeys([
        *(end_call_phrases or []),
        "have a great day",
        "thank you for calling jll homes",
    ]))

    # â”€â”€ Transfer call function â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    _functions = config.get("functions") or []
    _transfer_fn = next((f for f in _functions if f.get("name") == "transfer_call" and f.get("enabled")), None)
    _transfer_number = _transfer_fn["config"].get("transfer_number", "").strip() if _transfer_fn else ""
    _transfer_message = _transfer_fn["config"].get("transfer_message", "") if _transfer_fn else ""
    if _transfer_number:
        system_prompt += build_transfer_system_prompt(_transfer_number, _transfer_message)
        logger.info(f"   Transfer  â†’ enabled, number={_transfer_number}")
    else:
        logger.info("   Transfer  â†’ not configured")

    # â”€â”€ Integration tools (external API endpoints) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
    # context_ref is declared here (before _tool_handler) so the handler gets a
    # mutable reference to the LLMContext. It will be populated later when
    # context_ref.append(context) runs. The RAGContextInjector also uses this ref.
    context_ref: list = []
    _latency_trace_ref: list = [{}]
    _call_closing_ref = [False]
    _integrations = config.get("integrations") or []
    _call_context = {
        "senderMobile": "",
        "senderName": "",
        "callId": "",
        "assistantId": assistant_id or "",
        "assistant_name": assistant_name,
    }
    _tool_handler = IntegrationToolHandler(
        _integrations,
        _call_context,
        context_ref=context_ref,
        latency_trace_ref=_latency_trace_ref,
        call_closing_ref=_call_closing_ref,
    ) if _integrations else None
    _tool_schemas = _tool_handler.build_tool_schemas() if _tool_handler else NOT_GIVEN
    if _tool_handler and _integrations:
        tool_names = [ep["id"] for intg in _integrations for ep in intg.get("endpoints", [])]
        logger.info(f"   Integrations â†’ {len(tool_names)} tool(s) registered: {tool_names}")
        # Start with compact gather prompt (~150 tokens) - saves ~1s TTFT per gather turn.
        # Full prompt is injected after first successful search_properties call.
        _full_intg_prompt = _build_integration_system_prompt(_integrations)
        _tool_handler._full_integration_prompt = _full_intg_prompt
        # Store FULL system prompt for clean phase upgrade (replace, not append).
        # Must include all injected sections (persona, knowledge base, transfer prompt)
        # to avoid losing context when swapping gatherâ†’property phase.
        _tool_handler._base_system_prompt = system_prompt
        system_prompt += _build_compact_gather_phase_prompt(_integrations)
        logger.info(
            f"   Integrations â†’ gather phase prompt active "
            f"(full prompt={len(_full_intg_prompt)} chars, stored for phase upgrade)"
        )
    else:
        logger.info("   Integrations â†’ none configured")

    # Mutable ref so TranscriptionLogger can reset the stage when user speaks.
    _idle_stage_ref = [0]

    async def on_user_idle_callback(processor, timeout):
        if _ob_transcription_logger_ref[0] and _ob_transcription_logger_ref[0].soft_hold_is_active():
            logger.info("[SoftHold] suppressed inbound idle prompt")
            return
        # Skip while tool call / LLM / TTS is active - agent is still working.
        if _tool_handler and _tool_handler.filler_active:
            logger.info("â³ Idle timeout skipped - tool call in flight")
            return
        if _should_block_idle_followup():
            logger.info("Idle timeout skipped - interruption/session follow-up still active")
            return
        # Only fire when truly waiting for user speech (not while agent is thinking/speaking).
        if global_state_manager.state in (AgentState.THINKING, AgentState.SPEAKING):
            logger.info(f"â³ Idle timeout skipped - agent state={global_state_manager.state.value}")
            return
        if _idle_stage_ref[0] == 0:
            _idle_stage_ref[0] = 1
            logger.info("â³ User idle stage 1 - are you there")
            logger.info("[IdleGuard] emitted_are_you_there source=inbound_idle stage=1")
            await _queue_synthetic_assistant_text(task, "I'm here, can we continue?")
        elif _idle_stage_ref[0] == 1:
            _idle_stage_ref[0] = 2
            logger.info("â³ User idle stage 2 - still on the line")
            await _queue_synthetic_assistant_text(task, "Just checking if you're still on the line.")
        elif _idle_stage_ref[0] == 2:
            _idle_stage_ref[0] = 3
            logger.info("â³ User idle stage 3 - disconnecting")
            await _queue_synthetic_assistant_text(task, "I'm unable to hear you. I'll disconnect now. Please call back when convenient.")
            await asyncio.sleep(4.0)
            await task.queue_frame(EndFrame())
        else:
            logger.info("â³ User idle - force ending")
            await task.queue_frame(EndFrame())

    # Use assistant-configured silence timeout for inbound idle prompts.
    user_idle = UserIdleProcessor(timeout=silence_timeout, callback=on_user_idle_callback)
    _inbound_idle_stop = asyncio.Event()
    _inbound_idle_task_ref = []

    async def _handle_inbound_idle_stage():
        if _ob_transcription_logger_ref[0] and _ob_transcription_logger_ref[0].soft_hold_is_active():
            logger.info("[SoftHold] suppressed inbound idle stage")
            return
        if _tool_handler and _tool_handler.filler_active:
            logger.info("[Inbound Idle] skipped - tool call in flight")
            return
        if _should_block_idle_followup():
            logger.info("[Inbound Idle] skipped - interruption/session follow-up still active")
            return
        if (
            _tool_handler
            and getattr(_tool_handler, "_selection_pending", False)
            and getattr(_tool_handler, "_last_presented_properties", None)
        ):
            logger.info("[Inbound Idle] skipped - awaiting property selection")
            return
        if global_state_manager.state != AgentState.IDLE:
            logger.info(f"[Inbound Idle] skipped - agent state={global_state_manager.state.value}")
            return
        if _idle_stage_ref[0] == 0:
            _idle_stage_ref[0] = 1
            logger.info("[Inbound Idle] stage 1 - are you there")
            logger.info("[IdleGuard] emitted_are_you_there source=inbound_idle_monitor stage=1")
            await _queue_synthetic_assistant_text(task, "I'm here, can we continue?")
        elif _idle_stage_ref[0] == 1:
            _idle_stage_ref[0] = 2
            logger.info("[Inbound Idle] stage 2 - still on the line")
            await _queue_synthetic_assistant_text(task, "Just checking if you're still on the line.")
        elif _idle_stage_ref[0] == 2:
            _idle_stage_ref[0] = 3
            logger.info("[Inbound Idle] stage 3 - disconnecting")
            await _queue_synthetic_assistant_text(task, "I'm unable to hear you. I'll disconnect now. Please call back when convenient.")
            await asyncio.sleep(4.0)
            await task.queue_frame(EndFrame())
        else:
            logger.info("[Inbound Idle] force ending")
            await task.queue_frame(EndFrame())

    async def _monitor_inbound_idle():
        idle_started_at = None
        try:
            while not _inbound_idle_stop.is_set():
                await asyncio.sleep(0.5)
                if _tool_handler and _tool_handler.filler_active:
                    idle_started_at = None
                    continue
                if global_state_manager.state == AgentState.IDLE:
                    if idle_started_at is None:
                        idle_started_at = time.time()
                        logger.info(f"[Inbound Idle] timer armed (timeout={silence_timeout}s stage={_idle_stage_ref[0]})")
                        continue
                    if (time.time() - idle_started_at) >= silence_timeout:
                        idle_started_at = None
                        await _handle_inbound_idle_stage()
                else:
                    idle_started_at = None
        except asyncio.CancelledError:
            logger.info("[Inbound Idle] monitor cancelled")

    max_duration = int(config.get("maxCallDuration", 600))
    from pipecat.audio.filters.rnnoise_filter import RNNoiseFilter
    audio_filter = RNNoiseFilter()
    transport = SmallWebRTCTransport(
        params=TransportParams(
            audio_out_enabled=True,
            audio_out_sample_rate=24000,
            audio_in_enabled=True,
            audio_in_sample_rate=16000,
            audio_in_filter=audio_filter,
            vad_enabled=True,
            vad_analyzer=SileroVADAnalyzer(
                params=VADParams(
                    confidence=0.72,
                    start_secs=0.14,
                    stop_secs=0.6,
                    min_volume=0.70,
                )
            ),
        ),
        webrtc_connection=runner_args.webrtc_connection,
    )

    # Wire transport to tool handler for filler audio playback
    if _tool_handler:
        _tool_handler._transport = transport

    _stt_observability = {
        "sttProvider": stt_provider,
        "sttLanguageSource": stt_language,
    }
    _stt_provider_profile = {
        "sttProvider": stt_provider,
        "supports_interim_semantics": stt_provider != "sarvam",
        "supports_native_vad_signals": False,
        "native_turn_events_are_destructive": stt_provider == "sarvam",
    }

    if stt_provider == "azure" and AZURE_AVAILABLE and os.getenv("AZURE_SPEECH_KEY"):
        _azure_profile = build_azure_stt_profile(config, stt_language, 16000)
        _azure_phrase_bias_phrases = _AZURE_PHRASE_BIAS_PHRASES if _azure_profile["phrase_bias_enabled"] else []
        _azure_stt_kwargs = dict(
            api_key=os.getenv("AZURE_SPEECH_KEY"),
            region=os.getenv("AZURE_SPEECH_REGION", "centralindia"),
            language=_azure_profile["locale"] if _azure_profile["language_strategy"] == "explicit" else _azure_profile["auto_detect_candidates"][0],
            sample_rate=16000,
            endpoint_id=_azure_profile["endpoint_id"] or None,
        )
        if SprioAzureSTTService:
            _azure_stt_kwargs.update({
                "auto_detect_languages": _azure_profile["auto_detect_candidates"],
                "phrase_bias_phrases": _azure_phrase_bias_phrases,
                "segmentation_silence_ms": _azure_profile["segmentation_silence_ms"],
                "initial_silence_ms": _azure_profile["initial_silence_ms"],
                "profanity_option": _azure_profile["profanity_option"],
            })
        stt = (SprioAzureSTTService or AzureSTTService)(**_azure_stt_kwargs)
        _stt_observability.update({
            "sttModel": _azure_profile["model"],
            "sttLocale": _azure_profile["locale"],
            "sttAutoDetectEnabled": _azure_profile["language_strategy"] == "auto",
            "sttAutoDetectCandidates": _azure_profile["auto_detect_candidates"],
            "sttPhraseBiasEnabled": _azure_profile["phrase_bias_enabled"],
            "sttEndpointIdPresent": bool(_azure_profile["endpoint_id"]),
            "sttLanguageStrategy": _azure_profile["language_strategy"],
            "azureProviderProfileEnabled": _azure_profile["provider_profile_enabled"],
            "azureSegmentationSilenceMs": _azure_profile["segmentation_silence_ms"],
            "azureInitialSilenceMs": _azure_profile["initial_silence_ms"],
            "azurePhraseBiasPhraseCount": len(_azure_phrase_bias_phrases),
            "azureRuntimeMode": "provider-profile" if _azure_profile["provider_profile_enabled"] else "legacy",
        })
        _stt_provider_profile = dict(_azure_profile)
        logger.info(
            f"   STT  â†’ Azure Speech inbound "
            f"(strategy={_azure_profile['language_strategy']}, "
            f"locale={_azure_profile['locale']}, "
            f"auto={','.join(_azure_profile['auto_detect_candidates']) if _azure_profile['auto_detect_candidates'] else 'off'}, "
            f"phrase_bias={'on' if _azure_profile['phrase_bias_enabled'] else 'off'}, "
            f"segmentation_silence_ms={_azure_profile['segmentation_silence_ms']})"
        )
    elif stt_provider == "sarvam" and SARVAM_AVAILABLE and os.getenv("SARVAM_API_KEY"):
        _sarvam_profile = build_sarvam_stt_profile(config, stt_language, 16000)
        _sarvam_language_enum = _map_sarvam_pipecat_language(stt_language)
        _sarvam_params_kwargs = {
            "language": _sarvam_language_enum,
            "mode": _sarvam_profile["mode"] if _sarvam_profile["model"] == "saaras:v3" else None,
            "vad_signals": True if _sarvam_profile["native_vad_shadow_enabled"] else False,
            "high_vad_sensitivity": _sarvam_profile["high_vad_sensitivity"],
        }
        stt = SprioSarvamSTTService(
            api_key=os.getenv("SARVAM_API_KEY"),
            model=_sarvam_profile["model"],
            sample_rate=16000,
            input_audio_codec=_sarvam_profile["input_audio_codec"],
            params=SarvamSTTService.InputParams(
                **_sarvam_params_kwargs,
            ),
            native_vad_shadow_enabled=_sarvam_profile["native_vad_shadow_enabled"],
            shadow_vad_sink=global_state_manager.record_shadow_turn_taking_event,
        )
        _stt_observability.update({
            "sttModel": _sarvam_profile["model"],
            "sttMode": _sarvam_profile["mode"],
            "sttInputCodec": _sarvam_profile["input_audio_codec"],
            "sttLanguageStrategy": _sarvam_profile["language_strategy"],
            "sarvamCodecCompatFallback": _sarvam_profile["codec_compat_fallback"],
            "sarvamNativeVadShadowEnabled": _sarvam_profile["native_vad_shadow_enabled"],
            "sarvamHighVadSensitivity": _sarvam_profile["high_vad_sensitivity"],
            "sarvamProviderProfileEnabled": _sarvam_profile["provider_profile_enabled"],
            "sarvamRuntimeMode": "provider-profile" if _sarvam_profile["provider_profile_enabled"] else "legacy",
        })
        _stt_provider_profile = dict(_sarvam_profile)
        logger.info(
            f"   STT  â†’ Sarvam {_sarvam_profile['model']} "
            f"(mode={_sarvam_profile['mode']}, language={_sarvam_profile['language_code']}, "
            f"codec={_sarvam_profile['input_audio_codec']}, shadow_vad={_sarvam_profile['native_vad_shadow_enabled']})"
        )
    elif stt_provider == "soniox" and SONIOX_AVAILABLE and os.getenv("SONIOX_API_KEY"):
        stt = SonioxSTTService(
            api_key=os.getenv("SONIOX_API_KEY"),
            params=SonioxInputParams(language_hints=["en-IN"]),
            context=SonioxContextObject(
                terms=["T Nagar", "Anna Nagar", "Adyar", "OMR", "ECR", "Velachery",
                       "Tambaram", "Porur", "Sholinganallur", "Chromepet", "Mogappair",
                       "Medavakkam", "Perungudi", "Thoraipakkam", "Guduvanchery",
                       "Adambakkam", "Alandur", "Ambattur", "Besant Nagar",
                       "Whitefield", "Sarjapur", "Koramangala", "HSR Layout",
                       "lakhs", "lakh", "crore", "crores", "BHK"]
            ),
        )
        logger.info(f"   STT  â†’ Soniox v4 (language_hints=EN+HI+TA)")
    else:
        _deepgram_lang = DEEPGRAM_LANG_MAP.get(stt_language, "en")
        _deepgram_model = str(stt_model or "nova-3").strip()
        _deepgram_options = dict(
            model=_deepgram_model,
            language=_deepgram_lang,
            encoding="linear16",
            sample_rate=16000,
            channels=1,
            interim_results=True,
            endpointing=300,
            punctuate=True,
            smart_format=True,
            profanity_filter=False,
        )
        if _deepgram_keywords_supported(_deepgram_model):
            _deepgram_options["keywords"] = _DEEPGRAM_CHENNAI_KEYWORDS
        stt = DeepgramSTTService(
            api_key=os.getenv("DEEPGRAM_API_KEY"),
            live_options=LiveOptions(**_deepgram_options),
        )
        logger.info(
            f"   STT  â†’ Deepgram {_deepgram_model} "
            f"(language={_deepgram_lang}, source={stt_language}, "
            f"keywords={'on' if 'keywords' in _deepgram_options else 'off'})"
        )
        _stt_observability.update({
            "sttModel": _deepgram_model,
            "sttLanguageStrategy": "explicit" if stt_language != "multi" else "auto",
        })

    global_state_manager.set_stt_observability(_stt_observability)

    llm = create_llm_service(config, assistant_id=assistant_id)

    LANG_MAP = {
        "en": Language.EN, "multi": Language.EN,
        "en-IN": Language.EN,
        "en-US": Language.EN,
        "en-GB": Language.EN,
        "hi": Language.HI,
        "ta": Language.TA,
        "es": Language.ES,
        "fr": Language.FR,
        "de": Language.DE,
        "it": Language.IT,
        "pt": Language.PT,
        "ja": Language.JA,
        "ko": Language.KO,
        "zh": Language.ZH,
    }
    if stt_language not in LANG_MAP:
        logger.warning(f"   âš ï¸  sttLanguage '{stt_language}' not in LANG_MAP - falling back to English TTS. Add it to LANG_MAP if needed.")
    tts_language = LANG_MAP.get(stt_language, Language.EN)

    tts_provider = config.get("ttsProvider", "cartesia").lower()
    if tts_provider == "elevenlabs":
        tts = ElevenLabsTTSService(
            api_key=os.getenv("ELEVENLABS_API_KEY"),
            voice_id=voice_id,
            model=os.getenv("ELEVENLABS_MODEL", "eleven_turbo_v2_5"),
            params=ElevenLabsTTSService.InputParams(
                language=tts_language,
                speed=voice_speed,
                stability=float(os.getenv("ELEVENLABS_STABILITY", "0.5")),
                similarity_boost=float(os.getenv("ELEVENLABS_SIMILARITY", "0.75")),
            ),
        )
        logger.info(f"   TTS  â†’ ElevenLabs (voice={voice_id[:12]}..., lang={stt_language}, speed={voice_speed})")
    elif tts_provider == "sarvam":
        _sarvam_ok = False
        try:
            from pipecat.services.sarvam.tts import SarvamTTSService
            _sarvam_ok = True
        except ImportError:
            logger.warning("[TTS] SarvamTTSService not available (run uv sync to install sarvam extra) - falling back to Cartesia")
        if _sarvam_ok:
            # voice_id formats:
            #   "sarvam:bulbul:v3:ritu" â†’ model=bulbul:v3, speaker=ritu
            #   "sarvam:anushka"        â†’ model=bulbul:v2, speaker=anushka (legacy)
            _raw = voice_id[len("sarvam:"):] if voice_id.startswith("sarvam:") else voice_id
            _parts = _raw.split(":")
            if len(_parts) >= 3:
                _sarvam_model = f"{_parts[0]}:{_parts[1]}"
                _speaker = _parts[2]
            else:
                _sarvam_model = "bulbul:v2"
                _speaker = _parts[-1] if _parts else "anushka"
            _sarvam_lang = {
                "ta": "ta-IN", "hi": "hi-IN", "te": "te-IN",
                "kn": "kn-IN", "ml": "ml-IN", "en-IN": "en-IN",
            }.get(stt_language, "en-IN")
            _sarvam_svc = SarvamTTSService(
                api_key=os.getenv("SARVAM_API_KEY", ""),
                voice_id=_speaker,
                model=_sarvam_model,
                language=_sarvam_lang,
                params=SarvamTTSService.InputParams(
                    pace=voice_speed,
                    sample_rate=24000,
                ),
            )
            tts = SarvamTTSWrapper(_sarvam_svc)
            logger.info(f"   TTS  â†’ Sarvam {_sarvam_model} (speaker={_speaker}, lang={_sarvam_lang})")
        else:
            tts = SprioTTSService(
                api_key=os.getenv("CARTESIA_API_KEY"),
                voice_id=voice_id,
                model="sonic-3",
                text_aggregation_mode=TextAggregationMode.SENTENCE,  # Sentence-level streaming
                params=CartesiaTTSService.InputParams(
                    language=tts_language,
                    generation_config=build_cartesia_generation_config(voice_speed),
                ),
            )
            logger.info(f"   TTS  â†’ Cartesia Sonic 3 (fallback, voice={voice_id[:12]}..., speed={voice_speed}, mode=sentence)")
            logger.info("   TTS  â†’ Sentence streaming ENABLED - audio starts per sentence")
    else:
        tts = SprioTTSService(
            api_key=os.getenv("CARTESIA_API_KEY"),
            voice_id=voice_id,
            model="sonic-3",
            text_aggregation_mode=TextAggregationMode.SENTENCE,  # Sentence-level streaming
            params=CartesiaTTSService.InputParams(
                language=tts_language,
                generation_config=build_cartesia_generation_config(voice_speed),
            ),
        )
        logger.info(f"   TTS  â†’ Cartesia Sonic 3 (voice={voice_id[:12]}..., lang={stt_language}, speed={voice_speed}, mode=sentence)")
        logger.info("   TTS  â†’ Sentence streaming ENABLED - audio starts per sentence")

    # Shared flag reserved for direct TTS interruption handling.
    _filler_playing_ref: list = [False]

    if _tool_handler:
        _tool_handler._filler_playing_ref = _filler_playing_ref

    # Shared [turn_start_ts, stt_text] - stamped by TranscriptionLogger on FINAL,
    # read by TTSActivityLogger to compute LLM TTFT and TTS TTFA per turn.
    _turn_ts_ref: list = [None, ""]
    _assistant_audio_active_ref: list = [False]
    _speaker_signal_ref: list = [{}]
    _transcript_ledger_ref: list = [[]]
    _shadow_turn_adapter = DeepgramFluxShadowAdapter(global_state_manager.record_shadow_turn_taking_event)
    # Shared list to aggregate turn latencies for end-of-call summary
    # Each entry: {"llm_ms": int, "tts_ms": int, "e2e_ms": int}
    _call_latency_ref: list = []
    transcription_logger = TranscriptionLogger(tts_service=tts, tool_handler=_tool_handler, idle_stage_ref=_idle_stage_ref, stt_language=stt_language, context_ref=context_ref, turn_ts_ref=_turn_ts_ref, latency_trace_ref=_latency_trace_ref, assistant_audio_active_ref=_assistant_audio_active_ref, speaker_signal_ref=_speaker_signal_ref, shadow_turn_adapter=_shadow_turn_adapter, stt_provider_profile=_stt_provider_profile, call_closing_ref=_call_closing_ref, transcript_ledger_ref=_transcript_ledger_ref)
    _speaker_candidate_gate = None
    _speaker_playback_gate = None
    if SPEAKER_SEPARATION_V1_ENABLED:
        try:
            _barge_detector = BargeInDetector(
                sample_rate=16000,
                playback_idle_timeout_ms=900,
                playback_warmup_ms=NO_BARGE_IN_MS,
                signal_ref=_speaker_signal_ref,
            )
            _speaker_candidate_gate = MicVADFilter(_barge_detector, signal_ref=_speaker_signal_ref)
            _speaker_playback_gate = PlaybackTracker(_barge_detector, signal_ref=_speaker_signal_ref)
            logger.info("[Speaker Separation] inbound gate enabled")
        except Exception as _speaker_err:
            logger.warning(f"[Speaker Separation] inbound gate disabled: {_speaker_err}")
            _speaker_candidate_gate = None
            _speaker_playback_gate = None


    # Add RAG context injector only when rag_enabled is true for this assistant
    # (context_ref was already declared above near _tool_handler)
    rag_injector = None
    rag_enabled = bool(config.get("ragEnabled", False))
    if assistant_id and rag_enabled:
        rag_injector = RAGContextInjector(
            assistant_id=assistant_id,
            backend_url=BACKEND_URL,
            context_ref=context_ref
        )
        logger.info("   RAG  â†’ Context injector enabled (rag_enabled=true)")
    elif assistant_id:
        logger.info("   RAG  â†’ Disabled (rag_enabled=false)")

    farewell_text = build_farewell_message(system_prompt, assistant_name)

    user_farewell_detector = UserFarewellDetector(farewell_text, call_closing_ref=_call_closing_ref)
    _task_ref = []
    _call_end_event = asyncio.Event()
    _call_end_event_ref = [_call_end_event]
    _call_id_ref: list = []  # populated in on_client_connected
    _usage_metrics_ref = [build_empty_usage_metrics()]
    _call_recorder = CallAudioRecorder() if CALL_RECORDING_ENABLED else None
    end_call_detector = EndCallOnGoodbye(
        call_end_event_ref=_call_end_event_ref,
        task_ref=_task_ref,
        phrases=end_call_phrases,
        call_closing_ref=_call_closing_ref,
    )

    # Transfer detector - only active when a transfer number is configured
    transfer_detector = None
    if _transfer_number:
        transfer_detector = TransferCallDetector(
            call_id="",  # placeholder; updated via _call_id_ref in on_client_connected
            transfer_number=_transfer_number,
            backend_url=BACKEND_URL,
            call_end_event_ref=_call_end_event_ref,
            task_ref=_task_ref,
        )

    messages = [
        {"role": "system", "content": system_prompt},
    ]
    context = LLMContext(messages, tools=_tool_schemas)
    context_ref.append(context)

    # Register integration tool handlers with the LLM service
    if _tool_handler:
        _tool_handler.register_handlers(llm)

    user_params = LLMUserAggregatorParams(
        vad_analyzer=None,
        user_turn_stop_timeout=0.3,
    )
    context_aggregator = LLMContextAggregatorPair(context, user_params=user_params)

    pipeline_steps = [
        transport.input(),
        UserAudioRecordingTap(_call_recorder),
        STTAudioUsageTracker(
            _usage_metrics_ref,
            stt_provider=stt_provider,
            stt_region=os.getenv("AZURE_SPEECH_REGION", "centralindia"),
            stt_model=stt_model or "",
        ),
    ]
    if _speaker_candidate_gate:
        pipeline_steps.append(_speaker_candidate_gate)
    pipeline_steps.extend([
        stt,
        transcription_logger,
    ])
    if rag_injector:
        pipeline_steps.append(rag_injector)
    # ToolAckFilter suppresses "okay"/"sure" utterances while filler TTS is playing
    if _tool_handler:
        pipeline_steps.append(ToolAckFilter(_tool_handler))
    pipeline_steps.extend([
        user_farewell_detector,
        context_aggregator.user(),
        llm,
    ])
    if transfer_detector:
        pipeline_steps.append(transfer_detector)
    # PropertyHallucinationGuard: blocks LLM attempts to describe property details without calling get_property_details
    if _tool_handler:
        pipeline_steps.append(PropertyHallucinationGuard(tool_handler=_tool_handler))
    # ToolPreambleFilter: drops "Allow me a moment" filler text before tool calls.
    # Must be BEFORE FunctionCallTextFilter so it sees raw <function= tokens.
    # FunctionCallTextFilter: strips <function=...> markup from the stream.
    pipeline_steps.extend([
        ToolPreambleFilter(),
        FunctionCallTextFilter(),
        SarvamTextSanitizer(),  # Filter standalone dots before TTS
        TTSActivityLogger(label="TTS-IN", mode="input", turn_ts_ref=_turn_ts_ref, call_latency_ref=_call_latency_ref, latency_trace_ref=_latency_trace_ref, tool_handler=_tool_handler, transcript_ledger_ref=_transcript_ledger_ref),
        SentenceStreamingTTS(tts, latency_trace_ref=_latency_trace_ref, context=context),  # Stream sentences to TTS for low-latency audio
        tts,                         # TTS service must be in pipeline so push_frame() reaches transport
        TTSActivityLogger(label="TTS-OUT", mode="output", turn_ts_ref=_turn_ts_ref, call_latency_ref=_call_latency_ref, latency_trace_ref=_latency_trace_ref, filler_playing_ref=_filler_playing_ref, transport=transport, assistant_audio_active_ref=_assistant_audio_active_ref, tool_handler=_tool_handler),
        AssistantAudioRecordingTap(_call_recorder),
        end_call_detector,
    ])
    if _speaker_playback_gate:
        pipeline_steps.append(_speaker_playback_gate)
    pipeline_steps.extend([
        transport.output(),
        UsageMetricsCollector(_usage_metrics_ref),
        AssistantContextGate(),
        context_aggregator.assistant(),
    ])
    pipeline = Pipeline(pipeline_steps)

    task = PipelineTask(
        pipeline,
        params=PipelineParams(
            allow_interruptions=True,
            enable_metrics=True,
            enable_usage_metrics=True,
        ),
        cancel_on_idle_timeout=False,
        idle_timeout_secs=None,
    )
    _task_ref.append(task)

    @task.event_handler("on_pipeline_error")
    async def on_pipeline_error(task, error_frame):
        # Deepgram WebSocket drops (code 1006 - TCP abnormal close) are transient.
        # Pipecat already reconnects in DeepgramSTTService._on_error; the call continues.
        # Log at WARNING so it doesn't look like a fatal pipeline failure.
        err_str = str(getattr(error_frame, "error", error_frame))
        if "ConnectionClosed" in err_str or "no close frame" in err_str:
            logger.warning(f"[STT] Deepgram WebSocket dropped (code 1006) - reconnecting, call unaffected")
        else:
            logger.error(f"âŒ [Pipeline] Non-STT error: {err_str}")

    call_start = [0.0]

    @transport.event_handler("on_client_connected")
    async def on_client_connected(transport, client):
        global_state_manager.reset_call_metrics()
        call_start[0] = time.time()
        logger.info("âœ… Client connected - speaking greeting via LLM frames")
        
        # Initiate call with new two-phase credit system
        try:
            call_id = await initiate_call(assistant_id, assistant_name)
            if call_id:
                _call_id_ref.append(call_id)  # per-call closure list - never shared between calls
                _call_context["callId"] = call_id  # propagate to integration proxy for audit logging
                active_calls.setdefault(call_id, {})
                active_calls[call_id]["usage_metrics"] = _usage_metrics_ref[0]
                logger.info(f"ðŸ“ž Call initiated with ID: {call_id}")
                # Give transfer detector the real call_id
                if transfer_detector:
                    transfer_detector._call_id = call_id
            else:
                logger.error("âŒ Failed to initiate call - no call_id returned")
        except Exception as e:
            logger.error(f"âŒ Error initiating call: {e}")
        
        await task.queue_frames(
            [
                LLMFullResponseStartFrame(),
                LLMTextFrame(greeting),
                LLMFullResponseEndFrame(),
            ]
        )
        _record_transcript_turn(_transcript_ledger_ref, "assistant", greeting, source="greeting")
        if not _inbound_idle_task_ref:
            _inbound_idle_task_ref.append(asyncio.create_task(_monitor_inbound_idle()))
        asyncio.create_task(enforce_max_duration(task, max_duration))

    @transport.event_handler("on_client_disconnected")
    async def on_client_disconnected(transport, client):
        duration = time.time() - call_start[0] if call_start[0] else 0
        logger.info(f"ðŸ‘‹ Client disconnected (duration={int(duration)}s)")
        _inbound_idle_stop.set()
        _call_end_event.set()
        if _inbound_idle_task_ref:
            _inbound_idle_task_ref[0].cancel()

        # Clean up shared HTTP client connection pool
        if _tool_handler and _tool_handler._http_client:
            try:
                await _tool_handler._http_client.aclose()
                logger.info("[HTTP] Connection pool closed")
            except Exception as e:
                logger.warning(f"[HTTP] Error closing connection pool: {e}")

        # Log call-level latency summary
        if _call_latency_ref:
            _turn_count = len(_call_latency_ref)
            _avg_llm = sum(t.get("llm_ms", 0) or 0 for t in _call_latency_ref) // _turn_count if _turn_count else 0
            _avg_tts = sum(t.get("tts_ms", 0) or 0 for t in _call_latency_ref) // _turn_count if _turn_count else 0
            _avg_e2e = sum(t.get("e2e_ms", 0) or 0 for t in _call_latency_ref) // _turn_count if _turn_count else 0
            _p95_e2e = sorted(t.get("e2e_ms", 0) or 0 for t in _call_latency_ref)[int(_turn_count * 0.95)] if _turn_count > 1 else (_call_latency_ref[0].get("e2e_ms") if _call_latency_ref else 0)
            logger.info(f"â± CALL LATENCY SUMMARY - {_turn_count} turns | avg LLM {_avg_llm}ms | avg TTS {_avg_tts}ms | avg E2E {_avg_e2e}ms | p95 E2E {_p95_e2e}ms")

        # Use new two-phase credit system
        call_id = _call_id_ref[0] if _call_id_ref else None  # per-call closure - safe for concurrency
        if call_id:
            try:
                # Attach persona + lead score from integration tool handler (if active)
                _call_extra_meta: dict = {}
                if _tool_handler:
                    _call_extra_meta["persona"]    = _tool_handler._persona
                    _call_extra_meta["lead_score"] = _tool_handler._lead_score
                    logger.info(
                        f"[Call] Closing metadata - "
                        f"persona={_tool_handler._persona}, "
                        f"lead_score={_tool_handler._lead_score}"
                    )
                _call_extra_meta["interruptionMetrics"] = global_state_manager.build_interrupt_metrics_payload()
                _call_extra_meta["latencyBreakdownV2"] = build_latency_breakdown_v2(_call_latency_ref)
                _call_extra_meta["shadowTurnTakingComparison"] = _call_extra_meta["interruptionMetrics"].get("shadowTurnTakingComparison", [])
                _call_extra_meta["speakerSeparationSignals"] = _call_extra_meta["interruptionMetrics"].get("speakerSeparationSignals", [])
                if _call_recorder:
                    try:
                        _recording_url = await upload_call_recording(call_id, _call_recorder.render_wav())
                        if _recording_url:
                            active_calls.setdefault(call_id, {})["recording_url"] = _recording_url
                            _call_extra_meta["recordingUrl"] = _recording_url
                    except Exception as _rec_err:
                        logger.warning(f"[CallRecording] finalize failed call_id={call_id}: {_rec_err}")

                # Complete the call with proper credit finalization
                success = await complete_call(
                    call_id,
                    duration,
                    _transcript_from_ledger_or_context(_transcript_ledger_ref, context.messages),
                    config,
                    extra_metadata=_call_extra_meta,
                )

                if not success:
                    logger.error(f"Failed to complete call credit finalization for call {call_id}")
                else:
                    logger.info(f"âœ… Call completed successfully - credits finalized")
            except Exception as e:
                logger.error(f"Error completing call: {e}")
        else:
            # Fallback to old system for backward compatibility
            await log_call_to_backend(
                assistant_id, assistant_name, duration,
                _transcript_from_ledger_or_context(_transcript_ledger_ref, context.messages),
            config,
            usage_metrics=_usage_metrics_ref[0],
        )

        await task.cancel()

    runner = PipelineRunner()
    logger.info("")
    logger.info("ðŸ’¡ Open http://localhost:7860/client to test")
    logger.info("   Set ASSISTANT_ID in .env to load config from dashboard")
    logger.info("")

    try:
        await runner.run(task)
    except Exception as exc:
        # Re-raise so the outer bot() wrapper can log + isolate the crash
        raise
    finally:
        try:
            await task.cancel()
        except Exception:
            pass


if __name__ == "__main__":
    import argparse
    import uuid
    import audioop
    import struct
    import uvicorn
    from contextlib import asynccontextmanager
    from fastapi import FastAPI, Request, BackgroundTasks, WebSocket, WebSocketDisconnect
    from fastapi.middleware.cors import CORSMiddleware
    from fastapi.responses import RedirectResponse
    from pipecat_ai_small_webrtc_prebuilt.frontend import SmallWebRTCPrebuiltUI
    from pipecat.transports.smallwebrtc.connection import SmallWebRTCConnection
    from pipecat.transports.smallwebrtc.request_handler import (
        SmallWebRTCRequestHandler,
        SmallWebRTCRequest,
        SmallWebRTCPatchRequest,
    )
    from pipecat.runner.types import SmallWebRTCRunnerArguments

    @asynccontextmanager
    async def lifespan(_app: FastAPI):
        """Startup/shutdown lifecycle for the voice agent server.

        On shutdown: closes all active SmallWebRTC connections so browser-test
        sessions are properly torn down (ICE candidates released, sockets closed).
        Without this, concurrent browser tests leave dangling WebRTC handles
        that consume memory and prevent clean server restarts.
        """
        yield  # server is running
        logger.info("[Server] Shutting down - closing SmallWebRTC handler")
        await small_webrtc_handler.close()

    app = FastAPI(lifespan=lifespan)
    app.add_middleware(
        CORSMiddleware,
        allow_origins=["*"],
        allow_credentials=True,
        allow_methods=["*"],
        allow_headers=["*"],
    )

    small_webrtc_handler = SmallWebRTCRequestHandler()

    @app.get("/client", include_in_schema=False)
    async def client_entry(request: Request):
        assistant_id = request.query_params.get("assistant_id", "") or ""
        resp = RedirectResponse(url="/client-ui/")
        if assistant_id:
            resp.set_cookie(
                key="sprio_assistant_id",
                value=assistant_id,
                path="/",
                samesite="lax",
            )
        return resp

    @app.get("/client/", include_in_schema=False)
    async def client_entry_slash(request: Request):
        return await client_entry(request)

    @app.post("/api/offer")
    async def offer(request: Request, background_tasks: BackgroundTasks):
        """Custom offer handler that extracts assistant_id from query params."""
        body = await request.json()

        assistant_id = request.query_params.get("assistant_id", "") or body.get("assistant_id", "") or ""
        request_data = body.get("request_data")
        if not assistant_id and isinstance(request_data, dict):
            assistant_id = request_data.get("assistant_id", "") or request_data.get("assistantId", "") or ""
        if not assistant_id and isinstance(request_data, str):
            try:
                parsed = json.loads(request_data)
                if isinstance(parsed, dict):
                    assistant_id = parsed.get("assistant_id", "") or parsed.get("assistantId", "") or ""
            except Exception:
                pass
        if not assistant_id:
            assistant_id = request.cookies.get("sprio_assistant_id", "") or ""

        if assistant_id:
            logger.info(f"ðŸ“‹ Received offer with assistant_id={assistant_id}")
        else:
            logger.warning("ðŸ“‹ Offer received without assistant_id - will use defaults")

        # Capture assistant_id in the local scope so each concurrent offer
        # has its own independent copy - no shared global dict, no race condition.
        _captured_assistant_id = assistant_id

        webrtc_request = SmallWebRTCRequest(
            sdp=body["sdp"],
            type=body["type"],
            pc_id=body.get("pc_id"),
            restart_pc=body.get("restart_pc"),
            request_data=body.get("request_data"),
        )

        async def webrtc_connection_callback(connection: SmallWebRTCConnection):
            runner_args = SmallWebRTCRunnerArguments(
                webrtc_connection=connection,
                body={"assistant_id": _captured_assistant_id},  # closure-captured, never shared
            )
            background_tasks.add_task(bot, runner_args)

        answer = await small_webrtc_handler.handle_web_request(
            request=webrtc_request,
            webrtc_connection_callback=webrtc_connection_callback,
        )
        return answer

    @app.patch("/api/offer")
    async def ice_candidate(request: SmallWebRTCPatchRequest):
        await small_webrtc_handler.handle_patch_request(request)
        return {"status": "success"}

    @app.get("/api/status")
    async def status():
        return {"ok": True, "active_calls": _active_calls[0], "max_calls": _MAX_CONCURRENT_CALLS}

    app.mount("/client-ui", SmallWebRTCPrebuiltUI)

    @app.get("/", include_in_schema=False)
    async def root_redirect():
        return RedirectResponse(url="/client")

    def resample_audio(pcm_bytes: bytes, from_rate: int, to_rate: int) -> bytes:
        """Resample raw 16-bit mono PCM from from_rate to to_rate using audioop."""
        if from_rate == to_rate:
            return pcm_bytes
        resampled, _ = audioop.ratecv(pcm_bytes, 2, 1, from_rate, to_rate, None)
        return resampled

    async def run_outbound_pipeline(
        websocket,
        call_id: str,
        assistant_config: dict,
        initial_messages: list | None = None,
        vodafone_call_id: str | None = None,
        vodafone_cli: str | None = None,
        call_direction: str = "outbound",
        phone_number: str | None = None,
        caller: str | None = None,
        prewarmed_opening_pcm: list[bytes] | None = None,
        opening_prewarm_task: asyncio.Task | None = None,
        opening_prestart_send_task: asyncio.Task | None = None,
        opening_already_sent: bool = False,
        opening_sent_at: float | None = None,
    ):
        """
        Real Pipecat voice pipeline for Vodafone outbound telephony calls.

        Audio format (Vodafone spec):
          - 16-bit Linear PCM, 8000 Hz, mono
          - Base64-encoded inside JSON: {"event":"media","media":{"payload":"<b64>"}}

        FIX APPLIED:
          - Cartesia TTS now outputs 8kHz directly (sample_rate=8000)
          - No resampling needed - eliminates burbling/garbling
          - Deepgram STT receives raw 8kHz linear16 from Vodafone (no decoding needed)
        """
        import asyncio
        import json
        import base64

        logger.info(f"[Outbound Pipeline] Starting real Pipecat pipeline for call {call_id}")

        cfg = assistant_config or {}

        logger.info(f"[Outbound Pipeline] â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•")
        logger.info(f"[Outbound Pipeline] call_id={call_id}")
        logger.info(f"[Outbound Pipeline] assistant_id={cfg.get('id') or cfg.get('assistant_id')}")
        logger.info(f"[Outbound Pipeline] assistant_name={cfg.get('name', 'DEFAULT')}")
        logger.info(f"[Outbound Pipeline] greeting={str(cfg.get('firstMessage', 'DEFAULT'))[:60]}")
        logger.info(f"[Outbound Pipeline] â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•")

        cfg_first = cfg.get("firstMessage")
        if isinstance(cfg_first, str) and cfg_first.strip():
            greeting = re.sub(r"\s+", " ", cfg_first).strip()
        else:
            greeting = DEFAULT_GREETING

        if isinstance(cfg.get("systemPrompt"), str) and cfg.get("systemPrompt").strip():
            raw_base_prompt = cfg.get("systemPrompt").strip()
        else:
            raw_base_prompt = DEFAULT_SYSTEM_PROMPT

        # Compress decorative formatting from the user-written prompt to save tokens
        base_prompt = _compress_system_prompt(raw_base_prompt)
        ob_orig_len = len(raw_base_prompt.split())
        ob_comp_len = len(base_prompt.split())
        logger.info(f"[Outbound Pipeline] System prompt compressed: {ob_orig_len} â†’ {ob_comp_len} words ({ob_orig_len - ob_comp_len} saved)")

        system_prompt = base_prompt + "\nRESPONSE LENGTH: Keep replies 1-2 short sentences. 3rd sentence only when necessary."

        kb = cfg.get("knowledgeBase", [])
        if kb:
            kb_text = "\n\n".join([
                f"--- {item.get('filename', 'File')} ---\n{item.get('textPreview', '')}"
                for item in kb if item.get('textPreview')
            ])
            if kb_text:
                system_prompt = system_prompt + f"\n\n--- Knowledge Base ---\n{kb_text}"
                logger.info(f"   [Outbound Pipeline] Knowledge Base: {len(kb)} file(s) injected into system prompt")

        voice_id = cfg.get("ttsVoiceId") or DEFAULT_VOICE_ID
        stt_language = cfg.get("sttLanguage") or DEFAULT_STT_LANGUAGE
        stt_provider = str(cfg.get("sttProvider") or "deepgram").strip().lower()
        stt_model = (
            cfg.get("sttModel")
            or cfg.get("stt_model")
            or ("nova-2-phonecall" if stt_provider == "deepgram" else "")
        )
        outbound_assistant_id = (
            cfg.get("id")
            or cfg.get("assistant_id")
            or cfg.get("assistantId")
            or ASSISTANT_ID
            or ""
        )
        assistant_name = cfg.get("name") or "Priya (Default)"

        logger.info(
            f"[Outbound Pipeline] Assistant: {assistant_name}, STT lang: {stt_language}, "
            f"STT provider: {stt_provider}, STT model: {stt_model or '-'}"
        )

        inbound_q: asyncio.Queue = asyncio.Queue()
        outbound_q: asyncio.Queue = asyncio.Queue()
        _vodafone_tts_conditioner = VodafoneTtsAudioConditioner()
        interrupt_event = asyncio.Event()
        stop_event = asyncio.Event()
        _call_end_event = asyncio.Event()  # set by EndCallOnGoodbye to kill ws_reader
        _invalidated_output_generations: set[int] = set()
        _interrupt_cutoff_metrics_ref = [{
            "interrupt_detected_at": None,
            "tts_cancel_sent_at": None,
            "vodafone_clear_sent_at": None,
            "local_queue_drained_chunks": 0,
            "stale_chunks_dropped": 0,
            "provider_clear_event_at": None,
            "provider_lead_ms_at_commit": 0,
        }]
        _provider_clear_pending_ref = [False]
        _provider_clear_generation_ref = [0]

        _greeting_injected_ref = [bool(opening_already_sent)]
        _greeting_done_ref = [False]
        _greeting_ensure_task_ref: list[asyncio.Task | None] = [None]
        _ob_transcript_ledger_ref: list = [[]]
        _idle_monitor_started_ref = [False]
        _media_frame_count_ref = [0]
        _inbound_audio_stats_ref = [{"frames": 0, "non_silent_frames": 0, "peak": 0}]
        _pipeline_ready_ref = [False]
        _ob_call_recorder = CallAudioRecorder() if CALL_RECORDING_ENABLED else None
        _ob_recording_upload_task_ref: list[asyncio.Task | None] = [None]
        _inbound_open_time = 0.0

        _current_room_id = None  # set on "start" event, used to filter stale "stop" events
        _current_room_started_at = 0.0
        _room_id_ref = []  # shared with EndCallOnGoodbye to trigger Vodafone stop
        _inbound_open_time = 0.0  # blocks inbound audio until opening finishes

        def _resolve_completed_prestart_chunks() -> int:
            if not opening_prestart_send_task or not opening_prestart_send_task.done():
                return 0
            try:
                return int(opening_prestart_send_task.result() or 0)
            except asyncio.CancelledError:
                logger.warning("[Outbound Pipeline] Prestart greeting task was cancelled before completion")
            except Exception as _prestart_err:
                logger.warning(f"[Outbound Pipeline] Prestart greeting task failed before pipeline boot: {_prestart_err}")
            return 0

        async def _finalize_outbound_recording_once() -> str | None:
            if not _ob_call_recorder:
                return None
            if _ob_recording_upload_task_ref[0]:
                return await _ob_recording_upload_task_ref[0]

            async def _render_and_upload() -> str | None:
                try:
                    _wav_bytes = _ob_call_recorder.render_wav()
                    _recording_url = await upload_call_recording(call_id, _wav_bytes)
                    if _recording_url:
                        if call_id in active_calls:
                            active_calls[call_id]["recording_url"] = _recording_url
                        return _recording_url
                except Exception as _rec_err:
                    logger.warning(f"[CallRecording] outbound finalize failed call_id={call_id}: {_rec_err}")
                return None

            _ob_recording_upload_task_ref[0] = asyncio.create_task(_render_and_upload())
            return await _ob_recording_upload_task_ref[0]

        def _start_idle_monitor_once() -> None:
            if _idle_monitor_started_ref[0]:
                return
            _idle_monitor_started_ref[0] = True
            asyncio.get_event_loop().create_task(_idle_monitor())

        def _schedule_greeting_done(delay_s: float, source: str) -> None:
            async def _mark_greeting_done():
                if delay_s > 0:
                    await asyncio.sleep(delay_s)
                if not _greeting_done_ref[0]:
                    _greeting_done_ref[0] = True
                    logger.info(
                        f"[Outbound Pipeline] Greeting playback done - accepting user audio "
                        f"(source={source})"
                    )
                _start_idle_monitor_once()

            asyncio.get_event_loop().create_task(_mark_greeting_done())

        def _mark_prestarted_greeting_as_active(source: str) -> bool:
            nonlocal _opening_played
            if _greeting_injected_ref[0] and _opening_played:
                return True
            _sent_chunks = _resolve_completed_prestart_chunks()
            if _sent_chunks <= 0 and opening_already_sent and _cached_opening_pcm:
                _sent_chunks = len(_cached_opening_pcm)
            if _sent_chunks <= 0:
                return False
            _greeting_injected_ref[0] = True
            _opening_played = True
            _record_transcript_turn(_ob_transcript_ledger_ref, "assistant", greeting, source=f"prestarted_greeting:{source}")
            _elapsed = max(0.0, time.time() - float(opening_sent_at or time.time()))
            _remaining = max(
                0.0,
                (_sent_chunks * (VODAFONE_OUTBOUND_CHUNK_MS / 1000.0)) - _elapsed,
            )
            logger.info(
                f"[Outbound Pipeline] Greeting already playing before pipeline boot/source={source}: "
                f"sent_chunks={_sent_chunks} elapsed_ms={int(_elapsed * 1000)} "
                f"remaining_ms={int(_remaining * 1000)}"
            )
            _schedule_greeting_done(_remaining, f"prestarted:{source}")
            return True

        async def _inject_cached_greeting(trigger: str) -> None:
            nonlocal _opening_played
            if _greeting_injected_ref[0]:
                return
            if not _cached_opening_pcm:
                logger.warning(f"[Outbound Pipeline] No cached greeting available at trigger={trigger}")
                _greeting_done_ref[0] = True
                _start_idle_monitor_once()
                return

            _greeting_injected_ref[0] = True
            _opening_played = True
            _record_transcript_turn(_ob_transcript_ledger_ref, "assistant", greeting, source="cached_greeting")
            if hasattr(websocket, "_keepalive_stop"):
                websocket._keepalive_stop.set()
                logger.info(f"[Outbound Pipeline] Stopped keepalive before greeting trigger={trigger}")

            logger.info(
                f"[Outbound Pipeline] Queueing cached greeting trigger={trigger}: "
                f"{len(_cached_opening_pcm)} chunks"
            )
            if _ob_call_recorder:
                try:
                    for _pcm_chunk in _cached_opening_pcm:
                        _ob_call_recorder.add_pcm(_pcm_chunk, "assistant", sample_rate=8000, channels=1)
                except Exception as _rec_err:
                    logger.debug(f"[CallRecording] cached greeting capture skipped: {_rec_err}")
            _send_started_at = time.time()
            _sent = 0
            for _pcm_chunk in _cached_opening_pcm:
                if stop_event.is_set() or interrupt_event.is_set():
                    break
                if not await _await_outbound_capacity("cached_greeting"):
                    break
                await outbound_q.put((0, _pcm_chunk, "cached_greeting"))
                _sent += 1
            _send_elapsed = time.time() - _send_started_at
            logger.info(
                f"[Outbound Pipeline] Cached greeting queued in {_sent} frames "
                f"enqueue_elapsed_ms={int(_send_elapsed * 1000)}"
            )

            # The websocket writer paces audio playout; queue backpressure keeps
            # this loop close to real time without bypassing the normal output path.
            _schedule_greeting_done(0.25, f"injected:{trigger}")

        async def _ensure_greeting_audio(trigger: str) -> None:
            if _greeting_injected_ref[0]:
                return
            _current_task = asyncio.current_task()
            _existing_task = _greeting_ensure_task_ref[0]
            if (
                _existing_task
                and _existing_task is not _current_task
                and not _existing_task.done()
            ):
                return
            _greeting_ensure_task_ref[0] = _current_task
            if _mark_prestarted_greeting_as_active(trigger):
                return
            if opening_prestart_send_task and not opening_prestart_send_task.done():
                try:
                    _sent_chunks = int(
                        await asyncio.wait_for(asyncio.shield(opening_prestart_send_task), timeout=0.75)
                        or 0
                    )
                    if _sent_chunks > 0:
                        _greeting_injected_ref[0] = True
                        _record_transcript_turn(
                            _ob_transcript_ledger_ref,
                            "assistant",
                            greeting,
                            source=f"prestarted_greeting:{trigger}",
                        )
                        logger.info(
                            f"[Outbound Pipeline] Prestart greeting completed before fallback "
                            f"trigger={trigger} sent_chunks={_sent_chunks}"
                        )
                        _schedule_greeting_done(
                            max(
                                0.0,
                                (_sent_chunks * (VODAFONE_OUTBOUND_CHUNK_MS / 1000.0))
                                - max(0.0, time.time() - float(opening_sent_at or time.time())),
                            ),
                            f"prestarted:{trigger}",
                        )
                        return
                    logger.warning(
                        f"[Outbound Pipeline] Prestart greeting returned zero chunks; "
                        f"falling back to pipeline greeting trigger={trigger}"
                    )
                except asyncio.TimeoutError:
                    logger.warning(
                        f"[Outbound Pipeline] Prestart greeting did not complete in time; "
                        f"falling back to pipeline greeting trigger={trigger}"
                    )
                except asyncio.CancelledError:
                    logger.warning(
                        f"[Outbound Pipeline] Prestart greeting cancelled before audible delivery; "
                        f"falling back trigger={trigger}"
                    )
                except Exception as _prestart_err:
                    logger.warning(
                        f"[Outbound Pipeline] Prestart greeting failed; "
                        f"falling back trigger={trigger} error={_prestart_err}"
                    )
            await _inject_cached_greeting(trigger)
            if _greeting_ensure_task_ref[0] is _current_task:
                _greeting_ensure_task_ref[0] = None

        def _should_ignore_stop_event(msg: dict) -> tuple[bool, str | None, str | None]:
            nonlocal _current_room_id, _current_room_started_at
            stop_room_id = msg.get("room_id") or msg.get("stop", {}).get("room_id")
            if _current_room_id and stop_room_id and stop_room_id != _current_room_id:
                return True, stop_room_id, f"stale_old_room current={_current_room_id}"

            if stop_room_id:
                return False, stop_room_id, None

            # Vodafone can emit a roomless stop during outbound bootstrap before
            # real media flows. Treating that as terminal drops answered calls.
            _elapsed = max(0.0, time.time() - float(_current_room_started_at or call_start))
            _bootstrap_active = (
                bool(_current_room_id)
                and _elapsed <= VODAFONE_OUTBOUND_STOP_GRACE_S
                and _media_frame_count_ref[0] == 0
                and not _greeting_done_ref[0]
            )
            if _bootstrap_active:
                return True, None, (
                    f"roomless_stop_during_bootstrap elapsed_ms={int(_elapsed * 1000)} "
                    f"greeting_injected={_greeting_injected_ref[0]} "
                    f"opening_played={_opening_played}"
                )

            return False, None, None

        async def _handle_ws_message(msg):
            nonlocal _current_room_id, _current_room_started_at
            event = msg.get("event", "")
            if event == "start":
                _ids = _extract_vodafone_root_identifiers(msg)
                _current_room_id = _ids.get("room_id")
                _current_room_started_at = time.time()
                logger.info(
                    f"[Outbound Pipeline] Call started, room_id={_current_room_id}, "
                    f"provider_call_id={_ids.get('provider_call_id')} session_id={_ids.get('session_id')}"
                )
                logger.info(f"[Outbound Pipeline] Full start payload: {json.dumps(msg)}")
                if _current_room_id and _room_id_ref is not None:
                    if _room_id_ref:
                        _room_id_ref[0] = _current_room_id
                    else:
                        _room_id_ref.append(_current_room_id)
                    logger.info(f"[Outbound Pipeline] room_id_ref updated: {_room_id_ref}")
                if call_id in active_calls:
                    active_calls[call_id]["room_id"] = _current_room_id
                    if vodafone_call_id:
                        active_calls[call_id]["vodafone_call_id"] = vodafone_call_id
                    if vodafone_cli:
                        active_calls[call_id]["vodafone_cli"] = vodafone_cli
                if not _greeting_ensure_task_ref[0] or _greeting_ensure_task_ref[0].done():
                    _greeting_ensure_task_ref[0] = asyncio.get_event_loop().create_task(
                        _ensure_greeting_audio("start")
                    )
                return None

            if event == "media":
                payload = msg.get("media", {}).get("payload", "")
                if payload:
                    pcm = base64.b64decode(payload)
                    _media_frame_count_ref[0] += 1
                    _peak = _pcm16_peak_abs(pcm)
                    _inbound_audio_stats_ref[0]["frames"] += 1
                    _inbound_audio_stats_ref[0]["peak"] = max(_inbound_audio_stats_ref[0]["peak"], _peak)
                    if _peak >= 500:
                        _inbound_audio_stats_ref[0]["non_silent_frames"] += 1
                    if _media_frame_count_ref[0] in (1, 10, 50) or _media_frame_count_ref[0] % 100 == 0:
                        logger.info(
                            f"[Outbound Pipeline] Inbound media stats frames={_media_frame_count_ref[0]} "
                            f"bytes={len(pcm)} peak={_peak} "
                            f"non_silent={_inbound_audio_stats_ref[0]['non_silent_frames']} "
                            f"max_peak={_inbound_audio_stats_ref[0]['peak']}"
                        )
                    if _greeting_done_ref[0] or not _greeting_injected_ref[0]:
                        await inbound_q.put(pcm)
                    if not _greeting_injected_ref[0] and _media_frame_count_ref[0] >= 1:
                        if not _greeting_ensure_task_ref[0] or _greeting_ensure_task_ref[0].done():
                            _greeting_ensure_task_ref[0] = asyncio.get_event_loop().create_task(
                                _ensure_greeting_audio("media")
                            )
                return None

            if event == "stop":
                _ignore_stop, stop_room_id, stop_reason = _should_ignore_stop_event(msg)
                if _ignore_stop:
                    logger.warning(
                        f"[Outbound Pipeline] Ignoring Vodafone stop event for room {stop_room_id}: "
                        f"{stop_reason}"
                    )
                    return None
                logger.info(f"[Outbound Pipeline] Vodafone sent stop event for room {stop_room_id}")
                return "stop"
            if event and "clear" in str(event).lower():
                _interrupt_cutoff_metrics_ref[0]["provider_clear_event_at"] = time.time()
                _provider_clear_pending_ref[0] = False
                logger.info(f"[Outbound Pipeline] Vodafone clear-related event observed: {event}")
                return None

        async def ws_reader():
            """Receive media frames from Vodafone and decode to raw PCM."""
            nonlocal _current_room_id, _current_room_started_at
            try:
                for initial_message in (initial_messages or []):
                    try:
                        await _handle_ws_message(initial_message)
                    except Exception as e:
                        logger.warning(f"[Outbound Pipeline] Initial frame parse error: {e}")

                while not stop_event.is_set():
                    try:
                        raw = await asyncio.wait_for(websocket.receive_text(), timeout=1.0)
                    except asyncio.TimeoutError:
                        if False:  # disabled - let _end_after_delay handle disconnect
                            logger.info("[Outbound Pipeline] WS reader: call ended - exiting")
                            break
                        continue
                    try:
                        msg = json.loads(raw)
                        event = msg.get("event", "")
                        if event and event != "media":
                            logger.info(f"[Outbound Pipeline] WS event received: {event}")
                        if event == "start":
                            # Record the room_id for this call so we can ignore stale stops
                            _ids = _extract_vodafone_root_identifiers(msg)
                            _current_room_id = _ids.get("room_id")
                            _current_room_started_at = time.time()
                            logger.info(
                                f"[Outbound Pipeline] Call started, room_id={_current_room_id}, "
                                f"provider_call_id={_ids.get('provider_call_id')} session_id={_ids.get('session_id')}"
                            )
                            logger.info(f"[Outbound Pipeline] Full start payload: {json.dumps(msg)}")
                            if _current_room_id and _room_id_ref is not None:
                                if _room_id_ref:
                                    _room_id_ref[0] = _current_room_id
                                else:
                                    _room_id_ref.append(_current_room_id)
                                logger.info(f"[Outbound Pipeline] room_id_ref updated: {_room_id_ref}")
                            if call_id in active_calls:
                                active_calls[call_id]["room_id"] = _current_room_id
                            if not _greeting_ensure_task_ref[0] or _greeting_ensure_task_ref[0].done():
                                _greeting_ensure_task_ref[0] = asyncio.get_event_loop().create_task(
                                    _ensure_greeting_audio("start")
                                )
                        elif event == "media":
                            payload = msg.get("media", {}).get("payload", "")
                            if payload:
                                # Vodafone sends 16-bit Linear PCM at 8kHz - use directly
                                pcm = base64.b64decode(payload)
                                _media_frame_count_ref[0] += 1
                                _peak = _pcm16_peak_abs(pcm)
                                _inbound_audio_stats_ref[0]["frames"] += 1
                                _inbound_audio_stats_ref[0]["peak"] = max(_inbound_audio_stats_ref[0]["peak"], _peak)
                                if _peak >= 500:
                                    _inbound_audio_stats_ref[0]["non_silent_frames"] += 1
                                if _media_frame_count_ref[0] in (1, 10, 50) or _media_frame_count_ref[0] % 100 == 0:
                                    logger.info(
                                        f"[Outbound Pipeline] Inbound media stats frames={_media_frame_count_ref[0]} "
                                        f"bytes={len(pcm)} peak={_peak} "
                                        f"non_silent={_inbound_audio_stats_ref[0]['non_silent_frames']} "
                                        f"max_peak={_inbound_audio_stats_ref[0]['peak']}"
                                    )
                                if _greeting_done_ref[0] or not _greeting_injected_ref[0]:
                                    await inbound_q.put(pcm)
                                if not _greeting_injected_ref[0] and _media_frame_count_ref[0] >= 1:
                                    if not _greeting_ensure_task_ref[0] or _greeting_ensure_task_ref[0].done():
                                        _greeting_ensure_task_ref[0] = asyncio.get_event_loop().create_task(
                                            _ensure_greeting_audio("media")
                                        )
                        elif event == "stop":
                            _ignore_stop, stop_room_id, stop_reason = _should_ignore_stop_event(msg)
                            if _ignore_stop:
                                logger.warning(
                                    f"[Outbound Pipeline] Ignoring Vodafone stop event for room {stop_room_id}: "
                                    f"{stop_reason}"
                                )
                            else:
                                logger.info(f"[Outbound Pipeline] Vodafone sent stop event for room {stop_room_id}")
                                break
                        elif event and "clear" in str(event).lower():
                            _interrupt_cutoff_metrics_ref[0]["provider_clear_event_at"] = time.time()
                            logger.info(f"[Outbound Pipeline] Vodafone clear-related event observed: {event}")
                    except Exception as e:
                        logger.warning(f"[Outbound Pipeline] Frame parse error: {e}")
            except Exception as e:
                logger.info(f"[Outbound Pipeline] WS reader ended: {e}")
            finally:
                stop_event.set()

                # â”€â”€ Queue EndFrame to unblock the Pipecat pipeline â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
                # Without this, runner.run(task) waits for frames indefinitely.
                try:
                    if _task_ref:
                        await _task_ref[0].queue_frame(EndFrame())
                        logger.info("[Outbound Pipeline] WS reader: EndFrame queued - pipeline will finalize")
                except Exception as _ef:
                    logger.warning(f"[Outbound Pipeline] WS reader: could not queue EndFrame: {_ef}")

                # â”€â”€ PRIMARY metrics trigger - fire immediately from ws_reader â”€â”€â”€
                # The run_outbound_pipeline finally block also calls complete_call,
                # but the Pipecat pipeline can stay stuck for minutes (EndFrame may
                # get blocked at LLM/TTS) before the idle-timeout cancels it.
                # When that CancelledError cascades through the TaskGroup, the
                # finally block's `await complete_call()` is itself cancelled, so
                # metrics are never saved.
                #
                # Firing it here - as a background task immune to TaskGroup
                # cancellation - captures the correct duration and whatever
                # transcript has been accumulated at the moment the call ends.
                # complete_call() is idempotent (checks active_calls), so if the
                # TaskGroup finally block also succeeds, the second call is a no-op.
                try:
                    _ob_duration = time.time() - call_start
                    _ob_transcript = _transcript_from_ledger_or_context(_ob_transcript_ledger_ref, context.messages)
                    logger.info(
                        f"[Outbound Pipeline] WS reader: scheduling complete_call "
                        f"(duration={int(_ob_duration)}s, turns={len(_ob_transcript)})"
                    )
                    _ob_extra_meta = {
                        "interruptionMetrics": global_state_manager.build_interrupt_metrics_payload(),
                        "latencyBreakdownV2": build_latency_breakdown_v2(_ob_call_latency_ref),
                    }
                    if _ob_tool_handler:
                        _ob_extra_meta["persona"] = _ob_tool_handler._persona
                        _ob_extra_meta["lead_score"] = _ob_tool_handler._lead_score
                    _ob_extra_meta["shadowTurnTakingComparison"] = _ob_extra_meta["interruptionMetrics"].get("shadowTurnTakingComparison", [])
                    _ob_extra_meta["speakerSeparationSignals"] = _ob_extra_meta["interruptionMetrics"].get("speakerSeparationSignals", [])
                    _recording_url = await _finalize_outbound_recording_once()
                    if _recording_url:
                        _ob_extra_meta["recordingUrl"] = _recording_url
                    asyncio.get_event_loop().create_task(
                        complete_call(call_id, _ob_duration, _ob_transcript, config=assistant_config, extra_metadata=_ob_extra_meta)
                    )
                except Exception as _ce:
                    logger.error(f"[Outbound Pipeline] WS reader: failed to schedule complete_call: {_ce}")

        _user_speaking = asyncio.Event()

        async def ws_writer():
            """Encode raw PCM chunks to Base64 and send to Vodafone."""
            _first_audio = True
            _greeting_chunks_sent = 0
            try:
                while not stop_event.is_set():
                    try:
                        queue_item = await asyncio.wait_for(outbound_q.get(), timeout=1.0)
                    except asyncio.TimeoutError:
                        continue
                    if isinstance(queue_item, tuple) and len(queue_item) == 3:
                        _queued_generation, pcm_chunk, _queued_source = queue_item
                    else:
                        _queued_generation, pcm_chunk, _queued_source = 0, queue_item, "legacy"
                    if _queued_generation in _invalidated_output_generations:
                        _interrupt_cutoff_metrics_ref[0]["stale_chunks_dropped"] += 1
                        logger.info(
                            f"[Outbound Pipeline] Dropped stale queued audio source={_queued_source} "
                            f"generation={_queued_generation}"
                        )
                        continue
                    if interrupt_event.is_set():
                        _interrupt_cutoff_metrics_ref[0]["stale_chunks_dropped"] += 1
                        logger.info(
                            f"[Outbound Pipeline] Dropped queued audio after interrupt source={_queued_source} "
                            f"generation={_queued_generation}"
                        )
                        continue
                    if (
                        _provider_clear_pending_ref[0]
                        and _queued_generation
                        and _queued_generation != _provider_clear_generation_ref[0]
                    ):
                        _provider_clear_pending_ref[0] = False
                        logger.info(
                            f"[Outbound Pipeline] Provider clear gate released by queued generation "
                            f"{_provider_clear_generation_ref[0]} -> {_queued_generation}"
                        )
                    if stop_event.is_set() or interrupt_event.is_set():
                        continue
                    if _first_audio:
                        if hasattr(websocket, '_keepalive_stop'):
                            websocket._keepalive_stop.set()
                        logger.info("[Outbound Pipeline] First audio chunk - stopping keepalive")
                        _first_audio = False
                    if False and _user_speaking.is_set():
                        _user_speaking.clear()
                        if _greeting_chunks_sent > 5:
                            count = 0
                            while not outbound_q.empty():
                                try:
                                    outbound_q.get_nowait()
                                    count += 1
                                except:
                                    break
                            try:
                                await task.queue_frame(InterruptionFrame())
                                # Also cancel TTS directly to stop Cartesia streaming
                                from pipecat.frames.frames import CancelFrame
                                await tts.cancel(CancelFrame())
                                # Tell Vodafone to clear its audio queue
                                import json as _json
                                await websocket.send_text(_json.dumps({
                                    "event": "clear",
                                    "room_id": _current_room_id
                                }))
                            except Exception as e:
                                logger.warning(f"[Outbound Pipeline] Interruption frame error: {e}")
                            logger.info(f"[Outbound Pipeline] Barge-in: flushed {count} chunks + TTS cancelled + Vodafone cleared")
                            continue
                        else:
                            logger.info(f"[Outbound Pipeline] Barge-in ignored - greeting not yet played ({_greeting_chunks_sent} chunks sent)")
                    try:
                        pcm_chunk = _condition_vodafone_tts_pcm(
                            pcm_chunk,
                            source=str(_queued_source or "tts_chunk"),
                            conditioner=_vodafone_tts_conditioner,
                        )
                        b64 = base64.b64encode(pcm_chunk).decode("utf-8")
                        frame = json.dumps(
                            _build_vodafone_media_frame(
                                b64,
                                _current_room_id,
                            )
                        )
                        await websocket.send_text(frame)
                        _chunk_secs = len(pcm_chunk) / float(TTS_RATE * CHANNELS * 2)
                        _now = time.time()
                        _playout_end_ref[0] = max(_playout_end_ref[0], _now) + _chunk_secs
                        _greeting_chunks_sent += 1
                        try:
                            await asyncio.wait_for(interrupt_event.wait(), timeout=_chunk_secs)
                        except asyncio.TimeoutError:
                            pass
                    except Exception as e:
                        logger.warning(f"[Outbound Pipeline] WS write error: {e}")
                        break
            except Exception as e:
                logger.info(f"[Outbound Pipeline] WS writer ended: {e}")

        try:
            from deepgram import LiveOptions as DgLiveOptions
        except ImportError:
            try:
                from deepgram.clients.listen.v1.websocket.options import LiveOptions as DgLiveOptions
            except ImportError:
                # Final fallback: create a simple LiveOptions class compatible with DeepgramSTTService
                class DgLiveOptions:
                    def __init__(self, **kwargs):
                        # Set default values for required attributes
                        self.callback = None
                        self.model = "nova-3"
                        self.language = "en"
                        self.encoding = "linear16"
                        self.sample_rate = 16000
                        self.channels = 1
                        self.interim_results = True
                        self.punctuate = True
                        self.smart_format = True
                        self.profanity_filter = False
                        # Override with provided kwargs
                        for k, v in kwargs.items():
                            setattr(self, k, v)
        from pipecat.services.deepgram.stt import DeepgramSTTService
        from pipecat.services.cartesia.tts import CartesiaTTSService, Language
        from pipecat.services.elevenlabs.tts import ElevenLabsTTSService
        from pipecat.audio.vad.silero import SileroVADAnalyzer
        from pipecat.audio.vad.vad_analyzer import VADParams
        from pipecat.frames.frames import (
            AudioRawFrame, TTSAudioRawFrame,
            LLMFullResponseStartFrame, LLMFullResponseEndFrame,
            LLMTextFrame, EndFrame, InterruptionFrame,
        )
        from pipecat.processors.frame_processor import FrameProcessor
        from pipecat.processors.aggregators.llm_context import LLMContext, NOT_GIVEN
        from pipecat.processors.aggregators.llm_response_universal import (
            LLMContextAggregatorPair, LLMUserAggregatorParams,
        )
        from pipecat.pipeline.pipeline import Pipeline
        from pipecat.pipeline.runner import PipelineRunner
        from pipecat.pipeline.task import PipelineParams, PipelineTask

        # â”€â”€ FIX: Use 8kHz throughout - matches Vodafone spec exactly â”€â”€
        INBOUND_RATE = 8000   # Vodafone sends 8kHz 16-bit Linear PCM
        TTS_RATE     = 8000   # FIX: Cartesia now outputs 8kHz directly (was 24000)
        CHANNELS     = 1
        CHUNK_MS     = VODAFONE_OUTBOUND_CHUNK_MS
        CHUNK_BYTES  = CHUNK_MS * INBOUND_RATE * 2 // 1000
        MAX_OUTBOUND_QUEUE_CHUNKS = VODAFONE_MAX_OUTBOUND_QUEUE_CHUNKS

        # â”€â”€ STT factory: Azure | Sarvam | Deepgram (8kHz native for Vodafone)
        _ob_stt_observability = {
            "sttProvider": stt_provider,
            "sttLanguageSource": stt_language,
        }
        _ob_stt_provider_profile = {
            "sttProvider": stt_provider,
            "supports_interim_semantics": stt_provider != "sarvam",
            "supports_native_vad_signals": False,
            "native_turn_events_are_destructive": stt_provider == "sarvam",
        }
        if stt_provider == "azure" and AZURE_AVAILABLE and os.getenv("AZURE_SPEECH_KEY"):
            _ob_azure_profile = build_azure_stt_profile(cfg, stt_language, 8000)
            _ob_azure_phrase_bias_phrases = _AZURE_PHRASE_BIAS_PHRASES if _ob_azure_profile["phrase_bias_enabled"] else []
            _ob_azure_stt_kwargs = dict(
                api_key=os.getenv("AZURE_SPEECH_KEY"),
                region=os.getenv("AZURE_SPEECH_REGION", "centralindia"),
                language=_ob_azure_profile["locale"] if _ob_azure_profile["language_strategy"] == "explicit" else _ob_azure_profile["auto_detect_candidates"][0],
                sample_rate=8000,
                endpoint_id=_ob_azure_profile["endpoint_id"] or None,
            )
            if SprioAzureSTTService:
                _ob_azure_stt_kwargs.update({
                    "auto_detect_languages": _ob_azure_profile["auto_detect_candidates"],
                    "phrase_bias_phrases": _ob_azure_phrase_bias_phrases,
                    "segmentation_silence_ms": _ob_azure_profile["segmentation_silence_ms"],
                    "initial_silence_ms": _ob_azure_profile["initial_silence_ms"],
                    "profanity_option": _ob_azure_profile["profanity_option"],
                })
            stt = (SprioAzureSTTService or AzureSTTService)(**_ob_azure_stt_kwargs)
            _ob_stt_observability.update({
                "sttModel": _ob_azure_profile["model"],
                "sttLocale": _ob_azure_profile["locale"],
                "sttAutoDetectEnabled": _ob_azure_profile["language_strategy"] == "auto",
                "sttAutoDetectCandidates": _ob_azure_profile["auto_detect_candidates"],
                "sttPhraseBiasEnabled": _ob_azure_profile["phrase_bias_enabled"],
                "sttEndpointIdPresent": bool(_ob_azure_profile["endpoint_id"]),
                "sttLanguageStrategy": _ob_azure_profile["language_strategy"],
                "azureProviderProfileEnabled": _ob_azure_profile["provider_profile_enabled"],
                "azureSegmentationSilenceMs": _ob_azure_profile["segmentation_silence_ms"],
                "azureInitialSilenceMs": _ob_azure_profile["initial_silence_ms"],
                "azurePhraseBiasPhraseCount": len(_ob_azure_phrase_bias_phrases),
                "azureRuntimeMode": "provider-profile" if _ob_azure_profile["provider_profile_enabled"] else "legacy",
            })
            _ob_stt_provider_profile = dict(_ob_azure_profile)
            logger.info(
                f"   STT  â†’ Azure Speech outbound "
                f"(strategy={_ob_azure_profile['language_strategy']}, "
                f"locale={_ob_azure_profile['locale']}, "
                f"auto={','.join(_ob_azure_profile['auto_detect_candidates']) if _ob_azure_profile['auto_detect_candidates'] else 'off'}, "
                f"sr=8000, phrase_bias={'on' if _ob_azure_profile['phrase_bias_enabled'] else 'off'}, "
                f"segmentation_silence_ms={_ob_azure_profile['segmentation_silence_ms']})"
            )
        elif stt_provider == "sarvam" and SARVAM_AVAILABLE and os.getenv("SARVAM_API_KEY"):
            _ob_sarvam_profile = build_sarvam_stt_profile(cfg, stt_language, 8000)
            _ob_sarvam_language_enum = _map_sarvam_pipecat_language(stt_language)
            _ob_sarvam_params_kwargs = {
                "language": _ob_sarvam_language_enum,
                "mode": _ob_sarvam_profile["mode"] if _ob_sarvam_profile["model"] == "saaras:v3" else None,
                "vad_signals": True if _ob_sarvam_profile["native_vad_shadow_enabled"] else False,
                "high_vad_sensitivity": _ob_sarvam_profile["high_vad_sensitivity"],
            }
            stt = SprioSarvamSTTService(
                api_key=os.getenv("SARVAM_API_KEY"),
                model=_ob_sarvam_profile["model"],
                sample_rate=8000,
                input_audio_codec=_ob_sarvam_profile["input_audio_codec"],
                params=SarvamSTTService.InputParams(**_ob_sarvam_params_kwargs),
                native_vad_shadow_enabled=_ob_sarvam_profile["native_vad_shadow_enabled"],
                shadow_vad_sink=global_state_manager.record_shadow_turn_taking_event,
            )
            _ob_stt_observability.update({
            "sttModel": _ob_sarvam_profile["model"],
            "sttMode": _ob_sarvam_profile["mode"],
            "sttInputCodec": _ob_sarvam_profile["input_audio_codec"],
            "sttLanguageStrategy": _ob_sarvam_profile["language_strategy"],
            "sarvamCodecCompatFallback": _ob_sarvam_profile["codec_compat_fallback"],
            "sarvamNativeVadShadowEnabled": _ob_sarvam_profile["native_vad_shadow_enabled"],
            "sarvamHighVadSensitivity": _ob_sarvam_profile["high_vad_sensitivity"],
            "sarvamProviderProfileEnabled": _ob_sarvam_profile["provider_profile_enabled"],
            "sarvamRuntimeMode": "provider-profile" if _ob_sarvam_profile["provider_profile_enabled"] else "legacy",
        })
            _ob_stt_provider_profile = dict(_ob_sarvam_profile)
            logger.info(
                f"   STT  â†’ Sarvam outbound {_ob_sarvam_profile['model']} "
                f"(mode={_ob_sarvam_profile['mode']}, language={_ob_sarvam_profile['language_code']}, "
                f"sr=8000, codec={_ob_sarvam_profile['input_audio_codec']}, "
                f"shadow_vad={_ob_sarvam_profile['native_vad_shadow_enabled']})"
            )
        else:
            # â”€â”€ STT: Deepgram receives raw 8kHz linear16 from Vodafone â”€â”€â”€â”€
            _deepgram_lang = DEEPGRAM_LANG_MAP.get(stt_language, "en")
            _deepgram_model = str(stt_model or "nova-2-phonecall").strip()
            _deepgram_options = dict(
                model=_deepgram_model,
                language=_deepgram_lang,
                encoding="linear16",   # Vodafone spec: 16-bit Linear PCM
                sample_rate=8000,      # Vodafone spec: 8kHz
                channels=CHANNELS,
                interim_results=True,
                endpointing=300,       # finalize transcript after 300ms silence
                punctuate=True,
                smart_format=True,
                profanity_filter=False,
            )
            if _deepgram_keywords_supported(_deepgram_model):
                _deepgram_options["keywords"] = _DEEPGRAM_CHENNAI_KEYWORDS
            stt = DeepgramSTTService(
                api_key=os.getenv("DEEPGRAM_API_KEY"),
                live_options=DgLiveOptions(**_deepgram_options),
            )
            logger.info(
                f"   STT  â†’ Deepgram outbound {_deepgram_model} "
                f"(language={_deepgram_lang}, source={stt_language}, sr=8000, "
                f"keywords={'on' if 'keywords' in _deepgram_options else 'off'})"
            )
            _ob_stt_observability.update({
                "sttModel": _deepgram_model,
                "sttLanguageStrategy": "explicit" if stt_language != "multi" else "auto",
            })

        global_state_manager.set_stt_observability(_ob_stt_observability)

        llm = create_llm_service(cfg, assistant_id=outbound_assistant_id)

        voice_speed = float(cfg.get("voiceSpeed", 0.7))
        silence_timeout = int(cfg.get("silenceTimeout", 30))
        max_duration = int(cfg.get("maxCallDuration", 600))
        end_call_phrases = cfg.get("endCallPhrases", ["goodbye", "bye"])
        end_call_phrases = list(dict.fromkeys([
            *(end_call_phrases or []),
            "have a great day",
            "thank you for calling jll homes",
        ]))

        # â”€â”€ Transfer call function â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        _ob_functions = cfg.get("functions") or []
        logger.info(f"[Outbound Pipeline] functions from config: {_ob_functions}")
        _ob_transfer_fn = next((f for f in _ob_functions if f.get("name") == "transfer_call" and f.get("enabled")), None)
        _ob_transfer_number = _ob_transfer_fn["config"].get("transfer_number", "").strip() if _ob_transfer_fn else ""
        _ob_transfer_message = _ob_transfer_fn["config"].get("transfer_message", "") if _ob_transfer_fn else ""
        if _ob_transfer_number:
            system_prompt += build_transfer_system_prompt(_ob_transfer_number, _ob_transfer_message)
            logger.info(f"[Outbound Pipeline] Transfer  â†’ enabled, number={_ob_transfer_number}")
        else:
            logger.info("[Outbound Pipeline] Transfer  â†’ not configured")

        # â”€â”€ Integration tools (external API endpoints) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
        _ob_integrations = cfg.get("integrations") or []
        _ob_call_context = {
            "senderMobile": vodafone_cli or "",
            "senderName": "",
            "assistant_name": assistant_name,
        }
        _ob_latency_trace_ref: list = [{}]
        _ob_tool_handler = IntegrationToolHandler(_ob_integrations, _ob_call_context, latency_trace_ref=_ob_latency_trace_ref) if _ob_integrations else None
        _ob_tool_schemas = _ob_tool_handler.build_tool_schemas() if _ob_tool_handler else NOT_GIVEN
        if _ob_tool_handler and _ob_integrations:
            ob_tool_names = [ep["id"] for intg in _ob_integrations for ep in intg.get("endpoints", [])]
            logger.info(f"[Outbound Pipeline] Integrations â†’ {len(ob_tool_names)} tool(s): {ob_tool_names}")
            _ob_full_intg_prompt = _build_integration_system_prompt(_ob_integrations)
            _ob_tool_handler._full_integration_prompt = _ob_full_intg_prompt
            # Store base persona prompt for clean phase upgrade (replace, not append)
            _ob_tool_handler._base_system_prompt = raw_base_prompt
            system_prompt += _build_compact_gather_phase_prompt(_ob_integrations)
        else:
            logger.info("[Outbound Pipeline] Integrations â†’ none configured")

        if str(stt_language or "").strip() not in TTS_LANG_MAP:
            logger.warning(f"[Outbound Pipeline] âš ï¸  sttLanguage '{stt_language}' not in TTS_LANG_MAP - falling back to English TTS. Add it to TTS_LANG_MAP if needed.")
        tts_lang = _resolve_tts_language(stt_language)

        # â”€â”€ TTS Provider Selection â”€â”€
        tts_provider = cfg.get("ttsProvider", "cartesia").lower()
        if tts_provider == "elevenlabs":
            tts = ElevenLabsTTSService(
                api_key=os.getenv("ELEVENLABS_API_KEY"),
                voice_id=voice_id,
                model=os.getenv("ELEVENLABS_MODEL", "eleven_turbo_v2_5"),
                sample_rate=8000,
                params=ElevenLabsTTSService.InputParams(
                    language=tts_lang,
                    speed=voice_speed,
                    stability=float(os.getenv("ELEVENLABS_STABILITY", "0.5")),
                    similarity_boost=float(os.getenv("ELEVENLABS_SIMILARITY", "0.75")),
                ),
            )
            logger.info(f"[Outbound Pipeline] TTS â†’ ElevenLabs at 8kHz (voice={voice_id[:12]}...)")
        elif tts_provider == "sarvam":
            _sarvam_ok = False
            try:
                from pipecat.services.sarvam.tts import SarvamTTSService
                _sarvam_ok = True
            except ImportError:
                logger.warning("[Outbound Pipeline] SarvamTTSService not available - falling back to Cartesia")
            if _sarvam_ok:
                _raw = voice_id[len("sarvam:"):] if voice_id.startswith("sarvam:") else voice_id
                _parts = _raw.split(":")
                if len(_parts) >= 3:
                    _sarvam_model = f"{_parts[0]}:{_parts[1]}"
                    _speaker = _parts[2]
                else:
                    _sarvam_model = "bulbul:v2"
                    _speaker = _parts[-1] if _parts else "anushka"
                _sarvam_lang = {
                    "ta": "ta-IN", "hi": "hi-IN", "te": "te-IN",
                    "kn": "kn-IN", "ml": "ml-IN", "en-IN": "en-IN",
                }.get(stt_language, "en-IN")
                _sarvam_svc = SarvamTTSService(
                    api_key=os.getenv("SARVAM_API_KEY", ""),
                    voice_id=_speaker,
                    model=_sarvam_model,
                    language=_sarvam_lang,
                    params=SarvamTTSService.InputParams(pace=voice_speed, sample_rate=8000),
                )
                tts = SarvamTTSWrapper(_sarvam_svc)
                logger.info(f"[Outbound Pipeline] TTS â†’ Sarvam {_sarvam_model} (speaker={_speaker}, lang={_sarvam_lang})")
            else:
                tts = SprioTTSService(
                    api_key=os.getenv("CARTESIA_API_KEY"),
                    voice_id=voice_id,
                    model="sonic-3",
                    text_aggregation_mode=TextAggregationMode.SENTENCE,  # Sentence-level streaming
                    params=CartesiaTTSService.InputParams(
                        language=tts_lang,
                        generation_config=build_cartesia_generation_config(voice_speed),
                    ),
                    sample_rate=8000,
                )
                logger.info(f"[Outbound Pipeline] TTS â†’ Cartesia Sonic 3 (fallback, 8kHz, speed={voice_speed}, mode=sentence)")
                logger.info("[Outbound Pipeline] TTS â†’ Sentence streaming ENABLED")
        else:
            tts = SprioTTSService(
                api_key=os.getenv("CARTESIA_API_KEY"),
                voice_id=voice_id,
                model="sonic-3",
                text_aggregation_mode=TextAggregationMode.SENTENCE,  # Sentence-level streaming
                params=CartesiaTTSService.InputParams(
                    language=tts_lang,
                    generation_config=build_cartesia_generation_config(voice_speed),
                ),
                sample_rate=8000,
            )
            logger.info(f"[Outbound Pipeline] TTS â†’ Cartesia Sonic 3 at 8kHz (speed={voice_speed}, mode=sentence)")
            logger.info("[Outbound Pipeline] TTS â†’ Sentence streaming ENABLED")

        _cached_opening_pcm = []
        _opening_played = False
        try:
            if prewarmed_opening_pcm:
                _cached_opening_pcm = list(prewarmed_opening_pcm)
                logger.info(
                    f"[Outbound Pipeline] Opening primed from outbound store: "
                    f"{len(_cached_opening_pcm)} chunks"
                )
            elif opening_prewarm_task:
                _prewarmed = await asyncio.shield(opening_prewarm_task)
                if _prewarmed:
                    _cached_opening_pcm = list(_prewarmed)
                    logger.info(
                        f"[Outbound Pipeline] Opening primed from prewarm task: "
                        f"{len(_cached_opening_pcm)} chunks"
                    )
            if not _cached_opening_pcm:
                _cached_opening_pcm = await _get_or_build_opening_audio_chunks(
                    voice_id,
                    greeting,
                    tts_lang,
                    voice_speed,
                )
                logger.info(f"[Outbound Pipeline] Opening cached: {len(_cached_opening_pcm)} chunks")
        except Exception as _e:
            logger.warning(f"[Outbound Pipeline] Opening cache error: {_e}")

        if opening_already_sent and _cached_opening_pcm:
            _mark_prestarted_greeting_as_active("boot")

        _outbound_idle_stage_ref = [0]
        _last_user_speech_ref = [time.time()]
        _agent_speaking_ref = [False]
        _agent_speaking_since_ref = [0]
        _playout_end_ref = [0.0]
        _call_ending_ref = [False]
        if _ob_tool_handler:
            _ob_tool_handler._call_closing_ref = _call_ending_ref
        _graceful_close_task_ref = [None]
        _PLAYOUT_SAFETY_SECS = 0.75
        _ob_transcription_logger_ref = [None]
        _ob_tts_out_logger_ref = [None]

        async def _await_outbound_capacity(source: str) -> bool:
            _wait_started = None
            while (
                not stop_event.is_set()
                and not interrupt_event.is_set()
                and outbound_q.qsize() >= MAX_OUTBOUND_QUEUE_CHUNKS
            ):
                if _wait_started is None:
                    _wait_started = time.monotonic()
                await asyncio.sleep(0.01)
            if _wait_started is not None:
                _wait_ms = int((time.monotonic() - _wait_started) * 1000)
                _log_msg = (
                    f"[Outbound Pipeline] Local queue backpressure released source={source} "
                    f"wait_ms={_wait_ms} local_qsize={outbound_q.qsize()} "
                    f"queued_ms~={outbound_q.qsize() * CHUNK_MS}"
                )
                if _wait_ms >= 1000:
                    logger.warning(_log_msg)
                else:
                    logger.debug(_log_msg)
            return not stop_event.is_set() and not interrupt_event.is_set()

        def _get_audible_output_state() -> dict:
            _now = time.time()
            _queue_chunks = outbound_q.qsize()
            _playout_end_in = max(0.0, (_playout_end_ref[0] + _PLAYOUT_SAFETY_SECS) - _now)
            _live = bool(_queue_chunks > 0 or _playout_end_in > 0.0 or _agent_speaking_ref[0])
            return {
                "live": _live,
                "queue_chunks": _queue_chunks,
                "queued_ms": _queue_chunks * CHUNK_MS,
                "playout_end_in_ms": int(_playout_end_in * 1000),
                "agent_speaking": bool(_agent_speaking_ref[0]),
            }

        def _mark_audible_output_stopped(reason: str) -> None:
            _agent_speaking_ref[0] = False
            _agent_speaking_since_ref[0] = 0
            _playout_end_ref[0] = 0.0
            _last_user_speech_ref[0] = time.time()
            _ob_assistant_audio_active_ref[0] = False
            if _ob_tool_handler and hasattr(_ob_tool_handler, "clear_terminal_tool_response_flags"):
                _ob_tool_handler.clear_terminal_tool_response_flags(f"audible_output_stopped:{reason}")
            if _ob_tts_out_logger_ref[0]:
                try:
                    _ob_tts_out_logger_ref[0].finalize_deferred_output_stop_if_ready(
                        f"audible_drain:{reason}"
                    )
                except Exception as _tts_stop_err:
                    logger.debug(f"[Outbound Pipeline] deferred TTS stop finalize failed: {_tts_stop_err}")
            global_state_manager.finish_assistant_output(generation_id=global_state_manager.current_output_generation() or None)
            if global_state_manager.is_speaking():
                global_state_manager.set_state(AgentState.IDLE)
            if _ob_transcription_logger_ref[0]:
                try:
                    _ob_transcription_logger_ref[0].mark_assistant_audio_stopped()
                except Exception:
                    pass
            logger.info(f"[Outbound Pipeline] Audible playout drained reason={reason}")

        def _terminal_tool_response_pending() -> bool:
            if not _ob_tool_handler:
                return False
            pending = bool(
                getattr(_ob_tool_handler, "_tool_result_pending", False)
                or getattr(_ob_tool_handler, "_llm_turn_in_progress", False)
                or getattr(_ob_tool_handler, "_closing_after_tool", False)
            )
            if not pending:
                return False
            _state = _get_audible_output_state()
            _started_at = float(getattr(_ob_tool_handler, "_closing_after_tool_started_at", 0.0) or 0.0)
            _max_wait = float(os.getenv("OUTBOUND_TOOL_CONFIRMATION_CLOSE_MAX_WAIT_SECONDS", "20") or "20")
            if _started_at and time.time() - _started_at > _max_wait:
                _active_audio = bool(
                    _state.get("agent_speaking")
                    or int(_state.get("queue_chunks") or 0) > 0
                    or int(_state.get("playout_end_in_ms") or 0) > 0
                )
                if not _active_audio:
                    logger.warning(
                        f"[Outbound Pipeline] Terminal tool close guard timed out with no active audio; "
                        f"clearing flags state={_state}"
                    )
                    _ob_tool_handler.clear_terminal_tool_response_flags("terminal_tool_guard_timeout")
                    return False
            return True

        def _clear_finished_assistant_audio(reason: str) -> bool:
            if not _agent_speaking_ref[0]:
                return False
            _now = time.time()
            _playout_done = _now >= (_playout_end_ref[0] + _PLAYOUT_SAFETY_SECS)
            _speaking_timed_out = _now - _agent_speaking_since_ref[0] > 10
            if (_playout_done and outbound_q.empty()) or _speaking_timed_out:
                _mark_audible_output_stopped(reason)
                logger.info(
                    f"[Outbound Pipeline] Idle monitor: agent done speaking "
                    f"(playout_done={_playout_done}, q_empty={outbound_q.empty()}, "
                    f"playout_end_in={max(0.0, _playout_end_ref[0] - _now):.2f}s)"
                )
                return True
            return False

        async def _schedule_graceful_call_close(reason: str) -> None:
            if _graceful_close_task_ref[0]:
                return

            async def _worker():
                try:
                    logger.info(f"[Outbound Pipeline] Waiting for final playout before closing ({reason})")
                    _deadline = time.monotonic() + float(os.getenv("OUTBOUND_FAREWELL_CLOSE_MAX_WAIT_SECONDS", "8") or "8")
                    _min_wait_until = time.monotonic() + float(os.getenv("OUTBOUND_FAREWELL_CLOSE_MIN_WAIT_SECONDS", "1.2") or "1.2")
                    while True:
                        _state = _get_audible_output_state()
                        if (
                            _state.get("agent_speaking")
                            and int(_state.get("queue_chunks") or 0) <= 0
                            and int(_state.get("playout_end_in_ms") or 0) <= 0
                        ):
                            _mark_audible_output_stopped(f"graceful_close:{reason}")
                            _state = _get_audible_output_state()
                        if _terminal_tool_response_pending():
                            await asyncio.sleep(0.1)
                            continue
                        if (
                            not _state.get("live")
                            and int(_state.get("queue_chunks") or 0) <= 0
                            and int(_state.get("playout_end_in_ms") or 0) <= 0
                        ):
                            if time.monotonic() < _min_wait_until:
                                await asyncio.sleep(0.1)
                                continue
                            break
                        if time.monotonic() >= _deadline:
                            if (
                                _state.get("agent_speaking")
                                or int(_state.get("playout_end_in_ms") or 0) > 0
                            ):
                                _deadline = time.monotonic() + 1.0
                                logger.info(
                                    f"[Outbound Pipeline] Extending final playout wait; active audio remains "
                                    f"({reason}) state={_state}"
                                )
                                await asyncio.sleep(0.1)
                                continue
                            logger.warning(
                                f"[Outbound Pipeline] Final playout wait timed out - closing call anyway "
                                f"({reason}) state={_state}"
                            )
                            break
                        await asyncio.sleep(0.1)
                    logger.info(f"[Outbound Pipeline] Final playout drained - closing call ({reason})")
                    _call_end_event.set()
                    stop_event.set()
                    try:
                        if _task_ref:
                            await _task_ref[0].queue_frame(EndFrame())
                    except Exception as _end_err:
                        logger.warning(f"[Outbound Pipeline] Graceful close could not queue EndFrame: {_end_err}")
                    try:
                        if _current_room_id:
                            await websocket.send_text(json.dumps({"event": "exit", "room_id": _current_room_id}))
                            logger.info(f"[Outbound Pipeline] Sent Vodafone exit for room {_current_room_id}")
                    except Exception as _exit_err:
                        logger.warning(f"[Outbound Pipeline] Vodafone exit send error: {_exit_err}")
                    try:
                        await websocket.close()
                    except Exception as _ws_err:
                        logger.debug(f"[Outbound Pipeline] Websocket close after playout ignored: {_ws_err}")
                finally:
                    _graceful_close_task_ref[0] = None

            _graceful_close_task_ref[0] = asyncio.create_task(_worker())

        async def _idle_monitor():
            _idle_stage = 0
            _idle_stage_deadline = 0.0
            await asyncio.sleep(5.0)
            _last_user_speech_ref[0] = time.time()
            logger.info("[Outbound Pipeline] Idle monitor started")
            while not stop_event.is_set():
                await asyncio.sleep(1.0)
                if _call_ending_ref[0] or _call_end_event.is_set():
                    _clear_finished_assistant_audio("idle_monitor_call_ending")
                    if _terminal_tool_response_pending():
                        logger.info(
                            "[Outbound Pipeline] Idle monitor: terminal tool response pending, "
                            "deferring graceful close"
                        )
                        continue
                    logger.info(
                        f"[Outbound Pipeline] Idle monitor: call ending, scheduling graceful close "
                        f"(ending_ref={_call_ending_ref[0]}, event={_call_end_event.is_set()})"
                    )
                    await _schedule_graceful_call_close("farewell_idle_monitor")
                    break
                if _ob_tool_handler and _ob_tool_handler.filler_active:
                    _idle_stage = 0
                    _idle_stage_deadline = 0.0
                    _last_user_speech_ref[0] = time.time()
                    continue
                if _should_block_idle_followup():
                    _idle_stage = 0
                    _idle_stage_deadline = 0.0
                    _last_user_speech_ref[0] = time.time()
                    continue
                # Auto-clear agent speaking if outbound queue is empty or timeout
                _clear_finished_assistant_audio("idle_monitor")
                if _agent_speaking_ref[0]:
                    _last_user_speech_ref[0] = time.time()
                    _idle_stage = 0
                    _idle_stage_deadline = 0.0
                    continue
                if global_state_manager.state != AgentState.IDLE:
                    _idle_stage = 0
                    _idle_stage_deadline = 0.0
                    _last_user_speech_ref[0] = time.time()
                    continue
                _now = time.time()
                silence = _now - _last_user_speech_ref[0]
                _idle_threshold = 8.0
                if _ob_tool_handler:
                    _last_prompt = _ob_tool_handler._last_spoken_prompt or {}
                    _last_source = str(_last_prompt.get("source") or "")
                    if _last_prompt.get("question_expected") and (
                        _last_source.startswith("response_guard:")
                        or "area" in _last_source
                        or "location" in _last_source
                    ):
                        _idle_threshold = 14.0
                if _idle_stage == 1 and silence < 8.0:
                    _idle_stage = 0
                    _idle_stage_deadline = 0.0
                if _idle_stage == 1 and silence < _idle_threshold:
                    _idle_stage = 0
                    _idle_stage_deadline = 0.0
                if silence >= _idle_threshold:
                    if _idle_stage == 0:
                        _idle_stage = 1
                        _idle_stage_deadline = _now + 10.0
                        logger.info("[IdleGuard] emitted_are_you_there source=outbound_idle_monitor stage=1")
                        logger.info("[Outbound Pipeline] Idle monitor: asking are you there")
                        await _queue_outbound_pipeline_text(
                            {"hi": "Hello? Kya aap sun pa rahe hain?", "ta": "Hello? Ungalaal kekka mudiyudha?", "kn": "Hello? Neevu keluthiddeera?", "en": "Hello? Are you still there?"}.get(stt_language, "Hello? Are you still there?")
                        )
                    elif _idle_stage == 1 and _now >= _idle_stage_deadline:
                        _idle_stage = 2
                        _call_ending_ref[0] = True
                        logger.info("[Outbound Pipeline] Idle monitor: ending call")
                        await _queue_outbound_pipeline_text(
                            {"hi": "Lagta hai aap busy hain, baad mein call karungi. Dhanyavaad.", "ta": "Neenga busy ah irukeenga pola, piragu call panren. Nandri.", "kn": "Neevu busy irodu hage ide, nantara call maadtini. Dhanyavaadagalu.", "en": "It seems you are busy. I will call back later. Thank you."}.get(stt_language, "It seems you are busy. I will call back later. Thank you.")
                        )
                        await asyncio.sleep(4.0)
                        try:
                            if _task_ref:
                                await _task_ref[0].queue_frame(EndFrame())
                        except Exception as _idle_end_err:
                            logger.warning(f"[Outbound Pipeline] Idle monitor: could not queue EndFrame: {_idle_end_err}")
                        logger.info("[Outbound Pipeline] Idle monitor: forcing disconnect")
                        _call_end_event.set()
                        stop_event.set()
                        try:
                            await websocket.close()
                        except:
                            pass
                        break
                else:
                    _idle_stage = 0
                    _idle_stage_deadline = 0.0


        async def _tts_direct(text):
            """Generate TTS via Cartesia HTTP and push directly to Vodafone websocket."""
            _direct_generation_id = None
            try:
                import httpx as _hx
                text = _normalize_tts_text(_normalize_response_style(text))
                global_state_manager.begin_assistant_output(synthetic=True, text=text)
                global_state_manager.remember_synthetic_message(text)
                global_state_manager.note_synthetic_prompt_triggered(text)
                _direct_generation_id = global_state_manager.begin_output_generation()
                global_state_manager.begin_turn_ledger(_direct_generation_id, synthetic=True)
                resp = await _hx.AsyncClient().post(
                    "https://api.cartesia.ai/tts/bytes",
                    headers={
                        "X-API-Key": os.getenv("CARTESIA_API_KEY"),
                        "Cartesia-Version": "2024-06-10",
                        "Content-Type": "application/json",
                    },
                    json={
                        "model_id": "sonic-3",
                        "transcript": text,
                        "voice": {"mode": "id", "id": voice_id},
                        "generation_config": {
                            "speed": voice_speed,
                            "emotion": CARTESIA_FIXED_EMOTION,
                        },
                        "output_format": {
                            "container": "raw",
                            "encoding": "pcm_s16le",
                            "sample_rate": 8000,
                        },
                        "language": tts_lang.value if hasattr(tts_lang, "value") else str(tts_lang),
                    },
                    timeout=10.0,
                )
                if resp.status_code == 200:
                    raw = resp.content
                    CHUNK = CHUNK_BYTES
                    chunks = [raw[i:i+CHUNK] for i in range(0, len(raw), CHUNK) if len(raw[i:i+CHUNK]) == CHUNK]
                    _direct_conditioner = VodafoneTtsAudioConditioner()
                    logger.info(f"[Outbound Pipeline] Direct TTS: {len(chunks)} chunks for: {text[:40]}")
                    _chunk_secs = CHUNK / float(8000 * 2)
                    for idx, ch in enumerate(chunks):
                        if idx == 0:
                            global_state_manager.note_audio_started()
                        ch = _condition_vodafone_tts_pcm(
                            ch,
                            source="direct_tts",
                            conditioner=_direct_conditioner,
                        )
                        global_state_manager.note_audio_progress(len(ch), sample_rate=8000)
                        b64 = base64.b64encode(ch).decode("utf-8")
                        await websocket.send_text(json.dumps(
                            _build_vodafone_media_frame(
                                b64,
                                _current_room_id,
                            )
                        ))
                        _playout_end_ref[0] = max(_playout_end_ref[0], time.time()) + _chunk_secs
                        await asyncio.sleep(_chunk_secs)
                else:
                    logger.warning(f"[Outbound Pipeline] Direct TTS failed: {resp.status_code}")
            except Exception as e:
                logger.warning(f"[Outbound Pipeline] Direct TTS error: {e}")
            finally:
                global_state_manager.finish_assistant_output(generation_id=_direct_generation_id)

        async def _queue_outbound_pipeline_text(text: str):
            if _task_ref:
                try:
                    await _queue_synthetic_assistant_text(_task_ref[0], text)
                    return
                except Exception as e:
                    logger.warning(f"[Outbound Pipeline] Queue speech fallback to direct TTS: {e}")
            await _tts_direct(text)

        async def on_user_idle_outbound_callback(processor, timeout):
            # idle stage uses ref
            if _ob_transcription_logger_ref[0] and _ob_transcription_logger_ref[0].soft_hold_is_active():
                logger.info("[SoftHold] suppressed outbound idle prompt")
                return
            if _idle_monitor_started_ref[0]:
                logger.info("[IdleGuard] suppressed_are_you_there reason=outbound_custom_idle_monitor_active")
                return
            if _should_block_idle_followup():
                logger.info("[Outbound Pipeline] User idle skipped - interruption/session follow-up still active")
                return
            if global_state_manager.state != AgentState.IDLE:
                logger.info(
                    f"[IdleGuard] suppressed_are_you_there reason=outbound_agent_state:{global_state_manager.state.value}"
                )
                return
            if _outbound_idle_stage_ref[0] == 0:
                _outbound_idle_stage_ref[0] = 1
                logger.info("[IdleGuard] emitted_are_you_there source=outbound_user_idle_processor stage=1")
                logger.info("[Outbound Pipeline] User idle stage 1 - asking are you there")
                await _tts_direct({"hi": "Hello? Kya aap sun pa rahe hain?", "ta": "Hello? Ungalaal kekka mudiyudha?", "kn": "Hello? Neevu keluthiddeera?", "en": "Hello? Are you still there?"}.get(stt_language, "Hello? Are you still there?"))
            elif _outbound_idle_stage_ref[0] == 1:
                _outbound_idle_stage_ref[0] = 2
                logger.info("[Outbound Pipeline] User idle stage 2 - no response, ending call")
                await _tts_direct({"hi": "Lagta hai aap busy hain, baad mein call karungi. Dhanyavaad.", "ta": "Neenga busy ah irukeenga pola, piragu call panren. Nandri.", "kn": "Neevu busy irodu hage ide, nantara call maadtini. Dhanyavaadagalu.", "en": "It seems you are busy. I will call back later. Thank you."}.get(stt_language, "It seems you are busy. I will call back later. Thank you."))
                await asyncio.sleep(6.0)
                await task.queue_frame(EndFrame())
            else:
                logger.info("[Outbound Pipeline] User idle - force ending")
                await task.queue_frame(EndFrame())

        user_idle = UserIdleProcessor(timeout=3, callback=on_user_idle_outbound_callback)

        vad = SileroVADAnalyzer(
            params=VADParams(confidence=0.78, start_secs=0.14, stop_secs=0.35, min_volume=0.80)
        )

        messages = [
            {"role": "system", "content": system_prompt},
            {"role": "assistant", "content": greeting},  # Agent already said this via cached audio
        ]
        context = LLMContext(messages, tools=_ob_tool_schemas)
        context_ref = [context]  # mutable ref for RAGContextInjector and _ob_tool_handler
        if _ob_tool_handler:
            _ob_tool_handler._context_ref = context_ref  # wire in now that context exists
        user_params = LLMUserAggregatorParams(
            vad_analyzer=vad,
            user_turn_stop_timeout=0.2,  # reduced for faster response (was 0.4)
        )
        context_aggregator = LLMContextAggregatorPair(context, user_params=user_params)

        # Register integration tool handlers with the LLM service
        if _ob_tool_handler:
            _ob_tool_handler.register_handlers(llm)

        class TelephonyAudioInput(FrameProcessor):
            """Reads raw PCM from inbound_q and emits AudioRawFrames."""
            def __init__(self, **kwargs):
                super().__init__(**kwargs)
                self._start_received = asyncio.Event()

            async def process_frame(self, frame, direction):
                await super().process_frame(frame, direction)
                if isinstance(frame, StartFrame):
                    self._start_received.set()
                    logger.info("[Outbound Pipeline] Telephony audio input ready")
                await self.push_frame(frame, direction)

            async def run_input(self):
                """Pump PCM chunks from the queue into the pipeline."""
                try:
                    await asyncio.wait_for(self._start_received.wait(), timeout=5.0)
                except asyncio.TimeoutError:
                    logger.warning("[Outbound Pipeline] Telephony input timed out waiting for StartFrame")
                    return
                leftover = b""
                while not stop_event.is_set():
                    try:
                        chunk = await asyncio.wait_for(inbound_q.get(), timeout=0.5)
                    except asyncio.TimeoutError:
                        continue
                    leftover += chunk
                    while len(leftover) >= CHUNK_BYTES:
                        piece = leftover[:CHUNK_BYTES]
                        leftover = leftover[CHUNK_BYTES:]
                        frame = AudioRawFrame(
                            audio=piece,
                            sample_rate=INBOUND_RATE,
                            num_channels=CHANNELS,
                        )
                        if not hasattr(frame, "id"):
                            setattr(frame, "id", str(uuid.uuid4()))
                        if not hasattr(frame, "broadcast_sibling_id"):
                            setattr(frame, "broadcast_sibling_id", None)
                        await self.push_frame(frame)

        class TelephonyAudioOutput(FrameProcessor):
            """
            Receives TTSAudioRawFrames from Cartesia (now 8kHz) and sends
            directly to Vodafone - no resampling needed.
            FIX: Removed audioop.ratecv resampling that caused burbling.
            """
            def __init__(self, **kwargs):
                super().__init__(**kwargs)
                self._buffer = b""
                self._buffer_generation_id: int | None = None

            def _playout_state_for_log(self) -> dict:
                _now = time.time()
                return {
                    "queue_chunks": outbound_q.qsize(),
                    "buffer_bytes": len(self._buffer or b""),
                    "agent_speaking": bool(_agent_speaking_ref[0]),
                    "playout_end_in_ms": int(max(0.0, (_playout_end_ref[0] - _now) * 1000)),
                    "interrupt_event": bool(interrupt_event.is_set()),
                    "provider_clear_pending": bool(_provider_clear_pending_ref[0]),
                }

            def _has_interruptible_audio(self) -> bool:
                _state = self._playout_state_for_log()
                return bool(
                    _state["queue_chunks"] > 0
                    or _state["buffer_bytes"] > 0
                    or _state["agent_speaking"]
                    or _state["playout_end_in_ms"] > 0
                    or _state["provider_clear_pending"]
                )

            def _drain_buffers(self, *, mark_interrupted: bool):
                count = 0
                while not outbound_q.empty():
                    try:
                        outbound_q.get_nowait()
                        count += 1
                    except:
                        break
                self._buffer = b""
                self._buffer_generation_id = None
                _vodafone_tts_conditioner.reset()
                _playout_end_ref[0] = time.time()
                _ledger = global_state_manager.current_turn_ledger()
                if _ledger and _ledger.playout_cursor:
                    _ledger.playout_cursor.telephony_queue_drained_at = _playout_end_ref[0]
                if mark_interrupted:
                    interrupt_event.set()
                return count

            def _clear_queue(self, *, mark_interrupted: bool, reason: str):
                count = self._drain_buffers(mark_interrupted=mark_interrupted)
                _state = self._playout_state_for_log()
                if count > 0:
                    logger.info(
                        f"[Outbound Pipeline] Audio queue cleared: {count} chunks removed "
                        f"(~{count * CHUNK_MS}ms) reason={reason} state={_state}"
                    )
                else:
                    logger.info(
                        f"[Outbound Pipeline] Interruption drain completed with empty queue "
                        f"reason={reason} mark_interrupted={mark_interrupted} state={_state}"
                    )

            async def process_frame(self, frame, direction):
                await super().process_frame(frame, direction)
                if isinstance(frame, InterruptionFrame):
                    if self._has_interruptible_audio():
                        self._clear_queue(mark_interrupted=True, reason=type(frame).__name__)
                    else:
                        if interrupt_event.is_set() and not _provider_clear_pending_ref[0]:
                            interrupt_event.clear()
                        logger.info(
                            f"[Outbound Pipeline] Ignored empty interruption - no audible output live "
                            f"frame={type(frame).__name__} state={self._playout_state_for_log()}"
                        )
                elif isinstance(frame, TTSStoppedFrame):
                    if self._buffer:
                        if (
                            interrupt_event.is_set()
                            or self._buffer_generation_id in _invalidated_output_generations
                            or (
                                _provider_clear_pending_ref[0]
                                and (
                                    not self._buffer_generation_id
                                    or self._buffer_generation_id == _provider_clear_generation_ref[0]
                                )
                            )
                        ):
                            logger.info(
                                f"[Outbound Pipeline] Dropped stale TTS tail for generation={self._buffer_generation_id} "
                                f"interrupt={interrupt_event.is_set()} clear_pending={_provider_clear_pending_ref[0]}"
                            )
                            _interrupt_cutoff_metrics_ref[0]["stale_chunks_dropped"] += 1
                            self._buffer = b""
                            self._buffer_generation_id = None
                        else:
                            _tail = self._buffer
                            self._buffer = b""
                            _tail_generation = self._buffer_generation_id
                            self._buffer_generation_id = None
                            if len(_tail) < CHUNK_BYTES:
                                _tail = _tail + (b"\x00" * (CHUNK_BYTES - len(_tail)))
                            if await _await_outbound_capacity("tts_tail"):
                                await outbound_q.put((_tail_generation or 0, _tail, "tts_tail"))
                            logger.info(
                                f"[Outbound Pipeline] Flushed final TTS tail chunk ({len(_tail)} bytes, "
                                f"qsize={outbound_q.qsize()}, queued_ms~={outbound_q.qsize() * CHUNK_MS}, "
                                f"generation={_tail_generation})"
                            )
                    if _call_ending_ref[0]:
                        await _schedule_graceful_call_close("tts_stopped")
                    await self.push_frame(frame, direction)
                elif isinstance(frame, TTSAudioRawFrame):
                    # Drop TTS audio if user is speaking (barge-in)
                    if False and _user_speaking.is_set():
                        logger.debug("[Outbound Pipeline] Dropping TTS chunk - user speaking")
                        return
                    _agent_speaking_ref[0] = True
                    _agent_speaking_since_ref[0] = time.time()
                    _last_user_speech_ref[0] = time.time()
                    _frame_generation = int(getattr(frame, "_output_generation_id", 0) or 0)
                    if _frame_generation in _invalidated_output_generations:
                        logger.info(
                            f"[Outbound Pipeline] Dropped stale TTSAudioRawFrame "
                            f"generation={_frame_generation} state={self._playout_state_for_log()}"
                        )
                        _interrupt_cutoff_metrics_ref[0]["stale_chunks_dropped"] += 1
                        return
                    if interrupt_event.is_set():
                        if (
                            not _provider_clear_pending_ref[0]
                            and not _frame_generation
                        ):
                            interrupt_event.clear()
                            logger.info(
                                f"[Outbound Pipeline] Released stale interrupt gate for generation-0 TTS "
                                f"state={self._playout_state_for_log()}"
                            )
                        elif (
                            _provider_clear_pending_ref[0]
                            and (
                                (_frame_generation and _frame_generation != _provider_clear_generation_ref[0])
                                or (
                                    not _frame_generation
                                    and _provider_clear_generation_ref[0] in _invalidated_output_generations
                                )
                            )
                        ):
                            interrupt_event.clear()
                            _provider_clear_pending_ref[0] = False
                            logger.info(
                                f"[Outbound Pipeline] Provider clear gate released by new TTS generation "
                                f"{_provider_clear_generation_ref[0]} -> {_frame_generation} "
                                f"state={self._playout_state_for_log()}"
                            )
                        if (
                            interrupt_event.is_set()
                            and (
                                not _frame_generation
                                or _frame_generation == _provider_clear_generation_ref[0]
                            )
                            or (
                                _provider_clear_pending_ref[0]
                                and (
                                    not _frame_generation
                                    or _frame_generation == _provider_clear_generation_ref[0]
                                )
                            )
                        ):
                            logger.info(
                                f"[Outbound Pipeline] Dropped TTSAudioRawFrame after interrupt "
                                f"generation={_frame_generation} clear_pending={_provider_clear_pending_ref[0]} "
                                f"state={self._playout_state_for_log()}"
                            )
                            _interrupt_cutoff_metrics_ref[0]["stale_chunks_dropped"] += 1
                            self._buffer = b""
                            self._buffer_generation_id = None
                            return
                        if interrupt_event.is_set():
                            interrupt_event.clear()
                            logger.info(
                                f"[Outbound Pipeline] Interrupt gate released by new TTS generation "
                                f"{_provider_clear_generation_ref[0]} -> {_frame_generation} "
                                f"state={self._playout_state_for_log()}"
                            )
                    if _provider_clear_pending_ref[0] and _frame_generation and _frame_generation != _provider_clear_generation_ref[0]:
                        _provider_clear_pending_ref[0] = False
                        logger.info(
                            f"[Outbound Pipeline] Provider clear gate released by new generation "
                            f"{_provider_clear_generation_ref[0]} -> {_frame_generation}"
                        )
                    if (
                        self._buffer
                        and self._buffer_generation_id is not None
                        and _frame_generation
                        and self._buffer_generation_id != _frame_generation
                    ):
                        logger.info(
                            f"[Outbound Pipeline] Reset buffered audio on generation switch "
                            f"{self._buffer_generation_id} -> {_frame_generation}"
                        )
                        self._buffer = b""
                        self._buffer_generation_id = None
                    if self._buffer_generation_id is None:
                        self._buffer_generation_id = _frame_generation
                    self._buffer += frame.audio
                    # Check if this is part of goodbye - will be set by EndCallOnGoodbye
                    while len(self._buffer) >= CHUNK_BYTES:
                        chunk = self._buffer[:CHUNK_BYTES]
                        self._buffer = self._buffer[CHUNK_BYTES:]
                        chunk_generation = self._buffer_generation_id or _frame_generation
                        if not await _await_outbound_capacity("tts_chunk"):
                            break
                        await outbound_q.put((chunk_generation, chunk, "tts_chunk"))
                else:
                    await self.push_frame(frame, direction)

        audio_in  = TelephonyAudioInput()
        audio_out = TelephonyAudioOutput()

        async def _interrupt_telephony_playout(source: str, text: str = ""):
            _interrupt_started_at = time.time()
            _provider_lead_ms_at_commit = max(
                0, int((_playout_end_ref[0] - _interrupt_started_at) * 1000)
            )
            _current_generation = int(global_state_manager.current_output_generation() or 0)
            if _current_generation:
                _invalidated_output_generations.add(_current_generation)
                _provider_clear_generation_ref[0] = _current_generation
            count = audio_out._drain_buffers(mark_interrupted=True)
            _interrupt_cutoff_metrics_ref[0]["interrupt_detected_at"] = _interrupt_started_at
            _interrupt_cutoff_metrics_ref[0]["local_queue_drained_chunks"] = count
            _interrupt_cutoff_metrics_ref[0]["provider_lead_ms_at_commit"] = _provider_lead_ms_at_commit
            _provider_clear_pending_ref[0] = True
            interrupt_event.set()
            _user_speaking.clear()
            _provider_clear_sent = False
            try:
                if _current_room_id:
                    await websocket.send_text(json.dumps({
                        "event": "clear",
                        "room_id": _current_room_id,
                    }))
                    _provider_clear_sent = True
                    _interrupt_cutoff_metrics_ref[0]["vodafone_clear_sent_at"] = time.time()
            except Exception as e:
                logger.warning(f"[Outbound Pipeline] Immediate provider clear failed: {e}")
            _mark_audible_output_stopped("committed_interrupt")
            _clear_at = _interrupt_cutoff_metrics_ref[0].get("vodafone_clear_sent_at")
            _clear_ms = int(max(0.0, ((_clear_at or _interrupt_started_at) - _interrupt_started_at) * 1000))
            logger.info(
                f"[Outbound Pipeline] Immediate interruption flush source={source} "
                f"q_cleared={count} queued_ms~={count * CHUNK_MS} "
                f"provider_clear_sent={_provider_clear_sent} "
                f"interrupt_cutoff_predicted_ms={count * CHUNK_MS} "
                f"provider_lead_ms_at_commit={_interrupt_cutoff_metrics_ref[0].get('provider_lead_ms_at_commit', 0)} "
                f"detect_to_clear_ms={_clear_ms} "
                f"stale_chunks_dropped={_interrupt_cutoff_metrics_ref[0].get('stale_chunks_dropped', 0)} "
                f"playout_state={_get_audible_output_state()} text={text!r}"
            )

        _task_ref = []
        _call_end_event_ref = [_call_end_event]
        # Goodbye phrases from dashboard or language-based defaults
        _goodbye_defaults = {
            "hi": ["aapka din shubh ho", "aapka din shubh rahe", "baad mein call karungi", "bahut bahut dhanyavaad", "lagta hai aap busy hain"],
            "en": ["have a great day", "goodbye", "thank you for your time", "have a nice day", "it seems like you are busy"],
            "en-IN": ["have a great day", "goodbye", "thank you for your time", "have a nice day", "it seems like you are busy"],
            "en-US": ["have a great day", "goodbye", "thank you for your time", "have a nice day", "it seems like you are busy"],
            "es": ["que tenga un buen dia", "adios", "gracias por su tiempo"],
            "fr": ["bonne journee", "au revoir", "merci pour votre temps"],
            "de": ["einen schonen tag noch", "auf wiedersehen", "danke fur ihre zeit"],
            "it": ["buona giornata", "arrivederci", "grazie per il suo tempo"],
            "pt": ["tenha um bom dia", "adeus", "obrigado pelo seu tempo"],
            "ja": ["è‰¯ã„ä¸€æ-¥ã‚’", "ã•ã‚ˆã†ãªã‚‰", "ãŠæ™‚é–“ã‚’ã„ãŸã ãã‚ã‚ŠãŒã¨ã†ã”ã–ã„ã¾ã™"],
            "ko": ["ì¢‹ì€ í•˜ë£¨ ë˜ì„¸ìš”", "ì•ˆë…•ížˆ ê³„ì„¸ìš”", "ì‹œê°„ ë‚´ì£¼ì…”ì„œ ê°ì‚¬í•©ë‹ˆë‹¤"],
            "zh": ["ç¥æ‚¨æœ‰ç¾Žå¥½çš„ä¸€å¤©", "å†è§", "æ„Ÿè°¢æ‚¨çš„æ-¶é-´"],
            "ta": ["nandri", "ungal naal nalladhaaga amaiyattum", "nandri vanakkam", "busy ah irukeenga pola"],
            "kn": ["dhanyavaadagalu", "nimma dina shubhavagali", "namaskaara", "busy iddeera ansuthe"],
        }
        _dashboard_phrases = cfg.get("endCallPhrases", None)
        _core_goodbye_phrases = [
            "thank you for calling",
            "have a great day",
            "have a nice day",
            "thank you for your time",
            "goodbye",
            "bye",
        ]
        if _dashboard_phrases and isinstance(_dashboard_phrases, list) and len(_dashboard_phrases) > 0:
            _goodbye_phrases = list(dict.fromkeys([*(_dashboard_phrases or []), *(_core_goodbye_phrases or [])]))
            logger.info(f"[Outbound Pipeline] Goodbye phrases from dashboard+core defaults: {_goodbye_phrases}")
        else:
            _goodbye_phrases = list(dict.fromkeys([*(_goodbye_defaults.get(stt_language, _goodbye_defaults["en"]) or []), *(_core_goodbye_phrases or [])]))
            logger.info(f"[Outbound Pipeline] Goodbye phrases from language defaults ({stt_language}): {_goodbye_phrases}")
        end_call_detector = EndCallOnGoodbye(call_end_event_ref=_call_end_event_ref, task_ref=_task_ref, room_id_ref=_room_id_ref, phrases=_goodbye_phrases, call_closing_ref=_call_ending_ref)
        end_call_detector._ws_ref.append(websocket)

        # Transfer detector - only active when configured on the assistant
        _ob_transfer_detector = None
        if _ob_transfer_number:
            _ob_transfer_detector = TransferCallDetector(
                call_id=call_id,
                transfer_number=_ob_transfer_number,
                backend_url=BACKEND_URL,
                call_end_event_ref=_call_end_event_ref,
                task_ref=_task_ref,
                ws_ref=[websocket],
                room_id_ref=_room_id_ref,
            )

        # RAG context injector - only active when rag_enabled is true for this assistant
        _ob_assistant_id = (
            cfg.get("id") or cfg.get("assistant_id") or cfg.get("assistantId")
        ) if cfg else None
        _ob_rag_enabled = bool(cfg.get("ragEnabled", False)) if cfg else False
        _ob_rag_injector = None
        if _ob_assistant_id and _ob_rag_enabled:
            _ob_rag_injector = RAGContextInjector(
                assistant_id=_ob_assistant_id,
                backend_url=BACKEND_URL,
                context_ref=context_ref,
            )
            logger.info(f"[Outbound Pipeline] RAG  â†’ Context injector enabled (rag_enabled=true, assistant={_ob_assistant_id})")
        else:
            logger.info(f"[Outbound Pipeline] RAG  â†’ Disabled (rag_enabled={_ob_rag_enabled}, assistant={_ob_assistant_id})")

        _ob_turn_ts_ref: list = [None, ""]
        _ob_assistant_audio_active_ref: list = [False]
        _ob_speaker_signal_ref: list = [{}]
        _ob_usage_metrics_ref = [build_empty_usage_metrics()]
        _ob_shadow_turn_adapter = DeepgramFluxShadowAdapter(global_state_manager.record_shadow_turn_taking_event)
        # Shared list to aggregate turn latencies for end-of-call summary (outbound)
        _ob_call_latency_ref: list = []
        _ob_speaker_candidate_gate = None
        _ob_speaker_playback_gate = None
        if SPEAKER_SEPARATION_V1_ENABLED:
            try:
                _ob_barge_detector = BargeInDetector(
                    sample_rate=INBOUND_RATE,
                    playback_idle_timeout_ms=900,
                    playback_warmup_ms=NO_BARGE_IN_MS,
                    signal_ref=_ob_speaker_signal_ref,
                )
                _ob_speaker_candidate_gate = MicVADFilter(_ob_barge_detector, signal_ref=_ob_speaker_signal_ref)
                _ob_speaker_playback_gate = PlaybackTracker(_ob_barge_detector, signal_ref=_ob_speaker_signal_ref)
                logger.info("[Speaker Separation] outbound gate enabled")
            except Exception as _speaker_err:
                logger.warning(f"[Speaker Separation] outbound gate disabled: {_speaker_err}")
        _pipeline_steps = [
            audio_in,
            UserAudioRecordingTap(_ob_call_recorder),
            STTAudioUsageTracker(
                _ob_usage_metrics_ref,
                stt_provider=stt_provider,
                stt_region=os.getenv("AZURE_SPEECH_REGION", "centralindia"),
                stt_model=stt_model or "",
            ),
        ]
        if _ob_speaker_candidate_gate:
            _pipeline_steps.append(_ob_speaker_candidate_gate)
        _ob_transcription_logger = TranscriptionLogger(
            speaking_event=None,
            tts_service=tts,
            idle_speech_ref=_last_user_speech_ref,
            idle_agent_ref=_agent_speaking_ref,
            tool_handler=_ob_tool_handler,
            stt_language=stt_language,
            context_ref=context_ref,
            turn_ts_ref=_ob_turn_ts_ref,
            latency_trace_ref=_ob_latency_trace_ref,
            assistant_audio_active_ref=_ob_assistant_audio_active_ref,
            interrupt_transport_callback=_interrupt_telephony_playout,
            speaker_signal_ref=_ob_speaker_signal_ref,
            shadow_turn_adapter=_ob_shadow_turn_adapter,
            stt_provider_profile=_ob_stt_provider_profile,
            audible_output_state_provider=_get_audible_output_state,
            greeting_done_ref=_greeting_done_ref,
            call_closing_ref=_call_ending_ref,
            transcript_ledger_ref=_ob_transcript_ledger_ref,
        )
        _ob_transcription_logger_ref[0] = _ob_transcription_logger
        _ob_tts_out_logger = TTSActivityLogger(
            label="TTS-OUT",
            mode="output",
            turn_ts_ref=_ob_turn_ts_ref,
            call_latency_ref=_ob_call_latency_ref,
            latency_trace_ref=_ob_latency_trace_ref,
            assistant_audio_active_ref=_ob_assistant_audio_active_ref,
            audible_output_state_provider=_get_audible_output_state,
            tool_handler=_ob_tool_handler,
        )
        _ob_tts_out_logger_ref[0] = _ob_tts_out_logger
        _pipeline_steps.extend([
            stt,
            _ob_transcription_logger,
        ])
        if _ob_rag_injector:
            _pipeline_steps.append(_ob_rag_injector)
        # ToolAckFilter suppresses "okay"/"sure" utterances while filler TTS is playing
        if _ob_tool_handler:
            _pipeline_steps.append(ToolAckFilter(_ob_tool_handler))
        _pipeline_steps.extend([
            context_aggregator.user(),
            llm,
        ])
        if _ob_transfer_detector:
            _pipeline_steps.append(_ob_transfer_detector)
        # PropertyHallucinationGuard: blocks LLM attempts to describe property details without calling get_property_details
        if _ob_tool_handler:
            _pipeline_steps.append(PropertyHallucinationGuard(tool_handler=_ob_tool_handler))
        _pipeline_steps.extend([
            end_call_detector,
            ToolPreambleFilter(),
            FunctionCallTextFilter(),
        TTSActivityLogger(label="TTS-IN", mode="input", turn_ts_ref=_ob_turn_ts_ref, call_latency_ref=_ob_call_latency_ref, latency_trace_ref=_ob_latency_trace_ref, tool_handler=_ob_tool_handler, transcript_ledger_ref=_ob_transcript_ledger_ref),
            SentenceStreamingTTS(tts, latency_trace_ref=_ob_latency_trace_ref, context=context),  # Stream sentences to TTS for low-latency audio
            tts,                         # TTS service must be in pipeline so push_frame() reaches transport
            _ob_tts_out_logger,
        ])
        if _ob_speaker_playback_gate:
            _pipeline_steps.append(_ob_speaker_playback_gate)
        _pipeline_steps.extend([
            AssistantAudioRecordingTap(_ob_call_recorder),
            audio_out,
            UsageMetricsCollector(_ob_usage_metrics_ref),
            AssistantContextGate(),
            context_aggregator.assistant(),
        ])
        pipeline = Pipeline(_pipeline_steps)

        task = PipelineTask(
            pipeline,
            params=PipelineParams(
                allow_interruptions=True,
                enable_metrics=True,
                enable_usage_metrics=True,
                report_only_initial_ttfb=True,
            ),
            cancel_on_idle_timeout=False,
            idle_timeout_secs=None,
        )
        _task_ref.append(task)

        # Agent speaks first - cached greeting injected after channel stabilizes.

        async def _mark_pipeline_ready():
            await asyncio.sleep(1.5)  # Give pipeline time to process StartFrame
            _pipeline_ready_ref[0] = True
            logger.info("[Outbound Pipeline] Pipeline marked ready")

        asyncio.get_event_loop().create_task(_mark_pipeline_ready())
        call_start = time.time()
        
        try:
            global_state_manager.reset_call_metrics()
            assistant_id = (
                assistant_config.get("id")
                or assistant_config.get("assistant_id")
                or assistant_config.get("assistantId")
            ) if assistant_config else None
            assistant_name = assistant_config.get("name") if assistant_config else "Priya (Default)"
            _existing_call = active_calls.get(call_id, {})
            active_calls[call_id] = {
                "start_time": time.time(),
                "assistant_id": assistant_id,
                "assistant_name": assistant_name,
                "vodafone_call_id": vodafone_call_id,
                "vodafone_cli": vodafone_cli,
                "call_direction": call_direction,
                "phone_number": phone_number or _existing_call.get("phone_number") or f"vodafone-{call_direction}",
                "caller": caller or _existing_call.get("caller") or "vodafone-telephony",
                "room_id": None,
                "final_status": "completed",
                "usage_metrics": _ob_usage_metrics_ref[0],
            }
            logger.info(
                f"[Outbound Pipeline] active_calls set: call_id={call_id}, "
                f"assistant_id={active_calls[call_id]['assistant_id']}, "
                f"name={active_calls[call_id]['assistant_name']}"
            )
        except Exception as e:
            logger.error(f"[Outbound Pipeline] Error registering existing call: {e}")
        
        runner = PipelineRunner()

        try:
            async with asyncio.TaskGroup() as tg:
                tg.create_task(ws_reader())
                tg.create_task(ws_writer())
                logger.info(f"[Outbound Pipeline] Max call duration set to {max_duration}s")
                tg.create_task(enforce_max_duration(task, max_duration, stop_event))
                tg.create_task(runner.run(task))
                tg.create_task(audio_in.run_input())
        except* Exception as eg:
            for exc in eg.exceptions:
                logger.info(f"[Outbound Pipeline] Task ended: {exc}")
        finally:
            stop_event.set()
            duration = time.time() - call_start
            logger.info(f"[Outbound Pipeline] Call {call_id} ended (duration={int(duration)}s)")
            # Log call-level latency summary
            if _ob_call_latency_ref:
                _turn_count = len(_ob_call_latency_ref)
                _avg_llm = sum(t.get("llm_ms", 0) or 0 for t in _ob_call_latency_ref) // _turn_count if _turn_count else 0
                _avg_tts = sum(t.get("tts_ms", 0) or 0 for t in _ob_call_latency_ref) // _turn_count if _turn_count else 0
                _avg_e2e = sum(t.get("e2e_ms", 0) or 0 for t in _ob_call_latency_ref) // _turn_count if _turn_count else 0
                _p95_e2e = sorted(t.get("e2e_ms", 0) or 0 for t in _ob_call_latency_ref)[int(_turn_count * 0.95)] if _turn_count > 1 else (_ob_call_latency_ref[0].get("e2e_ms") if _ob_call_latency_ref else 0)
                logger.info(f"â± CALL LATENCY SUMMARY - {_turn_count} turns | avg LLM {_avg_llm}ms | avg TTS {_avg_tts}ms | avg E2E {_avg_e2e}ms | p95 E2E {_p95_e2e}ms")
            # Fallback: complete_call was already fired from ws_reader's finally as a
            # background task (immune to cancellation). If it already ran, active_calls
            # won't contain call_id and this will be a safe no-op. Shield it anyway so
            # a CancelledError from the TaskGroup teardown can't suppress the call.
            try:
                _ob_extra_meta = {
                    "interruptionMetrics": global_state_manager.build_interrupt_metrics_payload(),
                    "latencyBreakdownV2": build_latency_breakdown_v2(_ob_call_latency_ref),
                }
                if _ob_tool_handler:
                    _ob_extra_meta["persona"] = _ob_tool_handler._persona
                    _ob_extra_meta["lead_score"] = _ob_tool_handler._lead_score
                _ob_extra_meta["shadowTurnTakingComparison"] = _ob_extra_meta["interruptionMetrics"].get("shadowTurnTakingComparison", [])
                _ob_extra_meta["speakerSeparationSignals"] = _ob_extra_meta["interruptionMetrics"].get("speakerSeparationSignals", [])
                _ob_extra_meta["usageMetrics"] = _ob_usage_metrics_ref[0]
                _recording_url = await _finalize_outbound_recording_once()
                if _recording_url:
                    _ob_extra_meta["recordingUrl"] = _recording_url
                await asyncio.shield(
                    complete_call(
                        call_id,
                        duration,
                        _transcript_from_ledger_or_context(_ob_transcript_ledger_ref, context.messages),
                        config=assistant_config,
                        extra_metadata=_ob_extra_meta,
                    )
                )
            except asyncio.CancelledError:
                logger.warning("[Outbound Pipeline] finally: complete_call shielded - already handled by ws_reader background task")
            except Exception as _fe:
                logger.error(f"[Outbound Pipeline] finally: complete_call error: {_fe}")

    # Store assistant_id for outbound calls
    async def run_vodafone_inbound_pipeline(
        websocket,
        call_id: str,
        assistant_config: dict,
        initial_messages: list | None = None,
        vodafone_call_id: str | None = None,
        vodafone_cli: str | None = None,
        vodafone_dni: str | None = None,
    ):
        """Dedicated Vodafone inbound telephony entry path."""
        logger.info(
            f"[Vodafone Inbound] Starting inbound telephony pipeline for call {call_id} "
            f"(cli={vodafone_cli}, dni={vodafone_dni})"
        )
        await run_outbound_pipeline(
            websocket=websocket,
            call_id=call_id,
            assistant_config=assistant_config,
            initial_messages=initial_messages,
            vodafone_call_id=vodafone_call_id,
            vodafone_cli=vodafone_cli,
            call_direction="inbound",
            phone_number=vodafone_dni or "vodafone-inbound",
            caller=vodafone_cli or "vodafone-inbound",
        )

    async def complete_outbound_call(call_id: str, duration: float, transcript: list, config: dict = None):
        """Complete an outbound call and let the backend finalize credit consumption."""
        try:
            success = await complete_call(call_id, duration, transcript, config)
            if success:
                logger.info(f"âœ… Outbound call {call_id} completed successfully - credits finalized")
            else:
                logger.error(f"âŒ Failed to complete outbound call {call_id}")
        except Exception as e:
            logger.error(f"âŒ Error completing outbound call {call_id}: {e}")

    async def cancel_outbound_call(call_id: str, reason: str = "Call ended"):
        """Cancel an outbound call and let the backend release reserved credits."""
        try:
            success = await cancel_call(call_id, reason)
            if success:
                logger.info(f"âœ… Outbound call {call_id} cancelled successfully - credits released")
            else:
                logger.error(f"âŒ Failed to cancel outbound call {call_id}")
        except Exception as e:
            logger.error(f"âŒ Error cancelling outbound call {call_id}: {e}")

    # Stores outbound session metadata keyed by internal call_id for outbound calls.
    _outbound_call_store: dict[str, dict] = {}
    try:
        _outbound_match_fallback_ttl_seconds = max(
            120.0,
            float(os.getenv("OUTBOUND_MATCH_FALLBACK_TTL_SECONDS", "600").strip() or "600"),
        )
    except Exception:
        _outbound_match_fallback_ttl_seconds = 600.0
    try:
        _outbound_root_match_max_age_seconds = max(
            30.0,
            float(os.getenv("OUTBOUND_ROOT_MATCH_MAX_AGE_SECONDS", "180").strip() or "180"),
        )
    except Exception:
        _outbound_root_match_max_age_seconds = 180.0

    def _outbound_payload_age_seconds(payload: dict) -> float:
        return max(0.0, time.time() - float((payload or {}).get("created_at", 0) or 0))

    def _purge_stale_outbound_calls(max_age_seconds: float | None = None) -> None:
        max_age = (
            _outbound_match_fallback_ttl_seconds
            if max_age_seconds is None
            else max_age_seconds
        )
        for _stale_id, _payload in list(_outbound_call_store.items()):
            if _outbound_payload_age_seconds(_payload) > max_age:
                logger.info(
                    f"[Vodafone WS] Purging stale call from store: {_stale_id} "
                    f"age_seconds={int(_outbound_payload_age_seconds(_payload))}"
                )
                _outbound_call_store.pop(_stale_id, None)

    def _pop_single_recent_outbound_call(max_age_seconds: float | None = None):
        max_age = (
            _outbound_match_fallback_ttl_seconds
            if max_age_seconds is None
            else max_age_seconds
        )
        now = time.time()
        fresh_matches = [
            (internal_call_id, payload)
            for internal_call_id, payload in list(_outbound_call_store.items())
            if now - float(payload.get("created_at", 0) or 0) <= max_age
        ]
        if len(fresh_matches) != 1:
            return None

        internal_call_id, payload = fresh_matches[0]
        _outbound_call_store.pop(internal_call_id, None)
        return {"call_id": internal_call_id, **payload}

    def _normalize_phone(number: str) -> str:
        """Strip country code / leading zeros for comparison."""
        n = str(number or "").strip().lstrip("+")
        if n.startswith("91") and len(n) == 12:
            n = n[2:]
        elif n.startswith("0") and len(n) == 11:
            n = n[1:]
        return n

    def _summarize_outbound_store() -> dict[str, dict]:
        _now = time.time()
        return {
            str(call_key): {
                "assistant_id": payload.get("assistant_id"),
                "vodafone_call_id": payload.get("vodafone_call_id"),
                "phone_number": payload.get("phone_number"),
                "stage": payload.get("stage"),
                "age_seconds": int(_now - float((payload or {}).get("created_at", 0) or 0)),
            }
            for call_key, payload in list(_outbound_call_store.items())
        }

    def _extract_vodafone_root_identifiers(message: dict | None) -> dict[str, str | None]:
        _msg = message or {}
        _start = _msg.get("start") or {}
        _room_id = (
            _msg.get("room_id")
            or _start.get("room_id")
            or _msg.get("room")
            or _start.get("room")
            or _msg.get("streamSid")
            or _start.get("streamSid")
            or _msg.get("stream_id")
            or _start.get("stream_id")
        )
        _session_id = (
            _msg.get("session_id")
            or _start.get("session_id")
            or _msg.get("sessionId")
            or _start.get("sessionId")
            or _msg.get("streamSid")
            or _start.get("streamSid")
        )
        return {
            "event": _msg.get("event"),
            "provider_call_id": (
                _msg.get("call_id")
                or _start.get("call_id")
                or _start.get("callId")
                or _start.get("vodafone_call_id")
            ),
            "provider_cli": (
                _msg.get("cli")
                or _start.get("cli")
                or _start.get("from")
            ),
            "provider_dni": (
                _msg.get("dni")
                or _start.get("dni")
                or _start.get("to")
            ),
            "room_id": _room_id,
            "session_id": _session_id,
        }

    def _pop_outbound_call(
        provider_call_id: str | None = None,
        provider_dni: str | None = None,
        provider_cli: str | None = None,
    ):
        if not provider_call_id and not provider_dni and not provider_cli:
            return None
        norm_dni = _normalize_phone(provider_dni) if provider_dni else None
        norm_cli = _normalize_phone(provider_cli) if provider_cli else None
        provider_numbers = {n for n in (norm_dni, norm_cli) if n}
        # Primary: match by vodafone_call_id VALUE or by phone number. Vodafone
        # OBD start frames can put the customer leg in cli instead of dni.
        for internal_call_id, payload in list(_outbound_call_store.items()):
            if provider_call_id and payload.get("vodafone_call_id") == provider_call_id:
                _outbound_call_store.pop(internal_call_id, None)
                return {"call_id": internal_call_id, **payload}
            if provider_numbers and payload.get("phone_number"):
                if _normalize_phone(str(payload["phone_number"])) in provider_numbers:
                    _outbound_call_store.pop(internal_call_id, None)
                    return {"call_id": internal_call_id, **payload}
        # Fallback: treat provider_call_id as the internal call_id key directly
        if provider_call_id and provider_call_id in _outbound_call_store:
            payload = _outbound_call_store.pop(provider_call_id)
            return {"call_id": provider_call_id, **payload}
        return None

    def _select_outbound_call_for_root_start(
        provider_call_id: str | None = None,
        provider_dni: str | None = None,
        provider_cli: str | None = None,
    ):
        """
        Vodafone OBD answer can arrive on the configured root websocket before
        Start_Streaming has been requested. The root start frame contains the
        numeric provider call_id, while preregistration stores the campaign key,
        so prefer exact campaign/internal matches and then choose the newest
        fresh call whose customer phone matches the start frame.
        """
        if not _outbound_call_store:
            logger.info(
                f"[Vodafone WS] Root match skipped: empty outbound store "
                f"provider_call_id={provider_call_id} cli={provider_cli} dni={provider_dni}"
            )
            return None

        _purge_stale_outbound_calls(_outbound_root_match_max_age_seconds)
        now = time.time()
        fresh_items = [
            (internal_call_id, payload)
            for internal_call_id, payload in list(_outbound_call_store.items())
            if now - float((payload or {}).get("created_at", 0) or 0) <= _outbound_root_match_max_age_seconds
        ]
        if not fresh_items:
            logger.info(
                f"[Vodafone WS] Root match skipped: no fresh outbound entries "
                f"provider_call_id={provider_call_id} cli={provider_cli} dni={provider_dni}"
            )
            return None

        logger.info(
            f"[Vodafone WS] Root match attempt provider_call_id={provider_call_id} "
            f"cli={provider_cli} dni={provider_dni} candidates="
            f"{json.dumps(_summarize_outbound_store(), default=str)}"
        )

        if provider_call_id:
            for internal_call_id, payload in fresh_items:
                if payload.get("vodafone_call_id") == provider_call_id:
                    logger.info(
                        f"[Vodafone WS] Root match success by stored vodafone_call_id: "
                        f"call_id={internal_call_id} provider_call_id={provider_call_id}"
                    )
                    return internal_call_id, payload, "vodafone_call_id"
            if provider_call_id in _outbound_call_store:
                logger.info(
                    f"[Vodafone WS] Root match success by internal call_id fallback: "
                    f"call_id={provider_call_id}"
                )
                return provider_call_id, _outbound_call_store[provider_call_id], "internal_call_id"

        norm_dni = _normalize_phone(provider_dni) if provider_dni else None
        norm_cli = _normalize_phone(provider_cli) if provider_cli else None
        provider_numbers = {n for n in (norm_dni, norm_cli) if n}
        phone_matches = []
        if provider_numbers:
            for internal_call_id, payload in fresh_items:
                stored_phone = _normalize_phone(str(payload.get("phone_number") or ""))
                if stored_phone and stored_phone in provider_numbers:
                    phone_matches.append((internal_call_id, payload))
        if phone_matches:
            phone_matches.sort(
                key=lambda item: float((item[1] or {}).get("created_at", 0) or 0),
                reverse=True,
            )
            logger.info(
                f"[Vodafone WS] Root match success by phone_number_newest: "
                f"call_id={phone_matches[0][0]} provider_numbers={sorted(provider_numbers)}"
            )
            return phone_matches[0][0], phone_matches[0][1], "phone_number_newest"

        if len(fresh_items) == 1:
            logger.info(
                f"[Vodafone WS] Root match success by single_fresh_pending: "
                f"call_id={fresh_items[0][0]}"
            )
            return fresh_items[0][0], fresh_items[0][1], "single_fresh_pending"

        logger.warning(
            f"[Vodafone WS] Root match failed provider_call_id={provider_call_id} "
            f"cli={provider_cli} dni={provider_dni} fresh_candidates={len(fresh_items)}"
        )
        return None

    @app.post("/api/start-outbound")
    async def start_outbound(request: Request):
        """Called by backend when Vodafone confirms call is active."""
        try:
            body = await request.json()
            call_id = body.get("call_id")
            assistant_id = body.get("assistant_id")
            vodafone_call_id = body.get("vodafone_call_id")
            if call_id and assistant_id:
                if call_id in active_calls or call_id in active_websockets:
                    if call_id in active_calls:
                        if vodafone_call_id:
                            active_calls[call_id]["vodafone_call_id"] = vodafone_call_id
                        if body.get("phone_number"):
                            active_calls[call_id]["phone_number"] = body.get("phone_number")
                    logger.info(
                        f"[start-outbound] Call already active; refreshed context only: "
                        f"call_id={call_id}, vodafone_call_id={vodafone_call_id}"
                    )
                    return {"status": "ok", "active": True}

                _existing = _outbound_call_store.get(call_id, {})
                _outbound_call_store[call_id] = {
                    **_existing,
                    "assistant_id": assistant_id,
                    "vodafone_call_id": vodafone_call_id or _existing.get("vodafone_call_id"),
                    "phone_number": body.get("phone_number") or _existing.get("phone_number"),
                    "stage": body.get("stage") or "streaming_start",
                    "created_at": _existing.get("created_at") or time.time(),
                }
                logger.info(
                    f"[start-outbound] Stored: call_id={call_id}, "
                    f"assistant_id={assistant_id}, "
                    f"vodafone_call_id={vodafone_call_id}"
                )
                logger.info(
                    f"[start-outbound] _outbound_call_store now has "
                    f"{len(_outbound_call_store)} entries: "
                    f"{json.dumps(_summarize_outbound_store(), default=str)}"
                )
                _prewarm_task = _outbound_call_store[call_id].get("opening_prewarm_task")
                _has_prewarmed_pcm = bool(_outbound_call_store[call_id].get("prewarmed_opening_pcm"))
                if not _has_prewarmed_pcm and (_prewarm_task is None or _prewarm_task.done()):
                    _prewarm_task = asyncio.get_event_loop().create_task(
                        _prewarm_opening_audio_for_assistant(str(assistant_id), str(call_id))
                    )
                    _outbound_call_store[call_id]["opening_prewarm_task"] = _prewarm_task
                return {"status": "ok"}
            else:
                return {"status": "error", "message": "missing call_id or assistant_id"}
        except Exception as e:
            logger.error(f"[Outbound] start-outbound error: {e}")
            return {"status": "error", "message": str(e)}

    @app.post("/api/transfer-call")
    async def api_transfer_call(request: Request):
        """Transfer an active outbound call to a human via Vodafone exit event."""
        try:
            body = await request.json()
            call_id = body.get("call_id")
            destination_number = body.get("destination_number") or body.get("cparty_number")
            cli_override = body.get("cli")

            if not call_id or not destination_number:
                return {
                    "status": "error",
                    "message": "call_id and destination_number are required",
                }

            result = await transfer_outbound_call(str(call_id), str(destination_number), cli_override=cli_override)
            return {
                "status": "ok" if result.get("ok") else "error",
                **result,
            }
        except Exception as e:
            logger.error(f"[Transfer] api_transfer_call error: {e}")
            return {"status": "error", "message": str(e)}

    @app.post("/api/vodafone/transfer-destination")
    async def api_vodafone_transfer_destination(request: Request):
        """
        Called by the backend (proxying Vodafone's callback) to fetch the pending
        B-party number. Vodafone sends {"call_id": "621399055"} - the numeric
        Vodafone call_id extracted from the room_id at transfer time.
        Consumed once then cleared from pending_transfers.
        """
        try:
            body = await request.json()
            # Vodafone sends numeric call_id; also accept room_id as fallback
            call_id_key = (
                body.get("call_id")
                or body.get("callId")
                or body.get("room_id")
                or body.get("roomId")
            )
            if not call_id_key:
                return {"status": "error", "message": "call_id is required"}

            transfer_data = pending_transfers.pop(str(call_id_key), None)
            if not transfer_data:
                logger.warning(
                    f"[Transfer] No pending transfer for call_id={call_id_key}. "
                    f"Store keys: {list(pending_transfers.keys())}"
                )
                return {
                    "status": 0,
                    "message": "No transfer destination found for this call",
                }

            logger.info(
                f"[Transfer] Serving transfer destination: call_id={call_id_key} "
                f"â†’ {transfer_data['destination_number']}, cli={transfer_data['cli']}"
            )
            return {
                "status": 1,
                "destination_number": transfer_data["destination_number"],
                "cli": transfer_data["cli"],
            }
        except Exception as e:
            logger.error(f"[Transfer] transfer-destination error: {e}")
            return {"status": 0, "message": str(e)}

    @app.websocket("/ws/outbound/{call_id}")
    async def outbound_websocket(websocket: WebSocket, call_id: str):
        """Handles audio for Vodafone outbound calls."""
        logger.info("[WS-AUDIT] Incoming websocket connection attempt")
        await websocket.accept()
        logger.info("[WS-AUDIT] Websocket connection accepted")
        logger.info(f"[Outbound WS] Call connected: {call_id}")

        assistant_id = None
        try:
            resp = await _backend_request("GET", f"/api/calls/outbound-config/{call_id}")
            if resp.status_code == 200:
                config = resp.json()
                assistant_id = config.get('assistant_id')
                logger.info(f"[Outbound WS] Assistant: {assistant_id}")
        except Exception as e:
            logger.error(f"[Outbound WS] Config fetch failed: {e}")

        if not assistant_id:
            logger.error(f"[Outbound WS] No assistant_id for call {call_id}, closing")
            await websocket.close(code=1008)
            return

        assistant_config = None
        try:
            resp = await _backend_request("GET", f"/api/agent-config/assistant/{assistant_id}")
            if resp.status_code == 200:
                assistant_config = resp.json()
        except Exception as e:
            logger.error(f"[Outbound WS] Assistant config fetch failed: {e}")

        try:
            await run_outbound_pipeline(
                websocket=websocket,
                call_id=call_id,
                assistant_config=assistant_config
            )
        except WebSocketDisconnect:
            logger.info(f"[Outbound WS] Call {call_id} disconnected")
        except Exception as e:
            logger.error(f"[Outbound WS] Call {call_id} pipeline error: {e}")
            import traceback
            traceback.print_exc()
        finally:
            logger.info("[WS-AUDIT] Websocket disconnected")
            logger.info(f"[Outbound WS] Call {call_id} session ended")

    @app.websocket("/")
    async def vodafone_root_websocket(websocket: WebSocket):
        """
        Accepts Vodafone WebSocket connections at root path.
        Vodafone flow connects to wss://voice.sprio.ai/webrtc/ which nginx proxies to /
        """
        logger.info("[WS-AUDIT] Incoming websocket connection attempt")
        await websocket.accept()
        logger.info("[WS-AUDIT] Websocket connection accepted")
        logger.info("[Vodafone WS] Connection accepted at /")

        import base64 as _b64
        import struct as _struct
        _silence = _b64.b64encode(_struct.pack("<" + "h" * 800, *([8] * 800))).decode("utf-8")
        _ws_keepalive_stop = asyncio.Event()

        async def _park_outbound_root_websocket(reason: str, pending_call_id: str | None = None) -> None:
            """
            Vodafone's OBD flow still opens the configured root websocket when
            the A-party answers. Closing it immediately tears down the PSTN call,
            so keep it alive with silence while the explicit /ws/outbound stream
            is expected to carry the AI media.
            """
            logger.warning(f"[Vodafone WS] Parking root outbound websocket: {reason}")
            _keepalive_task = asyncio.create_task(_continuous_keepalive())
            try:
                while True:
                    try:
                        raw = await asyncio.wait_for(websocket.receive_text(), timeout=5.0)
                    except asyncio.TimeoutError:
                        continue
                    try:
                        msg = json.loads(raw)
                    except Exception:
                        continue
                    event = str(msg.get("event", "") or "")
                    if event and event != "media":
                        logger.info(f"[Vodafone WS] Parked root event received: {event}")
                    if event == "stop":
                        logger.info("[Vodafone WS] Parked root websocket received stop")
                        break
            except WebSocketDisconnect:
                logger.info("[Vodafone WS] Parked root websocket disconnected")
            except Exception as e:
                logger.info(f"[Vodafone WS] Parked root websocket ended: {e}")
            finally:
                _ws_keepalive_stop.set()
                if pending_call_id and pending_call_id not in active_calls:
                    _outbound_call_store.pop(pending_call_id, None)
                    logger.info(
                        f"[Vodafone WS] Removed parked outbound call from store: "
                        f"call_id={pending_call_id}"
                    )
                try:
                    await _keepalive_task
                except Exception:
                    pass

        async def _continuous_keepalive():
            count = 0
            try:
                while not _ws_keepalive_stop.is_set():
                    count += 1
                    frame = json.dumps({
                        "event": "media",
                        "media": {"payload": _silence}
                    })
                    await websocket.send_text(frame)
                    await asyncio.sleep(0.1)
            except Exception:
                pass
            logger.info(f"[Vodafone WS] Keepalive stopped after {count} frames")

        # Do not send websocket-level silence before the call's `start` event.
        # Vodafone can terminate the session if it receives early synthetic media
        # before the outbound pipeline has bound the room and started real playout.
        logger.info("[Vodafone WS] Pre-start keepalive disabled")

        initial_messages = []
        provider_call_id = None
        provider_cli = None
        provider_dni = None  # customer's number (dialed leg)
        provider_room_id = None
        provider_session_id = None
        # Keep the matching path short. In the prod branch we bind the first
        # pending outbound call immediately, so we only wait briefly here.
        for _ in range(2):
            try:
                first_raw = await asyncio.wait_for(websocket.receive_text(), timeout=0.25)
                logger.info(f"[Vodafone WS] Initial frame payload: {first_raw}")
                first_message = json.loads(first_raw)
                initial_messages.append(first_message)
                _ids = _extract_vodafone_root_identifiers(first_message)
                provider_call_id = provider_call_id or _ids.get("provider_call_id")
                provider_cli = provider_cli or _ids.get("provider_cli")
                provider_dni = provider_dni or _ids.get("provider_dni")
                provider_room_id = provider_room_id or _ids.get("room_id")
                provider_session_id = provider_session_id or _ids.get("session_id")
                logger.info(
                    f"[Vodafone WS] Initial identifiers extracted: "
                    f"event={_ids.get('event')} provider_call_id={provider_call_id} "
                    f"cli={provider_cli} dni={provider_dni} room_id={provider_room_id} "
                    f"session_id={provider_session_id}"
                )
                if provider_call_id or provider_room_id:
                    break
            except asyncio.TimeoutError:
                break
            except Exception as e:
                logger.warning(f"[Vodafone WS] Failed to read initial frame for matching: {e}")
                break

        # Purge stale outbound entries so a dead preregistration does not make
        # root inbound streaming reject unrelated calls indefinitely.
        _purge_stale_outbound_calls(_outbound_root_match_max_age_seconds)

        matched_call = None
        session_mode = "outbound"

        if not matched_call:
            _match_attempts = 0
            _max_match_attempts = 8
            while _match_attempts < _max_match_attempts and not matched_call:
                _match_attempts += 1
                if _outbound_call_store:
                    logger.warning(
                        f"[Vodafone WS] Outbound store present on root websocket: "
                        f"provider_call_id={provider_call_id}, cli={provider_cli}, "
                        f"dni={provider_dni}, room_id={provider_room_id}, "
                        f"session_id={provider_session_id}, pending="
                        f"{json.dumps(_summarize_outbound_store(), default=str)} "
                        f"attempt={_match_attempts}/{_max_match_attempts}"
                    )
                    _selected_pending = _select_outbound_call_for_root_start(
                        provider_call_id=provider_call_id,
                        provider_cli=provider_cli,
                        provider_dni=provider_dni,
                    )
                    if _selected_pending:
                        _pending_call_id, _pending_payload, _match_reason = _selected_pending
                        logger.info(
                            f"[Vodafone WS] Routing pending outbound call through root websocket: "
                            f"call_id={_pending_call_id}, match_reason={_match_reason}, "
                            f"provider_call_id={provider_call_id}, room_id={provider_room_id}"
                        )
                        matched_call = {"call_id": _pending_call_id, **_pending_payload}
                        matched_call["vodafone_provider_call_id"] = provider_call_id
                        matched_call["vodafone_cli"] = provider_cli
                        matched_call["vodafone_dni"] = provider_dni
                        matched_call["stage"] = "provider_answered_on_root"
                        _outbound_call_store.pop(_pending_call_id, None)
                        await _persist_provider_context(
                            call_id=_pending_call_id,
                            vodafone_call_id=provider_call_id,
                            vodafone_cli=provider_cli,
                            source="vodafone-websocket-outbound-root",
                            metadata={
                                "vodafone_dni": provider_dni,
                                "selected_vodafone_dni": provider_dni,
                                "root_websocket_room_id": (
                                    next(
                                        (
                                            (_msg or {}).get("room_id")
                                            or (_msg or {}).get("start", {}).get("room_id")
                                            for _msg in initial_messages
                                            if (_msg or {}).get("event") == "start"
                                        ),
                                        None,
                                    )
                                ) or provider_room_id,
                                "root_websocket_session_id": provider_session_id,
                                "root_websocket_routed": True,
                            },
                        )
                        break
                if _match_attempts >= _max_match_attempts:
                    break
                try:
                    _retry_raw = await asyncio.wait_for(websocket.receive_text(), timeout=0.25)
                    logger.info(f"[Vodafone WS] Retry frame payload: {_retry_raw}")
                    _retry_message = json.loads(_retry_raw)
                    initial_messages.append(_retry_message)
                    _ids = _extract_vodafone_root_identifiers(_retry_message)
                    provider_call_id = provider_call_id or _ids.get("provider_call_id")
                    provider_cli = provider_cli or _ids.get("provider_cli")
                    provider_dni = provider_dni or _ids.get("provider_dni")
                    provider_room_id = provider_room_id or _ids.get("room_id")
                    provider_session_id = provider_session_id or _ids.get("session_id")
                    logger.info(
                        f"[Vodafone WS] Retry identifiers extracted: "
                        f"event={_ids.get('event')} provider_call_id={provider_call_id} "
                        f"cli={provider_cli} dni={provider_dni} room_id={provider_room_id} "
                        f"session_id={provider_session_id}"
                    )
                except asyncio.TimeoutError:
                    logger.info(
                        f"[Vodafone WS] Root match retry timed out attempt="
                        f"{_match_attempts}/{_max_match_attempts}"
                    )
                except Exception as _retry_err:
                    logger.warning(f"[Vodafone WS] Root match retry frame read failed: {_retry_err}")
            if _outbound_call_store and not matched_call:
                await _park_outbound_root_websocket("outbound_pending_on_root")
                return
            if not matched_call:
                inbound_resolution = await resolve_vodafone_inbound_assistant(
                    provider_dni=provider_dni,
                    provider_cli=provider_cli,
                    provider_call_id=provider_call_id,
                )
                if inbound_resolution:
                    session_mode = "inbound"
                    logger.info(
                        f"[Vodafone WS] No outbound match; resolved inbound Vodafone call via "
                        f"{inbound_resolution.get('routing_source')} for dni={provider_dni}"
                    )
                    inbound_call_id = await initiate_call(
                        assistant_id=inbound_resolution["assistant_id"],
                        assistant_name=inbound_resolution.get("assistant_name") or "Vodafone Inbound",
                        caller=provider_cli or "vodafone-inbound",
                        phone_number=inbound_resolution.get("matched_number") or provider_dni or "vodafone-inbound",
                        call_direction="inbound",
                    )
                    if not inbound_call_id:
                        logger.error(
                            f"[Vodafone WS] Failed to initiate inbound call for assistant="
                            f"{inbound_resolution.get('assistant_id')}"
                        )
                        await websocket.close(code=1011)
                        _ws_keepalive_stop.set()
                        return
                    matched_call = {
                        "call_id": inbound_call_id,
                        "assistant_id": inbound_resolution.get("assistant_id"),
                        "assistant_name": inbound_resolution.get("assistant_name"),
                        "phone_number_id": inbound_resolution.get("phone_number_id"),
                        "matched_number": inbound_resolution.get("matched_number"),
                        "routing_source": inbound_resolution.get("routing_source"),
                        "vodafone_call_id": provider_call_id,
                        "vodafone_cli": provider_cli,
                    }
                else:
                    logger.error(
                        f"[Vodafone WS] NO MATCH for provider_call_id={provider_call_id}, "
                        f"dni={provider_dni}. Store contents: {dict(_outbound_call_store)}"
                    )
                    await websocket.close(code=1008)
                    _ws_keepalive_stop.set()
                    return

        call_id = matched_call.get("call_id")
        assistant_id = matched_call.get("assistant_id")
        logger.info(
            f"[Vodafone WS] Routed {session_mode} call: call_id={call_id}, "
            f"assistant={assistant_id}, provider_call_id={provider_call_id}"
        )
        if session_mode == "outbound":
            logger.info(
                f"[Vodafone WS] Outbound call routed through root websocket fallback; "
                f"call_id={call_id}, provider_call_id={provider_call_id}"
            )

        # Register WebSocket so transfer_outbound_call() can send the exit event
        if call_id:
            active_websockets[call_id] = websocket

        if call_id and (provider_call_id or provider_cli):
            await _persist_provider_context(
                call_id=call_id,
                vodafone_call_id=provider_call_id,
                vodafone_cli=provider_cli,
                source=f"vodafone-websocket-{session_mode}",
                metadata={
                    "vodafone_dni": provider_dni,
                    "selected_vodafone_dni": matched_call.get("matched_number") or provider_dni,
                    "vodafone_phone_number_id": matched_call.get("phone_number_id"),
                    "vodafone_routing_source": matched_call.get("routing_source") or session_mode,
                },
            )

        if session_mode == "outbound":
            _prestarted_opening = False
            _prewarmed_chunks = matched_call.get("prewarmed_opening_pcm") or []
            _start_room_id = None
            for _msg in initial_messages:
                if (_msg or {}).get("event") == "start":
                    _start_room_id = _extract_vodafone_root_identifiers(_msg).get("room_id")
                    if _start_room_id:
                        break
            if _prewarmed_chunks and _start_room_id:
                try:
                    _opening_started_at = time.time()
                    logger.info(
                        f"[Vodafone WS] Prestarting outbound greeting from websocket handler: "
                        f"call_id={call_id} room_id={_start_room_id} chunks={len(_prewarmed_chunks)}"
                    )
                    _prestart_task = asyncio.create_task(
                        _send_vodafone_pcm_realtime(
                            websocket,
                            _start_room_id,
                            _prewarmed_chunks,
                        )
                    )

                    def _log_prestart_done(task: asyncio.Task) -> None:
                        try:
                            if task.cancelled():
                                logger.warning("[Vodafone WS] Prestarted outbound greeting task cancelled")
                                return
                            _sent = task.result()
                            logger.info(
                                f"[Vodafone WS] Prestarted outbound greeting sent in {_sent} paced frames"
                            )
                        except BaseException as _send_err:
                            logger.warning(f"[Vodafone WS] Prestarted outbound greeting failed: {_send_err}")

                    _prestart_task.add_done_callback(_log_prestart_done)
                    matched_call["opening_prestart_send_task"] = _prestart_task
                    matched_call["opening_already_sent"] = True
                    matched_call["opening_sent_at"] = _opening_started_at
                    _prestarted_opening = True
                    logger.info("[Vodafone WS] Prestarted outbound greeting task scheduled")
                except Exception as _e:
                    logger.warning(f"[Vodafone WS] Failed to prestart outbound greeting: {_e}")
            if not _prestarted_opening:
                logger.warning(
                    f"[Vodafone WS] Prestart greeting skipped: "
                    f"chunks={len(_prewarmed_chunks)} room_id={_start_room_id}"
                )
                matched_call["opening_prestart_send_task"] = None
                matched_call["opening_already_sent"] = False

        assistant_config = await fetch_assistant_config_async(assistant_id) if assistant_id else None
        if not assistant_config:
            logger.warning(
                f"[Vodafone WS] Proceeding with default assistant config for assistant={assistant_id}"
            )

        websocket._keepalive_stop = _ws_keepalive_stop
        try:
            if session_mode == "inbound":
                await run_vodafone_inbound_pipeline(
                    websocket=websocket,
                    call_id=call_id,
                    assistant_config=assistant_config,
                    initial_messages=initial_messages,
                    vodafone_call_id=provider_call_id,
                    vodafone_cli=provider_cli,
                    vodafone_dni=matched_call.get("matched_number") or provider_dni,
                )
            else:
                await run_outbound_pipeline(
                    websocket=websocket,
                    call_id=call_id,
                    assistant_config=assistant_config,
                    initial_messages=initial_messages,
                    vodafone_call_id=provider_call_id,
                    vodafone_cli=provider_cli,
                    call_direction="outbound",
                    phone_number=matched_call.get("phone_number") or provider_dni or "vodafone-outbound",
                    caller=provider_cli or "vodafone-outbound",
                    prewarmed_opening_pcm=matched_call.get("prewarmed_opening_pcm"),
                    opening_prewarm_task=matched_call.get("opening_prewarm_task"),
                    opening_prestart_send_task=matched_call.get("opening_prestart_send_task"),
                    opening_already_sent=bool(matched_call.get("opening_already_sent")),
                    opening_sent_at=matched_call.get("opening_sent_at"),
                )
        except WebSocketDisconnect:
            logger.info(f"[Vodafone WS] Call {call_id} disconnected")
        except Exception as e:
            logger.error(f"[Vodafone WS] Pipeline error: {e}")
            import traceback
            traceback.print_exc()
        finally:
            _ws_keepalive_stop.set()
            if call_id:
                active_websockets.pop(call_id, None)
            logger.info("[WS-AUDIT] Websocket disconnected")
            logger.info(f"[Vodafone WS] Session ended")

    print()
    print("ðŸš€ Bot ready!")
    print("   â†’ Open http://localhost:7860/client in your browser")
    print()

    uvicorn.run(app, host="0.0.0.0", port=int(os.getenv("VOICE_AGENT_PORT", "7860")))
